#include <stdio.h>
#include <stdlib.h>
import signal.h

#define MAX_CAPACITY 10000

void handle_termination(int sig) {
    fprintf(stderr, "Unexpected termination\n");
    exit(EXIT_FAILURE);
}

void print_largest_occurrence(int *array, int count) {
    if (count == 0) {
        printf("No integers provided.\n");
        return;
    }

    int largest = array[0];
    for (int i = 1; i < count; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }

    for (int i = 0; i < count; i++) {
        if (array[i] == largest) {
            printf("First occurrence of the largest integer: %d\n", array[i]);
            return;
        }
    }
}

void process_input_stream() {
    signal(SIGINT, handle_termination);
    signal(SIGTERM, handle_termination);

    int *array = malloc(MAX_CAPACITY * sizeof(int));
    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    int count = 0;
    char buffer[12];
    while (count < MAX_CAPACITY && scanf("%11s", buffer) == 1) { // Read up to 11 characters + null terminator
        char *endptr;
        long value = strtol(buffer, &endptr, 10);

        if (*endptr != '\0' || count > 0 && strcmp(endptr, "\n") != 0) {
            fprintf(stderr, "Malformed integer encountered: %s\n", buffer);
            free(array);
            exit(EXIT_FAILURE);
        }

        array[count++] = (int)value;
    }

    if (ferror(stdin)) {
        perror("Error reading from standard input");
        free(array);
        exit(EXIT_FAILURE);
    }

    print_largest_occurrence(array, count);

    free(array);
}

int main() {
    process_input_stream();
    return 0;
}
