['```c
#include <stdio.h>
#include <stdarg.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_LOG_TARGETS 10
#define LOG_BUFFER_SIZE 1024

typedef enum {
    LOG_LEVEL_DEBUG,
    LOG_LEVEL_INFO,
    LOG_LEVEL_WARNING,
    LOG_LEVEL_ERROR
} LogLevel;

typedef struct {
    void *target; // File descriptor, console handle, or network socket
    int type;     // FILE, CONSOLE, NETWORK
} LogTarget;

typedef struct {
    LogTarget targets[MAX_LOG_TARGETS];
    int count;
    LogLevel level;
    pthread_mutex_t lock;
} LogManager;

LogManager log_manager = { .count = 0, .level = LOG_LEVEL_DEBUG, .lock = PTHREAD_MUTEX_INITIALIZER };

void configure_log_level(LogLevel level) {
    pthread_mutex_lock(&log_manager.lock);
    log_manager.level = level;
    pthread_mutex_unlock(&log_manager.lock);
}

int add_log_target(void *target, int type) {
    pthread_mutex_lock(&log_manager.lock);

    if (log_manager.count >= MAX_LOG_TARGETS) {
        pthread_mutex_unlock(&log_manager.lock);
        return -1; // Max targets reached
    }

    log_manager.targets[log_manager.count].target = target;
    log_manager.targets[log_manager.count].type = type;
    int index = log_manager.count++;

    pthread_mutex_unlock(&log_manager.lock);
    return index;
}

void remove_log_target(int index) {
    if (index < 0 || index >= log_manager.count) return;

    pthread_mutex_lock(&log_manager.lock);

    for (int i = index; i < log_manager.count - 1; ++i) {
        log_manager.targets[i] = log_manager.targets[i + 1];
    }
    log_manager.count--;

    pthread_mutex_unlock(&log_manager.lock);
}

void log_message(LogLevel level, const char *format, ...) {
    if (level > log_manager.level) return;

    char buffer[LOG_BUFFER_SIZE];
    va_list args;
    va_start(args, format);
    vsnprintf(buffer, sizeof(buffer), format, args);
    va_end(args);

    pthread_mutex_lock(&log_manager.lock);

    for (int i = 0; i < log_manager.count; ++i) {
        LogTarget *target = &log_manager.targets[i];

        switch (target->type) {
            case FILE:
                if (fprintf((FILE *)target->target, "%s\n", buffer) < 0) {
                    fprintf(stderr, "Failed to write to file: %s\n", strerror(errno));
                }
                break;
            case CONSOLE:
                printf("%s\n", buffer);
                break;
            case NETWORK:
                // Simulated network send operation
                if (write((int)(intptr_t)target->target, buffer, strlen(buffer)) < 0) {
                    fprintf(stderr, "Failed to write to network: %s\n", strerror(errno));
                }
                break;
        }
    }

    pthread_mutex_unlock(&log_manager.lock);
}

// Example usage
