typedef struct {
    char *log_file;
    int verbosity;
} Config;

// Function prototypes
void parse_config(const char *config_path, Config *config);
int initialize_cipher(const char *algorithm, const unsigned char *key, const unsigned char *iv, EVP_CIPHER_CTX **ctx);
void perform_encryption(EVP_CIPHER_CTX *ctx, FILE *input_file, FILE *output_file);
void cleanup(EVP_CIPHER_CTX *ctx);

// Global variables for caching and logging
pthread_mutex_t cache_mutex = PTHREAD_MUTEX_INITIALIZER;
Config global_config;

void log_message(const char *message) {
    if (global_config.log_file && global_config.verbosity > 0) {
        pthread_mutex_lock(&cache_mutex);
        FILE *log_fp = fopen(global_config.log_file, "a");
        if (log_fp) {
            fprintf(log_fp, "%s\n", message);
            fclose(log_fp);
        }
        pthread_mutex_unlock(&cache_mutex);
    }
}

void parse_config(const char *config_path, Config *config) {
    // Dummy implementation for parsing configuration
    config->log_file = "app.log";
    config->verbosity = 1;
}

int initialize_cipher(const char *algorithm, const unsigned char *key, const unsigned char *iv, EVP_CIPHER_CTX **ctx) {
    if (!(ctx = malloc(sizeof(EVP_CIPHER_CTX)))) {
        log_message("Error allocating memory for cipher context");
        return 0;
    }

    if (1 != EVP_EncryptInit_ex(*ctx, EVP_get_cipherbyname(algorithm), NULL, key, iv)) {
        log_message("EVP_EncryptInit_ex failed");
        free(ctx);
        return 0;
    }

    return 1;
}

void perform_encryption(EVP_CIPHER_CTX *ctx, FILE *input_file, FILE *output_file) {
    unsigned char inbuf[1024], outbuf[1024 + EVP_MAX_BLOCK_LENGTH];
    int inlen, outlen;

    while ((inlen = fread(inbuf, 1, sizeof(inbuf), input_file)) > 0) {
        if (1 != EVP_EncryptUpdate(ctx, outbuf, &outlen, inbuf, inlen)) {
            log_message("EVP_EncryptUpdate failed");
            return;
        }
        fwrite(outbuf, 1, outlen, output_file);
    }

    if (inlen < 0) {
        log_message("Error reading input file");
        return;
    }

    if (1 != EVP_EncryptFinal_ex(ctx, outbuf, &outlen)) {
        log_message("EVP_EncryptFinal_ex failed");
        return;
    }
    fwrite(outbuf, 1, outlen, output_file);
}

void cleanup(EVP_CIPHER_CTX *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx);
    }
}

void encrypt_with_config(const char *config_path) {
    Config config;
    parse_config(config_path, &config);

    global_config = config;

    const unsigned char key[] = "0123456789abcdef"; // Example key
    const unsigned char iv[]  = "1234567890abcdef";  // Example IV

    EVP_CIPHER_CTX *ctx = NULL;
    if (!initialize_cipher("aes-256-cbc", key, iv, &ctx)) {
        log_message("Failed to initialize cipher");
        return;
    }

    FILE *input_file = fopen("input.txt", "rb");
    FILE *output_file = fopen("output.enc", "wb");

    if (!input_file || !output_file) {
        log_message("Error opening files");
        cleanup(ctx);
        return;
    }

    perform_encryption(ctx, input_file, output_file);

    fclose(input_file);
    fclose(output_file);
    cleanup(ctx);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <config_path>\n", argv[0]);
        return EXIT_FAILURE;
    }

    encrypt_with_config(argv[1]);

    return EXIT_SUCCESS;
}
```

### Key Points:
- **Configuration Parsing**: A placeholder function `parse_config` is provided. It should be extended to read actual configurations from a file.
- **Cipher Initialization**: Uses OpenSSL's `EVP_EncryptInit_ex`.
- **Logging**: Logs messages based on verbosity and logs to a specified file.
- **Error Handling**: Provides meaningful error messages via logging.
- **Resource Management**: Properly allocates and deallocates memory for cipher contexts.

This code is modularized, allowing easy extension and integration into larger systems. Adjustments may be needed for specific requirements or configurations.']

['Below is a C code implementation addressing your requirements for managing a collection of semaphores:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <errno.h>

#define MAX_SEMAPHORE_VALUE 1000 // Define system limit for semaphore values

typedef struct {
    sem_t *sems;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} SemaphoreManager;

SemaphoreManager* create_semaphore_manager(size_t initial_capacity) {
    if (initial_capacity == 0) return NULL;

    SemaphoreManager *manager = malloc(sizeof(SemaphoreManager));
    if (!manager) {
        perror("Failed to allocate memory for semaphore manager");
        return NULL;
    }

    pthread_mutex_init(&manager->mutex, NULL);
    manager->sems = calloc(initial_capacity, sizeof(sem_t*));
    if (!manager->sems) {
        perror("Failed to allocate memory for semaphores array");
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;

    return manager;
}

void destroy_semaphore_manager(SemaphoreManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->count; ++i) {
        sem_destroy(manager->sems[i]);
        free(manager->sems[i]);
    }

    free(manager->sems);
    pthread_mutex_unlock(&manager->mutex);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

sem_t* create_semaphore(SemaphoreManager *manager, int initial_value) {
    if (!manager || initial_value < 0 || initial_value > MAX_SEMAPHORE_VALUE) {
        fprintf(stderr, "Invalid semaphore value\n");
        return NULL;
    }

    pthread_mutex_lock(&manager->mutex);

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        sem_t **new_sems = realloc(manager->sems, new_capacity * sizeof(sem_t*));
        if (!new_sems) {
            perror("Failed to reallocate memory for semaphore array");
            pthread_mutex_unlock(&manager->mutex);
            return NULL;
        }
        manager->sems = new_sems;
        manager->capacity = new_capacity;
    }

    sem_t *sem = malloc(sizeof(sem_t));
    if (!sem) {
        perror("Failed to allocate memory for semaphore");
        pthread_mutex_unlock(&manager->mutex);
        return NULL;
    }

    if (sem_init(sem, 0, initial_value)) {
        perror("Semaphore initialization failed");
        free(sem);
        pthread_mutex_unlock(&manager->mutex);
        return NULL;
    }

    manager->sems[manager->count++] = sem;

    pthread_mutex_unlock(&manager->mutex);

    printf("Semaphore created with initial value %d\n", initial_value);

    return sem;
}

void delete_semaphore(SemaphoreManager *manager, sem_t *sem) {
    if (!manager || !sem) return;

    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sems[i] == sem) {
            sem_destroy(sem);
            free(sem);
            memmove(&manager->sems[i], &manager->sems[i + 1],
                    (manager->count - i - 1) * sizeof(sem_t*));
            manager->count--;
            printf("Semaphore deleted\n");
            pthread_mutex_unlock(&manager->mutex);
            return;
        }
    }

    pthread_mutex_unlock(&manager->mutex);
}

// Function to log semaphore operations
void log_operation(const char *operation, int result, const char *details) {
    fprintf(stderr, "Operation: %s, Result: %d, Details: %s\n", operation, result, details);
}
```

### Key Features:

1. **Dynamic Memory Allocation**: The semaphores are stored in a dynamically sized array to minimize fragmentation and handle growing demands.
2. **Thread Safety**: Mutex locks protect critical sections where the semaphore list is modified, preventing race conditions.
3. **Atomic Updates**: Use of mutex ensures atomic updates to the count of allocated semaphores.
4. **Error Handling**: Comprehensive checks are in place for memory allocation failures, initialization errors, and invalid inputs with graceful error reporting.
5. **Validation and Fallbacks**: Semaphore initial values are checked against a defined system limit.
6. **Logging Mechanism**: A simple logging function is provided to record operations and their outcomes for debugging purposes.
7. **Performance Considerations**: Doubling the array capacity reduces reallocation frequency, optimizing performance at potential trade-offs in memory usage.

This implementation considers modularity, making it easy to integrate into larger systems while being mindful of system limits and load variations.']

