        return new List<object>(); // or your preferred default value

    try
    {
        var xmlDoc = XDocument.Parse(xmlContent);
        var elements = xmlDoc.XPathSelectElements(xpath);

        if (elements == null || !elements.Any())
            return new List<object>(); // or your preferred default value

