use std::env;
use std::fs;
use std::path::PathBuf;
use log::warn;

pub fn create_directory_with_env_var(env_var: &str, dir_name: &str) -> Result<(), String> {
    let env_value = env::var(env_var).ok();

    match env_value {
        Some(path_str) => {
            let path = PathBuf::from(path_str);
            if path.exists() && path.is_dir() {
                warn!("Environment variable {} is already set to: {}", env_var, path.display());
                Ok(())
            } else {
                Err(format!("Existing environment variable {} points to a non-directory or does not exist.", env_var))
            }
        },
        None => {
            let new_path = PathBuf::from(dir_name);
            if !new_path.exists() {
                fs::create_dir_all(&new_path).map_err(|e| e.to_string())?;
            }

            env::set_var(env_var, new_path.display().to_string());
            Ok(())
        }
    }
}
```

