['```java
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.List;
import java.util.concurrent.*;
import java.util.HashMap;

public class MD5BatchProcessor {

    public ConcurrentHashMap<String, String> processStrings(List<String> strings, int maxThreads) {
        // Initialize the map to store results.
        final ConcurrentHashMap<String, String> resultMap = new ConcurrentHashMap<>();

        // Create a thread pool executor with a configurable number of threads
        ExecutorService executor = Executors.newFixedThreadPool(maxThreads);

        try {
            // Use a CountDownLatch to track task completion
            CountDownLatch latch = new CountDownLatch(strings.size());

            for (String input : strings) {
                executor.submit(() -> {
                    try {
                        // Simulate external data source with variable response time using sleep (for demo purposes)
                        simulateVariableResponseTime();

                        // Generate MD5 hash
                        String md5Hash = generateMD5(input);

                        // Put the result in map if key is not already present
                        resultMap.putIfAbsent(input, md5Hash);
                    } catch (Exception e) {
                        System.err.println("Error processing string: " + input + ", Error: " + e.getMessage());
                    } finally {
                        latch.countDown();
                    }
                });
            }

            // Wait for all tasks to complete
            latch.await();

        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();  // Restore interrupted status
            System.err.println("Processing was interrupted.");
        } finally {
            executor.shutdown();
            try {
                if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                    executor.shutdownNow();
                }
            } catch (InterruptedException e) {
                executor.shutdownNow();
                Thread.currentThread().interrupt(); // Restore interrupted status
            }
        }

        return resultMap;
    }

    private String generateMD5(String input) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] hashBytes = md.digest(input.getBytes());
        StringBuilder hexString = new StringBuilder();
        for (byte b : hashBytes) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

    private void simulateVariableResponseTime() throws InterruptedException {
        // Simulate external data source latency
        long delay = (long) (Math.random() * 500); // Random delay up to 500ms
        Thread.sleep(delay);
    }
}
```

### Explanation:
- **ExecutorService:** A fixed thread pool is created using `Executors.newFixedThreadPool(maxThreads)` to manage concurrent tasks, where `maxThreads` can be configured based on system load.
- **ConcurrentHashMap:** Utilized for storing the results with original strings as keys and their MD5 hashes as values. The `putIfAbsent()` method ensures no duplicate keys are inserted.
- **CountDownLatch:** Used to wait until all tasks are completed before proceeding, which allows efficient handling of task completion without polling or busy waiting.
- **Error Handling:** Catches exceptions during hashing and logs an error message but continues processing other strings.
- **Simulated Delay:** `simulateVariableResponseTime()` method mimics the variable response time of an external data source.']

