public class ThemeManager {

    private static final String DEFAULT_THEME_DIR = "/default/theme";
    private static final Lock lock = new ReentrantLock();

    public MoSTState loadMoSTStateFromFile(String filePath) {
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filePath))) {
            Object obj = ois.readObject();
            return obj instanceof MoSTState ? (MoSTState) obj : null;
        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace();
            return null;
        }
    }

    public void ensureDefaultThemeDir() {
        lock.lock();
        try {
            Path themePath = Paths.get(DEFAULT_THEME_DIR);
            if (!Files.exists(themePath)) {
                Files.createDirectories(themePath);
            }
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            lock.unlock();
        }
    }

    public void updateThemeCache(String cacheRootDir) {
        lock.lock();
        try {
            Path root = Paths.get(cacheRootDir);
            if (!Files.exists(root)) return;

            Files.walkFileTree(root, new SimpleFileVisitor<Path>() {
                @Override
                public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) throws IOException {
                    if (file.toString().endsWith(".png")) {
                        try {
                            updateThemeBitmap(file);
                        } catch (IOException e) {
                            fallbackMechanism(file);
