```csharp
using System;
using System.Collections.Generic;
using System.Net.Mail;
using System.Security.Cryptography;
using System.Text;
using Microsoft.EntityFrameworkCore;

namespace UserManagementSystem
{
    // Models
    public class User
    {
        public int Id { get; set; }
        public string Username { get; set; }
        public byte[] PasswordHash { get; set; }
        public byte[] PasswordSalt { get; set; }
        public bool IsLockedOut { get; set; }
        public DateTime? LockoutEnd { get; set; }
    }

    public class UserSettings
    {
        public int MinPasswordLength { get; set; } = 8;
        public int MaxLoginAttempts { get; set; } = 5;
        public TimeSpan LockoutDuration { get; set; } = TimeSpan.FromMinutes(15);
    }

    // Database Context
    public class UserDbContext : DbContext
    {
        public DbSet<User> Users { get; set; }

        protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
        {
            optionsBuilder.UseSqlServer("YourConnectionString");
        }
    }

    // Services
    public interface IUserService
    {
        User Register(string username, string password);
        bool Login(string username, string password);
        void SendNotificationEmail(User user, string subject, string body);
        void LockUserAccount(User user);
        void UnlockUserAccount(User user);
    }

    public class UserService : IUserService
    {
        private readonly UserDbContext _context;
        private readonly SmtpClient _smtpClient;
        private readonly MfaService _mfaService;

        public UserService(UserDbContext context, string smtpHost, int smtpPort, string smtpUsername, string smtpPassword)
        {
            _context = context;
            _smtpClient = new SmtpClient(smtpHost, smtpPort) { Credentials = new System.Net.NetworkCredential(smtpUsername, smtpPassword), EnableSsl = true };
            _mfaService = new MfaService();
        }

        public User Register(string username, string password)
        {
            if (string.IsNullOrWhiteSpace(username) || password.Length < 8)
                throw new ArgumentException("Invalid username or password.");

            var user = new User { Username = username };

            CreatePasswordHash(password, out byte[] passwordHash, out byte[] passwordSalt);
            user.PasswordHash = passwordHash;
            user.PasswordSalt = passwordSalt;

            _context.Users.Add(user);
            _context.SaveChanges();

            return user;
        }

        public bool Login(string username, string password)
        {
            var user = _context.Users.SingleOrDefault(u => u.Username == username);

            if (user == null || !VerifyPasswordHash(password, user.PasswordHash, user.PasswordSalt))
                throw new UnauthorizedAccessException("Invalid credentials.");

            if (user.IsLockedOut && DateTime.UtcNow < user.LockoutEnd)
                throw new UnauthorizedAccessException("Account is locked out.");

            _mfaService.GenerateToken(user);

            return true;
        }

        public void SendNotificationEmail(User user, string subject, string body)
        {
            var mailMessage = new MailMessage("no-reply@yourdomain.com", user.Username) { Subject = subject, Body = body };
            try
            {
                _smtpClient.Send(mailMessage);
            }
            catch (Exception ex)
            {
                // Log and handle email sending error
                Console.WriteLine($"Email notification failed: {ex.Message}");
            }
        }

        public void LockUserAccount(User user)
        {
            user.IsLockedOut = true;
            user.LockoutEnd = DateTime.UtcNow.AddSeconds(15);
            _context.SaveChanges();
        }

        public void UnlockUserAccount(User user)
        {
            user.IsLockedOut = false;
            user.LockoutEnd = null;
            _context.SaveChanges();
        }

        private static void CreatePasswordHash(string password, out byte[] passwordHash, out byte[] passwordSalt)
        {
            using (var hmac = new HMACSHA512())
            {
                passwordSalt = hmac.Key;
                passwordHash = hmac.ComputeHash(Encoding.UTF8.GetBytes(password));
            }
        }

        private static bool VerifyPasswordHash(string password, byte[] storedHash, byte[] storedSalt)
        {
            using (var hmac = new HMACSHA512(storedSalt))
            {
                var computedHash = hmac.ComputeHash(Encoding.UTF8.GetBytes(password));
                return ComputeSha256Hash(computedHash) == ComputeSha256Hash(storedHash);
            }
        }

        private static string ComputeSha256Hash(byte[] data)
        {
            using (var sha256 = SHA256.Create())
            {
                return Convert.ToBase64String(sha256.ComputeHash(data));
            }
        }
    }

    // External MFA Service
    public class MfaService
    {
        public void GenerateToken(User user)
        {
            // Integrate with external MFA API to generate token
            Console.WriteLine($"MFA Token generated for {user.Username}");
        }
    }

    // Error Handling Example
    public static class ErrorHandler
    {
        public static void HandleError(Exception ex, string context)
        {
            Console.WriteLine($"Error in {context}: {ex.Message}");
            // Log and take necessary actions based on error type
        }
    }

    // Main Program
    class Program
    {
        static void Main(string[] args)
        {
            var dbContext = new UserDbContext();
            var userService = new UserService(dbContext, "smtp.example.com", 587, "username", "password");

            try
            {
                var user = userService.Register("testuser", "SecurePassword123");
                Console.WriteLine($"User {user.Username} registered successfully.");

                if (userService.Login(user.Username, "SecurePassword123"))
                    Console.WriteLine("Login successful.");
            }
            catch (Exception ex)
            {
                ErrorHandler.HandleError(ex, "Main Program");
            }
        }
    }
}
```

This code provides a basic structure for managing user accounts and authentication with integration points for external services like SMTP and MFA. It includes customizable username and password policies, lockout settings, and error handling. The application is designed to be extensible and maintainable, allowing future enhancements such as social login or additional authentication factors.']

