const fs = require('fs').promises;
const path = require('path');
const util = require('util');
const os = require('os');

// Convert `fs.readdir` and `fs.readFile` to their Promise-based versions
const readdir = util.promisify(fs.readdir);
const readFile = util.promisify(fs.readFile);

// Simple in-memory cache
const cache = new Map();

async function readFilesInDirectory(directory, extension) {
  const cacheKey = `${directory}-${extension}`;

  // Check if the result is already cached
  if (cache.has(cacheKey)) {
    console.log('Returning cached results');
    return cache.get(cacheKey);
  }

  try {
    // Read directory contents
    const files = await readdir(directory);

    // Filter files based on extension
    const filteredFiles = files.filter(file => path.extname(file) === `.${extension}`);

    let concatenatedContent = '';

    // Use a Promise.all to handle concurrent file reads
    const readPromises = filteredFiles.map(async (file) => {
      try {
        const filePath = path.join(directory, file);

        // Read file content and retrieve metadata using an external service simulation
        const [content, metadata] = await Promise.all([
          readFile(filePath, 'utf8'),
          fetchFileMetadataSimulated(filePath)  // Simulating latency
        ]);

        console.log(`Read ${filePath} with metadata:`, metadata);

        return content;
      } catch (error) {
        console.error(`Error reading file ${file}:`, error);
        return '';
      }
    });

    // Await all read operations and concatenate results
    const contents = await Promise.all(readPromises);
    concatenatedContent = contents.join('\n');

    // Cache the result with an eviction strategy for memory management
    cache.set(cacheKey, concatenatedContent);

    // Optionally implement cache eviction based on size or time-to-live (TTL)
    manageCacheSize();

    return concatenatedContent;
  } catch (error) {
    console.error(`Error reading directory ${directory}:`, error);
    throw new Error('Failed to read files in the specified directory.');
  }
}

// Simulate fetching file metadata with some latency
async function fetchFileMetadataSimulated(filePath) {
  // Introduce artificial delay to simulate external service call
  await new Promise(resolve => setTimeout(resolve, 100));

  return {
    size: fs.statSync(filePath).size,
    lastModified: fs.statSync(filePath).mtime,
  };
}

// Manage cache size to prevent excessive memory usage
function manageCacheSize() {
  const maxCacheEntries = 10; // Example limit

  if (cache.size > maxCacheEntries) {
    // Simple eviction strategy: remove the oldest entry
    const firstKey = cache.keys().next().value;
    cache.delete(firstKey);
    console.log(`Evicted cache entry for key: ${firstKey}`);
  }
}

// Usage example:
// (async () => {
//   try {
//     const result = await readFilesInDirectory('/path/to/directory', 'txt');
//     console.log('Concatenated Content:', result);
//   } catch (error) {
//     console.error(error.message);
//   }
// })();
```

### Key Points:
- **Concurrency**: Uses `Promise.all` to concurrently read files, optimizing for performance.
- **Error Handling**: Gracefully logs errors encountered during file reads without stopping the entire process.
- **Caching**: Implements a simple in-memory cache with eviction logic to manage memory usage.
- **Metadata Fetching**: Simulates latency introduced by external metadata service calls.
- **Scalability and Efficiency**: Designed for handling large numbers of files and efficient resource management."]

["```javascript
const { Worker, isMainThread, parentPort } = require('worker_threads');
const cluster = require('cluster');
const numCPUs = require('os').cpus().length;
const path = require('path');

// Mocking library setup (assuming a simple API)
class Blueslip {
  static initialize() {}
  static reset() {}
}

async function runTest(modulePath, testCallback, maxConcurrency) {
  const module = require(modulePath);
  const tests = testCallback(module);

  let activeWorkers = 0;
  let totalTests = tests.length;
  let successCount = 0;
  let failCount = 0;

  async function executeNext() {
    if (activeWorkers < maxConcurrency && tests.length > 0) {
      const currentTest = tests.shift();

      console.log(`Starting test: ${currentTest.name}`);

      Blueslip.initialize();
      try {
        await runTestInWorker(currentTest);
        successCount++;
        console.log(`Completed test: ${currentTest.name} (Success)`);
      } catch (error) {
        failCount++;
        console.error(`Failed test: ${currentTest.name}`, error);
      }

      Blueslip.reset();
      executeNext();
    }
  }

  async function runTestInWorker(testData) {
    return new Promise((resolve, reject) => {
      const workerPath = path.resolve(__filename, 'test-worker.js');
      const worker = new Worker(workerPath, { workerData: { ...testData } });

      worker.on('message', resolve);
      worker.on('error', reject);
      worker.on('exit', (code) => {
        if (code !== 0) {
          reject(new Error(`Worker stopped with exit code ${code}`));
        }
      });

      activeWorkers++;
    });
  }

  const testPromises = tests.map(() => executeNext());
  await Promise.all(testPromises);

  console.log('Summary Report:');
  console.log(`Total Tests: ${totalTests}, Successes: ${successCount}, Failures: ${failCount}`);
}

if (isMainThread) {
  runTest('./your-module.js', module => [
    { name: 'test1', fn: async () => {/* test logic */} },
    { name: 'test2', fn: async () => {/* test logic */} }
  ], 4).catch(console.error);
} else {
  const { workerData } = require('worker_threads');

  async function executeTest(testData) {
    try {
      await testData.fn();
      parentPort.postMessage({ status: 'success' });
    } catch (error) {
      parentPort.postMessage({ status: 'fail', error: error.message });
    }
  }

  executeTest(workerData);
}
```

### Key Points:

- **Concurrency Management**: Uses `worker_threads` to run tests in parallel, respecting the `maxConcurrency` limit.
- **Blueslip Mocking Library**: Initializes and resets before and after each test for environment isolation.
- **Logging**: Outputs detailed logs for start, completion, success, and failure of each test.
- **Error Handling**: Catches errors during test execution and reports them clearly.
- **Summary Report**: Provides a summary of total tests executed with counts of successes and failures.
- **Worker Threads**: Offloads individual test executions to worker threads to manage parallelism efficiently.

This setup should be integrated within your existing testing framework and can be extended for more complex reporting and error handling as needed."]

['Here is a JavaScript solution using Node.js streams and some basic error handling, regular expressions, and data processing techniques:

```javascript
const fs = require('fs');
const https = require('https');

// List of significant battles to look for
const wellDocumentedBattles = new Set([
  'Battle of Marathon',
  'Battle of Thermopylae',
  'Battle of Gaugamela',
  // Add more as needed...
]);

// Regular expression patterns to identify potential battle mentions
const battlePatterns = [
  /\b(?:Battle|Conflict) of (\w+)/g,
  /\b\w+\'s Battle\b/g,
  // Additional regex patterns can be added here for flexibility
];

// Function to fetch and process documents from external repositories
async function fetchAndProcessDocuments(urls) {
  const results = [];

  for (const url of urls) {
    try {
      const document = await fetchDocument(url);
      const battlesCount = extractBattles(document);

      if (Object.keys(battlesCount).length > 0) {
        results.push({ url, battles: battlesCount });
      }
    } catch (error) {
      console.error(`Failed to process ${url}:`, error.message);
    }
  }

  return results;
}

// Fetch a document from a given URL
function fetchDocument(url) {
  return new Promise((resolve, reject) => {
    https.get(url, (res) => {
      if (res.statusCode !== 200) {
        reject(new Error(`Failed to load ${url}, status code: ${res.statusCode}`));
      }

      const chunks = [];
      res.on('data', (chunk) => chunks.push(chunk));
      res.on('end', () => resolve(Buffer.concat(chunks).toString()));

    }).on('error', (err) => reject(err));
  });
}

// Extract and count significant battles from the document text
function extractBattles(documentText) {
  const battlesCount = {};

  for (const pattern of battlePatterns) {
    let match;

    while ((match = pattern.exec(documentText)) !== null) {
      const battleName = match[1] || match[0].split("'s")[0]; // Handle both capturing groups
      if (wellDocumentedBattles.has(battleName)) {
        battlesCount[battleName] = (battlesCount[battleName] || 0) + 1;
      }
    }
  }

  return battlesCount;
}

// Example usage with URLs of documents
const documentUrls = [
  'https://example.com/historical-document-1.txt',
  'https://example.com/historical-document-2.txt',
  // Add more URLs as needed...
];

fetchAndProcessDocuments(documentUrls)
  .then(results => {
    console.log('Battle extraction results:', results);
  })
  .catch(error => {
    console.error('An error occurred during processing:', error.message);
  });
```

### Key Components:

- **Streaming and Memory Management:** Using streams for fetching documents to handle large files efficiently.
- **Pattern Matching:** Regular expressions are used here, but the pattern array (`battlePatterns`) can be easily expanded or replaced with a more sophisticated natural language processing library if necessary.
- **Error Handling:** The solution includes basic error handling for network requests and parsing errors. You might expand on this based on specific needs (e.g., retries).
- **Maintainability:** The list of well-documented battles is stored in a `Set`, making it easy to update without altering the core logic.

This code provides an effective starting point, offering both robustness and adaptability for future enhancements or changes in data sources.']

["```javascript
function renderScriptFooters(scripts) {
    const renderedScripts = document.createDocumentFragment();

    if (!Array.isArray(scripts) || scripts.length === 0) return null;

    const existingIds = new Set();

    scripts.forEach(script => {
        if (typeof script.key !== 'string' || typeof script.code !== 'string') return;

        let id = `script-${sanitizeStringForId(script.key)}`;
        while (existingIds.has(id)) {
            id += '-1';
        }
        existingIds.add(id);

        const div = document.createElement('div');
        div.className = sanitizeClassName(script.key);

        const scriptTag = document.createElement('script');
        scriptTag.id = id;
        if ('innerHTML' in scriptTag) { // Safely use innerHTML only when available
            scriptTag.innerHTML = script.code;
        } else {
            scriptTag.textContent = script.code; // Fallback for environments without innerHTML support
        }

        div.appendChild(scriptTag);
        renderedScripts.appendChild(div);
    });

    return renderedScripts;
}

function sanitizeStringForId(input) {
    return input.trim().replace(/[^a-zA-Z0-9-_]/g, '');
}

function sanitizeClassName(input) {
    return 'footer-' + input.trim().replace(/[^\w-]/g, '').toLowerCase();
}
