const { EventEmitter } = require('events');
const amqp = require('amqplib/callback_api');

class DataStreamProcessor extends EventEmitter {
  constructor(analyticsQueue, javaServiceQueue) {
    super();
    this.analyticsQueue = analyticsQueue;
    this.javaServiceQueue = javaServiceQueue;
    this.paused = false;
    this.buffer = [];
    this.isUpdatingAnalytics = false;

    // Initialize the AMQP connection
    amqp.connect('amqp://localhost', (err, conn) => {
      if (err) throw err;
      conn.createChannel((err, ch) => {
        if (err) throw err;

        // Ensure queues exist
        ch.assertQueue(this.analyticsQueue, { durable: true });
        ch.assertQueue(this.javaServiceQueue, { durable: true });

        this.channel = ch;
      });
    });
  }

  async processData(data) {
    if (this.paused) {
      this.buffer.push(data);
      return;
    }

    try {
      // Simulate processing and store data
      await this.storeData(data);

      // Emit event for analytics update
      this.emit('dataProcessed', data);

      // Send processed data to Java service queue
      this.channel.sendToQueue(this.javaServiceQueue, Buffer.from(JSON.stringify(data)), { persistent: true });
    } catch (error) {
      console.error('Error processing data:', error);
    }
  }

  async storeData(data) {
    // Implement your storage logic here
    // This could involve caching strategies or database writes

    // Simulate an asynchronous operation
    return new Promise(resolve => setTimeout(resolve, 100));
  }

  pause() {
    this.paused = true;
  }

  resume() {
    this.paused = false;
    while (this.buffer.length > 0) {
      const data = this.buffer.shift();
      this.processData(data);
    }
  }

  async updateAnalyticsPlatform(processedData) {
    if (this.isUpdatingAnalytics) return;

    try {
      this.isUpdatingAnalytics = true;
      // Implement your analytics update logic here
      await new Promise(resolve => setTimeout(resolve, 200)); // Simulate network delay

      // Notify the completion of analytics update
      this.emit('analyticsUpdated', processedData);
    } catch (error) {
      console.error('Error updating analytics:', error);

      // Retry mechanism in case of failure
      setTimeout(() => this.updateAnalyticsPlatform(processedData), 5000);
    } finally {
      this.isUpdatingAnalytics = false;
    }
  }

  async start() {
    this.on('dataProcessed', (data) => this.updateAnalyticsPlatform(data));

    // Simulate receiving data from a streaming source
    setInterval(() => {
      const mockData = { timestamp: Date.now(), value: Math.random() };
      this.processData(mockData);
    }, 1000); // Adjust interval as needed for your data stream rate
  }
}

// Usage example:
const processor = new DataStreamProcessor('analyticsQueue', 'javaServiceQueue');
processor.start();

module.exports = DataStreamProcessor;
```

