import java.util.*;
import java.time.Instant;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentSkipListSet;

public class SessionProcessor {

    private static final ConcurrentHashMap<String, ConcurrentSkipListSet<SessionInterval>> sessions = new ConcurrentHashMap<>();

    public static void processActivity(String userId, String deviceType, Instant startTimestamp) {
        String key = generateKey(userId, deviceType);
        sessions.computeIfAbsent(key, k -> new ConcurrentSkipListSet<>(Comparator.comparingLong(SessionInterval::getEnd)))
                .add(new SessionInterval(startTimestamp.toEpochMilli(), estimateEndTime(deviceType, startTimestamp)));

        detectOverlaps(key);
    }

    private static String generateKey(String userId, String deviceType) {
        return userId + "-" + deviceType;
    }

    private static long estimateEndTime(String deviceType, Instant startTime) {
        // Placeholder for logic to estimate end time based on device type
        switch (deviceType) {
            case "mobile":
                return startTime.toEpochMilli() + 300000; // 5 minutes
            case "desktop":
                return startTime.toEpochMilli() + 600000; // 10 minutes
            default:
                return startTime.toEpochMilli() + 200000; // 3 minutes
        }
    }

    private static void detectOverlaps(String key) {
        ConcurrentSkipListSet<SessionInterval> sessionSet = sessions.get(key);
        if (sessionSet == null || sessionSet.size() < 2) return;

        long overlappingCount = 0;
        for (Iterator<SessionInterval> iterator = sessionSet.iterator(); iterator.hasNext();) {
            SessionInterval current = iterator.next();
            for (Iterator<SessionInterval> innerIterator = iterator; innerIterator.hasNext();) {
                SessionInterval next = innerIterator.next();
                if (current.overlapsWith(next)) {
                    overlappingCount++;
                }
            }
        }

        System.out.println("Overlapping sessions detected: " + overlappingCount);
    }

    static class SessionInterval {
        private final long start;
        private final long end;

        public SessionInterval(long start, long end) {
            this.start = start;
            this.end = end;
        }

        public boolean overlapsWith(SessionInterval other) {
            return this.start < other.end && other.start < this.end;
        }

        public long getEnd() {
            return end;
        }
    }

    public static void main(String[] args) {
        // Simulate processing real-time data
        processActivity("user1", "mobile", Instant.now());
        processActivity("user2", "desktop", Instant.now().plusSeconds(30));
        // Add more test cases as needed

        // Performance report logic (placeholder)
        System.out.println("Performance Report:");
        System.out.println("Average processing time per session: Placeholder");
        System.out.println("Memory usage statistics: Placeholder");
    }
}
