import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Logger;

public class DistributedCacheService {
    private static final Logger logger = Logger.getLogger(DistributedCacheService.class.getName());
    private Map<String, Node> nodes = new ConcurrentHashMap<>();
    private String leaderNodeKey;
    private boolean isNetworkPartitioned = false;

    public synchronized void addNode(Node node) {
        nodes.put(node.getId(), node);
        electLeader();
        logger.info("Node added: " + node.getId());
    }

    public synchronized void removeNode(String nodeId) {
        Node removedNode = nodes.remove(nodeId);
        if (removedNode != null) {
            if (isLeader(nodeId)) {
                electLeader();
            }
            logger.info("Node removed: " + nodeId);
        }
    }

    private void electLeader() {
        // Implement leader election using a consensus algorithm like Raft or Paxos
        leaderNodeKey = nodes.keySet().iterator().next(); // Simplified for illustration
        logger.info("New leader elected: " + leaderNodeKey);
    }

    public boolean isLeader(String nodeId) {
        return leaderNodeKey.equals(nodeId);
    }

    public void handleNetworkPartition(boolean partitioned) {
        isNetworkPartitioned = partitioned;
        if (partitioned) {
            // Implement logic to handle network partition
            logger.warning("Network partition detected.");
        } else {
            synchronizeData();
            logger.info("Network restored, data synchronized.");
        }
    }

    private void synchronizeData() {
        // Logic for re-synchronizing data across nodes after a network partition
        if (!isNetworkPartitioned) {
            for (Node node : nodes.values()) {
                node.synchronizeCache();
            }
        }
    }

    public void updateData(String key, Object value) {
        if (isLeader(leaderNodeKey)) {
            // Apply updates and propagate to other nodes
            nodes.get(leaderNodeKey).updateCache(key, value);
            propagateUpdate(key, value);
        } else {
            logger.info("Node is not the leader. Delegating update.");
            getNodeById(leaderNodeKey).delegateUpdate(key, value);
        }
    }

    private void propagateUpdate(String key, Object value) {
        for (Node node : nodes.values()) {
            if (!node.getId().equals(leaderNodeKey)) {
                node.updateCache(key, value);
            }
        }
    }

    public Node getNodeById(String nodeId) {
        return nodes.get(nodeId);
    }

    public void detectAndHandleNodeFailure() {
        // Implement failure detection and failover mechanism
        for (String nodeId : new HashSet<>(nodes.keySet())) {
            if (!nodes.get(nodeId).isAlive()) {
                removeNode(nodeId);
                logger.warning("Node failure detected and handled: " + nodeId);
            }
        }
    }

    public Object getData(String key) {
        return nodes.get(leaderNodeKey).getCache().get(key);
    }

    public void removeData(String key) {
        if (isLeader(leaderNodeKey)) {
            nodes.get(leaderNodeKey).removeFromCache(key);
            propagateRemoval(key);
        } else {
            getNodeById(leaderNodeKey).delegateRemove(key);
        }
    }

    private void propagateRemoval(String key) {
        for (Node node : nodes.values()) {
            if (!node.getId().equals(leaderNodeKey)) {
                node.removeFromCache(key);
            }
        }
    }

    public static class Node {
        private String id;
        private Map<String, Object> cache = new ConcurrentHashMap<>();

        public Node(String id) {
            this.id = id;
        }

        public String getId() {
