['```java
import java.util.concurrent.*;
import java.util.logging.*;
import java.net.URI;
import java.net.http.*;
import java.net.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;

public class ResourceIntensiveServiceManager {

    private static final Logger logger = Logger.getLogger(ResourceIntensiveServiceManager.class.getName());
    private static final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(4);
    private static volatile boolean running = true;

    private final HttpClient httpClient;
    private final MessagingSystem messagingSystem; // Assume MessagingSystem is an interface with necessary methods

    public ResourceIntensiveServiceManager(MessagingSystem messagingSystem) {
        this.httpClient = HttpClient.newBuilder()
                .connectTimeout(Duration.ofSeconds(10))
                .build();
        this.messagingSystem = messagingSystem;

        setupLogging();
    }

    private void setupLogging() {
        Handler consoleHandler = new ConsoleHandler();
        consoleHandler.setLevel(Level.INFO);
        logger.addHandler(consoleHandler);
        logger.setLevel(Level.FINE);
        Logger.getLogger("java.net.http").setLevel(Level.WARNING); // Reduce HTTP client logging verbosity
    }

    public void startServiceCycles(long periodSeconds) {
        Runnable task = () -> {
            if (running) {
                try {
                    startResourceIntensiveService();
                    stopResourceIntensiveService();
                } catch (Exception e) {
                    logger.log(Level.SEVERE, "Error during service cycle", e);
                }
            }
        };
        scheduler.scheduleAtFixedRate(task, 0, periodSeconds, TimeUnit.SECONDS);
    }

    private void startResourceIntensiveService() throws Exception {
        logger.info("Starting resource-intensive service");
        messagingSystem.sendMessage("Service started");

        // Simulate API interaction
        String response = performApiCallWithRetries("/start-service", 3);
        logger.fine("API Response: " + response);

        // Resource intensive task simulation
        performResourceIntensiveTask();

        healthCheck();
    }

    private void stopResourceIntensiveService() throws Exception {
        logger.info("Stopping resource-intensive service");
        messagingSystem.sendMessage("Service stopped");

        // Simulate API interaction
        String response = performApiCallWithRetries("/stop-service", 3);
        logger.fine("API Response: " + response);

        healthCheck();
    }

    private void performResourceIntensiveTask() {
        // Placeholder for resource-intensive operation
    }

    private String performApiCallWithRetries(String endpoint, int maxAttempts) throws Exception {
        int attempt = 0;
        while (attempt < maxAttempts) {
            try {
                HttpRequest request = HttpRequest.newBuilder()
                        .uri(URI.create("http://api.example.com" + endpoint))
                        .GET()
                        .build();

                HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
                if (response.statusCode() == 200) {
                    return response.body();
                } else {
                    logger.warning("Received non-OK response: " + response.statusCode());
                }
            } catch (IOException | InterruptedException e) {
                attempt++;
                if (attempt >= maxAttempts) throw e;
                sleepWithExponentialBackoff(attempt);
            }
        }
        throw new RuntimeException("Failed to perform API call after retries");
    }

    private void sleepWithExponentialBackoff(int attempt) {
        try {
            long delay = (long) Math.pow(2, attempt) * 100L; // Exponential backoff
            Thread.sleep(delay);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    private void healthCheck() throws Exception {
        logger.info("Performing health check");
        String response = performApiCallWithRetries("/health", 3);
        if (!response.equals("healthy")) {
            throw new RuntimeException("Health check failed: " + response);
        }
    }

    public void shutdown() {
        running = false;
        scheduler.shutdown();
        try {
            if (!scheduler.awaitTermination(60, TimeUnit.SECONDS)) {
                scheduler.shutdownNow();
            }
        } catch (InterruptedException e) {
            scheduler.shutdownNow();
        }
    }

    public static void main(String[] args) throws Exception {
        MessagingSystem messagingSystem = new YourMessagingSystemImplementation(); // Implement your own
        ResourceIntensiveServiceManager manager = new ResourceIntensiveServiceManager(messagingSystem);

        Runtime.getRuntime().addShutdownHook(new Thread(manager::shutdown));
        manager.startServiceCycles(10); // Start and stop every 10 seconds

        // Simulate running indefinitely
        while (true) {
            TimeUnit.SECONDS.sleep(1);
        }
    }

    @FunctionalInterface
    interface MessagingSystem {
        void sendMessage(String message) throws Exception;
    }
}
``` 

