<?php

// Load Composer's autoloader.
require_once __DIR__ . '/vendor/autoload.php';

use Symfony\Component\Yaml\Yaml;
use Symfony\Component\Yaml\Exception\ParseException;

class ConfigLoader
{
    private $envConfig = [];
    private $configCache = [];

    public function __construct($environment)
    {
        $this->loadEnvironmentVariables($environment);
        $this->loadAutoloader();
        $this->loadAndValidateConfig($environment);
    }

    private function loadEnvironmentVariables($environment)
    {
        $envFile = getenv('ENV_CONFIG_PATH') ?: "config/{$environment}.env";

        if (!file_exists($envFile)) {
            throw new Exception("Environment configuration file not found: {$envFile}");
        }

        $lines = file($envFile, FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES);

        foreach ($lines as $line) {
            if (strpos(trim($line), '#') === 0 || empty(trim($line))) {
                continue;
            }

            list($name, $value) = explode('=', $line, 2);

            if (!array_key_exists($name, $_SERVER) && !array_key_exists($name, $_ENV)) {
                putenv("{$name}={$value}");
                $_ENV[$name] = $value;
                $_SERVER[$name] = $value;
                $this->configCache[$name] = $value;
            }
        }

        // Implement fallback logic if necessary
    }

    private function loadAutoloader()
    {
        $autoloadPath = getenv('VENDOR_PATH') ?: __DIR__ . '/vendor/autoload.php';

        if (!file_exists($autoloadPath)) {
            throw new Exception("Vendor autoload file not found: {$autoloadPath}");
        }

        require_once $autoloadPath;
    }

    private function loadAndValidateConfig($environment)
