// Ensure thread safety
class ResourceLocker
{
    private static $lock;

    public static function lock($resource)
    {
        if (!isset(self::$lock[$resource])) {
            self::$lock[$resource] = true;
        } else {
            throw new Exception("Resource is already locked: {$resource}");
        }
    }

    public static function unlock($resource)
    {
        unset(self::$lock[$resource]);
    }
}

// Usage
try {
