    PerformanceMonitor::start();

    ResourceLocker::lock('config_loader');
    (new ConfigLoader($environment));
    DependencyManager::updateDependencies();
    ResourceLocker::unlock('config_loader');

    PerformanceMonitor::end();

} catch (Exception $e) {
    Logger::log("Error: " . $e->getMessage(), 'ERROR');
