use std::process::{Command, Output};
use std::time::{Duration, Instant};
use tokio::sync::mpsc;
use log::{info, warn, error};
use memusage::MemUsage;

async fn build_system_metrics(project_dir: &str) -> Result<BuildReport, String> {
    let mut metrics = BuildMetrics::new();

    // Start memory profiler
    let mut mem_usage = MemUsage::default();

    // Create a channel for logging events
    let (log_sender, mut log_receiver) = mpsc::channel(100);

    tokio::spawn(async move {
        while let Some(log_event) = log_receiver.recv().await {
            handle_log_event(&log_event).await;
        }
    });

    // Start timer
    let start_time = Instant::now();

    match run_build(project_dir, &metrics, &mut mem_usage, &log_sender).await {
        Ok(_) => metrics.set_success(true),
        Err(e) => {
            error!("Build failed: {}", e);
            metrics.set_error_message(e.to_string());
        }
    }

    // Calculate duration
    let duration = start_time.elapsed();

    // Collect final metrics
    metrics.set_duration(duration);

    if let Err(e) = mem_usage.get_process_memory().map_err(|e| e.to_string()) {
        error!("Failed to fetch memory usage: {}", e);
    } else {
        metrics.set_memory_usage(mem_usage.used());
    }

    Ok(BuildReport::new(metrics))
}

async fn run_build(
    project_dir: &str,
