### C-Based DNS Resolver Module

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <netdb.h>

// Function to resolve domain name to IP address using DNS lookup
char* dns_resolve(const char *domain) {
    struct addrinfo hints, *res;
    char ipstr[INET6_ADDRSTRLEN];

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    if (getaddrinfo(domain, NULL, &hints, &res) != 0) {
        return NULL;
    }

    void *addr = res->ai_addr->sa_data;
    if (inet_ntop(res->ai_family, addr, ipstr, sizeof(ipstr)) == NULL) {
        freeaddrinfo(res);
        return NULL;
    }

    freeaddrinfo(res);
    char* resolved_ip = strdup(ipstr);
    return resolved_ip;
}

// Example usage
int main() {
    const char *domain = "example.com";
    char *ip_address = dns_resolve(domain);

    if (ip_address) {
        printf("IP Address: %s\n", ip_address);
        free(ip_address);
    } else {
        printf("DNS resolution failed.\n");
    }

    return 0;
}
```

### PHP-Based OAuth 2.0 Client Module

```php
<?php
session_start();
require 'vendor/autoload.php';

use League\OAuth2\Client\Provider\GenericProvider;

$provider = new GenericProvider([
    'clientId'                => 'your-client-id',
    'clientSecret'            => 'your-client-secret',
    'redirectUri'             => 'https://your-redirect-uri/',
    'urlAuthorize'            => 'https://example.com/authorize',
    'urlAccessToken'          => 'https://example.com/token',
    'urlResourceOwnerDetails' => 'https://example.com/resource'
]);

// Function to authenticate user using OAuth 2.0
function authenticateUser() {
    global $provider;

    if (!isset($_GET['code'])) {
        $authorizationUrl = $provider->getAuthorizationUrl();
        $_SESSION['oauth2state'] = $provider->getState();

        header('Location: ' . $authorizationUrl);
        exit;
    } elseif (empty($_GET['state']) || ($_GET['state'] !== $_SESSION['oauth2state'])) {
        unset($_SESSION['oauth2state']);
        exit('Invalid state');
    } else {
        try {
            $accessToken = $provider->getAccessToken('authorization_code', [
                'code' => $_GET['code']
            ]);

            // Store access token in session
            $_SESSION['access_token'] = $accessToken;

            // Fetch user information
            $resourceOwner = $provider->getResourceOwner($accessToken);
            return $resourceOwner->toArray();

        } catch (Exception $e) {
            exit('Failed to get access token: ' . $e->getMessage());
        }
    }
}

// Example usage
$userInfo = authenticateUser();
print_r($userInfo);

?>
