#include <string.h>

char* appendSlashIfWithinLimit(const char* inputString, int sizeLimit, void* context) {
    // Calculate the length of the input string
    int inputLength = strlen(inputString);

    if (inputLength + 1 > sizeLimit) { // Check if adding a slash exceeds the limit
        return NULL; // Return NULL if it does exceed
    }

    // Allocate memory for new string with an extra character for the slash and null-terminator
    char* result = malloc((inputLength + 2) * sizeof(char));
    if (!result) {
        return NULL; // Handle memory allocation failure
    }

    // Copy input string to the newly allocated space
    strcpy(result, inputString);

    // Append a forward slash
    strcat(result, "/");

    // Return the result
    return result;
}
