function traverseDOM(document, selector, callback, context) {
    const matchedElements = [];

    function recursiveTraverse(node) {
        if (node.matches(selector)) {
            // Apply the callback with the context and check if it matches criteria
            if (callback.call(context, node)) {
                matchedElements.push(node.tagName);
            }
        }

        for (let child of node.children) {
            recursiveTraverse(child); // Recursively traverse child nodes
        }
    }

    recursiveTraverse(document.body); // Start traversal from the body element

    return matchedElements; // Return array of tag names of matched elements
}
