['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>

#define MAX_LINE_LENGTH 1024
#define DEFAULT_THEME_DIR "./themes"
#define CACHE_DIR "./cache"

typedef struct {
    char *path;
    int in_use;
} Theme;

Theme *theme_cache = NULL;
size_t theme_cache_size = 10; // Initial cache size

// Function to initialize the theme cache
void init_theme_cache() {
    theme_cache = (Theme *)malloc(theme_cache_size * sizeof(Theme));
    for (size_t i = 0; i < theme_cache_size; i++) {
        theme_cache[i].path = NULL;
        theme_cache[i].in_use = 0;
    }
}

// Function to get a theme from the cache or create a new one
char *get_theme(const char *theme_path) {
    for (size_t i = 0; i < theme_cache_size; i++) {
        if (!theme_cache[i].in_use && strcmp(theme_cache[i].path, theme_path) == 0) {
            theme_cache[i].in_use = 1;
            return theme_cache[i].path;
        }
    }

    for (size_t i = 0; i < theme_cache_size; i++) {
        if (!theme_cache[i].in_use) {
            free(theme_cache[i].path);
            theme_cache[i].path = strdup(theme_path);
            theme_cache[i].in_use = 1;
            return theme_cache[i].path;
        }
    }

    // Resize cache
    size_t new_size = theme_cache_size * 2;
    Theme *new_cache = (Theme *)realloc(theme_cache, new_size * sizeof(Theme));
    if (!new_cache) {
        perror("Failed to resize theme cache");
        exit(EXIT_FAILURE);
    }
    theme_cache = new_cache;
    for (size_t i = theme_cache_size; i < new_size; i++) {
        theme_cache[i].path = NULL;
        theme_cache[i].in_use = 0;
    }
    theme_cache_size = new_size;

    // Add new theme
    char *new_theme_path = strdup(theme_path);
    theme_cache[theme_cache_size - 1].path = new_theme_path;
    theme_cache[theme_cache_size - 1].in_use = 1;
    return new_theme_path;
}

// Function to process a file line by line
void process_file(const char *file_path) {
    FILE *file = fopen(file_path, "r");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    char *line = NULL;
    size_t len = 0;
    while (getline(&line, &len, file) != -1) {
        char *last_space = strrchr(line, ' ');
        if (last_space && last_space != line) {
            char *second_last_space = strrchr(line, ' ', last_space - line - 1);
            if (second_last_space) {
                double first_value = atof(second_last_space + 1);
                double second_value = atof(last_space + 1);
                double average = (first_value + second_value) / 2.0;
                snprintf(last_space + 1, len - (last_space - line), "%.2f", average);
            }
        }
        printf("%s", line); // Processed line output
    }

    free(line);
    fclose(file);
}

