#include <pthread.h>
#include "tiffio.h"  // Assume libtiff is used for TIFF handling

// Define a struct to hold image information and performance metrics
typedef struct {
    char filename[256];
    int bit_depth;
    unsigned long width, height;
    unsigned long extra_samples_count;
    double processing_time;  // in seconds
} ImageInfo;

// Mutex for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to log errors
void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

// Process a single TIFF file and populate the image information
int process_tiff_file(const char *filepath, ImageInfo *info) {
    struct stat fileInfo;
    if (stat(filepath, &fileInfo) != 0) {
        log_error("Failed to get file stats");
        return -1;
    }

    TIFF* tif = TIFFOpen(filepath, "r");
    if (!tif) {
        log_error("Error opening TIFF file");
        return -1;
    }

    uint32 width, height;
    int bit_depth;

    if (TIFFGetField(tif, TIFFTAG_IMAGEWIDTH, &width) &&
        TIFFGetField(tif, TIFFTAG_IMAGELENGTH, &height) &&
        TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &bit_depth)) {

        info->width = width;
        info->height = height;
        info->bit_depth = bit_depth;
    } else {
        log_error("Error reading image attributes");
        TIFFClose(tif);
        return -1;
    }

    uint32 samples_per_pixel;
    if (TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &samples_per_pixel)) {
        info->extra_samples_count = samples_per_pixel - 3; // Assuming RGB as base
    } else {
        log_error("Error reading sample count");
        TIFFClose(tif);
        return -1;
    }

    strcpy(info->filename, filepath);
    TIFFClose(tif);
    return 0;
}

// Thread function to process files concurrently
void* process_file_thread(void *arg) {
    char *filepath = (char *)arg;
    ImageInfo info;

    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    if (process_tiff_file(filepath, &info) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        double elapsed_time = (end.tv_sec - start.tv_sec) + 
                              (end.tv_nsec - start.tv_nsec) / 1e9;

        pthread_mutex_lock(&lock);
        info.processing_time = elapsed_time;
        printf("File: %s, Bit Depth: %d, Width: %lu, Height: %lu, "
               "Extra Samples: %lu, Processing Time: %.6f\n",
               info.filename, info.bit_depth, info.width, info.height,
               info.extra_samples_count, info.processing_time);
        pthread_mutex_unlock(&lock);
    }

    return NULL;
}

// Main function to process TIFF files in a directory
void process_tiff_directory(const char *directory_path) {
    DIR *dir;
    struct dirent *entry;

    if (!(dir = opendir(directory_path))) {
        log_error("Error opening directory");
        return;
    }

    pthread_t threads[1024]; // Assume max 1024 files to process
    int thread_count = 0;

    while ((entry = readdir(dir)) != NULL) {
        if (strstr(entry->d_name, ".tif") || strstr(entry->d_name, ".tiff")) {
            char filepath[512];
            snprintf(filepath, sizeof(filepath), "%s/%s", directory_path, entry->d_name);

            pthread_create(&threads[thread_count], NULL, process_file_thread, strdup(filepath));
            thread_count++;
        }
    }

    for (int i = 0; i < thread_count; i++) {
        pthread_join(threads[i], NULL);
    }

    closedir(dir);
}

// Example usage
int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <directory_path>\n", argv[0]);
        return EXIT_FAILURE;
    }

    process_tiff_directory(argv[1]);

    pthread_mutex_destroy(&lock);
    return EXIT_SUCCESS;
}
