#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_FILENAME_LENGTH 100
#define ORIGINAL_MAX_LENGTH 80
#define NUM_FILE_TYPES 5

typedef struct {
    char *types[NUM_FILE_TYPES];
    int count[NUM_FILE_TYPES];
} FileTypeSession;

void initFileTypeSession(FileTypeSession *session) {
    session->types[0] = ".txt";
    session->types[1] = ".log";
    session->types[2] = ".csv";
    session->types[3] = ".xml";
    session->types[4] = ".json";

    for (int i = 0; i < NUM_FILE_TYPES; i++) {
        session->count[i] = 0;
    }
}

int selectFileType(FileTypeSession *session) {
    int typeIndex, prevCount = -1;

    do {
        typeIndex = rand() % NUM_FILE_TYPES;
    } while (session->count[typeIndex] >= 3);

    if (prevCount != -1 && session->count[prevCount] == 3) {
        for (int i = 0; i < NUM_FILE_TYPES; i++) {
            if (i != prevCount && session->count[i] < 3) {
                typeIndex = i;
                break;
            }
        }
    }

    session->count[typeIndex]++;

    return typeIndex;
}

void generateRandomDigits(char *digits, int length) {
    for (int i = 0; i < length; i++) {
        digits[i] = '0' + rand() % 10;
    }
    digits[length] = '\0';
}

void modifyFilename(const char *original, char *newFilename, FileTypeSession *session) {
    int origLength = strlen(original);
    if (origLength > ORIGINAL_MAX_LENGTH) {
        origLength = ORIGINAL_MAX_LENGTH;
    }

    // Ensure the buffer is large enough
    newFilename[0] = '\0';

    char tempFilename[MAX_FILENAME_LENGTH];
    strncpy(tempFilename, original, origLength);
    tempFilename[origLength] = '\0';

    int digitCount = (rand() % 5) + 1;
    char randomDigits[6];
    generateRandomDigits(randomDigits, digitCount);

    int fileTypeIndex = selectFileType(session);
    const char *fileType = session->types[fileTypeIndex];

    snprintf(newFilename, MAX_FILENAME_LENGTH, "%s%s%s", tempFilename, randomDigits, fileType);
}

int main() {
    srand(time(NULL));

    FileTypeSession session;
    initFileTypeSession(&session);

    const char *originalFilename = "example_filename_with_special_chars_!@#";
    char newFilename[MAX_FILENAME_LENGTH];

    modifyFilename(originalFilename, newFilename, &session);

    printf("Original: %s\n", originalFilename);
    printf("Modified: %s\n", newFilename);

    return 0;
}
