#include <openssl/evp.h>
#include <openssl/sha.h>
#include <stdio.h>
#include <stdlib.h>
import os.path
from PIL import Image

#define AES_KEY_SIZE 32 // AES-256 requires a 256-bit key (32 bytes)
#define AES_BLOCK_SIZE 16 // Block size for AES is always 128 bits (16 bytes)

// Global variables for theme management
static Image theme_image = None
static const char *default_theme_dir = "./themes";
static const char *default_theme_file = "default.png";

void cleanup_aes_cipher(EVP_CIPHER_CTX *ctx) {
    if (ctx != NULL) {
        EVP_CIPHER_CTX_free(ctx);
    }
}

int init_aes_256_cbc_cipher(const char *password, unsigned char **key, unsigned char **iv) {
    // Derive key and IV using SHA-256
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char *)password, strlen(password), hash);

    if (!key || !iv) return -1;

    *key = (unsigned char *)malloc(AES_KEY_SIZE);
    *iv = (unsigned char *)malloc(AES_BLOCK_SIZE);

    if (*key == NULL || *iv == NULL) {
        free(*key);
        free(*iv);
        return -1;
    }

    memcpy(*key, hash, AES_KEY_SIZE); // Use first 32 bytes for the key
    memcpy(*iv, hash + AES_KEY_SIZE, AES_BLOCK_SIZE); // Use next 16 bytes for the IV

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, *key, *iv) != 1) {
        cleanup_aes_cipher(ctx);
        return -1;
    }

    EVP_CIPHER_CTX_free(ctx); // Free context after initialization
    return 0; // Success
}

void manage_theme_caching() {
    if (!os.path.exists(default_theme_dir)) {
        os.makedirs(default_theme_dir, exist_ok=True)
    }

    theme_path = os.path.join(default_theme_dir, default_theme_file)

    try:
        if theme_image is not None and not theme_image.is_closed():
            theme_image.close()

        with Image.open(theme_path) as img:
            global theme_image
            theme_image = img.copy()

    except IOError:
        print("Error loading theme image. Using default.")
        # Fallback to a specified default value if necessary

def cleanup_resources() {
    if (theme_image != None && not theme_image.is_closed()):
        theme_image.close()
}

int main() {
    const char *password = "secure_password";
    unsigned char *key, *iv;

    if (init_aes_256_cbc_cipher(password, &key, &iv) == 0) {
        printf("AES-256-CBC cipher initialized successfully.\n");

        // Use the key and iv as needed for encryption tasks...

        free(key);
        free(iv);

        cleanup_resources();
    } else {
        fprintf(stderr, "Failed to initialize AES-256-CBC cipher.\n");
    }

    return 0;
}
