#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

// Assuming the use of a hypothetical library 'libjpeg2pdf'
extern int convert_jpeg_to_pdf(const char *input, const char *output);

void* conversion_thread(void* arg) {
    struct ConversionTask {
        const char* input;
        const char* output;
    };

    struct ConversionTask* task = (struct ConversionTask*)arg;

    // Log start time
    printf("Conversion started for %s\n", task->input);
    int result = convert_jpeg_to_pdf(task->input, task->output);

    if (result == 0) {
        printf("Conversion successful: %s to %s\n", task->input, task->output);
    } else {
        fprintf(stderr, "Conversion failed for %s\n", task->input);
    }

    // Log end time
    free(task);
    return NULL;
}

int convertJpegToPdf(const char* inputFileName, const char* outputFileName) {
    if (strstr(inputFileName, ".jpg") == NULL && strstr(inputFileName, ".jpeg") == NULL) {
        fprintf(stderr, "Invalid file extension for %s\n", inputFileName);
        return 1;
    }

    // Check if the output file already exists
    if (access(outputFileName, F_OK) != -1) {
        fprintf(stderr, "Output file %s already exists.\n", outputFileName);
        return 1;
    }

    pthread_t thread;
    struct ConversionTask* task = malloc(sizeof(struct ConversionTask));
    task->input = strdup(inputFileName);
    task->output = strdup(outputFileName);

    if (pthread_create(&thread, NULL, conversion_thread, task) != 0) {
        fprintf(stderr, "Failed to create conversion thread.\n");
        free(task);
        return 1;
    }

    pthread_join(thread, NULL);
    return 0;
}
