            throw new ArgumentException("Directory path cannot be null or empty.", nameof(directoryPath));

        if (string.IsNullOrWhiteSpace(siteName))
            throw new ArgumentException("Site name cannot be null or empty.", nameof(siteName));

        int maxRetries = 3;
        TimeSpan delay = TimeSpan.FromSeconds(1);

        for (int attempt = 0; attempt < maxRetries; attempt++)
        {
            try
            {
                _logger.LogInformation($"Attempt {attempt + 1} to add and launch web application: {siteName}");

                if (!Directory.Exists(directoryPath))
                {
                    throw new DirectoryNotFoundException($"The directory '{directoryPath}' does not exist.");
                }

                string webConfigPath = Path.Combine(directoryPath, "web.config");

                if (!File.Exists(webConfigPath))
                {
                    _logger.LogWarning("No 'web.config' found. Attempting to generate a default one...");
                    GenerateDefaultWebConfig(webConfigPath);
                }

                ValidateAndEnsurePermissions(directoryPath);

                // Simulate adding and launching the application
                LaunchApplication(directoryPath, siteName);

                _logger.LogInformation($"Successfully launched web application: {siteName}");
                break;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Error during attempt {attempt + 1} to add and launch web application: {siteName}");

                if (attempt < maxRetries - 1)
                {
                    await Task.Delay(delay);
                    delay = TimeSpan.FromSeconds(delay.TotalSeconds * 2); // Exponential backoff
                }
                else
                {
                    throw new Exception($"Failed to add and launch web application after {maxRetries} attempts.", ex);
                }
            }
        }
    }

