    char *decryptionKey;
} DecryptionConfig;

// Define function pointer types for callbacks
typedef void (*DecryptionCallback)(const char *, const char *, char **, int *);
typedef void (*LogCallback)(const char *);

// Function to process and decrypt message
int processAndDecrypt(ConnectionInfo *connection, DecryptionConfig *config,
                      DecryptionCallback decryptionFunc, LogCallback logFunc) {
    // Validation checks
    if (!connection || !config || !decryptionFunc || !logFunc ||
        (connection->password == NULL && strlen(connection->password) == 0) ||
        connection->title == NULL || strlen(connection->title) == 0 ||
        !connection->isActive && config->encodedMessage != NULL) {

        logFunc("Validation failed.");
        return -1;
    }

    // Log the start of the decryption process
    char *decryptedMessage = NULL;
    int result;

    if (!connection->isActive && config->encodedMessage != NULL) {
        logFunc("Decryption attempted on inactive connection.");
        return -3;
    }

    // Perform decryption
    decryptionFunc(config->encodedMessage, config->decryptionKey, &decryptedMessage, &result);

    if (result == 0 && decryptedMessage != NULL) {
        printf("Decrypted Message: %s\n", decryptedMessage);
        free(decryptedMessage); // Assume memory was allocated by the callback
        return 0; // Success
    } else {
        logFunc("Decryption failed.");
