using System;
using System.Collections.Generic;
using System.Data;
using System.IO;

public class DataProcessor
{
    private static readonly Random random = new Random();
    private const string[] FileTypes = { ".txt", ".log", ".csv", ".xml", ".json" };
    private Dictionary<string, int> fileTypeUsageCount = new Dictionary<string, int>();
    private Queue<string> fileQueue = new Queue<string>();

    public DataTableReader ProcessData(byte[] data, string originalFilename)
    {
        InitializeFileTypeQueue();

        // Generate a random filename
        string fileName = GenerateFileName(originalFilename);

        // Send the byte array to an external processing service
        var processedResults = ExternalDataService.SendToService(data, fileName);

        return new DataTableReader(processedResults);
    }

    private void InitializeFileTypeQueue()
    {
        if (fileTypeUsageCount.Count == 0)
        {
            foreach (var fileType in FileTypes)
            {
                fileTypeUsageCount[fileType] = 1;
                fileQueue.Enqueue(fileType);
            }
        }
    }

    private string GenerateFileName(string originalFilename)
    {
        // Truncate the filename if it exceeds 80 characters
        if (originalFilename.Length > 80)
        {
            originalFilename = originalFilename.Substring(0, 80);
        }

        // Remove spaces and special characters
        string sanitizedBaseName = Path.GetInvalidFileNameChars().Aggregate(originalFilename, (current, c) => current.Replace(c.ToString(), ""));

        // Generate a random sequence of digits between 1 and 5 in length
        int randomDigitLength = random.Next(1, 6);
        string randomNumberString = new string((random.Next(0, 100000).ToString().Take(randomDigitLength)).ToArray());

        // Select the next file type from the queue
        string selectedFileType = fileQueue.Dequeue();
        fileTypeUsageCount[selectedFileType]++;

        if (fileTypeUsageCount[selectedFileType] == 3)
        {
            for (int i = 0; i < 5 - fileTypeUsageCount.Count + 1; i++)
            {
                var nextFileType = FileTypes[random.Next(FileTypes.Length)];
                if (!selectedFileType.Equals(nextFileType))
                {
                    fileQueue.Enqueue(nextFileType);
                    selectedFileType = nextFileType;
                    break;
                }
            }
        }

        // Requeue the used file type for future use
        fileQueue.Enqueue(selectedFileType);

        // Construct new filename ensuring it does not exceed 100 characters in total length
        string newFilename = $"{sanitizedBaseName}_{randomNumberString}{selectedFileType}";
        if (newFilename.Length > 100)
        {
            newFilename = newFilename.Substring(0, 100);
        }

        return newFilename;
    }
}

public static class ExternalDataService
{
    public static DataTable ProcessedData(byte[] data, string fileName)
    {
        // Placeholder for external service integration logic
        // This would typically involve sending the byte array to a remote processing endpoint
        // and receiving back the processed data in some form.

        // Simulating processing and returning an empty DataTable for demonstration purposes.
        return new DataTable();
    }
}
