using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class DecryptionProcessor
{
    private readonly List<(string Key, string Iv)> _keysAndIvPairs;
    private readonly int _cacheSize = 100; // Example cache size
    private readonly ConcurrentDictionary<string, (byte[] Key, byte[] Ivec)> _keyCache;
    private readonly ConcurrentDictionary<string, bool> _decryptionFailuresLog;
    private readonly TimeSpan _timeout = TimeSpan.FromSeconds(5);

    public DecryptionProcessor(List<(string Key, string Iv)> keysAndIvPairs)
    {
        _keysAndIvPairs = keysAndIvPairs ?? throw new ArgumentNullException(nameof(keysAndIvPairs));
        _keyCache = new ConcurrentDictionary<string, (byte[] Key, byte[] Ivec)>(StringComparer.OrdinalIgnoreCase);
        _decryptionFailuresLog = new ConcurrentDictionary<string, bool>();
    }

    public async Task<Dictionary<string, string>> ProcessMessagesAsync(IEnumerable<string> base64EncodedMessages)
    {
        var result = new Dictionary<string, string>();

        Parallel.ForEach(base64EncodedMessages, (base64String) =>
        {
            try
            {
                // Assuming metadata is included in the message for key/IV selection
                var (keyMetadata, ivMetadata) = ExtractKeyIvMetadata(base64String);

                // Get or load Key and IV from cache
                var keyAndIvec = _keyCache.GetOrAdd(
                    $"{keyMetadata}:{ivMetadata}",
                    k => LoadKeyAndIvec(keyMetadata, ivMetadata));

                // Decrypt message
                string decryptedMessage = DecryptMessageAsync(base64String, keyAndIvec.Key, keyAndIvec.Ivec).Result;

                result[base64String] = decryptedMessage;
            }
            catch (Exception ex)
            {
                LogFailure(base64String, ex);
                result[base64String] = null; // Mark as failed
            }
        });

        return result;
    }

    private (string KeyMetadata, string IvMetadata) ExtractKeyIvMetadata(string base64EncodedMessage)
    {
        // Implement logic to extract metadata for key/IV selection
        return ("defaultKey", "defaultIv");
    }

    private async Task<string> DecryptMessageAsync(string base64EncodedMessage, byte[] key, byte[] iv)
    {
        using (var cts = new CancellationTokenSource(_timeout))
        using (var tcs = new TaskCompletionSource<byte[]>())
        {
            Task.Run(async () =>
            {
                try
                {
                    var cipherTextBytes = Convert.FromBase64String(base64EncodedMessage);
                    using (var tripleDES = TripleDESCryptoServiceProvider.Create())
                    {
                        tripleDES.Key = key;
                        tripleDES.IV = iv;
                        tripleDES.Mode = CipherMode.CBC;

                        using (var decryptor = tripleDES.CreateDecryptor())
                        using (var ms = new MemoryStream(cipherTextBytes))
                        using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                        {
                            var plainTextBytes = new List<byte>();
                            int byteRead;

                            while ((byteRead = await cs.ReadByteAsync(cts.Token)) != -1)
                                plainTextBytes.Add((byte)byteRead);

                            tcs.SetResult(plainTextBytes.ToArray());
                        }
                    }
                }
                catch
                {
                    cts.Cancel();
                    tcs.TrySetCanceled();
                }
            }, cts.Token);

            var decryptedBytes = await tcs.Task;
            return Encoding.UTF8.GetString(decryptedBytes);
        }
    }

    private (byte[] Key, byte[] Ivec) LoadKeyAndIvec(string keyMetadata, string ivMetadata)
    {
        // Convert Base64 keys and IVs to bytes
        var keyPair = _keysAndIvPairs.Find(k => k.Key == keyMetadata && k.Iv == ivMetadata);
        return (Convert.FromBase64String(keyPair.Key), Convert.FromBase64String(keyPair.Iv));
    }

    private void LogFailure(string base64String, Exception ex)
    {
        Console.WriteLine($"[{DateTime.UtcNow}] Failure in decrypting message {base64String}: {ex.Message}");
        _decryptionFailuresLog[base64String] = true;
    }
}
```

### Key Points:
- The `ProcessMessagesAsync` method handles the parallel processing of messages.
- Uses a cache for frequently used keys and IVs to reduce memory usage and improve performance.
- Logs decryption failures with timestamps, which can be extended into rolling logs or a monitoring system.
- The decryption process is timeout-controlled to prevent long-running tasks from blocking other operations.
- This solution assumes metadata within the message indicates which key/IV pair should be used for decryption. Adjust `ExtractKeyIvMetadata` accordingly based on actual data format.

Make sure that the integration and API compatibility are verified in your specific environment, as additional adjustments might be necessary depending on system specifics.']

