using System;
using System.Collections.Concurrent;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace TextFileProcessor
{
    public interface IWordNormalizer
    {
        string Normalize(string word);
    }

    public class DefaultWordNormalizer : IWordNormalizer
    {
        public string Normalize(string word)
        {
            return word.ToLowerInvariant();
        }
    }

    public class TextFileProcessor
    {
        private readonly IWordNormalizer _normalizer;
        private readonly ConcurrentDictionary<string, int> _wordCounts;

        public TextFileProcessor(IWordNormalizer normalizer = null)
        {
            _normalizer = normalizer ?? new DefaultWordNormalizer();
            _wordCounts = new ConcurrentDictionary<string, int>();
        }

        public async Task<ConcurrentBag<(string Word, int Count)>> ProcessFileAsync(string filePath, Encoding encoding = null, bool isCompressed = false)
        {
            encoding ??= Encoding.UTF8;
            using var stream = isCompressed ? File.OpenRead(filePath) : new FileStream(filePath, FileMode.Open, FileAccess.Read);
            await ReadStreamAndProcessWordsAsync(stream, encoding).ConfigureAwait(false);

            return _wordCounts
                .OrderBy(x => x.Key)
                .ToConcurrentBag()
                .Select(x => (x.Key, x.Value))
                .ToConcurrentBag();
        }

        private async Task ReadStreamAndProcessWordsAsync(Stream stream, Encoding encoding)
        {
            var bufferSize = 4096;
            var buffer = new byte[bufferSize];
            int bytesRead;

            using var reader = new StreamReader(stream, encoding);
            while ((bytesRead = await stream.ReadAsync(buffer, 0, bufferSize)) > 0)
            {
                string textChunk = encoding.GetString(buffer, 0, bytesRead);
                Parallel.ForEach(textChunk.Split(new[] { '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries), line =>
                {
                    foreach (var word in ExtractWords(line))
                    {
                        var normalizedWord = _normalizer.Normalize(word);
                        if (!_wordCounts.TryAdd(normalizedWord, 1))
                        {
                            _wordCounts[normalizedWord]++;
                        }
                    }
                });
            }
        }

        private IEnumerable<string> ExtractWords(string line)
        {
            // Split by non-alphanumeric characters
            return System.Text.RegularExpressions.Regex.Split(line, @"\W+")
                .Where(word => !string.IsNullOrWhiteSpace(word));
        }
    }

    public static class Extensions
    {
        public static ConcurrentBag<T> ToConcurrentBag<T>(this IEnumerable<T> source)
        {
            var bag = new ConcurrentBag<T>();
            foreach (var item in source) bag.Add(item);
            return bag;
        }
    }

    // Usage example:
    // async Task ExampleUsage()
