#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int findMax(int *arr, int size) {
    if (size <= 0) return INT_MIN; // Handle empty array case
    int max = arr[0];
    for (int i = 1; i < size; i++) {
