        if (scanf("%d", &integers[i]) != 1) {
            fprintf(stderr, "Invalid integer input at position %d\n", i + 1);
            free(integers);
            free(indications);
            return;
        }
    }

    int maxInteger = findMax(integers, inputCount);
    printf("The largest integer is: %d\n", maxInteger);

    free(integers);
    free(indications);
