#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <stdalign.h>
#include <time.h>

#define MAX_ARRAY_SIZE 1024

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct {
    Node** array;
    size_t size;
    pthread_rwlock_t rwlock;
    pthread_mutex_t mutex;
    Node* lru_head;
    Node* lru_tail;
} DynamicArray;

static inline uint8_t generate_random_crc_flag() {
    return rand() % 256; // Random CRC flag between 0 and 255
}

DynamicArray* create_dynamic_array(size_t initial_size) {
    if (initial_size > MAX_ARRAY_SIZE) {
        initial_size = MAX_ARRAY_SIZE;
    }

    DynamicArray* array = malloc(sizeof(DynamicArray));
    alignas(64) Node* node_pool[MAX_ARRAY_SIZE];

    for (size_t i = 0; i < MAX_ARRAY_SIZE; ++i) {
        node_pool[i] = malloc(sizeof(Node));
        if (!node_pool[i]) {
            // Handle memory allocation failure
            for (size_t j = 0; j < i; ++j) free(node_pool[j]);
            free(array);
            return NULL;
        }
    }

    array->array = node_pool;
    array->size = initial_size;
    pthread_rwlock_init(&array->rwlock, NULL);
    pthread_mutex_init(&array->mutex, NULL);

    for (size_t i = 0; i < initial_size; ++i) {
        array->array[i]->next = &array->lru_tail;
        array->array[i]->prev = &array->lru_head;
    }

    Node* dummy_node = malloc(sizeof(Node));
    alignas(64);
    array->lru_head = dummy_node;
    array->lru_tail = dummy_node;
    array->lru_head->next = &array->lru_tail;
    array->lru_tail->prev = &array->lru_head;

    return array;
}

void free_dynamic_array(DynamicArray* array) {
    for (size_t i = 0; i < MAX_ARRAY_SIZE; ++i) {
        if (array->array[i] != NULL) {
            free(array->array[i]);
        }
    }
    pthread_rwlock_destroy(&array->rwlock);
    pthread_mutex_destroy(&array->mutex);
    free(array->lru_head);
    free(array);
}

void add_element(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_rwlock_wrlock(&array->rwlock);

    if (array->size >= MAX_ARRAY_SIZE) {
        // Evict the least recently used element
        Node* lru = array->lru_head->next;
        *lru->prev = lru->next;
        *(lru->next->prev) = lru->prev;

        size_t index_to_replace = 0; 
        for (size_t i = 1; i < MAX_ARRAY_SIZE; ++i) {
            if (array->array[i] == lru) {
                index_to_replace = i;
                break;
            }
        }

        array->array[index_to_replace] = NULL;
    }

    // Find the first free spot
    size_t index = 0;
    for (; index < MAX_ARRAY_SIZE; ++index) {
        if (array->array[index] == NULL) {
            break;
        }
    }

    Node* new_node = array->array[index];
    *new_node = (Node){ .data = element, .next = &array->lru_tail, .prev = &array->lru_head };

    *(new_node->prev) = new_node;
    *(new_node->next) = &array->lru_tail;

    array->size++;

    pthread_rwlock_unlock(&array->rwlock);
}

NFAPI_CRC_INDICATION_PDU_T* get_element(DynamicArray* array, size_t index) {
    if (index >= MAX_ARRAY_SIZE) return NULL;

    pthread_rwlock_rdlock(&array->rwlock);

    NFAPI_CRC_INDICATION_PDU_T* result = &array->array[index]->data;

    // Move accessed node to the front of LRU list
    Node* node = array->array[index];
    *(node->prev) = node->next;
    *(node->next->prev) = node->prev;

    *(node->next) = array->lru_head->next;
    *(node->prev) = &array->lru_head;
    *(array->lru_head->next) = node;
    *(array->lru_head->next->prev) = &array->lru_head;

    pthread_rwlock_unlock(&array->rwlock);

    return result;
}

void init_random() {
    srand(time(NULL));
}
```

This implementation manages a dynamic array of `NFAPI_CRC_INDICATION_PDU_T` structures with LRU eviction. It uses a combination of read-write locks and mutexes to ensure thread safety while minimizing contention, and the memory is aligned for optimal performance on modern processors. The functions provided allow adding new elements, retrieving them by index, and freeing resources safely. This setup also includes an initialization routine for random number generation used in CRC flag creation.']

