#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Mock structure definitions
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG; // Simplified for illustration
} NFAPI_CRC_INDICATION_PDU_T;

// External logging function (mock)
void log_message(const char* message) {
    printf("%s\n", message);
}

// Dynamic array structure with mutex for thread safety
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} CRC_Indication_Array;

// Initialize dynamic array
void init_crc_array(CRC_Indication_Array *arr) {
    arr->size = 0;
    arr->capacity = 10; // Initial capacity
    arr->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(arr->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!arr->array) {
        log_message("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&arr->lock, NULL);
}

// Resize array when needed
void resize_crc_array(CRC_Indication_Array *arr) {
    size_t new_capacity = arr->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(arr->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        log_message("Memory reallocation failed");
        exit(EXIT_FAILURE);
    }
    arr->array = new_array;
    arr->capacity = new_capacity;
}

// Add a new element to the array
void add_crc_pdu(CRC_Indication_Array *arr, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&arr->lock);
    if (arr->size >= arr->capacity) {
        resize_crc_array(arr);
    }
    arr->array[arr->size++] = pdu;
    log_message("Added new CRC PDU");
    pthread_mutex_unlock(&arr->lock);
}

// Retrieve an element by index
NFAPI_CRC_INDICATION_PDU_T get_crc_pdu(CRC_Indication_Array *arr, size_t index) {
    pthread_mutex_lock(&arr->lock);
    NFAPI_CRC_INDICATION_PDU_T pdu = {0};
    if (index < arr->size) {
        pdu = arr->array[index];
    }
    pthread_mutex_unlock(&arr->lock);
    return pdu;
}

// Clean up resources
void free_crc_array(CRC_Indication_Array *arr) {
    pthread_mutex_lock(&arr->lock);
    free(arr->array);
    arr->array = NULL;
    arr->size = 0;
    arr->capacity = 0;
    pthread_mutex_unlock(&arr->lock);
    pthread_mutex_destroy(&arr->lock);
    log_message("Resources freed");
}

// Generate a random CRC flag (simplified)
unsigned char generate_random_crc_flag() {
    return rand() % 256; // Random byte
}

// Example usage
int main() {
    srand(time(NULL)); // Seed for randomness

    CRC_Indication_Array crc_array;
    init_crc_array(&crc_array);

    NFAPI_CRC_INDICATION_PDU_T pdu = {1, 100, generate_random_crc_flag()};
    add_crc_pdu(&crc_array, pdu);

    NFAPI_CRC_INDICATION_PDU_T retrieved_pdu = get_crc_pdu(&crc_array, 0);
    printf("Retrieved PDU: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_FLAG=0x%X\n",
           retrieved_pdu.RX_UE_INFORMATION_TAG, retrieved_pdu.RNTI, retrieved_pdu.CRC_INDICATION_REL8_TAG);

    free_crc_array(&crc_array);
    return 0;
}
