#include <iostream>
#include <vector>
#include <mutex>
#include <random>
#include <chrono>
#include <thread>
#include <cstring>

namespace MemoryManager {

    struct Record {
        int value;
    };

    class Allocator {
    private:
        static std::mt19937_64 rng;
        static const size_t CACHE_SIZE = 1024 * 1024; // Example cache size
        static std::vector<char> memoryPool;
        static std::mutex mtx;

        static void log(const std::string &message) {
            auto now = std::chrono::system_clock::now();
            auto now_c = std::chrono::system_clock::to_time_t(now);
            std::cout << std::ctime(&now_c) << message << std::endl;
        }

    public:
        Allocator() {
            memoryPool.resize(CACHE_SIZE, 0);
            log("Allocator initialized");
        }

        ~Allocator() {
            log("Allocator destroyed");
        }

        long* allocateLong(size_t count) {
            if (count * sizeof(long) > memoryPool.size()) {
                log("Allocation error: Out of memory for longs");
                return nullptr;
            }
            std::lock_guard<std::mutex> lock(mtx);
            long* ptr = reinterpret_cast<long*>(memoryPool.data());
            memoryPool.erase(memoryPool.begin(), memoryPool.begin() + count * sizeof(long));
            log("Allocated " + std::to_string(count) + " longs");
            return ptr;
        }

        int* allocateInt(size_t count) {
            if (count * sizeof(int) > memoryPool.size()) {
                log("Allocation error: Out of memory for ints");
                return nullptr;
            }
            std::lock_guard<std::mutex> lock(mtx);
            int* ptr = reinterpret_cast<int*>(memoryPool.data());
            memoryPool.erase(memoryPool.begin(), memoryPool.begin() + count * sizeof(int));
            log("Allocated " + std::to_string(count) + " ints");
            return ptr;
        }

        Record* allocateRecords(size_t count) {
            if (count * sizeof(Record) > memoryPool.size()) {
                log("Allocation error: Out of memory for records");
                return nullptr;
            }
            std::lock_guard<std::mutex> lock(mtx);
            Record* ptr = reinterpret_cast<Record*>(memoryPool.data());
            memoryPool.erase(memoryPool.begin(), memoryPool.begin() + count * sizeof(Record));
            log("Allocated " + std::to_string(count) + " records");
            return ptr;
        }

        static int getRandom(int min, int max) {
            std::lock_guard<std::mutex> lock(mtx);
            std::uniform_int_distribution<int> dist(min, max);
            return dist(rng);
        }
    };

    std::mt19937_64 Allocator::rng{std::random_device{}()};
    std::vector<char> Allocator::memoryPool;
    std::mutex Allocator::mtx;

}

int main() {
    using namespace MemoryManager;

    Allocator allocator;

    long* longs = allocator.allocateLong(1000);
    int* keys = allocator.allocateInt(500);
    Record* records = allocator.allocateRecords(200);

    if (longs && keys && records) {
        std::cout << "Random value: " << Allocator::getRandom(1, 100) << std::endl;
    }

    return 0;
}
