void initialize_nfa_structures(int n) {
    // Dynamically allocate memory for the list
    NFAPI_CRC_INDICATION_PDU_T *structures = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!structures) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

