        do {
            rnti = rand() % 10000 + 1; // Generate a random RNTI
        } while ((i > 0 && rnti == structures[i - 1].RNTI) || 
                 (i < n - 1 && rnti == tags[(i + 1) % n])); // Ensure uniqueness

        structures[i].RNTI = rnti;

        structures[i].CRC_INDICATION_REL8_TAG = rand() % 256; // Random CRC tag
        structures[i].CRCFLAG = rand() & 1; // Randomly set CRC flag to 0 or 1
    }

