        fprintf(stderr, "Invalid number of integers\n");
        free(structures);
        return;
    }

    int *integers = (int *)malloc(num_integers * sizeof(int));
    if (!integers) {
        fprintf(stderr, "Memory allocation failed\n");
        free(structures);
        return;
    }

    printf("Enter the integers:\n");
    for (int i = 0; i < num_integers; ++i) {
        scanf("%d", &integers[i]);
