            if ((structures[i].RX_UE_INFORMATION_TAG == structures[j].RX_UE_INFORMATION_TAG &&
                 structures[i].RNTI == structures[j].RNTI)) {
                fprintf(stderr, "Duplicate RX_UE_INFORMATION_TAG and RNTI found\n");
                free(structures);
                free(integers);
                return;
            }
        }
    }

    printf("The largest integer is: %d\n", largest_integer);

