    pthread_mutex_t access_mutex;
    int http_client_initialized;
} NFAPIManager;

void initializeMemoryPool(MemoryPool* pool) {
    for (size_t i = 0; i < INITIAL_POOL_SIZE; ++i) {
        pool->pool[i] = NULL;
    }
    pool->count = 0;
    pthread_mutex_init(&pool->mutex, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* allocateFromPool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->count < INITIAL_POOL_SIZE) {
        NFAPI_CRC_INDICATION_PDU_T* new_element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pool->pool[pool->count++] = new_element;
        pthread_mutex_unlock(&pool->mutex);
        return new_element;
    }
    pthread_mutex_unlock(&pool->mutex);
    return NULL; // Pool full
}

void freeToPool(MemoryPool* pool, NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&pool->mutex);
    for (size_t i = 0; i < INITIAL_POOL_SIZE; ++i) {
        if (pool->pool[i] == element) {
            free(element);
            pool->pool[i] = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&pool->mutex);
}

void initializeHTTPClient(void* manager) {
