        nfa_api_manager->http_client_initialized = 1;
    }
}

void initializeNFAPIManager(NFAPIManager* manager, MemoryPool* pool) {
    manager->mem_pool = pool;
    pthread_mutex_init(&manager->access_mutex, NULL);
    pthread_once(&pool->init_done, initializeMemoryPool);
    initializeHTTPClient(manager);
}

void addElement(NFAPIManager* manager, int tag, int rnti) {
    pthread_mutex_lock(&manager->access_mutex);
    NFAPI_CRC_INDICATION_PDU_T* element = allocateFromPool(manager->mem_pool);
    if (element) {
        element->RX_UE_INFORMATION_TAG = tag;
        element->RNTI = rnti;
        srand(time(NULL));
        element->CRC_INDICATION_REL8_TAG = rand() & 0x1; // Random CRC flag
        printf("Added new element with RX UE Tag: %d\n", tag);
    } else {
        printf("Failed to add new element. Pool might be full.\n");
    }
    pthread_mutex_unlock(&manager->access_mutex);
}

NFAPI_CRC_INDICATION_PDU_T* getElement(NFAPIManager* manager, size_t index) {
    pthread_mutex_lock(&manager->access_mutex);
    NFAPI_CRC_INDICATION_PDU_T* element = NULL;
    if (index < manager->mem_pool->count) {
        element = manager->mem_pool->pool[index];
    }
    pthread_mutex_unlock(&manager->access_mutex);
    return element;
}

void cleanupNFAPIManager(NFAPIManager* manager) {
    pthread_mutex_lock(&manager->access_mutex);
    for (size_t i = 0; i < manager->mem_pool->count; ++i) {
        if (manager->mem_pool->pool[i]) {
            freeToPool(manager->mem_pool, manager->mem_pool->pool[i]);
