#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>

#define MAX_SYSTEM_MEMORY 1024 * 1024 * 512 // Example: 512 MB limit

typedef struct {
    int value;
} record;

typedef struct CacheNode {
    record* record_ptr;
    struct CacheNode* next;
} CacheNode;

typedef struct {
    CacheNode* head;
    pthread_mutex_t lock;
} RecordCache;

static const uint32_t CACHE_SIZE = 10; // Example cache size
static const int RNG_SEED = 42;        // Seed for reproducible random generation

pthread_mutex_t memory_lock;
RecordCache record_cache;

void initialize_cache(RecordCache* cache) {
    pthread_mutex_init(&cache->lock, NULL);
    cache->head = NULL;
}

record* allocate_records(size_t count, int min_val, int max_val, uint32_t seed) {
    if (count == 0 || min_val > max_val) return NULL;

    size_t total_size = sizeof(record) * count;
    if (total_size > MAX_SYSTEM_MEMORY) return NULL;

    record* records = malloc(total_size);
    if (!records) return NULL;

    srand(seed);
    for (size_t i = 0; i < count; ++i) {
        records[i].value = min_val + rand() % (max_val - min_val + 1);
    }

    pthread_mutex_lock(&memory_lock);

    // Simple caching mechanism: append to cache
    CacheNode* new_node = malloc(sizeof(CacheNode));
    if (!new_node) {
        free(records);
        pthread_mutex_unlock(&memory_lock);
        return NULL;
    }

    new_node->record_ptr = &records[i];
    new_node->next = record_cache.head;
    record_cache.head = new_node;

    pthread_mutex_unlock(&memory_lock);

    return records;
}

void deallocate_records(record* records, size_t count) {
    pthread_mutex_lock(&memory_lock);

    // Remove from cache
    CacheNode *current = record_cache.head, *prev = NULL;
    while (current) {
        if (current->record_ptr >= records && current->record_ptr < records + count) {
            if (prev) prev->next = current->next;
            else record_cache.head = current->next;

            free(current);
            current = prev ? record_cache.head : current->next;
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&memory_lock);

    free(records);
}

int find(int parent[], int i) {
    if (parent[i] != i)
        parent[i] = find(parent, parent[i]);
    return parent[i];
}

void union_set(int parent[], int rank[], int x, int y) {
    int rootX = find(parent, x);
    int rootY = find(parent, y);

    if (rootX != rootY) {
        if (rank[rootX] > rank[rootY])
            parent[rootY] = rootX;
        else if (rank[rootX] < rank[rootY])
            parent[rootX] = rootY;
        else {
            parent[rootY] = rootX;
            rank[rootX]++;
        }
    }
}

int find_disjoint_pairs(int* arr, size_t n) {
    if (!arr || n < 2) return -1;

    int* parent = malloc(n * sizeof(int));
    int* rank = calloc(n, sizeof(int));

    for (size_t i = 0; i < n; ++i)
        parent[i] = i;

    int disjoint_count = 0;
    struct timespec start_time, end_time;

    for (size_t i = 0; i < n - 1; ++i) {
        clock_gettime(CLOCK_MONOTONIC, &start_time);

        if (find(parent, arr[i]) != find(parent, arr[i + 1])) {
            union_set(parent, rank, arr[i], arr[i + 1]);
            disjoint_count++;
        }

        clock_gettime(CLOCK_MONOTONIC, &end_time);

        double elapsed = end_time.tv_sec - start_time.tv_sec +
                         (end_time.tv_nsec - start_time.tv_nsec) / 1e9;
        printf("Checking pair %d-%d took %.6f milliseconds\n",
               arr[i], arr[i + 1], elapsed * 1000);
    }

    free(parent);
    free(rank);

    return disjoint_count;
}

int main() {
    initialize_cache(&record_cache);
    pthread_mutex_init(&memory_lock, NULL);

    size_t long_array_len = 10; // Example length
    size_t int_array_len = 10;  // Example length
    size_t record_count = 5;    // Example number of records

    if (long_array_len * sizeof(long) + int_array_len * sizeof(int) +
        record_count * sizeof(record) > MAX_SYSTEM_MEMORY) {
        fprintf(stderr, "Memory allocation exceeds system limits.\n");
        return -1;
    }

    long* long_offset = malloc(long_array_len * sizeof(long));
    int* keys = malloc(int_array_len * sizeof(int));

    if (!long_offset || !keys) {
        perror("Failed to allocate memory for arrays.");
        free(long_offset);
        free(keys);
        return -1;
    }

    record* records = allocate_records(record_count, 0, 100, RNG_SEED);
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records.\n");
        deallocate_arrays(long_offset, keys);
        return -1;
    }

    int disjoint_pairs = find_disjoint_pairs((int[]){3, 8, 2, 5, 1}, 5);

    printf("Number of disjoint pairs: %d\n", disjoint_pairs);

    deallocate_records(records, record_count);
    deallocate_arrays(long_offset, keys);

    pthread_mutex_destroy(&memory_lock);
    return 0;
}

void deallocate_arrays(void* arr1, void* arr2) {
    if (arr1) free(arr1);
    if (arr2) free(arr2);
}
