['Below is a C function named `handleDataPacketQueue` that processes packets from a network socket, ensuring no duplicate packet IDs are added to the queue and validating packet integrity using checksums:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>

#define MAX_PACKET_ID 0xFFFFFFFF

typedef struct {
    uint32_t packetID;
    char sourceIP[16];
    char destinationIP[16];
    size_t payloadSize;
    time_t timestamp;
    char *payload; // Assuming payload is a string for simplicity
} DataPacket;

typedef struct Node {
    DataPacket data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
} PacketQueue;

unsigned int hash(uint32_t packetID) {
    return packetID % 1024; // Simple modulo-based hash function
}

bool is_duplicate(PacketQueue *queue, uint32_t packetID) {
    unsigned int index = hash(packetID);
    for (Node* current = queue->head; current != NULL; current = current->next) {
        if (current->data.packetID == packetID) {
            return true;
        }
    }
    return false;
}

bool validate_checksum(const char *payload, size_t payloadSize) {
    // Simple checksum algorithm for demonstration
    uint32_t checksum = 0;
    for (size_t i = 0; i < payloadSize; ++i) {
        checksum += (uint8_t)payload[i];
    }
    return checksum % 256 == 0; // Example condition
}

void log_message(const char* message) {
    printf("%s\n", message);
}

PacketQueue* create_queue() {
    PacketQueue* queue = (PacketQueue*)malloc(sizeof(PacketQueue));
    if (!queue) {
        log_message("Failed to allocate memory for packet queue");
        return NULL;
    }
    queue->head = NULL;
    return queue;
}

void enqueue_packet(PacketQueue *queue, DataPacket data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        log_message("Failed to allocate memory for new node");
        return;
    }

    newNode->data = data;
    newNode->next = queue->head;
    queue->head = newNode;
}

void handleDataPacketQueue(int socketFD) {
    PacketQueue* packetQueue = create_queue();
    if (!packetQueue) return;

    char buffer[1024]; // Buffer for reading from the socket
    while (true) { // Assuming some condition to break this loop in real-world scenarios
        ssize_t bytesRead = read(socketFD, buffer, sizeof(buffer));
        if (bytesRead <= 0) {
            log_message("Error reading from socket or connection closed");
            break;
        }

        DataPacket packet;
        memcpy(&packet.packetID, buffer, sizeof(packet.packetID));
        strncpy(packet.sourceIP, buffer + sizeof(packet.packetID), sizeof(packet.sourceIP) - 1);
        strncpy(packet.destinationIP, buffer + sizeof(packet.packetID) + sizeof(packet.sourceIP), sizeof(packet.destinationIP) - 1);
        memcpy(&packet.payloadSize, buffer + sizeof(packet.packetID) + sizeof(packet.sourceIP) + sizeof(packet.destinationIP), sizeof(packet.payloadSize));
        packet.timestamp = *((time_t*)(buffer + sizeof(packet.packetID) + sizeof(packet.sourceIP) + sizeof(packet.destinationIP) + sizeof(packet.payloadSize)));

        char* payloadStart = buffer + sizeof(packet.packetID) + sizeof(packet.sourceIP) + sizeof(packet.destinationIP) + sizeof(packet.payloadSize);
        packet.payload = (char*)malloc(packet.payloadSize);
        if (!packet.payload) {
            log_message("Failed to allocate memory for packet payload");
            continue;
        }
        memcpy(packet.payload, payloadStart, packet.payloadSize);

        // Check for duplicate packet ID
        if (is_duplicate(packetQueue, packet.packetID)) {
            free(packet.payload);
            log_message("Duplicate packet ID detected and discarded");
            continue;
        }

        // Validate checksum
        if (!validate_checksum(packet.payload, packet.payloadSize)) {
            free(packet.payload);
            log_message("Packet checksum validation failed and discarded");
            continue;
        }

        enqueue_packet(packetQueue, packet);

        // Example cleanup - in real-world scenarios, you'd have conditions to remove processed packets
    }

    // Cleanup
    while (packetQueue->head) {
        Node* temp = packetQueue->head;
        packetQueue->head = packetQueue->head->next;
        free(temp->data.payload);
        free(temp);
    }
    free(packetQueue);
}
```

### Key Points:
- **Duplicate Detection**: Uses a simple linked list to check for duplicates. A hash table could be more efficient but requires additional memory.
- **Checksum Validation**: Implements a basic checksum algorithm.
- **Error Handling and Logging**: Logs messages for errors like failed reads or duplicate packets.
- **Memory Management**: Allocates memory for each packet and ensures it is freed appropriately to prevent leaks.
- **Scalability Considerations**: The function processes packets in a loop, which can be adapted for asynchronous I/O to improve scalability.']

