#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_EVENTS 1000000

typedef struct Event {
    time_t timestamp;
    unsigned int event_id;
    char *description;
} Event;

typedef struct LogSystem {
    size_t count;
    size_t capacity;
    Event **events; // Array of pointers to Events
    pthread_mutex_t lock;
} LogSystem;

LogSystem* create_log_system(size_t initial_capacity) {
    LogSystem *log_sys = (LogSystem *)malloc(sizeof(LogSystem));
    log_sys->count = 0;
    log_sys->capacity = initial_capacity;
    log_sys->events = (Event **)calloc(initial_capacity, sizeof(Event *));
    pthread_mutex_init(&log_sys->lock, NULL);
    return log_sys;
}

void destroy_log_system(LogSystem *log_sys) {
    for (size_t i = 0; i < log_sys->count; ++i) {
        free(log_sys->events[i]->description);
        free(log_sys->events[i]);
    }
    free(log_sys->events);
    pthread_mutex_destroy(&log_sys->lock);
    free(log_sys);
}

int add_event(LogSystem *log_sys, Event *event) {
    pthread_mutex_lock(&log_sys->lock);

    if (log_sys->count >= log_sys->capacity) {
        size_t new_capacity = log_sys->capacity * 2;
        Event **new_events = (Event **)realloc(log_sys->events, new_capacity * sizeof(Event *));
        if (!new_events) {
            pthread_mutex_unlock(&log_sys->lock);
            return -1; // Memory allocation failed
        }
        for (size_t i = log_sys->capacity; i < new_capacity; ++i) {
            new_events[i] = NULL;
        }
        log_sys->events = new_events;
        log_sys->capacity = new_capacity;
    }

    log_sys->events[log_sys->count++] = event;

    pthread_mutex_unlock(&log_sys->lock);
    return 0;
}

Event* get_event(LogSystem *log_sys, size_t index) {
    if (index >= log_sys->count) {
        return NULL; // Index out of bounds
    }

    pthread_mutex_lock(&log_sys->lock);

    Event *event = log_sys->events[index];

    pthread_mutex_unlock(&log_sys->lock);
    return event;
}

Event* create_event(time_t timestamp, unsigned int event_id, const char *description) {
    Event *event = (Event *)malloc(sizeof(Event));
    if (!event) {
        return NULL; // Memory allocation failed
    }
    event->timestamp = timestamp;
    event->event_id = event_id;
    event->description = strdup(description);
    if (!event->description) {
        free(event);
        return NULL; // Memory allocation failed
    }
    return event;
}

void sync_with_logging_service(LogSystem *log_sys) {
    pthread_mutex_lock(&log_sys->lock);

    for (size_t i = 0; i < log_sys->count; ++i) {
        // Simulate synchronization with external logging service
        printf("Syncing Event ID: %u, Description: %s\n", 
               log_sys->events[i]->event_id, log_sys->events[i]->description);
    }

    pthread_mutex_unlock(&log_sys->lock);
}

int main() {
    LogSystem *log_sys = create_log_system(100);

    // Simulate adding events
    for (unsigned int i = 0; i < 10; ++i) {
        time_t now = time(NULL);
        Event *event = create_event(now, i, "Event Description");
        if (add_event(log_sys, event)) {
            fprintf(stderr, "Failed to add event\n");
        }
    }

    // Simulate retrieval and synchronization
    sync_with_logging_service(log_sys);

    destroy_log_system(log_sys);
    return 0;
}
```

### Key Points:
- **Thread Safety**: The implementation uses a mutex (`pthread_mutex_t`) for synchronizing access to the shared data structure.
- **Dynamic Resizing**: The event array is dynamically resized as needed, doubling its capacity when full.
- **Performance Optimization**: Using an array of pointers helps minimize memory fragmentation and ensures efficient insertion at the end.
- **Memory Management**: Careful allocation and deallocation are used to prevent leaks.
- **Concurrency**: Ensures safe concurrent access using mutex locks.']

