pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void* execute_command(void *arg) {
    char* command = (char*) arg;

    if (fork() == 0) { // Child process
        execlp("/bin/sh", "sh", "-c", command, NULL);
        exit(EXIT_FAILURE); // Exit child if exec fails
    }
    pthread_exit(NULL); // Parent returns after fork/exec
}

int create_nfa_pi_array(NFAPI_CRC_INDICATION_PDU_T** array) {
    *array = (NFAPI_CRC_INDICATION_PDU_T*) malloc(NUM_STRUCTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*array == NULL) return 0;

    for (int i = 0; i < NUM_STRUCTS; ++i) {
        pthread_mutex_lock(&mutex);

        // Populate structure
        (*array)[i].RX_UE_INFORMATION_TAG = i + 1;
        (*array)[i].RNTI = rand() % 10000 + 1; // Example RNTI generation
        (*array)[i].CRC_INDICATION_REL8_TAG = (rand() % ((1U << 16) - 1)) | (1U << 15); // Ensuring specific bit-width

        pthread_mutex_unlock(&mutex);
    }

    return 1;
}

int execute_user_command(char* command) {
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, execute_command, (void*)command)) {
        fprintf(stderr, "Error creating thread\n");
        return 0;
    }
    pthread_detach(thread_id); // Detach to minimize impact on main process
    return 1;
}

int generate_and_execute(char* command) {
    NFAPI_CRC_INDICATION_PDU_T* array = NULL;

    if (!create_nfa_pi_array(&array)) {
        fprintf(stderr, "Failed to create array\n");
        return 0;
    }

    if (!execute_user_command(command)) {
        free(array);
        fprintf(stderr, "Command execution failed\n");
        return 0;
    }

    // Logging success
    printf("Array created and command executed successfully.\n");

    free(array); // Clean up
    return 1;
}

int main() {
    char* user_command = "echo 'Executing background command'";
    int result = generate_and_execute(user_command);
    if (result) {
        printf("Operation completed successfully.\n");
    } else {
        fprintf(stderr, "Operation failed.\n");
    }

    pthread_mutex_destroy(&mutex);
    pthread_cond_destroy(&cond);

    return 0;
}
