#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
import "logging_framework.h"  // Assume this is your existing logging framework

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;                   // Ensure this is set to a valid value (non-zero)
    unsigned short CRC_INDICATION_REL8_TAG; // Randomly generated CRC flag
} NFAPI_CRC_INDICATION_PDU_T;

// Define the dynamic array structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray *arr = malloc(sizeof(DynamicArray));
    if (!arr) return NULL;

    arr->array = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    arr->capacity = initial_capacity;
    arr->size = 0;

    pthread_mutex_init(&arr->lock, NULL);
    pthread_cond_init(&arr->cond_var, NULL);

    LOG_INFO("Dynamic array created with initial capacity %zu", initial_capacity);

    return arr;
}

void free_dynamic_array(DynamicArray *arr) {
    if (!arr) return;

    pthread_mutex_lock(&arr->lock);
    free(arr->array);
    pthread_mutex_unlock(&arr->lock);

    pthread_mutex_destroy(&arr->lock);
    pthread_cond_destroy(&arr->cond_var);

    free(arr);
    LOG_INFO("Dynamic array freed");
}

void ensure_capacity(DynamicArray *arr, size_t required_capacity) {
    if (required_capacity <= arr->capacity) return;

    size_t new_capacity = arr->capacity * 2;
    while (new_capacity < required_capacity) new_capacity *= 2;

    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(arr->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        LOG_ERROR("Failed to reallocate memory");
        return;
    }

    arr->capacity = new_capacity;
    LOG_INFO("Array capacity increased to %zu", new_capacity);
}

void add_entry(DynamicArray *arr, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&arr->lock);

    ensure_capacity(arr, arr->size + 1);
    if (arr->size >= arr->capacity) {
        LOG_ERROR("Buffer overflow: could not add entry");
        pthread_mutex_unlock(&arr->lock);
        return;
    }

    arr->array[arr->size] = entry;
    arr->size++;
    LOG_INFO("Added an entry, total size is now %zu", arr->size);

    pthread_cond_signal(&arr->cond_var);
    pthread_mutex_unlock(&arr->lock);
}

void remove_entry(DynamicArray *arr) {
    pthread_mutex_lock(&arr->lock);

    if (arr->size == 0) {
        LOG_ERROR("Buffer underflow: no entry to remove");
        pthread_mutex_unlock(&arr->lock);
        return;
    }

    arr->array[0] = arr->array[arr->size - 1];
    arr->size--;
    LOG_INFO("Removed an entry, total size is now %zu", arr->size);

    pthread_cond_signal(&arr->cond_var);
    pthread_mutex_unlock(&arr->lock);
}

void* integrity_check(void *arg) {
    DynamicArray *arr = (DynamicArray *)arg;
    while (1) {
        sleep(10);  // Run every 10 seconds

        pthread_mutex_lock(&arr->lock);

        for (size_t i = 0; i < arr->size; ++i) {
            if (arr->array[i].RNTI == 0) {
                LOG_ERROR("Integrity issue detected at index %zu", i);
                // Trigger reinitialization or other corrective action
                break;
            }
        }

        pthread_mutex_unlock(&arr->lock);
    }

    return NULL;
}

int main() {
    DynamicArray *array = create_dynamic_array(1024);

    // Start the integrity check thread
    pthread_t checker_thread;
    if (pthread_create(&checker_thread, NULL, integrity_check, array) != 0) {
        LOG_ERROR("Failed to start integrity check thread");
    }

    // Example usage: add and remove entries
    NFAPI_CRC_INDICATION_PDU_T example_entry = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 12345, .CRC_INDICATION_REL8_TAG = rand() };
    add_entry(array, example_entry);

    // Clean up resources
    free_dynamic_array(array);

    pthread_cancel(checker_thread);
    pthread_join(checker_thread, NULL);

    return 0;
}
```

