```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint8_t CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define INITIAL_CAPACITY 10
#define MAX_CAPACITY 100

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} CRCList;

CRCList* create_crc_list() {
    CRCList *list = (CRCList*)malloc(sizeof(CRCList));
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size = 0;
    list->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void resize_crc_list(CRCList *list) {
    size_t new_capacity = (list->capacity < MAX_CAPACITY) ? list->capacity * 2 : MAX_CAPACITY;
    NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_data) {
        list->data = new_data;
        list->capacity = new_capacity;
    }
}

void add_crc_pdu(CRCList *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->mutex);
    if (list->size >= list->capacity) {
        resize_crc_list(list);
    }
    if (list->size < list->capacity) {
        list->data[list->size++] = pdu;
    }
    pthread_mutex_unlock(&list->mutex);
}

size_t serialize_crc_list(const CRCList *list, uint8_t **buffer) {
    size_t buffer_size = sizeof(size_t) + list->size * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    *buffer = (uint8_t*)malloc(buffer_size);

    if (*buffer) {
        memcpy(*buffer, &list->size, sizeof(size_t));
        memcpy(*buffer + sizeof(size_t), list->data, list->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    return buffer_size;
}

void deserialize_crc_list(CRCList *list, const uint8_t *buffer) {
    pthread_mutex_lock(&list->mutex);
    size_t size;
    memcpy(&size, buffer, sizeof(size_t));

    if (size > list->capacity) {
        free(list->data);
        list->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list->capacity = size;
    }

    memcpy(list->data, buffer + sizeof(size_t), size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size = size;
    pthread_mutex_unlock(&list->mutex);
}

void free_crc_list(CRCList *list) {
    pthread_mutex_destroy(&list->mutex);
    free(list->data);
    free(list);
}

int main() {
    CRCList *crc_list = create_crc_list();

    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = 1234;
    pdu.RNTI = 5678;
    pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRCFLAG

    add_crc_pdu(crc_list, pdu);

    uint8_t *buffer;
    size_t buffer_size = serialize_crc_list(crc_list, &buffer);

    if (buffer) {
        deserialize_crc_list(crc_list, buffer);
        free(buffer);
    }

    free_crc_list(crc_list);
    return 0;
}
```

