// Function to initialize OpenSSL and set error strings
void init_crypto() {
    if (!RAND_load_file("/dev/urandom", 256)) {
        fprintf(stderr, "Error initializing random number generator: %s\n", ERR_error_string(ERR_get_error(), NULL));
        exit(EXIT_FAILURE);
    }
