```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
    float weight;
    char *name;
} record;

typedef struct CacheNode {
    record *data;
    struct CacheNode *prev, *next;
} CacheNode;

typedef struct {
    CacheNode *head, *tail;
    size_t capacity;
    size_t size;
    pthread_rwlock_t lock;
} LRUCache;

void log_event(const char *event) {
    printf("[LOG] %s\n", event);
}

int resize_array(void **array, size_t current_size, size_t new_size, size_t element_size) {
    void *new_array = realloc(*array, new_size * element_size);
    if (!new_array) return -1;
    *array = new_array;
    return 0;
}

record* allocate_records(size_t num_records) {
    record *records = malloc(num_records * sizeof(record));
    if (!records) return NULL;

    for (size_t i = 0; i < num_records; ++i) {
        records[i].name = strdup("default");
        if (!records[i].name) {
            free(records);
            return NULL;
        }
    }
    log_event("Allocated record array.");
    return records;
}

void deallocate_records(record *records, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) {
        free(records[i].name);
    }
    free(records);
    log_event("Deallocated record array.");
}

void initialize_data(long *offsets, int *keys, float *weights, size_t length, unsigned int seed) {
    srand(seed);
    for (size_t i = 0; i < length; ++i) {
        offsets[i] = rand();
        keys[i] = rand() % 100;
        weights[i] = static_cast<float>(rand()) / RAND_MAX;
    }
}

LRUCache* create_cache(size_t capacity) {
    LRUCache *cache = malloc(sizeof(LRUCache));
    if (!cache) return NULL;

    cache->head = cache->tail = NULL;
    cache->capacity = capacity;
    cache->size = 0;
    pthread_rwlock_init(&cache->lock, NULL);
    log_event("Created LRU Cache.");
    return cache;
}

void destroy_cache(LRUCache *cache) {
    pthread_rwlock_wrlock(&cache->lock);

    CacheNode *current = cache->head;
    while (current) {
        CacheNode *next = current->next;
        free(current);
        current = next;
    }

    pthread_rwlock_unlock(&cache->lock);
    pthread_rwlock_destroy(&cache->lock);
    free(cache);
    log_event("Destroyed LRU Cache.");
}

void access_cache(LRUCache *cache, record *data) {
    pthread_rwlock_wrlock(&cache->lock);

    if (cache->size == cache->capacity) {
        CacheNode *to_remove = cache->head;
        cache->head = to_remove->next;
        free(to_remove);
        cache->size--;
    }

    CacheNode *new_node = malloc(sizeof(CacheNode));
    new_node->data = data;
    new_node->prev = NULL;
    new_node->next = cache->head;

    if (cache->head) {
        cache->head->prev = new_node;
    }
    cache->head = new_node;

    if (!cache->tail) {
        cache->tail = new_node;
    }

    pthread_rwlock_unlock(&cache->lock);
}

void manage_memory(size_t offset_length, size_t key_length, size_t weight_length, size_t record_count, unsigned int seed, size_t initial_offset_size, size_t initial_key_size, size_t initial_weight_size) {
    long *offsets = malloc(initial_offset_size * sizeof(long));
    int *keys = malloc(initial_key_size * sizeof(int));
    float *weights = malloc(initial_weight_size * sizeof(float));

    if (!offsets || !keys || !weights) {
        log_event("Failed to allocate initial memory.");
        return;
    }

    size_t final_offset_length = (offset_length > initial_offset_size) ? offset_length : initial_offset_size;
    size_t final_key_length = (key_length > initial_key_size) ? key_length : initial_key_size;
    size_t final_weight_length = (weight_length > initial_weight_size) ? weight_length : initial_weight_size;

    if (resize_array((void**)&offsets, initial_offset_size, final_offset_length, sizeof(long)) < 0 ||
        resize_array((void**)&keys, initial_key_size, final_key_length, sizeof(int)) < 0 ||
        resize_array((void**)&weights, initial_weight_size, final_weight_length, sizeof(float)) < 0) {

        log_event("Failed to resize memory.");
        free(offsets);
        free(keys);
        free(weights);
        return;
    }

    initialize_data(offsets, keys, weights, offset_length > key_length ? offset_length : key_length > weight_length ? key_length : weight_length, seed);

    record *records = allocate_records(record_count);
    if (!records) {
        log_event("Failed to allocate records.");
        free(offsets);
        free(keys);
        free(weights);
        return;
    }

    LRUCache *cache = create_cache(10);
    if (!cache) {
        deallocate_records(records, record_count);
        log_event("Failed to create cache.");
        free(offsets);
        free(keys);
        free(weights);
        return;
    }

    for (size_t i = 0; i < record_count; ++i) {
        records[i].value = rand() % 1000;
        access_cache(cache, &records[i]);
    }

    deallocate_records(records, record_count);
    destroy_cache(cache);
    free(offsets);
    free(keys);
    free(weights);
}
```

