record* allocate_memory(size_t num_offsets, size_t num_keys, size_t num_records,
                        int min_value, int max_value, unsigned long seed,
                        errorHandler_t *errorHandler) {

    if (errorHandler == NULL || errorHandler->handler == NULL)
        errorHandler = &(errorHandler_t){defaultErrorHandler};

    // Seed the random number generator
    srand(seed);

    // Allocate memory for offsets and keys
    long *offsets = calloc(num_offsets, sizeof(long));
    int *keys = malloc(num_keys * sizeof(int));

