    while (scanf("%d", &number) == 1) {
        if (count >= capacity) {
            capacity *= 2;
            numbers = (int *)realloc(numbers, capacity * sizeof(int));
            if (!numbers) return -1; // Reallocation failed
        }
        numbers[count++] = number;

        // Update largest number found
        if (number > largest) {
            largest = number;
        }
    }

    // Handle incomplete input or corrupted data
    if (count == 0) {
        free(numbers);
        return -1; // No valid integers were read
    }

    *pduList = (NFAPI_CRC_INDICATION_PDU_T *)malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*pduList) {
        free(numbers);
        return -1; // Allocation failed
