        (*pduList)[i].RNTI = numbers[i] + 100; // Example modification
        (*pduList)[i].CRC_INDICATION_REL8_TAG = numbers[i] + 200; // Example modification
        (*pduList)[i].CRCFLAG = rand() % 2; // Randomly set to 0 or 1
    }

    *listSize = count;

    free(numbers);
    return largest;
