['Below is a C code example that meets the requirements described in your task:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    double frequency;
    int signal_strength;
    int noise_level;
} ChannelMeasurement;

typedef struct {
    time_t timestamp;
    int sequence_number;
    size_t num_measurements;
    ChannelMeasurement *measurements;
} FrameInfo;

typedef struct {
    pthread_mutex_t lock;
    FrameInfo **frames;
    size_t frame_count;
    void (*log_error)(const char *);
    void (*log_event)(const char *);
} FrameManager;

void error_logger(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

void event_logger(const char *message) {
    printf("Event: %s\n", message);
}

FrameInfo* create_frame(size_t num_measurements) {
    FrameInfo *frame = malloc(sizeof(FrameInfo));
    if (!frame) {
        return NULL;
    }

    frame->measurements = malloc(num_measurements * sizeof(ChannelMeasurement));
    if (!frame->measurements) {
        free(frame);
        return NULL;
    }

    frame->num_measurements = num_measurements;

    // Initialize timestamp and sequence number to zero
    frame->timestamp = 0;
    frame->sequence_number = 0;

    return frame;
}

void destroy_frame(FrameInfo *frame) {
    if (frame) {
        free(frame->measurements);
        free(frame);
    }
}

int initialize_frame_manager(FrameManager *manager, size_t initial_frames,
                             void (*log_error)(const char *), 
                             void (*log_event)(const char *)) {

    manager->frames = malloc(initial_frames * sizeof(FrameInfo *));
    if (!manager->frames) {
        log_error("Failed to allocate memory for frames.");
        return -1;
    }

    pthread_mutex_init(&manager->lock, NULL);
    manager->frame_count = initial_frames;
    manager->log_error = log_error;
    manager->log_event = log_event;

    for (size_t i = 0; i < initial_frames; ++i) {
        FrameInfo *frame = create_frame(10); // Assuming each frame has 10 measurements initially
        if (!frame) {
            manager->log_error("Failed to initialize a frame.");
            return -1;
        }
        manager->frames[i] = frame;
    }

    manager->log_event("FrameManager initialized successfully.");

    return 0;
}

void update_frame(FrameManager *manager, size_t index, time_t new_timestamp, int new_sequence_number) {
    if (index >= manager->frame_count) {
        pthread_mutex_lock(&manager->lock);
        manager->log_error("Attempted to access frame out of bounds.");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    pthread_mutex_lock(&manager->lock);

    FrameInfo *frame = manager->frames[index];
    if (!frame) {
        manager->log_error("Frame is NULL, cannot update metadata.");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    frame->timestamp = new_timestamp;
    frame->sequence_number = new_sequence_number;

    manager->log_event("Updated frame metadata.");

    pthread_mutex_unlock(&manager->lock);
}

void cleanup_frame_manager(FrameManager *manager) {
    if (!manager) {
        return;
    }

    for (size_t i = 0; i < manager->frame_count; ++i) {
        destroy_frame(manager->frames[i]);
    }

    free(manager->frames);
    pthread_mutex_destroy(&manager->lock);
}

int main() {
    FrameManager manager;

    if (initialize_frame_manager(&manager, 100, error_logger, event_logger) != 0) {
        return EXIT_FAILURE;
    }

    // Example update
    time_t now = time(NULL);
    update_frame(&manager, 0, now, 42);

    cleanup_frame_manager(&manager);

    return EXIT_SUCCESS;
}
