// Function to initialize and populate FrameInfo array.
FrameInfo* initialize_frames(size_t num_frames, size_t measurements_per_frame) {
    if (num_frames == 0 || measurements_per_frame == 0) {
        return NULL;
    }

    FrameInfo* frames = malloc(num_frames * sizeof(FrameInfo));
    if (!frames) {
        perror("Failed to allocate memory for frames");
        return NULL;
    }

    for (size_t i = 0; i < num_frames; ++i) {
        frames[i].timestamp = time(NULL);
        frames[i].sequence_number = i + 1;

        // Allocate memory for measurements
        frames[i].measurements = malloc(measurements_per_frame * sizeof(ChannelMeasurement));
        if (!frames[i].measurements) {
            perror("Failed to allocate memory for channel measurements");
            free(frames); // Cleanup previously allocated frames
            return NULL;
        }

        // Populate with simulated data
        for (size_t j = 0; j < measurements_per_frame; ++j) {
            ChannelMeasurement cm = simulate_channel_measurement();

            // Simple heuristic filtering: ignore invalid values
            if (cm.frequency > 0 && cm.signal_strength >= 0 && cm.noise_level >= 0) {
                frames[i].measurements[j] = cm;
            } else {
                fprintf(stderr, "Invalid measurement encountered. Sequence: %u, Measurement Index: %zu\n", i + 1, j);
                // Handle missing or erroneous data gracefully
                frames[i].measurements[j] = simulate_channel_measurement(); // Retry simulation
            }
        }

        frames[i].num_measurements = measurements_per_frame;
    }

    return frames;
}

// Function to free allocated resources.
void cleanup_frames(FrameInfo* frames, size_t num_frames) {
    if (!frames) return;

    for (size_t i = 0; i < num_frames; ++i) {
        if (frames[i].measurements) {
            free(frames[i].measurements);
        }
    }

    free(frames);
}

int main() {
    size_t num_frames = 100;
    size_t measurements_per_frame = 10;

    FrameInfo* frames = initialize_frames(num_frames, measurements_per_frame);

    if (frames) {
        // Processing logic can go here
        cleanup_frames(frames, num_frames);
    }

    return 0;
}
