#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define the structure
typedef struct {
    int valid;
    int measurement_object_id;
    int measurement_id;
    size_t result_count;
    void **results; // Dynamic array of pointers to MEASUREMENT_RESULT_T
} LTE_RRC_MEASUREMENT_REPORT_T;

// Logger function for recording events
void log_event(const char *event) {
    printf("Log: %s\n", event);
}

// Error handling macro
#define HANDLE_ERROR(msg) \
    do { perror(msg); exit(EXIT_FAILURE); } while (0)

typedef struct {
    LTE_RRC_MEASUREMENT_REPORT_T **array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock; // Mutex for thread safety
} MeasurementReportManager;

// Function to initialize the manager
MeasurementReportManager* init_manager(size_t initial_capacity) {
    MeasurementReportManager *manager = (MeasurementReportManager *)malloc(sizeof(MeasurementReportManager));
    if (!manager) HANDLE_ERROR("Failed to allocate memory for manager");

    manager->array = (LTE_RRC_MEASUREMENT_REPORT_T **)calloc(initial_capacity, sizeof(LTE_RRC_MEASUREMENT_REPORT_T *));
    if (!manager->array) HANDLE_ERROR("Failed to allocate memory for reports array");

    manager->capacity = initial_capacity;
    manager->count = 0;

    pthread_mutex_init(&manager->lock, NULL);
    log_event("Manager initialized");

    return manager;
}

// Function to add a measurement report
int add_measurement_report(MeasurementReportManager *manager,
                           int measurement_object_id, 
                           int measurement_id, 
                           size_t result_count, 
                           void **results) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        // Resize array to double its capacity
        size_t new_capacity = manager->capacity * 2;
        LTE_RRC_MEASUREMENT_REPORT_T **new_array = realloc(manager->array, new_capacity * sizeof(LTE_RRC_MEASUREMENT_REPORT_T *));
        if (!new_array) {
            pthread_mutex_unlock(&manager->lock);
            log_event("Failed to resize reports array");
            return -1; // Indicate failure
        }
        manager->array = new_array;
        manager->capacity = new_capacity;
    }

    LTE_RRC_MEASUREMENT_REPORT_T *report = (LTE_RRC_MEASUREMENT_REPORT_T *)malloc(sizeof(LTE_RRC_MEASUREMENT_REPORT_T));
    if (!report) {
        pthread_mutex_unlock(&manager->lock);
        log_event("Failed to allocate memory for report");
        return -1; // Indicate failure
    }

    report->valid = 1;
    report->measurement_object_id = measurement_object_id;
    report->measurement_id = measurement_id;
    report->result_count = result_count;

    if (results) {
        report->results = malloc(result_count * sizeof(void *));
        if (!report->results) {
            free(report);
            pthread_mutex_unlock(&manager->lock);
            log_event("Failed to allocate memory for results");
            return -1; // Indicate failure
        }
        memcpy(report->results, results, result_count * sizeof(void *));
    } else {
        report->results = NULL;
    }

    manager->array[manager->count++] = report;

    pthread_mutex_unlock(&manager->lock);
    log_event("Measurement report added successfully");
    return 0; // Indicate success
}

// Function to free resources of the manager
void cleanup_manager(MeasurementReportManager *manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        LTE_RRC_MEASUREMENT_REPORT_T *report = manager->array[i];
        if (report && report->results) {
            free(report->results);
        }
        free(report);
    }

    free(manager->array);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);

    free(manager);
    log_event("Manager resources cleaned up");
}

int main() {
    MeasurementReportManager *manager = init_manager(4); // Initial capacity of 4

    int result1 = 10, result2 = 20;
    void *results[] = { (void *)&result1, (void *)&result2 };

    add_measurement_report(manager, 101, 201, 2, results);

    cleanup_manager(manager);

    return 0;
}
```

### Key Considerations:
- **Memory Constraints**: Efficiently manages memory by resizing the array dynamically and minimizing allocations.
- **Concurrency**: Uses a mutex to ensure thread safety when modifying shared data structures.
- **Scalability**: Resizes the dynamic array as needed, doubling its capacity each time it's full.
- **Performance**: Minimizes frequent reallocations by increasing capacity exponentially.
- **Error Handling**: Checks for allocation failures and logs errors appropriately.
- **Resource Management**: Ensures all allocated memory is freed correctly to prevent leaks.
- **Logging**: Provides basic logging for tracking operations.']

