int readIntegers(int **array, size_t *size) {
    if (scanf("%zu", size) != 1 || *size <= 0) {
        return -1; // Invalid input
    }

    int *buffer = malloc(*size * sizeof(int));
    if (!buffer) {
        return -2; // Memory allocation failure
    }

    for (size_t i = 0; i < *size; ++i) {
        if (scanf("%d", &buffer[i]) != 1) {
            free(buffer);
            return -1; // Invalid input
        }
    }

    *array = buffer;
    return 0; // Success
}

int findLargestInteger(const int *array, size_t size) {
    int largest = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

