// Function to calculate a simple checksum for validation
uint32_t calculate_checksum(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    uint32_t checksum = pdu->RX_UE_INFORMATION_TAG + pdu->RNTI;
    return checksum;
}

// Function to initialize dynamic array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* init_dynamic_array(size_t num_pdus, int *error_code) {
    if (num_pdus <= 0) {
        *error_code = -1; // Invalid number of PDUs
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        *error_code = -2; // Memory allocation failed
        return NULL;
    }

    for (size_t i = 0; i < num_pdus; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = rand() % UINT16_MAX + 1; // Random valid tag
        pdus[i].RNTI = rand() % UINT16_MAX + 1; // Random valid RNTI

        CRC_INDICATION_REL8_TAG crc_tag;
        crc_tag.CRCFLAG = rand() % 256; // Random CRC flag

        if (calculate_checksum(&pdus[i]) != 0) {
            free(pdus);
            *error_code = -3; // Checksum validation failed
            return NULL;
        }
    }

    *error_code = 0; // Success
    return pdus;
}

// Function to free the dynamic array
