#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int key;
    double value;
    char buffer[32]; // Assuming sufficient size for integer string representation
} Record;

typedef struct {
    Record *records;
    size_t count;
    size_t capacity;
} RecordCollection;

// Function prototypes
RecordCollection* create_collection(size_t initial_capacity);
void free_collection(RecordCollection *collection);
int add_record(RecordCollection *collection, int key, double value);
int modify_record(RecordCollection *collection, int key, double new_value);
int reset_records(RecordCollection *collection);
int serialize_to_file(const RecordCollection *collection, const char *filename);
int deserialize_from_file(RecordCollection *collection, const char *filename);

// Implementation
RecordCollection* create_collection(size_t initial_capacity) {
    RecordCollection *collection = (RecordCollection *)malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->records = (Record *)calloc(initial_capacity, sizeof(Record));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->count = 0;
    collection->capacity = initial_capacity;
    return collection;
}

void free_collection(RecordCollection *collection) {
    if (collection) {
        free(collection->records);
        free(collection);
    }
}

int add_record(RecordCollection *collection, int key, double value) {
    if (!collection || collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity == 0 ? 4 : collection->capacity * 2;
        Record *new_records = (Record *)realloc(collection->records, new_capacity * sizeof(Record));
        if (!new_records) return -1;

        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    Record *record = &collection->records[collection->count++];
    record->key = key;
    record->value = value;
    snprintf(record->buffer, sizeof(record->buffer), "%d", key);
    return 0;
}

int modify_record(RecordCollection *collection, int key, double new_value) {
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i].key == key) {
            collection->records[i].value = new_value;
            snprintf(collection->records[i].buffer, sizeof(collection->records[i].buffer), "%d", key);
            return 0;
        }
    }
    return -1;
}

int reset_records(RecordCollection *collection) {
    if (!collection) return -1;

    for (size_t i = 0; i < collection->count; ++i) {
        collection->records[i].value = 0.0;
        memset(collection->records[i].buffer, 0, sizeof(collection->records[i].buffer));
    }
    return 0;
}

int serialize_to_file(const RecordCollection *collection, const char *filename) {
    if (!collection || !filename) return -1;

    FILE *file = fopen(filename, "wb");
    if (!file) return -2;

    size_t written = fwrite(&collection->count, sizeof(collection->count), 1, file);
    if (written != 1) {
        fclose(file);
        return -3;
    }

    written = fwrite(collection->records, sizeof(Record), collection->count, file);
    if (written != collection->count) {
        fclose(file);
        return -4;
    }

    fclose(file);
    return 0;
}

int deserialize_from_file(RecordCollection *collection, const char *filename) {
    if (!collection || !filename) return -1;

    FILE *file = fopen(filename, "rb");
    if (!file) return -2;

    size_t read_count;
    read_count = fread(&collection->count, sizeof(collection->count), 1, file);
    if (read_count != 1) {
        fclose(file);
        return -3;
    }

    Record *new_records = (Record *)realloc(collection->records, collection->count * sizeof(Record));
    if (!new_records) {
        fclose(file);
        return -4;
    }

    collection->records = new_records;
    collection->capacity = collection->count;

    size_t read_size = fread(collection->records, sizeof(Record), collection->count, file);
    if (read_size != collection->count) {
        free(collection->records);
        fclose(file);
        return -5;
    }

    fclose(file);
    return 0;
}
