    struct timespec start, end;
    clock_gettime(CLOCK_REALTIME, &start);

    for (int i = 0; i < batch->count; ++i) {
        if (!checkJPEGValidity(batch->images[i].imageFile)) {
            printf("Invalid JPEG file: %s\n", batch->images[i].imageFile);
            return NULL;
        }

        // Simulate conversion process
        sleep(1);  // Replace with actual conversion call

        char outputFilePath[256];
        snprintf(outputFilePath, sizeof(outputFilePath), "%s/image_%d.pdf", "output_directory", i);

        if (access(outputFilePath, F_OK) != -1) {
            printf("File exists and will be overwritten: %s\n", outputFilePath);
        }

        FILE *pdf = fopen(outputFilePath, "w");
        if (!pdf) {
            perror("Failed to open PDF file for writing");
            return NULL;
        }
        fprintf(pdf, "PDF content from %s\n", batch->images[i].imageFile);
        fclose(pdf);
    }

    clock_gettime(CLOCK_REALTIME, &end);
    double elapsed = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1e9;
    if (elapsed > TIMEOUT_THRESHOLD) {
        printf("Batch processing exceeded time limit\n");
        return NULL;
    }

    return NULL;
}

int processImagesAndGeneratePDFs(int N, const char *outputDirectory, const char *imageFiles[], int imageCount) {
    if (!N || !outputDirectory || !imageFiles || imageCount == 0) {
        printf("Invalid input parameters\n");
        return 1;
    }

    DIR *dir = opendir(outputDirectory);
    if (!dir) {
        perror("Failed to open output directory");
        return 1;
    }
    closedir(dir);

    pthread_t threads[MAX_IMAGES_PER_BATCH];
    Batch batches[(imageCount + MAX_IMAGES_PER_BATCH - 1) / MAX_IMAGES_PER_BATCH];

    for (int i = 0; i < imageCount; ++i) {
        int batchIndex = i / MAX_IMAGES_PER_BATCH;
        batches[batchIndex].images[i % MAX_IMAGES_PER_BATCH] = (ImageInfo){imageFiles[i], checkJPEGValidity(imageFiles[i])};
        if ((i + 1) % MAX_IMAGES_PER_BATCH == 0 || i == imageCount - 1) {
            batches[batchIndex].count = (i + 1) % MAX_IMAGES_PER_BATCH ? (i + 1) % MAX_IMAGES_PER_BATCH : MAX_IMAGES_PER_BATCH;
            pthread_create(&threads[batchIndex], NULL, processBatch, &batches[batchIndex]);
        }
    }

    for (int i = 0; i < (imageCount + MAX_IMAGES_PER_BATCH - 1) / MAX_IMAGES_PER_BATCH; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
