void log_structure_details(NFAPI_CRC_INDICATION_PDU_T* pdu, int index);
void sleep_ms(int ms);

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pdus;
    size_t count;
} PduList;

PduList create_and_populate_pdulist(size_t n) {
    if (n > MAX_STRUCTURES) {
        fprintf(stderr, "Requested number of structures exceeds the maximum limit.\n");
        exit(EXIT_FAILURE);
    }

    PduList pdu_list = {NULL, 0};
    pthread_t update_thread;

    // Allocate memory for the list
    pdu_list.pdus = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list.pdus) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    pdu_list.count = n;

    // Populate the list with data
    for (size_t i = 0; i < n; ++i) {
        pdu_list.pdus[i].ue_tag.RNTI = rand() % 65536;
        pdu_list.pdus[i].ue_tag.CRCFLAG = rand() & 1;
        pdu_list.pdus[i].rnti = rand() % 65536;
        pdu_list.pdus[i].crc_indication_rel8_tag = rand() % 256;

        // Log structure details with throttling
        log_structure_details(&pdu_list.pdus[i], i);
    }

    // Start a thread to update the data source periodically
    if (pthread_create(&update_thread, NULL, update_data_source, &pdu_list)) {
        perror("Failed to create update thread");
        exit(EXIT_FAILURE);
    }
    pthread_detach(update_thread);

    return pdu_list;
}

void free_pdu_list(PduList* list) {
    if (list && list->pdus) {
        free(list->pdus);
        list->pdus = NULL;
        list->count = 0;
    }
}

void log_structure_details(NFAPI_CRC_INDICATION_PDU_T* pdu, int index) {
    pthread_mutex_lock(&log_mutex);

    FILE* file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("Failed to open log file");
        pthread_mutex_unlock(&log_mutex);
        return;
    }

    fprintf(file, "Index: %d, RNTI: %d, CRCFLAG: %d\n",
            index,
            pdu->ue_tag.RNTI,
            pdu->ue_tag.CRCFLAG);

    fclose(file);
    pthread_mutex_unlock(&log_mutex);

    // Throttle logging frequency
    sleep_ms(LOG_THROTTLE_MS);
}

void* update_data_source(void* arg) {
    PduList* list = (PduList*)arg;

    while (1) {
        int retries = 0;
        int delay = 100; // Initial backoff delay in ms

        while (retries < RETRY_LIMIT) {
            // Simulate data update from external source
            for (size_t i = 0; i < list->count; ++i) {
                list->pdus[i].ue_tag.CRCFLAG = rand() & 1;
            }

            if (/* success condition, e.g., network response */) {
                break;
            }

            retries++;
            sleep_ms(delay);
            delay *= 2;
        }

        // Update every few seconds
        sleep_ms(3000);
    }
}

void sleep_ms(int ms) {
    struct timespec req = {0};
    req.tv_sec = ms / 1000;
    req.tv_nsec = (ms % 1000) * 1000000L;
    nanosleep(&req, NULL);
}

// Usage example
int main() {
    PduList pdu_list = create_and_populate_pdulist(10);

    // Simulate some operation with the list...

    free_pdu_list(&pdu_list);
    return 0;
}
```

