```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int SEQUENCE_NUMBER;
    int TRANSPORT_FORMAT;
    int MODULATION_AND_CODING_SCHEME;
} NFMMT_Message;

typedef struct Node {
    NFMMT_Message message;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
} MessageList;

void log_error(const char* error) {
    fprintf(stderr, "Error: %s\n", error);
}

Node* create_node(NFMMT_Message msg) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_error("Memory allocation failed for new node.");
        return NULL;
    }
    new_node->message = msg;
    new_node->next = NULL;
    return new_node;
}

MessageList* create_message_list() {
    MessageList* list = (MessageList*)malloc(sizeof(MessageList));
    if (!list) {
        log_error("Memory allocation failed for message list.");
        return NULL;
    }
    list->head = NULL;
    list->size = 0;
    return list;
}

int insert_message(MessageList* list, NFMMT_Message msg) {
    if (!list) {
        log_error("Invalid message list pointer.");
        return -1;
    }

    Node* new_node = create_node(msg);
    if (!new_node) return -1;

    // Insert at head for simplicity; consider tail or sorted insertion based on needs
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    return 0;
}

int delete_message(MessageList* list, int sequence_number) {
    if (!list || !list->head) {
        log_error("Invalid message list pointer or empty list.");
        return -1;
    }

    Node *current = list->head, *prev = NULL;

    while (current && current->message.SEQUENCE_NUMBER != sequence_number) {
        prev = current;
        current = current->next;
    }

    if (!current) {
        log_error("Message with specified sequence number not found.");
        return -1;
    }

    if (!prev) { // Head node is being deleted
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    list->size--;

    return 0;
}

void traverse_messages(MessageList* list, void (*callback)(NFMMT_Message)) {
    if (!list || !list->head) {
        log_error("Invalid message list pointer or empty list.");
        return;
    }

    Node* current = list->head;
    while (current) {
        callback(current->message);
        current = current->next;
    }
}

void free_message_list(MessageList* list) {
    if (!list) return;

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    free(list);
}

// Example callback function for traversal
void print_message(NFMMT_Message msg) {
    printf("Sequence Number: %d, Transport Format: %d, Modulation and Coding Scheme: %d\n",
           msg.SEQUENCE_NUMBER, msg.TRANSPORT_FORMAT, msg.MODULATION_AND_CODING_SCHEME);
}

int main() {
    MessageList* list = create_message_list();
    if (!list) return -1;

    NFMMT_Message msg1 = {1, 100, 200};
    NFMMT_Message msg2 = {2, 101, 201};

    insert_message(list, msg1);
    insert_message(list, msg2);

    traverse_messages(list, print_message);

    delete_message(list, 1);
    traverse_messages(list, print_message);

    free_message_list(list);

    return 0;
}
```

### Key Points:
- **Input Validation**: The functions check for null pointers and invalid operations.
- **Error Logging**: A simple logging mechanism is implemented using `fprintf` to standard error.
- **Resource Management**: Memory is managed carefully with checks during allocation, and nodes are freed appropriately.
- **Performance Considerations**: Insertion at the head is used for simplicity; however, other strategies (like sorted insertion) can be considered based on specific performance needs.

This implementation provides a foundation that can be extended or optimized further depending on specific application requirements.']

