struct Attack {
    int attackType;
    int attackCooldown;  // in seconds
    std::chrono::time_point<std::chrono::steady_clock> cooldownTimestamp;
    std::chrono::time_point<std::chrono::steady_clock> lastUsedTimestamp;
    int playerID;
};

class AttackManager {
public:
    void selectAndCooldownAttack(int playerID) {
        std::unique_lock lock(mutex_);

        auto currentTime = std::chrono::steady_clock::now();
        if (cooldownMap_.find(playerID) != cooldownMap_.end() &&
            std::chrono::duration_cast<std::chrono::seconds>(currentTime - cooldownMap_[playerID]).count() < 9) {
            std::cout << "Attack on cooldown for player " << playerID << ".\n";
            return;
        }

        int selectedAttack = selectRandomAttack();

        // Simulate an attack being used
        useAttack(selectedAttack, playerID);

        cooldownMap_[playerID] = currentTime + std::chrono::seconds(9);
    }

private:
    std::vector<Attack> attacks_;
    std::unordered_map<int, std::chrono::time_point<std::chrono::steady_clock>> cooldownMap_;
    mutable std::shared_mutex mutex_;

    int selectRandomAttack() {
        std::random_device rd;
        std::mt19937 gen(rd());

        if (attacks_.empty()) return -1; // No attacks available

        std::uniform_int_distribution<> dis(0, attacks_.size() - 1);
        return dis(gen);
    }

    void useAttack(int attackIndex, int playerID) {
        if (attackIndex < 0 || attackIndex >= attacks_.size()) {
            std::cerr << "Invalid attack index.\n";
            return;
        }

        Attack& attack = attacks_[attackIndex];
        auto currentTime = std::chrono::steady_clock::now();

        // Update attack timestamps
        attack.lastUsedTimestamp = currentTime;
        attack.cooldownTimestamp = currentTime + std::chrono::seconds(attack.attackCooldown);

        // Log the selection
        std::cout << "Player " << playerID << " used Attack #" << attackIndex << "\n";
    }

public:
    void addAttack(const Attack& newAttack) {
        std::unique_lock lock(mutex_);
        attacks_.push_back(newAttack);
    }

    void updateAttack(int index, const Attack& updatedAttack) {
        std::unique_lock lock(mutex_);
        if (index < 0 || index >= attacks_.size()) return;
        attacks_[index] = updatedAttack;
    }

    void deleteAttack(int index) {
        std::unique_lock lock(mutex_);
        if (index < 0 || index >= attacks_.size()) return;
        attacks_.erase(attacks_.begin() + index);
    }
};

// Example usage
int main() {
    AttackManager manager;

    // Add some attacks
    manager.addAttack({1, 5, std::chrono::steady_clock::now(), std::chrono::steady_clock::time_point(), 1});
    manager.addAttack({2, 10, std::chrono::steady_clock::now(), std::chrono::steady_clock::time_point(), 2});

    // Simulate a player selecting an attack
    manager.selectAndCooldownAttack(1);

    return 0;
}
