            using (RSACryptoServiceProvider rsa = new RSACryptoServiceProvider()) {
                Log("RSA signing started.");
                rsa.ImportParameters(privateKey);

                var hashAlgorithm = SHA1.Create();
                var hashedData = hashAlgorithm.ComputeHash(data);

                return rsa.SignHash(hashedData, algorithm);
            }
        }

        // Asynchronous Example
        public async Task<byte[]> AesEncryptAsync(byte[] data, byte[] key, byte[] iv) {
            using (Aes aesAlg = Aes.Create()) {
                Log("AES encryption async started.");
                aesAlg.Key = key;
                aesAlg.IV = iv;

                ICryptoTransform encryptor = aesAlg.CreateEncryptor(aesAlg.Key, aesAlg.IV);
                return await Task.Run(() => PerformCryptography(data, encryptor));
            }
        }

        // Helper Method for Encryption/Decryption
        private byte[] PerformCryptography(byte[] data, ICryptoTransform cryptoTransform) {
            using (var ms = new System.IO.MemoryStream()) {
                using (var cs = new CryptoStream(ms, cryptoTransform, CryptoStreamMode.Write)) {
                    cs.Write(data, 0, data.Length);
                }
                return ms.ToArray();
            }
        }

        // Random Value Generation
        public int GetRandomInteger(bool inclusive) {
            float range = inclusive ? _maxValue - _minValue + 1 : _maxValue - _minValue;
            int randomFloat = Mathf.FloorToInt(UnityEngine.Random.Range(_minValue, _maxValue + (inclusive ? 1f : 0f)));
            return randomFloat;
        }

        public float GetRandomFloat() {
            return UnityEngine.Random.Range((float)_minValue, (float)(_maxValue + 1));
        }

        // Override ToString
        public override string ToString() {
            return $"CryptoModule Range: [{_minValue}, {_maxValue}]";
        }

        // Logging Mechanism
        private void Log(string message) {
            if(CurrentLogLevel == LogLevel.Debug || CurrentLogLevel == LogLevel.Info || 
               CurrentLogLevel == LogLevel.Warning || CurrentLogLevel == LogLevel.Error) {
