    unsigned int RNTI;
    unsigned short CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to calculate a simple checksum for validation
unsigned short calculate_checksum(const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    return (pdu->RX_UE_INFORMATION_TAG ^ pdu->RNTI ^ pdu->CRC_INDICATION_REL8_TAG);
}

// Initialize dynamic array of PDUs with randomized CRCFLAG
NFAPI_CRC_INDICATION_PDU_T* initialize_pdus(size_t count, unsigned int *status) {
    if (count == 0) {
        *status = 1; // Error: Invalid count
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        *status = 2; // Error: Memory allocation failed
        return NULL;
    }

    srand((unsigned int)time(NULL)); // Seed random number generator

    for (size_t i = 0; i < count; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = rand() % 256; // Example range
        pdus[i].RNTI = rand() % 65536;                // Example range
        pdus[i].CRC_INDICATION_REL8_TAG = rand() & 0xFFFF;

        unsigned short checksum = calculate_checksum(&pdus[i]);

        if (checksum == 0) { // Simple validation logic, replace with real criteria
            *status = 3; // Error: Invalid CRCFLAG after generation
            free(pdus);
            return NULL;
        }
    }

    *status = 0; // Success
    return pdus;
}

// Function to clean up allocated memory
void cleanup_pdus(NFAPI_CRC_INDICATION_PDU_T *pdus) {
    if (pdus) {
        free(pdus);
    }
}

int main() {
    unsigned int status;
    size_t pdu_count = 10; // Example count

    NFAPI_CRC_INDICATION_PDU_T *pdus = initialize_pdus(pdu_count, &status);

    if (status == 0) {
        printf("PDUs initialized successfully.\n");
        for (size_t i = 0; i < pdu_count; ++i) {
            printf("PDU %zu: RX_UE_INFORMATION_TAG=%u, RNTI=%u, CRC_INDICATION_REL8_TAG=%u\n",
                   i,
                   pdus[i].RX_UE_INFORMATION_TAG,
                   pdus[i].RNTI,
                   pdus[i].CRC_INDICATION_REL8_TAG);
        }
    } else {
        printf("Failed to initialize PDUs. Error code: %d\n", status);
    }

    cleanup_pdus(pdus);
    return 0;
}
