        fclose(logger->log_file);
        pthread_mutex_destroy(&logger->mutex);
        custom_free(logger);
    }
}

void log_if_needed(NFAPI_CRC_INDICATION_PDU_T* data, Logger* logger, int frequency) {
    if (!logger) return;

    pthread_mutex_lock(&logger->mutex);

    time_t now = time(NULL);
    if ((now - logger->last_log_time > frequency) || (logger->log_count >= frequency)) {
        log_structure(data, logger->log_file);
        logger->last_log_time = now;
        logger->log_count = 0;
    } else {
        logger->log_count++;
    }

    pthread_mutex_unlock(&logger->mutex);
}

Node* create_linked_list(int M, int log_frequency, const char* log_file_path) {
    if (M <= 0) return NULL;

    Logger* logger = init_logger(log_file_path, log_frequency);

    Node* head = NULL;
    Node** current = &head;

    for (int i = 0; i < M; ++i) {
        Node* new_node = (Node*) custom_alloc(sizeof(Node));
        if (!new_node) {
            fprintf(stderr, "Memory allocation failed.\n");
            free_linked_list(head);
            destroy_logger(logger);
            return NULL;
        }

        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % 1000; // Example random value
        pdu.RNTI = rand() % 10000;                 // Example random value
        pdu.CRC_INDICATION_REL8_TAG = rand() % 256; // Example random value
        pdu.CRCFLAG = rand() % 2;                  // Random CRC flag

        if (!is_valid(&pdu)) {
            fprintf(stderr, "Invalid data structure.\n");
            custom_free(new_node);
            continue;
        }

        new_node->data = pdu;
        new_node->next = NULL;

        *current = new_node;
        current = &new_node->next;

        log_if_needed(&pdu, logger, log_frequency);
    }

    // Periodic health checks and external updates
    while (1) {
        health_check(head);
        update_from_external_source(head);

        sleep(10); // Adjust as needed for refresh intervals
    }

    return head;
}

void free_linked_list(Node* head) {
    Node* tmp;
    while (head != NULL) {
        tmp = head;
        head = head->next;
        custom_free(tmp);
    }
}

