#include <unistd.h>

#define MAX_RETRY 5
#define LOG_THROTTLE_MS 1000

typedef struct {
    // Assuming these are the required fields for RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG
    int rx_ue_information_tag;
    int rnti;
    int crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} LinkedList;

int max_structures = 1000; // Default limit, configurable
size_t current_limit = max_structures;
pthread_mutex_t config_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_list(LinkedList* list) {
    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond, NULL);
}

void destroy_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->cond);
}

void add_structure(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (list->count >= current_limit) return;

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return; // Handle memory allocation failure

    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    list->count++;
    pthread_mutex_unlock(&list->lock);

    log_structure(data);
}

void update_max_structures(size_t new_limit) {
    pthread_mutex_lock(&config_lock);
    current_limit = new_limit;
    pthread_mutex_unlock(&config_lock);
}

static void log_structure(NFAPI_CRC_INDICATION_PDU_T data) {
    static FILE* log_file = NULL;
    if (!log_file) {
        log_file = fopen("nfa_log.txt", "a");
        if (!log_file) return; // Handle file open failure
    }

    pthread_mutex_lock(&config_lock);
    time_t now = time(NULL);
    struct tm *tm_struct = localtime(&now);

    fprintf(log_file, "[%02d:%02d:%02d] RX UE Info: %d, RNTI: %d, CRC Tag: %d\n",
            tm_struct->tm_hour, tm_struct->tm_min, tm_struct->tm_sec,
            data.rx_ue_information_tag, data.rnti, data.crc_indication_rel8_tag);
    fflush(log_file); // Ensure immediate write
    pthread_mutex_unlock(&config_lock);

    usleep(LOG_THROTTLE_MS * 1000); // Throttle logging frequency
}

void simulate_external_update(LinkedList* list) {
    for (int retry = 0; retry < MAX_RETRY; ++retry) {
        int delay = 1 << retry; // Exponential backoff

        if (!simulate_network_fetch()) continue;

        NFAPI_CRC_INDICATION_PDU_T data;
        // Populate `data` here
        srand(time(NULL));
        data.rx_ue_information_tag = rand();
        data.rnti = rand() % 1000;
        data.crc_indication_rel8_tag = rand() % 256;
        data.crcflag = (rand() % 2) ? 1 : 0;

        add_structure(list, data);

        break; // Break if successful
    }
}

int simulate_network_fetch() {
    return rand() % 2; // Simulate network success/failure
}

void* update_thread(void* arg) {
    LinkedList* list = (LinkedList*)arg;
    while (1) {
        simulate_external_update(list);
        sleep(5); // Update every 5 seconds
    }
    return NULL;
}

int main() {
    LinkedList list;
    initialize_list(&list);

    pthread_t update_tid;
    pthread_create(&update_tid, NULL, update_thread, &list);

    // Allow user to change configuration at runtime
    while (1) {
        size_t new_limit;
        printf("Enter new max structure limit: ");
        scanf("%zu", &new_limit);
        update_max_structures(new_limit);
    }

    pthread_join(update_tid, NULL);
    destroy_list(&list);

    return 0;
}
