MAC_PDU* create_mac_pdus(size_t max_memory_size, size_t *num_pdus) {
    if (max_memory_size < sizeof(MAC_PDU)) {
        return NULL;  // Not enough memory for even one PDU
    }

    srand(time(NULL));  // Seed random number generator

    MAC_PDU *pdus = NULL;
    size_t total_allocated_size = 0;
    size_t pdu_count = 0;

    while (total_allocated_size + sizeof(MAC_PDU) <= max_memory_size) {
        MAC_PDU *new_pdu = (MAC_PDU *)malloc(sizeof(MAC_PDU));
        if (!new_pdu) break; // Allocation failed

        new_pdu->header.dest_address = rand() % 65536;
        new_pdu->header.src_address = rand() % 65536;
        new_pdu->header.control_field = rand() % 256;

        size_t payload_length = (rand() % 91) + 10; // Payload length between 10 and 100
        if (total_allocated_size + sizeof(MAC_PDU) + payload_length > max_memory_size) break;

        new_pdu->payload_data = (unsigned char *)malloc(payload_length);
        if (!new_pdu->payload_data) {
            free(new_pdu); // Free MAC_PDU structure if payload allocation fails
            break;
        }

        memset(new_pdu->payload_data, rand() % 256, payload_length);

        pdus = realloc(pdus, sizeof(MAC_PDU) * (pdu_count + 1));
        if (!pdus) {
            free(new_pdu->payload_data);
            free(new_pdu);
            break;
        }

        pdus[pdu_count++] = *new_pdu;

        total_allocated_size += sizeof(MAC_PDU) + payload_length;
    }

    *num_pdus = pdu_count;
    return pdus;
}

void free_mac_pdus(MAC_PDU *pdus, size_t num_pdus) {
    if (!pdus) return;

    for (size_t i = 0; i < num_pdus; ++i) {
        free(pdus[i].payload_data);
    }

    free(pdus);
}

int main() {
    const size_t max_memory_size = 1024 * 1024; // Example: 1MB
    size_t num_pdus;
    MAC_PDU *pdus = create_mac_pdus(max_memory_size, &num_pdus);

    if (pdus) {
        printf("Created %zu PDUs\n", num_pdus);
        free_mac_pdus(pdus, num_pdus);
    } else {
        printf("Failed to allocate memory for any PDU.\n");
    }

    return 0;
}
