    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

int add_entry(CRC_Indication_List *list, const NFAPI_CRC_INDICATION_PDU_T *entry) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity) {
        resize_list(list, list->capacity * 2); // Double the capacity
    }

    list->entries[list->count++] = *entry;

    log_state(list);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_entry(CRC_Indication_List *list, unsigned long rnti) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->entries[i].rnti.rnti == rnti) {
            for (size_t j = i; j < list->count - 1; ++j) {
                list->entries[j] = list->entries[j + 1];
            }
            --list->count;

            if (list->capacity > 10 && list->count <= list->capacity / 4) {
                resize_list(list, list->capacity / 2); // Halve the capacity
            }

            log_state(list);
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Entry not found
}

void resize_list(CRC_Indication_List *list, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T* new_entries = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->entries, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (new_entries != NULL) {
