#include <errno.h>

// Define the record structure
typedef struct {
    long offset;
    int key;
    int value;
} Record;

// Define the NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    unsigned char RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function prototypes
void* safe_malloc(size_t size);
Record* initialize_records(int num_records);
NFAPI_CRC_INDICATION_PDU_T* initialize_crc_list(int num_elements, unsigned char tag, unsigned short rnti);
void run_command_in_background(const char *command);
void serialize_data(void *data, int data_size, const char *format);

// Safe memory allocation with error logging
void* safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Initialize an array of records
Record* initialize_records(int num_records) {
    Record *records = (Record*)safe_malloc(num_records * sizeof(Record));
    for (int i = 0; i < num_records; ++i) {
        records[i].offset = rand() % 1000000;
        records[i].key = rand() % 100;
        records[i].value = rand() % 100;
    }
    return records;
}

// Initialize a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* initialize_crc_list(int num_elements, unsigned char tag, unsigned short rnti) {
    NFAPI_CRC_INDICATION_PDU_T *crc_list = (NFAPI_CRC_INDICATION_PDU_T*)safe_malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < num_elements; ++i) {
        crc_list[i].RX_UE_INFORMATION_TAG = tag;
        crc_list[i].RNTI = rnti;
        crc_list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }
    return crc_list;
}

// Run a command in the background
void run_command_in_background(const char *command) {
    pid_t pid = fork();
    if (pid == -1) {
        perror("Fork failed");
        exit(EXIT_FAILURE);
    } else if (pid > 0) {
        // Parent process waits for the child to finish
        int status;
        waitpid(pid, &status, 0);
    } else {
        // Child process executes the command
        execlp(command, command, NULL);
        perror("Execution failed");
        exit(EXIT_FAILURE);
    }
}

// Serialize data based on format
void serialize_data(void *data, int data_size, const char *format) {
    if (strcmp(format, "binary") == 0) {
        // Binary serialization logic
        FILE *file = fopen("output.bin", "wb");
        if (!file) {
            perror("Failed to open file for binary write");
            exit(EXIT_FAILURE);
        }
        fwrite(data, data_size, 1, file);
        fclose(file);
    } else if (strcmp(format, "text") == 0) {
        // Text serialization logic
        FILE *file = fopen("output.txt", "w");
        if (!file) {
            perror("Failed to open file for text write");
            exit(EXIT_FAILURE);
        }
        // Example: serialize records as CSV
        Record *records = (Record*)data;
        for (int i = 0; i < data_size / sizeof(Record); ++i) {
            fprintf(file, "%ld,%d,%d\n", records[i].offset, records[i].key, records[i].value);
        }
        fclose(file);
    } else {
        fprintf(stderr, "Unsupported format: %s\n", format);
        exit(EXIT_FAILURE);
    }
}

int main() {
    int num_records = 1000000; // Example number of records
    Record *records = initialize_records(num_records);

    int num_crc_elements = 10000;
    NFAPI_CRC_INDICATION_PDU_T *crc_list = initialize_crc_list(num_crc_elements, 0xAA, 0x1234);

    run_command_in_background("ls");

    serialize_data(records, num_records * sizeof(Record), "binary");
    serialize_data(crc_list, num_crc_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T), "text");

    free(records);
    free(crc_list);

    return 0;
}
```

### Key Points:
