        fprintf(stderr, "Invalid input for number of values.\n");
        return;
    }

    double* values = (double*) malloc(num_values * sizeof(double));
    if (!values) {
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }

    int valid_count = 0;
    for (int i = 0; i < num_values; ++i) {
        if (scanf("%lf", &values[i]) != 1) {
            fprintf(stderr, "Invalid input detected. Skipping invalid entry.\n");
            --num_values;
            continue;
        }
        valid_count++;
    }

    double sum = 0.0;
    for (int i = 0; i < valid_count; ++i) {
        sum += values[i];
    }

    if (valid_count > 0) {
        printf("Average: %f\n", sum / valid_count);
    } else {
        fprintf(stderr, "No valid inputs to calculate average.\n");
    }

    free(values);
}

