} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_ARRAY_SIZE 1000

// Mock function to simulate fetching UE information and RNTI
int fetch_UE_information(int *RX_UE_INFORMATION_TAG, int *RNTI) {
    // Simulate connectivity issues with random failure
    if (rand() % 10 < 2) {  // 20% chance of failure
        return -1;
    }

    *RX_UE_INFORMATION_TAG = rand() % 100;  // Random RX UE Information Tag
    *RNTI = rand() % 50 + 1;  // Random RNTI (non-zero)
    return 0;
}

// Function to initialize and manage the array of structures
NFAPI_CRC_INDICATION_PDU_T* init_NFAPI_CRC_INDICATION_PDUs(size_t *size) {
    if (!size) {
        fprintf(stderr, "Error: Invalid size pointer\n");
        return NULL;
    }

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    *size = 0;

    while (*size < MAX_ARRAY_SIZE) {
        pthread_mutex_lock(&lock);

        // Attempt to reallocate memory
        if (!array || *size == array_capacity(array)) {
            size_t new_capacity = *size + 10;  // Increase in chunks of 10

            if (new_capacity > MAX_ARRAY_SIZE) {
                fprintf(stderr, "Error: Exceeded maximum capacity\n");
                free(array);
                pthread_mutex_unlock(&lock);
                return NULL;
            }

            NFAPI_CRC_INDICATION_PDU_T *temp = realloc(array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

            if (!temp) {
                fprintf(stderr, "Error: Memory allocation failed\n");
                free(array);
                pthread_mutex_unlock(&lock);
                return NULL;
            }

            array = temp;
        }

        // Fetch UE information and RNTI
        int RX_UE_INFORMATION_TAG, RNTI;
        if (fetch_UE_information(&RX_UE_INFORMATION_TAG, &RNTI) != 0) {
            fprintf(stderr, "Error: Failed to fetch UE information\n");
            free(array);
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        // Initialize CRC_INDICATION_REL8_TAG and CRCFLAG
        NFAPI_CRC_INDICATION_PDU_T pdu = {
            .RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG,
            .RNTI = RNTI,
            .CRC_INDICATION_REL8_TAG = rand() % 100,  // Random tag for illustration
            .CRCFLAG = rand() % 2  // Random CRC flag (0 or 1)
        };

        array[*size] = pdu;
        (*size)++;

        pthread_mutex_unlock(&lock);
    }

    return array;
}

// Utility function to get current capacity of the dynamically allocated array
static size_t array_capacity(NFAPI_CRC_INDICATION_PDU_T *array) {
