### Web API Endpoint: HTTP PUT for Updating Resource

```python
from flask import Flask, request, jsonify, abort
import threading

app = Flask(__name__)
lock = threading.Lock()
resources = {}

@app.route('/resource/<int:id>', methods=['PUT'])
def update_resource(id):
    with lock:
        if id not in resources:
            return jsonify({'error': 'Resource not found'}), 404

        data = request.json
        if 'updated_data' not in data:
            abort(400, description='Invalid input')

        # Update resource logic here
        resources[id]['data'] = data['updated_data']
        return jsonify(resources[id])

if __name__ == '__main__':
    app.run(debug=True)
```

### Web API Endpoint: HTTP DELETE for Deleting Resource

```python
@app.route('/resource/<int:id>', methods=['DELETE'])
def delete_resource(id):
    with lock:
        if id not in resources:
            return jsonify({'error': 'Resource not found'}), 404

        # Delete resource logic here
        del resources[id]

        # Return new resource with default values
        new_resource = {'data': 'default_value'}
        resources[id] = new_resource
        return jsonify(new_resource)
```

