['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_NICBS 10000

typedef struct {
    char MAC_ADDRESS[18]; // Format: XX:XX:XX:XX:XX:XX
    char IP_ADDRESS[16];  // Format: XXX.XXX.XXX.XXX or equivalent
    int PORT_NUMBER;      // Assuming a standard port range (0 - 65535)
} NICB;

typedef struct {
    NICB *nicbs;
    size_t count;
    size_t capacity;
} NICBManager;

int MAC_ADDRESS_unique(NICBManager *manager, const char *mac) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->nicbs[i].MAC_ADDRESS, mac) == 0) {
            return 0;
        }
    }
    return 1;
}

int initialize_NICBManager(NICBManager *manager) {
    manager->nicbs = NULL;
    manager->count = 0;
    manager->capacity = 0;

    if (manager->capacity < MAX_NICBS) {
        manager->capacity = MAX_NICBS;
        manager->nicbs = malloc(sizeof(NICB) * manager->capacity);
        return manager->nicbs != NULL ? 1 : 0;
    }
    return 0;
}

int add_NICB(NICBManager *manager, const NICB *new_nicb) {
    if (manager->count >= manager->capacity || !MAC_ADDRESS_unique(manager, new_nicb->MAC_ADDRESS)) {
        return -1; // Full or duplicate MAC_ADDRESS
    }

    manager->nicbs[manager->count] = *new_nicb;
    ++manager->count;

    return 0; // Success
}

void remove_NICB(NICBManager *manager, const char *mac) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->nicbs[i].MAC_ADDRESS, mac) == 0) {
            memmove(&manager->nicbs[i], &manager->nicbs[i + 1], sizeof(NICB) * (manager->count - i - 1));
            --manager->count;
            break;
        }
    }
