    StrategyManager() : maxEntries(5000), cooldownSeconds(8) {}

    void selectAndExecuteStrategy();

private:
    void logOperation(const std::string& message);
    int selectStrategy();
    void adjustMaxEntriesBasedOnLoad();

    mutable std::mutex mtx;
    std::atomic<int> lastSelectionTime{0};
    const int cooldownSeconds;
    std::atomic<int> maxEntries;

    static constexpr int strategyCount = 3;
};

void StrategyManager::selectAndExecuteStrategy() {
    std::lock_guard<std::mutex> lock(mtx);

    auto currentTime = std::chrono::system_clock::to_time_t(std::chrono::system_clock::now());
    if (currentTime - lastSelectionTime.load() < cooldownSeconds) {
        logOperation("Cooldown period active. Strategy selection aborted.");
        return;
    }

    adjustMaxEntriesBasedOnLoad();

    int strategy = selectStrategy();
    std::cout << "Selected Strategy: " << strategy << std::endl;

    // Simulate the execution of a strategy
    std::this_thread::sleep_for(std::chrono::milliseconds(100));  // Placeholder for actual strategy logic

    lastSelectionTime.store(currentTime);

    logOperation("Strategy executed successfully.");
}

void StrategyManager::logOperation(const std::string& message) {
    std::lock_guard<std::mutex> lock(mtx);
    std::ofstream logFile("strategy_log.txt", std::ios_base::app);
    if (logFile.is_open()) {
        auto now = std::chrono::system_clock::to_time_t(std::chrono::system_clock::now());
        logFile << std::ctime(&now) << message << "\n";
    }
}

int StrategyManager::selectStrategy() {
    static std::vector<std::unique_ptr<int>> strategies(strategyCount);

    if (strategies.empty()) {
        for (int i = 0; i < strategyCount; ++i) {
