#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
#include <stdbool.h>
#include <string.h>

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    bool CRC_INDICATION_REL8_TAG; // Randomly generated CRC flag
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t mutex;
} LockFreeQueue;

// Initialize the lock-free queue
void initLockFreeQueue(LockFreeQueue* queue) {
    queue->head = NULL;
    pthread_mutex_init(&queue->mutex, NULL);
}

// Push data to the lock-free queue
void pushToLockFreeQueue(LockFreeQueue* queue, NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        perror("Failed to allocate memory for new node");
        exit(EXIT_FAILURE);
    }
    newNode->data = pdu;
    newNode->next = NULL;

    pthread_mutex_lock(&queue->mutex);
    newNode->next = queue->head;
    queue->head = newNode;
    pthread_mutex_unlock(&queue->mutex);
}

// Pop data from the lock-free queue
bool popFromLockFreeQueue(LockFreeQueue* queue, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&queue->mutex);
    if (queue->head == NULL) {
        pthread_mutex_unlock(&queue->mutex);
        return false;
    }

    Node* temp = queue->head;
    *pdu = temp->data;
    queue->head = temp->next;
    free(temp);

    pthread_mutex_unlock(&queue->mutex);
    return true;
}

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t capacity;
    size_t count;
    atomic_uint_fast32_t unique_RNTIs; // Using atomic for thread-safety
    LockFreeQueue queue;
} DynamicArray;

// Initialize the dynamic array
void initDynamicArray(DynamicArray* dynArr, size_t initialCapacity) {
    dynArr->array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!dynArr->array) {
        perror("Failed to allocate memory for dynamic array");
        exit(EXIT_FAILURE);
    }
    dynArr->capacity = initialCapacity;
    dynArr->count = 0;
    atomic_init(&dynArr->unique_RNTIs, 0);
    initLockFreeQueue(&dynArr->queue);
}

// Resize the dynamic array
void resizeDynamicArray(DynamicArray* dynArr) {
    size_t newCapacity = dynArr->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T* newArray = (NFAPI_CRC_INDICATION_PDU_T*)realloc(dynArr->array, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newArray) {
        perror("Failed to reallocate memory for dynamic array");
        exit(EXIT_FAILURE);
    }
    dynArr->array = newArray;
    dynArr->capacity = newCapacity;
}

// Check if RNTI is unique
bool isRNTIUnique(DynamicArray* dynArr, unsigned int rnti) {
    for (size_t i = 0; i < dynArr->count; ++i) {
        if (dynArr->array[i].RNTI == rnti) {
            return false;
        }
    }
    return true;
}

// Add a new element to the dynamic array
void addElement(DynamicArray* dynArr, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&dynArr->mutex);

    if (!isRNTIUnique(dynArr, pdu.RNTI)) {
        printf("Duplicate RNTI detected: %u\n", pdu.RNTI);
        pthread_mutex_unlock(&dynArr->mutex);
        return;
    }

    if (dynArr->count == dynArr->capacity) {
        resizeDynamicArray(dynArr);
    }

    dynArr->array[dynArr->count++] = pdu;
    atomic_fetch_add(&dynArr->unique_RNTIs, 1);

    pthread_mutex_unlock(&dynArr->mutex);
}

// Retrieve an element by index
NFAPI_CRC_INDICATION_PDU_T getElement(DynamicArray* dynArr, size_t index) {
    if (index >= dynArr->count) {
        fprintf(stderr, "Index out of bounds\n");
        exit(EXIT_FAILURE);
    }
    return dynArr->array[index];
}

// Clean up resources
void cleanupDynamicArray(DynamicArray* dynArr) {
    pthread_mutex_lock(&dynArr->mutex);

    while (popFromLockFreeQueue(&dynArr->queue, NULL)) {
        // Drain the queue
    }

    free(dynArr->array);
    pthread_mutex_unlock(&dynArr->mutex);
    pthread_mutex_destroy(&dynArr->mutex);
}

int main() {
    DynamicArray dynArr;
    initDynamicArray(&dynArr, 10);

    NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 12345, .CRC_INDICATION_REL8_TAG = rand() % 2 };
    addElement(&dynArr, pdu);

    NFAPI_CRC_INDICATION_PDU_T retrievedPdu = getElement(&dynArr, 0);
    printf("Retrieved PDU: RX_UE_INFORMATION_TAG=%u, RNTI=%u, CRC_INDICATION_REL8_TAG=%d\n",
           retrievedPdu.RX_UE_INFORMATION_TAG, retrievedPdu.RNTI, retrievedPdu.CRC_INDICATION_REL8_TAG);

    cleanupDynamicArray(&dynArr);
    return 0;
}
