NFAPI_CRC_INDICATION_PDU_T* create_nfa_crc_indication_list(size_t max_size, size_t *actual_size) {
    NFAPI_CRC_INDICATION_PDU_T *list = NULL;
    int *rntis = malloc(max_size * sizeof(int));
    if (!rntis) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
