        int rnti = rand() % MAX_RNTI;

        for (size_t retry = 0; !is_unique(rntis, rnti, current_size); ++retry) {
            if (retry >= max_size - current_size) break; // Safety net
            rnti = (rnti + 1) % MAX_RNTI;
        }

        if (!is_unique(rntis, rnti, current_size)) {
            fprintf(stderr, "Failed to allocate unique RNTIs\n");
            free(list);
