        list[current_size].ue_info.rnti = rnti;
        list[current_size].ue_info.crc_tag.CRCFLAG = rand() % 2; // Random CRCFLAG value
        rntis[current_size] = rnti;

        ++current_size;
    }

    *actual_size = current_size;
    free(rntis);
    return list;
}

void destroy_nfa_crc_indication_list(NFAPI_CRC_INDICATION_PDU_T *list) {
