#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_LIST_SIZE 100
#define RNTI_RANGE_START 0x0001
#define RNTI_RANGE_END 0xFFFF
#define CHANNEL_MEASUREMENT_COUNT 10

typedef struct {
    unsigned short rnti;
} RX_UE_INFORMATION_TAG;

typedef struct {
    int crcflag; // Simulated CRCFLAG, randomly set to 0 or 1
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    unsigned short rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int timestamp; // Simplified representation of a timestamp
    unsigned int sequence_number;
    struct {
        float measurement_value;
    } channel_measurements[CHANNEL_MEASUREMENT_COUNT];
} FrameInfo;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct Node* next;
} NodeList;

typedef struct {
    NodeList* head;
    size_t size;
} PduList;

FrameInfo* create_frame_info_array(size_t count) {
    FrameInfo* frames = (FrameInfo*)calloc(count, sizeof(FrameInfo));
    if (!frames) {
        perror("Failed to allocate memory for FrameInfo array");
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        frames[i].timestamp = time(NULL); // Current timestamp
        frames[i].sequence_number = i + 1;

        for (int j = 0; j < CHANNEL_MEASUREMENT_COUNT; ++j) {
            // Simulate channel measurement values
            frames[i].channel_measurements[j].measurement_value = rand() % 100;
        }
    }

    return frames;
}

PduList* create_pdu_list(size_t max_size) {
    PduList* list = (PduList*)malloc(sizeof(PduList));
    if (!list) {
        perror("Failed to allocate memory for PDU List");
        return NULL;
    }

    list->head = NULL;
    list->size = 0;

    while (list->size < max_size) {
        NodeList* new_node = (NodeList*)malloc(sizeof(NodeList));
        if (!new_node) {
            perror("Failed to allocate memory for new Node");
            break;
        }

        unsigned short rnti = RNTI_RANGE_START + rand() % (RNTI_RANGE_END - RNTI_RANGE_START);

        // Ensure unique RNTI
        NodeList* current = list->head;
        while (current) {
            if (current->pdu.rnti == rnti) {
                free(new_node);
                break;
            }
            current = current->next;
        }

        new_node->pdu.rx_ue_info.rnti = rand(); // Simulate unique RX_UE_INFORMATION_TAG
        new_node->pdu.rnti = rnti;
        new_node->pdu.crc_indication.crcflag = rand() % 2;

        new_node->next = list->head;
        list->head = new_node;
        ++list->size;
    }

    return list;
}

void free_pdu_list(PduList* list) {
    NodeList* current = list->head;
    while (current) {
        NodeList* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

void free_frame_info_array(FrameInfo* frames, size_t count) {
    free(frames);
}

int main() {
    srand(time(NULL));

    size_t max_pdu_list_size = MAX_LIST_SIZE;
    PduList* pdu_list = create_pdu_list(max_pdu_list_size);

    if (!pdu_list) {
        fprintf(stderr, "Failed to create PDU list\n");
        return EXIT_FAILURE;
    }

    size_t frame_count = 10; // Example count
    FrameInfo* frames = create_frame_info_array(frame_count);

    if (!frames) {
        free_pdu_list(pdu_list);
        fprintf(stderr, "Failed to create Frame Info array\n");
        return EXIT_FAILURE;
    }

    // Simulate periodic updates by iterating over the PDU list and frame info

    for (NodeList* node = pdu_list->head; node != NULL; node = node->next) {
        printf("RNTI: %u, CRCFLAG: %d\n", node->pdu.rnti, node->pdu.crc_indication.crcflag);
    }

    for (size_t i = 0; i < frame_count; ++i) {
        printf("Frame %lu - Timestamp: %d, Sequence Number: %u\n",
               i + 1, frames[i].timestamp, frames[i].sequence_number);
    }

    // Clean up
    free_pdu_list(pdu_list);
    free_frame_info_array(frames, frame_count);

    return EXIT_SUCCESS;
}
