// Mock function to get system load and resource availability
int getSystemLoadAndResources() {
    // For demonstration purposes, return a value between 1000 and 5000 based on current time's seconds value
    std::random_device rd;
    std::mt19937 eng(rd());
    std::uniform_int_distribution<> distr(1000, 5000);
    return distr(eng);
}

// Mock function to log information
