class NFAPIManager {
public:
    void populateNFAPIListAndSelectStrategy(int N);

private:
    static constexpr size_t MAX_ENTRIES = 5000;
    std::vector<NFAPI_CRC_INDICATION_PDU_T> nfaPiList;
    mutable std::mutex mtx;
    int selectedStrategy = -1;
    std::chrono::steady_clock::time_point lastSwitchTime;

    void selectStrategy();
};

void NFAPIManager::populateNFAPIListAndSelectStrategy(int N) {
    {
        std::lock_guard<std::mutex> lock(mtx);
        nfaPiList.clear();

        int maxEntries = getSystemLoadAndResources();
        maxEntries = (maxEntries > MAX_ENTRIES) ? MAX_ENTRIES : maxEntries;

        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> tagDistr(1, 1000);
        std::uniform_int_distribution<> rntiDistr(1, 500);
        std::uniform_int_distribution<> crcflagDistr(0, 1);

        for (int i = 0; i < N && nfaPiList.size() < static_cast<size_t>(maxEntries); ++i) {
            int tag = tagDistr(gen);
            int rnti = rntiDistr(gen);
            bool crcflag = crcflagDistr(gen);

            nfaPiList.emplace_back(tag, rnti, crcflag);
        }

        log("Populated NFAPI list with " + std::to_string(nfaPiList.size()) + " entries.");
    }

    selectStrategy();
}

void NFAPIManager::selectStrategy() {
    std::lock_guard<std::mutex> lock(mtx);

    auto now = std::chrono::steady_clock::now();
    if (std::chrono::duration_cast<std::chrono::seconds>(now - lastSwitchTime).count() < 8) {
        log("Cooldown period active. Cannot switch strategy.");
        return;
    }

    int newStrategy = rand() % 3 + 1; // Select one of three strategies

    selectedStrategy = newStrategy;
    lastSwitchTime = now;

    log("Selected strategy: " + std::to_string(newStrategy));
}

int main() {
    NFAPIManager manager;

    // Example usage
    manager.populateNFAPIListAndSelectStrategy(1000);  // Populate with 1000 entries

    return 0;
}
