#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define LOG_LEVEL_DEBUG 1
#define LOG_LEVEL_INFO 2

typedef struct {
    int field1; // Example fields for demonstration
} MAC_HEADER;

typedef struct {
    int field2;
} PHY_HEADER;

typedef struct {
    char data[256];
} PAYLOAD;

typedef struct {
    MAC_HEADER mac_header;
    PHY_HEADER phy_header;
    PAYLOAD payload;
} MAC_PACKET_T;

pthread_mutex_t allocation_lock = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file = NULL;

void log_message(int level, const char *format, ...) {
    if (level < LOG_LEVEL_DEBUG) return; // Example logging filter

    va_list args;
    va_start(args, format);

    static pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&log_lock);

    if (!log_file) {
        log_file = fopen("packet_log.txt", "a");
        if (!log_file) {
            fprintf(stderr, "Failed to open log file.\n");
            exit(EXIT_FAILURE);
        }
    }

    vfprintf(log_file, format, args);
    fflush(log_file); // Ensure logs are written promptly

    pthread_mutex_unlock(&log_lock);

    va_end(args);
}

MAC_PACKET_T* allocate_packets(size_t N) {
    MAC_PACKET_T *packets = NULL;
    size_t total_size = N * sizeof(MAC_PACKET_T);

    pthread_mutex_lock(&allocation_lock);
    packets = (MAC_PACKET_T*)malloc(total_size);
    if (!packets) {
        log_message(LOG_LEVEL_INFO, "Memory allocation failed for %zu packets.\n", N);
        pthread_mutex_unlock(&allocation_lock);
        return NULL;
    }
    memset(packets, 0, total_size);

    // Initialize and validate each packet
    for (size_t i = 0; i < N; i++) {
        packets[i].mac_header.field1 = rand() % 100; // Example initialization
        packets[i].phy_header.field2 = rand() % 100;
        snprintf(packets[i].payload.data, sizeof(packets[i].payload.data), "Payload data %zu", i);

        if (!packets[i].mac_header.field1 || !packets[i].phy_header.field2) {
            log_message(LOG_LEVEL_DEBUG, "Validation failed for packet index: %zu\n", i);
            free(packets);
            pthread_mutex_unlock(&allocation_lock);
            return NULL;
        }

        log_message(LOG_LEVEL_DEBUG, "Created MAC_PACKET_T at index %zu. MAC_HEADER: %d, PHY_HEADER: %d, PAYLOAD: %s\n",
                    i, packets[i].mac_header.field1, packets[i].phy_header.field2,
                    packets[i].payload.data);
    }
    pthread_mutex_unlock(&allocation_lock);

    return packets;
}

void free_packets(MAC_PACKET_T *packets) {
    if (!packets) return;

    pthread_mutex_lock(&allocation_lock);
    free(packets);
    pthread_mutex_unlock(&allocation_lock);

    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}
