    printf("Added element with RNTI: %u\n", element.RNTI);

    pthread_mutex_unlock(&da->lock);
}

// Remove an element from the dynamic array by index
void removeElement(DynamicArray *da, size_t index) {
    if (index >= da->size) return;

    pthread_mutex_lock(&da->lock);

    memmove(&da->array[index], &da->array[index + 1], (da->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    da->size--;

    // Log removal
    printf("Removed element at index: %zu\n", index);

    pthread_mutex_unlock(&da->lock);
}

// Periodically verify the integrity of the array
void* verifyIntegrity(void *arg) {
