#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>

#define MAX_RNTI 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int parent;
    int rank;
} UnionFindNode;

UnionFindNode uf[MAX_RNTI];

// Function to find the root of a node
int find(int u) {
    if (uf[u].parent != u)
        uf[u].parent = find(uf[u].parent);
    return uf[u].parent;
}

// Function to union two sets
void unite(int u, int v) {
    int rootU = find(u);
    int rootV = find(v);

    if (rootU != rootV) {
        if (uf[rootU].rank < uf[rootV].rank)
            uf[rootU].parent = rootV;
        else if (uf[rootU].rank > uf[rootV].rank)
            uf[rootV].parent = rootU;
        else {
            uf[rootV].parent = rootU;
            uf[rootU].rank++;
        }
    }
}

// Function to apply CRC hash function on RNTI
uint8_t crc_hash(int rnti) {
    return (rnti ^ (rnti >> 4)) & 0xFF; // Example hash function
}

int processRNTIRegistrations(int *rntis, int size) {
    memset(uf, -1, sizeof(uf));
    for (int i = 0; i < MAX_RNTI; ++i)
        uf[i].parent = i;

    NFAPI_CRC_INDICATION_PDU_T pdu_list[size];
    int disjointPairs = 0;
    clock_t start, end;
    double cpu_time_used;

    for (int i = 0; i < size; ++i) {
        if (rntis[i] >= MAX_RNTI || rntis[i] < 0) continue; // Handle out-of-bounds RNTI

        int rootRNTI = find(rntis[i]);
        if (uf[rootRNTI].rank == 0) { // New set
            pdu_list[i].RX_UE_INFORMATION_TAG = i;
            pdu_list[i].RNTI = rntis[i];
            pdu_list[i].CRC_INDICATION_REL8_TAG = crc_hash(rntis[i]);
        } else {
            disjointPairs++;
            unite(rntis[i], rootRNTI);
        }
    }

    for (int i = 0; i < size; ++i) {
        for (int j = i + 1; j < size; ++j) {
            if (rntis[i] >= MAX_RNTI || rntis[j] >= MAX_RNTI || rntis[i] < 0 || rntis[j] < 0)
                continue;

            start = clock();
            int rootI = find(rntis[i]);
            int rootJ = find(rntis[j]);

            end = clock();
            cpu_time_used = ((double) (end - start)) / CLOCKS_PER_SEC * 1000; // milliseconds
            printf("Time taken for disjoint check between %d and %d: %.2f ms\n", rntis[i], rntis[j], cpu_time_used);

            if (rootI != rootJ)
                unite(rntis[i], rntis[j]);
        }
    }

    return disjointPairs;
}
