#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_MESSAGE_LENGTH 256

typedef struct LOG_EVENT_RECORD {
    int EVENT_ID;
    time_t TIMESTAMP;
    int SOURCE_ID;
    char MESSAGE[MAX_MESSAGE_LENGTH];
    struct LOG_EVENT_RECORD *next;
} LOG_EVENT_RECORD;

typedef struct {
    LOG_EVENT_RECORD *head;
    pthread_mutex_t mutex;
    size_t count;
} DynamicList;

void log_framework(const char *operation, const char *details) {
    // Placeholder for integration with the logging framework
    printf("Log: %s - %s\n", operation, details);
}

int insert_record(DynamicList *list, int event_id, time_t timestamp, int source_id, const char *message) {
    if (strlen(message) >= MAX_MESSAGE_LENGTH) {
        log_framework("Error", "Message too long, potential buffer overflow");
        return -1;
    }

    LOG_EVENT_RECORD *new_record = malloc(sizeof(LOG_EVENT_RECORD));
    if (!new_record) {
        log_framework("Error", "Memory allocation failed");
        return -1;
    }

    new_record->EVENT_ID = event_id;
    new_record->TIMESTAMP = timestamp;
    new_record->SOURCE_ID = source_id;
    strncpy(new_record->MESSAGE, message, MAX_MESSAGE_LENGTH);
    new_record->next = NULL;

    pthread_mutex_lock(&list->mutex);

    if (!list->head) {
        list->head = new_record;
    } else {
        LOG_EVENT_RECORD *current = list->head;
        while (current->next) {
            current = current->next;
        }
        current->next = new_record;
    }

    list->count++;
    pthread_mutex_unlock(&list->mutex);

    log_framework("Insert", "Record added successfully");
    return 0;
}

int delete_record(DynamicList *list, int event_id) {
    pthread_mutex_lock(&list->mutex);

    LOG_EVENT_RECORD *current = list->head;
    LOG_EVENT_RECORD *prev = NULL;

    while (current && current->EVENT_ID != event_id) {
        prev = current;
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->mutex);
        log_framework("Error", "Record not found for deletion");
        return -1;
    }

    if (prev) {
        prev->next = current->next;
    } else {
        list->head = current->next;
    }

    free(current);
    list->count--;
    pthread_mutex_unlock(&list->mutex);

    log_framework("Delete", "Record removed successfully");
    return 0;
}

LOG_EVENT_RECORD* retrieve_record(DynamicList *list, int event_id) {
    pthread_mutex_lock(&list->mutex);

    LOG_EVENT_RECORD *current = list->head;

    while (current && current->EVENT_ID != event_id) {
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->mutex);
        log_framework("Error", "Record not found for retrieval");
        return NULL;
    }

    log_framework("Retrieve", "Record accessed successfully");
    pthread_mutex_unlock(&list->mutex);

    return current;
}

void verify_and_reinitialize(DynamicList *list) {
    pthread_mutex_lock(&list->mutex);

    LOG_EVENT_RECORD *current = list->head;
    size_t valid_count = 0;

    while (current) {
        // Add validation logic here if necessary
        valid_count++;
        current = current->next;
    }

    if (valid_count != list->count) {
        log_framework("Warning", "Integrity check failed, reinitializing list");
        LOG_EVENT_RECORD *temp = list->head;

        while (list->head) {
            list->head = list->head->next;
            free(temp);
            temp = list->head;
        }

        list->count = 0;
    } else {
        log_framework("Info", "Integrity check passed");
    }

    pthread_mutex_unlock(&list->mutex);
}

DynamicList* create_list() {
    DynamicList *list = malloc(sizeof(DynamicList));
    if (!list) {
        log_framework("Error", "Failed to create list");
        return NULL;
    }
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    list->count = 0;
    return list;
}

void destroy_list(DynamicList *list) {
    pthread_mutex_lock(&list->mutex);

    LOG_EVENT_RECORD *current = list->head;

    while (current) {
        LOG_EVENT_RECORD *next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}
