        sleep(10); // Periodically clean up every 10 seconds
        pthread_mutex_lock(&mutex);
        for (size_t i = 0; i < tag_count; ++i) {
            if (allocated_tags[i] != NULL) {
                free(allocated_tags[i]->rx_ue_info_tag);
                free(allocated_tags[i]);
