        return NULL;
    }

    pthread_mutex_lock(&mutex);
    allocated_tags = (NFAPI_CRC_INDICATION_PDU_T**)realloc(allocated_tags, N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
