        result[i].RNTI = rnti;
        result[i].rx_ue_info_tag = malloc(sizeof(RX_UE_INFORMATION_TAG));
        if (!result[i].rx_ue_info_tag) {
            log_message("Memory allocation failed for RX_UE_INFORMATION_TAG.", LOG_LEVEL_INFO);
            break;
        }

        // Set the CRCFLAG with a random value
