        char log_msg[256];
        snprintf(log_msg, sizeof(log_msg), "RNTI: %u, RXUEInfoTag: %p, CRCFLAG: %d", rnti, result[i].rx_ue_info_tag, result[i].CRCFLAG);
        pthread_t thread;
        pthread_create(&thread, NULL, async_logging, strdup(log_msg));
    }

    pthread_mutex_unlock(&mutex);
    return result;
}

int main() {
    set_logging(stdout, LOG_LEVEL_DEBUG); // Set logging to stdout for demonstration
    size_t N = 1000;
