#include <pthread.h>

#define MAX_FRAMES 100
#define MIN_PAYLOAD_SIZE 64
#define MAX_PAYLOAD_SIZE 1500
#define MEMORY_THRESHOLD (MAX_FRAMES * (sizeof(MAC_FRAME_HEADER) + MAX_PAYLOAD_SIZE + sizeof(int)))

typedef struct {
    unsigned char* mac_frame_header;
    unsigned char* mac_payload;
    int frame_status; // e.g., FREE, IN_USE
} NICP_Frame;

typedef struct {
    NICP_Frame* frames[MAX_FRAMES];
    size_t total_allocated_memory;
    pthread_mutex_t lock;
} NICP_Pool;

void log_event(const char* message) {
    printf("NICP: %s\n", message);
}

int initialize_nicp_pool(NICP_Pool* pool, int max_frames, int min_payload_size, int max_payload_size) {
    if (!pool || max_frames <= 0 || min_payload_size < 1 || max_payload_size > MAX_PAYLOAD_SIZE ||
        min_payload_size > max_payload_size) {
        log_event("Invalid initialization parameters.");
        return -1;
    }

    pthread_mutex_init(&pool->lock, NULL);
    pool->total_allocated_memory = 0;

    for (int i = 0; i < max_frames && max_frames <= MAX_FRAMES; ++i) {
        NICP_Frame* frame = malloc(sizeof(NICP_Frame));
        if (!frame) {
            log_event("Memory allocation failed during initialization.");
            return -1;
        }

        size_t payload_size = min_payload_size + (rand() % (max_payload_size - min_payload_size + 1));
        frame->mac_frame_header = malloc(sizeof(MAC_FRAME_HEADER)); // Assuming MAC_FRAME_HEADER is defined elsewhere
        if (!frame->mac_frame_header) {
            free(frame);
            log_event("Memory allocation failed for header.");
            return -1;
        }

        frame->mac_payload = malloc(payload_size);
        if (!frame->mac_payload) {
            free(frame->mac_frame_header);
            free(frame);
            log_event("Memory allocation failed for payload.");
            return -1;
        }

        frame->frame_status = 0; // Assume 0 is FREE

        pthread_mutex_lock(&pool->lock);
        pool->frames[i] = frame;
        pool->total_allocated_memory += sizeof(NICP_Frame) + sizeof(MAC_FRAME_HEADER) + payload_size;
        if (pool->total_allocated_memory > MEMORY_THRESHOLD) {
            log_event("Memory threshold exceeded.");
            return -1;
        }
        pthread_mutex_unlock(&pool->lock);
    }

    log_event("NICP pool initialized successfully.");
    return 0;
}

void iterate_over_frames(NICP_Pool* pool, void (*process_frame)(NICP_Frame*)) {
    if (!pool || !process_frame) return;

    pthread_mutex_lock(&pool->lock);
    for (int i = 0; i < MAX_FRAMES && pool->frames[i]; ++i) {
        process_frame(pool->frames[i]);
    }
    pthread_mutex_unlock(&pool->lock);
}

// Example usage
void example_processing(NICP_Frame* frame) {
    // User-defined processing logic here
}

int main() {
    NICP_Pool nicp_pool = {0};
    if (initialize_nicp_pool(&nicp_pool, 50, 128, 512) == 0) {
        iterate_over_frames(&nicp_pool, example_processing);
    }
    // Clean-up would be required here
    return 0;
}
