    size_t capacity;
    size_t count;
    pthread_mutex_t lock; // Mutex for thread safety
} LteDynamicArray;

// Function prototypes
void init_dynamic_array(LteDynamicArray *array);
void free_dynamic_array(LteDynamicArray *array);
bool resize_dynamic_array(LteDynamicArray *array, size_t new_capacity);
bool add_frame(LteDynamicArray *array, const MacPdu *mac_pdu);
void update_stats(LteDlFrame *frame);
void periodic_update_from_external_source(LteDynamicArray *array);

// Initialize the dynamic array
void init_dynamic_array(LteDynamicArray *array) {
    pthread_mutex_init(&array->lock, NULL);
    array->capacity = 10; // Initial capacity
    array->count = 0;
    array->frames = (LteDlFrame *)malloc(array->capacity * sizeof(LteDlFrame));
}

// Free the dynamic array
void free_dynamic_array(LteDynamicArray *array) {
    pthread_mutex_lock(&array->lock);
    free(array->frames);
    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
}

// Resize the dynamic array
bool resize_dynamic_array(LteDynamicArray *array, size_t new_capacity) {
    LteDlFrame *new_frames = (LteDlFrame *)realloc(array->frames, new_capacity * sizeof(LteDlFrame));
    if (!new_frames) return false;

    pthread_mutex_lock(&array->lock);
    array->frames = new_frames;
    array->capacity = new_capacity;
    pthread_mutex_unlock(&array->lock);
    return true;
}

// Add a frame to the dynamic array
bool add_frame(LteDynamicArray *array, const MacPdu *mac_pdu) {
    if (array->count == array->capacity) {
        if (!resize_dynamic_array(array, array->capacity * 2)) return false;
    }

    pthread_mutex_lock(&array->lock);
    array->frames[array->count].mac_pdu = *mac_pdu;
    update_stats(&array->frames[array->count]);
    array->count++;
    pthread_mutex_unlock(&array->lock);
    return true;
}

// Update the PHY STATS with realistic values
void update_stats(LteDlFrame *frame) {
    frame->phy_stats.snr = (double)(rand() % 100 + 10); // Example SNR value between 10 and 110
    frame->phy_stats.rx_bytes = rand() % 1500; // Example received bytes up to 1500
    frame->phy_stats.latency_ms = (double)(rand() % 50 + 5); // Example latency between 5ms and 55ms
}

// Simulate periodic updates from an external data source
void *periodic_update_from_external_source(void *arg) {
    LteDynamicArray *array = (LteDynamicArray *)arg;

    while (true) {
        pthread_mutex_lock(&array->lock);
        for (size_t i = 0; i < array->count; ++i) {
            // Simulate external data update
            array->frames[i].phy_stats.snr += (double)(rand() % 5 - 2); // Random small change in SNR
        }
        pthread_mutex_unlock(&array->lock);

        sleep(10); // Update every 10 seconds, handle network delays and failures as needed
    }

    return NULL;
}

// Example usage
int main() {
    LteDynamicArray array;
    init_dynamic_array(&array);

    MacPdu mac_pdu = { .mac_pdu_length = 100 };
    add_frame(&array, &mac_pdu);

    pthread_t update_thread;
    pthread_create(&update_thread, NULL, periodic_update_from_external_source, (void *)&array);
    pthread_detach(update_thread); // Detach the thread to run independently

    // Simulate application running
    sleep(60);

    free_dynamic_array(&array);
    return 0;
}
```

This code provides a basic implementation of a dynamic array for managing LTE DL FRAME structures with thread-safe operations and periodic updates from an external source. Adjustments may be needed based on specific requirements or constraints.']

