NFAPI_RX_FRAME_T* init_nfa_rx_frames(int num_frames, int max_symbols_per_frame) {
    if (num_frames <= 0 || max_symbols_per_frame < 0) {
        return NULL;
    }

    // Allocate memory for the frames
    NFAPI_RX_FRAME_T* frames = (NFAPI_RX_FRAME_T*)malloc(num_frames * sizeof(NFAPI_RX_FRAME_T));
    if (!frames) {
        perror("Failed to allocate memory for frames");
        exit(EXIT_FAILURE);
    }

    // Initialize each frame
    for (int i = 0; i < num_frames; ++i) {
        frames[i].UE_ID = i + 1;           // Example UE_ID assignment
        frames[i].RRC_STATE = 'Connected'; // Example RRC state

        // Allocate memory for symbols, initially with a minimal size to avoid fragmentation
        int initial_size = max_symbols_per_frame > 0 ? max_symbols_per_frame : 10;
        frames[i].symbols = (ComplexFloat*)malloc(initial_size * sizeof(ComplexFloat));

        if (!frames[i].symbols) {
            perror("Failed to allocate memory for symbols");
            exit(EXIT_FAILURE);
        }

        // Initialize symbol count
        frames[i].num_symbols = 0;

        // Optionally pre-allocate more space to reduce the need for resizing
        // This can be tuned based on expected usage patterns and available memory.
    }

    return frames;
}

// Function to add a received symbol to a frame
void add_symbol(NFAPI_RX_FRAME_T* frame, ComplexFloat symbol) {
    if (!frame || !symbol) {
        return;
    }

    // If needed, double the allocation size to handle more symbols efficiently
    int current_capacity = (frame->num_symbols > 0 ? frame->num_symbols : 1);
    while (current_capacity <= frame->num_symbols) {
        current_capacity *= 2; // Exponential growth to reduce frequent allocations
    }

    ComplexFloat* new_symbols = (ComplexFloat*)realloc(frame->symbols, current_capacity * sizeof(ComplexFloat));
    if (!new_symbols) {
        perror("Failed to reallocate memory for symbols");
        exit(EXIT_FAILURE);
    }

    frame->symbols = new_symbols;
    frame->symbols[frame->num_symbols++] = symbol;
}

// Function to validate the integrity of received symbols in each frame
int validate_symbols(NFAPI_RX_FRAME_T* frames, int num_frames) {
    if (!frames || num_frames <= 0) {
        return -1; // Error code for invalid input
    }

    for (int i = 0; i < num_frames; ++i) {
        for (int j = 0; j < frames[i].num_symbols; ++j) {
            ComplexFloat symbol = frames[i].symbols[j];

            if ((symbol.real * symbol.real + symbol.imag * symbol.imag) > NOISE_THRESHOLD) {
                return -2; // Error code for noise threshold violation
            }
        }
    }

    return 0; // Success
}

// Function to clean up resources used by the frames
void cleanup_nfa_rx_frames(NFAPI_RX_FRAME_T* frames, int num_frames) {
    if (!frames || num_frames <= 0) {
        return;
    }

    for (int i = 0; i < num_frames; ++i) {
        free(frames[i].symbols);
    }

    free(frames);
}

int main() {
    // Example usage
    int num_frames = 5;
    int max_symbols_per_frame = 10;

    NFAPI_RX_FRAME_T* frames = init_nfa_rx_frames(num_frames, max_symbols_per_frame);

    if (frames) {
        ComplexFloat symbol = {0.05f, 0.03f}; // Example symbol
        for (int i = 0; i < num_frames; ++i) {
            add_symbol(&frames[i], symbol);
        }

        int validation_result = validate_symbols(frames, num_frames);
        if (validation_result == 0) {
            printf("All symbols validated successfully.\n");
        } else {
            printf("Symbols failed validation. Error code: %d\n", validation_result);
        }

        cleanup_nfa_rx_frames(frames, num_frames);
    }

    return 0;
}
