List list = {NULL, PTHREAD_MUTEX_INITIALIZER, 0};

void initialize_list() {
    pthread_mutex_lock(&list.lock);
    if (!list.head) {
        list.head = NULL;
        list.size = 0;
    }
    pthread_mutex_unlock(&list.lock);
}

int insert_entry(NFAPI_CRC_INDICATION_PDU_T* entry) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1;

    new_node->data = *entry;
    new_node->next = NULL;

    pthread_mutex_lock(&list.lock);
    new_node->next = list.head;
    list.head = new_node;
    list.size++;
    pthread_mutex_unlock(&list.lock);

    // Garbage collection
    if (list.size > 10000) {
        Node* temp = list.head;
        list.head = list.head->next;
        free(temp);
        list.size--;
    }

    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* retrieve_entry(int index) {
    pthread_mutex_lock(&list.lock);

    Node* current = list.head;
    int count = 0;

    while (current && count < index) {
        current = current->next;
        count++;
    }

    if (!current) {
        pthread_mutex_unlock(&list.lock);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* entry = &current->data;
    pthread_mutex_unlock(&list.lock);

