typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* entries[MAX_ENTRIES];
    atomic_size_t size;
    pthread_mutex_t lock; // Mutex for thread safety
} NFAPI_Manager;

void init_manager(NFAPI_Manager* manager) {
    atomic_store(&manager->size, 0);
    pthread_mutex_init(&manager->lock, NULL);
}

int add_entry(NFAPI_Manager* manager, uint16_t rx_ue_tag, uint16_t rnti, uint8_t crc_tag) {
    if (atomic_load(&manager->size) >= MAX_ENTRIES) {
        fprintf(stderr, "Memory exhaustion: Cannot add more entries.\n");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T* entry = aligned_alloc(16, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!entry) {
        perror("Failed to allocate memory for new entry");
        return -2;
    }

    pthread_mutex_lock(&manager->lock);
    entry->RX_UE_INFORMATION_TAG = rx_ue_tag;
    entry->RNTI = rnti;
    entry->crc_data.CRC_INDICATION_REL8_TAG = crc_tag;

    // Random CRCFLAG generation and validation
    do {
        entry->crc_data.CRCFLAG = rand() & 0xFF; // Generate random CRCFLAG
    } while ((entry->crc_data.CRCFLAG & ~CRCFLAG_MASK) != 0); // Validate against mask

    manager->entries[atomic_fetch_add(&manager->size, 1)] = entry;
    pthread_mutex_unlock(&manager->lock);

    return 0;
}

void update_entries_periodically(NFAPI_Manager* manager) {
    while (true) {
        sleep(10); // Simulate periodic update every 10 seconds

        pthread_mutex_lock(&manager->lock);
        for (size_t i = 0; i < atomic_load(&manager->size); ++i) {
            // Example: Randomly modify CRCFLAG to simulate data source update
            manager->entries[i]->crc_data.CRCFLAG = rand() & 0xFF;
        }
        pthread_mutex_unlock(&manager->lock);
    }
}

void free_manager(NFAPI_Manager* manager) {
    for (size_t i = 0; i < atomic_load(&manager->size); ++i) {
        free(manager->entries[i]);
    }
    pthread_mutex_destroy(&manager->lock);
}

int main() {
    srand(time(NULL)); // Seed random number generator

    NFAPI_Manager manager;
    init_manager(&manager);

    if (add_entry(&manager, 1, 2, 3) != 0) {
        fprintf(stderr, "Failed to add entry.\n");
    }

    // Launch a separate thread for periodic updates
    pthread_t update_thread;
    pthread_create(&update_thread, NULL, (void*(*)(void*))update_entries_periodically, &manager);

    // Simulate program running
    sleep(60); 

    free_manager(&manager);
    pthread_cancel(update_thread);
    pthread_join(update_thread, NULL);

    return 0;
}
