#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
} DoublyLinkedList;

DoublyLinkedList* create_list() {
    DoublyLinkedList* list = malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(DoublyLinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

Node* create_node(const NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* node = malloc(sizeof(Node));
    if (!node) return NULL;
    *node->data = *data;
    node->next = node->prev = NULL;
    return node;
}

void free_node(Node* node) {
    free(node);
}

int append_to_list(DoublyLinkedList* list, const NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = create_node(data);
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    if (list->tail) {
        list->tail->next = new_node;
        new_node->prev = list->tail;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void* batch_populate(void* args) {
    DoublyLinkedList* list = (DoublyLinkedList*)args;
    const int BATCH_SIZE = 1000; // Configurable batch size
    NFAPI_CRC_INDICATION_PDU_T data;

    for (int i = 0; i < BATCH_SIZE; ++i) {
        data.RX_UE_INFORMATION_TAG = rand() % 256;
        data.RNTI = rand() % 65536;
        data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1;

        if (append_to_list(list, &data) != 0) {
            fprintf(stderr, "Memory allocation failed\n");
            break;
        }
    }

    return NULL;
}

void populate_list(DoublyLinkedList* list, int total_entries, int batch_size) {
    srand(time(NULL));
    pthread_t threads[total_entries / batch_size];

    for (int i = 0; i < total_entries / batch_size; ++i) {
        if (pthread_create(&threads[i], NULL, batch_populate, (void*)list)) {
            fprintf(stderr, "Error creating thread\n");
            break;
        }
    }

    for (int i = 0; i < total_entries / batch_size; ++i) {
        pthread_join(threads[i], NULL);
    }
}

void iterate_forward(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        printf("RX: %d, RNTI: %d, CRCFLAG: %d\n",
               current->data.RX_UE_INFORMATION_TAG,
               current->data.RNTI,
               current->data.CRC_INDICATION_REL8_TAG.CRCFLAG);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void iterate_backward(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->tail;
    while (current) {
        printf("RX: %d, RNTI: %d, CRCFLAG: %d\n",
               current->data.RX_UE_INFORMATION_TAG,
               current->data.RNTI,
               current->data.CRC_INDICATION_REL8_TAG.CRCFLAG);
        current = current->prev;
    }

    pthread_mutex_unlock(&list->lock);
}

int main() {
    int total_entries = 10000;
    int batch_size = 1000;

    DoublyLinkedList* list = create_list();
    if (!list) {
        fprintf(stderr, "Failed to create list\n");
        return -1;
    }

    populate_list(list, total_entries, batch_size);
    iterate_forward(list);
    iterate_backward(list);

    destroy_list(list);
    return 0;
}
