#include <stdio.h>
#include <string.h>
#include <time.h>

#define MAX_ENTRIES 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRCFLAG;
} CRC_INDICATION_REL8_TAG;

