    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu() {
    pthread_mutex_lock(&memory_pool.lock);

    if (memory_pool.used >= memory_pool.capacity) {
        log_event("Memory pool exhausted");
        pthread_mutex_unlock(&memory_pool.lock);
        return NULL;
    }

    void *ptr = ((char*)memory_pool.pool) + (memory_pool.used++ * memory_pool.block_size);
    pthread_mutex_unlock(&memory_pool.lock);

    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)ptr;

