    pdu->RX_UE_INFORMATION_TAG = rand() % 1000;
    pdu->crc_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    return pdu;
}

void adjust_memory_pool(size_t new_capacity) {
    pthread_mutex_lock(&memory_pool.lock);

    void *new_pool = realloc(memory_pool.pool, new_capacity * memory_pool.block_size);
    if (!new_pool && new_capacity > memory_pool.capacity) {
        log_event("Failed to expand memory pool");
        pthread_mutex_unlock(&memory_pool.lock);
        return;
    }

    if (new_pool) {
        memory_pool.pool = new_pool;
        memory_pool.capacity = new_capacity;
    }

    pthread_mutex_unlock(&memory_pool.lock);
}

void cleanup_memory_pool() {
    pthread_mutex_destroy(&memory_pool.lock);
    free(memory_pool.pool);
