#define MAX_FRAMES 10000
#define NOISE_THRESHOLD 0.1

typedef struct {
    float real;
    float imag;
} complex_float;

typedef enum {
    IDLE,
    CONNECTED,
    HANDOFF,
    // Add other states as needed
} RRC_STATE;

typedef struct {
