    RRC_STATE rrc_state;
    size_t num_symbols;
    complex_float *symbols;
    int update_count;
} NFAPI_RX_FRAME_T;

typedef struct {
    NFAPI_RX_FRAME_T *frames[MAX_FRAMES];
    size_t frame_count;
} FrameArray;

FrameArray* init_frame_array() {
    FrameArray *fa = (FrameArray*)malloc(sizeof(FrameArray));
    if (!fa) return NULL;
    memset(fa, 0, sizeof(FrameArray));
    return fa;
}

int add_frame(FrameArray *fa, int ue_id, RRC_STATE state, size_t num_symbols, complex_float *symbols) {
    if (fa->frame_count >= MAX_FRAMES) return -1;

    NFAPI_RX_FRAME_T *new_frame = (NFAPI_RX_FRAME_T*)malloc(sizeof(NFAPI_RX_FRAME_T));
    if (!new_frame) return -1;

    new_frame->UE_ID = ue_id;
    new_frame->rrc_state = state;
    new_frame->num_symbols = num_symbols;

    new_frame->symbols = (complex_float*)malloc(num_symbols * sizeof(complex_float));
    if (!new_frame->symbols) {
        free(new_frame);
        return -1;
    }

    memcpy(new_frame->symbols, symbols, num_symbols * sizeof(complex_float));
    new_frame->update_count = 0;

    fa->frames[fa->frame_count++] = new_frame;
    return 0;
}

void validate_frames(FrameArray *fa) {
    for (size_t i = 0; i < fa->frame_count; ++i) {
        NFAPI_RX_FRAME_T *frame = fa->frames[i];
        int valid = 1;

        for (size_t j = 0; j < frame->num_symbols; ++j) {
            double magnitude = cabsf(frame->symbols[j]);
            if (magnitude > NOISE_THRESHOLD) {
                valid = 0;
                break;
            }
        }

        if (!valid) {
            printf("Frame %d has invalid symbols\n", frame->UE_ID);
        }
    }
}

void update_frame(FrameArray *fa, int ue_id, size_t num_symbols, complex_float *symbols) {
    for (size_t i = 0; i < fa->frame_count; ++i) {
        if (fa->frames[i]->UE_ID == ue_id) {
            free(fa->frames[i]->symbols);

            fa->frames[i]->num_symbols = num_symbols;
            fa->frames[i]->symbols = (complex_float*)malloc(num_symbols * sizeof(complex_float));
            memcpy(fa->frames[i]->symbols, symbols, num_symbols * sizeof(complex_float));

            fa->frames[i]->update_count++;
            return;
        }
    }

    // If frame not found, add a new one
    add_frame(fa, ue_id, IDLE, num_symbols, symbols);  // Assuming state as IDLE for simplicity
}

void export_frames_to_file(FrameArray *fa, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&fa->frame_count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < fa->frame_count; ++i) {
        NFAPI_RX_FRAME_T *frame = fa->frames[i];

        fwrite(&frame->UE_ID, sizeof(int), 1, file);
        fwrite(&frame->rrc_state, sizeof(RRC_STATE), 1, file);
        fwrite(&frame->num_symbols, sizeof(size_t), 1, file);

        for (size_t j = 0; j < frame->num_symbols; ++j) {
            fwrite(&frame->symbols[j], sizeof(complex_float), 1, file);
        }
    }

    fclose(file);
}

void free_frame_array(FrameArray *fa) {
    for (size_t i = 0; i < fa->frame_count; ++i) {
        NFAPI_RX_FRAME_T *frame = fa->frames[i];
        if (frame) {
            free(frame->symbols);
            free(frame);
        }
    }

    free(fa);
}
