// Definition of NFAPI_CRC_INDICATION_PDU_T structure.
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    uint32_t CRC_INDICATION_REL8_TAG; // Assume this contains a CRC flag
} NFAPI_CRC_INDICATION_PDU_T;

// Node for the dynamic array with linked list segments to minimize fragmentation.
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Dynamic array structure with mutex for thread safety.
typedef struct {
    Node* head;
    size_t length;
    pthread_mutex_t lock; // Mutex for thread-safe access
} DynamicArray;

DynamicArray* create_array() {
    DynamicArray* arr = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!arr) return NULL;

    arr->head = NULL;
    arr->length = 0;
    pthread_mutex_init(&arr->lock, NULL);
    return arr;
}

void destroy_array(DynamicArray* arr) {
    Node* current = arr->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&arr->lock);
    free(arr);
}

// Helper function to log operations.
void log_operation(const char* operation, int thread_id) {
    time_t now = time(NULL);
    printf("[%s] Operation: %s by Thread ID: %d\n", ctime(&now), operation, thread_id);
}

NFAPI_CRC_INDICATION_PDU_T generate_random_crc_pdu() {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = rand(); // Assume random generation for demo
    pdu.RNTI = rand();
    pdu.CRC_INDICATION_REL8_TAG = rand(); // Random CRC flag
    return pdu;
}

void add_element(DynamicArray* arr, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&arr->lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&arr->lock);
        return;
    }

    new_node->data = element;
    new_node->next = arr->head;
    arr->head = new_node;
    arr->length++;

    log_operation("Add Element", (int)pthread_self());

    pthread_mutex_unlock(&arr->lock);
}

NFAPI_CRC_INDICATION_PDU_T get_element(DynamicArray* arr, size_t index) {
    pthread_mutex_lock(&arr->lock);

    Node* current = arr->head;
    for (size_t i = 0; current && i < index; ++i) {
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&arr->lock);
        return (NFAPI_CRC_INDICATION_PDU_T){0}; // Return zero-initialized structure on failure
    }

    NFAPI_CRC_INDICATION_PDU_T result = current->data;
    log_operation("Get Element", (int)pthread_self());

    pthread_mutex_unlock(&arr->lock);

    return result;
}

void serialize_array(DynamicArray* arr, char** output_buffer, size_t* buffer_size) {
    // Simple serialization logic
    pthread_mutex_lock(&arr->lock);

    *buffer_size = sizeof(size_t) + arr->length * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    *output_buffer = (char*)malloc(*buffer_size);
    if (!*output_buffer) {
        pthread_mutex_unlock(&arr->lock);
        return;
    }

    memcpy(*output_buffer, &arr->length, sizeof(size_t));
    Node* current = arr->head;
    char* buffer_ptr = *output_buffer + sizeof(size_t);

    for (size_t i = 0; current && i < arr->length; ++i) {
        memcpy(buffer_ptr, &(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T));
        buffer_ptr += sizeof(NFAPI_CRC_INDICATION_PDU_T);
        current = current->next;
    }

    log_operation("Serialize Array", (int)pthread_self());

    pthread_mutex_unlock(&arr->lock);
}

void deserialize_array(char* input_buffer, DynamicArray** arr) {
    // Simple deserialization logic
    size_t length;
    memcpy(&length, input_buffer, sizeof(size_t));

    *arr = create_array();
    if (!*arr) return;

    char* buffer_ptr = input_buffer + sizeof(size_t);
    for (size_t i = 0; i < length; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        memcpy(&pdu, buffer_ptr, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        add_element(*arr, pdu);
        buffer_ptr += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    log_operation("Deserialize Array", (int)pthread_self());
}

// Health check function for array integrity.
void health_check(DynamicArray* arr) {
    pthread_mutex_lock(&arr->lock);

    Node* current = arr->head;
    size_t count = 0;

    while (current) {
        if (!current->data.RX_UE_INFORMATION_TAG || !current->data.RNTI || !current->data.CRC_INDICATION_REL8_TAG) {
            log_operation("Data Integrity Issue Detected", (int)pthread_self());
        }
        current = current->next;
        count++;
    }

    if (count != arr->length) {
        log_operation("Array Length Mismatch", (int)pthread_self());
    } else {
        printf("Health check passed. Array length: %zu\n", arr->length);
    }

    pthread_mutex_unlock(&arr->lock);
}

// Example usage
int main() {
    srand(time(NULL)); // Seed for random number generation

    DynamicArray* my_array = create_array();
    if (!my_array) return EXIT_FAILURE;

    add_element(my_array, generate_random_crc_pdu());

    NFAPI_CRC_INDICATION_PDU_T pdu = get_element(my_array, 0);
    printf("Retrieved PDU: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%u\n",
           pdu.RX_UE_INFORMATION_TAG, pdu.RNTI, pdu.CRC_INDICATION_REL8_TAG);

    char* serialized_data = NULL;
    size_t serialized_size = 0;

    serialize_array(my_array, &serialized_data, &serialized_size);

    DynamicArray* new_array = NULL;
    deserialize_array(serialized_data, &new_array);

    health_check(new_array);

    free(serialized_data);
    destroy_array(my_array);
    destroy_array(new_array);

    return EXIT_SUCCESS;
}
