    return n * sizeof(NFAPI_CRC_INDICATION_PDU_T) + (n > 1000 ? n / 2 : n); 
}

PDU_LIST_MANAGER* create_pdu_list_manager(size_t initial_size) {
    PDU_LIST_MANAGER* manager = malloc(sizeof(PDU_LIST_MANAGER));
    if (!manager) {
        fprintf(stderr, "Failed to allocate memory for PDU list manager\n");
        return NULL;
    }

    manager->pdu_list = malloc(adjust_memory_allocation(initial_size));
    if (!manager->pdu_list) {
        fprintf(stderr, "Failed to allocate initial memory for PDU list\n");
        free(manager);
        return NULL;
    }

    manager->count = 0;
    pthread_mutex_init(&manager->list_mutex, NULL);
    initialize_history(manager->history);
    manager->history_index = 0;

    return manager;
}

void update_pdu_list(PDU_LIST_MANAGER* manager, size_t n) {
