        memset(manager->pdu_list[i].RX_UE_INFORMATION_TAG, rand() % 256, sizeof(manager->pdu_list[i].RX_UE_INFORMATION_TAG));
        manager->pdu_list[i].crc_tag.CRCFLAG = rand() & 1;

        int history_idx = (manager->history_index + i) % MAX_HISTORY_SIZE;
        manager->history[history_idx] = manager->pdu_list[i].crc_tag;
    }

    manager->count = n;
    manager->history_index = (manager->history_index + n) % MAX_HISTORY_SIZE;

    pthread_mutex_unlock(&manager->list_mutex);
}

void serialize_pdu_list(const PDU_LIST_MANAGER* manager, const char* filename) {
    if (!manager || !filename) return;

    FILE* file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for serialization\n");
