    fwrite(manager->pdu_list, sizeof(NFAPI_CRC_INDICATION_PDU_T), manager->count, file);

    pthread_mutex_unlock(&manager->list_mutex);
    fclose(file);
}

void destroy_pdu_list_manager(PDU_LIST_MANAGER* manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->list_mutex);

    free(manager->pdu_list);

    pthread_mutex_unlock(&manager->list_mutex);
    pthread_mutex_destroy(&manager->list_mutex);
    free(manager);
}

