#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ELEMENTS 10000000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    char CRCFLAG; // Assume '1' for good quality, '0' for poor
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    pthread_mutex_t lock; // For thread safety
} CRCList;

// Function to create a new node
Node* create_node(NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        return NULL;
    }
    newNode->data = pdu;
    newNode->next = NULL;
    return newNode;
}

// Function to initialize CRCList
CRCList* init_crc_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) {
        return NULL;
    }
    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Function to validate NFAPI_CRC_INDICATION_PDU_T
int is_valid_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pdu || pdu->RX_UE_INFORMATION_TAG < 0 ||
        pdu->RNTI <= 0 || pdu->CRC_INDICATION_REL8_TAG < 0 ||
        (pdu->CRCFLAG != '1' && pdu->CRCFLAG != '0')) {
        return 0;
    }
    return 1;
}

// Function to add a new PDU
int add_pdu(CRCList* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!list || !is_valid_pdu(pdu)) {
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    Node* newNode = create_node(*pdu);
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        // Log out-of-memory error
        fprintf(stderr, "Failed to allocate memory for new node\n");
        return -1;
    }

    newNode->next = list->head;
    list->head = newNode;
    list->count++;

    pthread_mutex_unlock(&list->lock);

    return 0;
}

// Function to serialize the CRCList
int serialize_crc_list(CRCList* list, const char* filename) {
    if (!list || !filename) {
        return -1;
    }

    FILE* file = fopen(filename, "wb");
    if (!file) {
        // Log file open error
        fprintf(stderr, "Failed to open file for writing\n");
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    fclose(file);

    pthread_mutex_unlock(&list->lock);

    return 0;
}

// Function to deserialize the CRCList
CRCList* deserialize_crc_list(const char* filename) {
    if (!filename) {
        return NULL;
    }

    FILE* file = fopen(filename, "rb");
    if (!file) {
        // Log file open error
        fprintf(stderr, "Failed to open file for reading\n");
        return NULL;
    }

    CRCList* list = init_crc_list();
    if (!list) {
        fclose(file);
        return NULL;
    }

    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T pdu;
    while (fread(&pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        add_pdu(list, &pdu);
    }

    fclose(file);

    pthread_mutex_unlock(&list->lock);

    return list;
}

// Cleanup function
void free_crc_list(CRCList* list) {
    if (!list) {
        return;
    }

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example logging function for capturing performance metrics
void log_performance_metrics() {
    // Placeholder for actual logging implementation
    printf("Logging performance metrics\n");
}
