    if (!cache) return NULL;

    cache->themePaths = (char **)malloc(initialSize * sizeof(char *));
    if (!cache->themePaths) {
        free(cache);
        return NULL;
    }

    cache->themeCount = 0;
    return cache;
}

void destroyThemeCache(ThemeCache *cache) {
    for (size_t i = 0; i < cache->themeCount; ++i) {
        free(cache->themePaths[i]);
    }
    free(cache->themePaths);
    free(cache);
}

// Function to process text files
char* processTextFile(const char *filePath) {
    FILE *file = fopen(filePath, "r");
    if (!file) return NULL;

    size_t bufferSize = 256;
    char *buffer = (char *)malloc(bufferSize);
    if (!buffer) {
        fclose(file);
        return NULL;
    }

    while (fgets(buffer, bufferSize, file)) {
        // Process each line
        char *lastComma = strrchr(buffer, ',');
        if (lastComma) {
            char *secondLastComma = strrchr(buffer, ',', lastComma - buffer - 1);
            if (secondLastComma) {
                int firstField = atoi(lastComma + 1);
                int secondField = atoi(secondLastComma + 1);
                float average = (firstField + secondField) / 2.0f;

                snprintf(lastComma + 1, bufferSize - (lastComma - buffer), "%.2f", average);
            }
        }
    }

    fclose(file);
    return buffer;
}

