CRCManager* create_crc_manager() {
    CRCManager *manager = (CRCManager *)malloc(sizeof(CRCManager));
    if (!manager) return NULL;
    manager->array = (NFAPI_CRC_INDICATION_PDU_T *)calloc(MAX_ENTRIES, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        free(manager);
        return NULL;
    }
    manager->active_entries = 0;
    return manager;
}

void destroy_crc_manager(CRCManager *manager) {
    if (manager) {
        free(manager->array);
        free(manager);
    }
}

int add_entry(CRCManager *manager, uint16_t rx_tag, uint32_t rnti) {
    if (!manager || manager->active_entries >= MAX_ENTRIES) return -1;

    for (size_t i = 0; i < manager->active_entries; ++i) {
        if (manager->array[i].RNTI == rnti) return -2;
    }

    NFAPI_CRC_INDICATION_PDU_T *entry = &manager->array[manager->active_entries++];
    entry->RX_UE_INFORMATION_TAG = rx_tag;
    entry->RNTI = rnti;
    entry->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1

    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_entry(CRCManager *manager, uint32_t rnti) {
    if (!manager) return NULL;

    for (size_t i = 0; i < manager->active_entries; ++i) {
        if (manager->array[i].RNTI == rnti) {
            return &manager->array[i];
        }
    }

    return NULL;
}

int update_crc_status(CRCManager *manager, uint32_t rnti, int crcflag) {
    if (!manager) return -1;

    for (size_t i = 0; i < manager->active_entries; ++i) {
        if (manager->array[i].RNTI == rnti) {
            manager->array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = crcflag;
            return 0;
        }
    }

    return -2;
}

void simulate_external_update(CRCManager *manager) {
    // Simulate periodic updates from an external source
    if (!manager) return;

    for (size_t i = 0; i < manager->active_entries; ++i) {
        // Randomly update CRCFLAG to simulate external changes
        manager->array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }
}

void log_status(CRCManager *manager) {
    if (!manager) return;

    printf("Active Entries: %zu\n", manager->active_entries);
    for (size_t i = 0; i < manager->active_entries; ++i) {
        printf("RNTI: %u, CRCFLAG: %d\n",
               manager->array[i].RNTI,
               manager->array[i].CRC_INDICATION_REL8_TAG.CRCFLAG);
    }
}

int main() {
    srand(time(NULL)); // Seed for random number generation

    CRCManager *manager = create_crc_manager();
    if (!manager) {
        fprintf(stderr, "Failed to create CRC manager\n");
        return 1;
    }

    add_entry(manager, 0x01, 1001);
    add_entry(manager, 0x02, 1002);

    log_status(manager);

    NFAPI_CRC_INDICATION_PDU_T *entry = get_entry(manager, 1001);
    if (entry) {
        printf("Retrieved Entry: RNTI %u, CRCFLAG %d\n", entry->RNTI, entry->CRC_INDICATION_REL8_TAG.CRCFLAG);
    }

    update_crc_status(manager, 1002, 1);

    log_status(manager);

    simulate_external_update(manager);

    log_status(manager);

    destroy_crc_manager(manager);
    return 0;
}
