    arr->size = 0;
    arr->array = malloc(arr->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&arr->lock, NULL);
}

// Resize the dynamic array when needed
void resize_crc_array(CRC_Array *arr) {
    pthread_mutex_lock(&arr->lock);

    if (arr->size >= arr->capacity) {
        arr->capacity *= 2;
        arr->array = realloc(arr->array, arr->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    pthread_mutex_unlock(&arr->lock);
}

// Add a new element to the dynamic array
