        exit(EXIT_FAILURE);  // Handle this more gracefully in production code
    }

    pthread_mutex_lock(&arr->lock);
    NFAPI_CRC_INDICATION_PDU_T pdu = arr->array[index];
    pthread_mutex_unlock(&arr->lock);

    return pdu;
}

// Free the dynamic array and its resources
