```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_CAPACITY 1024

typedef struct {
    int rnti;
    // Other fields...
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node** table;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_hash_table(size_t size) {
    HashTable* ht = malloc(sizeof(HashTable));
    ht->table = calloc(size, sizeof(Node*));
    ht->size = size;
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

unsigned int hash(int rnti, size_t size) {
    return (unsigned int)rnti % size;
}

void free_hash_table(HashTable* ht) {
    for (size_t i = 0; i < ht->size; ++i) {
        Node* node = ht->table[i];
        while (node) {
            Node* temp = node;
            node = node->next;
            free(temp);
        }
    }
    free(ht->table);
    pthread_mutex_destroy(&ht->lock);
    free(ht);
}

void hash_table_add(HashTable* ht, NFAPI_CRC_INDICATION_PDU_T data) {
    unsigned int index = hash(data.rnti, ht->size);
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return;
    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&ht->lock);
    if (ht->table[index]) {
        Node* current = ht->table[index];
        while (current->next) {
            current = current->next;
        }
        current->next = new_node;
    } else {
        ht->table[index] = new_node;
    }
    pthread_mutex_unlock(&ht->lock);
}

void hash_table_remove(HashTable* ht, int rnti) {
    unsigned int index = hash(rnti, ht->size);

    pthread_mutex_lock(&ht->lock);
    Node *current = ht->table[index], *prev = NULL;
    while (current && current->data.rnti != rnti) {
        prev = current;
        current = current->next;
    }
    if (!current) {
        pthread_mutex_unlock(&ht->lock);
        return;
    }
    if (prev) {
        prev->next = current->next;
    } else {
        ht->table[index] = current->next;
    }
    free(current);
    pthread_mutex_unlock(&ht->lock);
}

NFAPI_CRC_INDICATION_PDU_T* hash_table_search(HashTable* ht, int rnti) {
    unsigned int index = hash(rnti, ht->size);

    pthread_mutex_lock(&ht->lock);
    Node* current = ht->table[index];
    while (current && current->data.rnti != rnti) {
        current = current->next;
    }
    pthread_mutex_unlock(&ht->lock);

    if (current) return &current->data;
    return NULL;
}

void handle_external_data_updates(HashTable* ht, NFAPI_CRC_INDICATION_PDU_T* updates, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        // Validate RNTI and data format
        if (updates[i].rnti <= 0) continue;

        NFAPI_CRC_INDICATION_PDU_T* existing = hash_table_search(ht, updates[i].rnti);
        if (existing) {
            *existing = updates[i]; // Update existing entry
        } else {
            hash_table_add(ht, updates[i]); // Add new entry
        }
    }
}

void cleanup_and_exit(HashTable* ht) {
    free_hash_table(ht);
}

int main() {
    HashTable* ht = create_hash_table(101); // Prime number size for better distribution

    // Simulate external data update
    NFAPI_CRC_INDICATION_PDU_T updates[] = {{1, /* other fields */}, {2, /* other fields */}};
    handle_external_data_updates(ht, updates, 2);

    // Example usage
    hash_table_add(ht, (NFAPI_CRC_INDICATION_PDU_T){3, /* other fields */});
    NFAPI_CRC_INDICATION_PDU_T* found = hash_table_search(ht, 1);
    if (found) {
        printf("Found RNTI: %d\n", found->rnti);
    }

    cleanup_and_exit(ht);

    return 0;
}
