        manager->array[i] = NULL;
    }
    return manager;
}

void destroy_frame_manager(FrameManager *manager) {
    if (!manager) return;
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->array[i]);
    }
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_entry(FrameManager *manager, int rf_freq, int rssi) {
    if (!manager || manager->count >= MAX_ENTRIES) return -1;

    pthread_mutex_lock(&manager->lock);

    // Check for duplicate RF_FREQ
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->array[i]->phy_frame_info.RF_FREQ == rf_freq) {
            pthread_mutex_unlock(&manager->lock);
            return -2;
        }
    }

    // Allocate and initialize new entry
    NFAPI_RX_FRAME_PDU_T *new_entry = (NFAPI_RX_FRAME_PDU_T *)malloc(sizeof(NFAPI_RX_FRAME_PDU_T));
    if (!new_entry) {
        pthread_mutex_unlock(&manager->lock);
        return -3;
    }
    new_entry->phy_frame_info.RF_FREQ = rf_freq;
    new_entry->phy_frame_info.RSSI = rssi;

    manager->array[manager->count++] = new_entry;
    pthread_mutex_unlock(&manager->lock);

    return 0;
}

NFAPI_RX_FRAME_PDU_T* get_entry_by_rf_freq(FrameManager *manager, int rf_freq) {
    if (!manager) return NULL;

    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->array[i]->phy_frame_info.RF_FREQ == rf_freq) {
            NFAPI_RX_FRAME_PDU_T *entry = manager->array[i];
            pthread_mutex_unlock(&manager->lock);
            return entry;
        }
    }
    pthread_mutex_unlock(&manager->lock);

    return NULL;
}

int update_signal_quality(FrameManager *manager, int rf_freq, int new_rssi) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->array[i]->phy_frame_info.RF_FREQ == rf_freq) {
            manager->array[i]->phy_frame_info.RSSI = new_rssi;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);

    return -2; // Entry not found
}
