```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_CAPACITY 1000

typedef struct {
    int UE_ID;
    // Add SRS_INFO and MCS_TABLE fields as needed.
} NRUEContext;

typedef struct Node {
    NRUEContext context;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t count;
} ContextList;

// Function to create a new node
Node* create_node(int ue_id) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;

    new_node->context.UE_ID = ue_id;
    // Initialize SRS_INFO and MCS_TABLE as needed.
    new_node->next = NULL;

    return new_node;
}

// Function to initialize the context list
void init_context_list(ContextList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
}

// Function to add a new context
int add_context(ContextList* list, int ue_id) {
    if (list->count >= MAX_CAPACITY) return -1;

    Node* new_node = create_node(ue_id);
    if (!new_node) return -1;

    pthread_mutex_lock(&list->lock);

    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Function to remove a context by UE_ID
int remove_context(ContextList* list, int ue_id) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;

    while (current != NULL && current->context.UE_ID != ue_id) {
        prev = current;
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return -1; // UE_ID not found
    }

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    list->count--;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Function to update MCS_TABLE for a specific UE_ID
int update_mcs_table(ContextList* list, int ue_id) {
    // Assuming MCS_TABLE is part of NRUEContext and accessible.
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;

    while (current != NULL && current->context.UE_ID != ue_id) {
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return -1; // UE_ID not found
    }

    // Update MCS_TABLE here as needed.
    // Example: current->context.MCS_TABLE = new_mcs_table;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Function to free the context list
void free_context_list(ContextList* list) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *next_node;

    while (current != NULL) {
        next_node = current->next;
        free(current);
        current = next_node;
    }

    list->head = NULL;
    list->count = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Example usage
int main() {
    ContextList context_list;
    init_context_list(&context_list);

    add_context(&context_list, 1);
    update_mcs_table(&context_list, 1);
    remove_context(&context_list, 1);

    free_context_list(&context_list);
    return 0;
}
```

### Key Points:
- **Thread Safety**: The use of `pthread_mutex_t` ensures that the list can be safely accessed by multiple threads.
- **Error Handling**: Functions return `-1` on failure (e.g., when adding a context to a full list or removing/updating a non-existent UE_ID).
- **Memory Management**: Proper allocation and deallocation of nodes prevent memory leaks.
- **Capacity Limit**: The list has a maximum capacity (`MAX_CAPACITY`) to manage resources effectively.']

