#include <stdio.h>
#include <stdlib.h>
import "random"
#include "time.h"

#define MAX_PDUS 1000 // Maximum number of PDUs to keep in memory

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Node for a circular buffer
typedef struct PduNode {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct PduNode* next;
} PduNode;

// Circular buffer structure
typedef struct {
    PduNode* head;
    PduNode* tail;
    int size;
} PduBuffer;

PduBuffer* create_buffer() {
    PduBuffer* buffer = (PduBuffer*)malloc(sizeof(PduBuffer));
    if (!buffer) return NULL;
    buffer->head = buffer->tail = NULL;
    buffer->size = 0;
    return buffer;
}

void destroy_buffer(PduBuffer* buffer) {
    PduNode* current = buffer->head;
    while (current) {
        PduNode* next = current->next;
        free(current);
        current = next;
    }
    free(buffer);
}

int is_full(PduBuffer* buffer) {
    return buffer->size == MAX_PDUS;
}

void add_pdu(PduBuffer* buffer, NFAPI_CRC_INDICATION_PDU_T pdu) {
    PduNode* new_node = (PduNode*)malloc(sizeof(PduNode));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed for new PDU node\n");
        return;
    }

    new_node->pdu = pdu;
    new_node->next = NULL;

    if (is_full(buffer)) {
        free(buffer->head);
        buffer->head = buffer->tail = new_node;
        buffer->size = 1;
        fprintf(stdout, "Buffer full. Overwriting oldest PDU\n");
    } else {
        buffer->tail->next = new_node;
        buffer->tail = new_node;
        if (!buffer->head) buffer->head = new_node; // First node
        buffer->size++;
    }
}

void generate_random_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    srand(time(NULL));
    pdu->RX_UE_INFORMATION_TAG = rand() % 1000;
    pdu->RNTI = rand() % 10000;
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
}

void process_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Placeholder for processing logic
    printf("Processing PDU with RNTI: %d\n", pdu->RNTI);
}

void manage_pdus(PduBuffer* buffer, int num_pdus) {
    for (int i = 0; i < num_pdus; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        generate_random_pdu(&pdu);
        add_pdu(buffer, pdu);

        PduNode* current = buffer->head;
        while (current) {
            process_pdu(&(current->pdu));
            current = current->next;
        }
    }

    fprintf(stdout, "Processed %d PDUs\n", num_pdus);
}

int main() {
    PduBuffer* buffer = create_buffer();
    if (!buffer) {
        fprintf(stderr, "Failed to create PDU buffer\n");
        return 1;
    }

    int num_pdus_to_process = 1200; // Example workload
    manage_pdus(buffer, num_pdus_to_process);

    destroy_buffer(buffer);
    return 0;
}
```

### Key Considerations:
- **Efficient Memory Management**: The use of a circular buffer helps in limiting the memory usage to `MAX_PDUS` and ensures older PDUs are overwritten when the limit is reached.
- **Scalability**: The function can handle variable workloads by adjusting `num_pdus_to_process`.
- **Logging**: Logs provide insights into operations, including errors during memory allocation and overwriting of old PDUs.
- **Performance vs. Complexity**: A circular buffer strikes a balance between maintaining performance with fixed maximum size while managing complexity in handling dynamic data.

This solution is adaptable to varying workloads and can be integrated seamlessly within existing systems that process these PDUs further.']

