#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

#define MAX_LIST_SIZE 1000

typedef struct {
    uint8_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list;
    size_t count;
    pthread_mutex_t mutex;
    uint16_t rnti_range_min;
    uint16_t rnti_range_max;
    size_t max_unique_rntis;
} CRC_INDICATOR_LIST;

void initialize_crc_indicator_list(CRC_INDICATOR_LIST *indicator_list, size_t max_size,
                                   uint16_t rnti_min, uint16_t rnti_max, size_t max_unique) {
    indicator_list->list = malloc(max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    indicator_list->count = 0;
    pthread_mutex_init(&indicator_list->mutex, NULL);
    indicator_list->rnti_range_min = rnti_min;
    indicator_list->rnti_range_max = rnti_max;
    indicator_list->max_unique_rntis = max_unique;
}

void free_crc_indicator_list(CRC_INDICATOR_LIST *indicator_list) {
    if (indicator_list && indicator_list->list) {
        free(indicator_list->list);
        pthread_mutex_destroy(&indicator_list->mutex);
    }
}

uint16_t generate_random_rnti(CRC_INDICATOR_LIST *indicator_list, uint16_t last_rnti, uint16_t *used_rntis) {
    uint16_t new_rnti;
    do {
        new_rnti = indicator_list->rnti_range_min + (rand() % 
            (indicator_list->rnti_range_max - indicator_list->rnti_range_min + 1));
    } while ((new_rnti == last_rnti) || used_rntis[new_rnti]);

    used_rntis[new_rnti] = 1;
    return new_rnti;
}

void reset_used_rntis(uint16_t *used_rntis, uint16_t rnti_min, uint16_t rnti_max) {
    for (uint16_t i = rnti_min; i <= rnti_max; ++i) {
        used_rntis[i] = 0;
    }
}

void add_crc_pdu(CRC_INDICATOR_LIST *indicator_list) {
    if (indicator_list->count >= MAX_LIST_SIZE || indicator_list->max_unique_rntis == 0) {
        return;
    }

    pthread_mutex_lock(&indicator_list->mutex);

    uint16_t rnti_range = indicator_list->rnti_range_max - indicator_list->rnti_range_min + 1;
    static uint16_t used_rntis[rnti_range] = {0};
    uint8_t last_rnti = (indicator_list->count > 0) ? 
        indicator_list->list[indicator_list->count - 1].RNTI : ~0;

    while (indicator_list->max_unique_rntis == 0 || __sync_fetch_and_sub(&indicator_list->max_unique_rntis, 1) > 0) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % 256;
        pdu.RNTI = generate_random_rnti(indicator_list, last_rnti, used_rntis);
        pdu.CRC_INDICATION_REL8_TAG = rand();
        pdu.CRCFLAG = rand() % 2;

        indicator_list->list[indicator_list->count++] = pdu;

        if (indicator_list->count >= MAX_LIST_SIZE) {
            break;
        }
    }

    pthread_mutex_unlock(&indicator_list->mutex);
}

int main() {
    srand(time(NULL));

    CRC_INDICATOR_LIST list;
    initialize_crc_indicator_list(&list, MAX_LIST_SIZE, 1000, 2000, 50);

    // Simulate concurrent access
    const int num_threads = 10;
    pthread_t threads[num_threads];

    for (int i = 0; i < num_threads; ++i) {
