#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_MAX_PDUS 1000
#define CONFIG_UPDATE_INTERVAL_MS 5000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned char CRCFLAG; // Randomly set in function
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    int count;
    pthread_mutex_t lock;
    int max_pdus;
} LRUCache;

LRUCache cache;

void initialize_cache(int initial_max_pdus) {
    cache.head = NULL;
    cache.tail = NULL;
    cache.count = 0;
    cache.max_pdus = initial_max_pdus;
    pthread_mutex_init(&cache.lock, NULL);
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;

    new_node->pdu = pdu;
    new_node->prev = NULL;
    new_node->next = NULL;
    return new_node;
}

void move_to_front(Node* node) {
    if (node == cache.head) return;

    // Remove from current position
    if (node->prev) node->prev->next = node->next;
    if (node->next) node->next->prev = node->prev;
    if (cache.tail == node) cache.tail = node->prev;

    // Move to front
    node->next = cache.head;
    node->prev = NULL;
    if (cache.head) cache.head->prev = node;
    cache.head = node;

    if (!cache.tail) cache.tail = node;
}

void evict_lru() {
    if (!cache.tail) return;

    Node* lru_node = cache.tail;
    cache.tail = cache.tail->prev;
    if (cache.tail) cache.tail->next = NULL;
    cache.count--;

    free(lru_node);
}

void add_pdu(NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&cache.lock);

    // Check and evict LRU if necessary
    while (cache.count >= cache.max_pdus) {
        evict_lru();
    }

    Node* new_node = create_node(pdu);
    if (!new_node) {
        printf("Memory allocation failed\n");
        pthread_mutex_unlock(&cache.lock);
        return;
    }

    // Add to front
    new_node->next = cache.head;
    if (cache.head) cache.head->prev = new_node;
    cache.head = new_node;

    if (!cache.tail) cache.tail = new_node;
    cache.count++;

    pthread_mutex_unlock(&cache.lock);
}

void update_configuration(int new_max_pdus) {
    pthread_mutex_lock(&cache.lock);

    // Adjust the maximum PDUs allowed
    cache.max_pdus = new_max_pdus;

    while (cache.count > cache.max_pdus) {
        evict_lru();
    }

    pthread_mutex_unlock(&cache.lock);
}

void generate_random_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    srand(time(NULL));
    pdu->RX_UE_INFORMATION_TAG = rand() % 1000;
    pdu->RNTI = rand() % 1000;
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1; // Randomly set to 0 or 1
}

void process_pdus() {
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        generate_random_pdu(&pdu);
        add_pdu(pdu);

        // Simulate processing delay
        usleep(1000); 
    }
}

int main() {
    initialize_cache(INITIAL_MAX_PDUS);

    pthread_t producer_thread;
    if (pthread_create(&producer_thread, NULL, (void*)process_pdus, NULL) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    // Simulate dynamic configuration update
    sleep(10);
    update_configuration(500);

    pthread_join(producer_thread, NULL);
    return 0;
}
```

