#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>

#define MAX_STRUCTS 1024

typedef struct {
    uint32_t rnti;
    // Other fields...
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Global definitions
static NFAPI_CRC_INDICATION_PDU_T* array = NULL;
static size_t count = 0;
static const size_t max_capacity = MAX_STRUCTS;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static Node** hash_table = NULL; // Simple chaining for collision resolution

void initialize_memory_pool() {
    hash_table = calloc(max_capacity, sizeof(Node*));
}

uint32_t hash(uint32_t rnti) {
    return rnti % max_capacity;
}

NFAPI_CRC_INDICATION_PDU_T* find_by_rnti(uint32_t rnti) {
    uint32_t index = hash(rnti);
    Node* node = hash_table[index];

    while (node != NULL) {
        if (node->data.rnti == rnti)
            return &(node->data);
        node = node->next;
    }
    return NULL;
}

void add_pdu(NFAPI_CRC_INDICATION_PDU_T new_pdu) {
    pthread_mutex_lock(&mutex);

    if (count >= max_capacity) {
        printf("Error: Maximum capacity reached\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    size_t index = count++;
    array[index] = new_pdu;

    uint32_t hash_index = hash(new_pdu.rnti);
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        printf("Error: Memory allocation failed\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    new_node->data = new_pdu;
    new_node->next = hash_table[hash_index];
    hash_table[hash_index] = new_node;

    printf("Added PDU with RNTI %u\n", new_pdu.rnti);

    pthread_mutex_unlock(&mutex);
}

void remove_pdu_by_rnti(uint32_t rnti) {
    pthread_mutex_lock(&mutex);

    uint32_t hash_index = hash(rnti);
    Node *prev = NULL, *node = hash_table[hash_index];

    while (node != NULL) {
        if (node->data.rnti == rnti) {
            if (prev)
                prev->next = node->next;
            else
                hash_table[hash_index] = node->next;

            for (size_t i = 0; i < count; ++i) {
                if (array[i].rnti == rnti) {
                    memset(&array[i], 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
                    break;
                }
            }

            free(node);
            printf("Removed PDU with RNTI %u\n", rnti);

            pthread_mutex_unlock(&mutex);
            return;
        }
        prev = node;
        node = node->next;
    }

    printf("Error: PDU with RNTI %u not found\n", rnti);
    pthread_mutex_unlock(&mutex);
}

void cleanup() {
    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < max_capacity; ++i) {
        Node* node = hash_table[i];
        while (node != NULL) {
            Node* temp = node;
            node = node->next;
            free(temp);
        }
    }

    if (array)
        free(array);

    free(hash_table);
    pthread_mutex_unlock(&mutex);
}

int main() {
    initialize_memory_pool();

    array = malloc(max_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        printf("Error: Memory allocation failed for array\n");
        return 1;
    }

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T pdu = { .rnti = 12345 };
    add_pdu(pdu);

    remove_pdu_by_rnti(12345);

    cleanup();
    pthread_mutex_destroy(&mutex);

    return 0;
}
```

### Key Features:
