    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int is_duplicate(CRCDList* list, int rnti) {
    Node* current = list->head;
    while (current) {
        if (current->data.RNTI == rnti) return 1;
        current = current->next;
    }
    return 0;
}

void insert_node(CRCDList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);

    if (is_duplicate(list, data.RNTI)) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    memcpy(&new_node->data, &data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
}

void free_list(CRCDList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void print_list(CRCDList* list) {
    pthread_mutex_lock(&list->lock);

    Node* sorted = NULL;

    Node* current = list->head;
    while (current) {
        Node* next = current->next;

        if (!sorted || sorted->data.RNTI > current->data.RNTI) {
            current->next = sorted;
            sorted = current;
        } else {
            Node* temp = sorted;
            while (temp->next && temp->next->data.RNTI < current->data.RNTI) {
                temp = temp->next;
            }
            current->next = temp->next;
            temp->next = current;
        }

        current = next;
    }

    Node* traverse = sorted;
    while (traverse) {
        printf("RNTI: %d\n", traverse->data.RNTI);
        Node* temp = traverse;
        traverse = traverse->next;
        free(temp);
    }

    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T generate_random_pdu() {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RNTI = rand() % 1000; // Example range
    strcpy(pdu.RX_UE_INFORMATION_TAG, "ExampleTag");
    pdu.crcTag.CRCFLAG = rand() % 2;
    return pdu;
}

void* thread_function(void* arg) {
    CRCDList* list = (CRCDList*)arg;
    for (int i = 0; i < 100; ++i) { // Example loop count
        NFAPI_CRC_INDICATION_PDU_T pdu = generate_random_pdu();
        insert_node(list, pdu);
    }
    return NULL;
}

int main() {
    CRCDList* list = create_list();

    pthread_t threads[4];
    for (int i = 0; i < 4; ++i) { // Example thread count
        pthread_create(&threads[i], NULL, thread_function, list);
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    print_list(list);
    free_list(list);

    return 0;
}
```

### Key Points:
- **Thread Safety**: A mutex is used to ensure that only one thread can modify the list at a time.
- **Duplicate Handling**: The `is_duplicate` function checks for existing RNTI values before insertion.
- **Memory Management**: Memory allocation and deallocation are carefully managed to prevent leaks.
- **Sorting During Print**: The list is sorted during traversal to print RNTIs in ascending order.
- **Random Data Generation**: A helper function generates random PDU data.']

