#include <time.h>

#define INITIAL_CAPACITY 10

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG; // Randomly set for demonstration purposes
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Custom memory pool using a simple block allocator
#define POOL_SIZE 1024

typedef struct MemoryBlock {
    size_t size;
    void *memory;
    int free;
    struct MemoryBlock *next;
} MemoryBlock;

static MemoryBlock *freeList = NULL;
pthread_mutex_t memMutex = PTHREAD_MUTEX_INITIALIZER;

void initializeMemoryPool() {
    freeList = (MemoryBlock *)malloc(sizeof(MemoryBlock));
    freeList->size = POOL_SIZE - sizeof(MemoryBlock);
    freeList->memory = malloc(freeList->size);
    freeList->free = 1;
    freeList->next = NULL;
}

void *customAlloc(size_t size) {
    pthread_mutex_lock(&memMutex);

    MemoryBlock *current = freeList;
    while (current != NULL) {
        if (current->free && current->size >= size) {
            current->free = 0;
            pthread_mutex_unlock(&memMutex);
            return current->memory;
        }
        current = current->next;
    }

    MemoryBlock *newBlock = (MemoryBlock *)malloc(sizeof(MemoryBlock));
    newBlock->size = size > POOL_SIZE - sizeof(MemoryBlock) ? size : POOL_SIZE - sizeof(MemoryBlock);
    newBlock->memory = malloc(newBlock->size);
    newBlock->free = 0;
    newBlock->next = NULL;

    if (current != NULL) {
        current->next = newBlock;
    } else {
        freeList = newBlock;
    }

    pthread_mutex_unlock(&memMutex);
    return newBlock->memory;
}

void customFree(void *ptr) {
    pthread_mutex_lock(&memMutex);

    MemoryBlock *current = freeList;
    while (current != NULL) {
        if (current->memory == ptr) {
            current->free = 1;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&memMutex);
}

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_rwlock_t rwlock;
} DynamicArray;

DynamicArray* createDynamicArray() {
    DynamicArray *arr = (DynamicArray *)customAlloc(sizeof(DynamicArray));
    arr->array = (NFAPI_CRC_INDICATION_PDU_T *)customAlloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    arr->capacity = INITIAL_CAPACITY;
    arr->size = 0;
    pthread_rwlock_init(&arr->rwlock, NULL);
    return arr;
}

void resizeArray(DynamicArray *arr) {
    size_t newCapacity = arr->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *newArray = (NFAPI_CRC_INDICATION_PDU_T *)customAlloc(newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memcpy(newArray, arr->array, arr->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    customFree(arr->array);
    arr->array = newArray;
    arr->capacity = newCapacity;
}

void insertElement(DynamicArray *arr, size_t index, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_rwlock_wrlock(&arr->rwlock);

    if (arr->size >= arr->capacity) {
        resizeArray(arr);
    }

    memmove(&arr->array[index + 1], &arr->array[index], (arr->size - index) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    arr->array[index] = element;
    arr->size++;

    pthread_rwlock_unlock(&arr->rwlock);
}

void deleteElement(DynamicArray *arr, size_t index) {
    pthread_rwlock_wrlock(&arr->rwlock);

    if (index < arr->size) {
        memmove(&arr->array[index], &arr->array[index + 1], (arr->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        arr->size--;
    }

    pthread_rwlock_unlock(&arr->rwlock);
}

NFAPI_CRC_INDICATION_PDU_T getElement(DynamicArray *arr, size_t index) {
    NFAPI_CRC_INDICATION_PDU_T element;
    pthread_rwlock_rdlock(&arr->rwlock);

    if (index < arr->size) {
        element = arr->array[index];
    }

    pthread_rwlock_unlock(&arr->rwlock);
    return element;
}

void serializeArray(DynamicArray *arr, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&arr->size, sizeof(size_t), 1, file);
    fwrite(arr->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), arr->size, file);

    fclose(file);
}

void healthCheck(DynamicArray *arr) {
    pthread_rwlock_rdlock(&arr->rwlock);

    for (size_t i = 0; i < arr->size; ++i) {
        NFAPI_CRC_INDICATION_PDU_T element = getElement(arr, i);
        if (element.RX_UE_INFORMATION_TAG <= 0 || element.RNTI <= 0) {
            printf("Data integrity issue at index %zu\n", i);
        }
    }

    pthread_rwlock_unlock(&arr->rwlock);
}

void logOperation(const char *operation, const char *threadName) {
    time_t now = time(NULL);
    char *timeStr = ctime(&now);
    timeStr[strlen(timeStr) - 1] = '\0'; // Remove newline

    printf("[%s] [%s] %s\n", timeStr, threadName, operation);
}

void cleanupDynamicArray(DynamicArray *arr) {
    pthread_rwlock_destroy(&arr->rwlock);
    customFree(arr->array);
    customFree(arr);
}

int main() {
    initializeMemoryPool();

    DynamicArray *dynamicArray = createDynamicArray();
    NFAPI_CRC_INDICATION_PDU_T pdu = {1, 1001, {.CRCFLAG = rand() % 2}};

    insertElement(dynamicArray, 0, pdu);
    logOperation("Inserted element", "MainThread");

    serializeArray(dynamicArray, "data.bin");
    healthCheck(dynamicArray);

    cleanupDynamicArray(dynamicArray);
    return 0;
}
