#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <pthread.h>

#define INITIAL_SIZE 100

typedef struct {
    char ip_address[INET_ADDRSTRLEN];
    int port;
    int status; // 0 for closed, 1 for established
} Connection;

typedef struct {
    Connection *connections;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} ConnectionArray;

void log_connection_event(const char *event) {
    // Placeholder for logging integration
    printf("%s\n", event);
}

int initialize_connections(ConnectionArray *array, size_t initial_size) {
    array->size = 0;
    array->capacity = initial_size;
    array->connections = (Connection *)malloc(sizeof(Connection) * initial_size);
    if (!array->connections) return -1;

    pthread_mutex_init(&array->lock, NULL);

    for (size_t i = 0; i < initial_size; ++i) {
        struct in_addr addr;
        addr.s_addr = htonl(rand() % 256); // Simple random IP generation

        if (inet_ntop(AF_INET, &addr, array->connections[i].ip_address, sizeof(array->connections[i].ip_address)) == NULL) {
            log_connection_event("Failed to initialize connection object with valid IP address.");
            return -1;
        }

        array->connections[i].port = rand() % 65535 + 1; // Random port number
        array->connections[i].status = 1; // Established

        log_connection_event("Initialized connection object");
    }
    return 0;
}

void resize_connections(ConnectionArray *array, size_t new_capacity) {
    pthread_mutex_lock(&array->lock);

    Connection *new_array = (Connection *)realloc(array->connections, sizeof(Connection) * new_capacity);
    if (!new_array) {
        log_connection_event("Failed to resize connections array.");
        pthread_mutex_unlock(&array->lock);
        return;
    }

    memset(new_array + array->capacity, 0, sizeof(Connection) * (new_capacity - array->capacity));
    array->connections = new_array;
    array->capacity = new_capacity;

    log_connection_event("Resized connection array");
    pthread_mutex_unlock(&array->lock);
}

int add_connection(ConnectionArray *array, const char *ip_address, int port) {
    if (pthread_mutex_lock(&array->lock) != 0) return -1;

    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        resize_connections(array, new_capacity);
        if (new_capacity <= array->capacity) {
            pthread_mutex_unlock(&array->lock);
            log_connection_event("Failed to add connection due to resizing failure.");
            return -1;
        }
    }

    struct in_addr addr;
    if (inet_pton(AF_INET, ip_address, &addr) != 1) {
        pthread_mutex_unlock(&array->lock);
        log_connection_event("Invalid IP address provided.");
        return -1;
    }

    strncpy(array->connections[array->size].ip_address, ip_address, INET_ADDRSTRLEN);
    array->connections[array->size].port = port;
    array->connections[array->size].status = 1; // Established

    log_connection_event("Added new connection");
    array->size++;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

void free_connections(ConnectionArray *array) {
    if (array->connections) {
        free(array->connections);
        array->connections = NULL;
        array->size = 0;
        array->capacity = 0;
    }
    pthread_mutex_destroy(&array->lock);
}
