    }

    pthread_mutex_lock(&da->lock);
    *outElement = da->array[index];
    pthread_mutex_unlock(&da->lock);

    return 0; // Success
}

// Serialize array to binary format
int serialize_array(DynamicArray* da, uint8_t** buffer, size_t* bufferSize) {
    pthread_mutex_lock(&da->lock);

    *bufferSize = sizeof(size_t) + da->size * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    *buffer = (uint8_t*)custom_alloc(*bufferSize);

    memcpy(*buffer, &da->size, sizeof(size_t)); // Store size
    memcpy((*buffer) + sizeof(size_t), da->array, da->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_unlock(&da->lock);

    return 0; // Success
}

// Deserialize binary format to array
int deserialize_array(DynamicArray* da, const uint8_t* buffer, size_t bufferSize) {
    pthread_mutex_lock(&da->lock);

