    }

    memcpy(da->array, buffer + sizeof(size_t), new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    da->size = new_size;

    pthread_mutex_unlock(&da->lock);

    return 0; // Success
}

// Clean up resources
