// Thread-safe function to insert an element
int dynamic_array_insert(DynamicArray* array, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pdu || !array)
        return -1;

    pthread_rwlock_wrlock(&array->read_write_lock);

    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        if (new_capacity > MAX_ARRAY_SIZE)
            new_capacity = MAX_ARRAY_SIZE;

        NFAPI_CRC_INDICATION_PDU_T* new_data = custom_malloc(new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_rwlock_unlock(&array->read_write_lock);
            return -1;
        }

        memcpy(new_data, array->data, array->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        custom_free(array->data);
        array->data = new_data;
        array->capacity = new_capacity;
    }

    memcpy(&array->data[array->size], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->size++;

    pthread_rwlock_unlock(&array->read_write_lock);

    return 0;
}

