#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <string.h>

#define MAX_NFAPDUS 100

typedef struct {
    int RNTI;
    unsigned char RX_UE_INFORMATION_TAG[8];
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG tag;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef enum {
    SERVICE_STOPPED,
    SERVICE_RUNNING
} ServiceState;

typedef struct {
    pthread_mutex_t mutex;
    pthread_cond_t cond_var;
    ServiceState state;
    int pending_tasks;
    NFAPI_CRC_INDICATION_PDU_T nfapi_pdus[MAX_NFAPDUS];
} CRCService;

void* crc_service_thread(void* arg) {
    CRCService* service = (CRCService*)arg;

    while (1) {
        pthread_mutex_lock(&service->mutex);

        while (service->state == SERVICE_STOPPED && service->pending_tasks == 0) {
            pthread_cond_wait(&service->cond_var, &service->mutex);
        }

        if (service->state == SERVICE_STOPPED && service->pending_tasks == 0) {
            break;
        }

        int index = rand() % MAX_NFAPDUS;
        CRC_INDICATION_REL8_TAG* tag = &service->nfapi_pdus[index].tag;

        // Populate with random data
        service->nfapi_pdus[index].CRCFLAG = rand() % 2 == 0;
        for (int i = 0; i < sizeof(tag->RX_UE_INFORMATION_TAG); ++i) {
            tag->RX_UE_INFORMATION_TAG[i] = rand() % 256;
        }
        tag->RNTI = rand() % 10000;

        service->pending_tasks--;

        pthread_mutex_unlock(&service->mutex);
    }

    // Notify monitoring system
    printf("Service stopped. Pending tasks: %d\n", service->pending_tasks);

    return NULL;
}

void start_crc_service(CRCService* service) {
    pthread_t thread_id;

    pthread_mutex_lock(&service->mutex);
    service->state = SERVICE_RUNNING;
    service->pending_tasks = 0;

    if (pthread_create(&thread_id, NULL, crc_service_thread, service) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_unlock(&service->mutex);
}

void stop_crc_service(CRCService* service) {
    pthread_mutex_lock(&service->mutex);

    service->state = SERVICE_STOPPED;

    while (service->pending_tasks > 0) {
        pthread_cond_signal(&service->cond_var);
    }

    pthread_mutex_unlock(&service->mutex);

    // Join the thread
    pthread_join(thread_id, NULL);
}

void add_task(CRCService* service) {
    pthread_mutex_lock(&service->mutex);

    if (service->pending_tasks < MAX_NFAPDUS) {
        service->pending_tasks++;
    } else {
        fprintf(stderr, "Maximum number of tasks reached\n");
    }

    pthread_cond_signal(&service->cond_var);
    pthread_mutex_unlock(&service->mutex);
}

int main() {
    CRCService service;
    pthread_mutex_init(&service.mutex, NULL);
    pthread_cond_init(&service.cond_var, NULL);

    start_crc_service(&service);

    // Simulate adding tasks
    for (int i = 0; i < 10; ++i) {
        add_task(&service);
    }

    sleep(2); // Allow some time for processing

    stop_crc_service(&service);

    pthread_mutex_destroy(&service.mutex);
    pthread_cond_destroy(&service.cond_var);

    return 0;
}
```

