#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char *UE_ID;
    char *RRC_STATE;
} MeasurementResult;

typedef struct {
    char *UE_ID;
    char *RRC_STATE;
    MeasurementResult *MeasurementResults;
    size_t measurement_count;
} UEState;

typedef struct {
    UEState **data;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

void init_dynamic_array(DynamicArray *array) {
    array->capacity = 10;
    array->data = malloc(array->capacity * sizeof(UEState *));
    if (!array->data) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&array->lock, NULL);
}

void resize_dynamic_array(DynamicArray *array) {
    size_t new_capacity = array->capacity * 2;
    UEState **new_data = realloc(array->data, new_capacity * sizeof(UEState *));
    if (!new_data) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->data = new_data;
    array->capacity = new_capacity;
}

void free_measurement_results(MeasurementResult *results, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free(results[i].UE_ID);
        free(results[i].RRC_STATE);
    }
    free(results);
}

void free_ue_state(UEState *ue_state) {
    free(ue_state->UE_ID);
    free(ue_state->RRC_STATE);
    free_measurement_results(ue_state->MeasurementResults, ue_state->measurement_count);
    free(ue_state);
}

void free_dynamic_array(DynamicArray *array) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->capacity; ++i) {
        if (array->data[i]) {
            free_ue_state(array->data[i]);
        }
    }
    free(array->data);
    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
}

int parse_csv_line(char *line, UEState **ue_state) {
    char *token;
    char *rest = line;

    // Parse UE_ID
    token = strtok_r(rest, ",", &rest);
    if (!token || strlen(token) == 0) return -1;

    // Allocate and set UE_ID
    *ue_state = malloc(sizeof(UEState));
    (*ue_state)->UE_ID = strdup(token);

    // Parse RRC_STATE
    token = strtok_r(rest, ",", &rest);
    if (!token || strlen(token) == 0) return -1;
    (*ue_state)->RRC_STATE = strdup(token);

    // Initialize measurement results list
    (*ue_state)->MeasurementResults = NULL;
    (*ue_state)->measurement_count = 0;

    while ((token = strtok_r(rest, ",", &rest))) {
        MeasurementResult *new_result = realloc((*ue_state)->MeasurementResults,
                                                (++(*ue_state)->measurement_count) * sizeof(MeasurementResult));
        if (!new_result) return -1;
        (*ue_state)->MeasurementResults = new_result;

        // Parse UE_ID for measurement
        char *measure_ue_id = strdup(token);
        token = strtok_r(NULL, ",", &rest);

        // Parse RRC_STATE for measurement
        if (!token || strlen(token) == 0) {
            free(measure_ue_id);
            return -1;
        }
        char *measure_rrc_state = strdup(token);

        (*ue_state)->MeasurementResults[(*ue_state)->measurement_count - 1].UE_ID = measure_ue_id;
        (*ue_state)->MeasurementResults[(*ue_state)->measurement_count - 1].RRC_STATE = measure_rrc_state;
    }

    return 0;
}

void load_csv_files(DynamicArray *array, const char **file_paths, size_t file_count) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < file_count; ++i) {
        FILE *file = fopen(file_paths[i], "r");
        if (!file) {
            fprintf(stderr, "Failed to open file: %s\n", file_paths[i]);
            continue;
        }

        char line[1024];
        while (fgets(line, sizeof(line), file)) {
            UEState *ue_state = NULL;
            if (parse_csv_line(line, &ue_state) == 0) {
                if ((array->capacity - 1) < array->capacity / 2) {
                    resize_dynamic_array(array);
                }
                array->data[array->capacity - 1] = ue_state;
            } else {
                fprintf(stderr, "Failed to parse line: %s\n", line);
                free(ue_state);
            }
        }

        fclose(file);
    }

    pthread_mutex_unlock(&array->lock);
}

int main() {
    DynamicArray array;
    init_dynamic_array(array);

    const char *file_paths[] = {"sector1.csv", "sector2.csv"};
    load_csv_files(&array, file_paths, 2);

    // Process the data...

    free_dynamic_array(&array);
    return 0;
}
