["```cpp
#include <forward_list>
#include <mutex>
#include <random>
#include <fstream>
#include <sstream>

struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t rnti;
    uint8_t crcflag;

    // Serialization methods for saving/loading from disk
    std::string serialize() const {
        std::ostringstream oss;
        oss << rnti << ' ' << static_cast<int>(crcflag);
        return oss.str();
    }

    void deserialize(const std::string& data) {
        std::istringstream iss(data);
        iss >> rnti >> crcflag;
    }
};

class NFAPI_CRCManager {
public:
    void processForwardList(std::forward_list<NFAPI_CRC_INDICATION_PDU_T>& pduList,
                            uint16_t rnti1, uint16_t rnti2, bool enableCRCCheck) {

        std::unique_lock<std::mutex> lock(mutex_);

        auto it = findPDU(pduList, rnti1, rnti2);
        if (it != pduList.end()) {
            NFAPI_CRC_INDICATION_PDU_T newPDU;
            initializeNewPDU(newPDU, enableCRCCheck);

            // Insert the new PDU immediately after the found one
            auto nextIt = std::next(it);
            pduList.insert_after(it, newPDU);
        } else {
            NFAPI_CRC_INDICATION_PDU_T newPDU;
            initializeNewPDU(newPDU, enableCRCCheck);

            // Append to end if not found
            pduList.push_front(std::move(pduList.front()));
            pduList.pop_front();
            pduList.push_front(newPDU);
        }
    }

    void saveToFile(const std::string& filename) {
        std::unique_lock<std::mutex> lock(mutex_);

        std::ofstream ofs(filename, std::ios::binary);
        if (ofs.is_open()) {
            for (const auto& pdu : pduList_) {
                ofs << pdu.serialize() << '\n';
            }
        }
    }

    void loadFromFile(const std::string& filename) {
        std::unique_lock<std::mutex> lock(mutex_);

        std::ifstream ifs(filename, std::ios::binary);
        if (ifs.is_open()) {
            std::string line;
            pduList_.clear();
            while (std::getline(ifs, line)) {
                NFAPI_CRC_INDICATION_PDU_T pdu;
                pdu.deserialize(line);
                pduList_.push_front(pdu);
            }
        }
    }

private:
    std::forward_list<NFAPI_CRC_INDICATION_PDU_T> pduList_;
    std::mutex mutex_;

    void initializeNewPDU(NFAPI_CRC_INDICATION_PDU_T& pdu, bool enableCRCCheck) {
        pdu.rnti = 0; // Assume some default value
        if (enableCRCCheck) {
            static std::random_device rd;
            static std::mt19937 gen(rd());
            static std::uniform_int_distribution<> dis(0, 1);
            pdu.crcflag = static_cast<uint8_t>(dis(gen));
        } else {
            pdu.crcflag = 0; // Default value if CRC check is disabled
        }
    }

    auto findPDU(const std::forward_list<NFAPI_CRC_INDICATION_PDU_T>& list, uint16_t rnti1, uint16_t rnti2) -> decltype(list.begin()) {
        for (auto it = list.begin(); it != list.end(); ++it) {
            if (it->rnti == rnti1 || it->rnti == rnti2) {
                return it;
            }
        }
        return list.end();
    }
};
