void initialize_list(ResizableList* list, void (*log_function)(const char*)) {
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->cond_var, NULL);
    list->head = list->tail = NULL;
    list->count = 0;
    list->log_function = log_function;
    if (log_function) {
        log_function("List initialized.");
    }
}

void cleanup_list(ResizableList* list) {
    pthread_mutex_lock(&list->mutex);

    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&list->mutex);

    pthread_mutex_destroy(&list->mutex);
    pthread_cond_destroy(&list->cond_var);

    if (list->log_function) {
