typedef struct {
    NFAPI_CRC_INDICATION_PDU_T** pdus;
    size_t capacity;
    size_t count;
} PDU_Batch;

PDU_Batch* create_pdu_batch(size_t initial_capacity) {
    PDU_Batch* batch = (PDU_Batch*)malloc(sizeof(PDU_Batch));
    if (!batch) {
        log_message("Error: Memory allocation failed for PDU_Batch.");
        return NULL;
    }
    batch->pdus = (NFAPI_CRC_INDICATION_PDU_T**)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!batch->pdus) {
        free(batch);
        log_message("Error: Memory allocation failed for PDU pointers.");
        return NULL;
    }
    batch->capacity = initial_capacity;
    batch->count = 0;
    return batch;
}

void destroy_pdu_batch(PDU_Batch* batch) {
    if (batch) {
        for (size_t i = 0; i < batch->count; ++i) {
            free(batch->pdus[i]);
        }
        free(batch->pdus);
        free(batch);
    }
