void adaptive_batch_processing(size_t initial_batch_size, int load_factor) {
    size_t batch_size = initial_batch_size;
    while (1) { // Simulate continuous processing
        PDU_Batch* batch = create_pdu_batch(batch_size);
        if (!batch) break;

        pthread_t thread_id;
        if (pthread_create(&thread_id, NULL, process_pdus, batch)) {
            log_message("Error: Thread creation failed.");
            destroy_pdu_batch(batch);
            continue;
        }

        pthread_join(thread_id, NULL);

        // Simulate adaptive adjustment based on load_factor
        batch_size = (load_factor > 0.5) ? batch_size * 2 : batch_size / 2;

        // Clean up after processing
        destroy_pdu_batch(batch);

        sleep(1); // Simulating time delay between batches
    }
}

