```php
<?php
session_start();

function authenticateAndStoreAccessToken($clientId, $clientSecret, $authUrl, $redirectUri) {
    if (!isset($_GET['code'])) {
        // Build authorization URL for user consent
        $params = [
            'response_type' => 'code',
            'client_id'     => $clientId,
            'redirect_uri'  => $redirectUri,
            'scope'         => 'profile email', // Example scope, adjust as needed
        ];
        $authUrlWithParams = $authUrl . '?' . http_build_query($params);

        header('Location: ' . $authUrlWithParams);
        exit;
    }

    // User has authorized; get access token
    $code = $_GET['code'];
    $tokenUrl = $authUrl . '/token'; // Typically, the token endpoint is at the same base URL

    $postFields = [
        'grant_type'    => 'authorization_code',
        'client_id'     => $clientId,
        'client_secret' => $clientSecret,
        'code'          => $code,
        'redirect_uri'  => $redirectUri,
    ];

    $ch = curl_init($tokenUrl);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_POST, true);
    curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query($postFields));

    $response = curl_exec($ch);
    if (curl_errno($ch)) {
        die('Curl error: ' . curl_error($ch));
    }

    $tokenData = json_decode($response, true);

    // Store token securely
    $_SESSION['access_token'] = $tokenData['access_token'];
}

function getUserInfo($userInfoUrl) {
    if (!isset($_SESSION['access_token'])) {
        return null;
    }

    $accessToken = $_SESSION['access_token'];

    $ch = curl_init($userInfoUrl);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_HTTPHEADER, [
        'Authorization: Bearer ' . $accessToken
    ]);

    $response = curl_exec($ch);

    if (curl_errno($ch)) {
        die('Curl error: ' . curl_error($ch));
    }

    return json_decode($response, true);
}

// Example usage
