typedef struct {
    PDCP_PDU pdcp_pdu;
    RRC_PDU rrc_pdu;
    uint16_t pdcp_sn;  // Optional PDCP sequence number
} NFAPI_RRC_PDU_T;

// Dynamic list node and management structures.
typedef struct Node {
    NFAPI_RRC_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;  // Mutex for thread safety
    size_t count;
    size_t capacity;
    void (*log)(const char*);  // Logging function pointer
    uint32_t checksum;        // For data integrity during serialization
} DynamicList;

// Function prototypes.
DynamicList* create_list(void (*log_func)(const char*));
void destroy_list(DynamicList** list);
int add_entry(DynamicList* list, const NFAPI_RRC_PDU_T* entry);
int update_entry(DynamicList* list, uint16_t pdcp_sn, const NFAPI_RRC_PDU_T* updated_data);
Node* find_node_by_pdcpsn(DynamicList* list, uint16_t pdcp_sn);
void perform_garbage_collection(DynamicList* list);
void serialize_list(const DynamicList* list, FILE* out_file);
int deserialize_list(DynamicList* list, const char* format, FILE* in_file);
uint32_t calculate_checksum(const NFAPI_RRC_PDU_T* entry);

// Implementations
DynamicList* create_list(void (*log_func)(const char*)) {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    list->capacity = 10; // Initial capacity
    list->log = log_func ? log_func : (void (*)(const char*))printf;

    return list;
}

void destroy_list(DynamicList** list) {
    if (!list || !*list) return;

    Node* current = (*list)->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&(*list)->lock);
    free(*list);
    *list = NULL;
}

int add_entry(DynamicList* list, const NFAPI_RRC_PDU_T* entry) {
    if (!list || !entry) return -1;

    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -2;
    }

    memcpy(&new_node->data, entry, sizeof(NFAPI_RRC_PDU_T));
    new_node->next = list->head;
    list->head = new_node;

    // Update checksum for data integrity validation
    list->checksum ^= calculate_checksum(entry);

    list->count++;
    if (list->count > list->capacity) {
        perform_garbage_collection(list);  // Trigger garbage collection if needed
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int update_entry(DynamicList* list, uint16_t pdcp_sn, const NFAPI_RRC_PDU_T* updated_data) {
    if (!list || !updated_data) return -1;

    pthread_mutex_lock(&list->lock);

    Node* node = find_node_by_pdcpsn(list, pdcp_sn);
    if (node) {
        memcpy(&node->data, updated_data, sizeof(NFAPI_RRC_PDU_T));
        list->checksum ^= calculate_checksum(updated_data);  // Update checksum
    }

    pthread_mutex_unlock(&list->lock);
    return node ? 0 : -1;
}

Node* find_node_by_pdcpsn(DynamicList* list, uint16_t pdcp_sn) {
    Node* current = list->head;
    while (current) {
        if (current->data.pdcp_sn == pdcp_sn) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void perform_garbage_collection(DynamicList* list) {
    // Simplified example: Reduce the capacity by half
    size_t new_capacity = list->capacity / 2;

    Node *current = list->head, *prev = NULL;
    while (current && new_capacity < list->count) {
        Node* next = current->next;
        free(current);
        if (prev) prev->next = next;
        else list->head = next;
        list->count--;
        current = next;
    }

    list->capacity = new_capacity;
}

void serialize_list(const DynamicList* list, FILE* out_file) {
    // Serialize into a binary format
    pthread_mutex_lock((pthread_mutex_t*)&list->lock);

    fwrite(&list->checksum, sizeof(uint32_t), 1, out_file);
    Node* current = list->head;

    while (current) {
        fwrite(&current->data, sizeof(NFAPI_RRC_PDU_T), 1, out_file);
        current = current->next;
    }

    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
}

int deserialize_list(DynamicList* list, const char* format, FILE* in_file) {
    if (strcmp(format, "binary") == 0) {
        uint32_t checksum_read;

        pthread_mutex_lock(&list->lock);

        fread(&checksum_read, sizeof(uint32_t), 1, in_file);
        Node* current = list->head;

        while (!feof(in_file)) {
            NFAPI_RRC_PDU_T entry;
            if (fread(&entry, sizeof(NFAPI_RRC_PDU_T), 1, in_file) == 1) {
                add_entry(list, &entry);
            }
        }

        list->checksum = checksum_read;

        pthread_mutex_unlock(&list->lock);

        // Validate integrity
        Node* validate_current = list->head;
        uint32_t calculated_checksum = 0;

        while (validate_current) {
            calculated_checksum ^= calculate_checksum(&validate_current->data);
            validate_current = validate_current->next;
        }

        return calculated_checksum == checksum_read ? 0 : -1;

    } else if (strcmp(format, "text") == 0) {
        // Implement text-based serialization/deserialization logic
        pthread_mutex_unlock(&list->lock);
        return -2; // Placeholder for unsupported format in this example
    }

    pthread_mutex_unlock(&list->lock);
    return -3;
}

uint32_t calculate_checksum(const NFAPI_RRC_PDU_T* entry) {
    // Simple checksum calculation as an example.
    uint8_t *data = (uint8_t*)entry;
    size_t len = sizeof(NFAPI_RRC_PDU_T);

    uint32_t checksum = 0;
    for (size_t i = 0; i < len; ++i) {
        checksum ^= data[i];
    }

    return checksum;
}

// Example logging function
void log_message(const char* message) {
    printf("Log: %s\n", message);
}

int main() {
    // Usage example with a dynamic list.
    DynamicList* my_list = create_list(log_message);

