['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} CRC_INDICATION_REL8_TAG_T;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    CRC_INDICATION_REL8_TAG_T CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t count;
    pthread_mutex_t mutex;
} NFAPI_CRC_ARRAY_CONTEXT;

void initialize_crc_array(NFAPI_CRC_ARRAY_CONTEXT *context, size_t size) {
    if (size > MAX_ELEMENTS) {
        fprintf(stderr, "Error: Requested size exceeds maximum limit.\n");
        return;
    }

    context->count = 0;
    pthread_mutex_init(&context->mutex, NULL);
    context->array = (NFAPI_CRC_INDICATION_PDU_T *)calloc(size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!context->array) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        pthread_mutex_destroy(&context->mutex);
        exit(EXIT_FAILURE);
    }
}

void destroy_crc_array(NFAPI_CRC_ARRAY_CONTEXT *context) {
    free(context->array);
    context->array = NULL;
    pthread_mutex_destroy(&context->mutex);
}

void log_memory_usage(const NFAPI_CRC_ARRAY_CONTEXT *context) {
    printf("Memory Usage: %zu elements allocated\n", context->count);
}

int set_random_crcflag(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    srand(time(NULL));
    pdu->CRCFLAG = rand() % 2;
    return 0; // Success
}

void populate_array(NFAPI_CRC_ARRAY_CONTEXT *context, size_t num_elements) {
    pthread_mutex_lock(&context->mutex);

    for (size_t i = 0; i < num_elements && context->count < MAX_ELEMENTS; ++i) {
