#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    uint32_t rnti;
    int crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} CRCArray;

CRCArray* create_crc_array(size_t initial_capacity) {
    CRCArray* arr = (CRCArray*)malloc(sizeof(CRCArray));
    if (!arr) return NULL;
    arr->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!arr->array) {
        free(arr);
        return NULL;
    }
    arr->capacity = initial_capacity;
    arr->size = 0;
    pthread_mutex_init(&arr->mutex, NULL);
    return arr;
}

void destroy_crc_array(CRCArray* arr) {
    if (arr) {
        free(arr->array);
        pthread_mutex_destroy(&arr->mutex);
        free(arr);
    }
}

int resize_crc_array(CRCArray* arr, size_t new_capacity) {
    pthread_mutex_lock(&arr->mutex);
    NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(arr->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        pthread_mutex_unlock(&arr->mutex);
        return -1;
    }
    arr->capacity = new_capacity;
    arr->array = new_array;
    pthread_mutex_unlock(&arr->mutex);
    return 0;
}

int add_crc_pdu(CRCArray* arr, uint32_t rnti, int crc_flag) {
    pthread_mutex_lock(&arr->mutex);
    if (arr->size >= arr->capacity) {
        size_t new_capacity = arr->capacity * 2;
        if (resize_crc_array(arr, new_capacity)) {
            pthread_mutex_unlock(&arr->mutex);
            return -1;
        }
    }
    NFAPI_CRC_INDICATION_PDU_T* pdu = &arr->array[arr->size++];
    pdu->rnti = rnti;
    pdu->crc_flag = crc_flag;
    pthread_mutex_unlock(&arr->mutex);
    return 0;
}

int remove_crc_pdu(CRCArray* arr, uint32_t rnti) {
    pthread_mutex_lock(&arr->mutex);
    for (size_t i = 0; i < arr->size; ++i) {
        if (arr->array[i].rnti == rnti) {
            for (size_t j = i; j < arr->size - 1; ++j) {
                arr->array[j] = arr->array[j + 1];
            }
            --arr->size;
            pthread_mutex_unlock(&arr->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&arr->mutex);
    return -1;
}

int update_crc_flag(CRCArray* arr, uint32_t rnti, int new_crc_flag) {
    pthread_mutex_lock(&arr->mutex);
    for (size_t i = 0; i < arr->size; ++i) {
        if (arr->array[i].rnti == rnti) {
            arr->array[i].crc_flag = new_crc_flag;
            pthread_mutex_unlock(&arr->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&arr->mutex);
    return -1;
}

int verify_crc_flag(CRCArray* arr, uint32_t rnti, int expected_crc_flag) {
    pthread_mutex_lock(&arr->mutex);
    for (size_t i = 0; i < arr->size; ++i) {
        if (arr->array[i].rnti == rnti) {
            int result = arr->array[i].crc_flag == expected_crc_flag;
            pthread_mutex_unlock(&arr->mutex);
            return result;
        }
    }
    pthread_mutex_unlock(&arr->mutex);
    return -1; // RNTI not found
}

int main() {
    CRCArray* crc_array = create_crc_array(10);
    if (!crc_array) {
        printf("Failed to create CRC array.\n");
        return 1;
    }

    add_crc_pdu(crc_array, 1001, 1);
    update_crc_flag(crc_array, 1001, 0);
    int result = verify_crc_flag(crc_array, 1001, 0);

    printf("CRC flag verification: %s\n", result == 1 ? "Success" : "Failure");

    remove_crc_pdu(crc_array, 1001);
    destroy_crc_array(crc_array);

    return 0;
}
```

