    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// A node in the linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// The dynamic list structure with synchronization primitives
typedef struct {
    Node* head;
    size_t size;
    pthread_mutex_t lock; // Mutex for protecting the list
    pthread_cond_t cond;  // Condition variable for signaling
} CRCIndicationList;

// Logging function (stub)
void log_operation(const char* message) {
    printf("%s\n", message);
}

// Function to generate a random CRC flag
unsigned char generate_random_crc_flag() {
    return rand() % 256;
}

// Initialize the list
void init_list(CRCIndicationList* list) {
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond, NULL);
    list->head = NULL;
    list->size = 0;
}

// Destroy the list and free resources
void destroy_list(CRCIndicationList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->cond);
}

// Add an element to the list
void add_element(CRCIndicationList* list, unsigned int RX_UE_TAG, unsigned int RNTI) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_operation("Memory allocation failed for new node");
        return;
    }

    new_node->data.RX_UE_INFORMATION_TAG = RX_UE_TAG;
    new_node->data.RNTI = RNTI;
    new_node->data.CRC_INDICATION_REL8_TAG = generate_random_crc_flag();
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = new_node;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    list->size++;
    log_operation("Element added, total size: ");
    printf("%zu\n", list->size);
    pthread_mutex_unlock(&list->lock);
}

// Remove an element from the list by RX_UE_TAG
void remove_element(CRCIndicationList* list, unsigned int RX_UE_TAG) {
    pthread_mutex_lock(&list->lock);
    Node *current = list->head, *prev = NULL;
    while (current != NULL && current->data.RX_UE_INFORMATION_TAG != RX_UE_TAG) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        log_operation("Element not found for removal");
        return;
    }

    if (prev == NULL) { // Head needs to be removed
        list->head = current->next;
    } else {
        prev->next = current->next;
    }
    free(current);
    list->size--;
    log_operation("Element removed, total size: ");
    printf("%zu\n", list->size);
    pthread_mutex_unlock(&list->lock);
}

// Access an element from the list by RX_UE_TAG
NFAPI_CRC_INDICATION_PDU_T* access_element(CRCIndicationList* list, unsigned int RX_UE_TAG) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL && current->data.RX_UE_INFORMATION_TAG != RX_UE_TAG) {
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);

    if (current == NULL) {
        log_operation("Element not found for access");
        return NULL;
    }

    log_operation("Element accessed, total size: ");
    printf("%zu\n", list->size);
    return &current->data;
}

// Periodic update from an external data source
void* periodic_update(void* arg) {
    CRCIndicationList* list = (CRCIndicationList*)arg;

    while (1) {
        // Simulate fetching new RNTI values and updating the list
        sleep(5);  // Example update frequency

        pthread_mutex_lock(&list->lock);
        Node* current = list->head;
        while (current != NULL) {
            // Here, you would fetch a new RNTI for each element from an external source
            current->data.RNTI += 1;  // Dummy operation
            current = current->next;
        }
        pthread_mutex_unlock(&list->lock);

        log_operation("Periodic update completed");
    }

    return NULL;
}

// Main function to demonstrate usage
int main() {
    srand(time(NULL)); // Seed random number generator

    CRCIndicationList list;
    init_list(&list);

    pthread_t updater_thread;
    pthread_create(&updater_thread, NULL, periodic_update, &list);

    add_element(&list, 1, 100);
    add_element(&list, 2, 200);

    NFAPI_CRC_INDICATION_PDU_T* data = access_element(&list, 1);
    if (data) {
