               data->RX_UE_INFORMATION_TAG,
               data->RNTI,
               data->CRC_INDICATION_REL8_TAG);
    }

    remove_element(&list, 1);

    pthread_cancel(updater_thread);
    pthread_join(updater_thread, NULL);

    destroy_list(&list);

    return 0;
}
