typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned long RNTI;
    int RX_UE_INFORMATION_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    int sequence_number;
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    Node** ptr = &(list->head);
    int sequence_number = 0;

    while (*ptr) {
        if ((*ptr)->sequence_number > sequence_number) {
            sequence_number = (*ptr)->sequence_number;
        }
        ptr = &((*ptr)->next);
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    sequence_number++;
    new_node->sequence_number = sequence_number;
    new_node->data = data;
    new_node->next = NULL;

    *ptr = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void print_list(LinkedList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        printf("Sequence Number: %d, RX_UE_INFORMATION_TAG: %d, RNTI: %lu, CRCFLAG: %d\n",
               current->sequence_number,
               current->data.RX_UE_INFORMATION_TAG,
               current->data.RNTI,
               current->data.CRC_INDICATION_REL8_TAG.CRCFLAG);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

