#include <pthread.h>

typedef struct {
    float snr;
    int rsrp;
    float srs;
} LTE_PHY_Metrics;

typedef struct {
    LTE_PHY_Metrics *metrics;
    size_t num_cells;
    pthread_mutex_t lock;
} CellMetricsManager;

// Function to initialize the Cell Metrics Manager
CellMetricsManager* init_cell_metrics_manager(size_t num_cells) {
    CellMetricsManager *manager = (CellMetricsManager*)malloc(sizeof(CellMetricsManager));
    if (!manager) return NULL;

    manager->metrics = (LTE_PHY_Metrics*)calloc(num_cells, sizeof(LTE_PHY_Metrics));
    if (!manager->metrics) {
        free(manager);
        return NULL;
    }

    manager->num_cells = num_cells;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

// Function to update metrics for a specific cell
int update_cell_metrics(CellMetricsManager *manager, size_t cell_index, float snr, int rsrp, float srs) {
    if (cell_index >= manager->num_cells) return -1;

    pthread_mutex_lock(&manager->lock);

    manager->metrics[cell_index].snr = snr;
    manager->metrics[cell_index].rsrp = rsrp;
    manager->metrics[cell_index].srs = srs;

    pthread_mutex_unlock(&manager->lock);

    return 0;
}

// Function to retrieve metrics for a specific cell
int get_cell_metrics(const CellMetricsManager *manager, size_t cell_index, float *snr, int *rsrp, float *srs) {
    if (cell_index >= manager->num_cells) return -1;

    pthread_mutex_lock(&manager->lock);

    if (snr) *snr = manager->metrics[cell_index].snr;
    if (rsrp) *rsrp = manager->metrics[cell_index].rsrp;
    if (srs) *srs = manager->metrics[cell_index].srs;

    pthread_mutex_unlock(&manager->lock);

    return 0;
}

// Function to deallocate resources used by the Cell Metrics Manager
void free_cell_metrics_manager(CellMetricsManager *manager) {
    if (!manager) return;

    free(manager->metrics);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

// Example usage of the manager
int main() {
    size_t num_cells = 5;
    CellMetricsManager *manager = init_cell_metrics_manager(num_cells);

    if (manager) {
        update_cell_metrics(manager, 0, -10.5f, -95, 3.2f);

        float snr;
        int rsrp;
        float srs;

        get_cell_metrics(manager, 0, &snr, &rsrp, &srs);

        printf("Cell 0 Metrics: SNR=%.2f, RSRP=%d, SRS=%.2f\n", snr, rsrp, srs);

        free_cell_metrics_manager(manager);
    }

    return 0;
}
```

