#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

typedef struct {
    uint8_t crcflag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint16_t RNTI;
    uint32_t RX_UE_INFORMATION_TAG;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
    pthread_mutex_t lock; // For thread safety
} PDUList;

// Function to initialize the list
PDUList* create_pdu_list() {
    PDUList* list = (PDUList*)malloc(sizeof(PDUList));
    if (!list) return NULL;

    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Function to add a new structure to the list
int add_pdu(PDUList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list || pthread_mutex_lock(&list->lock)) return -1;

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    newNode->data = pdu;
    newNode->next = list->head;
    list->head = newNode;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Function to create and populate the list
PDUList* populate_pdu_list(size_t n) {
    PDUList* pduList = create_pdu_list();
    if (!pduList) return NULL;

    for (size_t i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;

        // Generate random RNTI and RX_UE_INFORMATION_TAG
        pdu.RNTI = rand() % 65535; // Example range for RNTI
        pdu.RX_UE_INFORMATION_TAG = rand(); 

        // Randomly set CRCFLAG
        pdu.crcIndicationRel8Tag.crcflag = rand() % 2;

        if (add_pdu(pduList, pdu) != 0) {
            printf("Failed to add PDU\n");
            break;
        }
    }

    return pduList;
}

// Function to free the list
void free_pdu_list(PDUList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example usage
int main() {
    size_t n = 100000; // Max number of structures to create

    PDUList* pduList = populate_pdu_list(n);
    if (!pduList) {
        printf("Failed to create PDU list\n");
        return -1;
    }

    free_pdu_list(pduList);

    return 0;
}
