} NFAPI_CRC_INDICATION_PDU_T;

EVP_CIPHER* configure_nfaapi_crc_indication(int num_structures, const char *cipher_mode) {
    // Allocate memory for the list of structures
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Generate random boolean values for CRCFLAG
    unsigned char crcflag;

    for (int i = 0; i < num_structures; ++i) {
        pdu_list[i].RX_UE_INFORMATION_TAG = rand() % UINT_MAX;
        pdu_list[i].RNTI = rand() % UINT_MAX;

        // Randomly set CRCFLAG
        if (rand() % 2) {
            crcflag = 1;
        } else {
            crcflag = 0;
        }

        pdu_list[i].CRC_INDICATION_REL8_TAG[0] = crcflag << 7;  // Set the most significant bit for CRCFLAG
        pdu_list[i].CRC_INDICATION_REL8_TAG[1] = rand() % 128;  // Randomly set other bits
    }

    // Choose the cipher mode
    EVP_CIPHER *cipher = NULL;
    if (strcmp(cipher_mode, "ECB") == 0) {
        cipher = EVP_des_ecb();
    } else if (strcmp(cipher_mode, "EDE") == 0) {
        cipher = EVP_des_ede();
    } else if (strcmp(cipher_mode, "EDE3") == 0) {
        cipher = EVP_des_ede3();
    } else if (strcmp(cipher_mode, "CFB") == 0) {
        cipher = EVP_des_cfb64();
    } else if (strcmp(cipher_mode, "NULL") == 0) {
        cipher = EVP_null_cipher();
    }

    if (!cipher) {
        fprintf(stderr, "Invalid cipher mode\n");
        free(pdu_list);
        return NULL;
    }

    // Initialize the key and IV
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_BLOCK_SIZE];

    if (EVP_CIPHER_key_length(cipher) > 0) {
        if (!RAND_bytes(key, EVP_CIPHER_key_length(cipher))) {
            fprintf(stderr, "Random bytes generation failed\n");
            free(pdu_list);
            return NULL;
        }
    }

    if (EVP_CIPHER_iv_length(cipher) > 0) {
        if (!RAND_bytes(iv, EVP_CIPHER_iv_length(cipher))) {
            fprintf(stderr, "Random IV bytes generation failed\n");
            free(pdu_list);
            return NULL;
        }
    }

    // Return the cipher for further use
    return cipher;
}
