#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_N 100000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Memory pool structure
typedef struct {
    Node* free_list;
    pthread_mutex_t mutex;
} MemoryPool;

MemoryPool pool;

void initialize_pool() {
    pthread_mutex_init(&pool.mutex, NULL);
    pool.free_list = NULL;
}

Node* allocate_node_from_pool() {
    pthread_mutex_lock(&pool.mutex);
    Node* node = pool.free_list;
    if (!node) {
        node = (Node*)malloc(sizeof(Node));
    } else {
        pool.free_list = node->next;
    }
    pthread_mutex_unlock(&pool.mutex);
    return node;
}

void deallocate_node_to_pool(Node* node) {
    pthread_mutex_lock(&pool.mutex);
    node->next = pool.free_list;
    pool.free_list = node;
    pthread_mutex_unlock(&pool.mutex);
}

int is_valid_tag(int tag) {
    // Add actual validation logic
    return tag > 0 && tag < 1000; // Example range check
}

int is_valid_rnti(int rnti) {
    // Add actual validation logic
    return rnti > 0 && rnti < 65535; // Example range check
}

NFAPI_CRC_INDICATION_PDU_T* manage_nfa_pi_crc_indications(unsigned int N) {
    if (N == 0 || N > MAX_N) {
        fprintf(stderr, "Invalid parameter: N must be between 1 and %d\n", MAX_N);
        return NULL;
    }

    pthread_mutex_lock(&lock);

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    srand(time(NULL));

    for (unsigned int i = 0; i < N; ++i) {
        Node* node = allocate_node_from_pool();
        node->data.RX_UE_INFORMATION_TAG = rand() % 1000 + 1; // Example value
        node->data.RNTI = rand() % 65535 + 1; // Example value
        node->data.CRC_INDICATION_REL8_TAG = rand(); // Example value
        node->data.CRCFLAG = rand() & 1;

        if (!is_valid_tag(node->data.RX_UE_INFORMATION_TAG) || !is_valid_rnti(node->data.RNTI)) {
            fprintf(stderr, "Invalid data detected for index %u\n", i);
            deallocate_node_to_pool(node);
            free(array);
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        array[i] = node->data;

        // Free the node to pool after copying data
        deallocate_node_to_pool(node);
    }

    pthread_mutex_unlock(&lock);

    return array;
}

void cleanup_pool() {
    Node* current = pool.free_list;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
}

int main() {
    initialize_pool();

    unsigned int N = 100; // Example usage
    NFAPI_CRC_INDICATION_PDU_T* pdu_array = manage_nfa_pi_crc_indications(N);

    if (pdu_array) {
        for (unsigned int i = 0; i < N; ++i) {
            printf("PDU %u: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d, CRCFLAG=%d\n",
                   i + 1,
                   pdu_array[i].RX_UE_INFORMATION_TAG,
                   pdu_array[i].RNTI,
                   pdu_array[i].CRC_INDICATION_REL8_TAG,
                   pdu_array[i].CRCFLAG);
        }
        free(pdu_array);
    }

    cleanup_pool();

    return 0;
}
