#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define INITIAL_CAPACITY 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG; // 1 for success, 0 for failure
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} CRCList;

void initCRCList(CRCList *list) {
    list->count = 0;
    list->capacity = INITIAL_CAPACITY;
    list->entries = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->capacity);
    if (list->entries == NULL) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->cond, NULL);
}

void destroyCRCList(CRCList *list) {
    free(list->entries);
    pthread_mutex_destroy(&list->mutex);
    pthread_cond_destroy(&list->cond);
}

void resizeIfNeeded(CRCList *list) {
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_entries = realloc(list->entries, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
        if (new_entries == NULL) {
            perror("Failed to reallocate memory");
            exit(EXIT_FAILURE);
        }
        list->entries = new_entries;
        list->capacity = new_capacity;
    }
}

void addEntry(CRCList *list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->mutex);

    resizeIfNeeded(list);

    list->entries[list->count++] = entry;

    pthread_cond_signal(&list->cond);
    pthread_mutex_unlock(&list->mutex);
}

int removeEntry(CRCList *list, int index, NFAPI_CRC_INDICATION_PDU_T *entry) {
    pthread_mutex_lock(&list->mutex);

    while (list->count == 0) {
        pthread_cond_wait(&list->cond, &list->mutex);
    }

    if (index < 0 || index >= list->count) {
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }

    *entry = list->entries[index];
    for (size_t i = index; i < list->count - 1; ++i) {
        list->entries[i] = list->entries[i + 1];
    }
    --list->count;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void logState(const CRCList *list) {
    printf("Current count: %zu, Capacity: %zu\n", list->count, list->capacity);
}

// Example usage
int main() {
    CRCList crcList;
    initCRCList(&crcList);

    // Simulate adding entries
    for (int i = 0; i < 5000; ++i) {
        NFAPI_CRC_INDICATION_PDU_T entry = { .RX_UE_INFORMATION_TAG = i, .RNTI = i * 2, .CRC_INDICATION_REL8_TAG = 1 };
        addEntry(&crcList, entry);
    }

    logState(&crcList);

    // Simulate removing entries
    NFAPI_CRC_INDICATION_PDU_T removedEntry;
    for (int i = 0; i < 1000; ++i) {
        removeEntry(&crcList, 0, &removedEntry);
    }

    logState(&crcList);

    destroyCRCList(&crcList);
    return 0;
}
