#define MAX_PDU_SIZE 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct PduNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct PduNode* next;
} PduNode;

typedef struct {
    PduNode* head;
    size_t size;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} PduList;

PduList pdu_list = {NULL, 0, PTHREAD_MUTEX_INITIALIZER, PTHREAD_COND_INITIALIZER};

void log_message(const char* message) {
    printf("%s\n", message);
}

int random_crc_flag() {
    return rand() % 2; // Randomly returns 0 or 1
}

NFAPI_CRC_INDICATION_PDU_T create_pdu(int rx_ue_info_tag, int rnti) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    pdu.RNTI = rnti;
    pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = random_crc_flag();
    return pdu;
}

int add_pdu_to_list(int rx_ue_info_tag, int rnti) {
    pthread_mutex_lock(&pdu_list.mutex);

    if (pdu_list.size >= MAX_PDU_SIZE) {
        log_message("Maximum PDU size reached. Cannot add more PDUs.");
        pthread_mutex_unlock(&pdu_list.mutex);
        return -1;
    }

    PduNode* new_node = malloc(sizeof(PduNode));
    if (!new_node) {
        log_message("Memory allocation failed for new PDU node.");
        pthread_mutex_unlock(&pdu_list.mutex);
        return -1;
    }

    new_node->data = create_pdu(rx_ue_info_tag, rnti);
    new_node->next = pdu_list.head;
    pdu_list.head = new_node;
    pdu_list.size++;

    log_message("Successfully added a new PDU.");
    pthread_mutex_unlock(&pdu_list.mutex);
    return 0;
}

void cleanup_pdus() {
    pthread_mutex_lock(&pdu_list.mutex);

    PduNode* current = pdu_list.head;
    while (current) {
        PduNode* temp = current;
        current = current->next;
        free(temp);
    }

    pdu_list.head = NULL;
    pdu_list.size = 0;

    log_message("Cleaned up all PDUs.");
    pthread_mutex_unlock(&pdu_list.mutex);
}

void* periodic_cleanup(void* arg) {
    while (1) {
        sleep(60); // Cleanup every 60 seconds
        cleanup_pdus();
    }
    return NULL;
}

int main() {
    srand(time(NULL));

    pthread_t cleanup_thread;
    if (pthread_create(&cleanup_thread, NULL, &periodic_cleanup, NULL) != 0) {
        log_message("Failed to create periodic cleanup thread.");
        exit(EXIT_FAILURE);
    }

    // Simulate adding PDUs
    for (int i = 0; i < 1050; ++i) { // More than MAX_PDU_SIZE to test limits
        add_pdu_to_list(i, rand());
    }

    pthread_join(cleanup_thread, NULL); // Wait indefinitely

    return 0;
}
