typedef enum {
    EVENT_TYPE_A,
    EVENT_TYPE_B,
    // Add more event types as needed
} EventType;

typedef struct NICPEvent {
    unsigned long timestamp;
    EventType event_type;
    char *status_message;  // Dynamic allocation for status message to allow efficient updates
} NICPEvent;

// Function prototypes
void initNICPEvents(NICPEvent **events, size_t initial_capacity);
void addNICPEvent(NICPEvent **events, size_t *num_events, size_t capacity,
                  unsigned long timestamp, EventType event_type, const char *status_message);
void updateStatusMessage(NICPEvent *events, size_t num_events,
                         unsigned long timestamp, EventType event_type,
                         const char *new_status);
void sortNICPEventsByTimestamp(NICPEvent *events, size_t num_events);
void filterNICPEventsByType(NICPEvent **filtered_events, size_t *num_filtered_events,
                            NICPEvent *events, size_t num_events, EventType type);

// Implementation
void initNICPEvents(NICPEvent **events, size_t initial_capacity) {
    *events = (NICPEvent *)malloc(initial_capacity * sizeof(NICPEvent));
}

void addNICPEvent(NICPEvent **events, size_t *num_events, size_t capacity,
                  unsigned long timestamp, EventType event_type, const char *status_message) {
    if (*num_events >= capacity) {
        // Resize the array to accommodate more events
        capacity *= 2;
        NICPEvent *new_events = (NICPEvent *)realloc(*events, capacity * sizeof(NICPEvent));
        if (!new_events) {
            perror("Failed to reallocate memory for NICP events");
            exit(EXIT_FAILURE);
        }
        *events = new_events;
    }

    (*events)[*num_events].timestamp = timestamp;
    (*events)[*num_events].event_type = event_type;
    (*events)[*num_events].status_message = strdup(status_message); // Dynamic allocation
    if (!(*events)[*num_events].status_message) {
        perror("Failed to allocate memory for status message");
        exit(EXIT_FAILURE);
    }
    (*num_events)++;
}

void updateStatusMessage(NICPEvent *events, size_t num_events,
                         unsigned long timestamp, EventType event_type,
                         const char *new_status) {
    for (size_t i = 0; i < num_events; ++i) {
        if (events[i].timestamp == timestamp && events[i].event_type == event_type) {
            free(events[i].status_message);
            events[i].status_message = strdup(new_status);
            if (!events[i].status_message) {
                perror("Failed to allocate memory for updated status message");
                exit(EXIT_FAILURE);
            }
            break;
        }
    }
}

void sortNICPEventsByTimestamp(NICPEvent *events, size_t num_events) {
    // Simple bubble sort; replace with a more efficient algorithm like quicksort if needed
    for (size_t i = 0; i < num_events - 1; ++i) {
        for (size_t j = 0; j < num_events - i - 1; ++j) {
            if (events[j].timestamp > events[j + 1].timestamp) {
                NICPEvent temp = events[j];
                events[j] = events[j + 1];
                events[j + 1] = temp;
            }
        }
    }
}

void filterNICPEventsByType(NICPEvent **filtered_events, size_t *num_filtered_events,
                            NICPEvent *events, size_t num_events, EventType type) {
    *num_filtered_events = 0;

    for (size_t i = 0; i < num_events; ++i) {
        if (events[i].event_type == type) {
            addNICPEvent(filtered_events, num_filtered_events, 10, events[i].timestamp,
                         events[i].event_type, events[i].status_message);
        }
    }
}

// Usage example
int main() {
    NICPEvent *nicpEvents = NULL;
    size_t numNicpEvents = 0;

    initNICPEvents(&nicpEvents, 10);

    addNICPEvent(&nicpEvents, &numNicpEvents, 10, 1625079600, EVENT_TYPE_A, "Initial event");
    addNICPEvent(&nicpEvents, &numNicpEvents, 10, 1625083200, EVENT_TYPE_B, "Second event");

    updateStatusMessage(nicpEvents, numNicpEvents, 1625079600, EVENT_TYPE_A,
                        "Updated status for first event");

    sortNICPEventsByTimestamp(nicpEvents, numNicpEvents);

    NICPEvent *filteredEvents = NULL;
    size_t numFilteredEvents = 0;

    filterNICPEventsByType(&filteredEvents, &numFilteredEvents, nicpEvents,
                           numNicpEvents, EVENT_TYPE_A);

    // Cleanup
    for (size_t i = 0; i < numNicpEvents; ++i) {
        free(nicpEvents[i].status_message);
    }
    free(nicpEvents);

    for (size_t i = 0; i < numFilteredEvents; ++i) {
        free(filteredEvents[i].status_message);
    }
    free(filteredEvents);

    return 0;
}
