unsigned int calculateChecksum(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    return (pdu->RX_UE_INFORMATION_TAG + pdu->RNTI + pdu->CRC_INDICATION_REL8_TAG.CRCFLAG) & 0xFFFFFFFF;
}

int validatePDU(NFAPI_CRC_INDICATION_PDU_T* pdu, unsigned int expectedChecksum) {
    unsigned int actualChecksum = calculateChecksum(pdu);
    return actualChecksum == expectedChecksum;
}

NFAPI_CRC_INDICATION_PDU_T* initializeNfarxIndications(size_t count) {
    if (count <= 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* pdus = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) return NULL;

    srand(time(NULL)); // Seed for randomness

    unsigned int checksums[count];

    for (size_t i = 0; i < count; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = rand() % UINT_MAX;
        pdus[i].RNTI = rand() % UINT_MAX;
        pdus[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        checksums[i] = calculateChecksum(&pdus[i]);
    }

    for (size_t i = 0; i < count; ++i) {
        if (!validatePDU(&pdus[i], checksums[i])) {
            free(pdus);
            return NULL;
        }
    }

    return pdus;
}

void freeNfarxIndications(NFAPI_CRC_INDICATION_PDU_T* pdus) {
    if (pdus) {
        free(pdus);
    }
}
