#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>
#include <string.h>

// Assuming these structures and functions exist
typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint8_t CRCFLAG;
        // Other fields...
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void log_operation(const char* operation, pthread_t thread_id);
uint32_t get_random_uint32(void);

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
    pthread_mutex_t lock;
} NFAPI_List;

void init_list(NFAPI_List* list) {
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T create_pdu() {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = get_random_uint32();
    pdu.RNTI = (uint16_t)get_random_uint32(); // Simulate RNTI generation
    pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRCFLAG
    return pdu;
}

void add_pdu(NFAPI_List* list) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_operation("Failed to allocate memory", pthread_self());
        exit(EXIT_FAILURE);
    }
    new_node->data = create_pdu();
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    log_operation("Added PDU", pthread_self());

    pthread_mutex_unlock(&list->lock);
}

void serialize_list(const NFAPI_List* list, uint8_t** buffer, size_t* length) {
    // External serialization library assumed
    // Serialize the linked list to a binary format
    size_t estimated_size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->size;
    *buffer = (uint8_t*)malloc(estimated_size);
    if (!(*buffer)) {
        log_operation("Failed to allocate memory for serialization", pthread_self());
        exit(EXIT_FAILURE);
    }

    Node* current = list->head;
    size_t offset = 0;
    while (current) {
        memcpy((*buffer) + offset, &current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        current = current->next;
        offset += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    *length = estimated_size;
}

void health_check(const NFAPI_List* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        // Perform integrity checks on each PDU
        if (current->data.RX_UE_INFORMATION_TAG == 0 || current->data.RNTI == 0) {
            log_operation("Health check failed: Invalid data", pthread_self());
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void cleanup_list(NFAPI_List* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    list->size = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);

    log_operation("Cleaned up list", pthread_self());
}

void log_operation(const char* operation, pthread_t thread_id) {
    time_t now = time(NULL);
    printf("[%ld] [%lu] %s\n", now, (unsigned long)thread_id, operation);
}

int main() {
    NFAPI_List list;
    init_list(&list);

    for (size_t i = 0; i < 10; ++i) {
        add_pdu(&list);
    }

    uint8_t* buffer;
    size_t length;
    serialize_list(&list, &buffer, &length);

    health_check(&list);

    cleanup_list(&list);

    free(buffer);
    return 0;
}
