#include <time.h>

#define MAX_RNTI 65535
#define DEFAULT_MAX_SIZE 1000000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t count;
    size_t capacity;
} PduList;

void log_error(const char *message) {
    fprintf(stderr, "ERROR: %s\n", message);
}

bool validate_pdu(const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    return (pdu->RX_UE_INFORMATION_TAG != 0 && pdu->RNTI <= MAX_RNTI);
}

void free_pdu_list(PduList *list) {
    if (list && list->pdus) {
        free(list->pdus);
        list->pdus = NULL;
        list->count = 0;
        list->capacity = 0;
    }
}

PduList* generateNfapiPduList(int N, unsigned int seed, size_t max_size) {
    if (N <= 0 || max_size == 0) return NULL;

    srand(seed);
    PduList *list = malloc(sizeof(PduList));
    if (!list) {
        log_error("Memory allocation failed for PduList");
        return NULL;
    }

    list->capacity = N < max_size ? N : max_size;
    list->count = 0;
    list->pdus = calloc(list->capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->pdus) {
        log_error("Memory allocation failed for Pdu structures");
        free_pdu_list(list);
        return NULL;
    }

    unsigned int used_tags[MAX_RNTI + 1] = {0};
    bool success = false;

    while (list->count < N && list->count < list->capacity) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &list->pdus[list->count];
        pdu->RX_UE_INFORMATION_TAG = rand() % 100000; // Example range
        pdu->RNTI = (unsigned short)(rand() % (MAX_RNTI + 1));
        pdu->CRCFLAG = rand() % 2;

        if (!used_tags[pdu->RNTI] && validate_pdu(pdu)) {
            used_tags[pdu->RNTI] = 1;
            list->count++;
        } else {
            log_error("Duplicate RNTI or invalid PDU detected");
        }
    }

    success = (list->count == N);
    if (!success) {
        free_pdu_list(list);
        return NULL;
    }

    return list;
}

void validate_and_report(PduList *list) {
    int valid_count = 0;
    for (size_t i = 0; i < list->count; ++i) {
        if (validate_pdu(&list->pdus[i])) {
            valid_count++;
        }
    }

    printf("Validation Report: %d/%zu PDUs are valid.\n", valid_count, list->count);
}

int main() {
    int N = 1000;
    unsigned int seed = time(NULL);
    size_t max_size = DEFAULT_MAX_SIZE;

    PduList *pdu_list = generateNfapiPduList(N, seed, max_size);
    if (pdu_list) {
        validate_and_report(pdu_list);
        free_pdu_list(pdu_list);
    } else {
        log_error("Failed to generate NFAPI PDU list");
    }

    return 0;
}
