#define MAX_ELEMENTS 1000

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crcTag;
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ueInfoTag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* elements[MAX_ELEMENTS];
    size_t count;
    pthread_mutex_t lock;
} CRCIndicationList;

// Mock logging function
void log_creation(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Implementation of logging
}

// Error handling macro
#define HANDLE_ERROR(err_msg) do { perror(err_msg); exit(EXIT_FAILURE); } while (0)

CRCIndicationList* create_crc_indication_list() {
    CRCIndicationList* list = malloc(sizeof(CRCIndicationList));
    if (!list) HANDLE_ERROR("Memory allocation failed for list");

    memset(list->elements, 0, sizeof(list->elements));
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_crc_indication_list(CRCIndicationList* list) {
    if (!list) return;

    for (size_t i = 0; i < list->count; ++i) {
        free(list->elements[i]);
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_crc_indication_pdu(CRCIndicationList* list, uint16_t rnti) {
    if (!list || list->count >= MAX_ELEMENTS)
        return -1;

    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        pthread_mutex_unlock(&list->lock);
        HANDLE_ERROR("Memory allocation failed for PDU");
    }

    pdu->ueInfoTag.RNTI = rnti;
    pdu->ueInfoTag.crcTag.CRCFLAG = rand() % 2;

    list->elements[list->count++] = pdu;
    log_creation(pdu);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void remove_crc_indication_pdu(CRCIndicationList* list, size_t index) {
    if (!list || index >= list->count)
        return;

    pthread_mutex_lock(&list->lock);

    free(list->elements[index]);
    memmove(&list->elements[index], &list->elements[index + 1],
            (list->count - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    list->count--;

    pthread_mutex_unlock(&list->lock);
}

// Unit tests
void test_add_remove_elements() {
    CRCIndicationList* list = create_crc_indication_list();
    size_t initial_count = list->count;

    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        add_crc_indication_pdu(list, rand());
    }

    // Test that no more elements can be added
    assert(add_crc_indication_pdu(list, 1234) == -1);

    // Remove all elements
    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        remove_crc_indication_pdu(list, 0);
    }

    // Test that the list is empty
    assert(list->count == initial_count);

    destroy_crc_indication_list(list);
}

void test_concurrent_add_remove() {
    CRCIndicationList* list = create_crc_indication_list();

    pthread_t threads[MAX_ELEMENTS];
    size_t i;

    for (i = 0; i < MAX_ELEMENTS / 2; ++i) {
        pthread_create(&threads[i], NULL, (void*)add_crc_indication_pdu, (void*)list);
    }

    for (i = 0; i < MAX_ELEMENTS / 2; ++i) {
        pthread_join(threads[i], NULL);
    }

    assert(list->count == MAX_ELEMENTS / 2);

    destroy_crc_indication_list(list);
}

int main() {
    test_add_remove_elements();
    test_concurrent_add_remove();

    printf("All tests passed.\n");
    return 0;
}
