// Union-Find data structure for disjoint set operations
class UnionFind {
private:
    std::vector<int> parent, rank;

public:
    UnionFind(int size) : parent(size), rank(size, 0) {
        for (int i = 0; i < size; ++i)
            parent[i] = i;
    }

    int find(int u) {
        if (u != parent[u])
            parent[u] = find(parent[u]);
        return parent[u];
    }

    void unite(int u, int v) {
        int rootU = find(u);
        int rootV = find(v);

        if (rootU != rootV) {
            if (rank[rootU] > rank[rootV]) 
                parent[rootV] = rootU;
            else if (rank[rootU] < rank[rootV])
                parent[rootU] = rootV;
            else {
                parent[rootV] = rootU;
                ++rank[rootU];
            }
        }
    }

    bool connected(int u, int v) {
        return find(u) == find(v);
    }
};

int findDisjointPairsWithTiming(const std::vector<int>& array) {
    if (array.size() < 2) return 0;

    UnionFind uf(array.size());
    int disjointCount = 0;

    auto start = std::chrono::high_resolution_clock::now();

    for (size_t i = 0; i < array.size(); ++i) {
        for (size_t j = i + 1; j < array.size(); ++j) {
            if (!uf.connected(i, j)) {
                uf.unite(i, j);
                ++disjointCount;
            }
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double, std::milli> duration = end - start;

    std::cout << "Duration: " << duration.count() << " ms" << std::endl;

    return disjointCount;
}

extern "C" {
    int createNFAPacketListAndRunCommandWrapper(int numPackets, const char* command) {
        return createNFAPacketListAndRunCommand(numPackets, command);
    }

    int findDisjointPairsWithTimingWrapper(const int* array, size_t size) {
        std::vector<int> vec(array, array + size);
        return findDisjointPairsWithTiming(vec);
    }
}
