int validate_file_path(const char *path) {
    FILE *file = fopen(path, "r");
    if (!file) return 0;
    fclose(file);
    return 1;
}

size_t load_configuration_file(const char *filepath, size_t **items) {
    FILE *file = fopen(filepath, "r");
    if (!file) {
        perror("Failed to open file");
        return 0;
    }

    size_t count = 0;
    unsigned long rnti;

    while (fscanf(file, "%lu", &rnti) == 1) {
        (*items)[count].rx_ue_information_tag.rnti = rnti;
        (*items)[count].rnti = rnti;
        // Set CRCFLAG to a random value
        srand(time(NULL) + (unsigned int)rnti);
        (*items)[count].crc_indication_rel8_tag.crcflag = rand() % 2; // Random 0 or 1
        count++;
    }

    fclose(file);

    if (ferror(file)) {
        perror("Error reading file");
        free(*items);
        return 0;
    }

    return count;
}

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_nfa_items(const char *config_path, size_t *item_count) {
    if (!validate_file_path(config_path)) {
        fprintf(stderr, "Invalid file path: %s\n", config_path);
        return NULL;
    }

    FILE *file = fopen(config_path, "r");
    if (!file) {
        perror("Failed to open configuration file");
        return NULL;
    }

    // Initial attempt to count lines for memory allocation
    fseek(file, 0, SEEK_END);
    long fsize = ftell(file);
    rewind(file);

    size_t line_count = 1 + (fsize ? (fsize / sizeof(unsigned long)) : 0); // Approximate line count

    NFAPI_CRC_INDICATION_PDU_T *items = malloc(line_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!items) {
        perror("Memory allocation failed");
        fclose(file);
        return NULL;
    }

    size_t count = load_configuration_file(config_path, &items);

    // Adjust the allocated memory based on actual items loaded
    NFAPI_CRC_INDICATION_PDU_T *adjusted_items = realloc(items, count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!adjusted_items) {
        perror("Memory reallocation failed");
        free(items);
        fclose(file);
        return NULL;
    }

    *item_count = count;
    fclose(file);
    return adjusted_items;
}

int main() {
    size_t item_count = 0;
    const char *config_path = "path/to/config.txt";
    NFAPI_CRC_INDICATION_PDU_T *items = create_and_populate_nfa_items(config_path, &item_count);

    if (items) {
        printf("Loaded %zu items from the configuration file.\n", item_count);

        // Free allocated memory
        free(items);
    } else {
        fprintf(stderr, "Failed to load NFA items.\n");
    }

    return 0;
}
