void initialize_crc_indication_list(CRC_Indication_List *list) {
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

int add_entry(CRC_Indication_List *list, int rx_ue_tag, int rnti, int crc_rel8_tag) {
    if (pthread_mutex_lock(&list->lock)) {
        fprintf(stderr, "Failed to lock list\n");
        return -1;
    }

    if (list->count >= MAX_ENTRIES) {
        fprintf(stderr, "Resource exhaustion: List is full.\n");
        pthread_mutex_unlock(&list->lock);
        return -2; // Error code for resource exhaustion
    }

    NFAPI_CRC_INDICATION_PDU_T *entry = &list->entries[list->count];

    entry->RX_UE_INFORMATION_TAG = rx_ue_tag;
    entry->RNTI = rnti;
    entry->CRC_INDICATION_REL8_TAG = crc_rel8_tag;

    // Set CRCFLAG with random value aligned to the predefined mask
    srand(time(NULL) + rand()); // Seed for random number generation
    entry->CRCFLAG = (rand() & CRCFLAG_MASK);

    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void update_from_external_source(CRC_Indication_List *list, int (*external_data_provider)(int, int*, int*), int max_entries) {
    if (!pthread_mutex_trylock(&list->lock)) {
        for (size_t i = 0; i < list->count && i < max_entries; ++i) {
            int rnti, crc_rel8_tag;
            if (external_data_provider(i, &rnti, &crc_rel8_tag) == 0) {
                NFAPI_CRC_INDICATION_PDU_T *entry = &list->entries[i];

                entry->RNTI = rnti;
                entry->CRC_INDICATION_REL8_TAG = crc_rel8_tag;
            } else {
                fprintf(stderr, "Intermittent connectivity issue: Failed to update entry %zu.\n", i);
                // Handle failure case, perhaps retry or log detailed error
            }
        }

        pthread_mutex_unlock(&list->lock);
    } else {
        fprintf(stderr, "Failed to acquire lock for updating from external source.\n");
    }
}

void destroy_crc_indication_list(CRC_Indication_List *list) {
    pthread_mutex_destroy(&list->lock);
}

int main() {
    CRC_Indication_List list;
    initialize_crc_indication_list(&list);

    // Simulate adding entries
    for (int i = 0; i < 10; ++i) {
        add_entry(&list, i, rand(), rand());
    }

    // Simulate external update source function
    int external_data_provider(int index, int *rnti, int *crc_rel8_tag) {
        if (index % 2 == 0) return 1; // Simulate a connectivity issue on even indices
        *rnti = rand();
        *crc_rel8_tag = rand();
        return 0;
    }

    update_from_external_source(&list, external_data_provider, MAX_ENTRIES);

    destroy_crc_indication_list(&list);
    return 0;
}
