    pthread_mutex_t lock;
    int operation_success_count;
    int error_count;
} CRC_Indication_Collection;

void init_collection(CRC_Indication_Collection* collection) {
    collection->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!collection->data) exit(EXIT_FAILURE); // Handle out-of-memory
    collection->capacity = INITIAL_CAPACITY;
    collection->size = 0;
    pthread_mutex_init(&collection->lock, NULL);
    collection->operation_success_count = 0;
    collection->error_count = 0;
}

void destroy_collection(CRC_Indication_Collection* collection) {
    free(collection->data);
    pthread_mutex_destroy(&collection->lock);
}

int resize_if_needed(CRC_Indication_Collection* collection) {
    if (collection->size >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(collection->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) return 0; // Out-of-memory
        collection->data = new_data;
        collection->capacity = new_capacity;
    }
    return 1;
}

int add_element(CRC_Indication_Collection* collection, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&collection->lock);
    if (!resize_if_needed(collection)) {
        collection->error_count++;
        pthread_mutex_unlock(&collection->lock);
        return -1; // Out-of-memory
    }
    collection->data[collection->size++] = element;
    collection->operation_success_count++;
    pthread_mutex_unlock(&collection->lock);
    return 0;
}

int remove_element(CRC_Indication_Collection* collection, size_t index) {
    pthread_mutex_lock(&collection->lock);
    if (index >= collection->size) {
        collection->error_count++;
        pthread_mutex_unlock(&collection->lock);
        return -1; // Invalid index
    }
    for (size_t i = index; i < collection->size - 1; i++) {
        collection->data[i] = collection->data[i + 1];
    }
    collection->size--;
    collection->operation_success_count++;
    pthread_mutex_unlock(&collection->lock);
    return 0;
}

int update_element(CRC_Indication_Collection* collection, size_t index, NFAPI_CRC_INDICATION_PDU_T new_value) {
    pthread_mutex_lock(&collection->lock);
    if (index >= collection->size) {
        collection->error_count++;
        pthread_mutex_unlock(&collection->lock);
        return -1; // Invalid index
    }
    collection->data[index] = new_value;
    collection->operation_success_count++;
    pthread_mutex_unlock(&collection->lock);
    return 0;
}

void print_statistics(CRC_Indication_Collection* collection) {
    printf("Operations Success: %d, Errors: %d\n", collection->operation_success_count, collection->error_count);
}

// Example usage
