        std::lock_guard<std::mutex> lock(mtx);
        if (data_list.size() < max_capacity) {
            data_list.push_back(element);
            operation_success_count++;
        } else {
            error_count++;
            log("Add operation failed: Capacity reached.");
        }
    }

    void removeElement(size_t index) {
        std::lock_guard<std::mutex> lock(mtx);
        if (index < data_list.size()) {
            data_list.erase(data_list.begin() + index);
            operation_success_count++;
        } else {
            error_count++;
            log("Remove operation failed: Index out of bounds.");
        }
    }

    void updateElement(size_t index, const NFAPI_CRC_INDICATION_PDU_T& element) {
        std::lock_guard<std::mutex> lock(mtx);
        if (index < data_list.size()) {
            data_list[index] = element;
            operation_success_count++;
        } else {
            error_count++;
            log("Update operation failed: Index out of bounds.");
        }
    }

