#define MME_ID_FORMAT_SIZE 16 // Example format size for MME_ID

typedef struct {
    int UE_ID;
    int UE_CONTEXT_TAG;
    char* MAC_Entity_ID; // Dynamically allocated MME_ID string
} LTE_ENB_RRC_API_UE_STATE;

typedef struct {
    LTE_ENB_RRC_API_UE_STATE** array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

// Function to initialize and populate the dynamic array of UE states
int init_and_populate_ue_states(DynamicArray* da, size_t initial_capacity) {
    if (!da || initial_capacity == 0) return -1; // Error: Invalid input

    pthread_mutex_init(&da->lock, NULL);
    da->array = (LTE_ENB_RRC_API_UE_STATE**)calloc(initial_capacity, sizeof(LTE_ENB_RRC_API_UE_STATE*));
    if (!da->array) {
        pthread_mutex_destroy(&da->lock);
        return -1; // Error: Memory allocation failed
    }

    da->capacity = initial_capacity;
    da->count = 0;

    for (size_t i = 0; i < initial_capacity; ++i) {
        LTE_ENB_RRC_API_UE_STATE* ue_state = malloc(sizeof(LTE_ENB_RRC_API_UE_STATE));
        if (!ue_state) {
            free_array_resources(da);
            pthread_mutex_destroy(&da->lock);
            return -1; // Error: Memory allocation failed
        }

        ue_state->UE_ID = (int)i;
        ue_state->UE_CONTEXT_TAG = i + 1000;

        char* mme_id = malloc(MME_ID_FORMAT_SIZE);
        if (!mme_id) {
            free(ue_state);
            free_array_resources(da);
            pthread_mutex_destroy(&da->lock);
            return -1; // Error: Memory allocation failed
        }
        snprintf(mme_id, MME_ID_FORMAT_SIZE, "MME-%08zu", i); // Example format for MME_ID
        ue_state->MAC_Entity_ID = mme_id;

        da->array[i] = ue_state;
    }

    return 0; // Success
}

// Helper function to free allocated resources in case of failure
void free_array_resources(DynamicArray* da) {
    if (da && da->array) {
        for (size_t i = 0; i < da->count; ++i) {
            if (da->array[i]) {
                free(da->array[i]->MAC_Entity_ID);
                free(da->array[i]);
            }
        }
        free(da->array);
    }
}

// Example usage
int main() {
    DynamicArray da;
    int result = init_and_populate_ue_states(&da, 10);

    if (result == 0) {
        printf("UE states initialized successfully.\n");
    } else {
        fprintf(stderr, "Failed to initialize UE states.\n");
    }

