#define MAX_ELEMENTS 10000
#define MEMORY_POOL_SIZE (MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T))
#define LOG_LEVEL_NONE 0
#define LOG_LEVEL_INFO 1
#define LOG_LEVEL_DEBUG 2

typedef struct {
