    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
    int log_level;
    FILE *log_file;
    volatile int successful_ops;
    volatile int error_ops;
} CRCManager;

CRCManager crc_manager = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER, LOG_LEVEL_NONE, NULL, 0, 0};

void log_message(int level, const char *message) {
    if (crc_manager.log_file && crc_manager.log_level >= level) {
        fprintf(crc_manager.log_file, "%s\n", message);
        fflush(crc_manager.log_file);
    }
}

void init_crc_manager(size_t initial_capacity) {
    pthread_mutex_lock(&crc_manager.mutex);
    crc_manager.data = malloc(MEMORY_POOL_SIZE);
    if (!crc_manager.data) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    crc_manager.capacity = initial_capacity;
    crc_manager.size = 0;
    pthread_mutex_unlock(&crc_manager.mutex);
}

void free_crc_manager() {
    pthread_mutex_lock(&crc_manager.mutex);
    free(crc_manager.data);
    crc_manager.data = NULL;
    crc_manager.size = 0;
    crc_manager.capacity = 0;
    if (crc_manager.log_file) {
        fclose(crc_manager.log_file);
        crc_manager.log_file = NULL;
    }
    pthread_mutex_unlock(&crc_manager.mutex);
}

void add_element(NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&crc_manager.mutex);

    while (crc_manager.size >= crc_manager.capacity) {
        size_t new_capacity = crc_manager.capacity * 2;
        if (new_capacity > MAX_ELEMENTS) break;

        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(crc_manager.data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&crc_manager.mutex);
            log_message(LOG_LEVEL_INFO, "Failed to reallocate memory");
            crc_manager.error_ops++;
            return;
        }
        crc_manager.data = new_data;
        crc_manager.capacity = new_capacity;
    }

    if (crc_manager.size < MAX_ELEMENTS) {
        crc_manager.data[crc_manager.size++] = element;
        crc_manager.successful_ops++;
    } else {
        log_message(LOG_LEVEL_INFO, "Reached maximum capacity");
        crc_manager.error_ops++;
    }

    pthread_mutex_unlock(&crc_manager.mutex);
}

void remove_element(size_t index) {
    pthread_mutex_lock(&crc_manager.mutex);

    if (index >= crc_manager.size) {
        log_message(LOG_LEVEL_INFO, "Invalid index for removal");
        crc_manager.error_ops++;
        pthread_mutex_unlock(&crc_manager.mutex);
        return;
    }

    memmove(&crc_manager.data[index], &crc_manager.data[index + 1], (crc_manager.size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    crc_manager.size--;
    crc_manager.successful_ops++;

    pthread_mutex_unlock(&crc_manager.mutex);
}

void update_crcflag(size_t index, bool new_flag) {
    pthread_mutex_lock(&crc_manager.mutex);

    if (index >= crc_manager.size) {
        log_message(LOG_LEVEL_INFO, "Invalid index for CRCFLAG update");
        crc_manager.error_ops++;
        pthread_mutex_unlock(&crc_manager.mutex);
        return;
    }

    crc_manager.data[index].CRC_INDICATION_REL8_TAG.CRCFLAG = new_flag;
    crc_manager.successful_ops++;

    pthread_mutex_unlock(&crc_manager.mutex);
}

NFAPI_CRC_INDICATION_PDU_T* get_element(size_t index) {
    pthread_mutex_lock(&crc_manager.mutex);

    NFAPI_CRC_INDICATION_PDU_T *result = NULL;
    if (index < crc_manager.size) {
        result = &crc_manager.data[index];
        crc_manager.successful_ops++;
    } else {
        log_message(LOG_LEVEL_INFO, "Invalid index for retrieval");
        crc_manager.error_ops++;
    }

    pthread_mutex_unlock(&crc_manager.mutex);
    return result;
}

void filter_and_add_elements(uint16_t rnti_start, uint16_t rnti_end) {
    // Simulated function to populate the list with filtered elements
    for (size_t i = 0; i < crc_manager.size; i++) {
        if (crc_manager.data[i].RNTI >= rnti_start && crc_manager.data[i].RNTI <= rnti_end) {
            NFAPI_CRC_INDICATION_PDU_T new_element;
            new_element.RX_UE_INFORMATION_TAG = rand();
            new_element.RNTI = crc_manager.data[i].RNTI + 1; // Example increment
            new_element.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2 == 0;

            add_element(new_element);
        }
    }
}

void set_log_file(FILE *file, int level) {
    pthread_mutex_lock(&crc_manager.mutex);
    if (crc_manager.log_file) {
        fclose(crc_manager.log_file);
    }
    crc_manager.log_file = file;
    crc_manager.log_level = level;
    pthread_mutex_unlock(&crc_manager.mutex);
}

void adjust_log_level(int new_level) {
