    int RNTI;
    struct {
        bool CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
};

class NFACacheManager {
public:
    NFACacheManager() : maxEntries(5000), activeEntries(0) {}

    void populateNFAPIListAndSelectStrategy(size_t N);

private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T> nfaPis;
    size_t maxEntries;
    size_t activeEntries;

    mutable std::mutex mtx;
    std::atomic<bool> configUpdated{false};

    void updateMaxEntries();
    bool validateCRCFlags(const std::vector<bool>& reference);
    void logOperation(const std::string& message) const;
    void notifyComponents() const;

    // Simulated external system check for load-based configuration
