    bool retryOnFailure(Func func, int retries = 3);
};

void NFACacheManager::populateNFAPIListAndSelectStrategy(size_t N) {
    std::lock_guard<std::mutex> lock(mtx);

    if (configUpdated.load()) {
        updateMaxEntries();
    }

    // Strategy selection logic
    int strategyNumber = rand() % 3 + 1;
    std::cout << "Selected strategy number: " << strategyNumber << std::endl;

    nfaPis.clear();

    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> tagDist(0, 10000);
    std::uniform_int_distribution<> rntiDist(0, 10000);
    std::bernoulli_distribution crcFlagDist(0.5);

    for (size_t i = 0; i < N && activeEntries < maxEntries; ++i) {
        nfaPis.emplace_back({
            tagDist(gen),
            rntiDist(gen),
            {crcFlagDist(gen)}
        });
        ++activeEntries;
    }

    logOperation("NFAPI structures populated");
    notifyComponents();
}

size_t NFACacheManager::getSystemLoadConfiguration() {
    // Simulated dynamic adjustment based on system load
    std::this_thread::sleep_for(std::chrono::milliseconds(50));  // Simulate delay
    return rand() % (maxEntries - 1000) + 3000;  // Randomize for example purposes
}

void NFACacheManager::updateMaxEntries() {
    maxEntries = getSystemLoadConfiguration();
    configUpdated.store(false);
}

bool NFACacheManager::validateCRCFlags(const std::vector<bool>& reference) {
    bool isValid = true;
    for (size_t i = 0; i < nfaPis.size(); ++i) {
        if (nfaPis[i].CRC_INDICATION_REL8_TAG.CRCFLAG != reference[i]) {
            logOperation("Discrepancy found in CRC flags");
            isValid = false;
        }
    }
    return isValid;
}

template<typename Func>
bool NFACacheManager::retryOnFailure(Func func, int retries) {
    while (retries-- > 0) {
        if (func()) return true;
        std::this_thread::sleep_for(std::chrono::milliseconds(100)); // Backoff
    }
    logOperation("Failed after multiple attempts");
    return false;
}

void NFACacheManager::logOperation(const std::string& message) const {
    // Implement logging mechanism
    std::cout << "[LOG] " << message << std::endl;
}

void NFACacheManager::notifyComponents() const {
    // Notify dependent components using callbacks or other mechanisms
    logOperation("Notifying dependent components");
}
