#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Assuming these are defined elsewhere in your system.
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define INITIAL_SIZE 10
#define GROWTH_FACTOR 2

// Node structure for linked list management of dynamic array
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Structure to manage the array and its mutex
typedef struct {
    Node* head;
    size_t size;
    pthread_mutex_t lock;
} CRCManager;

CRCManager* create_crc_manager() {
    CRCManager* manager = (CRCManager*)malloc(sizeof(CRCManager));
    if (!manager) return NULL;

    manager->head = NULL;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void free_crc_manager(CRCManager* manager) {
    Node* current = manager->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_entry(CRCManager* manager, int rnti) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->lock);

    Node* current = manager->head;
    while (current) {
        if (current->data.RNTI == rnti) {
            pthread_mutex_unlock(&manager->lock);
            return 0; // Entry already exists
        }
        current = current->next;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Allocation failed
    }

    new_node->data.RX_UE_INFORMATION_TAG = rand(); // Replace with actual logic
    new_node->data.RNTI = rnti;
    new_node->data.CRC_INDICATION_REL8_TAG.CRCFLAG = generate_random_crc_flag();

    new_node->next = manager->head;
    manager->head = new_node;
    manager->size++;

    pthread_mutex_unlock(&manager->lock);
    return 1; // Success
}

int update_entry(CRCManager* manager, int rnti) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->lock);

    Node* current = manager->head;
    while (current) {
        if (current->data.RNTI == rnti) {
            // Update logic; assume CRCFLAG needs updating
            current->data.CRC_INDICATION_REL8_TAG.CRCFLAG = generate_random_crc_flag();
            pthread_mutex_unlock(&manager->lock);
            return 1; // Success
        }
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
    return 0; // Entry not found
}

int remove_entry(CRCManager* manager, int rnti) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->lock);

    Node *current = manager->head, *prev = NULL;
    while (current) {
        if (current->data.RNTI == rnti) {
            if (prev)
                prev->next = current->next;
            else
                manager->head = current->next;

            free(current);
            manager->size--;
            pthread_mutex_unlock(&manager->lock);
            return 1; // Success
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
    return 0; // Entry not found
}

// Stub function for generating random CRC flags
int generate_random_crc_flag() {
    return rand() % 2; // Returns a random 0 or 1
}
