    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

// Configuration parameters (placeholders for external configuration)
#define DEFAULT_MAX_LIST_SIZE 100
size_t max_list_size = DEFAULT_MAX_LIST_SIZE;
size_t resize_threshold = max_list_size / 2;

// Thread-safe list structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} CRC_Indication_List;

// Function prototypes
void initialize_list(CRC_Indication_List *crcList);
int add_crc_indication(CRC_Indication_List *crcList, NFAPI_CRC_INDICATION_PDU_T pdu);
void resize_list(CRC_Indication_List *crcList);
int serialize_list(const CRC_Indication_List *crcList, const char *filename);
void log_error(const char *message);

// Function implementations
void initialize_list(CRC_Indication_List *crcList) {
    crcList->list = NULL;
    crcList->count = 0;
    crcList->capacity = 0;
    pthread_mutex_init(&crcList->mutex, NULL);
}

int add_crc_indication(CRC_Indication_List *crcList, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&crcList->mutex);

    if (crcList->count >= crcList->capacity) {
        resize_list(crcList);
    }

    crcList->list[crcList->count++] = pdu;

    pthread_mutex_unlock(&crcList->mutex);
    return 0; // Success
}

void resize_list(CRC_Indication_List *crcList) {
    size_t new_capacity = (crcList->capacity == 0) ? 10 : crcList->capacity * 2;
    if (new_capacity > max_list_size) {
        log_error("Maximum list size exceeded");
        return; // Do not resize beyond maximum allowed
    }

    NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(crcList->list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_list == NULL) {
        log_error("Memory allocation failed during resizing");
        return;
    }
    crcList->list = new_list;
    crcList->capacity = new_capacity;
}

int serialize_list(const CRC_Indication_List *crcList, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        log_error("Failed to open file for serialization");
        return -1; // Error
    }

    pthread_mutex_lock((pthread_mutex_t *)&crcList->mutex);

    size_t written = fwrite(crcList->list, sizeof(NFAPI_CRC_INDICATION_PDU_T), crcList->count, file);
    if (written != crcList->count) {
        log_error("Failed to serialize the entire list");
        pthread_mutex_unlock((pthread_mutex_t *)&crcList->mutex);
        fclose(file);
        return -1; // Error
    }

    pthread_mutex_unlock((pthread_mutex_t *)&crcList->mutex);

    fclose(file);
    return 0; // Success
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Example usage
int main() {
    CRC_Indication_List crcList;
    initialize_list(&crcList);

    NFAPI_CRC_INDICATION_PDU_T pdu = { .rx_ue_info = {1}, .rnti = 12345 };
    srand(time(NULL));
    pdu.crc_indication_rel8.CRCFLAG = rand() % 2; // Random CRC flag

    add_crc_indication(&crcList, pdu);

    if (serialize_list(&crcList, "output.bin") != 0) {
        log_error("Serialization failed");
    }

    free(crcList.list);
    pthread_mutex_destroy(&crcList.mutex);

    return 0;
}
```

### Key Points:
- **Thread Safety**: The list operations are protected by a mutex to ensure thread safety.
- **Dynamic Resizing**: The list resizes when the count reaches capacity, doubling its size until it hits the maximum allowed size.
