    LTE_RRC_CUCU_MESSAGE *cucu_messages;
    RRC_CONNECTION_RECONFIGURATION_INDICATION *reconfig_indications;
} DynamicArray;

int initialize_dynamic_array(DynamicArray *array, size_t initial_capacity) {
    if (!array) return -1;

    array->capacity = initial_capacity;
    array->size = 0;

    array->cucu_messages = (LTE_RRC_CUCU_MESSAGE *)malloc(array->capacity * sizeof(LTE_RRC_CUCU_MESSAGE));
