    array->reconfig_indications = (RRC_CONNECTION_RECONFIGURATION_INDICATION *)malloc(array->capacity * sizeof(RRC_CONNECTION_RECONFIGURATION_INDICATION));
    if (!array->reconfig_indications) {
        free(array->cucu_messages);
        return -1;
    }

    for (size_t i = 0; i < array->capacity; ++i) {
        array->cucu_messages[i].message_tag.id = rand() % 1000; // Example ID generation
        snprintf(array->cucu_messages[i].message_tag.content, sizeof(array->cucu_messages[i].message_tag.content), "Message %zu", i);

        snprintf(array->reconfig_indications[i].nas_message_content, sizeof(array->reconfig_indications[i].nas_message_content),
                 "NAS Transport for Message %zu", i);
    }

    return 0;
}

int resize_dynamic_array(DynamicArray *array) {
    if (!array) return -1;

    size_t new_capacity = array->capacity * RESIZE_FACTOR;
    LTE_RRC_CUCU_MESSAGE *new_cucu_messages = (LTE_RRC_CUCU_MESSAGE *)realloc(array->cucu_messages, new_capacity * sizeof(LTE_RRC_CUCU_MESSAGE));
    if (!new_cucu_messages) return -1;

    RRC_CONNECTION_RECONFIGURATION_INDICATION *new_reconfig_indications = (RRC_CONNECTION_RECONFIGURATION_INDICATION *)realloc(array->reconfig_indications, new_capacity * sizeof(RRC_CONNECTION_RECONFIGURATION_INDICATION));
    if (!new_reconfig_indications) {
        free(new_cucu_messages);
        return -1;
    }

    array->cucu_messages = new_cucu_messages;
    array->reconfig_indications = new_reconfig_indications;
    array->capacity = new_capacity;

    for (size_t i = array->size; i < array->capacity; ++i) {
        array->cucu_messages[i].message_tag.id = rand() % 1000; // Example ID generation
        snprintf(array->cucu_messages[i].message_tag.content, sizeof(array->cucu_messages[i].message_tag.content), "Message %zu", i);

        snprintf(array->reconfig_indications[i].nas_message_content, sizeof(array->reconfig_indications[i].nas_message_content),
                 "NAS Transport for Message %zu", i);
    }

    return 0;
}

void add_message(DynamicArray *array) {
    if (!array || array->size == array->capacity) {
        if (resize_dynamic_array(array) != 0) {
            fprintf(stderr, "Failed to resize the dynamic array.\n");
            exit(EXIT_FAILURE);
        }
    }

    array->cucu_messages[array->size].message_tag.id = rand() % 1000; // Example ID generation
    snprintf(array->cucu_messages[array->size].message_tag.content, sizeof(array->cucu_messages[array->size].message_tag.content), "Message %zu", array->size);

    snprintf(array->reconfig_indications[array->size].nas_message_content, sizeof(array->reconfig_indications[array->size].nas_message_content),
             "NAS Transport for Message %zu", array->size);

    ++array->size;
}

void free_dynamic_array(DynamicArray *array) {
    if (array) {
        free(array->cucu_messages);
        free(array->reconfig_indications);
        array->cucu_messages = NULL;
        array->reconfig_indications = NULL;
        array->capacity = 0;
        array->size = 0;
    }
}

int main() {
    DynamicArray array;
    if (initialize_dynamic_array(&array, INITIAL_CAPACITY) != 0) {
        fprintf(stderr, "Failed to initialize dynamic array.\n");
        return EXIT_FAILURE;
    }

    // Simulate adding messages
    for (size_t i = 0; i < 20; ++i) { // Example load
        add_message(&array);
    }

    // Use the data in `array.cucu_messages` and `array.reconfig_indications` as needed...

    free_dynamic_array(&array);

    return EXIT_SUCCESS;
}
