['Below is a C implementation that addresses the requirements outlined in your task:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_RNTI_ENTRIES 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    uint8_t CRCFLAG; // Assume it's a single byte for simplicity
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pdu_list;
    size_t count;
    pthread_mutex_t lock;
} NFAPI_CRC_LIST;

// Function prototypes
NFAPI_CRC_LIST* create_crc_list();
void destroy_crc_list(NFAPI_CRC_LIST* list);
int add_crc_pdu(NFAPI_CRC_LIST* list, unsigned int rnti);
uint8_t generate_non_consecutive_crcflag(uint8_t previous_crcflag);
void log_message(const char* message);

// Initialize the CRC list
NFAPI_CRC_LIST* create_crc_list() {
    NFAPI_CRC_LIST* list = (NFAPI_CRC_LIST*)malloc(sizeof(NFAPI_CRC_LIST));
    if (!list) {
        log_message("Memory allocation failed for NFAPI_CRC_LIST");
        return NULL;
    }

    list->pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)calloc(MAX_RNTI_ENTRIES, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->pdu_list) {
        log_message("Memory allocation failed for pdu_list");
        free(list);
        return NULL;
    }

    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);

    log_message("NFAPI_CRC_LIST created successfully");
    return list;
}

// Destroy the CRC list
void destroy_crc_list(NFAPI_CRC_LIST* list) {
    if (!list) return;

    free(list->pdu_list);
    pthread_mutex_destroy(&list->lock);
    free(list);

    log_message("NFAPI_CRC_LIST destroyed successfully");
}

// Add a new CRC PDU to the list
int add_crc_pdu(NFAPI_CRC_LIST* list, unsigned int rnti) {
    if (!list || list->count >= MAX_RNTI_ENTRIES) return -1;

    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->pdu_list[i].RNTI == rnti) {
            log_message("Duplicate RNTI detected");
            pthread_mutex_unlock(&list->lock);
            return -2;
        }
    }

    uint8_t previous_crcflag = 0;
    if (list->count > 0) {
        previous_crcflag = list->pdu_list[list->count - 1].CRCFLAG;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = &list->pdu_list[list->count];
    pdu->RX_UE_INFORMATION_TAG = rand() % 100; // Example value
    pdu->RNTI = rnti;
    pdu->CRCFLAG = generate_non_consecutive_crcflag(previous_crcflag);

    list->count++;
    log_message("CRC PDU added successfully");

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Generate a non-consecutive CRCFLAG
uint8_t generate_non_consecutive_crcflag(uint8_t previous_crcflag) {
    uint8_t crcflag;
    do {
        crcflag = rand() % 256; // Example range for CRCFLAG
    } while (crcflag == previous_crcflag);

    return crcflag;
}

// Log messages to track the process
void log_message(const char* message) {
    printf("%s\n", message);
}

int main() {
    srand(time(NULL)); // Seed random number generator

    NFAPI_CRC_LIST* list = create_crc_list();
    if (!list) return -1;

    for (unsigned int rnti = 0; rnti < MAX_RNTI_ENTRIES; ++rnti) {
        int result = add_crc_pdu(list, rnti);
        if (result != 0) {
            log_message("Failed to add CRC PDU");
        }
    }

    destroy_crc_list(list);
    return 0;
}
```

### Key Points:

- **Memory Management**: Allocates and frees memory for the list of PDUs.
- **Unique RNTI**: Checks for duplicate RNTIs before adding a new entry.
- **Non-Consecutive CRCFLAG**: Ensures diversity by generating non-consecutive CRCFLAG values.
- **Thread Safety**: Uses `pthread_mutex_t` to ensure thread safety.
- **Logging**: Provides logging for each significant action.
- **Scalability**: Designed to accommodate future expansions with minimal changes.

This code provides a robust starting point, focusing on performance and resource management while maintaining flexibility for future enhancements.']

