#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <uuid/uuid.h>

#define MAX_FILENAME_LENGTH 150
#define MIN_FILENAME_TRUNCATE 120
#define RANDOM_SEQ_MIN_LENGTH 5
#define RANDOM_SEQ_MAX_LENGTH 10

typedef struct {
    time_t timestamp;
    int event_id;
    char uuid[37]; // UUID string with null terminator
} NetworkEventLog;

typedef struct Node {
    NetworkEventLog log;
    struct Node* next;
} LogNode;

int file_type_usage_counter[5] = {0, 0, 0, 0, 0};
const char* file_types[] = {".log", ".json", ".xml", ".csv", ".db"};
char previous_file_type_index = -1;
int session_counter = 0;

void generate_random_sequence(char *buffer, size_t buffer_size) {
    const char charset[] =
        "abcdefghijklmnopqrstuvwxyz"
        "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        "0123456789";
    if (buffer_size < RANDOM_SEQ_MIN_LENGTH || buffer_size > RANDOM_SEQ_MAX_LENGTH)
        return; // Invalid buffer size

    time_t t;
    srand((unsigned) time(&t));
    for (size_t n = 0; n < rand() % (RANDOM_SEQ_MAX_LENGTH - RANDOM_SEQ_MIN_LENGTH + 1) + RANDOM_SEQ_MIN_LENGTH; ++n) {
        if (n < buffer_size - 1)
            buffer[n] = charset[rand() % (sizeof(charset) - 1)];
    }
    buffer[buffer_size - 1] = '\0';
}

int select_random_file_type(int previous_index) {
    int selected_index;
    do {
        selected_index = rand() % 5;
    } while ((previous_index == selected_index && file_type_usage_counter[selected_index] >= 3) ||
             (file_type_usage_counter[selected_index] == 0));

    if (++session_counter > 4) { // Ensure each type is used at least once
        for (int i = 0; i < 5; ++i)
            if (file_type_usage_counter[i] == 0)
                return i;
    }

    file_type_usage_counter[selected_index]++;
    previous_file_type_index = selected_index;
    return selected_index;
}

void manage_network_event_logs(LogNode **head, const char *original_filename) {
    // Create a UUID
    uuid_t uuid;
    uuid_generate_random(uuid);
    char uuid_str[37];
    uuid_unparse_lower(uuid, uuid_str);

    // Get the current timestamp
    time_t now = time(NULL);

    // Allocate new log node
    LogNode* new_node = (LogNode*)malloc(sizeof(LogNode));
    if (!new_node) {
        perror("Failed to allocate memory for a new log entry");
        exit(EXIT_FAILURE);
    }

    // Populate the log entry
    new_node->log.timestamp = now;
    new_node->log.event_id = rand(); // Assuming event ID is generated randomly
    strncpy(new_node->log.uuid, uuid_str, 36);

    // Add to linked list
    new_node->next = *head;
    *head = new_node;

    // Modify the filename
    char random_sequence[RANDOM_SEQ_MAX_LENGTH + 1];
    generate_random_sequence(random_sequence, RANDOM_SEQ_MAX_LENGTH);

    int file_type_index = select_random_file_type(previous_file_type_index);
    const char* selected_file_type = file_types[file_type_index];

    char new_filename[MAX_FILENAME_LENGTH + 1] = "";
    if (strlen(original_filename) > MIN_FILENAME_TRUNCATE) {
        strncpy(new_filename, original_filename, MAX_FILENAME_LENGTH - strlen(random_sequence) - strlen(selected_file_type));
    } else {
        strcpy(new_filename, original_filename);
    }

    // Construct the final filename
    snprintf(new_filename + strlen(new_filename), sizeof(new_filename) - strlen(new_filename),
             "_%s%s", random_sequence, selected_file_type);

    printf("New Filename: %s\n", new_filename);
}

// Example of usage:
int main() {
    LogNode* log_list = NULL;
    const char *original_filename = "example/path/to/logfile_with_very_long_name.txt";

    manage_network_event_logs(&log_list, original_filename);

    // Free allocated memory for logs (omitted for brevity)

    return 0;
}
