#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

#define MAX_RNTI 0xFFFFF
#define MEMORY_LIMIT_PERCENTAGE 50

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Custom memory pool structure
typedef struct {
    void *pool;
    size_t element_size;
    size_t max_elements;
    pthread_mutex_t lock;
} MemoryPool;

// Global variables for logging and memory management
pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;
int current_log_level = 1; // Default log level

MemoryPool* create_memory_pool(size_t element_size, size_t max_elements) {
    MemoryPool *pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->element_size = element_size;
    pool->max_elements = max_elements;
    pool->pool = malloc(element_size * max_elements);
    if (!pool->pool) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_memory_pool(MemoryPool *pool) {
    if (pool) {
        if (pool->pool) free(pool->pool);
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_tags(int min_rnti, int max_rnti, size_t num_elements, MemoryPool *pool) {
    if (!pool || pool->element_size != sizeof(NFAPI_CRC_INDICATION_PDU_T)) return NULL;

    pthread_mutex_lock(&pool->lock);

    // Calculate available memory and set limit
    long total_memory = sysconf(_SC_PAGESIZE) * sysconf(_SC_PHYS_PAGES);
    size_t max_allocation = (total_memory * MEMORY_LIMIT_PERCENTAGE) / 100;
    if (num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T) > max_allocation) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Allocation exceeds memory limit
    }

    NFAPI_CRC_INDICATION_PDU_T *tags = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!tags) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Allocation failed
    }

    srand(time(NULL)); // Seed for random number generation

    for (size_t i = 0; i < num_elements; ++i) {
        int rnti = rand() % (MAX_RNTI + 1); // Random RNTI
        if (rnti >= min_rnti && rnti <= max_rnti) {
            tags[i].RX_UE_INFORMATION_TAG = i;
            tags[i].RNTI = rnti;
            tags[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRC flag
        } else {
            --i; // Retry with a new random RNTI
        }
    }

    pthread_mutex_unlock(&pool->lock);
    return tags;
}

void log_tag_details(NFAPI_CRC_INDICATION_PDU_T *tags, size_t num_elements, const char* filename) {
    FILE *log_file = fopen(filename, "a");
    if (!log_file) return;

    for (size_t i = 0; i < num_elements; ++i) {
        pthread_mutex_lock(&log_lock);
        fprintf(log_file, "Tag: %d, RNTI: %u, CRCFLAG: %d\n",
                tags[i].RX_UE_INFORMATION_TAG,
                tags[i].RNTI,
                tags[i].CRC_INDICATION_REL8_TAG.CRCFLAG);
        pthread_mutex_unlock(&log_lock);
    }

    fclose(log_file);
}

void adjust_log_level(int level) {
    pthread_mutex_lock(&log_lock);
    current_log_level = level;
    pthread_mutex_unlock(&log_lock);
}

int main() {
    size_t num_elements = 1000; // Example number of elements
    int min_rnti = 1, max_rnti = 500;

    MemoryPool *pool = create_memory_pool(sizeof(NFAPI_CRC_INDICATION_PDU_T), num_elements);
    if (!pool) {
        fprintf(stderr, "Failed to create memory pool\n");
        return EXIT_FAILURE;
    }

    NFAPI_CRC_INDICATION_PDU_T *tags = allocate_tags(min_rnti, max_rnti, num_elements, pool);
    if (tags) {
        log_tag_details(tags, num_elements, "log.txt");
        free(tags);
    } else {
        fprintf(stderr, "Failed to allocate tags\n");
    }

    destroy_memory_pool(pool);
    return EXIT_SUCCESS;
}
```

### Key Points:
- **Memory Pool**: A custom memory pool is used to manage allocations efficiently and ensure thread safety.
- **Concurrency**: Mutexes are used to protect shared resources like the log file and memory pool.
- **Dynamic Allocation**: The function checks available system memory before allocation to prevent exceeding limits.
- **Logging**: Logging is implemented with a mutex lock to avoid race conditions, and logging level can be adjusted at runtime.
- **Resource Management**: Handles allocation failures gracefully and ensures that allocations do not exceed 50% of system RAM.

This code provides a foundation for handling concurrency, memory management, and logging efficiently. Further optimizations may include more sophisticated memory pooling strategies and integration with external services for performance metrics.']

