```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define the structure as per given requirements
typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_ARRAY_SIZE 1000

// Global variables and mutex for thread safety
NFAPI_CRC_INDICATION_PDU_T* pduArray = NULL;
size_t arraySize = 0;
pthread_mutex_t lock;

// Function to initialize the random number generator
void init_random() {
    srand((unsigned int)time(NULL));
}

// Function to create a valid structure
int create_valid_structure(NFAPI_CRC_INDICATION_PDU_T* structure) {
    if (!structure) return -1;

    // Assign values ensuring validity
    structure->RX_UE_INFORMATION_TAG = rand();
    structure->RNTI = (rand() % 0xFFFFF) + 1; // Avoid zero
    structure->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1;

    return 0;
}

// Function to dynamically manage array of structures
int manage_pdu_array(size_t newSize) {
    if (newSize > MAX_ARRAY_SIZE || newSize == 0) return -1;

    pthread_mutex_lock(&lock);

    NFAPI_CRC_INDICATION_PDU_T* newArray = realloc(pduArray, newSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newArray) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    pduArray = newArray;
    arraySize = newSize;

    for (size_t i = 0; i < newSize; ++i) {
        if (create_valid_structure(&pduArray[i]) != 0) {
            pthread_mutex_unlock(&lock);
            return -1;
        }
    }

    // Sort the array based on RNTI
    qsort(pduArray, newSize, sizeof(NFAPI_CRC_INDICATION_PDU_T), 
          [](const void* a, const void* b) -> int {
              const NFAPI_CRC_INDICATION_PDU_T* pduA = (NFAPI_CRC_INDICATION_PDU_T*)a;
              const NFAPI_CRC_INDICATION_PDU_T* pduB = (NFAPI_CRC_INDICATION_PDU_T*)b;
              return (int)(pduA->RNTI - pduB->RNTI);
          });

    pthread_mutex_unlock(&lock);
    return 0;
}

// Function to export the sorted array to a binary file
int export_to_file(const char* filename) {
    if (!filename || !pduArray) return -1;

    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return -1;
    }

    unsigned int metadata[2];
    metadata[0] = arraySize;
    metadata[1] = pduArray[arraySize-1].RNTI; // Assuming sorted

    fwrite(metadata, sizeof(unsigned int), 2, file);
    fwrite(pduArray, sizeof(NFAPI_CRC_INDICATION_PDU_T), arraySize, file);

    fclose(file);
    return 0;
}

// Thread-safe main function to manage array
void* thread_safe_manage_array(void* arg) {
    size_t newSize = *(size_t*)arg;

    if (manage_pdu_array(newSize) == 0) {
        export_to_file("output.bin");
    }

    return NULL;
}

int main() {
    init_random();

    pthread_mutex_init(&lock, NULL);

    size_t newSize = 500; // Example new size
    pthread_t thread;

    if (pthread_create(&thread, NULL, thread_safe_manage_array, &newSize) != 0) {
        perror("Thread creation failed");
        return -1;
    }

    pthread_join(thread, NULL);

    pthread_mutex_destroy(&lock);

    free(pduArray); // Clean up dynamically allocated memory
    pduArray = NULL;

    return 0;
}
```

