        LTE_DL_FRAMEINFO *new_array = (LTE_DL_FRAMEINFO *)realloc(frame_info_array->array, new_capacity * sizeof(LTE_DL_FRAMEINFO));
        if (!new_array) {
            pthread_mutex_unlock(&frame_info_array->lock);
            return -1; // Error: reallocation failed
        }
        frame_info_array->capacity = new_capacity;
        frame_info_array->array = new_array;
