    ALLOCATION_ERROR,
    MEMORY_LIMIT_REACHED,
    THREAD_SYNC_ERROR
} ErrorCode;

// Structure Definitions
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Shared Data and Synchronization Primitives
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t count;
    pthread_mutex_t mutex;
} DynamicArrayManager;

DynamicArrayManager manager = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

// Function to initialize a structure with random data
void init_structure(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pdu->RX_UE_INFORMATION_TAG = rand() % 65536; // Random uint16_t value
    pdu->RNTI = rand() % 65536;
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random boolean value
}

// Function to allocate and initialize the dynamic array
ErrorCode manage_dynamic_array(DynamicArrayManager* manager, size_t new_count) {
    pthread_mutex_lock(&manager->mutex);

    ErrorCode error_code = SUCCESS;
    if (new_count > MAX_ELEMENTS) {
        fprintf(stderr, "Error: Requested number of elements exceeds maximum limit.\n");
        error_code = MEMORY_LIMIT_REACHED;
        goto cleanup;
    }

    NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(manager->array, new_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_array == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        error_code = ALLOCATION_ERROR;
        goto cleanup;
    }

    // Initialize the new elements
    for (size_t i = manager->count; i < new_count; ++i) {
        init_structure(&new_array[i]);
    }

    manager->array = new_array;
    manager->count = new_count;

cleanup:
    pthread_mutex_unlock(&manager->mutex);
    return error_code;
}

// Logging function
void log_status(const char* message, ErrorCode code) {
    const char *error_message;
    switch (code) {
        case SUCCESS: error_message = "Success"; break;
        case ALLOCATION_ERROR: error_message = "Allocation Error"; break;
        case MEMORY_LIMIT_REACHED: error_message = "Memory Limit Reached"; break;
        case THREAD_SYNC_ERROR: error_message = "Thread Synchronization Error"; break;
        default: error_message = "Unknown Error";
    }
    printf("%s - %s\n", message, error_message);
}

// Main function for testing
int main() {
    srand(time(NULL)); // Seed the random number generator

    ErrorCode result = manage_dynamic_array(&manager, 5000); // Example usage
    log_status("Allocation Result", result);

    // Free allocated memory
    free(manager.array);
    manager.array = NULL;
    pthread_mutex_destroy(&manager.mutex);

    return (result == SUCCESS) ? EXIT_SUCCESS : EXIT_FAILURE;
}
