#include <pthread.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

#define MAX_SESSIONS 10000
#define MAX_MESSAGES 100
#define TABLE_SIZE 1048576 // Use a power of two for fast modulus

typedef enum { SESSION_ACTIVE, SESSION_INACTIVE } SessionState;

typedef struct {
    char messages[MAX_MESSAGES][256];
    int message_count;
} MessageQueue;

typedef struct {
    uint64_t session_id;
    MessageQueue queue;
    SessionState state;
} UserSession;

typedef struct HashNode {
    uint64_t session_id;
    UserSession session;
    struct HashNode* next;
} HashNode;

typedef struct {
    HashNode** table;
    pthread_mutex_t locks[TABLE_SIZE];
} DistributedHashTable;

DistributedHashTable* create_table() {
    DistributedHashTable* dht = malloc(sizeof(DistributedHashTable));
    dht->table = calloc(TABLE_SIZE, sizeof(HashNode*));
    for (int i = 0; i < TABLE_SIZE; ++i) {
        pthread_mutex_init(&dht->locks[i], NULL);
    }
    return dht;
}

uint64_t hash_function(uint64_t session_id) {
    return session_id % TABLE_SIZE;
}

void add_session(DistributedHashTable* dht, uint64_t session_id, UserSession session) {
    int index = hash_function(session_id);
    pthread_mutex_lock(&dht->locks[index]);

    HashNode* node = malloc(sizeof(HashNode));
    node->session_id = session_id;
    node->session = session;
    node->next = dht->table[index];
    dht->table[index] = node;

    pthread_mutex_unlock(&dht->locks[index]);
}

UserSession* get_session(DistributedHashTable* dht, uint64_t session_id) {
    int index = hash_function(session_id);
    pthread_mutex_lock(&dht->locks[index]);

    HashNode* node = dht->table[index];
    while (node) {
        if (node->session_id == session_id) {
            UserSession* result = &node->session;
            pthread_mutex_unlock(&dht->locks[index]);
            return result;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&dht->locks[index]);
    return NULL; // Session not found
}

void delete_session(DistributedHashTable* dht, uint64_t session_id) {
    int index = hash_function(session_id);
    pthread_mutex_lock(&dht->locks[index]);

    HashNode *prev = NULL, *node = dht->table[index];
    while (node) {
        if (node->session_id == session_id) {
            if (prev) {
                prev->next = node->next;
            } else {
                dht->table[index] = node->next;
            }
            free(node);
            break;
        }
        prev = node;
        node = node->next;
    }

    pthread_mutex_unlock(&dht->locks[index]);
}

void destroy_table(DistributedHashTable* dht) {
    for (int i = 0; i < TABLE_SIZE; ++i) {
        HashNode *node = dht->table[i], *tmp;
        while (node) {
            tmp = node;
            node = node->next;
            free(tmp);
        }
        pthread_mutex_destroy(&dht->locks[i]);
    }
    free(dht->table);
    free(dht);
}

// Example usage
int main() {
    DistributedHashTable* dht = create_table();

    UserSession session1 = { .session_id = 12345, .queue = {0}, .state = SESSION_ACTIVE };
    add_session(dht, session1.session_id, session1);

    UserSession* retrieved_session = get_session(dht, 12345);
    if (retrieved_session) {
        printf("Session ID: %llu\n", retrieved_session->session_id);
    }

    delete_session(dht, 12345);
    destroy_table(dht);

    return 0;
}
```

This C code implements a basic distributed user session store using a custom hash table structure with thread-safe operations. It supports adding, retrieving, and deleting sessions efficiently under concurrent access. The implementation uses mutex locks for simplicity but can be extended with lock-free techniques or finer-grained locking strategies for better performance in high-concurrency scenarios.']

