    if (!is_valid_rnti(dynamicArray, RNTI)) {
        return -1; // Invalid or duplicate RNTI
    }

    pthread_mutex_lock(&dynamicArray->lock);

    if (dynamicArray->count >= MAX_STRUCTS) {
        pthread_mutex_unlock(&dynamicArray->lock);
        return -2; // Capacity exceeded
    }

    NFAPI_CRC_INDICATION_PDU_T *structure = &dynamicArray->array[dynamicArray->count++];
    structure->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    structure->RNTI = RNTI;
    structure->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    structure->CRCFLAG = rand() % 2 == 0;

    pthread_mutex_unlock(&dynamicArray->lock);
    return 0; // Success
}

void free_dynamic_array(DynamicArray *dynamicArray) {
    if (dynamicArray) {
        free(dynamicArray->array);
        pthread_mutex_destroy(&dynamicArray->lock);
        free(dynamicArray);
    }
}
