    list->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_list(DynamicList* list) {
    if (list) {
        pthread_mutex_destroy(&list->lock);
        free(list->data);
        free(list);
    }
}

int resize_if_needed(DynamicList* list) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int add_element(DynamicList* list, int RX_UE_INFORMATION_TAG, int RNTI) {
    if (resize_if_needed(list) != 0) {
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T element;
    element.tag.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    element.tag.RNTI = RNTI;
    element.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    list->data[list->size++] = element;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_element(DynamicList* list, int index) {
    if (index < 0 || index >= list->size) {
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    for (size_t i = index; i < list->size - 1; ++i) {
        list->data[i] = list->data[i + 1];
    }

    --list->size;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* find_element(DynamicList* list, int RNTI) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].tag.RNTI == RNTI) {
            pthread_mutex_unlock(&list->lock);
            return &list->data[i];
        }
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}
