        bool CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t size;
    pthread_mutex_t lock;
} CRCList;

CRCList* create_crc_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;

    list->head = list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_crc_list(CRCList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

bool add_element(CRCList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    if (!list || list->size >= MAX_ELEMENTS) return false;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return false;

    new_node->data = element;
    new_node->next = NULL;
    new_node->prev = list->tail;

    pthread_mutex_lock(&list->lock);

    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }

    list->tail = new_node;
    list->size++;
    pthread_mutex_unlock(&list->lock);
    return true;
}

bool remove_element(CRCList* list, uint16_t RNTI) {
    if (!list || list->size == 0) return false;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current && current->data.RNTI != RNTI) {
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    if (current->prev) {
        current->prev->next = current->next;
    } else {
        list->head = current->next;
    }

    if (current->next) {
        current->next->prev = current->prev;
    } else {
        list->tail = current->prev;
    }

    free(current);
    list->size--;
    pthread_mutex_unlock(&list->lock);

    return true;
}

void set_random_crcflag(NFAPI_CRC_INDICATION_PDU_T* element) {
    if (element) {
        srand(time(NULL) ^ (intptr_t)element); // Seed with time and address
        element->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2 == 0;
    }
}

void update_crcflag(CRCList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        set_random_crcflag(&(current->data));
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void iterate_list(CRCList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    if (!list || !callback) return;

    Node* current = list->head;
    while (current) {
        callback(&(current->data));
        current = current->next;
    }
}

void print_element(NFAPI_CRC_INDICATION_PDU_T* element) {
    if (element) {
        printf("RX_UE_INFORMATION_TAG: %u, RNTI: %u, CRCFLAG: %d\n", 
               element->RX_UE_INFORMATION_TAG, element->RNTI,
               element->CRC_INDICATION_REL8_TAG.CRCFLAG);
    }
}

int main() {
    CRCList* list = create_crc_list();

    if (!list) {
        fprintf(stderr, "Failed to initialize CRC List\n");
        return EXIT_FAILURE;
    }

    NFAPI_CRC_INDICATION_PDU_T element = {1, 1234};
    set_random_crcflag(&element);
    add_element(list, element);

    iterate_list(list, print_element);

    remove_element(list, 1234);

    destroy_crc_list(list);
    return EXIT_SUCCESS;
}
```

