#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define NUM_STRUCTURES 1000
#define MAX_MEMORY_USAGE (5 * 1024 * 1024) // 5 MB
#define LOG_FILE "nfa_pi_log.csv"
#define RETRY_LIMIT 3
#define BACKOFF_INTERVAL_MS 100

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void log_structure(const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    static FILE *file = NULL;
    int retries = 0;
    while (retries < RETRY_LIMIT) {
        if (!file) {
            file = fopen(LOG_FILE, "a");
            if (!file) {
                usleep(BACKOFF_INTERVAL_MS * 1000);
                retries++;
                continue;
            }
        }

        pthread_mutex_lock(&lock);
        fprintf(file, "%ld,%d\n", time(NULL), pdu->CRCFLAG);
        fflush(file);
        pthread_mutex_unlock(&lock);

        break;
    }

    if (retries == RETRY_LIMIT && file) {
        fclose(file);
        file = NULL;
    }
}

void generate_and_populate_structures(NFAPI_CRC_INDICATION_PDU_T *array, size_t size) {
    struct timespec start_time, end_time;

    clock_gettime(CLOCK_MONOTONIC, &start_time);

    for (size_t i = 0; i < size; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 10000;
        array[i].RNTI = rand() % 100000;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 1000;
        array[i].CRCFLAG = rand() % 2;

        log_structure(&array[i]);
    }

    clock_gettime(CLOCK_MONOTONIC, &end_time);
    double elapsed_time_ms = (end_time.tv_sec - start_time.tv_sec) * 1000.0 +
                             (end_time.tv_nsec - start_time.tv_nsec) / 1e6;

    if (elapsed_time_ms > 200.0) {
        fprintf(stderr, "Operation exceeded time limit: %f ms\n", elapsed_time_ms);
    }
}

int main() {
    srand(time(NULL));

    NFAPI_CRC_INDICATION_PDU_T *structures = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * NUM_STRUCTURES);
    if (!structures) {
        fprintf(stderr, "Memory allocation failed.\n");
        return EXIT_FAILURE;
    }

    generate_and_populate_structures(structures, NUM_STRUCTURES);

    free(structures);
    pthread_mutex_destroy(&lock);

    return EXIT_SUCCESS;
}
