void* serialize_list(NFACRCList_T* list, const char *filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return NULL;

    fwrite(&list->size, sizeof(size_t), 1, file);
    fwrite(list->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->size, file);

    fclose(file);
    log_message(LOG_INFO, "List serialized successfully.");
    return file;
}

NFACRCList_T* deserialize_list(const char *filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return NULL;

    NFACRCList_T* list = malloc(sizeof(NFACRCList_T));
    fread(&list->size, sizeof(size_t), 1, file);
    list->capacity = list->size;
    list->elements = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->capacity);

    fread(list->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->size, file);

    fclose(file);
    pthread_mutex_init(&list->lock, NULL);
    log_message(LOG_INFO, "List deserialized successfully.");
    return list;
}

NFACRCList_T* create_list(size_t initial_capacity) {
    NFACRCList_T* list = malloc(sizeof(NFACRCList_T));
    if (!list) return NULL;

    list->capacity = initial_capacity > MAX_ELEMENTS ? MAX_ELEMENTS : initial_capacity;
    list->elements = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->capacity);
    list->size = 0;

    pthread_mutex_init(&list->lock, NULL);

    if (!list->elements) {
        free(list);
        return NULL;
    }

    log_message(LOG_INFO, "List created successfully.");
    return list;
}

int add_element(NFACRCList_T* list, unsigned int rnti) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= list->capacity || !is_rnti_unique(list, rnti)) {
        pthread_mutex_unlock(&list->lock);
        log_message(LOG_INFO, "Failed to add element: List full or RNTI not unique.");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T* new_elements = realloc(list->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->size + 1));
    if (!new_elements) {
        pthread_mutex_unlock(&list->lock);
        log_message(LOG_INFO, "Failed to allocate memory for new element.");
        return -1;
    }

    list->elements = new_elements;
    list->elements[list->size].crc_tag.CRCFLAG = rand() % 2; // Random CRCFLAG
    // Populate RX_UE_INFORMATION_TAG and RNTI here

    ++list->size;

    pthread_mutex_unlock(&list->lock);
    log_message(LOG_INFO, "Element added successfully.");
    return 0;
}

void free_list(NFACRCList_T* list) {
    if (list) {
        free(list->elements);
        pthread_mutex_destroy(&list->lock);
        free(list);
        log_message(LOG_INFO, "List freed successfully.");
    }
}
