#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int CELL_ID;
    int PCI;
    time_t MEASUREMENT_TIMESTAMP;
} NR_CELL_STATS_T;

typedef struct {
    NR_CELL_STATS_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

// Initialize the dynamic array
void initDynamicArray(DynamicArray *arr) {
    arr->size = 0;
    arr->capacity = 10; // Initial capacity
    arr->array = malloc(arr->capacity * sizeof(NR_CELL_STATS_T));
    pthread_mutex_init(&arr->lock, NULL);
}

// Resize the array when needed
void resizeArray(DynamicArray *arr) {
    pthread_mutex_lock(&arr->lock);
    if (arr->size >= arr->capacity) {
        arr->capacity *= 2;
        NR_CELL_STATS_T *new_array = realloc(arr->array, arr->capacity * sizeof(NR_CELL_STATS_T));
        if (new_array) {
            arr->array = new_array;
        }
    }
    pthread_mutex_unlock(&arr->lock);
}

// Add a new element to the array
void addElement(DynamicArray *arr, NR_CELL_STATS_T elem) {
    resizeArray(arr);
    pthread_mutex_lock(&arr->lock);
    arr->array[arr->size++] = elem;
    pthread_mutex_unlock(&arr->lock);
}

// Retrieve an element by index
NR_CELL_STATS_T getElement(DynamicArray *arr, size_t index) {
    pthread_mutex_lock(&arr->lock);
    NR_CELL_STATS_T elem = {0};
    if (index < arr->size) {
        elem = arr->array[index];
    }
    pthread_mutex_unlock(&arr->lock);
    return elem;
}

// Update an existing element
void updateElement(DynamicArray *arr, size_t index, NR_CELL_STATS_T newElem) {
    pthread_mutex_lock(&arr->lock);
    if (index < arr->size) {
        arr->array[index] = newElem;
    }
    pthread_mutex_unlock(&arr->lock);
}

// Filter elements based on PCI or timestamp
void filterElements(DynamicArray *arr, int pciFilter, time_t timestampFilter, NR_CELL_STATS_T **result, size_t *count) {
    pthread_mutex_lock(&arr->lock);
    *count = 0;
    for (size_t i = 0; i < arr->size; ++i) {
        if ((pciFilter == -1 || arr->array[i].PCI == pciFilter) &&
            (timestampFilter == -1 || arr->array[i].MEASUREMENT_TIMESTAMP == timestampFilter)) {
            (*count)++;
        }
    }

    *result = malloc(*count * sizeof(NR_CELL_STATS_T));
    size_t j = 0;
    for (size_t i = 0; i < arr->size; ++i) {
        if ((pciFilter == -1 || arr->array[i].PCI == pciFilter) &&
            (timestampFilter == -1 || arr->array[i].MEASUREMENT_TIMESTAMP == timestampFilter)) {
            (*result)[j++] = arr->array[i];
        }
    }
    pthread_mutex_unlock(&arr->lock);
}

// Save the data to disk
void saveToDisk(DynamicArray *arr, const char *filename) {
    pthread_mutex_lock(&arr->lock);
    FILE *file = fopen(filename, "wb");
    if (file) {
        fwrite(arr->array, sizeof(NR_CELL_STATS_T), arr->size, file);
        fclose(file);
    }
    pthread_mutex_unlock(&arr->lock);
}

// Load the data from disk
void loadFromDisk(DynamicArray *arr, const char *filename) {
    pthread_mutex_lock(&arr->lock);
    FILE *file = fopen(filename, "rb");
    if (file) {
        fseek(file, 0, SEEK_END);
        size_t file_size = ftell(file);
        fseek(file, 0, SEEK_SET);

        arr->capacity = file_size / sizeof(NR_CELL_STATS_T);
        NR_CELL_STATS_T *new_array = malloc(arr->capacity * sizeof(NR_CELL_STATS_T));
        if (new_array) {
            fread(new_array, sizeof(NR_CELL_STATS_T), arr->capacity, file);
            free(arr->array);
            arr->array = new_array;
            arr->size = arr->capacity;
        }
        fclose(file);
    }
    pthread_mutex_unlock(&arr->lock);
}

// Clean up the dynamic array
void freeDynamicArray(DynamicArray *arr) {
    pthread_mutex_lock(&arr->lock);
    free(arr->array);
    pthread_mutex_unlock(&arr->lock);
    pthread_mutex_destroy(&arr->lock);
}
