#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <arpa/inet.h>
#include <time.h>

// Network Interface Configuration structure
typedef struct NICConfig {
    char mac_address[18];
    char ip_address[16];
    char subnet_mask[16];
    int ref_count;
    struct NICConfig *prev, *next;
} NICConfig;

// Doubly linked list node for scalability and thread safety
typedef struct NICList {
    NICConfig *head;
    pthread_mutex_t lock;
    size_t count;
} NICList;

// Function prototypes
NICList* init_nic_list();
int add_nic_config(NICList* nic_list, const char* mac, const char* ip, const char* subnet);
void remove_nic_config(NICList* nic_list, const char* mac);
int validate_ip_subnet(const char* ip, const char* subnet);
void log_event(const char *event);
void free_nic_list(NICList* nic_list);

// Initialize the doubly linked list
NICList* init_nic_list() {
    NICList* nic_list = (NICList*)malloc(sizeof(NICList));
    if (!nic_list) return NULL;

    nic_list->head = NULL;
    pthread_mutex_init(&nic_list->lock, NULL);
    nic_list->count = 0;

    log_event("Initialized NIC List");
    return nic_list;
}

// Add a new NIC configuration
int add_nic_config(NICList* nic_list, const char* mac, const char* ip, const char* subnet) {
    if (!validate_ip_subnet(ip, subnet)) return -1; // Invalid IP/Subnet

    pthread_mutex_lock(&nic_list->lock);

    NICConfig *new_node = (NICConfig*)malloc(sizeof(NICConfig));
    if (!new_node) {
        pthread_mutex_unlock(&nic_list->lock);
        return -1;
    }

    strncpy(new_node->mac_address, mac, 18);
    new_node->mac_address[17] = '\0';
    strncpy(new_node->ip_address, ip, 16);
    new_node->ip_address[15] = '\0';
    strncpy(new_node->subnet_mask, subnet, 16);
    new_node->subnet_mask[15] = '\0';
    new_node->ref_count = 1;
    new_node->prev = NULL;
    new_node->next = nic_list->head;

    if (nic_list->head) {
        nic_list->head->prev = new_node;
    }
    nic_list->head = new_node;

    nic_list->count++;

    pthread_mutex_unlock(&nic_list->lock);

    log_event("Added NIC Config");
    return 0;
}

// Remove a NIC configuration
void remove_nic_config(NICList* nic_list, const char* mac) {
    pthread_mutex_lock(&nic_list->lock);

    NICConfig *current = nic_list->head;
    while (current && strcmp(current->mac_address, mac) != 0) {
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&nic_list->lock);
        return;
    }

    if (current->ref_count > 1) {
        current->ref_count--;
    } else {
        if (current->prev) current->prev->next = current->next;
        if (current->next) current->next->prev = current->prev;
        if (nic_list->head == current) nic_list->head = current->next;

        free(current);
        nic_list->count--;
    }

    pthread_mutex_unlock(&nic_list->lock);

    log_event("Removed NIC Config");
}

// Validate IP and Subnet
int validate_ip_subnet(const char* ip, const char* subnet) {
    struct in_addr addr, netmask;
    if (inet_aton(ip, &addr) == 0 || inet_aton(subnet, &netmask) == 0) return 0;

    unsigned long ip_long = ntohl(addr.s_addr);
    unsigned long mask_long = ntohl(netmask.s_addr);

    // Ensure IP is within the range defined by Subnet
    if ((ip_long & mask_long) != (addr.s_addr & netmask.s_addr)) {
        return 0;
    }
    return 1;
}

// Log events with timestamps
void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);

    printf("[%04d-%02d-%02d %02d:%02d:%02d] %s\n", 
           tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
           tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, event);
}

// Free the NIC list
void free_nic_list(NICList* nic_list) {
    pthread_mutex_lock(&nic_list->lock);

    NICConfig *current = nic_list->head;
    while (current) {
        NICConfig *next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&nic_list->lock);
    pthread_mutex_destroy(&nic_list->lock);
    free(nic_list);

    log_event("Freed NIC List");
}
```']

