    pthread_mutex_init(&list->lock, NULL);
}

void free_node(Node* node) {
    if (node) {
        free(node);
    }
}

Node* create_node(NICPEvent event) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for a new node");
        exit(EXIT_FAILURE);
    }
    new_node->data = event;
    new_node->next = NULL;
    return new_node;
}

void insert_event(EventList* list, NICPEvent event) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = create_node(event);
    if (!list->head || list->head->data.unique_id > event.unique_id) {
        new_node->next = list->head;
        list->head = new_node;
    } else {
        Node* current = list->head;
        while (current->next && current->next->data.unique_id < event.unique_id) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }

    pthread_mutex_unlock(&list->lock);
}

void delete_event(EventList* list, int unique_id) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;

    while (current && current->data.unique_id != unique_id) {
        prev = current;
        current = current->next;
    }

    if (!current) { // Event not found
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (prev) {
        prev->next = current->next;
    } else {
        list->head = current->next;
    }

    free_node(current);

    pthread_mutex_unlock(&list->lock);
}

NICPEvent* retrieve_event(EventList* list, int unique_id) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;

    while (current && current->data.unique_id != unique_id) {
        current = current->next;
    }

    NICPEvent* event = NULL;
    if (current) {
        *event = current->data;
    }

    pthread_mutex_unlock(&list->lock);

    return event;
}

void update_event_status(EventList* list, int unique_id, const char* new_status) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;

    while (current && current->data.unique_id != unique_id) {
        current = current->next;
    }

    if (current) {
        strncpy(current->data.status, new_status, MAX_STATUS_LENGTH - 1);
        current->data.status[MAX_STATUS_LENGTH - 1] = '\0';
    }

    pthread_mutex_unlock(&list->lock);
}

void filter_and_sort_events(EventList* list, EventType type_filter, long timestamp_min, long timestamp_max) {
    pthread_mutex_lock(&list->lock);

    Node** sorted_array = malloc(sizeof(Node*) * 100); // Assume max of 100 for simplicity
    int count = 0;

    Node* current = list->head;
    while (current) {
        if ((type_filter == EVENT_TYPE_A || type_filter == EVENT_TYPE_B || type_filter == -1) &&
            current->data.timestamp >= timestamp_min && 
            current->data.timestamp <= timestamp_max) {

            sorted_array[count++] = current;
        }
        current = current->next;
    }

    // Simple bubble sort for demonstration purposes
    for (int i = 0; i < count - 1; ++i) {
        for (int j = 0; j < count - i - 1; ++j) {
            if (sorted_array[j]->data.timestamp > sorted_array[j + 1]->data.timestamp) {
                Node* temp = sorted_array[j];
                sorted_array[j] = sorted_array[j + 1];
                sorted_array[j + 1] = temp;
            }
        }
    }

    // Log filtered and sorted events
    for (int i = 0; i < count; ++i) {
        printf("Event ID: %d, Type: %d, Timestamp: %ld, Status: %s\n",
               sorted_array[i]->data.unique_id,
               sorted_array[i]->data.type,
               sorted_array[i]->data.timestamp,
               sorted_array[i]->data.status);
    }

    free(sorted_array);

    pthread_mutex_unlock(&list->lock);
}

// Dummy function for logging integration
void log_event_to_service(NICPEvent event) {
    printf("Logging to service: ID=%d, Timestamp=%ld, Type=%d, Status=%s\n",
           event.unique_id, event.timestamp, event.type, event.status);
}

void process_events(EventList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;

    while (current) {
        log_event_to_service(current->data);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Example usage
int main() {
    EventList events;
    init_event_list(&events);

    NICPEvent event1 = { .timestamp=162523, .type=EVENT_TYPE_A, .status="Event A", .unique_id=101 };
    insert_event(&events, event1);

    NICPEvent event2 = { .timestamp=162526, .type=EVENT_TYPE_B, .status="Event B", .unique_id=102 };
    insert_event(&events, event2);

    update_event_status(&events, 101, "Updated Event A");

    NICPEvent* retrieved = retrieve_event(&events, 101);
    if (retrieved) {
        printf("Retrieved: ID=%d, Status=%s\n", retrieved->unique_id, retrieved->status);
    }

    filter_and_sort_events(&events, -1, 162500, 162530); // No type filtering

    delete_event(&events, 101);

    process_events(&events);

    pthread_mutex_destroy(&events.lock);
    return 0;
}
```

### Key Considerations:
- **Concurrency**: A mutex is used to ensure thread-safe access and modifications.
- **Memory Management**: Nodes are dynamically allocated for each event. Careful cleanup in `free_node` ensures no memory leaks.
- **Sorting/Filtering**: Implemented a basic bubble sort for simplicity; consider more efficient algorithms like quicksort or mergesort for production use.
- **Logging Integration**: A simple logging function is included, which can be extended to interface with external services.
- **Performance**: The implementation uses linked list structures to facilitate efficient insertion and deletion operations by unique identifier.']

