// Define event types and structures
typedef enum {
    EVENT_TYPE_A,
    EVENT_TYPE_B,
    // Add more event types as needed
} EventType;

typedef struct NICPEvent {
    time_t timestamp;
    EventType eventType;
    char *statusMessage;
    struct NICPEvent *next;
} NICPEvent;

// Global lock for thread safety
pthread_mutex_t nicp_lock = PTHREAD_MUTEX_INITIALIZER;

// Dynamic array of NICP events
typedef struct {
    NICPEvent **events;
    size_t count;
    size_t capacity;
} NICPEventManager;

// Function declarations
void initNICPEventManager(NICPEventManager *manager, size_t initial_capacity);
void freeNICPEventManager(NICPEventManager *manager);
void addNICPEvent(NICPEventManager *manager, time_t timestamp, EventType eventType, const char *statusMessage);
void updateStatusMessage(NICPEventManager *manager, time_t timestamp, EventType eventType, const char *newStatus);
NICPEvent* findNICPEvent(NICPEventManager *manager, time_t timestamp, EventType eventType);
void sortEventsByTimestamp(NICPEventManager *manager);
void filterAndSortEvents(NICPEventManager *manager, EventType filterType);
void logPerformanceMetrics(const NICPEvent *event);
void exportNICPEvents(NICPEventManager *manager);

// Initialize the dynamic array of events
void initNICPEventManager(NICPEventManager *manager, size_t initial_capacity) {
    pthread_mutex_lock(&nicp_lock);
    manager->events = malloc(initial_capacity * sizeof(NICPEvent*));
    manager->count = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_unlock(&nicp_lock);
}

// Free allocated resources
void freeNICPEventManager(NICPEventManager *manager) {
    pthread_mutex_lock(&nicp_lock);
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->events[i]->statusMessage);
        free(manager->events[i]);
    }
    free(manager->events);
    pthread_mutex_unlock(&nicp_lock);
}

// Add a new NICP event
void addNICPEvent(NICPEventManager *manager, time_t timestamp, EventType eventType, const char *statusMessage) {
    pthread_mutex_lock(&nicp_lock);

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        NICPEvent **new_events = realloc(manager->events, new_capacity * sizeof(NICPEvent*));
        if (!new_events) return; // Handle reallocation failure
        manager->events = new_events;
        manager->capacity = new_capacity;
    }

    NICPEvent *event = malloc(sizeof(NICPEvent));
    event->timestamp = timestamp;
    event->eventType = eventType;
    event->statusMessage = strdup(statusMessage);
    event->next = NULL;

    manager->events[manager->count++] = event;

    pthread_mutex_unlock(&nicp_lock);
}

// Update status message without reallocating memory
void updateStatusMessage(NICPEventManager *manager, time_t timestamp, EventType eventType, const char *newStatus) {
    NICPEvent *event = findNICPEvent(manager, timestamp, eventType);
    if (event) {
        free(event->statusMessage);
        event->statusMessage = strdup(newStatus);
    }
}

// Find a specific NICP event
NICPEvent* findNICPEvent(NICPEventManager *manager, time_t timestamp, EventType eventType) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->events[i]->timestamp == timestamp && manager->events[i]->eventType == eventType)
            return manager->events[i];
    }
    return NULL;
}

// Sort events by timestamp
void sortEventsByTimestamp(NICPEventManager *manager) {
    for (size_t i = 0; i < manager->count - 1; ++i) {
        for (size_t j = 0; j < manager->count - i - 1; ++j) {
            if (manager->events[j]->timestamp > manager->events[j + 1]->timestamp) {
                NICPEvent *temp = manager->events[j];
                manager->events[j] = manager->events[j + 1];
                manager->events[j + 1] = temp;
            }
        }
    }
}

// Filter and sort events by type
void filterAndSortEvents(NICPEventManager *manager, EventType filterType) {
    // Filtering step: Remove non-matching types
    size_t write_index = 0;
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->events[i]->eventType == filterType || filterType == -1) { // -1 implies no filtering
            if (write_index != i)
                manager->events[write_index] = manager->events[i];
            write_index++;
        }
    }
    manager->count = write_index;

    sortEventsByTimestamp(manager);  // Sorting step
}

// Log performance metrics for each event
void logPerformanceMetrics(const NICPEvent *event) {
    // Placeholder: Implement logging of latency, throughput, etc.
    printf("Logging metrics for Event at %ld with type %d\n", event->timestamp, event->eventType);
}

// Export NICP events to a standardized format
void exportNICPEvents(NICPEventManager *manager) {
    pthread_mutex_lock(&nicp_lock);
    // Placeholder: Implement exporting logic (synchronous/asynchronous)
    printf("Exporting NICP Events...\n");
    for (size_t i = 0; i < manager->count; ++i) {
        printf("Event %zu: Time=%ld, Type=%d, Status=%s\n", i, manager->events[i]->timestamp,
               manager->events[i]->eventType, manager->events[i]->statusMessage);
    }
    pthread_mutex_unlock(&nicp_lock);
}

// Main function for testing
int main() {
    NICPEventManager manager;
    initNICPEventManager(&manager, 10);

    addNICPEvent(&manager, time(NULL), EVENT_TYPE_A, "Initial status");
    addNICPEvent(&manager, time(NULL) - 100, EVENT_TYPE_B, "Another event");

    updateStatusMessage(&manager, time(NULL), EVENT_TYPE_A, "Updated status message");

    filterAndSortEvents(&manager, -1); // No filtering, just sorting by timestamp

    exportNICPEvents(&manager);

    freeNICPEventManager(&manager);

    return 0;
}
