#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <jansson.h>
#include <libxml/parser.h>
#include <libxml/tree.h>

typedef struct {
    // Placeholder for actual fields
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function prototypes
int load_config_and_create_array(const char *file_path, NFAPI_CRC_INDICATION_PDU_T **array);
static int parse_json_file(const char *file_path, NFAPI_CRC_INDICATION_PDU_T **array);
static int parse_xml_file(const char *file_path, NFAPI_CRC_INDICATION_PDU_T **array);

int load_config_and_create_array(const char *file_path, NFAPI_CRC_INDICATION_PDU_T **array) {
    if (!file_path || !array) return -1;

    FILE *file = fopen(file_path, "rb");
    if (!file) {
        fprintf(stderr, "Error opening file: %s\n", strerror(errno));
        return -2;
    }

    fseek(file, 0, SEEK_END);
    long filesize = ftell(file);
    rewind(file);

    char *buffer = (char *)malloc(filesize + 1);
    if (!buffer) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(file);
        return -3;
    }

    fread(buffer, 1, filesize, file);
    buffer[filesize] = '\0';
    fclose(file);

    // Determine format and parse accordingly
    int result = 0;
    if (strstr(file_path, ".json")) {
        result = parse_json_file(buffer, array);
    } else if (strstr(file_path, ".xml")) {
        result = parse_xml_file(buffer, array);
    } else {
        fprintf(stderr, "Unsupported file format\n");
        free(buffer);
        return -4;
    }

    free(buffer);

    return result;
}

static int parse_json_file(const char *buffer, NFAPI_CRC_INDICATION_PDU_T **array) {
    json_error_t error;
    json_t *root = json_loads(buffer, 0, &error);
    if (!root) {
        fprintf(stderr, "JSON parsing error: %s\n", error.text);
        return -5;
    }

    size_t array_size = json_array_size(root);
    *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(array_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*array) {
        fprintf(stderr, "Memory allocation failed\n");
        json_decref(root);
        return -6;
    }

    for (size_t i = 0; i < array_size; ++i) {
        json_t *item = json_array_get(root, i);

        // Extract and assign values
        (*array)[i].RX_UE_INFORMATION_TAG = json_integer_value(json_object_get(item, "RX_UE_INFORMATION_TAG"));
        (*array)[i].RNTI = json_integer_value(json_object_get(item, "RNTI"));

        // Set CRCFLAG randomly for demonstration purposes
        int crcflag = rand() % 2;
        (*array)[i].CRC_INDICATION_REL8_TAG.CRCFLAG = crcflag;
    }

    json_decref(root);
    return (int)array_size;
}

static int parse_xml_file(const char *buffer, NFAPI_CRC_INDICATION_PDU_T **array) {
    xmlDocPtr doc = xmlReadMemory(buffer, strlen(buffer), "noname.xml", NULL, 0);
    if (!doc) {
        fprintf(stderr, "Failed to parse XML\n");
        return -7;
    }

    xmlNode *root_element = xmlDocGetRootElement(doc);

    int count = 0;
    for (xmlNode *node = root_element->children; node; node = node->next) {
        if (node->type == XML_ELEMENT_NODE && strcmp((const char *)node->name, "Item") == 0) {
            count++;
        }
    }

    *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*array) {
        fprintf(stderr, "Memory allocation failed\n");
        xmlFreeDoc(doc);
        return -8;
    }

    int index = 0;
    for (xmlNode *node = root_element->children; node; node = node->next) {
        if (node->type == XML_ELEMENT_NODE && strcmp((const char *)node->name, "Item") == 0) {
            xmlChar *rx_ue_tag = xmlGetProp(node, BAD_CAST "RX_UE_INFORMATION_TAG");
            xmlChar *rnti_tag = xmlGetProp(node, BAD_CAST "RNTI");

            (*array)[index].RX_UE_INFORMATION_TAG = atoi((const char *)rx_ue_tag);
            (*array)[index].RNTI = atoi((const char *)rnti_tag);

            // Set CRCFLAG randomly for demonstration purposes
            int crcflag = rand() % 2;
            (*array)[index].CRC_INDICATION_REL8_TAG.CRCFLAG = crcflag;

            xmlFree(rx_ue_tag);
            xmlFree(rnti_tag);
            index++;
        }
    }

    xmlFreeDoc(doc);
    return count;
}
