    int num;
    char *token = strtok(input, " \t\n");
    while (token) {
        char *endptr;
        num = strtol(token, &endptr, 10);

        if (*endptr != '\0' || endptr == token || num < INT_MIN || num > MAX_INT) {
            log_error("Invalid integer input.");
            return -1;
        }

        count++;
        token = strtok(NULL, " \t\n");
    }

    *size = count;

    int *data = (int *)malloc(count * sizeof(int));
    if (!data) {
        log_error("Memory allocation failed for integers.");
        return -1;
    }

    token = strtok(input, " \t\n");
    for (size_t i = 0; i < count; ++i) {
        num = strtol(token, &endptr, 10);
        if (*endptr != '\0') {
            free(data);
            log_error("Invalid integer input during parsing.");
            return -1;
        }
        data[i] = num;
        token = strtok(NULL, " \t\n");
    }

    *array = data;
    return 0;
}

