        (*list)[i].ue_info_tag.RX_UE_INFORMATION_TAG = rand() % 256 - 128; // Example tag range

        (*list)[i].crc_rel8_tag.CRCFLAG = rand() % 2; // Random CRC flag

        time(&(*list)[i].timestamp); // Current system time
    }
}

