        free(integers);
        return; // Exit on failure
    }

    struct timespec start_time, end_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    find_and_print_largest(integers, count);

    NFAPI_CRC_INDICATION_PDU_T *nfaapi_list = NULL;
    create_and_populate_nfaapi_list(&nfaapi_list, count);

    clock_gettime(CLOCK_MONOTONIC, &end_time);

    double elapsed_seconds = end_time.tv_sec - start_time.tv_sec + 
                             (end_time.tv_nsec - start_time.tv_nsec) / 1e9;

    printf("Processing time: %.6f seconds\n", elapsed_seconds);

    free(integers);
    if (nfaapi_list != NULL) {
        free(nfaapi_list);
    }
}

