int isValidInteger(char *str) {
    if (*str == '-' || *str == '+') str++;
    if (!*str) return 0;
    while (*str) {
        if (*str < '0' || *str > '9') return 0;
        str++;
    }
    return 1;
}

void readIntegers(int **array, size_t *size) {
    char buffer[12];
    int capacity = INITIAL_SIZE;
    *array = malloc(capacity * sizeof(int));
    if (*array == NULL) handleError("Memory allocation failed for integer array.");

    int count = 0;
    while (scanf("%11s", buffer) == 1) {
        if (!isValidInteger(buffer)) break;

        if (count >= capacity) {
            capacity *= 2;
            *array = realloc(*array, capacity * sizeof(int));
            if (*array == NULL) handleError("Memory reallocation failed for integer array.");
        }

        (*array)[count++] = atoi(buffer);
    }
    *size = count;
}

