```c
#include <stdio.h>
#include <stdlib.h>
import <pthread.h>
#include <time.h>

#define MAX_ENTRIES 1000

typedef struct {
    // Example fields, replace with actual ones as needed
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG; 
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t count;
    pthread_rwlock_t rwlock;
} CRCList;

// Initialize the list
void init_list(CRCList* list) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    pthread_rwlock_init(&list->rwlock, NULL);
}

// Add an entry to the list
int add_entry(CRCList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_rwlock_wrlock(&list->rwlock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_rwlock_unlock(&list->rwlock);
        return -1; // Allocation failed
    }

    new_node->data = data;
    new_node->next = NULL;

    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }

    list->tail = new_node;
    list->count++;
    pthread_rwlock_unlock(&list->rwlock);

    return 0; // Success
}

// Remove an entry from the list by index
int remove_entry(CRCList* list, size_t index) {
    if (index >= list->count) return -1;

    pthread_rwlock_wrlock(&list->rwlock);

    Node *prev = NULL, *current = list->head;
    for (size_t i = 0; i < index; ++i) {
        prev = current;
        current = current->next;
    }

    if (prev) {
        prev->next = current->next;
    } else {
        list->head = current->next;
    }

    if (!current->next) {
        list->tail = prev;
    }

    free(current);
    --list->count;

    pthread_rwlock_unlock(&list->rwlock);
    return 0; // Success
}

// Get the count of entries in the list
size_t get_count(const CRCList* list) {
    pthread_rwlock_rdlock(&list->rwlock);
    size_t count = list->count;
    pthread_rwlock_unlock(&list->rwlock);
    return count;
}

// Iterate over and process each entry
void iterate_and_process(CRCList* list, void (*process)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_rwlock_rdlock(&list->rwlock);

    Node* current = list->head;
    while (current) {
        // Perform non-blocking operation on data
        process(&(current->data));
        current = current->next;
    }

    pthread_rwlock_unlock(&list->rwlock);
}

// Example processing function
void example_process(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    printf("Processing PDU with RNTI: %d\n", pdu->RNTI);
}

// Cleanup the list and free resources
void cleanup_list(CRCList* list) {
    pthread_rwlock_wrlock(&list->rwlock);

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    list->tail = NULL;
    list->count = 0;

    pthread_rwlock_unlock(&list->rwlock);
    pthread_rwlock_destroy(&list->rwlock);
}

// Example usage
int main() {
    CRCList list;
    init_list(&list);

    NFAPI_CRC_INDICATION_PDU_T pdu1 = {1, 12345, 6789, rand() % 2};
    add_entry(&list, pdu1);

    iterate_and_process(&list, example_process);

    size_t count = get_count(&list);
    printf("Current count: %zu\n", count);

    remove_entry(&list, 0);

    cleanup_list(&list);
    return 0;
}
```

### Key Aspects:

- **Thread Safety:** Uses `pthread_rwlock_t` for thread-safe read and write access to the list.

- **Error Handling:** Checks for memory allocation failures when adding entries.

- **Dynamic Memory Management:** Ensures no memory leaks by freeing nodes upon removal and during cleanup.

- **Iterating with Non-blocking Operations:** The iteration function accepts a processing callback, allowing non-blocking operations on each entry. 

- **Concurrency Considerations:** The use of read-write locks allows multiple readers or single writer access to the list, balancing performance with safety for concurrent operations.

- **Count Maintenance:** Maintains an accurate count of entries in constant time without needing to iterate over the list.

This example provides a foundation that can be extended and adapted to specific system architecture needs and network dependencies.']

