#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>

#define MAX_RNTI 65535

typedef struct {
    uint16_t rnti;
    uint8_t crcFlag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint32_t rxUeInformationTag;
    CRC_INDICATION_REL8_TAG tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Function prototypes
void* customAllocator(size_t size);
void freeCustomMemory(void* ptr);
NFAPI_CRC_INDICATION_PDU_T* generateNfapiPduList(int N, uint32_t seed, int logLevel);
int validateStructure(const NFAPI_CRC_INDICATION_PDU_T* pdu);
void adjustCrcFlagProbability(double* crcFlagProbability, double networkLoad);

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* generateNfapiPduList(int N, uint32_t seed, int logLevel) {
    if (N <= 0) return NULL;

    pthread_mutex_lock(&mutex);
    NFAPI_CRC_INDICATION_PDU_T* pduList = customAllocator(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pduList) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    srand(seed);
    double crcFlagProbability = 0.5; // Initial probability
    int validationSuccessCount = 0;

    for (int i = 0; i < N; ++i) {
        pduList[i].rxUeInformationTag = rand();

        uint16_t rnti;
        do {
            rnti = rand() % (MAX_RNTI + 1);
        } while ((rnti == MAX_RNTI) && logLevel > 0); // Log if max RNTI is selected

        pduList[i].tag.rnti = rnti;

        double networkLoad = rand() / (double)RAND_MAX; // Simulate network load
        adjustCrcFlagProbability(&crcFlagProbability, networkLoad);

        pduList[i].tag.crcFlag = (rand() / (double)RAND_MAX < crcFlagProbability) ? 1 : 0;

        if (validateStructure(&pduList[i])) {
            validationSuccessCount++;
        }
    }

    pthread_mutex_unlock(&mutex);

    if (logLevel > 0) {
        printf("Generated %d PDUs, %d validated successfully.\n", N, validationSuccessCount);
    }

    return pduList;
}

int validateStructure(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    return (pdu->rxUeInformationTag != 0 && pdu->tag.rnti <= MAX_RNTI);
}

void adjustCrcFlagProbability(double* crcFlagProbability, double networkLoad) {
    *crcFlagProbability = 0.5 + 0.5 * networkLoad; // Example adjustment
}

void* customAllocator(size_t size) {
    return malloc(size);
}

void freeCustomMemory(void* ptr) {
    free(ptr);
}
