            pdus[start_index + i].RX_UE_INFORMATION_TAG = generate_unique_RX_UE_INFORMATION_TAG(pthread_self());
            pdus[start_index + i].RNTI = generate_unique_RNTI(pthread_self());
            pdus[start_index + i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
        }
        return NULL;
    }

    for (int i = 0; i < num_threads; ++i) {
