typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;

// Utility function to generate a random CRCFLAG ensuring no two consecutive are the same
int getRandomCRCFlag(int previousFlag) {
    int flag;
    do {
        flag = rand() % 2; // Assuming CRCFLAG is binary for simplicity
    } while (flag == previousFlag);
    return flag;
}

// Function to insert a new element into the list, avoiding duplicates based on RNTI
int insertElement(uint16_t rxTag, uint16_t rnti, int* crcFlags) {
    Node* current = head;
    Node* prev = NULL;

    while (current != NULL && current->data.RNTI < rnti) {
        prev = current;
        current = current->next;
    }

    if (current != NULL && current->data.RNTI == rnti) {
        // RNTI already exists, no insertion
        return 0;
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        fprintf(stderr, "Memory allocation failed.\n");
        freeList();
        return -1;
    }

    int previousFlag = crcFlags[prev != NULL ? prev->data.RNTI : 0];
    newNode->data.CRC_INDICATION_REL8_TAG.CRCFLAG = getRandomCRCFlag(previousFlag);
    crcFlags[rnti] = newNode->data.CRC_INDICATION_REL8_TAG.CRCFLAG;

    newNode->data.RX_UE_INFORMATION_TAG = rxTag;
    newNode->data.RNTI = rnti;

    if (prev == NULL) {
        // Insert at head
        newNode->next = head;
        head = newNode;
    } else {
        // Insert in middle or end
        newNode->next = current;
        prev->next = newNode;
    }

    return 1;
}

// Function to free the linked list memory
void freeList() {
    Node* current = head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    head = NULL;
}

// Function to process updates and manage integrity of the list
int updateCRCIndications(uint16_t* rxTags, uint16_t* rntis, int count) {
    static int crcFlags[MAX_ELEMENTS] = {0};

    if (count > MAX_ELEMENTS) {
        fprintf(stderr, "Too many elements to process at once.\n");
        return -1;
    }

    for (int i = 0; i < count; ++i) {
        insertElement(rxTags[i], rntis[i], crcFlags);
    }

    // Assuming further logic is needed here if dealing with concurrency or spikes

    return 0;
}

// Example of periodic update handling
void periodicUpdate(uint16_t* rxTags, uint16_t* rntis, int count) {
