#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 1000
#define MAX_ELEMENTS 10000

typedef struct {
    int CRCFLAG;
    // Assume these are defined elsewhere in your environment.
    unsigned long RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    unsigned long CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock; // For thread safety
} DynamicArray;

// Function to allocate and initialize the dynamic array.
DynamicArray* create_dynamic_array(size_t initial_capacity) {
    if (initial_capacity == 0 || initial_capacity > MAX_ELEMENTS) {
        initial_capacity = INITIAL_CAPACITY;
    }

    DynamicArray* dyn_arr = malloc(sizeof(DynamicArray));
    if (!dyn_arr) return NULL;

    dyn_arr->array = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!dyn_arr->array) {
        free(dyn_arr);
        return NULL;
    }

    dyn_arr->capacity = initial_capacity;
    dyn_arr->size = 0;
    pthread_mutex_init(&dyn_arr->lock, NULL);

    return dyn_arr;
}

// Helper function to resize the array.
int resize_array(DynamicArray* dyn_arr) {
    size_t new_capacity = dyn_arr->capacity * 2;
    if (new_capacity > MAX_ELEMENTS) {
        return -1; // Cannot resize beyond MAX_ELEMENTS
    }

    NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(dyn_arr->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) return -1;

    dyn_arr->array = new_array;
    dyn_arr->capacity = new_capacity;

    return 0; // Success
}

// Function to add an element to the array.
int add_element(DynamicArray* dyn_arr, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&dyn_arr->lock);

    if (dyn_arr->size == dyn_arr->capacity) {
        int res = resize_array(dyn_arr);
        if (res != 0) {
            pthread_mutex_unlock(&dyn_arr->lock);
            return -1;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T* element_ptr = &dyn_arr->array[dyn_arr->size++];
    *element_ptr = *pdu;

    pthread_mutex_unlock(&dyn_arr->lock);
    return 0; // Success
}

// Function to initialize and populate an array with random data.
int populate_random_data(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    srand((unsigned int)time(NULL));

    pdu->CRCFLAG = rand() % 2;
    pdu->RX_UE_INFORMATION_TAG = rand();
    pdu->RNTI = rand();
    pdu->CRC_INDICATION_REL8_TAG = rand();

    return 0; // Success
}

// Function to print the contents of the dynamic array.
void print_dynamic_array(const DynamicArray* dyn_arr) {
    pthread_mutex_lock(&dyn_arr->lock);

    for (size_t i = 0; i < dyn_arr->size; ++i) {
        printf("CRCFLAG: %d, RX_UE_INFORMATION_TAG: %lu, RNTI: %lu, CRC_INDICATION_REL8_TAG: %lu\n",
               dyn_arr->array[i].CRCFLAG,
               dyn_arr->array[i].RX_UE_INFORMATION_TAG,
               dyn_arr->array[i].RNTI,
               dyn_arr->array[i].CRC_INDICATION_REL8_TAG);
    }

    pthread_mutex_unlock(&dyn_arr->lock);
}

// Function to free resources.
void destroy_dynamic_array(DynamicArray* dyn_arr) {
    if (!dyn_arr) return;

    pthread_mutex_lock(&dyn_arr->lock);

    free(dyn_arr->array);
    pthread_mutex_unlock(&dyn_arr->lock);
    pthread_mutex_destroy(&dyn_arr->lock);
    free(dyn_arr);
}

// Example usage
int main() {
    DynamicArray* dyn_arr = create_dynamic_array(INITIAL_CAPACITY);
    if (!dyn_arr) {
        fprintf(stderr, "Failed to allocate dynamic array\n");
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < 20; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        populate_random_data(&pdu);
        if (add_element(dyn_arr, &pdu) != 0) {
            fprintf(stderr, "Failed to add element %zu\n", i);
        }
    }

    print_dynamic_array(dyn_arr);
    destroy_dynamic_array(dyn_arr);

    return EXIT_SUCCESS;
}
