    LTE_RRC_CUCU_MESSAGE *new_messages = realloc(array->cucu_messages, new_capacity * sizeof(LTE_RRC_CUCU_MESSAGE));
    if (!new_messages) {
        pthread_mutex_unlock(&array->lock);
        return -1;  // Memory allocation failure
    }
    array->capacity = new_capacity;
    memset(new_messages + array->count, 0, (new_capacity - array->count) * sizeof(LTE_RRC_CUCU_MESSAGE));
    array->cucu_messages = new_messages;
    pthread_mutex_unlock(&array->lock);
    return 0; 
}

// Function to initialize and configure the dynamic array
int init_dynamic_array(DynamicArray *array, size_t initial_capacity) {
    pthread_mutex_init(&array->lock, NULL);
