}

// Function to add a new LTE_RRC_CUCU_MESSAGE
int add_cucu_message(DynamicArray *array, int message_tag, const char *message_content) {
    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        // Resize the array by doubling its capacity
        if (resize_array(array, array->capacity * 2)) {
