            return -1;  // Memory allocation failure during resize
        }
    }

    LTE_RRC_CUCU_MESSAGE *message = &array->cucu_messages[array->count++];
    message->CUCU_MESSAGE_TAG = message_tag;
    strncpy(message->MME_UPLINK_NAS_Transport, message_content, sizeof(message->MME_UPLINK_NAS_Transport) - 1);

    pthread_mutex_unlock(&array->lock);
    return 0; // Success
