    if (!da->array) {
        free(da);
        return NULL;
    }

    da->size = 0;
    da->capacity = initial_capacity;
    pthread_mutex_init(&da->lock, NULL);

    return da;
}

// Destroy dynamic array
void destroy_dynamic_array(DynamicArray *da) {
    if (da) {
        free(da->array);
        pthread_mutex_destroy(&da->lock);
        free(da);
    }
}

// Add element to dynamic array
int add_element(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&da->lock);

    if (da->size == da->capacity) {
        size_t new_capacity = da->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&da->lock);
            return -1; // Allocation failure
        }
        da->array = new_array;
        da->capacity = new_capacity;
    }

    da->array[da->size++] = element;

    pthread_mutex_unlock(&da->lock);
    return 0;
}

// Sort array based on RNTI
void sort_array(DynamicArray *da) {
    pthread_mutex_lock(&da->lock);

    for (size_t i = 0; i < da->size - 1; ++i) {
        for (size_t j = 0; j < da->size - i - 1; ++j) {
            if (da->array[j].RNTI > da->array[j + 1].RNTI) {
                NFAPI_CRC_INDICATION_PDU_T temp = da->array[j];
                da->array[j] = da->array[j + 1];
                da->array[j + 1] = temp;
            }
        }
    }

    pthread_mutex_unlock(&da->lock);
}

// Print array contents
void print_array(const DynamicArray *da) {
    pthread_mutex_lock((pthread_mutex_t*)&da->lock);

    for (size_t i = 0; i < da->size; ++i) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %u\n",
               da->array[i].RX_UE_INFORMATION_TAG,
               da->array[i].RNTI,
               da->array[i].CRC_INDICATION_REL8_TAG.CRCFLAG);
    }

    pthread_mutex_unlock((pthread_mutex_t*)&da->lock);
}

// Export array to binary file
void export_to_file(const DynamicArray *da, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    pthread_mutex_lock((pthread_mutex_t*)&da->lock);

    fwrite(da->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), da->size, file);

    pthread_mutex_unlock((pthread_mutex_t*)&da->lock);
    fclose(file);
}

