typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t size;
    AllocatorPool *allocator_pool;
    pthread_rwlock_t rwlock; // For thread safety
} DynamicArray;

// Initialize a custom allocator pool
int init_allocator_pool(AllocatorPool *pool, size_t block_size, size_t max_blocks) {
    if (pthread_mutex_init(&pool->lock, NULL) != 0)
        return -1;

    pool->block_size = block_size;
    pool->max_blocks = max_blocks;
    pool->used_blocks = 0;
    pool->pool = malloc(block_size * max_blocks);
    if (!pool->pool) {
        pthread_mutex_destroy(&pool->lock);
        return -1;
    }
    return 0;
}

// Free a custom allocator pool
void free_allocator_pool(AllocatorPool *pool) {
    free(pool->pool);
    pthread_mutex_destroy(&pool->lock);
}

// Allocate memory from the pool
void* allocate_from_pool(AllocatorPool *pool, size_t size) {
    if (size > pool->block_size || pool->used_blocks >= pool->max_blocks)
        return NULL;

    pthread_mutex_lock(&pool->lock);
    void *ptr = pool->pool + (pool->used_blocks++ * pool->block_size);
    pthread_mutex_unlock(&pool->lock);

    return ptr;
}

// Function to create the dynamic array
DynamicArray* create_dynamic_array(size_t initial_capacity, AllocatorPool *allocator_pool) {
    DynamicArray *array = malloc(sizeof(DynamicArray));
    if (!array)
        return NULL;

    array->data = (NFAPI_CRC_INDICATION_PDU_T*)allocate_from_pool(allocator_pool, sizeof(NFAPI_CRC_INDICATION_PDU_T) * initial_capacity);
    if (!array->data) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    array->allocator_pool = allocator_pool;

    pthread_rwlock_init(&array->rwlock, NULL);

    return array;
}

// Function to resize the dynamic array
int resize_dynamic_array(DynamicArray *array, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)allocate_from_pool(array->allocator_pool, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
    if (!new_data)
        return -1;

    memcpy(new_data, array->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * array->size);

    pthread_rwlock_wrlock(&array->rwlock);
    free(array->data); // Custom free logic should be in place
    array->data = new_data;
    array->capacity = new_capacity;
    pthread_rwlock_unlock(&array->rwlock);

    return 0;
}

// Add an element to the dynamic array
int add_element(DynamicArray *array) {
