        size_t new_capacity = array->capacity * 2;
        if (resize_dynamic_array(array, new_capacity) != 0)
            return -1; // Handle allocation failure gracefully
    }

    pthread_rwlock_wrlock(&array->rwlock);
    NFAPI_CRC_INDICATION_PDU_T *element = &array->data[array->size++];
    element->RX_UE_INFORMATION_TAG = rand() % 65536;
    element->RNTI = rand() % 65536;
    element->CRC_INDICATION_REL8_TAG = rand() % 256;
