    free(array->data); // Ensure proper deallocation if needed
    free(array);
}

int main() {
    AllocatorPool pool;
    if (init_allocator_pool(&pool, sizeof(NFAPI_CRC_INDICATION_PDU_T) * INITIAL_CAPACITY, 20) != 0) {
        fprintf(stderr, "Failed to initialize allocator pool\n");
