typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    pthread_mutex_t lock;
} CrcIndicationList;

CrcIndicationList* create_list() {
    CrcIndicationList *list = malloc(sizeof(CrcIndicationList));
    if (list) {
        list->data = calloc(MAX_LIST_SIZE, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list->size = 0;
        pthread_mutex_init(&list->lock, NULL);
    }
    return list;
}

int add_element(CrcIndicationList *list, NFAPI_CRC_INDICATION_PDU_T element) {
    if (list->size >= MAX_LIST_SIZE) return -1;

    pthread_mutex_lock(&list->lock);
    list->data[list->size++] = element;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

int remove_element(CrcIndicationList *list, uint16_t rnti) {
    int found = 0;

    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].RNTI == rnti) {
            for (size_t j = i; j < list->size - 1; ++j) {
                list->data[j] = list->data[j + 1];
            }
            --list->size;
            found = 1;
            break;
        }
    }
    pthread_mutex_unlock(&list->lock);

    return found ? 0 : -1;
}

void filter_list(CrcIndicationList *list, uint16_t rnti_min, uint16_t rnti_max) {
    pthread_mutex_lock(&list->lock);
    size_t filtered_size = 0;

    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].RNTI >= rnti_min && list->data[i].RNTI <= rnti_max) {
            list->data[filtered_size++] = list->data[i];
        }
    }

    list->size = filtered_size;
    pthread_mutex_unlock(&list->lock);
}

void serialize_list(const CrcIndicationList *list, uint8_t **buffer, size_t *length) {
    pthread_mutex_lock(&list->lock);

    *length = sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->size;
    *buffer = malloc(*length);

    if (*buffer) {
        memcpy(*buffer, list->data, *length);
    }

    pthread_mutex_unlock(&list->lock);
}

int deserialize_list(CrcIndicationList *list, const uint8_t *buffer, size_t length) {
    pthread_mutex_lock(&list->lock);

    size_t new_size = length / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (new_size > MAX_LIST_SIZE) return -1;

    free(list->data);
    list->data = malloc(length);

    if (!list->data) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    memcpy(list->data, buffer, length);
    list->size = new_size;

    pthread_mutex_unlock(&list->lock);

    return 0;
}

void destroy_list(CrcIndicationList *list) {
    if (list) {
        free(list->data);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}
