void init_dynamic_list(DynamicList *list, size_t initial_capacity) {
    list->capacity = initial_capacity;
    list->size = 0;
    list->data = (NFAPI_L1_RX_STATS_T *)malloc(initial_capacity * sizeof(NFAPI_L1_RX_STATS_T));
    if (!list->data) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&list->mutex, NULL);
}

void destroy_dynamic_list(DynamicList *list) {
    free(list->data);
    pthread_mutex_destroy(&list->mutex);
}

int append_to_list(DynamicList *list, NFAPI_L1_RX_STATS_T stats) {
    pthread_mutex_lock(&list->mutex);

    if (list->size == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_L1_RX_STATS_T *new_data = (NFAPI_L1_RX_STATS_T *)realloc(list->data, new_capacity * sizeof(NFAPI_L1_RX_STATS_T));
        if (!new_data) {
            pthread_mutex_unlock(&list->mutex);
            perror("Failed to reallocate memory");
            return -1;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }

    list->data[list->size++] = stats;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int update_list_entry(DynamicList *list, uint64_t timestamp, NFAPI_L1_RX_STATS_T updated_stats) {
    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].RX_TIME_STAMP == timestamp) {
            list->data[i] = updated_stats;
            pthread_mutex_unlock(&list->mutex);
            return 0;
        }
    }

    pthread_mutex_unlock(&list->mutex);
    return -1; // Entry not found
}

size_t serialize_list(const DynamicList *list, uint8_t **buffer) {
    size_t total_size = list->size * sizeof(NFAPI_L1_RX_STATS_T);
    *buffer = (uint8_t *)malloc(total_size);
    if (!*buffer) {
        perror("Failed to allocate memory for serialization");
        return 0;
    }

    memcpy(*buffer, list->data, total_size);

    return total_size;
}

size_t filter_list_by_time_range(const DynamicList *list, uint64_t start_time, uint64_t end_time, NFAPI_L1_RX_STATS_T **filtered_data) {
    size_t count = 0;
    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].RX_TIME_STAMP >= start_time && list->data[i].RX_TIME_STAMP <= end_time) {
            ++count;
        }
    }

    *filtered_data = (NFAPI_L1_RX_STATS_T *)malloc(count * sizeof(NFAPI_L1_RX_STATS_T));
    if (!*filtered_data) {
        perror("Failed to allocate memory for filtered data");
        return 0;
    }

    size_t index = 0;
    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].RX_TIME_STAMP >= start_time && list->data[i].RX_TIME_STAMP <= end_time) {
            (*filtered_data)[index++] = list->data[i];
        }
    }

    return count;
}
