                int *newArray = realloc(inputArray, newSize * sizeof(int));
                if (!newArray) {
                    fprintf(stderr, "Memory allocation failed for input array.\n");
                    free(indicationList);
                    free(inputArray);
                    return;
                }
                inputArray = newArray;
                memset(&inputArray[inputSize], 0, (newSize - inputSize) * sizeof(int));
                inputSize = newSize;
