            if (value != 0 || numElements == 0) { // Handle zero or first element
                inputArray[numElements++] = value;
            }
            token = strtok(NULL, " \t\n");
        }
    }

    if (inputSize > 0) {
        int largestValue = findLargestInteger(inputArray, inputSize);
        printf("The largest integer is: %d\n", largestValue);
    } else {
