    }

    // Free allocated memory
    free(indicationList);
    free(inputArray);
}

int findLargestInteger(int *arr, size_t n) {
    if (n == 0)
        return INT_MIN;

    int largest = arr[0];
    for (size_t i = 1; i < n; ++i) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }
    return largest;
}

