        if (i == capacity - 1 && getchar() != '\n') { // Handle overflow
            printf("Too many numbers, increasing size.\n");
            int new_capacity = capacity * 2;
            int *new_inputs = realloc(inputs, new_capacity * sizeof(int));
            if (!new_inputs) {
                free(inputs);
                return EXIT_FAILURE;
            }
            inputs = new_inputs;
            capacity = new_capacity;
        } else {
            ++i; // Ensure space for the next number
        }
    }

    count = (size_t)(inputs[capacity - 1] != 0 ? capacity : i);

