#define MAX_BUFFER_SIZE 1518 // Example buffer limit (e.g., Ethernet MTU)
#define MIN_PAYLOAD_LEN 46   // Minimum payload length (e.g., Min Ethernet frame size - headers)
#define MAX_PAYLOAD_LEN 1500 // Maximum payload length

typedef struct {
    uint8_t destination_mac[6];
    uint8_t source_mac[6];
    uint16_t vlan_tag;
    uint8_t payload[MAX_PAYLOAD_LEN];
} MAC_HEADER;

typedef struct {
    MAC_HEADER mac_header;
    size_t payload_length;
} TX_FRAME;

bool is_valid_mac(uint8_t *mac) {
    for (int i = 0; i < 6; ++i) {
        if (mac[i] == 0 || mac[i] == 0xFF)
            return false;
    }
    return true;
}

TX_FRAME* initialize_tx_frames(size_t num_frames, size_t buffer_size, uint8_t *external_mac_src, bool (*validate_mac)(uint8_t*)) {
    TX_FRAME *frames = (TX_FRAME *)malloc(num_frames * sizeof(TX_FRAME));
    if (!frames) {
        return NULL; // Memory allocation failure
    }

    for (size_t i = 0; i < num_frames; ++i) {
        size_t payload_len = MIN_PAYLOAD_LEN + rand() % (MAX_PAYLOAD_LEN - MIN_PAYLOAD_LEN + 1);

        // Check alignment
        if ((buffer_size - sizeof(MAC_HEADER)) < payload_len) {
            free(frames);
            return NULL; // Insufficient buffer space for this frame
        }

        // Generate unique MAC header and VLAN tag
        memcpy(frames[i].mac_header.destination_mac, external_mac_src, 6); // Using external source for destination
        if (!validate_mac(external_mac_src) || !validate_mac(frames[i].mac_header.source_mac)) {
            free(frames);
            return NULL; // Invalid MAC address detected
        }

        frames[i].mac_header.vlan_tag = htons(rand() % 0xFFFF); // Random VLAN tag

        memset(&frames[i].mac_header.payload, 0, MAX_PAYLOAD_LEN); // Initialize payload to zeros
        frames[i].payload_length = payload_len;
    }

    return frames;
}
