// NFS structure definition
typedef struct {
    uint64_t packet_count;
    uint64_t byte_count;
    char source_ip[INET6_ADDRSTRLEN];
    char destination_ip[INET6_ADDRSTRLEN];
    int protocol_type;
    time_t timestamp;
} NetworkFlowStats;

// Configuration for thresholds
typedef struct {
    uint64_t min_packet_count;
    uint64_t min_byte_count;
} FilterConfig;

// Global configuration (simulated external config)
FilterConfig config = {100, 1024}; // Example thresholds

// Function prototypes
int parse_network_trace(const char *file_path);
void log_error(const char *message);

#define CACHE_SIZE 1024
typedef struct {
    NetworkFlowStats cache[CACHE_SIZE];
    int index;
} Cache;

Cache flow_cache;

// Initialize cache
void init_cache() {
    memset(flow_cache.cache, 0, sizeof(flow_cache.cache));
    flow_cache.index = 0;
}

// Add to cache with simple eviction policy
void add_to_cache(NetworkFlowStats *nfs) {
    if (flow_cache.index < CACHE_SIZE) {
        flow_cache.cache[flow_cache.index++] = *nfs;
    } else {
        // Evict oldest entry
        memmove(flow_cache.cache, &flow_cache.cache[1], sizeof(NetworkFlowStats) * (CACHE_SIZE - 1));
        flow_cache.cache[CACHE_SIZE - 1] = *nfs;
    }
}

// Main function to initialize dynamic array of NFS structures
int parse_network_trace(const char *file_path) {
    FILE *file = fopen(file_path, "r");
    if (!file) {
        log_error("Unable to open file.");
        return -1;
    }

    NetworkFlowStats *nfs_array = NULL;
    size_t capacity = 10;
    size_t count = 0;

    char line[4096];
    while (fgets(line, sizeof(line), file)) {
        NetworkFlowStats nfs;

        // Example parsing logic
        if (sscanf(line, "%lu %lu %255s %255s %d %ld",
                   &nfs.packet_count,
                   &nfs.byte_count,
                   nfs.source_ip,
                   nfs.destination_ip,
                   &nfs.protocol_type,
                   &nfs.timestamp) < 6) {
            log_error("Malformed line encountered.");
            continue;
        }

        // Filtering based on configuration
        if (nfs.packet_count >= config.min_packet_count &&
            nfs.byte_count >= config.min_byte_count) {

            // Check cache for existing entry
            int found = 0;
            for (int i = 0; i < flow_cache.index; ++i) {
                if (strcmp(flow_cache.cache[i].source_ip, nfs.source_ip) == 0 &&
                    strcmp(flow_cache.cache[i].destination_ip, nfs.destination_ip) == 0 &&
                    flow_cache.cache[i].protocol_type == nfs.protocol_type) {
                    found = 1;
                    break;
                }
            }

            if (!found) {
                // Resize array if necessary
                if (count >= capacity) {
                    capacity *= 2;
                    nfs_array = realloc(nfs_array, capacity * sizeof(NetworkFlowStats));
                    if (!nfs_array) {
                        log_error("Memory allocation failed.");
                        fclose(file);
                        return -1;
                    }
                }

                nfs_array[count++] = nfs;
                add_to_cache(&nfs);
            }
        }
    }

    fclose(file);

    // Null-terminate the array
    NetworkFlowStats *final_array = realloc(nfs_array, (count + 1) * sizeof(NetworkFlowStats));
    if (!final_array) {
        log_error("Memory reallocation failed.");
        return -1;
    }
    final_array[count].packet_count = 0; // Mark end of data

    return 0;
}

// Error logging function
void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}
