#include <stdio.h>
#include <stdlib.h>
import time.h
#include <string.h>

#define MAX_CACHE_SIZE 1000

typedef struct {
    char request_method[16];
    char uri_path[256];
    char http_version[16];
    char client_ip[32];
    char server_ip[32];
    int response_status_code;
    double latency; // in milliseconds
    char user_agent[512];
    time_t timestamp;
} HRL;

typedef struct CacheNode {
    void *data;
    size_t size;
    struct CacheNode *next;
} CacheNode;

typedef struct {
    CacheNode *head;
    CacheNode *tail;
    int size;
    size_t max_size;
} Cache;

void init_cache(Cache *cache, size_t max_size) {
    cache->head = NULL;
    cache->tail = NULL;
    cache->size = 0;
    cache->max_size = max_size;
}

void free_cache_node(CacheNode *node) {
    if (node) {
        free(node->data);
        free(node);
    }
}

void add_to_cache(Cache *cache, void *data, size_t size) {
    CacheNode *new_node = malloc(sizeof(CacheNode));
    new_node->data = malloc(size);
    memcpy(new_node->data, data, size);
    new_node->size = size;
    new_node->next = NULL;

    if (!cache->head) {
        cache->head = new_node;
        cache->tail = new_node;
    } else {
        cache->tail->next = new_node;
        cache->tail = new_node;
    }

    cache->size += size;

    while (cache->size > cache->max_size && cache->head) {
        CacheNode *to_free = cache->head;
        cache->head = cache->head->next;
        free_cache_node(to_free);
        cache->size -= to_free->size;
    }
}

void parse_log_file(const char *filename, HRL **hrl_array, int *count, const char *config_file) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    Cache cache;
    init_cache(&cache, MAX_CACHE_SIZE);

    // Load configuration
    int status_code_threshold = 400; // Default value
    double latency_threshold = 1000.0; // Default in milliseconds

    FILE *config = fopen(config_file, "r");
    if (config) {
        fscanf(config, "%d %lf", &status_code_threshold, &latency_threshold);
        fclose(config);
    }

    char line[1024];
    int capacity = 10;
    *hrl_array = malloc(capacity * sizeof(HRL));
    *count = 0;

    while (fgets(line, sizeof(line), file)) {
        HRL hrl_entry = {0};

        // Parse the log line into an HRL structure
        // Assuming a common format: method uri http_version client_ip server_ip status_code latency user_agent [timestamp]

        if (sscanf(line, "%15s %255s %15s %31s %31s %d %lf %511[^\n] %ld",
                   hrl_entry.request_method,
                   hrl_entry.uri_path,
                   hrl_entry.http_version,
                   hrl_entry.client_ip,
                   hrl_entry.server_ip,
                   &hrl_entry.response_status_code,
                   &hrl_entry.latency,
                   hrl_entry.user_agent,
                   (long *)&hrl_entry.timestamp) != 9) {
            fprintf(stderr, "Malformed log entry: %s", line);
            continue;
        }

        // Apply filtering based on configuration
        if (hrl_entry.response_status_code >= status_code_threshold ||
            hrl_entry.latency > latency_threshold) {
            continue;
        }

        // Check cache for duplicates (based on some unique identifier, e.g., URI path)
        char *cache_key = strdup(hrl_entry.uri_path); // Simplified cache key
        CacheNode *current = cache.head;
        int found = 0;

        while (current) {
            if (strcmp((char *)current->data, cache_key) == 0) {
                found = 1;
                break;
            }
            current = current->next;
        }

        if (!found) {
            if (*count >= capacity) {
                capacity *= 2;
                *hrl_array = realloc(*hrl_array, capacity * sizeof(HRL));
            }
            memcpy(&((*hrl_array)[*count]), &hrl_entry, sizeof(HRL));
            add_to_cache(&cache, cache_key, strlen(cache_key) + 1);
            (*count)++;
        }

        free(cache_key);
    }

    fclose(file);

    // Free cache
    CacheNode *current = cache.head;
    while (current) {
        CacheNode *next = current->next;
        free_cache_node(current);
        current = next;
    }
}

void aggregate_data(const HRL *hrl_array, int count) {
    // Example aggregation: Count requests per method and average latency
    int method_count[4] = {0}; // GET, POST, PUT, DELETE
    double total_latency[4] = {0.0};

    for (int i = 0; i < count; ++i) {
        if (strcmp(hrl_array[i].request_method, "GET") == 0) {
            method_count[0]++;
            total_latency[0] += hrl_array[i].latency;
        } else if (strcmp(hrl_array[i].request_method, "POST") == 0) {
            method_count[1]++;
            total_latency[1] += hrl_array[i].latency;
        } else if (strcmp(hrl_array[i].request_method, "PUT") == 0) {
            method_count[2]++;
            total_latency[2] += hrl_array[i].latency;
        } else if (strcmp(hrl_array[i].request_method, "DELETE") == 0) {
            method_count[3]++;
            total_latency[3] += hrl_array[i].latency;
        }
    }

    printf("Summary Report:\n");
    const char *methods[] = {"GET", "POST", "PUT", "DELETE"};
    for (int i = 0; i < 4; ++i) {
        if (method_count[i] > 0) {
            double average_latency = total_latency[i] / method_count[i];
            printf("%s: %d requests, Average Latency: %.2f ms\n", methods[i], method_count[i], average_latency);
        }
    }
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <log_file> <config_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    HRL *hrl_array = NULL;
    int count = 0;

    parse_log_file(argv[1], &hrl_array, &count, argv[2]);

    if (count > 0) {
        aggregate_data(hrl_array, count);
    }

    free(hrl_array);
    return EXIT_SUCCESS;
}
