#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    uint8_t CRCFLAG;
    time_t timestamp; // to track when entry was added or updated
} NFAPI_CRC_INDICATION_PDU_T;

#define LIST_SIZE 1024

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T entries[LIST_SIZE];
    pthread_mutex_t lock;
    size_t count;
} CRCList;

void initialize_list(CRCList* list) {
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
}

int add_or_update_entry(CRCList* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; i++) {
        if (list->entries[i].RX_UE_INFORMATION_TAG == entry.RX_UE_INFORMATION_TAG &&
            list->entries[i].RNTI == entry.RNTI) {

            // Update existing entry
            list->entries[i] = entry;
            pthread_mutex_unlock(&list->lock);
            return 0; // Success
        }
    }

    if (list->count < LIST_SIZE) {
        entry.timestamp = time(NULL); // Set timestamp for new entry
        list->entries[list->count++] = entry;
        pthread_mutex_unlock(&list->lock);
        return 1; // New entry added
    } else {
        pthread_mutex_unlock(&list->lock);
        return -1; // List full
    }
}

void purge_old_entries(CRCList* list) {
    time_t current_time = time(NULL);
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count;) {
        if ((current_time - list->entries[i].timestamp) > 5) { // 5 seconds threshold
            memmove(&list->entries[i], &list->entries[i + 1],
                    (list->count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            list->count--;
        } else {
            i++;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void reset_all_crc_flags(CRCList* list) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; i++) {
        list->entries[i].CRCFLAG = 0;
    }

    pthread_mutex_unlock(&list->lock);
}

void destroy_list(CRCList* list) {
    pthread_mutex_destroy(&list->lock);
}

int main() {
    CRCList crcList;
    initialize_list(&crcList);

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T entry = {1, 100, rand() % 2, time(NULL)};
    add_or_update_entry(&crcList, entry);

    purge_old_entries(&crcList);
    reset_all_crc_flags(&crcList);

    destroy_list(&crcList);
    return 0;
}
