#define MAX_SESSIONS 100

typedef struct {
    int sessionID;
    NFAPI_RX_TX_CONFIG config;
    int initialized;
} Session;

Session sessions[MAX_SESSIONS];
int sessionCount = 0;

// Logging mechanism
void log_metrics(int sessionId, double packetLoss, double latency) {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);

    // Truncate the newline from timestamp
    timestamp[strcspn(timestamp, "\n")] = '\0';

    printf("[%s] SessionID: %d - Packet Loss: %.2f%%, Latency: %.2f ms\n",
           timestamp, sessionId, packetLoss * 100, latency);
}

// Error handling function
void handle_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Function to find an available session slot or create a new one
Session* get_session_slot(int sessionId) {
    for (int i = 0; i < MAX_SESSIONS; ++i) {
        if (!sessions[i].initialized || sessions[i].config.sessionId == sessionId) {
            return &sessions[i];
        }
    }

    handle_error("Max session limit reached");
    return NULL;
}

// Function to initialize and configure a network interface
int configure_network_interface(int sessionId, int bandwidth, double centerFrequency, double channelBandwidth) {
    Session *session = get_session_slot(sessionId);
    if (!session) {
        return -1; // Error: Unable to allocate session slot
    }

    memset(&session->config, 0, sizeof(NFAPI_RX_TX_CONFIG));

    session->config.sessionId = sessionId;
    session->config.rxChannelBandwidth = channelBandwidth;
    session->config.txCenterFrequency = centerFrequency;
    session->config.bandwidth = bandwidth;

    // Simulate configuration and initialization
    int status = nfasyscfg_open(&session->config);
    if (status != NF_SUCCESS) {
        handle_error("Failed to open NFAPI session");
        return -1;
    }

    session->initialized = 1;
    sessionCount++;

    // Simulating monitoring metrics
    double simulatedPacketLoss = 0.02; // Example: 2% packet loss
    double simulatedLatency = 10.5;    // Example: 10.5 ms latency

    log_metrics(sessionId, simulatedPacketLoss, simulatedLatency);

    return 0; // Success
}

// Cleanup function to free resources
void cleanup_sessions() {
    for (int i = 0; i < MAX_SESSIONS; ++i) {
        if (sessions[i].initialized) {
            nfasyscfg_close(&sessions[i].config);
            sessions[i].initialized = 0;
        }
    }
}

// Example usage
int main() {
    configure_network_interface(1, 100, 2405.0, 20.0);
    configure_network_interface(2, 200, 2415.0, 40.0);

    // Simulate application running
    sleep(10); 

    cleanup_sessions();
    return 0;
}
