    dynArray->capacity = maxSize;
    dynArray->count = 0;
    pthread_mutex_init(&dynArray->lock, NULL);
    return dynArray;
}

int addElement(DynamicArray* dynArray, NFAPI_CRC_INDICATION_PDU_T element) {
