    if (dynArray->count >= dynArray->capacity) {
        pthread_mutex_unlock(&dynArray->lock);
        return -1; // Overflow condition
    }

    dynArray->array[dynArray->count++] = element;
    pthread_mutex_unlock(&dynArray->lock);
