    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} MAC_ECTable;

// Function to initialize the MAC EC table
void init_MAC_ECTable(MAC_ECTable *table) {
    table->size = 0;
    table->capacity = INITIAL_CAPACITY;
    table->array = (MAC_EC_T *)malloc(table->capacity * sizeof(MAC_EC_T));
    pthread_mutex_init(&table->mutex, NULL);
}

// Function to validate MAC EC with an external source
int validate_MAC_EC(MAC_EC_T ec) {
    // Simulate validation logic
    return 1; // Assume valid for simplicity
}

// Function to resize the array when capacity is reached
void resize_array(MAC_ECTable *table) {
    size_t new_capacity = table->capacity * 2;
    MAC_EC_T *new_array = (MAC_EC_T *)realloc(table->array, new_capacity * sizeof(MAC_EC_T));
    if (new_array) {
        table->array = new_array;
        table->capacity = new_capacity;
    } else {
        // Handle memory allocation failure
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

// Function to add a MAC EC
int add_MAC_EC(MAC_ECTable *table, MAC_EC_T ec) {
    pthread_mutex_lock(&table->mutex);

    if (!validate_MAC_EC(ec)) {
        pthread_mutex_unlock(&table->mutex);
        return 0; // Validation failed
    }

    if (table->size == table->capacity) {
        resize_array(table);
    }

    for (size_t i = 0; i < table->size; ++i) {
        if (table->array[i].EID == ec.EID) {
            pthread_mutex_unlock(&table->mutex);
            return 0; // MAC EC already exists
        }
    }

    table->array[table->size++] = ec;
    pthread_mutex_unlock(&table->mutex);
    return 1;
}

// Function to update a MAC EC by EID
int update_MAC_EC(MAC_ECTable *table, int eid, MAC_EC_T new_ec) {
    pthread_mutex_lock(&table->mutex);

    for (size_t i = 0; i < table->size; ++i) {
        if (table->array[i].EID == eid) {
            if (!validate_MAC_EC(new_ec)) {
                pthread_mutex_unlock(&table->mutex);
                return 0; // Validation failed
            }
            table->array[i] = new_ec;
            pthread_mutex_unlock(&table->mutex);
            return 1;
        }
    }

    pthread_mutex_unlock(&table->mutex);
    return 0; // MAC EC not found
}

// Function to retrieve a MAC EC by EID
MAC_EC_T *get_MAC_EC(MAC_ECTable *table, int eid) {
    pthread_mutex_lock(&table->mutex);

    for (size_t i = 0; i < table->size; ++i) {
        if (table->array[i].EID == eid) {
            MAC_EC_T *ec = &table->array[i];
            pthread_mutex_unlock(&table->mutex);
            return ec;
        }
    }

    pthread_mutex_unlock(&table->mutex);
    return NULL; // MAC EC not found
}

// Function to free the MAC EC table resources
void free_MAC_ECTable(MAC_ECTable *table) {
    pthread_mutex_lock(&table->mutex);
    free(table->array);
    pthread_mutex_unlock(&table->mutex);
    pthread_mutex_destroy(&table->mutex);
}
