#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int id;
    int supported_scs; // Subcarrier spacing
    int *pucch_resources; // List of configured PUCCH resources
} MACConfig;

typedef struct ConfigNode {
    MACConfig config;
    struct ConfigNode* next;
} ConfigNode;

typedef struct {
    ConfigNode* head;
    size_t count;
} MACConfigList;

MACConfigList* create_mac_config_list() {
    MACConfigList* list = (MACConfigList*)malloc(sizeof(MACConfigList));
    if (list) {
        list->head = NULL;
        list->count = 0;
    }
    return list;
}

void free_mac_config_list(MACConfigList* list) {
    ConfigNode* current = list->head;
    while (current) {
        ConfigNode* next = current->next;
        free(current->config.pucch_resources);
        free(current);
        current = next;
    }
    free(list);
}

int add_configuration(MACConfigList* list, int id, int supported_scs, int* pucch_resources, size_t res_count) {
    if (!list || !pucch_resources) return -1;

    ConfigNode* new_node = (ConfigNode*)malloc(sizeof(ConfigNode));
    if (!new_node) return -1;

    new_node->config.id = id;
    new_node->config.supported_scs = supported_scs;
    new_node->config.pucch_resources = malloc(res_count * sizeof(int));
    if (!new_node->config.pucch_resources) {
        free(new_node);
        return -1;
    }

    memcpy(new_node->config.pucch_resources, pucch_resources, res_count * sizeof(int));
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    return 0; // Success
}

int remove_configuration(MACConfigList* list, int id) {
    if (!list || !list->head) return -1;

    ConfigNode *current = list->head, *prev = NULL;

    while (current && current->config.id != id) {
        prev = current;
        current = current->next;
    }

    if (!current) return -1; // Not found

    if (prev) {
        prev->next = current->next;
    } else {
        list->head = current->next;
    }

    free(current->config.pucch_resources);
    free(current);

    list->count--;
    return 0; // Success
}

void iterate_configurations(MACConfigList* list, void (*operation)(MACConfig*)) {
    if (!list || !list->head) return;

    ConfigNode* current = list->head;
    while (current) {
        operation(&current->config);
        current = current->next;
    }
}

// Mock external configuration management service
int fetch_configuration_from_service(int id, MACConfig* config) {
    // Simulate network latency and occasional failures
    if ((rand() % 10) < 2) { // 20% failure rate
        return -1; // Service failure
    }

    // Simulated delay
    usleep(100 * 1000); 

    // Mock response, populate config with data
    config->id = id;
    config->supported_scs = (rand() % 5) + 15; // Random SCS between 15 and 19
    int res_count = rand() % 10 + 1; // Random resource count between 1 and 10
    config->pucch_resources = malloc(res_count * sizeof(int));

    for (int i = 0; i < res_count; ++i) {
        config->pucch_resources[i] = rand();
    }

    return 0; // Success
}

MACConfig* get_configuration_with_retry(int id, int retries, int delay_ms) {
    MACConfig *config = NULL;
    for (int attempt = 0; attempt <= retries; ++attempt) {
        if (fetch_configuration_from_service(id, config) == 0) {
            return config;
        }

        usleep(delay_ms * 1000); // Delay before retry
    }

    return NULL; // All attempts failed
}

// Example operation to perform on each configuration
void print_config(MACConfig* config) {
    if (config) {
        printf("ID: %d, SCS: %d, PUCCH Resources Count: %lu\n",
               config->id, config->supported_scs, 
               config ? config->pucch_resources ? sizeof(config->pucch_resources) / sizeof(int) : 0 : 0);
    }
}

// Main function for demonstration purposes
int main() {
