    int pucch_resources[] = {1, 2, 3};
    add_configuration(list, 101, 15, pucch_resources, sizeof(pucch_resources) / sizeof(int));

    iterate_configurations(list, print_config);

    remove_configuration(list, 101);

    free_mac_config_list(list);

    return 0;
}
