// Function to dynamically allocate and populate an array of structures.
NFAPI_CRC_INDICATION_PDU_T* create_crc_pdu_array(size_t max_size, int *allocated_count) {
    if (max_size < MINIMUM_SIZE || max_size > MAX_ARRAY_SIZE) {
        fprintf(stderr, "Invalid size for CRC PDU Array.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu_array = malloc(max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu_array == NULL) {
        perror("Failed to allocate memory for CRC PDU array.");
        return NULL;
    }

    int seen_tags[MAX_ARRAY_SIZE] = {0};
    srand(time(NULL));  // Seed the random number generator.

    for (size_t i = 0; i < max_size; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *current_pdu = &pdu_array[i];

        int tag;
        do {
            tag = rand() % (MAX_ARRAY_SIZE * 2); // Ensuring uniqueness by expanding the range
        } while (seen_tags[tag]);

        current_pdu->RX_UE_INFORMATION_TAG = tag;
        seen_tags[tag] = 1;  // Mark this tag as used

        current_pdu->RNTI = rand() % MAX_ARRAY_SIZE;

        current_pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;  // Randomly set CRCFLAG to 0 or 1
    }

    *allocated_count = max_size;
    return pdu_array;
}

// Function to free the allocated array.
