#include <time.h>

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[4];
} NFAPI_CRC_INDICATION_PDU_T;

#define LIST_INIT_CAPACITY 10

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *items;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    // Logging framework integration would be here
} DynamicList;

void log_operation(const char* operation, size_t count) {
    printf("Operation: %s, Count: %zu\n", operation, count);
}

void random_crc_flag(uint8_t *crc_flag) {
    srand(time(NULL));
    for (int i = 0; i < sizeof(crc_flag); i++) {
        crc_flag[i] = rand() & 1;
    }
}

DynamicList* dynamic_list_create() {
    DynamicList* list = malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->items = calloc(LIST_INIT_CAPACITY, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->items) {
        free(list);
        return NULL;
    }

    pthread_mutex_init(&list->lock, NULL);
    list->capacity = LIST_INIT_CAPACITY;
    list->size = 0;

    log_operation("List Created", LIST_INIT_CAPACITY);

    return list;
}

int dynamic_list_resize(DynamicList* list) {
    size_t new_capacity = list->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_items = realloc(list->items, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!new_items) return -1;

    list->items = new_items;
    list->capacity = new_capacity;
    log_operation("List Resized", new_capacity);
    return 0;
}

int dynamic_list_add(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity && dynamic_list_resize(list)) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    memcpy(&list->items[list->size], &item, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size++;
    log_operation("Item Added", 1);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int dynamic_list_remove(DynamicList* list) {
    pthread_mutex_lock(&list->lock);

    if (list->size == 0) {
        pthread_mutex_unlock(&list->lock);
        log_operation("Remove Failed - Empty", 0);
        return -1;
    }

    memmove(&list->items[0], &list->items[1], (list->size - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size--;
    log_operation("Item Removed", 1);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void* read_access(DynamicList* list, size_t index) {
    pthread_mutex_lock(&list->lock);

    if (index >= list->size) {
        pthread_mutex_unlock(&list->lock);
        log_operation("Read Failed - Invalid Index", 0);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *item = &list->items[index];
    log_operation("Item Accessed", 1);

    pthread_mutex_unlock(&list->lock);
    return (void*) item;
}

void dynamic_list_destroy(DynamicList* list) {
    pthread_mutex_lock(&list->lock);

    free(list->items);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);

    log_operation("List Destroyed", 0);
    free(list);
}
```

