            if (!context) return -1;

            context->sessionID = sessionID;
            context->ueIdentifier = strdup(ueIdentifier);
            context->bufferSize = manager->bufferConfigSize;
            context->pduBuffer = (char*)calloc(manager->bufferConfigSize, sizeof(char));

            if (!context->pduBuffer || !context->ueIdentifier) {
                free(context->pduBuffer);
                free(context->ueIdentifier);
                free(context);
                return -1;
            }

            manager->sessions[i] = context;
            manager->activeSessionsCount++;
            return 0;
        }
    }

    return -1; // Should not reach here
}

void removeSession(SessionManager* manager, int sessionID) {
    for (int i = 0; i < MAX_SESSIONS; ++i) {
        if (manager->sessions[i] && manager->sessions[i]->sessionID == sessionID) {
            free(manager->sessions[i]->pduBuffer);
            free(manager->sessions[i]->ueIdentifier);
            free(manager->sessions[i]);

            manager->sessions[i] = NULL;
            manager->activeSessionsCount--;
            return;
        }
