                fprintf(stderr, "Failed to update UE Identifier\n");
            }
            return;
        }
    }

    fprintf(stderr, "Session ID not found\n");
}

char* getPDUBuffer(SessionManager* manager, int sessionID) {
    for (int i = 0; i < MAX_SESSIONS; ++i) {
        if (manager->sessions[i] && manager->sessions[i]->sessionID == sessionID) {
            return manager->sessions[i]->pduBuffer;
        }
    }

    fprintf(stderr, "Session ID not found\n");
    return NULL;
}

int isSessionActive(SessionManager* manager, int sessionID) {
    for (int i = 0; i < MAX_SESSIONS; ++i) {
        if (manager->sessions[i] && manager->sessions[i]->sessionID == sessionID) {
            return 1;
        }
    }

    return 0;
}

void freeResources(SessionManager* manager) {
