    CRC_INDICATION_REL8_TAG crc_tag;
    bool CRCFLAG; // Randomly set
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

// Thread-safe structure for the linked list
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* head;
    pthread_mutex_t lock;
    size_t allocated_nodes; // To track allocations
} ThreadSafeLinkedList;

ThreadSafeLinkedList* create_linked_list() {
    ThreadSafeLinkedList* list = (ThreadSafeLinkedList*)malloc(sizeof(ThreadSafeLinkedList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->allocated_nodes = 0;

    // Sentinel node
    NFAPI_CRC_INDICATION_PDU_T* sentinel = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!sentinel) {
        free(list);
        return NULL;
    }

    sentinel->next = NULL;
    pthread_mutex_lock(&list->lock);
    list->head = sentinel; // Initialize the list with the sentinel
    list->allocated_nodes++;
    pthread_mutex_unlock(&list->lock);

    return list;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_node(ThreadSafeLinkedList* list) {
    if (!list) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) return NULL;

    // Randomly set CRCFLAG
    new_node->crc_tag.RX_UE_INFORMATION_TAG = rand();  // Example randomization
    new_node->crc_tag.RNTI = rand() % 65536;  // Example RNTI value
    new_node->CRCFLAG = rand() % 2 == 0;

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head->next;
    list->head->next = new_node;
    list->allocated_nodes++;
    pthread_mutex_unlock(&list->lock);

    return new_node;
}

void free_all_nodes(ThreadSafeLinkedList* list) {
    if (!list) return;

    NFAPI_CRC_INDICATION_PDU_T *current, *temp;

    pthread_mutex_lock(&list->lock);
    current = list->head->next;  // Start from the first actual node

    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp);
    }

    list->allocated_nodes = 0;
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Function to periodically collect garbage (simulate with manual call)
void periodic_garbage_collection(ThreadSafeLinkedList* list) {
    // Implement logic here as needed
    printf("Garbage collection: %zu nodes allocated\n", list->allocated_nodes);
}

int main() {
    ThreadSafeLinkedList* linked_list = create_linked_list();

    if (!linked_list) return 1;

    // Simulate allocation of multiple nodes
    for (size_t i = 0; i < 1000000; ++i) {  // Large-scale deployment simulation
        allocate_node(linked_list);
    }

    periodic_garbage_collection(linked_list);

    free_all_nodes(linked_list);

    return 0;
}
