#include <stdio.h>
#include <stdlib.h>
#include <stdatomic.h>
#include <string.h>

typedef struct {
    int RNTI;
    uint8_t CRCFLAG; // Assuming it's a single byte for simplicity.
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    CRC_INDICATION_REL8_TAG crcIndicationTag;
} NFAPI_CRC_INDICATION_PDU_T;

// Node structure for linked list
struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
};

// Head of the list, wrapped in atomic pointer for lock-free operations
static atomic_struct(Node*) head = {NULL};

// Function to insert an element into the list
int insert_into_list(NFAPI_CRC_INDICATION_PDU_T newElement) {
    struct Node** curr = &atomic_load(&head);
    struct Node* prev = NULL;

    while (*curr != NULL) {
        if ((*curr)->data.RNTI == newElement.RNTI &&
            (*curr)->data.crcIndicationTag.CRCFLAG == newElement.crcIndicationTag.CRCFLAG) {
            // Duplicate found, not inserting
            return 0; 
        }

        prev = *curr;
        curr = &((*curr)->next);
    }

    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    if (newNode == NULL) {
        perror("Failed to allocate memory");
        return -1; // Memory allocation failure
    }

    newNode->data = newElement;
    newNode->next = NULL;

    while (!atomic_compare_exchange_weak(curr, &prev, newNode)) {
        prev = *curr;
        curr = &((*curr)->next);
    }

    return 1; // Successfully inserted
}

// Utility function to generate a random CRCFLAG for testing purposes
void set_random_crcflag(CRC_INDICATION_REL8_TAG* tag) {
    if (tag != NULL) {
        tag->CRCFLAG = rand() % 256;
    }
}
