// Define the structures
typedef struct PHY_STATS_T {
    int data; // Placeholder for actual data
    struct MAC_CONTEXT_T *mac_context;
} PHY_STATS_T;

typedef struct MAC_CONTEXT_T {
    pthread_mutex_t lock;
    PHY_STATS_T **phy_stats;
    size_t num_phy_stats;
    struct MAC_CONTEXT_T *next;
} MAC_CONTEXT_T;

// Global head of the linked list
MAC_CONTEXT_T *head = NULL;
pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize a new MAC context node
MAC_CONTEXT_T* create_mac_context(size_t initial_capacity) {
    MAC_CONTEXT_T *node = (MAC_CONTEXT_T*)malloc(sizeof(MAC_CONTEXT_T));
    if (!node) return NULL;

    pthread_mutex_init(&node->lock, NULL);
    node->phy_stats = (PHY_STATS_T**)calloc(initial_capacity, sizeof(PHY_STATS_T*));
    node->num_phy_stats = 0;
    node->next = NULL;

    return node;
}

// Function to add a MAC context node to the linked list
void add_mac_context(MAC_CONTEXT_T *new_node) {
    pthread_mutex_lock(&global_lock);
    new_node->next = head;
    head = new_node;
    pthread_mutex_unlock(&global_lock);
}

// Function to safely add a PHY_STATS instance to a MAC context
int add_phy_stats_to_mac_context(MAC_CONTEXT_T *mac_ctx, PHY_STATS_T *phy_stats) {
    pthread_mutex_lock(&mac_ctx->lock);

    if (mac_ctx->num_phy_stats >= sizeof(mac_ctx->phy_stats) / sizeof(PHY_STATS_T*)) {
        size_t new_capacity = mac_ctx->num_phy_stats ? mac_ctx->num_phy_stats * 2 : 4;
        PHY_STATS_T **new_array = realloc(mac_ctx->phy_stats, new_capacity * sizeof(PHY_STATS_T*));
        if (!new_array) {
            pthread_mutex_unlock(&mac_ctx->lock);
            return -1; // Memory allocation failed
        }
        mac_ctx->phy_stats = new_array;
    }

    mac_ctx->phy_stats[mac_ctx->num_phy_stats] = phy_stats;
    phy_stats->mac_context = mac_ctx;
    mac_ctx->num_phy_stats++;

    pthread_mutex_unlock(&mac_ctx->lock);
    return 0;
}

// Function to check for orphaned PHY_STATS instances
void check_for_orphans() {
    MAC_CONTEXT_T *current = head;
    while (current) {
        pthread_mutex_lock(&current->lock);

        for (size_t i = 0; i < current->num_phy_stats; ++i) {
            if (!current->phy_stats[i]) continue;

            // If a PHY_STATS instance is not linked back, it's considered orphaned
            if (current->phy_stats[i]->mac_context != current) {
                fprintf(stderr, "Orphaned PHY_STATS_T found at index %zu\n", i);
            }
        }

        pthread_mutex_unlock(&current->lock);
        current = current->next;
    }
}

// Function to clean up the linked list
void cleanup_mac_contexts() {
    MAC_CONTEXT_T *current = head;
    while (current) {
        MAC_CONTEXT_T *to_free = current;
        current = current->next;

        pthread_mutex_lock(&to_free->lock);
        free(to_free->phy_stats);
        pthread_mutex_unlock(&to_free->lock);

        pthread_mutex_destroy(&to_free->lock);
        free(to_free);
    }
}

// Example usage of the functions
int main() {
    // Create and add MAC contexts
    MAC_CONTEXT_T *mac1 = create_mac_context(2);
    MAC_CONTEXT_T *mac2 = create_mac_context(2);

    if (mac1 && mac2) {
        add_mac_context(mac1);
        add_mac_context(mac2);

        PHY_STATS_T phy_stat1, phy_stat2;
        add_phy_stats_to_mac_context(mac1, &phy_stat1);
        add_phy_stats_to_mac_context(mac2, &phy_stat2);
    }

    // Check for orphaned PHY_STATS instances
    check_for_orphans();

    // Clean up all MAC contexts
    cleanup_mac_contexts();

    return 0;
}
```

### Key Points:
- **Thread Safety**: Each `MAC_CONTEXT_T` node has its own mutex to allow concurrent modifications, while a global lock protects the linked list head.
- **Dynamic Growth**: The `phy_stats` array in each `MAC_CONTEXT_T` can grow dynamically using `realloc`.
- **Orphan Detection**: A function checks for orphaned `PHY_STATS_T` instances by verifying their linkage back to the `MAC_CONTEXT_T`.
- **Resource Management**: Proper cleanup of allocated memory and mutexes is ensured.
- **Scalability and Performance**: The design allows for easy scaling with increased data volume and concurrent access.']

