    unsigned long RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct LinkedList {
    NFAPI_CRC_INDICATION_PDU_T *head;
    int size;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) {
        fprintf(stderr, "Failed to allocate memory for linked list.\n");
        return NULL;
    }
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_node(NFAPI_CRC_INDICATION_PDU_T *node) {
    if (node) {
        free(node->RX_UE_INFORMATION_TAG); // Assuming this was dynamically allocated
        free(node);
    }
}

int append_node(LinkedList* list, unsigned long rnti) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed.\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_node->RX_UE_INFORMATION_TAG = (struct RX_UE_INFORMATION_TAG*)malloc(sizeof(struct RX_UE_INFORMATION_TAG)); // Dummy allocation
    if (!new_node->RX_UE_INFORMATION_TAG) {
        free(new_node);
        fprintf(stderr, "Memory allocation failed for RX_UE_INFORMATION_TAG.\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_node->RNTI = rnti;

    // Randomly set CRCFLAG
    time_t t;
    srand((unsigned)time(&t));
    new_node->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void garbage_collect(LinkedList* list, int threshold) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    NFAPI_CRC_INDICATION_PDU_T *prev = NULL;

    while (current) {
        if ((rand() % 100) < threshold) { // Randomly decide to remove based on threshold
            NFAPI_CRC_INDICATION_PDU_T *to_free = current;
            current = current->next;
            if (prev) {
                prev->next = current;
            } else {
                list->head = current;
            }
            free_node(to_free);
            list->size--;
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void destroy_linked_list(LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free_node(current);
        current = next;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    LinkedList* list = create_linked_list();
    if (!list) return -1;

    for (int i = 0; i < 100; ++i) {
        append_node(list, i);
    }

    garbage_collect(list, 20); // Example threshold

    destroy_linked_list(list);
    return 0;
}
