#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>

// Assuming these types are defined elsewhere
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG tag;
    int CRCFLAG; // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

// Logger function (assuming logging framework is already integrated)
void log_operation(const char* operation, const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    printf("Operation: %s - RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n",
           operation, pdu->tag.RX_UE_INFORMATION_TAG, pdu->tag.RNTI, pdu->CRCFLAG);
}

// Global dynamic array management
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

void init_dynamic_array(DynamicArray *da) {
    da->capacity = 10; // Initial capacity
    da->size = 0;
    da->array = malloc(da->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&da->lock, NULL);
}

void destroy_dynamic_array(DynamicArray *da) {
    free(da->array);
    pthread_mutex_destroy(&da->lock);
}

// Ensure array has enough capacity
void ensure_capacity(DynamicArray *da) {
    if (da->size >= da->capacity) {
        size_t new_capacity = da->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            perror("Failed to reallocate memory");
            exit(EXIT_FAILURE);
        }
        da->array = new_array;
        da->capacity = new_capacity;
    }
}

// Add a new PDU
void add_pdu(DynamicArray *da, const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&da->lock);

    ensure_capacity(da);
    memcpy(&da->array[da->size], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    log_operation("Add", pdu);
    da->size++;

    pthread_mutex_unlock(&da->lock);
}

// Remove a PDU by index
void remove_pdu(DynamicArray *da, size_t index) {
    if (index >= da->size) {
        fprintf(stderr, "Index out of bounds\n");
        return;
    }

    pthread_mutex_lock(&da->lock);

    log_operation("Remove", &da->array[index]);
    memmove(&da->array[index], &da->array[index + 1], (da->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    da->size--;

    pthread_mutex_unlock(&da->lock);
}

// Access a PDU by index
const NFAPI_CRC_INDICATION_PDU_T* access_pdu(DynamicArray *da, size_t index) {
    if (index >= da->size) {
        fprintf(stderr, "Index out of bounds\n");
        return NULL;
    }

    pthread_mutex_lock(&da->lock);

    log_operation("Access", &da->array[index]);

    pthread_mutex_unlock(&da->lock);
    return &da->array[index];
}

// Sample function to simulate network data fetching and error handling
int fetch_data_with_retry(NFAPI_CRC_INDICATION_PDU_T *pdu, int max_retries) {
    for (int attempts = 0; attempts < max_retries; ++attempts) {
        // Simulate network data fetching with possible failure
        if ((rand() % 10) != 0) { // 90% chance of success
            pdu->tag.RX_UE_INFORMATION_TAG = rand();
            pdu->tag.RNTI = rand();
            pdu->CRCFLAG = (rand() % 2); // Randomly set CRCFLAG to 0 or 1
            return 0; // Success
        }
        usleep(100000); // Wait for a short period before retrying
    }
    fprintf(stderr, "Failed to fetch data after multiple attempts\n");
    return -1;
}

// Example usage of the dynamic array management
void manage_pdus() {
    DynamicArray da;
    init_dynamic_array(&da);

    NFAPI_CRC_INDICATION_PDU_T pdu;
    int max_retries = 5;

    for (size_t i = 0; i < 10000000; ++i) { // Simulating a large number of entries
        if (fetch_data_with_retry(&pdu, max_retries) == 0) {
            add_pdu(&da, &pdu);
        }
    }

    // Example access and removal
    if (access_pdu(&da, 500)) {
        remove_pdu(&da, 500);
    }

    destroy_dynamic_array(&da);
}

int main() {
    manage_pdus();
    return 0;
