#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define the Message structure with potential for future extension.
typedef struct {
    int id;
    time_t timestamp;
    size_t payload_length;
} Message;

// Extendable message type to accommodate future changes.
typedef void* ExtendedMessage;
#define BASE_MESSAGE ((void*)&((Message*)0)->id)
#define EXTENDED_MESSAGE_SIZE (sizeof(ExtendedMessage) - sizeof(Message))

typedef struct {
    ExtendedMessage *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} MessageArray;

// Function prototypes
int init_message_array(MessageArray *array, size_t initial_capacity);
void cleanup_message_array(MessageArray *array);
int add_message(MessageArray *array, int id, time_t timestamp, size_t payload_length);
int update_message(MessageArray *array, int id, time_t timestamp, size_t payload_length);
Message* get_messages_in_range(MessageArray *array, time_t start_time, time_t end_time, Message **results, size_t *result_count);

// Initialize the dynamic array
int init_message_array(MessageArray *array, size_t initial_capacity) {
    pthread_mutex_init(&array->lock, NULL);
    array->data = (ExtendedMessage *)calloc(initial_capacity, sizeof(ExtendedMessage));
    if (!array->data) return -1;
    array->capacity = initial_capacity;
    array->size = 0;
    return 0;
}

// Clean up the dynamic array
void cleanup_message_array(MessageArray *array) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->size; ++i) {
        free(array->data[i]);
    }
    free(array->data);
    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
}

// Add a new message
int add_message(MessageArray *array, int id, time_t timestamp, size_t payload_length) {
    pthread_mutex_lock(&array->lock);

    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        ExtendedMessage *new_data = realloc(array->data, new_capacity * sizeof(ExtendedMessage));
        if (!new_data) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Memory allocation failed
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }

    Message *msg = (Message*)calloc(1, sizeof(Message) + EXTENDED_MESSAGE_SIZE);
    if (!msg) {
        pthread_mutex_unlock(&array->lock);
        return -1; // Memory allocation failed
    }

    msg->id = id;
    msg->timestamp = timestamp;
    msg->payload_length = payload_length;

    array->data[array->size++] = (ExtendedMessage)msg;
    pthread_mutex_unlock(&array->lock);

    return 0;
}

// Update an existing message by ID
int update_message(MessageArray *array, int id, time_t timestamp, size_t payload_length) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->size; ++i) {
        Message *msg = (Message*)array->data[i];
        if (msg->id == id) {
            msg->timestamp = timestamp;
            msg->payload_length = payload_length;
            pthread_mutex_unlock(&array->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&array->lock);
    return -1; // Message not found
}

// Retrieve messages within a specific time range
Message* get_messages_in_range(MessageArray *array, time_t start_time, time_t end_time, Message **results, size_t *result_count) {
    pthread_mutex_lock(&array->lock);

    size_t count = 0;
    for (size_t i = 0; i < array->size; ++i) {
        Message *msg = (Message*)array->data[i];
        if (msg->timestamp >= start_time && msg->timestamp <= end_time) {
            count++;
        }
    }

    if (count == 0) {
        pthread_mutex_unlock(&array->lock);
        return NULL;
    }

    *results = malloc(count * sizeof(Message));
    if (!*results) {
        pthread_mutex_unlock(&array->lock);
        return NULL; // Memory allocation failed
    }

    size_t j = 0;
    for (size_t i = 0; i < array->size; ++i) {
        Message *msg = (Message*)array->data[i];
        if (msg->timestamp >= start_time && msg->timestamp <= end_time) {
            (*results)[j++] = *msg;
        }
    }

    *result_count = count;

    pthread_mutex_unlock(&array->lock);
    return *results;
}

// Example usage
int main() {
    MessageArray array;
    init_message_array(&array, 10);

    add_message(&array, 1, time(NULL), 100);
    add_message(&array, 2, time(NULL) - 3600, 200); // 1 hour ago

    Message *results = NULL;
    size_t result_count = 0;
    get_messages_in_range(&array, time(NULL) - 7200, time(NULL), &results, &result_count);

    for (size_t i = 0; i < result_count; ++i) {
        printf("Message ID: %d, Timestamp: %ld, Payload Length: %zu\n", results[i].id, results[i].timestamp, results[i].payload_length);
    }

    if (results) free(results);

    cleanup_message_array(&array);
    return 0;
}
