#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_STRUCTURES 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    time_t timestamp;
    int frequency;
} ManagedPDU;

int validate_RNTI(int rnti, const int* user_list, size_t user_count) {
    for (size_t i = 0; i < user_count; ++i) {
        if (user_list[i] == rnti) return 1;
    }
    return 0;
}

double compute_weighted_sum(NFAPI_CRC_INDICATION_PDU_T* pdu, double accuracy_factor, double frequency_factor) {
    // Example weighted sum calculation
    return (accuracy_factor * (pdu->RX_UE_INFORMATION_TAG + pdu->RNTI)) +
           (frequency_factor * pdu->CRCFLAG);
}

void manage_pdu_list(NFAPI_CRC_INDICATION_PDU_T* pdus, size_t n, const int* user_list, size_t user_count,
                     double accuracy_factor, double frequency_factor, ManagedPDU** managed_pdus,
                     size_t* max_weighted_sum_index, double* metrics) {
    *metrics = 0.0;
    *max_weighted_sum_index = -1;
    size_t valid_count = 0, invalid_count = 0;

    if (!managed_pdus || !pdus) return;

    ManagedPDU* active_pdus = (ManagedPDU*)calloc(n, sizeof(ManagedPDU));
    if (!active_pdus) {
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }

    time_t current_time = time(NULL);
    for (size_t i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &pdus[i];
        if (!validate_RNTI(pdu->RNTI, user_list, user_count)) {
            invalid_count++;
            continue;
        }

        valid_count++;

        // Reuse or initialize structure
        int found = 0;
        for (size_t j = 0; j < n; ++j) {
            if (active_pdus[j].pdu.RNTI == pdu->RNTI) {
                active_pdus[j].timestamp = current_time;
                active_pdus[j].frequency++;
                found = 1;
                break;
            }
        }

        if (!found && valid_count <= n) {
            ManagedPDU* new_pdu = &active_pdus[valid_count - 1];
            new_pdu->pdu = *pdu;
            new_pdu->timestamp = current_time;
            new_pdu->frequency = 1;
        }

        double weighted_sum = compute_weighted_sum(pdu, accuracy_factor, frequency_factor);
        if (*max_weighted_sum_index == -1 || weighted_sum > compute_weighted_sum(&active_pdus[*max_weighted_sum_index].pdu,
                                                                                 accuracy_factor, frequency_factor)) {
            *max_weighted_sum_index = i;
        }
    }

    *metrics = (double)valid_count / n;
    *managed_pdus = active_pdus;

    printf("Valid structures processed: %zu\n", valid_count);
    printf("Invalid structures processed: %zu\n", invalid_count);

    free(active_pdus);
}

int main() {
    const size_t N = 1000;
    NFAPI_CRC_INDICATION_PDU_T pdus[N];

    // Initialize pdus with random values for demonstration
    srand(time(NULL));
    for (size_t i = 0; i < N; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = rand() % 100;
        pdus[i].RNTI = rand() % 100;
        pdus[i].CRC_INDICATION_REL8_TAG = rand() & 1;
        pdus[i].CRCFLAG = rand() & 1;
    }

    const int user_list[] = {10, 20, 30}; // Example valid RNTIs
    size_t user_count = sizeof(user_list) / sizeof(user_list[0]);

    ManagedPDU* managed_pdus = NULL;
    size_t max_weighted_sum_index = -1;
    double metrics = 0.0;

    manage_pdu_list(pdus, N, user_list, user_count, 0.5, 0.5, &managed_pdus, &max_weighted_sum_index, &metrics);

    if (max_weighted_sum_index != -1) {
        printf("Max weighted sum index: %zu\n", max_weighted_sum_index);
    } else {
        printf("No valid structures found.\n");
    }

    return 0;
}
