['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>

#define MAX_STRUCTURES 10000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Thread-local storage for maintaining state
__thread uint32_t thread_local_crcflags[MAX_STRUCTURES];
__thread size_t thread_local_count = 0;

// External logging function prototype
void log_info(const char *message);

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu_list;
    size_t count;
} NFAPI_CRC_INDICATION_LIST_T;

NFAPI_CRC_INDICATION_LIST_T create_nfa_crc_indication_pdu_list(size_t n) {
    if (n > MAX_STRUCTURES) {
        log_info("Error: Requested number exceeds maximum allowed structures.");
        return (NFAPI_CRC_INDICATION_LIST_T){NULL, 0};
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu_list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        log_info("Error: Memory allocation failed.");
        return (NFAPI_CRC_INDICATION_LIST_T){NULL, 0};
    }

    // Initialize thread-local storage for CRCFLAG uniqueness
    for (size_t i = 0; i < n; ++i) {
        thread_local_crcflags[i] = UINT32_MAX;
    }
    thread_local_count = 0;

    time_t start_time = time(NULL);

    for (size_t i = 0; i < n; ++i) {
        pdu_list[i].RX_UE_INFORMATION_TAG = rand() % UINT32_MAX;
        pdu_list[i].RNTI = rand() % UINT16_MAX;
        pdu_list[i].CRC_INDICATION_REL8_TAG = rand() % 256;

        uint8_t crcflag;
        do {
            crcflag = rand() % 256;
        } while (!is_unique_crcflag(crcflag));

        pdu_list[i].CRCFLAG = crcflag;
    }

    time_t end_time = time(NULL);
    log_info("NFAPI_CRC_INDICATION_PDU_T structures created successfully.");
    log_info("Number of structures: %zu", n);
    log_info("Processing time: %ld seconds", difftime(end_time, start_time));

    return (NFAPI_CRC_INDICATION_LIST_T){pdu_list, n};
}

int is_unique_crcflag(uint8_t crcflag) {
    for (size_t i = 0; i < thread_local_count; ++i) {
        if (thread_local_crcflags[i] == crcflag) {
            return 0;
        }
    }

    // Mark this CRCFLAG as used
    thread_local_crcflags[thread_local_count++] = crcflag;
    return 1;
}

void log_info(const char *message) {
    printf("%s\n", message); // Placeholder for actual logging system integration
}
