```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_L1_FRAMES 10
#define MIN_CQI 0
#define MAX_CQI 15

typedef struct {
    int qpsk_modulation_tag;
} QPSK_MODULATION_TAG_T;

typedef struct {
    int cqi; // Channel Quality Indicator
    QPSK_MODULATION_TAG_T modulation_tag;
} L1_FRAME_T;

typedef struct {
    size_t num_l1_frames;
    L1_FRAME_T *l1_frames;
} RX_FRAME_INFO_T;

typedef struct {
    RX_FRAME_INFO_T frame_info;
} NFAPI_RX_FRAME_PDU_T;

// Error codes
#define SUCCESS 0
#define MEMORY_ALLOCATION_FAILURE -1

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

NFAPI_RX_FRAME_PDU_T* initialize_nfa_rx_frame_pdu(int num_pdus) {
    if (num_pdus <= 0) return NULL;

    NFAPI_RX_FRAME_PDU_T *pdus = malloc(num_pdus * sizeof(NFAPI_RX_FRAME_PDU_T));
    if (!pdus) return (NFAPI_RX_FRAME_PDU_T*)MEMORY_ALLOCATION_FAILURE;

    for (int i = 0; i < num_pdus; ++i) {
        pthread_mutex_lock(&lock);

        // Simulating varying load conditions
        size_t num_l1_frames = rand() % (MAX_L1_FRAMES + 1);

        pdus[i].frame_info.num_l1_frames = num_l1_frames;
        pdus[i].frame_info.l1_frames = malloc(num_l1_frames * sizeof(L1_FRAME_T));

        if (!pdus[i].frame_info.l1_frames) {
            free(pdus);
            return (NFAPI_RX_FRAME_PDU_T*)MEMORY_ALLOCATION_FAILURE;
        }

        for (size_t j = 0; j < num_l1_frames; ++j) {
            pdus[i].frame_info.l1_frames[j].cqi = rand() % (MAX_CQI - MIN_CQI + 1) + MIN_CQI;
            pdus[i].frame_info.l1_frames[j].modulation_tag.qpsk_modulation_tag = j; // Example tag
        }

        pthread_mutex_unlock(&lock);
    }

    return pdus;
}

void cleanup_nfa_rx_frame_pdu(NFAPI_RX_FRAME_PDU_T *pdus, int num_pdus) {
    if (!pdus) return;

    for (int i = 0; i < num_pdus; ++i) {
        free(pdus[i].frame_info.l1_frames);
    }

    free(pdus);
}

int main() {
    int num_pdus = 5;
    NFAPI_RX_FRAME_PDU_T *pdus = initialize_nfa_rx_frame_pdu(num_pdus);

    if (pdus == (NFAPI_RX_FRAME_PDU_T*)MEMORY_ALLOCATION_FAILURE) {
        fprintf(stderr, "Memory allocation failed.\n");
        return MEMORY_ALLOCATION_FAILURE;
    }

    // Further processing...

    cleanup_nfa_rx_frame_pdu(pdus, num_pdus);
    pthread_mutex_destroy(&lock);

    return 0;
}
