#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    unsigned int LTE_RRC_CU_MESSAGE_ID;
    unsigned int UE_ID;
    char CIPHERING_KEY[16];
    unsigned short KEY_SEQUENCE_COUNTER;
} LTE_RRC_CU_MESSAGE;

// Function declarations
void processNetworkMessages(unsigned int numNFAPIDescriptors, unsigned int numLTEStructures);
void calculateStatistics();

int main() {
    // Example usage of the functions
    processNetworkMessages(10, 5); // Example parameters
    calculateStatistics();
    return 0;
}

void processNetworkMessages(unsigned int numNFAPIDescriptors, unsigned int numLTEStructures) {
    NFAPI_CRC_INDICATION_PDU_T *nfaArray = (NFAPI_CRC_INDICATION_PDU_T *)malloc(numNFAPIDescriptors * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfaArray) {
        fprintf(stderr, "Memory allocation failed for NFAPI array\n");
        return;
    }

    LTE_RRC_CU_MESSAGE *lteArray = (LTE_RRC_CU_MESSAGE *)malloc(numLTEStructures * sizeof(LTE_RRC_CU_MESSAGE));
    if (!lteArray) {
        free(nfaArray);
        fprintf(stderr, "Memory allocation failed for LTE array\n");
        return;
    }

    // Initialize NFAPI_CRC_INDICATION_PDU_T structures
    for (unsigned int i = 0; i < numNFAPIDescriptors; ++i) {
        nfaArray[i].RX_UE_INFORMATION_TAG = rand() % 10000 + 1; // Random example value
        nfaArray[i].RNTI = rand() % 10000 + 1;                   // Random example value
        nfaArray[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1; // Randomly set CRCFLAG to 0 or 1
    }

    // Initialize LTE_RRC_CU_MESSAGE structures with unique UE_IDs and other values
    for (unsigned int i = 0; i < numLTEStructures; ++i) {
        lteArray[i].LTE_RRC_CU_MESSAGE_ID = i + 1;
        lteArray[i].UE_ID = rand() % 10000 + 1;
        sprintf(lteArray[i].CIPHERING_KEY, "KEY%04u", i); // Example key format
        lteArray[i].KEY_SEQUENCE_COUNTER = rand() % 65536;  // Random example value

        // Ensure unique UE_IDs within this function call
        for (unsigned int j = 0; j < i; ++j) {
            while (lteArray[i].UE_ID == lteArray[j].UE_ID) {
                lteArray[i].UE_ID = rand() % 10000 + 1;
            }
        }
    }

    // Free allocated memory
    free(nfaArray);
    free(lteArray);
}

void calculateStatistics() {
    int count;
    if (scanf("%d", &count) != 1 || count <= 0) {
        fprintf(stderr, "Invalid input for number of values\n");
        return;
    }

    double *values = (double *)malloc(count * sizeof(double));
    if (!values) {
        fprintf(stderr, "Memory allocation failed for value array\n");
        return;
    }

    // Read the floating-point numbers
    printf("Enter %d floating-point numbers:\n", count);
    for (int i = 0; i < count; ++i) {
        if (scanf("%lf", &values[i]) != 1) {
            fprintf(stderr, "Invalid input encountered\n");
            free(values);
            return;
        }
    }

    // Calculate statistics
    double sum = 0.0, mean, variance = 0.0, minVal = values[0], maxVal = values[0];
    for (int i = 0; i < count; ++i) {
        sum += values[i];
        if (values[i] < minVal) minVal = values[i];
        if (values[i] > maxVal) maxVal = values[i];
    }
    mean = sum / count;

    // Calculate variance
    for (int i = 0; i < count; ++i) {
        variance += (values[i] - mean) * (values[i] - mean);
    }
    variance /= count;

    printf("Mean: %f\n", mean);
    printf("Variance: %f\n", variance);
    printf("Minimum: %f\n", minVal);
    printf("Maximum: %f\n", maxVal);

    free(values);
}
