    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

#define MEMORY_ALLOCATION_ERROR NULL

// Function to dynamically allocate memory for the linked list
NFAPI_CRC_INDICATION_PDU_T* create_linked_list(int N) {
    if (N <= 0) return MEMORY_ALLOCATION_ERROR;

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    NFAPI_CRC_INDICATION_PDU_T *head = NULL, **current = &head;

    for (int i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) {
            pthread_mutex_unlock(&mutex);
            while (head != NULL) {
                NFAPI_CRC_INDICATION_PDU_T *temp = head;
                head = head->next;
                free(temp);
            }
            return MEMORY_ALLOCATION_ERROR;
        }

        // Randomly set CRCFLAG and other fields
        new_node->ue_info_tag = rand() % 1000;       // Example random value
        new_node->rnti = rand() % 10000;             // Example random value
        new_node->crc_ind_rel8.CRCFLAG = rand() % 2; // Random CRC flag (0 or 1)

        new_node->next = NULL;
        *current = new_node;
        current = &new_node->next;
    }

    pthread_mutex_unlock(&mutex);
    return head;
}

// Function to free all allocated memory
void free_linked_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T *current, *temp;

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    current = head;
    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&mutex);
}

// Example usage
int main() {
    int N = 5; // Example number of nodes

    NFAPI_CRC_INDICATION_PDU_T* list = create_linked_list(N);

    if (list == MEMORY_ALLOCATION_ERROR) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    free_linked_list(list);
    return EXIT_SUCCESS;
}
