// Function to perform DNS resolution with retries
int resolve_hostname(const char* hostname, u_char* ip_array) {
    struct hostent *host = NULL;
    int attempts = 0;

    while (attempts < MAX_RETRIES && !(host = gethostbyname(hostname))) {
        attempts++;
        fprintf(stderr, "DNS resolution failed for %s. Attempt: %d\n", hostname, attempts);
        sleep(1); // Simple backoff strategy
    }

    if (!host) {
        fprintf(stderr, "Failed to resolve DNS after %d attempts.\n", MAX_RETRIES);
        return -1;
    }

    struct in_addr *addr_list = (struct in_addr*) host->h_addr_list[0];
    memcpy(ip_array, &addr_list->s_addr, sizeof(u_char) * 4);
    return 0;
}

// Function to create and populate NFAPI_CRC_INDICATION_PDU_T list
NFAPI_CRC_INDICATION_PDU_T* create_nfa_pdi_list(size_t num_pdus, char** hostnames, size_t hostname_count, u_char* ip_storage) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_t threads[hostname_count];
    NFAPI_CRC_INDICATION_PDU_T *nfa_pdi_list = malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!nfa_pdi_list) {
        fprintf(stderr, "Memory allocation failed for NFAPI_CRC_INDICATION_PDU_T list.\n");
        return NULL;
    }

    for (size_t i = 0; i < num_pdus; ++i) {
        nfa_pdi_list[i].rx_ue_information_tag.RNTI = rand() % UINT16_MAX; // Example randomization
        nfa_pdi_list[i].rnti = rand() % UINT16_MAX;
        nfa_pdi_list[i].crc_indication_rel8_tag.CRCFLAG = (rand() % 2) ? 1 : 0;

        if (hostname_count > i) {
            pthread_create(&threads[i], NULL, (void *(*)(void *)) resolve_hostname, hostnames[i]);
        }
    }

    for (size_t i = 0; i < hostname_count && i < num_pdus; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Free resources
    free(nfa_pdi_list);
    pthread_mutex_destroy(&mutex);

    return nfa_pdi_list;
}

int main() {
    size_t num_pdus = 10;
    char *hostnames[] = {"example.com", "anotherdomain.org"};
    size_t hostname_count = sizeof(hostnames) / sizeof(hostnames[0]);
    u_char ip_storage[hostname_count * 4];

    NFAPI_CRC_INDICATION_PDU_T* nfa_pdi_list = create_nfa_pdi_list(num_pdus, hostnames, hostname_count, ip_storage);
    if (nfa_pdi_list) {
        free(nfa_pdi_list); // Free allocated list
    }

    return 0;
}
