#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define structures based on assumed types from task description
typedef struct {
    uint8_t RX_UE_INFORMATION_TAG;
    // Add other necessary fields...
} RX_UE_INFORMATION_TAG_T;

typedef struct {
    uint16_t RNTI;
    // Add other necessary fields...
} CRC_INDICATION_REL8_TAG_T;

typedef struct {
    uint8_t CRCFLAG;  // Assuming it's a flag for CRC indication
    // Add other necessary fields...
} NFAPI_CRC_INDICATION_PDU_T;

// Node structure for the linked list
typedef struct ListNode {
    RX_UE_INFORMATION_TAG_T rxUeInfoTag;
    uint16_t rnti;
    NFAPI_CRC_INDICATION_PDU_T crcIndicationRel8Tag;
    struct ListNode* next;
} ListNode;

#define MEMORY_POOL_SIZE 50 * 1024 * 1024 // 50MB
#define MAX_NODES_PER_LIST 10000

typedef struct {
    ListNode* head;
    size_t node_count;
    pthread_mutex_t lock;
    char* memory_pool;
    size_t pool_size;
    size_t current_usage;
} LinkedList;

// Error indicator for allocation failures
#define ERROR_ALLOCATION -1

// Function to create a new linked list with initial configuration
LinkedList* create_linked_list(size_t max_nodes, size_t memory_pool_size) {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = NULL;
    list->node_count = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->memory_pool = (char*)malloc(memory_pool_size);
    if (!list->memory_pool) {
        free(list);
        return NULL;
    }
    list->pool_size = memory_pool_size;
    list->current_usage = 0;

    return list;
}

// Function to add a node to the linked list
int add_node(LinkedList* list, RX_UE_INFORMATION_TAG_T rxUeInfoTag, uint16_t rnti) {
    if (list->node_count >= MAX_NODES_PER_LIST) return ERROR_ALLOCATION;

    pthread_mutex_lock(&list->lock);

    // Validate RNTI and allocate memory for new node
    if (rnti < 0 || rnti > 65535) {
        printf("Invalid RNTI: %u\n", rnti);
        pthread_mutex_unlock(&list->lock);
        return ERROR_ALLOCATION;
    }

    size_t required_memory = sizeof(ListNode);
    if ((list->current_usage + required_memory) > list->pool_size) {
        pthread_mutex_unlock(&list->lock);
        return ERROR_ALLOCATION;  // Not enough memory
    }

    ListNode* new_node = (ListNode*)(list->memory_pool + list->current_usage);
    list->current_usage += required_memory;

    new_node->rxUeInfoTag = rxUeInfoTag;
    new_node->rnti = rnti;
    new_node->crcIndicationRel8Tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    new_node->next = list->head;
    list->head = new_node;
    list->node_count++;

    pthread_mutex_unlock(&list->lock);

    return 0;  // Success
}

// Function to free all allocated memory for the linked list
void free_linked_list(LinkedList* list) {
    if (!list) return;

    ListNode* current = list->head;
    while (current) {
        ListNode* next_node = current->next;
        current = next_node;  // Freeing is implicit as we use a pre-allocated memory pool
    }

    pthread_mutex_destroy(&list->lock);
    free(list->memory_pool);
    free(list);
}

// Example usage and testing
int main() {
    LinkedList* list = create_linked_list(MAX_NODES_PER_LIST, MEMORY_POOL_SIZE);
    if (!list) {
        printf("Failed to create linked list.\n");
        return -1;
    }

    RX_UE_INFORMATION_TAG_T rxUeInfoTag = { .RX_UE_INFORMATION_TAG = 0x01 }; // Example tag
    for (int i = 0; i < 100; ++i) {
        if (add_node(list, rxUeInfoTag, i) == ERROR_ALLOCATION) {
            printf("Failed to add node %d.\n", i);
            break;
        }
    }

    free_linked_list(list);

    return 0;
}
