#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_RETRIES 5
#define BACKOFF_BASE_MS 100

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = NULL;
    list->count = 0;
    if (pthread_mutex_init(&list->lock, NULL) != 0) {
        free(list);
        return NULL;
    }
    return list;
}

NFAPI_CRC_INDICATION_PDU_T generate_random_pdu() {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    srand((unsigned int)time(NULL));
    pdu.RX_UE_INFORMATION_TAG = rand();
    pdu.RNTI = rand();
    pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set to 0 or 1
    return pdu;
}

int add_node(LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Allocation failure
    }

    new_node->data = generate_random_pdu();
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int initialize_list(LinkedList* list, size_t N) {
    if (!list) return -1;

    for (size_t i = 0; i < N; ++i) {
        int result = add_node(list);
        if (result != 0) {
            // Handle allocation failure
            while (list->count > 0) {
                Node* temp = list->head;
                list->head = list->head->next;
                free(temp);
                list->count--;
            }
            pthread_mutex_destroy(&list->lock);
            free(list);
            return -1;
        }
    }
    return 0;
}

void log_structure_details(const LinkedList* list, const char* filename) {
    static FILE* file = NULL;
    static pthread_once_t once_control = PTHREAD_ONCE_INIT;

    pthread_once(&once_control, ^{
        file = fopen(filename, "a");
        if (!file) {
            fprintf(stderr, "Failed to open log file.\n");
            exit(EXIT_FAILURE);
        }
    });

    pthread_mutex_lock((pthread_mutex_t*)&file);

    for (Node* curr = list->head; curr != NULL; curr = curr->next) {
        fprintf(file, "RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n",
                curr->data.RX_UE_INFORMATION_TAG,
                curr->data.RNTI,
                curr->data.CRC_INDICATION_REL8_TAG.CRCFLAG);
    }

    pthread_mutex_unlock((pthread_mutex_t*)&file);
}

void cleanup_list(LinkedList* list) {
    if (!list) return;

    while (list->count > 0) {
        Node* temp = list->head;
        list->head = list->head->next;
        free(temp);
        list->count--;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);

    static FILE* file = NULL;
    if (file) {
        fclose(file);
        file = NULL;
    }
}

int main() {
    size_t N = 10; // Example: Set at runtime
    LinkedList* list = create_linked_list();

    if (!list || initialize_list(list, N) != 0) {
        fprintf(stderr, "Failed to initialize linked list.\n");
        return EXIT_FAILURE;
    }

    log_structure_details(list, "log.txt");

    cleanup_list(list);
    return EXIT_SUCCESS;
}
