#include <string.h>
#include <time.h>

#define MAX_MEMORY_USAGE 1048576 // Maximum memory usage in bytes (1MB)
#define PERFORMANCE_MONITORING_ENABLED 1

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t count;
    size_t duplicates;
} ResultStats;

static clock_t start_time = 0;
static clock_t end_time = 0;

void monitor_performance() {
    if (PERFORMANCE_MONITORING_ENABLED) {
        if (!start_time) {
            start_time = clock();
        }
        end_time = clock();
    }
}

int check_memory_usage(size_t current_size) {
    return current_size > MAX_MEMORY_USAGE;
}

ResultStats *create_nfa_crc_indications_list(int N) {
    ResultStats *result_stats = malloc(sizeof(ResultStats));
    if (!result_stats) {
        fprintf(stderr, "Memory allocation for result statistics failed\n");
        return NULL;
    }

    result_stats->data = NULL;
    result_stats->count = 0;
    result_stats->duplicates = 0;

    uint16_t *rnti_tracker = malloc(N * sizeof(uint16_t));
    if (!rnti_tracker) {
        fprintf(stderr, "Memory allocation for RNTI tracker failed\n");
        free(result_stats);
        return NULL;
    }

    monitor_performance();

    size_t current_size = 0;

    for (int i = 0; i < N; ++i) {
        // Check if we can allocate more memory
        if (check_memory_usage(current_size)) {
            fprintf(stderr, "Exceeded maximum memory usage\n");
            break;
        }

        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(result_stats->data,
                                                       sizeof(NFAPI_CRC_INDICATION_PDU_T) * (result_stats->count + 1));
        if (!new_data) {
            fprintf(stderr, "Memory allocation failed during reallocation\n");
            break;
        }

        result_stats->data = new_data;
        NFAPI_CRC_INDICATION_PDU_T *current_entry = &result_stats->data[result_stats->count];

        // Assign random values
        current_entry->RX_UE_INFORMATION_TAG = rand();
        uint16_t rnti_value = rand() % 0xFFFF;

        int is_duplicate = 0;
        for (size_t j = 0; j < result_stats->count; ++j) {
            if (result_stats->data[j].RNTI == rnti_value) {
                is_duplicate = 1;
                break;
            }
        }

        if (is_duplicate) {
            fprintf(stderr, "Duplicate RNTI detected: %u\n", rnti_value);
            result_stats->duplicates++;
            continue; // Skip adding this entry
        } else {
            current_entry->RNTI = rnti_value;
            memcpy(rnti_tracker + result_stats->count, &rnti_value, sizeof(uint16_t));
        }

        current_entry->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        // Update memory usage tracking
        current_size += sizeof(NFAPI_CRC_INDICATION_PDU_T);

        ++(result_stats->count);
    }

    free(rnti_tracker);

    monitor_performance();

    printf("Execution time: %.2f seconds\n", (double)(end_time - start_time) / CLOCKS_PER_SEC);

    return result_stats;
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    int N = 1000; // Example input
    ResultStats *result = create_nfa_crc_indications_list(N);

    if (result) {
        printf("Successfully added %zu entries, encountered %zu duplicates\n", result->count, result->duplicates);

        free(result->data);
        free(result);
    }

    return 0;
}
