    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

bool is_rnti_unique(unsigned long rnti, unsigned long *rntis, int count) {
    for (int i = 0; i < count; ++i) {
        if (rntis[i] == rnti) return false;
    }
    return true;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_nfa_cri_indication_pdu(int N, size_t MAX_SIZE, int *error_code) {
    if (MAX_SIZE < sizeof(NFAPI_CRC_INDICATION_PDU_T) * N) {
        *error_code = 1; // Insufficient maximum size
        return NULL;
    }

    unsigned long rntis[N];
    bool allocation_success = true;

    NFAPI_CRC_INDICATION_PDU_T* pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);

    if (!pdu_array) {
        *error_code = 2; // Memory allocation failed
        return NULL;
    }

    srand((unsigned int)time(NULL));

    for (int i = 0; i < N; ++i) {
        pdu_array[i].rx_ue_information_tag.example_field = rand();  // Example initialization

        do {
            pdu_array[i].rnti.rnti_value = rand();
        } while (!is_rnti_unique(pdu_array[i].rnti.rnti_value, rntis, i));

        rntis[i] = pdu_array[i].rnti.rnti_value;

        pdu_array[i].crc_indication_rel8_tag.CRCFLAG = rand() % 2; // Randomly set CRC flag
    }

    *error_code = 0; // Success

