#define MAX_PAYLOAD_SIZE 1024

typedef struct {
    int session_id;
    int sequence_number;
    char payload[MAX_PAYLOAD_SIZE];
} PDU;

typedef struct Node {
    PDU pdu;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    pthread_mutex_t lock;
} PDUList;

// Function prototypes
void init_pdu_list(PDUList* list);
int add_pdu(PDUList* list, const PDU* pdu);
PDU* get_pdu_by_id_and_seq(PDUList* list, int session_id, int sequence_number);
int remove_pdu(PDUList* list, int session_id, int sequence_number);
void free_pdu_list(PDUList* list);

// Logging service stub
void log_transaction(const char* message) {
    // External logging implementation
}

void log_error(const char* message) {
    // External error logging implementation
}

// Initialize the PDU list
void init_pdu_list(PDUList* list) {
    if (!list) return;
    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

// Add a PDU to the list
int add_pdu(PDUList* list, const PDU* pdu) {
    if (!list || !pdu) {
        log_error("Invalid arguments provided.");
        return -1;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_error("Out of memory while allocating PDU node.");
        return -1;
    }

    memcpy(&new_node->pdu, pdu, sizeof(PDU));

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    list->count++;
    pthread_mutex_unlock(&list->lock);

    log_transaction("PDU added successfully.");
    return 0;
}

// Retrieve a PDU by session ID and sequence number
PDU* get_pdu_by_id_and_seq(PDUList* list, int session_id, int sequence_number) {
    if (!list) return NULL;

    pthread_mutex_lock(&list->lock);
    Node* current = list->head;

    while (current) {
        if (current->pdu.session_id == session_id && 
            current->pdu.sequence_number == sequence_number) {
            pthread_mutex_unlock(&list->lock);
            log_transaction("PDU retrieved successfully.");
            return &current->pdu;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    log_error("PDU not found.");
    return NULL;
}

// Remove a PDU by session ID and sequence number
int remove_pdu(PDUList* list, int session_id, int sequence_number) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);
    Node *current = list->head, *prev = NULL;

    while (current) {
        if (current->pdu.session_id == session_id && 
            current->pdu.sequence_number == sequence_number) {

            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }

            free(current);
            list->count--;
            pthread_mutex_unlock(&list->lock);

            log_transaction("PDU removed successfully.");
            return 0;
        }

        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    log_error("PDU not found for removal.");
    return -1;
}

// Free the entire PDU list
void free_pdu_list(PDUList* list) {
    if (!list) return;

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    log_transaction("PDU list freed successfully.");
}
```']

