#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_RNTI 65535

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Mutex for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Memory pool structure
typedef struct {
    size_t block_size;
    void* memory_pool;
    size_t total_blocks;
    size_t used_blocks;
} MemoryPool;

MemoryPool create_memory_pool(size_t block_size, size_t total_blocks) {
    MemoryPool pool;
    pool.block_size = block_size;
    pool.total_blocks = total_blocks;
    pool.memory_pool = malloc(block_size * total_blocks);
    if (!pool.memory_pool) {
        fprintf(stderr, "Failed to allocate memory for the pool\n");
        exit(EXIT_FAILURE);
    }
    pool.used_blocks = 0;
    return pool;
}

void* allocate_from_pool(MemoryPool* pool) {
    pthread_mutex_lock(&lock);
    if (pool->used_blocks >= pool->total_blocks) {
        pthread_mutex_unlock(&lock);
        fprintf(stderr, "Memory pool exhausted\n");
        return NULL;
    }
    void* block = ((char*)pool.memory_pool) + (pool->used_blocks * pool->block_size);
    pool->used_blocks++;
    pthread_mutex_unlock(&lock);
    return block;
}

void free_memory_pool(MemoryPool* pool) {
    if (pool->memory_pool) {
        free(pool->memory_pool);
    }
}

int populate_crc_indications(int n, NFAPI_CRC_INDICATION_PDU_T** result_list) {
    pthread_mutex_lock(&lock);

    // Create a memory pool for NFAPI_CRC_INDICATION_PDU_T structures
    MemoryPool pool = create_memory_pool(sizeof(NFAPI_CRC_INDICATION_PDU_T), n);
    *result_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!*result_list) {
        fprintf(stderr, "Failed to allocate memory for result list\n");
        pthread_mutex_unlock(&lock);
        free_memory_pool(&pool);
        return -1;
    }

    int success_count = 0;
    srand((unsigned int)time(NULL));

    for (int i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)allocate_from_pool(&pool);

        if (!pdu) {
            fprintf(stderr, "Allocation failed for index %d\n", i);
            break;
        }

        pdu->RX_UE_INFORMATION_TAG = rand() & 0xFF; // Example tag
        unsigned short rnti = (unsigned short)(rand() % (MAX_RNTI + 1));

        if (rnti > MAX_RNTI) {
            fprintf(stderr, "Invalid RNTI value: %u\n", rnti);
            continue;
        }

        pdu->RNTI = rnti;
        pdu->CRC_INDICATION_REL8_TAG = rand() & 0xFF; // Example tag
        pdu->CRCFLAG = rand() & 1; // Random CRC flag

        (*result_list)[success_count++] = *pdu;
    }

    free_memory_pool(&pool);
    pthread_mutex_unlock(&lock);

    return success_count;
}

int main() {
    int n = 10; // Number of structures to create
    NFAPI_CRC_INDICATION_PDU_T* list = NULL;

    int created_count = populate_crc_indications(n, &list);

    if (created_count > 0) {
        printf("Successfully created %d NFAPI_CRC_INDICATION_PDU_T structures.\n", created_count);
    } else {
        printf("Failed to create any structures.\n");
    }

    free(list); // Free the result list after use
    return 0;
}
```

### Key Points:

- **Memory Pool**: A memory pool is used to manage allocations efficiently, reducing fragmentation and allocation overhead.

- **Thread Safety**: `pthread_mutex_t` is used for synchronization to ensure thread safety when accessing shared resources.

- **Randomization**: Random values are generated for tags and flags using `rand()`, seeded with the current time for variability.

- **Error Handling**: The function logs errors for memory allocation failures and invalid RNTI values, providing meaningful feedback.

- **Scalability and Performance**: By reusing a fixed-size pool of preallocated memory blocks, the implementation is optimized for high-throughput scenarios.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct {
    // Assuming structure members; adjust as necessary
    int data;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

// Function prototypes
DynamicArray* create_dynamic_array(size_t initial_capacity);
bool add_pdu(DynamicArray* dyn_array, const NFAPI_CRC_INDICATION_PDU_T* pdu);
bool remove_pdu(DynamicArray* dyn_array, size_t index);
void iterate_over_pdus(const DynamicArray* dyn_array, void (*func)(const NFAPI_CRC_INDICATION_PDU_T*));
void free_dynamic_array(DynamicArray* dyn_array);

// Function implementations
DynamicArray* create_dynamic_array(size_t initial_capacity) {
    if (initial_capacity == 0) return NULL;

    DynamicArray* dyn_array = malloc(sizeof(DynamicArray));
    if (!dyn_array) return NULL;

    dyn_array->array = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!dyn_array->array) {
        free(dyn_array);
        return NULL;
    }

    dyn_array->capacity = initial_capacity;
    dyn_array->count = 0;
    pthread_mutex_init(&dyn_array->lock, NULL);

    return dyn_array;
}

bool add_pdu(DynamicArray* dyn_array, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!dyn_array || !pdu) return false;

    pthread_mutex_lock(&dyn_array->lock);

    if (dyn_array->count == dyn_array->capacity) {
        size_t new_capacity = dyn_array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(dyn_array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&dyn_array->lock);
            return false;
        }
        dyn_array->array = new_array;
        dyn_array->capacity = new_capacity;
    }

    dyn_array->array[dyn_array->count] = *pdu;
    ++dyn_array->count;

    pthread_mutex_unlock(&dyn_array->lock);
    return true;
}

bool remove_pdu(DynamicArray* dyn_array, size_t index) {
    if (!dyn_array || index >= dyn_array->count) return false;

    pthread_mutex_lock(&dyn_array->lock);

    for (size_t i = index; i < dyn_array->count - 1; ++i) {
        dyn_array->array[i] = dyn_array->array[i + 1];
    }
    --dyn_array->count;

    pthread_mutex_unlock(&dyn_array->lock);
    return true;
}

void iterate_over_pdus(const DynamicArray* dyn_array, void (*func)(const NFAPI_CRC_INDICATION_PDU_T*)) {
    if (!dyn_array || !func) return;

    pthread_mutex_lock((pthread_mutex_t*)&dyn_array->lock);

    for (size_t i = 0; i < dyn_array->count; ++i) {
        func(&dyn_array->array[i]);
    }

    pthread_mutex_unlock((pthread_mutex_t*)&dyn_array->lock);
}

void free_dynamic_array(DynamicArray* dyn_array) {
    if (!dyn_array) return;

    pthread_mutex_lock(&dyn_array->lock);

    free(dyn_array->array);
    pthread_mutex_unlock(&dyn_array->lock);

    pthread_mutex_destroy(&dyn_array->lock);
    free(dyn_array);
}
```

