#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_SIZE 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

// Helper function to initialize the array structure
void init_array(DynamicArray *dynamicArray, size_t initialCapacity) {
    dynamicArray->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    dynamicArray->count = 0;
    dynamicArray->capacity = initialCapacity;
    pthread_mutex_init(&dynamicArray->lock, NULL);
}

// Helper function to free the array
void free_array(DynamicArray *dynamicArray) {
    if (dynamicArray->array) {
        free(dynamicArray->array);
    }
    pthread_mutex_destroy(&dynamicArray->lock);
}

// Helper function for resizing the array
int resize_array(DynamicArray *dynamicArray, size_t newCapacity) {
    NFAPI_CRC_INDICATION_PDU_T *newArray = (NFAPI_CRC_INDICATION_PDU_T *)realloc(dynamicArray->array, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newArray) {
        return -1;
    }
    dynamicArray->array = newArray;
    dynamicArray->capacity = newCapacity;
    return 0;
}

// Function to initialize the array with N elements
DynamicArray* initialize_dynamic_array(size_t n) {
    if (n <= 0 || n > MAX_SIZE) {
        fprintf(stderr, "Invalid size requested.\n");
        return NULL;
    }

    DynamicArray *dynamicArray = malloc(sizeof(DynamicArray));
    if (!dynamicArray) {
        fprintf(stderr, "Memory allocation for DynamicArray failed.\n");
        return NULL;
    }

    init_array(dynamicArray, n);

    pthread_mutex_lock(&dynamicArray->lock);
    for (size_t i = 0; i < n; ++i) {
        // Example initialization logic
        dynamicArray->array[i].RX_UE_INFORMATION_TAG = i + 1;
        dynamicArray->array[i].RNTI = i * 2;
        dynamicArray->array[i].CRC_INDICATION_REL8_TAG = i * 3;

        // Check for data consistency (e.g., valid RNTI)
        if (dynamicArray->array[i].RNTI <= 0) {
            fprintf(stderr, "Invalid RNTI encountered. Aborting initialization.\n");
            free_array(dynamicArray);
            free(dynamicArray);
            return NULL;
        }
    }
    dynamicArray->count = n;
    pthread_mutex_unlock(&dynamicArray->lock);

    printf("Array initialized with %zu elements.\n", dynamicArray->count);
    return dynamicArray;
}

// Function to get resource monitoring information
void get_resource_info(DynamicArray *dynamicArray, size_t *totalElements, size_t *maxCapacity, float *utilization) {
    pthread_mutex_lock(&dynamicArray->lock);
    if (totalElements) *totalElements = dynamicArray->count;
    if (maxCapacity) *maxCapacity = dynamicArray->capacity;
    if (utilization) *utilization = ((float)dynamicArray->count / dynamicArray->capacity) * 100.0f;
    pthread_mutex_unlock(&dynamicArray->lock);
}

// Example function to demonstrate resizing
int resize_dynamic_array(DynamicArray *dynamicArray, size_t newSize) {
    if (!dynamicArray || newSize <= 0 || newSize > MAX_SIZE) {
        fprintf(stderr, "Invalid new size.\n");
        return -1;
    }

    pthread_mutex_lock(&dynamicArray->lock);
    if (resize_array(dynamicArray, newSize)) {
        fprintf(stderr, "Resizing failed due to memory allocation error.\n");
        pthread_mutex_unlock(&dynamicArray->lock);
        return -1;
    }
    pthread_mutex_unlock(&dynamicArray->lock);

    printf("Array resized to %zu elements.\n", dynamicArray->capacity);
    return 0;
}

// Example function to free the array
void cleanup_dynamic_array(DynamicArray *dynamicArray) {
    if (dynamicArray) {
        free_array(dynamicArray);
        free(dynamicArray);
    }
}

int main() {
    size_t n = 10;
    DynamicArray *array = initialize_dynamic_array(n);

    if (array) {
        size_t totalElements, maxCapacity;
        float utilization;

        get_resource_info(array, &totalElements, &maxCapacity, &utilization);
        printf("Total Elements: %zu\n", totalElements);
        printf("Max Capacity: %zu\n", maxCapacity);
        printf("Utilization: %.2f%%\n", utilization);

        if (resize_dynamic_array(array, 20) == 0) {
            get_resource_info(array, &totalElements, &maxCapacity, &utilization);
            printf("After resizing:\n");
            printf("Total Elements: %zu\n", totalElements);
            printf("Max Capacity: %zu\n", maxCapacity);
            printf("Utilization: %.2f%%\n", utilization);
        }

        cleanup_dynamic_array(array);
    }

    return 0;
}
