```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <jansson.h> // Use jansson for JSON handling

typedef struct {
    int fftSize;
    int ifftSize;
    char* cyclicPrefixType;  // Assume it's a string like "Normal", "Extended"
} LTEPHY_FFT_CONFIG;

LTEPHY_FFT_CONFIG* initializeFFTConfigs(const char* jsonFilePath, size_t* numConfigs) {
    FILE *file = fopen(jsonFilePath, "rb");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    struct json_error_s error;
    json_t *root = json_loadf(file, 0, &error);
    fclose(file);

    if (!root) {
        fprintf(stderr, "Error parsing JSON: %s\n", error.text);
        return NULL;
    }

    if (!json_is_array(root)) {
        fprintf(stderr, "JSON root is not an array\n");
        json_decref(root);
        return NULL;
    }

    size_t configCount = json_array_size(root);
    LTEPHY_FFT_CONFIG *configs = malloc(configCount * sizeof(LTEPHY_FFT_CONFIG));
    if (!configs) {
        fprintf(stderr, "Memory allocation failed for FFT configurations\n");
        json_decref(root);
        return NULL;
    }

    for (size_t i = 0; i < configCount; ++i) {
        json_t *configObj = json_array_get(root, i);

        if (!json_is_object(configObj)) continue;

        LTEPHY_FFT_CONFIG config;

        // Parse fftSize
        json_t *fftSizeJson = json_object_get(configObj, "fftSize");
        if (json_is_integer(fftSizeJson)) {
            config.fftSize = json_integer_value(fftSizeJson);
        } else {
            fprintf(stderr, "Invalid or missing fftSize\n");
            continue;
        }

        // Parse ifftSize
        json_t *ifftSizeJson = json_object_get(configObj, "ifftSize");
        if (json_is_integer(ifftSizeJson)) {
            config.ifftSize = json_integer_value(ifftSizeJson);
        } else {
            fprintf(stderr, "Invalid or missing ifftSize\n");
            continue;
        }

        // Parse cyclicPrefixType
        json_t *cyclicPrefixJson = json_object_get(configObj, "cyclicPrefixType");
        if (json_is_string(cyclicPrefixJson)) {
            config.cyclicPrefixType = strdup(json_string_value(cyclicPrefixJson));
        } else {
            fprintf(stderr, "Invalid or missing cyclicPrefixType\n");
            continue;
        }

        configs[i] = config;
    }

    *numConfigs = configCount;
    json_decref(root);

    return configs;
}

void freeFFTConfigs(LTEPHY_FFT_CONFIG* configs, size_t numConfigs) {
    if (configs == NULL) return;

    for (size_t i = 0; i < numConfigs; ++i) {
        free(configs[i].cyclicPrefixType);
    }

    free(configs);
}
```

