// Memory pool structure
#define POOL_SIZE 1024 * sizeof(NFAPI_CRC_INDICATION_PDU_T)
char memory_pool[POOL_SIZE];
size_t pool_offset = 0;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond_var = PTHREAD_COND_INITIALIZER;

// Logging function
void log_event(const char* message) {
    // Simple logging mechanism
    printf("%s\n", message);
}

// Allocate memory from the custom memory pool
NFAPI_CRC_INDICATION_PDU_T* allocate_from_pool(size_t size) {
    if (pool_offset + size > POOL_SIZE) {
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T *ptr = (NFAPI_CRC_INDICATION_PDU_T*)(memory_pool + pool_offset);
    pool_offset += size;
    log_event("Allocated memory from pool");
    return ptr;
}

// Initialize the array with random data
