    if (N == 0 || N > MAX_SIZE) {
        log_event("Invalid size, using default");
        N = DEFAULT_SIZE;
    }

    pthread_mutex_lock(&mutex);

    // Allocate memory from the pool
    NFAPI_CRC_INDICATION_PDU_T *arr = allocate_from_pool(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!arr) {
        pthread_mutex_unlock(&mutex);
        log_event("Allocation failed");
        return NULL;
    }

    initialize_array(arr, N);

    // Reset pool offset for demonstration purposes
    pool_offset = 0;

    pthread_mutex_unlock(&mutex);
    return arr;
}

// Function to iterate over the array safely
void iterate_array(NFAPI_CRC_INDICATION_PDU_T* arr, size_t N, int direction) {
    if (!arr) return;

    if (direction == 1) { // Forward
        for (size_t i = 0; i < N; ++i) {
            printf("Index: %zu, RX_UE_INFORMATION_TAG: %u, RNTI: %hu, CRCFLAG: %d\n",
                   i, arr[i].RX_UE_INFORMATION_TAG, arr[i].RNTI, arr[i].CRC_INDICATION_REL8_TAG.CRCFLAG);
        }
    } else if (direction == -1) { // Backward
        for (size_t i = N; i-- > 0;) {
            printf("Index: %zu, RX_UE_INFORMATION_TAG: %u, RNTI: %hu, CRCFLAG: %d\n",
                   i, arr[i].RX_UE_INFORMATION_TAG, arr[i].RNTI, arr[i].CRC_INDICATION_REL8_TAG.CRCFLAG);
        }
    }
}

// Function to free the memory (reset pool offset)
void free_crc_indication_array(NFAPI_CRC_INDICATION_PDU_T* arr) {
    if (!arr) return;

    pthread_mutex_lock(&mutex);

    // Reset pool offset
    pool_offset = 0;
    log_event("Freed memory");

    pthread_mutex_unlock(&mutex);
}

int main() {
    size_t N = 20; // Example size
    NFAPI_CRC_INDICATION_PDU_T* arr = manage_crc_indication_array(N);

    if (arr) {
        iterate_array(arr, N, 1); // Forward iteration
        iterate_array(arr, N, -1); // Backward iteration

        free_crc_indication_array(arr);
    }

    return 0;
}
