typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct Node* next;
} Node;

// Dynamic Array structure with cache mechanism
typedef struct {
    Node* head;
    size_t size;
    size_t capacity;
    uint32_t* crc_cache; // Simple LRU-like cache for CRC results.
    size_t cache_size;
    size_t (*crc_compute)(const NFAPI_CRC_INDICATION_PDU_T*);
} DynamicArray;

// Function prototypes
DynamicArray* create_dynamic_array(size_t initial_capacity, size_t cache_size, size_t (*crc_compute)(const NFAPI_CRC_INDICATION_PDU_T*));
void destroy_dynamic_array(DynamicArray* arr);
int add_pdu(DynamicArray* arr, const NFAPI_CRC_INDICATION_PDU_T* pdu);
int remove_pdu_by_id(DynamicArray* arr, uint32_t id);
void iterate_and_process(DynamicArray* arr, void (*process)(const NFAPI_CRC_INDICATION_PDU_T*));

// Helper functions
static int resize_cache(uint32_t** cache, size_t new_size, const char* operation);

DynamicArray* create_dynamic_array(size_t initial_capacity, size_t cache_size, size_t (*crc_compute)(const NFAPI_CRC_INDICATION_PDU_T*)) {
    DynamicArray* arr = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!arr) return NULL;

    arr->head = NULL;
    arr->size = 0;
    arr->capacity = initial_capacity;
    arr->crc_cache = (uint32_t*)calloc(cache_size, sizeof(uint32_t)); // Simple cache initialization.
    arr->cache_size = cache_size;
    arr->crc_compute = crc_compute;

    return arr;
}

void destroy_dynamic_array(DynamicArray* arr) {
    Node* current = arr->head;
    while (current) {
        Node* next = current->next;
        free(current->pdu.data);
        free(current);
        current = next;
    }
    free(arr->crc_cache);
    free(arr);
}

int add_pdu(DynamicArray* arr, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (arr->size >= arr->capacity)
        return -1; // Capacity exceeded.

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1;

    memcpy(&new_node->pdu, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->next = arr->head;
    arr->head = new_node;
    arr->size++;

    // CRC computation and caching.
    uint32_t crc_value = arr->crc_compute(pdu);
    resize_cache(&arr->crc_cache, arr->cache_size, "add");
    arr->crc_cache[arr->size % arr->cache_size] = crc_value;

    return 0;
}

int remove_pdu_by_id(DynamicArray* arr, uint32_t id) {
    Node *current = arr->head, *prev = NULL;

    while (current) {
        if (current->pdu.id == id) {
            if (prev)
                prev->next = current->next;
            else
                arr->head = current->next;

            free(current->pdu.data);
            free(current);
            arr->size--;

            return 0; // Successfully removed.
        }
        prev = current;
        current = current->next;
    }

    return -1; // Not found.
}

void iterate_and_process(DynamicArray* arr, void (*process)(const NFAPI_CRC_INDICATION_PDU_T*)) {
    Node* current = arr->head;

    while (current) {
        process(&current->pdu);
        current = current->next;
    }
}

// Simple cache resizing mechanism
static int resize_cache(uint32_t** cache, size_t new_size, const char* operation) {
    // This is a placeholder for an LRU or other eviction policy.
    if (operation && strcmp(operation, "add") == 0 && *cache) {
        // For demonstration: just resetting the pointers to simulate eviction
        memset(*cache, 0, new_size * sizeof(uint32_t));
    }
    return 0;
}

