    unsigned int sum = segment->header.source_port + segment->header.dest_port +
                       (segment->header.sequence_number >> 16) + (segment->header.sequence_number & 0xFFFF) +
                       (segment->header.ack_number >> 16) + (segment->header.ack_number & 0xFFFF);
    return (unsigned short)(~sum);
}

