    size_t successful_checks = 0, failed_checks = 0;

    for (size_t i = 0; i < num_segments; ++i) {
        unsigned short checksum = calculate_checksum(&segments[i]);

        if (checksum != segments[i].checksum) {  // Checksum validation
            // External verification during high-load scenarios
            if ((rand() % 100) > 70 && external_checksum_verification(&segments[i])) {
                successful_checks++;
            } else {
                failed_checks++;
            }
        } else {
            successful_checks++;
        }
    }

    printf("Checksum Validation - Successful: %zu, Failed: %zu\n", successful_checks, failed_checks);

    // Free allocated memory
    free(segments);
}

