#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Assuming definitions of structures as follows:
typedef struct {
    int valid;
    // Additional fields...
} RX_UE_INFORMATION_TAG;

typedef struct {
    unsigned long rnti;  // Assume RNTI is an unsigned long for simplicity
    RX_UE_INFORMATION_TAG info_tag;
    uint8_t crc_flag;  // Randomly set CRC flag
} NFAPI_CRC_INDICATION_PDU_T;

// Hash table entry structure
typedef struct HashNode {
    unsigned long rnti;
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct HashNode* next;
} HashNode;

// Global hash table and lock for thread safety
#define TABLE_SIZE 1024
HashNode* hashtable[TABLE_SIZE];
pthread_mutex_t locks[TABLE_SIZE];

// Initialize the hash table and locks
void initialize_hash_table() {
    memset(hashtable, 0, sizeof(hashtable));
    pthread_mutex_init(locks, NULL);
}

// Utility function for hashing RNTI
unsigned int hash_rnti(unsigned long rnti) {
    return (rnti & 0x7FFFFFFF) % TABLE_SIZE;
}

// Randomly generate CRC flag
uint8_t random_crc_flag() {
    return rand() % 2; // Simple binary flag: 0 or 1
}

// Validate RNTI (example validation logic)
int validate_rnti(unsigned long rnti) {
    // Example: ensure RNTI is non-zero
    return rnti != 0;
}

// Add an entry to the hash table
void add_entry(NFAPI_CRC_INDICATION_PDU_T* new_pdu) {
    if (!new_pdu || !validate_rnti(new_pdu->rnti)) {
        fprintf(stderr, "Invalid RNTI or NULL PDU\n");
        return;
    }

    unsigned int index = hash_rnti(new_pdu->rnti);
    pthread_mutex_lock(&locks[index]);

    HashNode* new_node = (HashNode*)malloc(sizeof(HashNode));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&locks[index]);
        return;
    }

    new_node->rnti = new_pdu->rnti;
    memcpy(&(new_node->pdu), new_pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->next = hashtable[index];
    hashtable[index] = new_node;

    pthread_mutex_unlock(&locks[index]);
}

// Remove an entry based on RNTI
void remove_entry_by_rnti(unsigned long rnti) {
    if (!validate_rnti(rnti)) {
        fprintf(stderr, "Invalid RNTI\n");
        return;
    }

    unsigned int index = hash_rnti(rnti);
    pthread_mutex_lock(&locks[index]);

    HashNode *current = hashtable[index], *prev = NULL;

    while (current) {
        if (current->rnti == rnti) {
            if (prev)
                prev->next = current->next;
            else
                hashtable[index] = current->next;

            free(current);
            pthread_mutex_unlock(&locks[index]);
            return;
        }
        prev = current;
        current = current->next;
    }

    fprintf(stderr, "RNTI not found\n");
    pthread_mutex_unlock(&locks[index]);
}

// Update CRC flag for a specific RNTI
void update_crc_flag(unsigned long rnti) {
    if (!validate_rnti(rnti)) {
        fprintf(stderr, "Invalid RNTI\n");
        return;
    }

    unsigned int index = hash_rnti(rnti);
    pthread_mutex_lock(&locks[index]);

    HashNode* current = hashtable[index];

    while (current) {
        if (current->rnti == rnti) {
            current->pdu.crc_flag = random_crc_flag();
            pthread_mutex_unlock(&locks[index]);
            return;
        }
        current = current->next;
    }

    fprintf(stderr, "RNTI not found for CRC update\n");
    pthread_mutex_unlock(&locks[index]);
}

// Clean up resources
void cleanup_hash_table() {
    for (int i = 0; i < TABLE_SIZE; ++i) {
        pthread_mutex_lock(&locks[i]);

        HashNode *current = hashtable[i];
        while (current) {
            HashNode* temp = current;
            current = current->next;
            free(temp);
        }

        pthread_mutex_unlock(&locks[i]);
    }
    pthread_mutex_destroy(locks);
}

// Example usage
int main() {
    initialize_hash_table();

    NFAPI_CRC_INDICATION_PDU_T pdu1 = { .rnti = 12345, .info_tag = {.valid = 1}, .crc_flag = random_crc_flag() };
    add_entry(&pdu1);

    update_crc_flag(12345);
    remove_entry_by_rnti(12345);

    cleanup_hash_table();

    return 0;
}
```

### Key Considerations:

- **Thread Safety**: The use of individual mutexes per hash bucket allows concurrent operations without blocking the entire table.

- **Error Handling**: Checks for invalid RNTI and memory allocation failures are in place with appropriate error messages.

- **Scalability & Performance**: Hashing and linked lists help manage growing numbers of entries. Consider using more sophisticated structures like dynamic arrays or balanced trees if performance bottlenecks arise as load increases.

- **Maintainability**: Functions are modular, with clear responsibilities (e.g., adding, removing, updating). Comments and descriptive names aid readability and future modifications.']

