#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_THREADS 10

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG; // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

// Global memory pool for better performance and reduced fragmentation
#define POOL_SIZE 1024 * 1024 // 1 MB pool size
static void* memory_pool[POOL_SIZE];
static pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;
static int pool_index = 0;

int initialize_memory_pool() {
    for (int i = 0; i < POOL_SIZE; ++i) {
        memory_pool[i] = NULL;
    }
    return 0;
}

void* allocate_from_pool(size_t size) {
    pthread_mutex_lock(&pool_mutex);

    // Find a contiguous block in the pool
    void* ptr = NULL;
    for (int i = 0; i < POOL_SIZE - (size / sizeof(void*)); ++i) {
        if (!memory_pool[i]) {
            ptr = &memory_pool[i];
            int j = 0;
            while (j < size / sizeof(void*) && !memory_pool[i + j]) {
                memory_pool[i + j] = malloc(sizeof(void*));
                j++;
            }
            if (j == size / sizeof(void*)) {
                pool_index += j;
                break;
            } else {
                // Free allocated blocks in case of failure
                for (int k = 0; k < j; ++k) {
                    free(memory_pool[i + k]);
                    memory_pool[i + k] = NULL;
                }
                ptr = NULL;
            }
        }
    }

    pthread_mutex_unlock(&pool_mutex);
    return ptr;
}

void free_memory_pool(void* ptr, size_t size) {
    if (!ptr) return;

    pthread_mutex_lock(&pool_mutex);

    unsigned char* byte_ptr = (unsigned char*)ptr;
    for (size_t i = 0; i < size; ++i) {
        int index = ((char*)byte_ptr - (char*)&memory_pool[0]) / sizeof(void*);
        if (index < POOL_SIZE && memory_pool[index] == malloc(sizeof(void*))) {
            free(memory_pool[index]);
            memory_pool[index] = NULL;
        }
    }

    pthread_mutex_unlock(&pool_mutex);
}

int allocate_nfa_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T** array, size_t count) {
    if (!array || count == 0) return -1;

    *array = (NFAPI_CRC_INDICATION_PDU_T*)allocate_from_pool(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*array) return -2; // Allocation failed

    srand(time(NULL)); // Seed for random number generation
    for (size_t i = 0; i < count; ++i) {
        (*array)[i].RX_UE_INFORMATION_TAG = rand() % 100;
        (*array)[i].RNTI = rand() % 10000;
        (*array)[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        (*array)[i].CRCFLAG = rand() % 2;
    }

    return 0; // Success
}

void free_nfa_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T* array, size_t count) {
    if (!array) return;

    free_memory_pool(array, count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

int main() {
    initialize_memory_pool();

    NFAPI_CRC_INDICATION_PDU_T* pdu_array = NULL;
    int result = allocate_nfa_crc_pdu_array(&pdu_array, 10);
    if (result == 0) {
        // Use the array
        free_nfa_crc_pdu_array(pdu_array, 10);
    } else {
        printf("Allocation failed with error code: %d\n", result);
    }

    return 0;
}
```

### Key Points:
- **Memory Pool**: A static memory pool is used to reduce fragmentation and improve allocation performance.
- **Thread Safety**: Mutexes ensure that the memory pool operations are thread-safe.
- **Random CRCFLAG**: Randomly set using `rand()`.
- **Error Handling**: Returns meaningful error codes for failures.
- **Flexibility**: Designed to be easily extensible for future changes.']

