    int status_code;
    char *response_body;
    unsigned int flag;
} HTTP_RESPONSE_PDU_T;

void free_request(HTTP_Request *req) {
    if (req->url) free(req->url);
    for (int i = 0; req->headers && req->headers[i]; i++) {
        free(req->headers[i]);
    }
    free(req->headers);
}

HTTP_Request* create_random_http_request(int bandwidth_usage, int latency, int server_response_time) {
    HTTP_Request *req = malloc(sizeof(HTTP_Request));
    if (!req) return NULL;

    // Randomly generate URL and Method
    char url[256];
    snprintf(url, sizeof(url), "http://example.com/resource%d", rand() % 1000);
    req->url = strdup(url);

    req->method = (HTTP_Method)(rand() % 4);

    // Set headers (simplified)
    req->headers = malloc(2 * sizeof(char*));
    req->headers[0] = strdup("Content-Type: text/html");
    req->headers[1] = NULL;

    // Adjust body size based on network conditions
    int base_body_size = rand() % (MAX_BODY_SIZE - MIN_BODY_SIZE + 1) + MIN_BODY_SIZE;
    if (bandwidth_usage > 80 || latency > 200 || server_response_time > 300) {
        req->body_size = base_body_size / 2;
    } else {
        req->body_size = base_body_size;
    }

    // Random response code for now
    req->response_code = rand() % 600;

    return req;
}

int validate_http_request(HTTP_Request *req, int peak_traffic) {
    if (!req) return -1;

    // Basic validation logic
    if (peak_traffic && (req->method == HTTP_GET || req->method == HTTP_DELETE)) {
        // Offload validation to external service during peak traffic
        return rand() % 2; // Simulating validation result
    }

    switch (req->method) {
        case HTTP_POST:
        case HTTP_PUT:
            if (req->response_code >= 200 && req->response_code < 300) return 0;
            break;
        case HTTP_GET:
        case HTTP_DELETE:
            if (req->response_code == 404 || req->response_code == 200) return 0;
            break;
    }
    return -1;
}

void free_response_pdu(HTTP_RESPONSE_PDU_T *pdu) {
    if (pdu->response_body) free(pdu->response_body);
}

HTTP_RESPONSE_PDU_T* create_random_http_response_pdu() {
