    pdu->status_code = rand() % 600;
    pdu->response_body = strdup("Response Body");
    pdu->flag = rand() & 1; // Random flag

    return pdu;
}

void manage_dynamic_array(int max_memory_size, int bandwidth_usage, int latency, int server_response_time) {
    HTTP_Request *requests = NULL;
    size_t request_count = 0;
    size_t total_allocated_memory = 0;

    int successful_validations = 0;
    int failed_validations = 0;

    while (total_allocated_memory < max_memory_size) {
        HTTP_Request *new_request = create_random_http_request(bandwidth_usage, latency, server_response_time);
        if (!new_request) break;

        size_t request_memory_size = sizeof(HTTP_Request) + strlen(new_request->url) + 1;
        for (int i = 0; new_request->headers && new_request->headers[i]; i++) {
            request_memory_size += strlen(new_request->headers[i]) + 1;
        }

        if (total_allocated_memory + request_memory_size > max_memory_size) {
            free_request(new_request);
            break;
        }

        total_allocated_memory += request_memory_size;

        requests = realloc(requests, sizeof(HTTP_Request) * (request_count + 1));
        requests[request_count++] = *new_request;

        int is_peak_traffic = bandwidth_usage > 70 || latency > 150; // Simplified condition
        if (validate_http_request(&requests[request_count - 1], is_peak_traffic) == 0) {
            successful_validations++;
        } else {
            failed_validations++;
        }
    }

    HTTP_RESPONSE_PDU_T *response_pdus = NULL;
    size_t response_pdu_count = request_count;

    for (size_t i = 0; i < response_pdu_count; i++) {
        HTTP_RESPONSE_PDU_T *new_pdu = create_random_http_response_pdu();
        if (!new_pdu) break;

        size_t pdu_memory_size = sizeof(HTTP_RESPONSE_PDU_T) + strlen(new_pdu->response_body) + 1;
        response_pdus = realloc(response_pdus, sizeof(HTTP_RESPONSE_PDU_T) * (i + 1));
        response_pdus[i] = *new_pdu;
    }

    printf("Successful Validations: %d\n", successful_validations);
    printf("Failed Validations: %d\n", failed_validations);

    // Free resources
    for (size_t i = 0; i < request_count; i++) {
        free_request(&requests[i]);
    }
    free(requests);

    for (size_t i = 0; i < response_pdu_count; i++) {
        free_response_pdu(&response_pdus[i]);
    }
    free(response_pdus);
}

int main() {
    srand(time(NULL));
    manage_dynamic_array(MAX_SIZE, rand() % 100, rand() % 500, rand() % 600);
    return 0;
}
