pthread_mutex_t frame_mutex = PTHREAD_MUTEX_INITIALIZER;

void init_frame_header(NFAPI_RX_FRAME_HEADER_T *header, uint8_t type, uint16_t seq_num) {
    if (header != NULL) {
        header->frame_type = type;
        header->sequence_number = seq_num;
    }
}

void init_frame_payload(NFAPI_RX_FRAME_PAYLOAD_T *payload, const void *data, size_t len) {
    if (payload != NULL && data != NULL && len > 0) {
        payload->length = len < FRAME_MEMORY_LIMIT ? len : FRAME_MEMORY_LIMIT;
        payload->data = malloc(payload->length);
        if (payload->data != NULL) {
            memcpy(payload->data, data, payload->length);
        } else {
            // Handle memory allocation failure
            payload->length = 0;
        }
    }
}

void free_frame_payload(NFAPI_RX_FRAME_PAYLOAD_T *payload) {
    if (payload != NULL && payload->data != NULL) {
        free(payload->data);
        payload->data = NULL;
        payload->length = 0;
    }
}

int initialize_nfa_frames(NFAPI_RX_FRAME_PDU_T **frames, size_t frame_count) {
    int result = -1;

    if (frame_count == 0 || frames == NULL) return result;

    *frames = malloc(frame_count * sizeof(NFAPI_RX_FRAME_PDU_T));
    if (*frames == NULL) return result;

    pthread_mutex_lock(&frame_mutex);

    for (size_t i = 0; i < frame_count; ++i) {
        init_frame_header(&(*frames)[i].header, i % 256, i);
        // Example payload data initialization
        const uint8_t *example_data = (uint8_t[]){1, 2, 3, 4};
        init_frame_payload(&(*frames)[i].payload, example_data, sizeof(example_data));
    }

    pthread_mutex_unlock(&frame_mutex);
    result = 0;

    return result;
}

void free_nfa_frames(NFAPI_RX_FRAME_PDU_T *frames, size_t frame_count) {
    if (frames == NULL || frame_count == 0) return;

    for (size_t i = 0; i < frame_count; ++i) {
        free_frame_payload(&frames[i].payload);
    }
    free(frames);
}
