    int snr;
    int frequency_band;
    // Add more fields as needed
} LTE_PHY_RX_FRAME_PDU_T;

#define POOL_SIZE 1024

typedef struct MemoryPool {
    LTE_PHY_RX_FRAME_PDU_T* pool[POOL_SIZE];
    pthread_mutex_t lock;
} MemoryPool;

// Initialize a memory pool
MemoryPool* init_memory_pool() {
    MemoryPool* mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!mp) return NULL;

    for (int i = 0; i < POOL_SIZE; ++i) {
        mp->pool[i] = NULL;
    }
    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

// Allocate memory from the pool
LTE_PHY_RX_FRAME_PDU_T* allocate_from_pool(MemoryPool* mp, int snr, int frequency_band) {
    pthread_mutex_lock(&mp->lock);

    for (int i = 0; i < POOL_SIZE; ++i) {
        if (!mp->pool[i]) {
            LTE_PHY_RX_FRAME_PDU_T* pdu = (LTE_PHY_RX_FRAME_PDU_T*)malloc(sizeof(LTE_PHY_RX_FRAME_PDU_T));
            if (!pdu) {
                pthread_mutex_unlock(&mp->lock);
                return NULL;
            }
            pdu->snr = snr;
            pdu->frequency_band = frequency_band;
            mp->pool[i] = pdu;
            pthread_mutex_unlock(&mp->lock);
            return pdu;
        }
    }

    pthread_mutex_unlock(&mp->lock);
    return NULL; // Pool is full
}

// Free memory back to the pool
void free_to_pool(MemoryPool* mp, LTE_PHY_RX_FRAME_PDU_T* pdu) {
    pthread_mutex_lock(&mp->lock);

    for (int i = 0; i < POOL_SIZE; ++i) {
        if (mp->pool[i] == pdu) {
            free(mp->pool[i]);
            mp->pool[i] = NULL;
            break;
        }
    }

    pthread_mutex_unlock(&mp->lock);
}

// Function to dynamically allocate memory for an array of LTE_PHY_RX_FRAME_PDU_T
int* create_pdu_array(MemoryPool* mp, int size, int snr, int frequency_band) {
    if (!mp || size <= 0) return NULL;

    int* pdu_array = (int*)malloc(size * sizeof(int));
    if (!pdu_array) return NULL;

    for (int i = 0; i < size; ++i) {
        LTE_PHY_RX_FRAME_PDU_T* pdu = allocate_from_pool(mp, snr, frequency_band);
        if (!pdu) {
            free(pdu_array); // Cleanup on failure
            return NULL;
        }
        pdu_array[i] = (int)(size_t)pdu; // Store pointer as integer
    }

    return pdu_array;
}

// Function to release the allocated array of LTE_PHY_RX_FRAME_PDU_T
void destroy_pdu_array(MemoryPool* mp, int* pdu_array, int size) {
    if (!mp || !pdu_array) return;

    for (int i = 0; i < size; ++i) {
        LTE_PHY_RX_FRAME_PDU_T* pdu = (LTE_PHY_RX_FRAME_PDU_T*)(size_t)pdu_array[i];
        free_to_pool(mp, pdu);
    }
    free(pdu_array);
}

// Example usage
int main() {
    MemoryPool* mp = init_memory_pool();
    if (!mp) return EXIT_FAILURE;

    int size = 10;
    int snr = 15;
    int frequency_band = 700;

    int* pdu_array = create_pdu_array(mp, size, snr, frequency_band);
    if (!pdu_array) {
        printf("Failed to allocate PDU array\n");
        free_memory_pool(mp);
        return EXIT_FAILURE;
    }

    // Use the pdu_array as needed...

    destroy_pdu_array(mp, pdu_array, size);

    free_memory_pool(mp);
    return EXIT_SUCCESS;
}

// Function to deallocate memory pool
void free_memory_pool(MemoryPool* mp) {
    if (!mp) return;

    for (int i = 0; i < POOL_SIZE; ++i) {
        if (mp->pool[i]) {
            free(mp->pool[i]);
        }
    }

    pthread_mutex_destroy(&mp->lock);
    free(mp);
}
