void initialize_memory_pool(size_t initial_size) {
    if (mem_pool.memory_pool != NULL) return;
    pthread_mutex_lock(&mem_pool.lock);
    if (!mem_pool.is_full) {
        mem_pool.memory_pool = malloc(initial_size);
        if (mem_pool.memory_pool == NULL) {
            fprintf(stderr, "Failed to allocate memory pool\n");
            exit(EXIT_FAILURE);
        }
        mem_pool.pool_size = initial_size;
    } else {
        pthread_mutex_unlock(&mem_pool.lock);
        return;
    }
    pthread_mutex_unlock(&mem_pool.lock);
}

void* allocate_from_pool(size_t size) {
    void *ptr = NULL;
    pthread_mutex_lock(&mem_pool.lock);

    if (size > mem_pool.pool_size || mem_pool.is_full) {
        pthread_mutex_unlock(&mem_pool.lock);
        fprintf(stderr, "Memory pool exhausted or insufficient resources\n");
        return NULL;
