    ptr = mem_pool.memory_pool; // Simplified allocation logic
    mem_pool.pool_size -= size;

    if (mem_pool.pool_size == 0) {
        mem_pool.is_full = true;
    }

    pthread_mutex_unlock(&mem_pool.lock);
    return ptr;
}

void* deallocate_to_pool(void *ptr, size_t size) {
    pthread_mutex_lock(&mem_pool.lock);

    if (!mem_pool.is_full && mem_pool.pool_size + size <= INITIAL_POOL_SIZE) {
        mem_pool.memory_pool = realloc(mem_pool.memory_pool, mem_pool.pool_size + size);
        if (mem_pool.memory_pool == NULL) {
