```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>

#define MAX_LIST_SIZE 1000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    unsigned long sequence_number; // Unique sequence number for tracking
} NFAPI_CRC_INDICATION_PDU_T;

// Structure to manage the dynamic list of pointers and ensure thread safety
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T **list;
    size_t count;
    pthread_mutex_t mutex;
    unsigned long seq_num; // For generating unique sequence numbers
} NFAPI_LIST;

// Function prototypes
void initialize_list(NFAPI_LIST *nfaList);
int add_pdu_to_list(NFAPI_LIST *nfaList, uint32_t rnti_min, uint32_t rnti_max);
void cleanup_list(NFAPI_LIST *nfaList);

NFAPI_LIST* create_nfa_list() {
    NFAPI_LIST *list = (NFAPI_LIST *)malloc(sizeof(NFAPI_LIST));
    initialize_list(list);
    return list;
}

void initialize_list(NFAPI_LIST *nfaList) {
    nfaList->list = (NFAPI_CRC_INDICATION_PDU_T **)calloc(MAX_LIST_SIZE, sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    nfaList->count = 0;
    pthread_mutex_init(&nfaList->mutex, NULL);
    nfaList->seq_num = 1; // Start sequence number from 1
}

int add_pdu_to_list(NFAPI_LIST *nfaList, uint32_t rnti_min, uint32_t rnti_max) {
    pthread_mutex_lock(&nfaList->mutex);

    if (nfaList->count >= MAX_LIST_SIZE) {
        pthread_mutex_unlock(&nfaList->mutex);
        return -1; // List is full
    }

    NFAPI_CRC_INDICATION_PDU_T *new_pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pdu) {
        pthread_mutex_unlock(&nfaList->mutex);
        return -1; // Memory allocation failed
    }

    new_pdu->RX_UE_INFORMATION_TAG = rand();  // Randomized for demonstration purposes
    uint16_t random_rnti = (uint16_t)(rand() % (rnti_max - rnti_min + 1) + rnti_min);
    new_pdu->RNTI = random_rnti;
    new_pdu->CRC_INDICATION_REL8_TAG = rand() % 256; // Randomized for demonstration purposes
    new_pdu->CRCFLAG = rand() & 1; // Randomly set CRCFLAG to 0 or 1
    new_pdu->sequence_number = nfaList->seq_num++;

    if (random_rnti >= rnti_min && random_rnti <= rnti_max) {
        nfaList->list[nfaList->count++] = new_pdu;
    } else {
        free(new_pdu); // Free memory if RNTI is out of range
    }

    pthread_mutex_unlock(&nfaList->mutex);
    return 0; // Successfully added
}

void cleanup_list(NFAPI_LIST *nfaList) {
    pthread_mutex_lock(&nfaList->mutex);

    for (size_t i = 0; i < nfaList->count; ++i) {
        free(nfaList->list[i]);
    }
    free(nfaList->list);
    pthread_mutex_unlock(&nfaList->mutex);
    pthread_mutex_destroy(&nfaList->mutex);
    free(nfaList);
}

// Example usage
int main() {
    NFAPI_LIST *nfaList = create_nfa_list();

    for (int i = 0; i < MAX_LIST_SIZE; ++i) {
        add_pdu_to_list(nfaList, 1000, 2000); // Example RNTI range
    }

    cleanup_list(nfaList);
    return 0;
}
```

### Key Points:
- **Thread Safety**: The code uses a mutex to ensure that access to the list is thread-safe.
- **Dynamic Memory Management**: Memory for each `NFAPI_CRC_INDICATION_PDU_T` structure and the array of pointers are dynamically allocated and properly deallocated.
- **Unique Sequence Number**: Each structure gets a unique sequence number using an atomic-like mechanism with mutex protection.
- **RNTI Filtering**: The list adds structures only if their RNTI falls within a specified range.
- **Resource Cleanup**: Proper cleanup function is provided to free all allocated memory, preventing leaks.']

