typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* entries;
    size_t count;
    pthread_mutex_t lock;
} NFAPI_CRC_INDICATION_LIST_T;

// Configuration management simulation
size_t getMaxEntries() {
    // Placeholder for dynamic configuration updates, returns MAX_ENTRIES by default
    return MAX_ENTRIES; 
}

void initializeList(NFAPI_CRC_INDICATION_LIST_T* list) {
    pthread_mutex_init(&list->lock, NULL);
    list->entries = NULL;
    list->count = 0;
}

void freeList(NFAPI_CRC_INDICATION_LIST_T* list) {
    pthread_mutex_lock(&list->lock);
    if (list->entries != NULL) {
        free(list->entries);
    }
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int addEntry(NFAPI_CRC_INDICATION_LIST_T* list, const NFAPI_CRC_INDICATION_PDU_T* entry) {
    pthread_mutex_lock(&list->lock);

    size_t maxEntries = getMaxEntries();
    if (list->count >= maxEntries) {
        printf("Maximum entries limit reached.\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T* new_entries = realloc(list->entries, 
                                                      sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->count + 1));
    if (!new_entries) {
        printf("Memory allocation failed.\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    list->entries = new_entries;
    memcpy(&list->entries[list->count], entry, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Randomly set CRCFLAG for simulation
    srand(time(NULL) + rand());
    ((NFAPI_CRC_INDICATION_PDU_T*)entry)->CRC_INDICATION_REL8_TAG[0] = rand() % 256;

    list->count++;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

int removeEntry(NFAPI_CRC_INDICATION_LIST_T* list, size_t index) {
    if (index >= list->count) {
        printf("Invalid entry index.\n");
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    memmove(&list->entries[index], &list->entries[index + 1],
            sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->count - index - 1));

    NFAPI_CRC_INDICATION_PDU_T* new_entries = realloc(list->entries,
                                                      sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->count - 1));
    if (!new_entries && list->count > 0) {
        printf("Memory reallocation failed during removal.\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    list->entries = new_entries;

    list->count--;

    pthread_mutex_unlock(&list->lock);

    return 0;
}

void iterateList(NFAPI_CRC_INDICATION_LIST_T* list, void (*process)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        process(&list->entries[i]);
    }

    pthread_mutex_unlock(&list->lock);
}

// Example usage and logging function
void logEntry(NFAPI_CRC_INDICATION_PDU_T* entry) {
    printf("Logging Entry: RX_UE_INFORMATION_TAG=%u, RNTI=%u, CRC_FLAG=%02x\n",
           entry->RX_UE_INFORMATION_TAG,
           entry->RNTI,
           entry->CRC_INDICATION_REL8_TAG[0]);
}

int main() {
    NFAPI_CRC_INDICATION_LIST_T list;
    initializeList(&list);

    // Example: Adding an entry
    NFAPI_CRC_INDICATION_PDU_T exampleEntry = {123, 456, {1,2,3,4}};
    addEntry(&list, &exampleEntry);

    // Iterate and log entries
    iterateList(&list, logEntry);

    freeList(&list);

    return 0;
}
