        *size = 0;

        for (size_t i = 0; i < file_count; ++i) {
            const char *file_path = file_paths[i];

            // Determine file format and parse accordingly
            if (strstr(file_path, ".json")) {
                success = json_parse_file(file_path, contexts, size); // Pseudo-function for JSON parsing
            } else if (strstr(file_path, ".xml")) {
                success = xml_parse_file(file_path, contexts, size);  // Pseudo-function for XML parsing
            } else if (strstr(file_path, ".csv")) {
                success = csv_parse_file(file_path, contexts, size);  // Pseudo-function for CSV parsing
            }

            if (!success) {
                break; // Exit early on failure
            }
        }

        if (validate_unique_serving_cell_ids(*contexts, *size)) {
            success = 1;
        } else {
            retry_count++;
            sleep(delay);
            delay *= 2; // Exponential backoff
        }

        pthread_mutex_unlock(&mutex);
    }

    return success ? 0 : -1;
}

int validate_unique_serving_cell_ids(NRUE_CONTEXT_T *contexts, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        for (size_t j = i + 1; j < size; ++j) {
            if (contexts[i].ServingCellID == contexts[j].ServingCellID) {
                return 0;
            }
        }
    }
    return 1;
}

void free_contexts(NRUE_CONTEXT_T *contexts, size_t size) {
    free(contexts);
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <file1> [<file2> ...]\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char **file_paths = &argv[1];
    size_t file_count = argc - 1;

    NRUE_CONTEXT_T *contexts = NULL;
    size_t context_size = 0;

    if (validate_and_populate(&contexts, &context_size, file_paths, file_count) != 0) {
        fprintf(stderr, "Failed to populate contexts after multiple attempts.\n");
        return EXIT_FAILURE;
    }

    // Use the populated contexts...

    free_contexts(contexts, context_size);

    return EXIT_SUCCESS;
}
