    LTE_UE_Context *context = (LTE_UE_Context*)malloc(sizeof(LTE_UE_Context));
    if (!context) {
        pthread_mutex_unlock(&manager->lock);
        handle_error("Failed to allocate memory for context");
    }

    context->UE_ID = UE_ID;
    context->S_TMSI = S_TMSI;
    strncpy(context->NAS_MESSAGE_PDU_T, nas_message, BUFFER_LIMIT - 1);
    manager->contexts[manager->count++] = context;
    pthread_mutex_unlock(&manager->lock);

    return 0;
}

void update_context(LTE_UE_Context_Manager *manager, int UE_ID, const char *nas_message) {
    if (!validate_nas_message(nas_message, strlen(nas_message)))
        handle_error("Invalid NAS message format");

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        LTE_UE_Context *context = manager->contexts[i];
        if (context->UE_ID == UE_ID) {
            strncpy(context->NAS_MESSAGE_PDU_T, nas_message, BUFFER_LIMIT - 1);
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void remove_context(LTE_UE_Context_Manager *manager, int UE_ID) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->contexts[i]->UE_ID == UE_ID) {
            free(manager->contexts[i]);
            memmove(&manager->contexts[i], &manager->contexts[i + 1],
                    sizeof(LTE_UE_Context*) * (manager->count - i - 1));
            manager->count--;
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

