CRCList* createList() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    list->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(INITIAL_CAPACITY, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->capacity = INITIAL_CAPACITY;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void resizeList(CRCList* list) {
    int new_capacity = list->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T* temp = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp) return; // Memory allocation failed
    list->array = temp;
    list->capacity = new_capacity;
}

void addPdu(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);
    while (list->count >= list->capacity) resizeList(list);

    // Ensure unique RNTI
    for (int i = 0; i < list->count; ++i) {
        if (list->array[i].RNTI == pdu.RNTI) {
            pthread_mutex_unlock(&list->lock);
            return;
        }
    }

    list->array[list->count++] = pdu;

    int crcFlagCount = 0;
    for (int i = 0; i < list->count; ++i) {
        if (list->array[i].CRCFLAG) ++crcFlagCount;
    }

    // Remove entries to ensure CRCFLAG count does not exceed 50%
    while (2 * crcFlagCount > list->count && list->count > 0) {
        for (int i = 0; i < list->count; ++i) {
            if (list->array[i].CRCFLAG) {
                memmove(&list->array[i], &list->array[i + 1], (list->count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                --list->count;
                --crcFlagCount;
                break;
            }
        }
    }
    pthread_mutex_unlock(&list->lock);
}

bool verifyIntegrity(NFAPI_CRC_INDICATION_PDU_T pdu) {
    // Simulated integrity check
    return pdu.CRC_INDICATION_REL8_TAG % 2 == 0; 
}

int findLargest(int* arr, size_t n) {
