#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_LIST_SIZE 1000
#define RX_UE_INFORMATION_TAG_MIN 1
#define RX_UE_INFORMATION_TAG_MAX 255
#define RNTI_MIN 1
#define RNTI_MAX 65535

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list;
    size_t count;
    pthread_mutex_t mutex;
} CRC_Indication_List;

void log_error(const char* message) {
    FILE* file = fopen("crc_indication_errors.log", "a");
    if (file) {
        fprintf(file, "%s\n", message);
        fclose(file);
    }
    // Placeholder for external logging service integration
}

int is_valid_rx_ue_tag(int tag) {
    return tag >= RX_UE_INFORMATION_TAG_MIN && tag <= RX_UE_INFORMATION_TAG_MAX;
}

int is_valid_rnti(int rnti) {
    return rnti >= RNTI_MIN && rnti <= RNTI_MAX;
}

void clear_list(CRC_Indication_List* list) {
    pthread_mutex_lock(&list->mutex);
    memset(list->list, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T) * MAX_LIST_SIZE);
    list->count = 0;
    pthread_mutex_unlock(&list->mutex);
}

CRC_Indication_List create_and_populate_list(size_t n, unsigned int seed) {
    if (n > MAX_LIST_SIZE) {
        log_error("Requested list size exceeds maximum allowed limit.");
        n = MAX_LIST_SIZE;
    }

    CRC_Indication_List list;
    list.list = calloc(n, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list.list) {
        log_error("Memory allocation failed for NFAPI_CRC_INDICATION_PDU_T list.");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&list.mutex, NULL);
    list.count = 0;

    srand(seed);

    for (size_t i = 0; i < n; ++i) {
        int rx_ue_tag, rnti;
        do {
            rx_ue_tag = rand() % (RX_UE_INFORMATION_TAG_MAX - RX_UE_INFORMATION_TAG_MIN + 1) + RX_UE_INFORMATION_TAG_MIN;
            rnti = rand() % (RNTI_MAX - RNTI_MIN + 1) + RNTI_MIN;
        } while (!is_valid_rx_ue_tag(rx_ue_tag) || !is_valid_rnti(rnti));

        pthread_mutex_lock(&list.mutex);
        list.list[list.count].RX_UE_INFORMATION_TAG = rx_ue_tag;
        list.list[list.count].RNTI = rnti;
        list.list[list.count].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRCFLAG
        list.count++;
        pthread_mutex_unlock(&list.mutex);
    }

    return list;
}

void free_list(CRC_Indication_List* list) {
    if (list->list) {
        free(list->list);
        pthread_mutex_destroy(&list->mutex);
    }
}
