#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef void (*ReductionCallback)(int *accumulated, const int *current);

void generateRandomCRCFlag(unsigned char *crcflag) {
    srand(time(NULL));
    *crcflag = rand() % 2; // Randomly set to 0 or 1
}

NFAPI_CRC_INDICATION_PDU_T* populateCRCIndications(int numUEs, int crcIndicationsPerUE, ...) {
    va_list args;
    va_start(args, crcIndicationsPerUE);

    NFAPI_CRC_INDICATION_PDU_T *indications = (NFAPI_CRC_INDICATION_PDU_T *)malloc(numUEs * crcIndicationsPerUE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!indications) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    int rnti;
    for (int i = 0; i < numUEs; ++i) {
        rnti = va_arg(args, int);
        for (int j = 0; j < crcIndicationsPerUE; ++j) {
            NFAPI_CRC_INDICATION_PDU_T *pdu = &indications[i * crcIndicationsPerUE + j];
            pdu->RX_UE_INFORMATION_TAG = i;
            pdu->RNTI = rnti;
            pdu->CRC_INDICATION_REL8_TAG = rand(); // Random tag
            generateRandomCRCFlag(&pdu->CRCFLAG);
        }
    }

    va_end(args);
    return indications;
}

typedef struct {
    int *metrics;
    size_t size;
    ReductionCallback callback;
    int initialValue;
    int result;
} AsyncReduceContext;

void* asyncReduceWorker(void *context) {
    AsyncReduceContext *ctx = (AsyncReduceContext *)context;
    ctx->result = ctx->initialValue;

    for (size_t i = 0; i < ctx->size; ++i) {
        int currentMetric = ctx->metrics[i];
        ctx->callback(&ctx->result, &currentMetric);
    }

    pthread_exit(NULL);
}

int asyncReduce(int *metrics, size_t size, int initialValue, ReductionCallback callback) {
    AsyncReduceContext context;
    context.metrics = metrics;
    context.size = size;
    context.callback = callback;
    context.initialValue = initialValue;

    pthread_t thread;
    if (pthread_create(&thread, NULL, asyncReduceWorker, &context)) {
        perror("Failed to create thread");
        return -1; // Error code
    }

    void *status;
    if (pthread_join(thread, &status) != 0) {
        perror("Failed to join thread");
        return -2; // Error code
    }

    return context.result;
}

void sampleReductionCallback(int *accumulated, const int *current) {
    *accumulated += *current;
}

int main() {
    int ueIdentifiers[] = {1, 2, 3};
    int numUEs = sizeof(ueIdentifiers) / sizeof(ueIdentifiers[0]);
    int crcIndicationsPerUE = 5;

    NFAPI_CRC_INDICATION_PDU_T *indications = populateCRCIndications(numUEs, crcIndicationsPerUE, ueIdentifiers[0], ueIdentifiers[1], ueIdentifiers[2]);

    for (int i = 0; i < numUEs * crcIndicationsPerUE; ++i) {
        printf("RNTI: %d, CRCFLAG: %u\n", indications[i].RNTI, indications[i].CRCFLAG);
    }

    int metrics[] = {10, 20, 30, 40};
    size_t metricsSize = sizeof(metrics) / sizeof(metrics[0]);
    int result = asyncReduce(metrics, metricsSize, 0, sampleReductionCallback);

    if (result >= 0) {
        printf("Async Reduce Result: %d\n", result);
    } else {
        fprintf(stderr, "Error during async reduce: %d\n", result);
    }

    free(indications);
    return 0;
}
