        newNode->next = NULL;
        if (list->head == NULL) {
            list->head = newNode;
            current = newNode;
        } else {
            current->next = newNode;
            current = newNode;
        }
    }

    int isValid = validateLinkedList(list->head);
    pthread_mutex_unlock(&list->lock);

    return isValid ? list->head : NULL;  // Return the head if valid, otherwise NULL
}

// Function to free the linked list
