    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* nextNode = current->next;
        freeNode(current);
        current = nextNode;
    }

    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
}

