// Helper function to compare TRANSPORT_LAYER_HEADERS
int compare_transport_layer_headers(const void* a, const void* b) {
    return ((TRANSPORT_LAYER_HEADER_T*)a)->transport_layer_header -
           ((TRANSPORT_LAYER_HEADER_T*)b)->transport_layer_header;
}

// Function to check if transport layer header is unique in the list
int is_unique_transport_layer_header(TX_PACKET_PDU_T* head, TRANSPORT_LAYER_HEADER_T tlh) {
    TX_PACKET_PDU_T* current = head;
    while (current != NULL) {
        if (current->transport_layer_header.transport_layer_header == tlh.transport_layer_header)
            return 0; // Duplicate found
        current = current->next;
    }
    return 1; // Unique
}

// Function to free the memory of a TX_PACKET_PDU_T node
void free_packet_node(TX_PACKET_PDU_T* node) {
    if (node != NULL) {
        free(node->payload);
        free(node);
    }
}

TX_PACKET_PDU_T* manage_packets_list(TX_PACKET_PDU_T** head, MAC_HEADER_T mac_header,
                                     unsigned int pdcp_sn, const char* payload, size_t payload_length) {
    TRANSPORT_LAYER_HEADER_T new_tlh;
    TX_PACKET_PDU_T* new_packet = NULL;
    TX_PACKET_PDU_T* current;
    int retry_count = 0;

    while (retry_count < 5) {
        // Generate a unique transport layer header
        do {
            new_tlh.transport_layer_header = rand(); // Assume some random generation logic

            if (*head == NULL || is_unique_transport_layer_header(*head, new_tlh)) {
                break; // Unique or first packet in list
            }

        } while (1);

        if (!is_unique_transport_layer_header(*head, new_tlh)) {
            retry_count++;
            continue;
        }

        // Allocate memory for the new packet
        new_packet = malloc(sizeof(TX_PACKET_PDU_T));
        if (!new_packet) {
            fprintf(stderr, "Memory allocation failed\n");
            return NULL;
        }

        // Initialize and link list node
        new_packet->sequence_number = (*head == NULL ? 1 : (*head)->sequence_number + 1);
        new_packet->transport_layer_header = new_tlh;
        new_packet->mac_header = mac_header;
        new_packet->pdcp_sn.pdcp_sn = pdcp_sn;

        // Allocate and copy payload
        new_packet->payload_length = payload_length;
        new_packet->payload = malloc(payload_length);
        if (!new_packet->payload) {
            fprintf(stderr, "Memory allocation failed for payload\n");
            free_packet_node(new_packet);
            return NULL;
        }

        memcpy(new_packet->payload, payload, payload_length);

        // Insert into list
        new_packet->next = *head;
        *head = new_packet;

        return new_packet;  // Successfully added the packet
    }

    // Failed to create a unique transport layer header within retry limit
    fprintf(stderr, "Failed to add packet: Maximum retries reached\n");
    if (new_packet) {
        free_packet_node(new_packet);
    }

    return NULL;
}

// Function to clean up all packets in the list
void cleanup_packets_list(TX_PACKET_PDU_T** head) {
    TX_PACKET_PDU_T* current = *head;
    while (current != NULL) {
        TX_PACKET_PDU_T* temp = current;
        current = current->next;
        free_packet_node(temp);
    }
    *head = NULL;
}
