// Function prototypes for initialization, management, and cleanup
void init_pdu_manager(LTE_PDU_Manager* manager);
int add_pdu_to_manager(LTE_PDU_Manager* manager, const NFAPI_L1_API_LTE_PDU_T* pdu);
void update_pdu_in_manager(LTE_PDU_Manager* manager, size_t index, const NFAPI_L1_API_LTE_PDU_T* pdu);
NFAPI_L1_API_LTE_PDU_T* get_pdu_from_manager(const LTE_PDU_Manager* manager, size_t index);
int resize_pdu_array(LTE_PDU_Manager* manager);
void free_pdu_manager(LTE_PDU_Manager* manager);

// Initialize the PDU Manager
void init_pdu_manager(LTE_PDU_Manager* manager) {
    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;

    // Allocate and align memory for optimal performance (assuming a cache line is 64 bytes)
    size_t alignment = 64;
    if (posix_memalign((void**)&manager->array, alignment, manager->capacity * sizeof(NFAPI_L1_API_LTE_PDU_T))) {
        // Handle allocation failure
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
}

// Add a PDU to the manager
int add_pdu_to_manager(LTE_PDU_Manager* manager, const NFAPI_L1_API_LTE_PDU_T* pdu) {
    if (manager->count == manager->capacity) {
        if (resize_pdu_array(manager) != 0) {
            return -1; // Handle resize failure
        }
    }

    memcpy(&manager->array[manager->count], pdu, sizeof(NFAPI_L1_API_LTE_PDU_T));
    manager->count++;
    return 0;
}

// Update an existing PDU in the manager
void update_pdu_in_manager(LTE_PDU_Manager* manager, size_t index, const NFAPI_L1_API_LTE_PDU_T* pdu) {
    if (index < manager->count) {
        memcpy(&manager->array[index], pdu, sizeof(NFAPI_L1_API_LTE_PDU_T));
    }
}

// Retrieve a PDU from the manager
NFAPI_L1_API_LTE_PDU_T* get_pdu_from_manager(const LTE_PDU_Manager* manager, size_t index) {
    if (index < manager->count) {
        return &manager->array[index];
    }
    return NULL;
}

// Resize the internal array of PDUs when capacity is exceeded
int resize_pdu_array(LTE_PDU_Manager* manager) {
    size_t new_capacity = manager->capacity * GROWTH_FACTOR;

    // Allocate and align memory for optimal performance (assuming a cache line is 64 bytes)
    size_t alignment = 64;
    NFAPI_L1_API_LTE_PDU_T* new_array = NULL;
    if (posix_memalign((void**)&new_array, alignment, new_capacity * sizeof(NFAPI_L1_API_LTE_PDU_T))) {
        perror("Memory reallocation failed");
        return -1; // Handle allocation failure
    }

    memcpy(new_array, manager->array, manager->count * sizeof(NFAPI_L1_API_LTE_PDU_T));
    free(manager->array);

    manager->array = new_array;
    manager->capacity = new_capacity;
    return 0;
}

// Free resources allocated by the PDU Manager
void free_pdu_manager(LTE_PDU_Manager* manager) {
    free(manager->array);
    manager->array = NULL;
    manager->capacity = 0;
    manager->count = 0;
}
