#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>

#define MAX_LIST_SIZE 1000
#define RX_UE_TAG_MIN 1
#define RX_UE_TAG_MAX 255
#define RNTI_MIN 0
#define RNTI_MAX 1023

typedef struct {
    uint8_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list;
    size_t current_size;
    size_t capacity;
    pthread_mutex_t lock;
} CrcList;

#define LOG_FILE "crc_indication_errors.log"
#define METRICS_LOG_FILE "crc_indication_metrics.log"

void log_error(const char *message) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log) {
        fprintf(log, "%s\n", message);
        fclose(log);
    }
}

void log_metric(const char *metric_message) {
    FILE *metrics_log = fopen(METRICS_LOG_FILE, "a");
    if (metrics_log) {
        fprintf(metrics_log, "%s\n", metric_message);
        fclose(metrics_log);
    }
}

int is_valid_rx_ue_tag(uint8_t tag) {
    return RX_UE_TAG_MIN <= tag && tag <= RX_UE_TAG_MAX;
}

int is_valid_rnti(uint16_t rnti) {
    return RNTI_MIN <= rnti && rnti <= RNTI_MAX;
}

void send_to_logging_service(const char *message, int attempt);

CrcList* create_crc_list(size_t initial_capacity) {
    if (initial_capacity > MAX_LIST_SIZE)
        initial_capacity = MAX_LIST_SIZE;

    CrcList *list = malloc(sizeof(CrcList));
    list->list = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->current_size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void free_crc_list(CrcList *list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);
    list->current_size = 0;
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list->list);
    free(list);
}

void populate_crc_list(CrcList *list, size_t n) {
    if (!list || !n) return;

    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < n && list->current_size < list->capacity; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;

        do {
            pdu.RX_UE_INFORMATION_TAG = rand() % 256;
        } while (!is_valid_rx_ue_tag(pdu.RX_UE_INFORMATION_TAG));

        do {
            pdu.RNTI = rand() % (RNTI_MAX + 1);
        } while (!is_valid_rnti(pdu.RNTI));

        pdu.CRC_INDICATION_REL8_TAG = rand();
        pdu.CRCFLAG = rand() & 0x01;

        if (list->current_size < list->capacity) {
            list->list[list->current_size++] = pdu;
        } else {
            log_error("Exceeded list capacity");
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void adjust_list_size(CrcList *list, size_t new_capacity) {
    if (!list || new_capacity == 0 || new_capacity > MAX_LIST_SIZE)
        return;

    pthread_mutex_lock(&list->lock);
    if (new_capacity < list->current_size) {
        log_error("New capacity is less than current usage");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(list->list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_list) {
        list->list = new_list;
        list->capacity = new_capacity;
    } else {
        log_error("Failed to resize list");
    }
    pthread_mutex_unlock(&list->lock);
}

void monitor_and_log(CrcList *list, size_t successful_ops, size_t failed_ops, double processing_time) {
    char metric_message[256];

    snprintf(metric_message, sizeof(metric_message),
             "Successful operations: %zu, Failed operations: %zu, Processing time: %.2f seconds",
             successful_ops, failed_ops, processing_time);
    log_metric(metric_message);

    if (failed_ops > 0) {
        send_to_logging_service("Critical error occurred during CRC list population", 1);
    }
}

void send_to_logging_service(const char *message, int attempt) {
    const int max_attempts = 5;
    int delay = 100; // milliseconds
    for (int i = 0; i < attempt && i < max_attempts; ++i) {
        // Simulate sending message to logging service
        FILE *log_service = fopen("logging_service.log", "a");
        if (log_service) {
            fprintf(log_service, "%s\n", message);
            fclose(log_service);
            return;
        }
        usleep(delay * 1000); 
        delay *= 2; // Exponential backoff
    }

    log_error("Failed to send critical error to logging service after multiple attempts");
}

int main() {
    srand(time(NULL));

    CrcList *list = create_crc_list(500);
    size_t n = 400;
    populate_crc_list(list, n);

    adjust_list_size(list, 800); // Adjust based on requirements

    double processing_time = 1.23; // Example time
    monitor_and_log(list, list->current_size, MAX_LIST_SIZE - list->current_size, processing_time);

    free_crc_list(list);

    return 0;
}
