    if (memory_budget < sizeof(L2_MESSAGE)) {
        external_log("Memory budget too small.");
        return -1;
    }

    list->allocated_size = memory_budget / sizeof(L2_MESSAGE);
    if (list->allocated_size > MAX_STRUCTURES) {
        list->allocated_size = MAX_STRUCTURES;
    }

    list->messages = (L2_MESSAGE *)calloc(list->allocated_size, sizeof(L2_MESSAGE));
