    time_t last_activity_timestamp;
    void* metadata; // Pointer to dynamic metadata structure
} TCPConnectionState;

typedef struct {
    TCPConnectionState* connections;
    size_t capacity;
    size_t count;
    pthread_spinlock_t lock;
} ConnectionPool;

// Custom allocator with adaptive strategy
void* custom_allocator(size_t size) {
    static unsigned long long allocations = 0;
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    allocations++;
    // Adapt allocation strategy based on historical data (dummy implementation)
    return ptr;
}

void custom_free(void* ptr) {
    free(ptr);
}

ConnectionPool* create_connection_pool(size_t initial_capacity) {
    ConnectionPool* pool = custom_allocator(sizeof(ConnectionPool));
    pool->connections = custom_allocator(initial_capacity * sizeof(TCPConnectionState));
    pool->capacity = initial_capacity;
    pool->count = 0;
    pthread_spin_init(&pool->lock, PTHREAD_PROCESS_PRIVATE);
    return pool;
}

void destroy_connection_pool(ConnectionPool* pool) {
    for (size_t i = 0; i < pool->count; ++i) {
        custom_free(pool->connections[i].metadata);
    }
    custom_free(pool->connections);
    pthread_spin_destroy(&pool->lock);
    custom_free(pool);
}

int add_connection(ConnectionPool* pool, int socket_descriptor, void* metadata) {
    pthread_spin_lock(&pool->lock);
    if (pool->count >= pool->capacity) {
        // Resize logic with adaptive strategy
        size_t new_capacity = pool->capacity * 2;
        TCPConnectionState* new_connections = custom_allocator(new_capacity * sizeof(TCPConnectionState));
        memcpy(new_connections, pool->connections, pool->count * sizeof(TCPConnectionState));
        custom_free(pool->connections);
        pool->connections = new_connections;
        pool->capacity = new_capacity;
    }
    TCPConnectionState conn;
    conn.socket_descriptor = socket_descriptor;
    conn.last_activity_timestamp = time(NULL);
    conn.metadata = metadata; // Assume metadata is pre-allocated
    pool->connections[pool->count++] = conn;
    pthread_spin_unlock(&pool->lock);
    log_connection_event("Added", socket_descriptor);
    return 0;
}

void remove_connection(ConnectionPool* pool, int socket_descriptor) {
    pthread_spin_lock(&pool->lock);
    for (size_t i = 0; i < pool->count; ++i) {
        if (pool->connections[i].socket_descriptor == socket_descriptor) {
            custom_free(pool->connections[i].metadata);
            memmove(&pool->connections[i], &pool->connections[i + 1],
                    (pool->count - i - 1) * sizeof(TCPConnectionState));
            pool->count--;
            log_connection_event("Removed", socket_descriptor);
            break;
        }
    }
    pthread_spin_unlock(&pool->lock);
}

void log_connection_event(const char* event, int socket_descriptor) {
    // Dummy logging mechanism
    printf("Event: %s, Socket Descriptor: %d\n", event, socket_descriptor);
}

// Unit tests (dummy implementation)
void test_connection_pool() {
    ConnectionPool* pool = create_connection_pool(10);
    add_connection(pool, 1, custom_allocator(sizeof(int)));
    add_connection(pool, 2, custom_allocator(sizeof(int)));
    remove_connection(pool, 1);
    destroy_connection_pool(pool);
}

int main() {
    test_connection_pool();
    return 0;
}
