pthread_mutex_t memory_threshold_mutex = PTHREAD_MUTEX_INITIALIZER;
int total_memory_allocated = 0;

void log_allocation(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&log_file_mutex);

    if (ftell(log_file) > MAX_LOG_SIZE) {
        fclose(log_file);
