            pdu->CRC_INDICATION_REL8_TAG.RNTI, pdu->CRCFLAG);

    fflush(log_file);
    pthread_mutex_unlock(&log_file_mutex);
}

int is_valid_tag(int tag, int* whitelist, int M) {
    for (int i = 0; i < M; ++i) {
        if (whitelist[i] == tag) return 1;
    }
    return 0;
}

void* allocate_memory_and_initialize(void *args) {
    int N = *((int*)args);
    int *whitelist, M, S, current_tag, valid_allocation_count = 0;

    // Example whitelist size and seed (these would be passed into the function)
    M = 5; 
    S = 42;

    whitelist = (int[]){1, 2, 3, 4, 5}; // Example whitelist

    pthread_mutex_lock(&memory_threshold_mutex);
    int available_memory = MEMORY_THRESHOLD - total_memory_allocated;
    pthread_mutex_unlock(&memory_threshold_mutex);

    NFAPI_CRC_INDICATION_PDU_T *array = NULL;

    if (available_memory < sizeof(NFAPI_CRC_INDICATION_PDU_T) * N) {
        fprintf(stderr, "Not enough memory to allocate %d structures.\n", N);
        return NULL;
    }

    array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
    if (!array) {
        perror("Failed to allocate memory");
        return NULL;
    }

    srand(S);

    for (int i = 0; i < N; ++i) {
        pthread_mutex_lock(&memory_threshold_mutex);
        if (total_memory_allocated + sizeof(NFAPI_CRC_INDICATION_PDU_T) > MEMORY_THRESHOLD) {
            fprintf(stderr, "Memory threshold exceeded during allocation.\n");
            break;
        }

        array[i].CRCFLAG = rand() % 2; // Random CRCFLAG

        do {
            current_tag = rand() % (M * 2); // Example tag range
        } while (!is_valid_tag(current_tag, whitelist, M));

        array[i].CRC_INDICATION_REL8_TAG.RX_UE_INFORMATION_TAG = current_tag;
        array[i].CRC_INDICATION_REL8_TAG.RNTI = rand(); // Random RNTI

        total_memory_allocated += sizeof(NFAPI_CRC_INDICATION_PDU_T);

        pthread_mutex_unlock(&memory_threshold_mutex);

        log_allocation(&array[i]);
        valid_allocation_count++;
    }

    pthread_mutex_lock(&memory_threshold_mutex);
    if (valid_allocation_count == 0) {
        free(array);
        array = NULL;
    }
    pthread_mutex_unlock(&memory_threshold_mutex);

    return array;
}

void cleanup(NFAPI_CRC_INDICATION_PDU_T* array) {
    pthread_mutex_lock(&memory_threshold_mutex);
    total_memory_allocated -= sizeof(NFAPI_CRC_INDICATION_PDU_T) * (array ? array[0] : 1);
    pthread_mutex_unlock(&memory_threshold_mutex);

    if (array) free(array);
}

int main(int argc, char **argv) {
    log_file = fopen("alloc_log.txt", "w");

    int N = 100; // Number of structures to create
    int result_array[N];

    for (int i = 0; i < N; ++i) {
        pthread_t thread;
        int args = N / N;

        if (pthread_create(&thread, NULL, allocate_memory_and_initialize, &args)) {
            fprintf(stderr, "Error creating thread\n");
            return 1;
        }

        void *res;
        if (pthread_join(thread, &res)) {
            fprintf(stderr, "Error joining thread\n");
            return 2;
        }

        result_array[i] = (int) res;
    }

    for (int i = 0; i < N; ++i) {
        cleanup((NFAPI_CRC_INDICATION_PDU_T*)result_array[i]);
    }

    fclose(log_file);
    pthread_mutex_destroy(&log_file_mutex);
    pthread_mutex_destroy(&memory_threshold_mutex);

    return 0;
}
