// Implementation
NodeList* init_list(int max_entries) {
    NodeList* head = (NodeList*)malloc(sizeof(NodeList));
    if (!head) return NULL;

    head->next = NULL;
    for (int i = 0; i < max_entries - 1; ++i) {
        head->next = (NodeList*)malloc(sizeof(NodeList));
        if (!head->next) {
            while (head != NULL) {
                NodeList* temp = head;
                head = head->next;
                free(temp);
            }
            return NULL;
