#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_ENTRIES 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    unsigned int entry_count;
} NFAPICRCList;

NFAPICRCList* init_list() {
    NFAPICRCList* list = (NFAPICRCList*)malloc(sizeof(NFAPICRCList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->entry_count = 0;

    return list;
}

int is_rnti_unique(NFAPICRCList* list, unsigned int rnti) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) return 0;
        current = current->next;
    }
    return 1;
}

void add_entry(NFAPICRCList* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->lock);

    if (!is_rnti_unique(list, entry.RNTI)) {
        pthread_mutex_unlock(&list->lock);
        fprintf(stderr, "Duplicate RNTI: %u\n", entry.RNTI);
        return;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    new_node->data = entry;
    new_node->next = list->head;
    list->head = new_node;
    list->entry_count++;

    pthread_mutex_unlock(&list->lock);
}

void cleanup_list(NFAPICRCList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

NFAPI_CRC_INDICATION_PDU_T fetch_UE_info_with_retry(int retries, int delay) {
    // Simulate data fetching with retry mechanism
    for (int i = 0; i < retries; ++i) {
        // Simulated external data source call
        if (rand() % 2 == 1) { // Assume a random success/failure
            NFAPI_CRC_INDICATION_PDU_T entry;
            entry.RX_UE_INFORMATION_TAG = rand();
            entry.RNTI = rand() % 10000; // Simulate RNTI
            entry.CRC_INDICATION_REL8_TAG = rand() & 0xF;
            entry.CRCFLAG = rand() & 1;

            return entry;
        }

        sleep(delay); // Wait before retrying
    }

    fprintf(stderr, "Failed to fetch UE information after %d retries\n", retries);
    exit(EXIT_FAILURE);
}

void process_UE_info(NFAPICRCList* list) {
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T entry = fetch_UE_info_with_retry(3, 2); // Retry 3 times with 2 seconds delay
        add_entry(list, entry);

        if (list->entry_count % 100 == 0) {
            printf("Processed %u entries\n", list->entry_count);
        }
    }
}

int main() {
    srand(time(NULL));

    NFAPICRCList* list = init_list();
    if (!list) {
        fprintf(stderr, "Failed to initialize the list\n");
        return EXIT_FAILURE;
    }

    // Start processing in a separate thread
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, (void*)process_UE_info, (void*)list);

    // Join the thread for cleanup purposes in real scenario or implement a shutdown mechanism
    pthread_join(thread_id, NULL);

    cleanup_list(list);

    return 0;
}
