#include <stdio.h>
#include <stdlib.h>
import pthread.h

#define INITIAL_CAPACITY 10
#define MAX_CAPACITY 1000

typedef struct {
    // Add the required fields for LTE_UL_CCCH_MESSAGE here
} LTE_UL_CCCH_MESSAGE;

typedef struct {
    // Add the required fields for LTE_UL_CQI_CSI_REPORT here
} LTE_UL_CQI_CSI_REPORT;

typedef unsigned int lte_cqi_csi_report_t;

typedef struct {
    LTE_UL_CCCH_MESSAGE ccch_message;
    LTE_UL_CQI_CSI_REPORT cqi_report;
    lte_cqi_csi_report_t unique_value;
} LTE_UE_MEASUREMENT_RESULT;

typedef struct {
    LTE_UE_MEASUREMENT_RESULT *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray* arr = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!arr) return NULL;

    arr->data = (LTE_UE_MEASUREMENT_RESULT*)malloc(INITIAL_CAPACITY * sizeof(LTE_UE_MEASUREMENT_RESULT));
    if (!arr->data) {
        free(arr);
        return NULL;
    }

    arr->size = 0;
    arr->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&arr->mutex, NULL);

    return arr;
}

void resize_dynamic_array(DynamicArray* arr, size_t new_capacity) {
    LTE_UE_MEASUREMENT_RESULT *new_data = (LTE_UE_MEASUREMENT_RESULT*)realloc(arr->data, new_capacity * sizeof(LTE_UE_MEASUREMENT_RESULT));
    if (!new_data) return; // Handle memory allocation failure gracefully
    arr->data = new_data;
    arr->capacity = new_capacity;
}

int add_element(DynamicArray* arr, LTE_UL_CCCH_MESSAGE ccch_message, LTE_UL_CQI_CSI_REPORT cqi_report, lte_cqi_csi_report_t unique_value) {
    pthread_mutex_lock(&arr->mutex);

    if (arr->size >= MAX_CAPACITY) {
        printf("Max capacity reached. Cannot add new element.\n");
        pthread_mutex_unlock(&arr->mutex);
        return -1;
    }

    if (arr->size == arr->capacity) {
        size_t new_capacity = arr->capacity * 2;
        if (new_capacity > MAX_CAPACITY) new_capacity = MAX_CAPACITY;
        resize_dynamic_array(arr, new_capacity);
    }

    LTE_UE_MEASUREMENT_RESULT* result = &arr->data[arr->size++];
    result->ccch_message = ccch_message;
    result->cqi_report = cqi_report;
    result->unique_value = unique_value;

    pthread_mutex_unlock(&arr->mutex);
    return 0;
}

int remove_element(DynamicArray* arr, size_t index) {
    if (index >= arr->size) return -1;

    pthread_mutex_lock(&arr->mutex);

    for (size_t i = index; i < arr->size - 1; ++i) {
        arr->data[i] = arr->data[i + 1];
    }

    arr->size--;

    // Shrink if necessary
    if (arr->size <= arr->capacity / 4 && arr->capacity / 2 >= INITIAL_CAPACITY) {
        resize_dynamic_array(arr, arr->capacity / 2);
    }

    pthread_mutex_unlock(&arr->mutex);
    return 0;
}

void free_dynamic_array(DynamicArray* arr) {
    if (!arr) return;

    pthread_mutex_destroy(&arr->mutex);
    free(arr->data);
    free(arr);
}

void iterate_elements(DynamicArray* arr, void (*func)(LTE_UE_MEASUREMENT_RESULT*)) {
    pthread_mutex_lock(&arr->mutex);

    for (size_t i = 0; i < arr->size; ++i) {
        func(&arr->data[i]);
    }

    pthread_mutex_unlock(&arr->mutex);
}

// Example unit test function
void test_dynamic_array() {
    DynamicArray *arr = create_dynamic_array();
    if (!arr) {
        printf("Failed to create dynamic array.\n");
        return;
    }

    LTE_UL_CCCH_MESSAGE ccch_message; // Initialize properly
    LTE_UL_CQI_CSI_REPORT cqi_report;  // Initialize properly
    lte_cqi_csi_report_t unique_value = 1;

    add_element(arr, ccch_message, cqi_report, unique_value);

    iterate_elements(arr, [](LTE_UE_MEASUREMENT_RESULT* result) {
        printf("Element with unique value: %u\n", result->unique_value);
    });

    remove_element(arr, 0);
    free_dynamic_array(arr);
}

// Example benchmark function
void benchmark_dynamic_array() {
    DynamicArray *arr = create_dynamic_array();
    if (!arr) return;

    for (int i = 0; i < MAX_CAPACITY; ++i) {
        LTE_UL_CCCH_MESSAGE ccch_message; // Initialize properly
        LTE_UL_CQI_CSI_REPORT cqi_report;  // Initialize properly
        lte_cqi_csi_report_t unique_value = i;

        add_element(arr, ccch_message, cqi_report, unique_value);
    }

    free_dynamic_array(arr);
}

int main() {
    test_dynamic_array();
    benchmark_dynamic_array();

    return 0;
}
