// Define error codes
#define SUCCESS 0
#define ERROR_OUT_OF_MEMORY -1
#define ERROR_INVALID_PARAMETER -2

// Define a logging function
void log_message(const char *message) {
    printf("%s\n", message);
}

// Custom memory pool for managing dynamic array
typedef struct MemoryPool {
    NFAPI_CRC_INDICATION_PDU_T* pool;
    size_t capacity;
    size_t used;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_capacity) {
    MemoryPool *mp = malloc(sizeof(MemoryPool));
    if (!mp) return NULL;

    mp->pool = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!mp->pool) {
        free(mp);
        return NULL;
    }

    mp->capacity = initial_capacity;
    mp->used = 0;
    return mp;
}

void destroy_memory_pool(MemoryPool *mp) {
    if (mp) {
        free(mp->pool);
        free(mp);
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_from_pool(MemoryPool *mp, size_t count) {
    if (!mp || mp->used + count > mp->capacity) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *result = &mp->pool[mp->used];
    mp->used += count;
    return result;
}

// Function to populate and manage the dynamic array
int manage_dynamic_array(size_t N, unsigned int seed, int concurrent_access, MemoryPool **array_mp) {
    if (N == 0 || !array_mp) {
        log_message("Invalid input parameters");
        return ERROR_INVALID_PARAMETER;
    }

    *array_mp = create_memory_pool(N);
    if (!*array_mp) {
        log_message("Out of memory while creating pool");
        return ERROR_OUT_OF_MEMORY;
    }

    pthread_mutex_t lock = (concurrent_access) ? PTHREAD_MUTEX_INITIALIZER : 0;

    srand(seed);
    NFAPI_CRC_INDICATION_PDU_T *array = allocate_from_pool(*array_mp, N);
    if (!array) {
        log_message("Out of memory while allocating from pool");
        destroy_memory_pool(*array_mp);
        return ERROR_OUT_OF_MEMORY;
    }

    for (size_t i = 0; i < N; ++i) {
        pthread_mutex_lock(&lock);

        array[i].RX_UE_INFORMATION_TAG = rand() % 256;
        array[i].RNTI = rand() % 1024;
        array[i].CRC_INDICATION_REL8_TAG = (rand() % 2 == 0);

        if (!concurrent_access) {
            array[i].CRCFLAG = rand() % 2; // Random value
        } else {
            array[i].CRCFLAG = 0; // Zero for concurrent access mode
        }

        log_message("Created structure with RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG");
        pthread_mutex_unlock(&lock);
    }

    if (concurrent_access) {
        pthread_mutex_destroy(&lock);
    }

    return SUCCESS;
}

// Unit tests
void test_manage_dynamic_array() {
    MemoryPool *mp = NULL;

    // Test empty array
    int result = manage_dynamic_array(0, 123, 0, &mp);
    assert(result == ERROR_INVALID_PARAMETER);

    // Test maximum capacity
