    assert(result == SUCCESS);

    // Simulate concurrent access (simplified test)
    pthread_t threads[2];
    for (int i = 0; i < 2; ++i) {
        pthread_create(&threads[i], NULL, (void*) manage_dynamic_array, (void*)(uintptr_t)(100 + i));
    }

    for (int i = 0; i < 2; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_memory_pool(mp);
}

// Main function to run the tests
