    Node* head;
    size_t count;
} NFALIST;

NFALIST* create_list() {
    NFALIST* list = (NFALIST*)malloc(sizeof(NFALIST));
    if (!list) return NULL;
    list->head = NULL;
    list->count = 0;
    return list;
}

void destroy_list(NFALIST* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

Node* find_node(NFALIST* list, int RNTI) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == RNTI)
            return current;
        current = current->next;
    }
    return NULL;
}

int add_entry(NFALIST* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    if (list->count >= MAX_ENTRIES) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1;

    new_node->data = entry;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;
    return 0;
}

int update_entry(NFALIST* list, int RNTI, NFAPI_CRC_INDICATION_PDU_T updated_entry) {
    Node* node = find_node(list, RNTI);
    if (!node) return -1;

    node->data = updated_entry;
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_entry(NFALIST* list, int RNTI) {
    Node* node = find_node(list, RNTI);
    if (!node) return NULL;
    return &node->data;
}

