void* populate_structures(void *arg);
void serialize_structures(NFAPI_CRC_INDICATION_PDU_T *structures, size_t count);
void log_crc_flags_count(NFAPI_CRC_INDICATION_PDU_T *structures, size_t count);
NFAPI_CRC_INDICATION_PDU_T* allocate_structures(size_t count, int* actual_count);

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <probability_threshold>\n", argv[0]);
        return EXIT_FAILURE;
    }

    double probability_threshold = atof(argv[1]);

    // Number of threads
    int num_threads = 4; // Adjust based on system capabilities

    size_t count_per_thread = MAX_STRUCTURES / num_threads;
    pthread_t threads[num_threads];
    NFAPI_CRC_INDICATION_PDU_T *structures = NULL;
    int actual_count;

    structures = allocate_structures(MAX_STRUCTURES, &actual_count);
    if (!structures) {
