    }

    // Join threads
    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    serialize_structures(structures, actual_count);

    log_crc_flags_count(structures, actual_count);

    free(structtures);
    return EXIT_SUCCESS;
}

void* populate_structures(void *arg) {
    NFAPI_CRC_INDICATION_PDU_T *structures = (NFAPI_CRC_INDICATION_PDU_T *)arg;
    size_t count = MAX_STRUCTURES / 4; // Assuming 4 threads
    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < count; ++i) {
        structures[i].RX_UE_INFORMATION_TAG = rand();
        structures[i].RNTI = rand();
        structures[i].CRC_INDICATION_REL8_TAG = rand();

        double r = ((double)rand() / RAND_MAX);
        structures[i].CRCFLAG = (r < probability_threshold) ? 1 : 0;
    }

    return NULL;
}

