    for (size_t i = 0; i < count; ++i) {
        if (structures[i].CRCFLAG) {
            crc_flag_count++;
        }
    }

    printf("Total CRC_INDICATION_REL8_TAG with CRCFLAG set to true: %d\n", crc_flag_count);
