NFAPI_CRC_INDICATION_PDU_T* allocate_structures(size_t count, int *actual_count) {
    NFAPI_CRC_INDICATION_PDU_T *structures = (NFAPI_CRC_INDICATION_PDU_T *)malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!structures) {
        // Attempt to allocate a smaller number of structures
        size_t reduced_count = count / 2;
        while (reduced_count > 0 && !structures) {
            structures = (NFAPI_CRC_INDICATION_PDU_T *)malloc(reduced_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!structures) {
                reduced_count /= 2;
            }
        }

        if (!structures) {
            fprintf(stderr, "Unable to allocate memory for any structures.\n");
            return NULL;
        }
    }

    *actual_count = structures ? (int)count : (int)reduced_count;
    return structures;
}
