    pdu->rx_info_tag.valid = 1;
    pdu->rx_info_tag.RNTI = (unsigned long)rnti;
    pdu->crc_indication_rel8_tag.CRCFLAG = rand() % 256; // Random CRCFLAG
    return pdu;
}

void free_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (pdu) free(pdu);
}

int add_entry(CRCList *list, NFAPI_CRC_INDICATION_PDU_T *data) {
    pthread_mutex_lock(&list->lock);

    Entry *new_entry = malloc(sizeof(Entry));
    if (!new_entry) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_entry->data = *data;
    new_entry->next = list->head;
    list->head = new_entry;
    list->size++;
    log_change("ADD", data);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_entry_by_rnti(CRCList *list, unsigned long rnti) {
    pthread_mutex_lock(&list->lock);

    Entry *current = list->head;
    while (current) {
        if (current->data.rx_info_tag.RNTI == rnti) {
            NFAPI_CRC_INDICATION_PDU_T *result = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!result) {
                pthread_mutex_unlock(&list->lock);
                return NULL;
            }
            *result = current->data;
            pthread_mutex_unlock(&list->lock);
            return result;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

int update_entry(CRCList *list, unsigned long rnti, NFAPI_CRC_INDICATION_PDU_T *new_data) {
    pthread_mutex_lock(&list->lock);

    Entry *current = list->head;
    while (current) {
        if (current->data.rx_info_tag.RNTI == rnti) {
            current->data = *new_data;
            log_change("UPDATE", new_data);
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Entry not found
}

void delete_entry(CRCList *list, unsigned long rnti) {
    pthread_mutex_lock(&list->lock);

    Entry **indirect = &list->head;
    while (*indirect) {
        if ((*indirect)->data.rx_info_tag.RNTI == rnti) {
            Entry *entry_to_delete = *indirect;
            *indirect = entry_to_delete->next;
            free_pdu(&entry_to_delete->data);
            free(entry_to_delete);
            list->size--;
            log_change("DELETE", &entry_to_delete->data);
            pthread_mutex_unlock(&list->lock);
            return;
        }
        indirect = &(*indirect)->next;
    }

    pthread_mutex_unlock(&list->lock);
}

int persist_entry(NFAPI_CRC_INDICATION_PDU_T *data) {
    int attempt = 0;
    while (attempt < RETRY_LIMIT) {
        if (db_insert(data)) {
            return 1; // Success
        }
        attempt++;
        sleep(1); // Wait before retrying
    }
    log_error("Failed to persist entry after retries.");
    return -1;
}

void load_entries_from_db() {
    NFAPI_CRC_INDICATION_PDU_T *data = db_fetch_all();
    if (data) {
        while (*data) {
            add_entry(&list, data++);
        }
        free(data);
    }
}

int main(int argc, char **argv) {
    srand(time(NULL));

    if (!initialize_database()) return 1;

    load_entries_from_db();

    // Example operations
    NFAPI_CRC_INDICATION_PDU_T *pdu = create_pdu(12345);
    add_entry(&list, pdu);
    persist_entry(pdu);

    NFAPI_CRC_INDICATION_PDU_T *retrieved_pdu = get_entry_by_rnti(&list, 12345);
    if (retrieved_pdu) {
        update_entry(&list, retrieved_pdu->rx_info_tag.RNTI, pdu);
        delete_entry(&list, retrieved_pdu->rx_info_tag.RNTI);
        free_pdu(retrieved_pdu);
    }

    finalize_database();
    return 0;
}
```

**Note**: This code assumes the existence of `database_api.h` and `logging_api.h`, which provide necessary database operations (`db_connect`, `db_disconnect`, `db_insert`, `db_fetch_all`) and logging functions (`log_change`, `log_error`). The implementation is designed to handle dynamic memory management, concurrent access with mutexes, and retry mechanisms for database operations.']

