typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t array_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond_var = PTHREAD_COND_INITIALIZER;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array[MAX_ELEMENTS];
    size_t count;
    pthread_mutex_t flush_mutex;
    time_t last_flush_time;
} DynamicArrayManager;

DynamicArrayManager managers[10]; // Assuming 10 independent instances

void init_manager(DynamicArrayManager* manager) {
    pthread_mutex_init(&manager->flush_mutex, NULL);
    manager->count = 0;
    manager->last_flush_time = time(NULL);
}

int allocate_array_element(DynamicArrayManager* manager) {
    pthread_mutex_lock(&array_lock);
    if (manager->count >= MAX_ELEMENTS) {
        printf("Error: Memory allocation failure\n");
        pthread_mutex_unlock(&array_lock);
        return -1;
    }

    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        if (!manager->array[i]) {
            manager->array[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!manager->array[i]) {
                printf("Error: Memory allocation failure\n");
                pthread_mutex_unlock(&array_lock);
                return -1;
            }
            ++manager->count;
            pthread_mutex_unlock(&array_lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&array_lock);
    return -1;
}

int validate_rnti(DynamicArrayManager* manager, int rnti) {
    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        if (manager->array[i] && manager->array[i]->RNTI == rnti) {
            printf("Error: Duplicate RNTI found\n");
            return -1;
        }
    }
    return 0;
}

void* process_crc_indication(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)arg;
    // Simulate external data processing
    sleep(rand() % 3); // Random delay to simulate variable response times

    // Validate CRCFLAG or perform other operations
    if (pdu->CRC_INDICATION_REL8_TAG.CRCFLAG != 1) {
        printf("Warning: Invalid CRCFLAG\n");
    }
    return NULL;
}

void add_pdu(DynamicArrayManager* manager, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&array_lock);
    if (allocate_array_element(manager) == -1) {
        pthread_mutex_unlock(&array_lock);
        return;
    }

    int rnti_valid = validate_rnti(manager, pdu.RNTI);
    if (rnti_valid == -1) {
        pthread_mutex_unlock(&array_lock);
        free(pdu.array); // Cleanup allocated memory
        return;
    }

    *manager->array[manager->count - 1] = pdu;

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, process_crc_indication, (void*)&pdu);

    pthread_mutex_unlock(&array_lock);
}

void flush_to_external_storage(DynamicArrayManager* manager) {
    pthread_mutex_lock(&manager->flush_mutex);

    // Simulate storage operation
    printf("Flushing data to external storage...\n");
    sleep(1); // Simulating delay

    // Reset array and count after flushing
    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        if (manager->array[i]) {
            free(manager->array[i]);
            manager->array[i] = NULL;
        }
    }
    manager->count = 0;

    pthread_mutex_unlock(&manager->flush_mutex);
}

void* flush_manager(void* arg) {
    DynamicArrayManager* manager = (DynamicArrayManager*)arg;
    while (1) {
        time_t current_time = time(NULL);
        if (difftime(current_time, manager->last_flush_time) >= MIN_FLUSH_INTERVAL) {
            flush_to_external_storage(manager);
            manager->last_flush_time = current_time;
        }
        sleep(10); // Check every 10 seconds
    }
}

int main() {
    srand(time(NULL));

    for (int i = 0; i < 10; ++i) { // Initialize 10 independent managers
        init_manager(&managers[i]);
        pthread_t flush_thread;
        pthread_create(&flush_thread, NULL, flush_manager, &managers[i]);
