        pdu.RNTI = rand() % 50000 + 1;
        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        add_pdu(&managers[0], pdu); // Add to the first manager for demonstration
    }

    pthread_exit(NULL);
}
