typedef struct {
    LTE_RRC_CUCU_MESSAGE *array;
    size_t used;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

void initDynamicArray(DynamicArray *a) {
    a->used = 0;
    a->size = INITIAL_SIZE;
    a->array = (LTE_RRC_CUCU_MESSAGE *)malloc(a->size * sizeof(LTE_RRC_CUCU_MESSAGE));
    if (!a->array) {
        fprintf(stderr, "Failed to allocate initial array.\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&a->lock, NULL);
}

void insertDynamicArray(DynamicArray *a, LTE_RRC_CUCU_MESSAGE item) {
    pthread_mutex_lock(&a->lock);

    if (a->used == a->size) {
        size_t new_size = a->size * 2;
        LTE_RRC_CUCU_MESSAGE *new_array = realloc(a->array, new_size * sizeof(LTE_RRC_CUCU_MESSAGE));
        if (!new_array) {
            fprintf(stderr, "Failed to reallocate array.\n");
            pthread_mutex_unlock(&a->lock);
            exit(EXIT_FAILURE);
        }
        a->array = new_array;
        a->size = new_size;
    }

    a->array[a->used++] = item;
    pthread_mutex_unlock(&a->lock);
}

void freeDynamicArray(DynamicArray *a) {
    for (size_t i = 0; i < a->used; ++i) {
        free(a->array[i].MME_UPLINK_NAS_Transport_message_content);
        for (size_t j = 0; j < a->array[i].num_pdu; ++j) {
            free(a->array[i].pdu_list[j]);
