        message->pdu_list[i]->RNTI = rand() % 65536;
        message->pdu_list[i]->crc_indication_rel8_tag.CRC_INDICATION_REL8_TAG = rand() % 256;
        message->pdu_list[i]->crc_indication_rel8_tag.CRCFLAG = rand() % 2;
