// Custom allocator structure and functions
typedef struct {
    size_t block_size;
    void* aligned_memory;
    pthread_mutex_t lock;
} CustomAllocator;

CustomAllocator* custom_allocator_init(size_t block_size, int align) {
    CustomAllocator* allocator = (CustomAllocator*)malloc(sizeof(CustomAllocator));
    if (!allocator) return NULL;

    allocator->block_size = block_size + ((align > 0) ? align - 1 : 0);
    pthread_mutex_init(&allocator->lock, NULL);

    // Allocate aligned memory
    void* ptr = malloc(allocator->block_size + sizeof(void*));
    if (!ptr) {
        free(allocator);
        return NULL;
    }

    uintptr_t address = (uintptr_t)ptr + sizeof(void*);
    allocator->aligned_memory = (void*)(((address + align - 1) / align) * align);

    // Store original pointer for cleanup
    memcpy((char*)allocator->aligned_memory - sizeof(void*), &ptr, sizeof(void*));

    return allocator;
}

void* custom_allocator_alloc(CustomAllocator* allocator, size_t size) {
    pthread_mutex_lock(&allocator->lock);
    void* ptr = malloc(size);
    pthread_mutex_unlock(&allocator->lock);

    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    return ptr;
}

void custom_allocator_free(CustomAllocator* allocator, void* ptr) {
    pthread_mutex_lock(&allocator->lock);
    free(ptr);
    pthread_mutex_unlock(&allocator->lock);
}

void custom_allocator_cleanup(CustomAllocator* allocator) {
    void* original_ptr = NULL;
    memcpy((char*)allocator->aligned_memory - sizeof(void*), &original_ptr, sizeof(void*));
    custom_allocator_free(allocator, original_ptr);
    free(allocator);
}

// Logging mechanism (simplified)
