    if (!pduList) return NULL;

    pduList->pdus = NULL;
    pduList->count = 0;
    pthread_mutex_init(&pduList->mutex, NULL);
    return pduList;
}

// Function to add a PDU
int add_pdu(PDU_LIST_T* pduList, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    if (!pduList || pduList->count >= MAX_PDUS)
        return -1;

    pthread_mutex_lock(&pduList->mutex);

    NFAPI_CRC_INDICATION_PDU_T* new_pdus = (NFAPI_CRC_INDICATION_PDU_T*)realloc(pduList->pdus, 
        (pduList->count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pdus) {
        pthread_mutex_unlock(&pduList->mutex);
        return -2;
    }

    pduList->pdus = new_pdus;

    NFAPI_CRC_INDICATION_PDU_T* pdu = &pduList->pdus[pduList->count];
    pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu->RNTI = RNTI;
    pdu->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;

    srand(time(NULL) + pdu->RX_UE_INFORMATION_TAG); // Seed with a unique value
    pdu->CRCFLAG = (rand() % 2 == 0);

    ++pduList->count;

    pthread_mutex_unlock(&pduList->mutex);
    return 0;
}

// Function to free the list
void destroy_pdu_list(PDU_LIST_T* pduList) {
    if (!pduList) return;

    pthread_mutex_lock(&pduList->mutex);
    free(pduList->pdus);
    pthread_mutex_unlock(&pduList->mutex);

    pthread_mutex_destroy(&pduList->mutex);
    free(pduList);
}

// Function to log messages
void log_message(const char* message) {
    printf("%s\n", message);
}

int main() {
    PDU_LIST_T* pduList = create_pdu_list();
    if (!pduList) {
        log_message("Failed to initialize PDU list.");
        return -1;
    }

    for (int i = 0; i < 100; ++i) { // Example adding PDUs
        int result = add_pdu(pduList, i, i * 10, i * 5);
        if (result != 0) {
            log_message("Error adding PDU.");
        }
    }

    destroy_pdu_list(pduList);

    return 0;
}
```

### Key Points:
- **Resource Allocation**: The list of PDUs is dynamically managed using `realloc` to accommodate growing sizes.
- **Concurrency**: A mutex lock (`pthread_mutex_t`) ensures thread-safe access and modification of the PDU list.
- **Performance Optimization**: Minimal function calls and direct data manipulation are used for performance.
- **Scalability**: The design allows adding more PDUs up to a defined limit (`MAX_PDUS`).
- **Usability**: Functions `add_pdu`, `create_pdu_list`, and `destroy_pdu_list` provide an intuitive API.
- **Logging**: Simple logging via `log_message`.
- **Error Handling**: Error codes are returned for failure conditions, allowing graceful handling.

This solution should serve as a robust starting point for managing PDUs in a scalable manner. Adjustments can be made based on specific requirements and performance testing.']

