#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>

#define MAX_SYMBOLS 1024

typedef struct {
    int16_t I;
    int16_t Q;
} NFAPI_RX_SYMBOL_T;

typedef struct {
    uint32_t UE_INDEX;
    uint8_t RX_UE_CONTEXT_TAG;
    NFAPI_RX_SYMBOL_T* symbols;
    size_t num_symbols;
} NFAPI_RX_FRAME_T;

typedef struct {
    void* pool;
    size_t total_size;
    size_t used_size;
    int ref_count;
} MemoryPool;

static MemoryPool symbol_pool = {NULL, 0, 0, 0};

bool init_memory_pool(size_t element_size, size_t num_elements) {
    if (symbol_pool.pool != NULL) return false; // Already initialized

    size_t pool_size = element_size * num_elements;
    symbol_pool.pool = malloc(pool_size);
    if (!symbol_pool.pool) return false;

    symbol_pool.total_size = pool_size;
    symbol_pool.used_size = 0;
    symbol_pool.ref_count = 1;
    return true;
}

void* allocate_from_pool(size_t size) {
    if (size > symbol_pool.total_size - symbol_pool.used_size)
        return NULL; // Not enough space

    void* ptr = (char*)symbol_pool.pool + symbol_pool.used_size;
    symbol_pool.used_size += size;
    symbol_pool.ref_count++;
    return ptr;
}

void free_memory_pool() {
    if (--symbol_pool.ref_count == 0 && symbol_pool.pool != NULL) {
        free(symbol_pool.pool);
        symbol_pool.pool = NULL;
    }
}

NFAPI_RX_FRAME_T* initNfapiRxFrames(size_t num_frames, uint8_t version) {
    NFAPI_RX_FRAME_T* frames = (NFAPI_RX_FRAME_T*)malloc(num_frames * sizeof(NFAPI_RX_FRAME_T));
    if (!frames) return NULL;

    for (size_t i = 0; i < num_frames; ++i) {
        frames[i].UE_INDEX = rand() % 100;
        frames[i].RX_UE_CONTEXT_TAG = rand() % 256;

        size_t num_symbols = version >= 2 ? MAX_SYMBOLS : (rand() % MAX_SYMBOLS);
        frames[i].symbols = (NFAPI_RX_SYMBOL_T*)allocate_from_pool(num_symbols * sizeof(NFAPI_RX_SYMBOL_T));
        if (!frames[i].symbols) {
            for (size_t j = 0; j < i; ++j)
                free(frames[j].symbols); // Cleanup in case of failure
            free(frames);
            return NULL;
        }

        frames[i].num_symbols = num_symbols;

        for (size_t s = 0; s < num_symbols; ++s) {
            int noise_level = rand() % 3 - 1; // Simulating noise levels: -1, 0, +1
            frames[i].symbols[s].I = rand() % 256 - 128 + noise_level;
            frames[i].symbols[s].Q = rand() % 256 - 128 + noise_level;
        }
    }

    return frames;
}

void freeNfapiRxFrames(NFAPI_RX_FRAME_T* frames, size_t num_frames) {
    if (!frames) return;

    for (size_t i = 0; i < num_frames; ++i)
        if (frames[i].symbols) free_memory_pool(); // Deallocate symbols

    free(frames);
}

int main() {
    if (!init_memory_pool(sizeof(NFAPI_RX_SYMBOL_T), MAX_SYMBOLS * 10)) {
        fprintf(stderr, "Failed to initialize memory pool.\n");
        return EXIT_FAILURE;
    }

    size_t num_frames = 5;
    NFAPI_RX_FRAME_T* frames = initNfapiRxFrames(num_frames, 2);

    if (!frames) {
        fprintf(stderr, "Failed to initialize RX frames.\n");
        return EXIT_FAILURE;
    }

    // Example processing and cleanup
    for (size_t i = 0; i < num_frames; ++i) {
        printf("Frame %zu: UE_INDEX=%u, Symbols=%zu\n", i, frames[i].UE_INDEX, frames[i].num_symbols);
    }

    freeNfapiRxFrames(frames, num_frames);

    return EXIT_SUCCESS;
}
