// Global mutex for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
FrameInfo* createFrameInfoArray(size_t numFrames);
void freeFrameInfoArray(FrameInfo *frames, size_t numFrames);
void populateRandomData(ChannelMeasurement *measurements, size_t numMeasurements);

// Main function to dynamically allocate and initialize FrameInfo structures.
FrameInfo* createFrameInfoArray(size_t numFrames) {
    if (numFrames == 0) return NULL;

    pthread_mutex_lock(&lock);

    FrameInfo *frames = malloc(numFrames * sizeof(FrameInfo));
    if (!frames) {
        perror("Failed to allocate memory for frames");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < numFrames; ++i) {
        frames[i].timestamp = time(NULL); // Use current timestamp
        frames[i].sequenceNumber = i + 1; // Simple sequence number

        size_t numMeasurements = rand() % 10 + 1; // Random number of measurements (1-10)
        frames[i].numMeasurements = numMeasurements;
        frames[i].measurements = malloc(numMeasurements * sizeof(ChannelMeasurement));

        if (!frames[i].measurements) {
            perror("Failed to allocate memory for channel measurements");

            // Free previously allocated resources
            for (size_t j = 0; j < i; ++j) {
                free(frames[j].measurements);
            }
            free(frames);

            pthread_mutex_unlock(&lock);
            return NULL;
        }

        populateRandomData(frames[i].measurements, numMeasurements);

        // Randomly assign metadata
        frames[i].RX_UE_INFORMATION_TAG = rand() % 1000;   // Simulated tag
        frames[i].RNTI = rand() % 256;                      // Simulated RNTI
        frames[i].CRCFLAG = (rand() & 1);                   // Random CRC flag
    }

    pthread_mutex_unlock(&lock);
    return frames;
}

// Function to populate random data for ChannelMeasurement structures.
void populateRandomData(ChannelMeasurement *measurements, size_t numMeasurements) {
    for (size_t i = 0; i < numMeasurements; ++i) {
        measurements[i].frequency = rand() % 10000 + 1;   // Random frequency
        measurements[i].signalStrength = rand() % 100 - 50;// Random signal strength (-50 to 49)
        measurements[i].noiseLevel = rand() % 30 - 15;    // Random noise level (-15 to 14)
    }
}

// Function to free allocated memory for FrameInfo structures.
void freeFrameInfoArray(FrameInfo *frames, size_t numFrames) {
    if (!frames) return;

    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < numFrames; ++i) {
        if (frames[i].measurements) {
            free(frames[i].measurements);
        }
    }

    free(frames);
    pthread_mutex_unlock(&lock);
}

// Example usage of the functions.
int main() {
    size_t numFrames = 5;
    FrameInfo *frames = createFrameInfoArray(numFrames);

    if (frames) {
        // Assume validation and processing happens here
        printf("Successfully created %zu frames.\n", numFrames);

        freeFrameInfoArray(frames, numFrames);
    } else {
        fprintf(stderr, "Failed to create frame information array.\n");
    }

    return 0;
}
