    while (count < INPUT_SIZE) {
        if (scanf("%d", &numbers[count]) != 1) {
            fprintf(stderr, "Malformed input encountered\n");
            break;
        }
        ++count;
    }

    // Find the maximum integer
    int maxNumber = findMax(numbers, count);
