    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, processNfarxIndications, NULL) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return EXIT_FAILURE;
    }

    if (pthread_join(thread_id, NULL) != 0) {
