#define MAX_LIST_SIZE 100
#define RX_UE_INFORMATION_TAG_MASK 0xFFFF
#define RNTI_POOL_SIZE 256

typedef struct {
    int valid;
    unsigned short rx_ue_information_tag;
    unsigned short rnti;
    unsigned char crc_flag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned char valid_rx_ue_information_tag:1;
    unsigned short rx_ue_information_tag;
    unsigned char valid_rnti:1;
    unsigned short rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

static unsigned short rnti_pool[RNTI_POOL_SIZE];
static int available_rntis = RNTI_POOL_SIZE;

void initializeRNTIPool() {
    for (int i = 0; i < RNTI_POOL_SIZE; i++) {
        rnti_pool[i] = rand() % RX_UE_INFORMATION_TAG_MASK + 1;
    }
}

unsigned short allocateRNTI() {
    if (available_rntis > 0) {
        return rnti_pool[--available_rntis];
    } else {
        fprintf(stderr, "Error: No RNTI resources available\n");
        exit(EXIT_FAILURE);
    }
}

void releaseRNTI(unsigned short rnti) {
    if (available_rntis < RNTI_POOL_SIZE) {
        rnti_pool[available_rntis++] = rnti;
    }
}

int findMax(int *arr, int size) {
    if (size <= 0) return INT_MIN;

    int max_val = arr[0];
    for (int i = 1; i < size; ++i) {
        if (arr[i] > max_val) {
            max_val = arr[i];
        }
    }
    return max_val;
}

void processNfarxIndications(NFAPI_CRC_INDICATION_PDU_T *list, int list_size, int *integers, int num_ints) {
    srand(time(NULL));

    initializeRNTIPool();

    for (int i = 0; i < list_size; ++i) {
        unsigned short tag = rand() % RX_UE_INFORMATION_TAG_MASK + 1;
        unsigned short rnti;

        do {
            rnti = allocateRNTI();
        } while (rnti == list[i].rx_ue_information_tag);

        list[i].valid_rx_ue_information_tag = 1;
        list[i].rx_ue_information_tag = tag;
        list[i].valid_rnti = 1;
        list[i].rnti = rnti;
        list[i].crc_indication_rel8_tag.crc_flag = rand() % 2;

        releaseRNTI(rnti);
    }

    int max_integer = findMax(integers, num_ints);
    printf("Maximum integer: %d\n", max_integer);
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T list[MAX_LIST_SIZE];
    int integers[100];
    int num_ints;

    printf("Enter number of integers to process: ");
    if (scanf("%d", &num_ints) != 1 || num_ints <= 0 || num_ints > sizeof(integers) / sizeof(integers[0])) {
        fprintf(stderr, "Error: Invalid number of integers\n");
        return EXIT_FAILURE;
    }

    printf("Enter integers:\n");
    for (int i = 0; i < num_ints; ++i) {
        if (scanf("%d", &integers[i]) != 1) {
            fprintf(stderr, "Error: Invalid integer input at position %d\n", i);
            return EXIT_FAILURE;
        }
    }

    processNfarxIndications(list, MAX_LIST_SIZE, integers, num_ints);

    return 0;
}
