    NETWORK_ENTITY_STATS stats;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    int size;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} StatsList;

// Initialize the list
void initStatsList(StatsList* list) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->cond, NULL);
}

// Add a new entry to the list
void addEntry(StatsList* list, NETWORK_ENTITY_STATS stats) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return;

    newNode->stats = stats;
    newNode->next = NULL;

    pthread_mutex_lock(&list->mutex);

    while (list->size >= MAX_ENTRIES) {
        pthread_cond_wait(&list->cond, &list->mutex);
    }

    if (list->tail) {
        list->tail->next = newNode;
    } else {
        list->head = newNode;
    }
    list->tail = newNode;
    list->size++;

    pthread_mutex_unlock(&list->mutex);
}

// Remove the least recently used entry
void removeLruEntry(StatsList* list) {
    if (!list->head) return;

    Node* temp = list->head;
    list->head = list->head->next;
    free(temp);
    list->size--;

    if (!list->head) {
        list->tail = NULL;
    }
}

