#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LIST_SIZE 100

typedef struct {
    int rnti;
    int crcFlag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int some_tag_data; // Placeholder for RX_UE_INFORMATION_TAG data.
} RX_UE_INFORMATION_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rxTag;
    int rnti;
    CRC_INDICATION_REL8_TAG crcIndication;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

// Metadata cache for lazy loading
typedef struct {
    int rnti;
    int metadata;
} UE_METADATA;

static NFAPI_CRC_INDICATION_PDU_T *head = NULL, *tail = NULL;
static int listSize = 0;
static UE_METADATA *metadataCache = NULL;
static int cacheSize = 0;

void fetchMetadata(int rnti, int *metadata) {
    // Simulate fetching metadata from an external data source
    *metadata = (rnti % 2 == 0) ? 1 : 0; // Placeholder logic for metadata
}

void addEntry(NFAPI_CRC_INDICATION_PDU_T **entry) {
    if (listSize >= MAX_LIST_SIZE) {
        NFAPI_CRC_INDICATION_PDU_T *oldest = head;
        head = head->next;
        free(oldest);
        listSize--;
    }

    *entry = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    (*entry)->next = NULL;

    if (tail) {
        tail->next = *entry;
    } else {
        head = *entry;
    }

    tail = *entry;
    listSize++;
}

void removeEntry(int rnti) {
    NFAPI_CRC_INDICATION_PDU_T **current = &head, *temp;

    while (*current) {
        if ((*current)->rnti == rnti) {
            temp = *current;
            *current = (*current)->next;

            if (tail == temp) tail = NULL;
            free(temp);
            listSize--;
            return;
        }
        current = &(*current)->next;
    }
}

void updateCRCFlag(int rnti, int newFlag) {
    NFAPI_CRC_INDICATION_PDU_T *entry = head;

    while (entry) {
        if (entry->rnti == rnti) {
            entry->crcIndication.crcFlag = newFlag;
            return;
        }
        entry = entry->next;
    }

    int metadata;
    fetchMetadata(rnti, &metadata);
    updateCRCFlag(rnti, metadata ? 1 : newFlag);
}

void lazyLoadMetadata(int rnti) {
    UE_METADATA *newEntry = realloc(metadataCache, (cacheSize + 1) * sizeof(UE_METADATA));

    if (!newEntry) return;

    metadataCache = newEntry;
    fetchMetadata(rnti, &metadataCache[cacheSize].metadata);
    metadataCache[cacheSize].rnti = rnti;
    cacheSize++;
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T *entry;

    // Example usage
    addEntry(&entry);
    entry->rxTag.some_tag_data = 42; // Assign some data
    entry->rnti = 12345;
    entry->crcIndication.crcFlag = rand() % 2;

    removeEntry(12345);

    updateCRCFlag(12345, 1);

    lazyLoadMetadata(67890);

    return 0;
}
