#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>

#define MAX_ELEMENTS 10000

// Define the NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    uint16_t RNTI;
    uint8_t RX_UE_INFORMATION_TAG;
    uint32_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG; // Randomly set value between 0 and 1
} NFAPI_CRC_INDICATION_PDU_T;

// Define the node for a linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Define the hash table structure
typedef struct {
    Node** buckets;
    size_t num_buckets;
    pthread_mutex_t* locks;
} HashTable;

// Function prototypes
HashTable* create_hash_table(size_t num_buckets);
void destroy_hash_table(HashTable* ht);
int hash_function(uint16_t rnti, size_t num_buckets);
Node* create_node(NFAPI_CRC_INDICATION_PDU_T data);
void insert_ht(HashTable* ht, NFAPI_CRC_INDICATION_PDU_T data);
NFAPI_CRC_INDICATION_PDU_T* retrieve_ht(HashTable* ht, uint16_t rnti);
void free_node(Node* node);

// Create a new hash table
HashTable* create_hash_table(size_t num_buckets) {
    HashTable* ht = (HashTable*)malloc(sizeof(HashTable));
    if (!ht) return NULL;

    ht->buckets = (Node**)calloc(num_buckets, sizeof(Node*));
    if (!ht->buckets) {
        free(ht);
        return NULL;
    }

    ht->num_buckets = num_buckets;
    ht->locks = (pthread_mutex_t*)malloc(num_buckets * sizeof(pthread_mutex_t));
    if (!ht->locks) {
        free(ht->buckets);
        free(ht);
        return NULL;
    }

    for (size_t i = 0; i < num_buckets; ++i) {
        pthread_mutex_init(&ht->locks[i], NULL);
    }

    return ht;
}

// Destroy the hash table
void destroy_hash_table(HashTable* ht) {
    if (!ht) return;

    for (size_t i = 0; i < ht->num_buckets; ++i) {
        Node* current = ht->buckets[i];
        while (current) {
            Node* temp = current;
            current = current->next;
            free_node(temp);
        }
        pthread_mutex_destroy(&ht->locks[i]);
    }

    free(ht->buckets);
    free(ht->locks);
    free(ht);
}

// Hash function for RNTI
int hash_function(uint16_t rnti, size_t num_buckets) {
    return rnti % num_buckets;
}

// Create a new node
Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;

    node->data = data;
    node->next = NULL;
    return node;
}

// Insert data into the hash table
void insert_ht(HashTable* ht, NFAPI_CRC_INDICATION_PDU_T data) {
    int bucket_index = hash_function(data.RNTI, ht->num_buckets);
    pthread_mutex_lock(&ht->locks[bucket_index]);

    Node** head = &ht->buckets[bucket_index];
    while (*head && (*head)->data.RNTI != data.RNTI) {
        head = &(*head)->next;
    }

    if (*head) {
        // Update existing node
        (*head)->data.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    } else {
        // Insert new node
        Node* new_node = create_node(data);
        if (!new_node) {
            pthread_mutex_unlock(&ht->locks[bucket_index]);
            return;
        }
        new_node->next = *head;
        *head = new_node;
    }

    pthread_mutex_unlock(&ht->locks[bucket_index]);
}

// Retrieve data from the hash table
NFAPI_CRC_INDICATION_PDU_T* retrieve_ht(HashTable* ht, uint16_t rnti) {
    int bucket_index = hash_function(rnti, ht->num_buckets);
    pthread_mutex_lock(&ht->locks[bucket_index]);

    Node* current = ht->buckets[bucket_index];
    while (current && current->data.RNTI != rnti) {
        current = current->next;
    }

    NFAPI_CRC_INDICATION_PDU_T* result = NULL;
    if (current) {
        result = &current->data;
    }

    pthread_mutex_unlock(&ht->locks[bucket_index]);
    return result;
}

// Free a node
void free_node(Node* node) {
    if (!node) return;
    free(node);
}

int main() {
    // Example usage
    HashTable* ht = create_hash_table(1000); // 1000 buckets for load balancing

    if (!ht) {
        fprintf(stderr, "Failed to create hash table\n");
        return EXIT_FAILURE;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu = { .RNTI = 1234, .RX_UE_INFORMATION_TAG = 1, .CRC_INDICATION_REL8_TAG = 0xABCDEF };
    insert_ht(ht, pdu);

    NFAPI_CRC_INDICATION_PDU_T* retrieved = retrieve_ht(ht, 1234);
    if (retrieved) {
        printf("RNTI: %u, CRCFLAG: %d\n", retrieved->RNTI, retrieved->CRCFLAG);
    }

    destroy_hash_table(ht);
    return EXIT_SUCCESS;
}
```

### Trade-offs and Evaluation:
- **Data Structure**: A hash table with separate chaining (linked lists) is chosen for its balance between memory usage and access speed. It provides average O(1) time complexity for insertions and lookups.
- **Thread Safety**: Each bucket in the hash table has an associated mutex lock to minimize contention, allowing multiple threads to operate on different buckets concurrently.
- **Scalability**: The number of buckets can be adjusted based on expected load, providing flexibility for varying numbers of UEs.
- **Memory Management**: Handles memory allocation failures gracefully and ensures all allocated resources are freed appropriately.
- **Complexity**: Moderate complexity due to the use of mutex locks and dynamic memory management, but manageable with clear separation of concerns.']

