import logging
import time
from queue import Queue, Empty

# Constants
MAX_INPUT_LENGTH = 1024
VALID_CRC_INDICATORS = {0xFFFFFFFF, 0x00000000}
RATE_LIMIT = 100  # requests per second

# Configure logging
logging.basicConfig(level=logging.INFO)

class NFAPI_CRC_INDICATION_PDU_T:
    def __init__(self, rnti, crcIndicator):
        self.rnti = rnti
        self.crcIndicator = crcIndicator


def generateNFAPCrcIndications(num_packets):
    generated_rntis = set()
    packets = []

    for _ in range(num_packets):
        rnti = generate_unique_rnti(generated_rntis)
        if not rnti:
            logging.error("Failed to generate unique RNTI")
            continue

        crc_indicator = generate_crc_indicator()
        if crc_indicator not in VALID_CRC_INDICATORS:
            logging.error(f"Invalid CRC indicator: {crc_indicator}")
            continue

        packets.append(NFAPI_CRC_INDICATION_PDU_T(rnti, crc_indicator))

    return packets


def generate_unique_rnti(existing_rntis):
    rnti = random.randint(0x0001, 0xFFFFF)
    if rnti in existing_rntis:
        return None
    existing_rntis.add(rnti)
    return rnti


def generate_crc_indicator():
    # Simulate valid CRC indicator generation
    return random.choice(list(VALID_CRC_INDICATORS))


def calculateMD5Hash(data_stream):
    if len(data_stream) > MAX_INPUT_LENGTH:
        raise ValueError("Input length exceeds maximum allowed")

    md5 = hashlib.md5()
    for chunk in data_stream:
        md5.update(chunk.encode('utf-8'))

    return md5.hexdigest()


def fetch_configuration():
    # Simulate fetching configuration from an external source
    time.sleep(1)  # simulate network delay
    return {"config_key": "config_value"}


class RateLimiter:
    def __init__(self, rate_limit):
        self.rate_limit = rate_limit
        self.allowance = rate_limit
        self.last_check = time.monotonic()

    def is_allowed(self):
        current = time.monotonic()
        elapsed = current - self.last_check

        self.last_check = current
        self.allowance += elapsed * (self.rate_limit / 1)

        if self.allowance > self.rate_limit:
            self.allowance = self.rate_limit

        if self.allowance < 1.0:
            return False
        else:
            self.allowance -= 1.0
            return True


def process_requests(request_queue, rate_limiter):
    while True:
        try:
            data_stream = request_queue.get(timeout=2)
        except Empty:
            continue

        if not rate_limiter.is_allowed():
            logging.warning("Rate limit exceeded, delaying processing")
            time.sleep(0.1)  # backpressure mechanism
            continue

        try:
            hash_result = calculateMD5Hash(data_stream)
            logging.info(f"Processed data: {hash_result}")
        except Exception as e:
            logging.error(f"Error processing request: {e}")


def main():
    config = fetch_configuration()
    logging.info(f"Fetched configuration: {config}")

    rate_limiter = RateLimiter(RATE_LIMIT)

    request_queue = Queue()

    # Start worker threads
    for _ in range(5):
        threading.Thread(target=process_requests, args=(request_queue, rate_limiter), daemon=True).start()

    while True:
        data_stream = input("Enter data to process: ")
        request_queue.put(data_stream)


if __name__ == "__main__":
    main()
