void updateTBSValue(LTE_DL_FRAMEINFO *frameArray, size_t numFrames, int frameIndex, int newTBS);
void resizeFrameArray(LTE_DL_FRAMEINFO **frameArray, size_t currentSize, size_t newSize);
bool validateTBS(int tbs);
void freeFrameArray(LTE_DL_FRAMEINFO *frameArray);

// Function definitions
bool initializeFrameArray(LTE_DL_FRAMEINFO **frameArray, size_t initialSize) {
    if (!frameArray) return false;

    *frameArray = (LTE_DL_FRAMEINFO *)malloc(initialSize * sizeof(LTE_DL_FRAMEINFO));
    if (*frameArray == NULL) return false;

    for (size_t i = 0; i < initialSize; ++i) {
        (*frameArray)[i].frameNum = -1; // Invalid frame number indicates unused slot
        (*frameArray)[i].tbs = 0;
    }

    return true;
}

void updateTBSValue(LTE_DL_FRAMEINFO *frameArray, size_t numFrames, int frameIndex, int newTBS) {
    if (frameArray == NULL || frameIndex < 0 || frameIndex >= (int)numFrames) return;

    if (!validateTBS(newTBS)) {
        printf("Invalid TBS value: %d\n", newTBS);
        return;
    }

    if (frameArray[frameIndex].frameNum == -1) {
        // New entry
        frameArray[frameIndex].frameNum = frameIndex;
    }

    frameArray[frameIndex].tbs = newTBS;
}

void resizeFrameArray(LTE_DL_FRAMEINFO **frameArray, size_t currentSize, size_t newSize) {
    if (!frameArray || *frameArray == NULL) return;

    LTE_DL_FRAMEINFO *newArray = (LTE_DL_FRAMEINFO *)realloc(*frameArray, newSize * sizeof(LTE_DL_FRAMEINFO));
    if (newArray == NULL) return; // Handle reallocation failure

    for (size_t i = currentSize; i < newSize; ++i) {
        newArray[i].frameNum = -1;
        newArray[i].tbs = 0;
    }

    *frameArray = newArray;
}

bool validateTBS(int tbs) {
    const int MIN_TBS = 0;
    const int MAX_TBS = 1024;

    return (tbs >= MIN_TBS && tbs <= MAX_TBS);
}

void freeFrameArray(LTE_DL_FRAMEINFO *frameArray) {
    if (frameArray != NULL) {
        free(frameArray);
    }
}

