} NR_Uplink_TransportChannelInfo;

#define INITIAL_ARRAY_SIZE 10
#define MAX_MCS_VALUE 28

// Function prototypes
NR_Uplink_TransportChannelInfo* initTransportChannels(const char *xmlConfigPath, int *count);
void freeTransportChannels(NR_Uplink_TransportChannelInfo *channels, int count);
static void resizeArray(NR_Uplink_TransportChannelInfo **channels, int *size, int newCapacity);
static int parseXMLConfiguration(const char *xmlConfigPath, NR_Uplink_TransportChannelInfo **channels);

NR_Uplink_TransportChannelInfo* initTransportChannels(const char *xmlConfigPath, int *count) {
    *count = 0;
    NR_Uplink_TransportChannelInfo *channels = malloc(INITIAL_ARRAY_SIZE * sizeof(NR_Uplink_TransportChannelInfo));
    if (channels == NULL) {
        fprintf(stderr, "Failed to allocate memory for transport channels.\n");
        return NULL;
    }

    int capacity = INITIAL_ARRAY_SIZE;

    // Parse XML configuration
    if (!parseXMLConfiguration(xmlConfigPath, &channels)) {
        freeTransportChannels(channels, *count);
        return NULL;
    }

    // Check and resize array as necessary
    if (*count > capacity) {
        resizeArray(&channels, &capacity, 2 * capacity); // Double the size for expansion
    }

    *count = capacity; // Return final count of channels loaded
    return channels;
}

void freeTransportChannels(NR_Uplink_TransportChannelInfo *channels, int count) {
    if (channels != NULL) {
        free(channels);
    }
}

static void resizeArray(NR_Uplink_TransportChannelInfo **channels, int *size, int newCapacity) {
    NR_Uplink_TransportChannelInfo *newChannels = realloc(*channels, newCapacity * sizeof(NR_Uplink_TransportChannelInfo));
    if (newChannels == NULL) {
        fprintf(stderr, "Failed to reallocate memory for transport channels.\n");
        return;
    }
    *channels = newChannels;
    *size = newCapacity;
}

static int parseXMLConfiguration(const char *xmlConfigPath, NR_Uplink_TransportChannelInfo **channels) {
    xmlDocPtr doc = xmlReadFile(xmlConfigPath, NULL, 0);
    if (doc == NULL) {
        fprintf(stderr, "Failed to read XML configuration file.\n");
        return 0;
    }

    xmlNode *root = xmlDocGetRootElement(doc);

    // Assuming root node has child nodes as individual transport channels
    for (xmlNode *channelNode = root->children; channelNode != NULL; channelNode = channelNode->next) {
        if (channelNode->type == XML_ELEMENT_NODE && strcmp((const char *)channelNode->name, "TransportChannel") == 0) {
            xmlChar *idAttr = xmlGetProp(channelNode, (const xmlChar *)"id");
            int transportChannelId = atoi((const char *)idAttr);
            xmlFree(idAttr);

            xmlChar *mcsAttr = xmlGetProp(channelNode, (const xmlChar *)"mcs");
            int mcsValue = atoi((const char *)mcsAttr);
            xmlFree(mcsAttr);

            if (mcsValue < 0 || mcsValue > MAX_MCS_VALUE) {
                fprintf(stderr, "Invalid MCS value %d for transport channel id %d. Skipping.\n", mcsValue, transportChannelId);
                continue;
            }

            // Check current capacity and resize if needed
            int currentCount = *channels ? (*channels)[0].transportChannelId : 0;
            if (currentCount >= INITIAL_ARRAY_SIZE) {
                resizeArray(channels, &INITIAL_ARRAY_SIZE, 2 * INITIAL_ARRAY_SIZE);
            }

            NR_Uplink_TransportChannelInfo channel;
            channel.transportChannelId = transportChannelId;
            channel.mcsValue = mcsValue;

            (*channels)[currentCount] = channel;
        }
    }

    xmlFreeDoc(doc);
    return 1; // Successful parsing
}
```

