#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ARRAY_SIZE 1024

typedef struct {
    int TBS_value;
} LTE_DL_FRAMEINFO;

typedef struct {
    char UE_info[256];
    int RNTI;
    int CRC_flag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    LTE_DL_FRAMEINFO *lte_frameinfo_array;
    size_t lte_frameinfo_count;
    size_t lte_frameinfo_capacity;

    NFAPI_CRC_INDICATION_PDU_T *crc_pdu_array;
    size_t crc_pdu_count;
    size_t crc_pdu_capacity;

    pthread_mutex_t lock;
} ArrayManager;

void initialize_arrays(ArrayManager *manager, size_t initial_capacity) {
    manager->lte_frameinfo_array = malloc(initial_capacity * sizeof(LTE_DL_FRAMEINFO));
    manager->lte_frameinfo_count = 0;
    manager->lte_frameinfo_capacity = initial_capacity;

    manager->crc_pdu_array = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->crc_pdu_count = 0;
    manager->crc_pdu_capacity = initial_capacity;

    pthread_mutex_init(&manager->lock, NULL);
}

void resize_array_if_needed(ArrayManager *manager, const char *array_name) {
    size_t new_capacity = (size_t)(manager->lte_frameinfo_capacity * 1.5);
    if (new_capacity > MAX_ARRAY_SIZE) {
        fprintf(stderr, "Maximum array capacity reached for %s.\n", array_name);
        return;
    }

    void **array_to_resize = (strcmp(array_name, "LTE_DL_FRAMEINFO") == 0)
                                ? (void **)&manager->lte_frameinfo_array
                                : (void **)&manager->crc_pdu_array;

    size_t *count_var = (strcmp(array_name, "LTE_DL_FRAMEINFO") == 0)
                            ? &manager->lte_frameinfo_count
                            : &manager->crc_pdu_count;

    size_t *capacity_var = (strcmp(array_name, "LTE_DL_FRAMEINFO") == 0)
                              ? &manager->lte_frameinfo_capacity
                              : &manager->crc_pdu_capacity;

    void **new_array = realloc(*array_to_resize, new_capacity * sizeof(LTE_DL_FRAMEINFO));
    if (!new_array) {
        perror("Failed to resize array");
        free(manager->lte_frameinfo_array);
        free(manager->crc_pdu_array);
        pthread_mutex_destroy(&manager->lock);
        exit(EXIT_FAILURE);
    }
    *array_to_resize = new_array;
    *capacity_var = new_capacity;
}

void add_lte_dl_frameinfo(ArrayManager *manager, int TBS_value) {
    pthread_mutex_lock(&manager->lock);

    if (manager->lte_frameinfo_count == manager->lte_frameinfo_capacity) {
        resize_array_if_needed(manager, "LTE_DL_FRAMEINFO");
    }

    if (manager->lte_frameinfo_count < manager->lte_frameinfo_capacity) {
        manager->lte_frameinfo_array[manager->lte_frameinfo_count].TBS_value = TBS_value;
        manager->lte_frameinfo_count++;
    } else {
        fprintf(stderr, "Failed to add LTE_DL_FRAMEINFO: array is full.\n");
    }

    pthread_mutex_unlock(&manager->lock);
}

void add_crc_pdu(ArrayManager *manager, const char *UE_info, int RNTI, int CRC_flag) {
    pthread_mutex_lock(&manager->lock);

    if (manager->crc_pdu_count == manager->crc_pdu_capacity) {
        resize_array_if_needed(manager, "NFAPI_CRC_INDICATION_PDU_T");
    }

    if (manager->crc_pdu_count < manager->crc_pdu_capacity) {
        strncpy(manager->crc_pdu_array[manager->crc_pdu_count].UE_info, UE_info, sizeof(manager->crc_pdu_array[0].UE_info) - 1);
        manager->crc_pdu_array[manager->crc_pdu_count].RNTI = RNTI;
        manager->crc_pdu_array[manager->crc_pdu_count].CRC_flag = CRC_flag;
        manager->crc_pdu_count++;
    } else {
        fprintf(stderr, "Failed to add NFAPI_CRC_INDICATION_PDU_T: array is full.\n");
    }

    pthread_mutex_unlock(&manager->lock);
}

void cleanup_arrays(ArrayManager *manager) {
    free(manager->lte_frameinfo_array);
    free(manager->crc_pdu_array);
    pthread_mutex_destroy(&manager->lock);
}

int main() {
    ArrayManager manager;
    initialize_arrays(&manager, 16);

    add_lte_dl_frameinfo(&manager, 1000);
    add_crc_pdu(&manager, "UE_1234", 5678, 1);

    cleanup_arrays(&manager);

    return 0;
}
