#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

#define MAX_ENTRIES 1024

typedef struct {
    uint16_t RNTI;
    uint8_t PCI;
} RX_UE_INFORMATION_TAG;

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

void log_entry(uint16_t RNTI, uint8_t PCI, int CRCFLAG) {
    printf("RNTI: %u, PCI: %d, CRCFLAG: %d\n", RNTI, PCI, CRCFLAG);
}

int generate_unique_RNTI(uint16_t *rnti_array, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        uint16_t rnti;
        do {
            rnti = rand() % 65536; // Generate a random RNTI
        } while (bsearch(&rnti, rnti_array, i, sizeof(uint16_t), (int(*)(const void*, const void*))strcmp) != NULL);
        rnti_array[i] = rnti;
    }
    return 0;
}

uint8_t generate_unique_PCI(uint8_t *pci_array, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        uint8_t pci;
        do {
            pci = rand() % 57; // Generate a random PCI
        } while (bsearch(&pci, pci_array, i, sizeof(uint8_t), (int(*)(const void*, const void*))strcmp) != NULL);
        pci_array[i] = pci;
    }
    return pci_array[count - 1];
}

void initialize_crc_flag(int *crc_flags, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        crc_flags[i] = rand() % 2; // Randomly set CRCFLAG to 0 or 1
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_and_initialize_array(size_t n, int enable_logging, int serialize) {
    if (n > MAX_ENTRIES) {
        fprintf(stderr, "Number of entries exceeds maximum limit.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *array = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        perror("Failed to allocate memory for the array");
        return NULL;
    }

    uint16_t rnti_array[MAX_ENTRIES];
    uint8_t pci_array[MAX_ENTRIES];
    int crc_flags[MAX_ENTRIES];

    generate_unique_RNTI(rnti_array, n);
    generate_unique_PCI(pci_array, n);
    initialize_crc_flag(crc_flags, n);

    for (size_t i = 0; i < n; ++i) {
        array[i].rx_ue_information_tag.RNTI = rnti_array[i];
        array[i].rx_ue_information_tag.PCI = pci_array[i];
        array[i].crc_indication_rel8_tag.CRCFLAG = crc_flags[i];

        if (enable_logging) {
            log_entry(array[i].rx_ue_information_tag.RNTI, array[i].rx_ue_information_tag.PCI, array[i].crc_indication_rel8_tag.CRCFLAG);
        }
    }

    if (serialize) {
        FILE *file = fopen("serialized_data.bin", "wb");
        if (!file) {
            perror("Failed to open file for serialization");
            free(array);
            return NULL;
        }
        fwrite(array, sizeof(NFAPI_CRC_INDICATION_PDU_T), n, file);
        fclose(file);
    }

    return array;
}

int main() {
    srand((unsigned int)time(NULL)); // Seed the random number generator

    size_t num_entries = 100; // Example: Allocate an array for 100 entries
    NFAPI_CRC_INDICATION_PDU_T *array = allocate_and_initialize_array(num_entries, 1, 1);

    if (array) {
        printf("Array allocated and initialized successfully.\n");
        free(array);
    }

    return 0;
}
