// Function to simulate external data source fetching distinct and valid RNTIs
bool fetch_valid_rnti(unsigned short *rnti, bool *used_rntis) {
    static const unsigned short MAX_RNTI = 65535; // Example max value for RNTI
    srand(time(NULL)); // Seed the random number generator

    while (1) {
        *rnti = rand() % MAX_RNTI + 1;
        if (!used_rntis[*rnti]) { // Check if the RNTI is already used
            return true;
        }
    }
}

// Function to calculate CRCFLAG based on RNTI and index (custom logic)
bool calculate_crcflag(unsigned short rnti, int index) {
    return ((rnti & 0x01) ^ (index % 2)) == 1; // Example non-trivial calculation
}

NFAPI_CRC_INDICATION_PDU_T* create_nfa_list(int ue_count, int *actual_ue_count) {
    if (ue_count > MAX_UE_COUNT || ue_count < 1) {
        fprintf(stderr, "Error: Invalid UE count. Must be between 1 and %d.\n", MAX_UE_COUNT);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *list = malloc(ue_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    bool used_rntis[MAX_UE_COUNT + 1] = {false}; // Track used RNTIs
    for (int i = 0; i < ue_count; ++i) {
        unsigned short rnti;

        if (!fetch_valid_rnti(&rnti, used_rntis)) {
            fprintf(stderr, "Error: Failed to fetch a valid RNTI.\n");
            free(list);
            return NULL;
        }

        // Mark the RNTI as used
        used_rntis[rnti] = true;

        list[i].RNTI = rnti;
        list[i].CRC_INDICATION_REL8_TAG.RX_UE_INFORMATION_TAG = i + 1; // Example tag value

        // Calculate CRCFLAG and set it in the structure
        list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = calculate_crcflag(rnti, i);
    }

    *actual_ue_count = ue_count;
    return list;
}

void free_nfa_list(NFAPI_CRC_INDICATION_PDU_T* list) {
    if (list) {
        free(list);
    }
}
