['Below is an implementation of the described C function managing a dynamic array of `NFAPI_CRC_INDICATION_PDU_T` structures with thread-safe operations and memory efficiency.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_HISTORY 100

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[4];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t count;
    pthread_mutex_t mutex;
} RollingHistory;

RollingHistory history = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

// Utility function to generate a random CRCFLAG
void set_random_crcflag(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu != NULL) {
        // Simulating setting of a random CRCFLAG
        for (int i = 0; i < sizeof(pdu->CRC_INDICATION_REL8_TAG); ++i) {
            pdu->CRC_INDICATION_REL8_TAG[i] = rand() % 256;
        }
    }
}

// Initialize the history with zeroed memory
void init_history(RollingHistory* h) {
    pthread_mutex_lock(&h->mutex);
    if (h->array != NULL) {
        free(h->array);
    }
    h->array = malloc(MAX_HISTORY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memset(h->array, 0, MAX_HISTORY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    h->count = 0;
    pthread_mutex_unlock(&h->mutex);
}

// Add a new element to the history
void add_to_history(RollingHistory* h, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&h->mutex);

    // Check for consecutive RNTI duplicates
    if (h->count > 0 && h->array[(h->count - 1) % MAX_HISTORY].RNTI == pdu->RNTI) {
        printf("Duplicate RNTI detected. Skipping addition.\n");
        pthread_mutex_unlock(&h->mutex);
        return;
    }

    // Insert the new element into history
    size_t index = h->count % MAX_HISTORY;
    memcpy(&h->array[index], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (h->count < MAX_HISTORY) {
        h->count++;
    }

    pthread_mutex_unlock(&h->mutex);
}

// Validate for duplicate RNTI within the array
void validate_no_duplicate_rnti(const RollingHistory* h) {
    pthread_mutex_lock(&h->mutex);

    for (size_t i = 0; i < h->count; ++i) {
        unsigned short currentRNTI = h->array[i].RNTI;
        for (size_t j = i + 1; j < h->count; ++j) {
            if (h->array[j].RNTI == currentRNTI) {
                printf("Duplicate RNTI found at index %zu and %zu\n", i, j);
                break;
            }
        }
    }

    pthread_mutex_unlock(&h->mutex);
}

// Cleanup function to free allocated memory
void cleanup_history(RollingHistory* h) {
    pthread_mutex_lock(&h->mutex);
    if (h->array != NULL) {
        free(h->array);
        h->array = NULL;
        h->count = 0;
    }
    pthread_mutex_unlock(&h->mutex);
}

int main() {
    init_history(&history);

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T pdu1 = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 100 };
    set_random_crcflag(&pdu1);
    add_to_history(&history, &pdu1);

    NFAPI_CRC_INDICATION_PDU_T pdu2 = { .RX_UE_INFORMATION_TAG = 2, .RNTI = 101 };
    set_random_crcflag(&pdu2);
    add_to_history(&history, &pdu2);

    validate_no_duplicate_rnti(&history);

    cleanup_history(&history);
    return 0;
}
```

### Trade-offs Evaluation

- **Efficiency vs. Usability**: The use of a mutex ensures thread safety but can introduce some overhead in high-throughput scenarios. However, the simplicity and usability are maintained by providing straightforward functions for history management.

- **Maintainability vs. Scalability**: The code is designed to be easy to maintain with clear function responsibilities. It scales efficiently by using modular design patterns and limiting complexity within each module.

- **Throughput vs. Latency**: A balance is struck by employing a rolling array approach, which minimizes allocation overhead, combined with lightweight synchronization mechanisms (mutexes), ensuring both throughput and low latency are prioritized effectively.']

