```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdbool.h>

#define MAX_HISTORY 100

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
    size_t history[MAX_HISTORY];
    size_t history_index;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* da = malloc(sizeof(DynamicArray));
    if (!da) return NULL;

    da->array = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        free(da);
        return NULL;
    }

    da->size = 0;
    da->capacity = initial_capacity;
    pthread_mutex_init(&da->lock, NULL);
    memset(da->history, 0, sizeof(size_t) * MAX_HISTORY);
    da->history_index = 0;

    return da;
}

bool validate_rnti(DynamicArray* da, int rnti) {
    for (size_t i = 0; i < da->size; ++i) {
        if (da->array[i].RNTI == rnti) return false;
    }
    return true;
}

void add_pdu(DynamicArray* da, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&da->lock);

    if (!validate_rnti(da, pdu.RNTI)) {
        pthread_mutex_unlock(&da->lock);
        printf("Duplicate RNTI detected: %d\n", pdu.RNTI);
        return;
    }

    if (da->size == da->capacity) {
        size_t new_capacity = da->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&da->lock);
            return;
        }
        da->array = new_array;
        da->capacity = new_capacity;
    }

    da->array[da->size] = pdu;

    size_t index_to_log = (da->history_index + da->size) % MAX_HISTORY;
    da->history[index_to_log] = da->size;

    pthread_mutex_unlock(&da->lock);
}

void export_state(DynamicArray* da, const char* filename) {
    FILE* file = fopen(filename, "w");
    if (!file) return;

    for (size_t i = 0; i < da->size; ++i) {
        fprintf(file, "%d,%d,%d,%s\n", da->array[i].RX_UE_INFORMATION_TAG,
                da->array[i].RNTI, da->array[i].CRC_INDICATION_REL8_TAG,
                da->array[i].CRCFLAG ? "true" : "false");
    }

    for (size_t i = 0; i < MAX_HISTORY; ++i) {
        size_t index = (da->history_index + i) % MAX_HISTORY;
        if (index < da->size) {
            fprintf(file, "History: %d\n", da->array[da->history[index]].RNTI);
        }
    }

    fclose(file);
}

void free_dynamic_array(DynamicArray* da) {
    pthread_mutex_destroy(&da->lock);
    free(da->array);
    free(da);
}

// Unit test function prototypes
void test_add_duplicate_rnti();
void test_full_history_capacity();
void test_concurrent_updates();

int main() {
    // Example usage and unit tests
    DynamicArray* da = create_dynamic_array(10);

    NFAPI_CRC_INDICATION_PDU_T pdu1 = {1, 1001, 5, true};
    add_pdu(da, pdu1);

    export_state(da, "state.txt");

    test_add_duplicate_rnti();
    test_full_history_capacity();
    test_concurrent_updates();

    free_dynamic_array(da);
    return 0;
}

void test_add_duplicate_rnti() {
    DynamicArray* da = create_dynamic_array(10);
    NFAPI_CRC_INDICATION_PDU_T pdu1 = {1, 1001, 5, true};
    add_pdu(da, pdu1);

    // Attempt to add duplicate RNTI
    NFAPI_CRC_INDICATION_PDU_T pdu2 = {2, 1001, 6, false};
    add_pdu(da, pdu2); // Should not be added

    free_dynamic_array(da);
}

void test_full_history_capacity() {
    DynamicArray* da = create_dynamic_array(10);

    for (int i = 0; i < MAX_HISTORY + 10; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = {i, i * 100, i % 5, i % 2 == 0};
        add_pdu(da, pdu);
    }

    // Check if history is rolling correctly
    for (int i = MAX_HISTORY; i < MAX_HISTORY + 10; ++i) {
        size_t index = (da->history_index + i - 10) % MAX_HISTORY;
        printf("History RNTI: %d\n", da->array[da->history[index]].RNTI);
    }

    free_dynamic_array(da);
}

void test_concurrent_updates() {
    DynamicArray* da = create_dynamic_array(10);

    pthread_t threads[4];
    NFAPI_CRC_INDICATION_PDU_T pdu;

    for (int i = 0; i < 4; ++i) {
        pdu.RX_UE_INFORMATION_TAG = i + 1;
        pdu.RNTI = (i + 1) * 100;
        pdu.CRC_INDICATION_REL8_TAG = i % 5;
        pdu.CRCFLAG = i % 2 == 0;

        pthread_create(&threads[i], NULL, (void*(*)(void*))add_pdu, da);
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    free_dynamic_array(da);
}
```

