    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

bool allocateList(NFAPI_CRC_INDICATION_PDU_T **list, size_t count) {
    *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    return (*list != NULL);
}

void freeList(NFAPI_CRC_INDICATION_PDU_T *list) {
    if (list != NULL) {
        free(list);
    }
}

int findLargestInteger(int *arr, size_t count) {
    int max = arr[0];
    for (size_t i = 1; i < count; ++i) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

void processAndAggregateCRCIndications() {
    NFAPI_CRC_INDICATION_PDU_T *list = NULL;
    int *integers = NULL;
    size_t count = 0;

    if (!allocateList(&list, MAX_ELEMENTS)) {
        fprintf(stderr, "Memory allocation failed for CRC indication list.\n");
        return;
    }

    printf("Enter integers (non-negative), -1 to stop:\n");
    while (true) {
        int num;
        scanf("%d", &num);
        if (num == -1 || count >= MAX_ELEMENTS) break;

        if (num < 0 && num != -1) {
            fprintf(stderr, "Invalid input: negative number other than -1.\n");
            continue;
        }

        integers = realloc(integers, (count + 1) * sizeof(int));
        if (!integers) {
            fprintf(stderr, "Memory allocation failed for integer array.\n");
            freeList(list);
            return;
        }
        integers[count++] = num;
    }

    srand(time(NULL));
    int usedRNTIs[10000] = {0}; // Assume RNTI range is 0-9999

    for (size_t i = 0; i < count && i < MAX_ELEMENTS; ++i) {
        list[i].RX_UE_INFORMATION_TAG = rand() % 1000000;
        do {
            list[i].RNTI = rand() % 10000;
        } while (usedRNTIs[list[i].RNTI] == 1);
        usedRNTIs[list[i].RNTI] = 1;

        list[i].CRC_INDICATION_REL8_TAG = rand();

        if (i > 0) {
            list[i].CRCFLAG = !list[i - 1].CRCFLAG;
        } else {
            list[i].CRCFLAG = rand() % 2;
        }
    }

    int largestInteger = findLargestInteger(integers, count);
    printf("The largest integer is: %d\n", largestInteger);

    freeList(list);
    free(integers);
}

int main() {
    processAndAggregateCRCIndications();
    return 0;
}
