    int CRC_INDICATION_REL8_TAG;
    char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

// Function declarations
DynamicArray* create_dynamic_array();
void destroy_dynamic_array(DynamicArray* array);
int add_pdu_to_array(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T pdu);
void validate_no_consecutive_duplicates(DynamicArray* array);

DynamicArray* create_dynamic_array() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;
    array->head = array->tail = NULL;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    Node* current = array->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int add_pdu_to_array(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!array || !pthread_mutex_lock(&array->lock)) return 0;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&array->lock);
        return 0;
    }
    new_node->data = pdu;
    new_node->next = NULL;

    if (array->count == HISTORY_SIZE) {
        free(array->head);
        array->head = array->tail = new_node;
        array->count = 1;
    } else {
        if (!array->tail) {
            array->head = array->tail = new_node;
        } else {
            array->tail->next = new_node;
            array->tail = new_node;
        }
        array->count++;
    }

    pthread_mutex_unlock(&array->lock);
    return 1;
}

void validate_no_consecutive_duplicates(DynamicArray* array) {
    if (!array || !pthread_mutex_lock(&array->lock)) return;

    Node* current = array->head;
    while (current && current->next) {
        if (current->data.RNTI == current->next->data.RNTI) {
            // Handle duplicate RNTI
            printf("Duplicate RNTI detected: %d\n", current->data.RNTI);
        }
        current = current->next;
    }

    pthread_mutex_unlock(&array->lock);
}

