#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <json-c/json.h>

#define TAI_MAX 0x7FFF // Example maximum value for TAI
#define TAC_MAX 0xFF   // Example maximum value for TAC

typedef struct {
    uint16_t mme_id;
    uint32_t tai;  // Tracking Area Identity
    uint8_t tac;   // Tracking Area Code
} TAICfg;

typedef struct {
    TAICfg *configs;
    size_t count;
    pthread_mutex_t lock;
} TAICfgList;

int init_taicfg_list(TAICfgList *list, size_t max_count) {
    list->configs = (TAICfg *)malloc(max_count * sizeof(TAICfg));
    if (!list->configs) return -1; // Error in allocation
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return 0;
}

void free_taicfg_list(TAICfgList *list) {
    free(list->configs);
    pthread_mutex_destroy(&list->lock);
}

int generate_unique_values(uint32_t *tai, uint8_t *tac, size_t index, unsigned int seed) {
    srand(seed + (unsigned int)index);
    *tai = rand() % (TAI_MAX + 1);
    *tac = rand() % (TAC_MAX + 1);

    // Ensure uniqueness logic here
    return 0; 
}

int add_taicfg(TAICfgList *list, uint16_t mme_id) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->configs->max_count) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List full
    }

    TAICfg cfg;
    cfg.mme_id = mme_id;
    int ret = generate_unique_values(&cfg.tai, &cfg.tac, list->count, time(NULL));
    if (ret != 0) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Error in generation
    }

    list->configs[list->count++] = cfg;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int serialize_to_json(const TAICfgList *list, const char *filename) {
    json_object *j_array = json_object_new_array();

    for (size_t i = 0; i < list->count; ++i) {
        json_object *j_obj = json_object_new_object();
        json_object_object_add(j_obj, "mme_id", json_object_new_int(list->configs[i].mme_id));
        json_object_object_add(j_obj, "tai", json_object_new_int(list->configs[i].tai));
        json_object_object_add(j_obj, "tac", json_object_new_int(list->configs[i].tac));

        json_object_array_add(j_array, j_obj);
    }

    FILE *fp = fopen(filename, "w");
    if (!fp) return -1;

    const char *json_str = json_object_to_json_string(j_array);
    fputs(json_str, fp);

    fclose(fp);
    json_object_put(j_array); // Free memory
    return 0;
}

int deserialize_from_json(TAICfgList *list, const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) return -1;

    struct json_object *j_obj;
    struct json_object *j_array;

    j_obj = json_object_from_file(fp);
    fclose(fp);

    if (json_object_get_type(j_obj) != json_type_array)
        return -1; // Invalid JSON format

    j_array = json_object_object_get(j_obj, "array");
    size_t len = json_object_array_length(j_array);

    for (size_t i = 0; i < len; ++i) {
        struct json_object *j_cfg = json_object_array_get_idx(j_array, i);

        if (!json_object_is_type(j_cfg, json_type_object))
            continue;

        TAICfg cfg;
        json_object_object_get_ex(j_cfg, "mme_id", &cfg.mme_id);
        json_object_object_get_ex(j_cfg, "tai", &cfg.tai);
        json_object_object_get_ex(j_cfg, "tac", &cfg.tac);

        add_taicfg(list, cfg.mme_id); // Re-add to the list
    }

    json_object_put(j_obj); // Free memory
    return 0;
}

int main() {
    TAICfgList list;
    if (init_taicfg_list(&list, 100) != 0) {
        fprintf(stderr, "Failed to initialize TAI/TAC configuration list\n");
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < 10; ++i) { // Example usage
        if (add_taicfg(&list, i + 1) != 0) {
            fprintf(stderr, "Failed to add TAI/TAC configuration\n");
            break;
        }
    }

    if (serialize_to_json(&list, "configurations.json") != 0) {
        fprintf(stderr, "Failed to serialize configurations to JSON\n");
    }

    TAICfgList new_list;
    init_taicfg_list(&new_list, 100);
    if (deserialize_from_json(&new_list, "configurations.json") != 0) {
        fprintf(stderr, "Failed to deserialize configurations from JSON\n");
    }

    free_taicfg_list(&list);
    free_taicfg_list(&new_list);

    return EXIT_SUCCESS;
}
