        return;
    }

    size_t written = fwrite(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->size, file);
    if (written < list->size) {
        // Handle partial write
        fprintf(stderr, "Partial write occurred during serialization\n");
    }

    fclose(file);
}

void deserialize_list(DynamicList *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for reading\n");
        return;
    }

    size_t count = fread(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->capacity, file);
    if (ferror(file)) {
        // Handle read error
        fprintf(stderr, "Error occurred during deserialization\n");
    } else {
        list->size = count;
    }

    fclose(file);
}

void free_dynamic_list(DynamicList *list) {
    if (list) {
        free(list->data);
        free(list);
    }
}

int main() {
    size_t N = 50; // Initial number of entries
    unsigned int seed = 12345;

    init_random(seed);

    DynamicList *nfa_list = create_dynamic_list(INITIAL_CHUNK_SIZE);
    if (!nfa_list) return EXIT_FAILURE;

    for (size_t i = 0; i < N; ++i) {
        add_entry(nfa_list, seed, i);
    }

    serialize_list(nfa_list, "nfa_list.dat");

    free_dynamic_list(nfa_list);

    nfa_list = create_dynamic_list(INITIAL_CHUNK_SIZE);
    deserialize_list(nfa_list, "nfa_list.dat");

    free_dynamic_list(nfa_list);

    return EXIT_SUCCESS;
}
```

