#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_ELEMENTS 5000
#define LOGGING_ENABLED 1 // Change to 0 to disable logging

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int value;
    int count;
} CRCFlagCounter;

void log_message(const char *message) {
#ifdef LOGGING_ENABLED
    printf("LOG: %s\n", message);
#endif
}

int allocate_memory(NFAPI_CRC_INDICATION_PDU_T **elements, size_t num_elements) {
    if (num_elements > MAX_ELEMENTS) return -1;

    *elements = malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*elements == NULL) {
        log_message("Memory allocation failed");
        return -1;
    }
    return 0;
}

void free_memory(NFAPI_CRC_INDICATION_PDU_T *elements) {
    free(elements);
}

int generate_random_crcflag(int previous_flag) {
    int flag = rand() % 2; // Assuming CRCFLAG is binary for simplicity
    while (flag == previous_flag) {
        flag = rand() % 2;
    }
    return flag;
}

void recycle_rnti_resources(int *used_rntis, size_t used_count, int *rnti_pool, size_t pool_size) {
    // Simple recycling strategy: reuse the first available RNTI
    for (size_t i = 0; i < used_count; ++i) {
        for (size_t j = 0; j < pool_size; ++j) {
            if (rnti_pool[j] == -1) { // Assuming -1 indicates an unused RNTI
                rnti_pool[j] = used_rntis[i];
                used_rntis[i] = -1;
                break;
            }
        }
    }
}

void processAndAggregateCRCIndications(int num_elements) {
    if (num_elements <= 0 || num_elements > MAX_ELEMENTS) {
        log_message("Invalid number of elements");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T *elements = NULL;
    int status = allocate_memory(&elements, num_elements);
    if (status != 0) {
        log_message("Failed to initialize elements due to memory allocation error.");
        return;
    }

    int used_rntis[MAX_ELEMENTS] = {0};
    memset(used_rntis, -1, sizeof(used_rntis));
    int rnti_pool[MAX_ELEMENTS];
    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        rnti_pool[i] = i + 1;
    }

    int previous_crcflag = -1;
    CRCFlagCounter crc_flag_counters[2] = {{.value = 0, .count = 0}, {.value = 1, .count = 0}};

    srand(time(NULL));

    for (int i = 0; i < num_elements; ++i) {
        // Unique RX_UE_INFORMATION_TAG and RNTI
        elements[i].RX_UE_INFORMATION_TAG = rand() % 10000 + 1;
        do {
            int rnti_index = rand() % MAX_ELEMENTS;
            if (rnti_pool[rnti_index] != -1) {
                elements[i].RNTI = rnti_pool[rnti_index];
                used_rntis[i] = elements[i].RNTI;
                rnti_pool[rnti_index] = -1;
                break;
            }
        } while (1);

        // Random CRC_INDICATION_REL8_TAG
        elements[i].CRC_INDICATION_REL8_TAG = rand() % 100;

        // Ensure no consecutive same CRCFLAG
        elements[i].CRCFLAG = generate_random_crcflag(previous_crcflag);
        previous_crcflag = elements[i].CRCFLAG;

        crc_flag_counters[elements[i].CRCFLAG].count++;
    }

    recycle_rnti_resources(used_rntis, num_elements, rnti_pool, MAX_ELEMENTS);

    int max_value = INT_MIN;

    // Read integers from standard input and find the largest
    int value;
    printf("Enter numbers (EOF to end): ");
    while (scanf("%d", &value) == 1) {
        if (value > max_value) {
            max_value = value;
        }
    }

    printf("The largest integer is: %d\n", max_value);

    for (int i = 0; i < 2; ++i) {
        log_message(crc_flag_counters[i].count > num_elements / 3 ? 
                    "CRCFLAG usage alert" : "");
    }

    free_memory(elements);
}

int main() {
    processAndAggregateCRCIndications(100); // Example call with 100 elements
    return 0;
}
