typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    pthread_mutex_t lock;
    unsigned long next_seq_num;
} LinkedList;

LinkedList *create_list() {
    LinkedList *list = (LinkedList *)malloc(sizeof(LinkedList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->next_seq_num = 0;
    return list;
}

void free_list(LinkedList *list) {
    Node *current = list->head;
    while (current != NULL) {
        Node *temp = current;
        current = current->next;
        free(temp->data);
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void add_to_list(LinkedList *list, NFAPI_CRC_INDICATION_PDU_T *data) {
    if (list == NULL || data == NULL) return;

    pthread_mutex_lock(&list->lock);

    Node *new_node = (Node *)malloc(sizeof(Node));
    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
}

void populate_list(LinkedList *list, int num_elements, int rnti_start, int rnti_end) {
    if (num_elements > MAX_LIST_SIZE || list == NULL) return;

    for (int i = 0; i < num_elements; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        data->RX_UE_INFORMATION_TAG = rand() % 256;
        data->RNTI = rnti_start + (rand() % (rnti_end - rnti_start + 1));
        data->CRC_INDICATION_REL8_TAG = rand() % 256;
        data->CRCFLAG = rand() % 2;

        pthread_mutex_lock(&list->lock);
        data->sequence_number = list->next_seq_num++;
        pthread_mutex_unlock(&list->lock);

        add_to_list(list, data);
    }
}

void filter_and_iterate(LinkedList *list, int rnti_start, int rnti_end) {
    if (list == NULL) return;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current != NULL) {
        if (current->data->RNTI >= rnti_start && current->data->RNTI <= rnti_end) {
            // Process the element as needed
            printf("Processing RNTI: %d, Sequence Number: %lu\n",
                   current->data->RNTI, current->data->sequence_number);
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

int main() {
    srand(time(NULL));

    LinkedList *list = create_list();
    populate_list(list, 10, 1000, 2000);
    filter_and_iterate(list, 1050, 1500);

    free_list(list);
    return 0;
}
