    TCPConnection connection;
    struct ConnectionNode* next;
} ConnectionNode;

typedef struct {
    ConnectionNode* head;
    pthread_mutex_t lock;
} ConnectionList;

void initialize_connections(ConnectionList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

TCPConnection* find_connection(ConnectionList* list, const char* client_address) {
    pthread_mutex_lock(&list->lock);

    ConnectionNode* current = list->head;
    while (current != NULL) {
        if (strcmp(current->connection.client_address, client_address) == 0) {
            pthread_mutex_unlock(&list->lock);
            return &current->connection;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void add_connection(ConnectionList* list, const char* client_addr, const char* server_addr) {
    TCPConnection new_conn;
    strcpy(new_conn.client_address, client_addr);
    strcpy(new_conn.server_address, server_addr);
    new_conn.is_active = 1;
    time(&new_conn.last_activity);

    ConnectionNode* new_node = (ConnectionNode*)malloc(sizeof(ConnectionNode));
    if (!new_node) {
        perror("Failed to allocate memory for connection node");
        return;
    }

    new_node->connection = new_conn;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

void update_connection_status(ConnectionList* list, const char* client_addr, int status) {
    TCPConnection* conn = find_connection(list, client_addr);

    if (conn) {
        time(&conn->last_activity);
        conn->is_active = status;
        log_event("Connection status updated");
    }
}

void remove_inactive_connections(ConnectionList* list) {
    pthread_mutex_lock(&list->lock);

    ConnectionNode *current = list->head, *prev = NULL;

    while (current != NULL) {
        time_t now;
        time(&now);
        if (!current->connection.is_active && difftime(now, current->connection.last_activity) > TIMEOUT_THRESHOLD) {
            if (prev == NULL) { // head needs to be removed
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            ConnectionNode* temp = current;
            current = current->next;
            free(temp);
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void log_event(const char* message) {
    // Implement logging mechanism here
    printf("%s\n", message);
}

void monitor_connections(ConnectionList* list) {
    while (1) {
        remove_inactive_connections(list);

        // Simulate integration with external monitoring service
        for (ConnectionNode* node = list->head; node != NULL; node = node->next) {
            if (!node->connection.is_active) {
                report_anomaly(node->connection.client_address, "Inactive connection detected");
            }
        }

        sleep(1); // Adjust as needed for your monitoring interval
    }
}

void report_anomaly(const char* client_addr, const char* message) {
    // Implement anomaly reporting to external service here
    log_event(message);
    log_event(client_addr);
}
