// Define constants for system resource limits
#define MAX_MEMORY_LIMIT 1024 * 1024 // Example limit in bytes

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    node->data = data;
    node->next = NULL;
    return node;
}

int populate_crc_array(int N, Node** head) {
    if (N <= 0) return 0;

    *head = create_node((NFAPI_CRC_INDICATION_PDU_T){.RX_UE_INFORMATION_TAG = 1, .RNTI = 2, .CRC_INDICATION_REL8_TAG = rand() % 2});
    if (!*head) return -1; // Memory allocation failed

    Node* current = *head;
    int count = 1;

    for (int i = 1; i < N; ++i) {
        int crc_flag = (rand() % 2 + 1) % 2; // Ensure no two consecutive CRC flags are the same
        NFAPI_CRC_INDICATION_PDU_T data = { .RX_UE_INFORMATION_TAG = rand(), .RNTI = rand(), .CRC_INDICATION_REL8_TAG = crc_flag };

        Node* new_node = create_node(data);
        if (!new_node) {
            // Cleanup in case of failure
            while (current != NULL) {
                Node* temp = current;
                current = current->next;
                free(temp);
            }
            return -1; // Memory allocation failed
        }

        current->next = new_node;
        current = new_node;
        count++;
    }

    return count;
}

void free_crc_array(Node** head) {
    Node* current = *head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    *head = NULL;
}

int main() {
    int N = 10; // Example input
    Node* head = NULL;

    int populated_count = populate_crc_array(N, &head);

    if (populated_count == -1) {
        printf("Memory allocation failed or exceeded system limits.\n");
    } else {
        printf("Successfully populated %d structures.\n", populated_count);
    }

    free_crc_array(&head);
    return 0;
}
