['Below is a C code implementation that meets your described requirements. This example focuses on managing a dynamic list of `NFAPI_CRC_INDICATION_PDU_T` structures with the specified features.

```c
#include <stdio.h>
#include <stdlib.h>
import threading

#define MAX_LIST_SIZE 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRCFLAG; // Assuming it's a byte for simplicity
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    // Other fields can be added here as needed
} NFAPI_CRC_INDICATION_PDU_T;

// Memory pool structure
typedef struct {
    size_t element_size;
    void *pool;
    size_t capacity;
    size_t used;
    pthread_mutex_t lock;
} MemoryPool;

// Logging function
void log_message(const char *message) {
    printf("%s\n", message);
}

MemoryPool create_memory_pool(size_t element_size, size_t initial_capacity) {
    MemoryPool pool = {element_size, NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER};
    if (initial_capacity > 0) {
        pool.pool = malloc(initial_capacity * element_size);
        pool.capacity = initial_capacity;
    }
    return pool;
}

void destroy_memory_pool(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    free(pool->pool);
    pthread_mutex_unlock(&pool->lock);
    pthread_mutex_destroy(&pool->lock);
    pool->capacity = 0;
    pool->used = 0;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_from_pool(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->used >= pool->capacity) {
        size_t new_capacity = pool->capacity == 0 ? 16 : pool->capacity * 2;
        void *new_pool = realloc(pool->pool, new_capacity * pool->element_size);
        if (!new_pool) {
            pthread_mutex_unlock(&pool->lock);
            log_message("Memory allocation failed");
            return NULL;
        }
        pool->pool = new_pool;
        pool->capacity = new_capacity;
    }
    void *ptr = (char *)pool->pool + pool->used * pool->element_size;
    pool->used++;
    pthread_mutex_unlock(&pool->lock);
    return (NFAPI_CRC_INDICATION_PDU_T*) ptr;
}

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T **entries;
    size_t count;
    MemoryPool pool;
    int compression_enabled;
} CRCListManager;

// Thread-safe initialization of the list manager
CRCListManager* initialize_crc_list_manager(int compression) {
    CRCListManager *manager = (CRCListManager*)malloc(sizeof(CRCListManager));
    if (!manager) {
        log_message("Failed to allocate memory for CRCListManager");
        return NULL;
    }
    pthread_mutex_init(&manager->pool.lock, NULL);
    manager->entries = NULL;
    manager->count = 0;
    manager->pool = create_memory_pool(sizeof(NFAPI_CRC_INDICATION_PDU_T), MAX_LIST_SIZE / 2);
    manager->compression_enabled = compression;
    return manager;
}

// Thread-safe addition of new entries
int add_crc_entry(CRCListManager *manager, int rx_ue_tag, int rnti) {
    pthread_mutex_lock(&manager->pool.lock);

    if (manager->count >= MAX_LIST_SIZE) {
        log_message("Maximum list size reached");
        pthread_mutex_unlock(&manager->pool.lock);
        return -1;
    }

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->entries[i]->RNTI == rnti) {
            log_message("Duplicate RNTI detected");
            pthread_mutex_unlock(&manager->pool.lock);
            return -2;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T *new_entry = allocate_from_pool(&manager->pool);
    if (!new_entry) {
        pthread_mutex_unlock(&manager->pool.lock);
        return -3; // Allocation failed
    }

    new_entry->RX_UE_INFORMATION_TAG = rx_ue_tag;
    new_entry->RNTI = rnti;
    new_entry->crc_indication_rel8_tag.CRCFLAG = rand() % 256; // Random CRCFLAG

    if (manager->count == manager->pool.used) {
        manager->entries = realloc(manager->entries, (manager->count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    }

    manager->entries[manager->count++] = new_entry;
    pthread_mutex_unlock(&manager->pool.lock);

    log_message("Entry added successfully");
    return 0; // Success
}

// Cleanup resources associated with the list manager
void cleanup_crc_list_manager(CRCListManager *manager) {
    if (manager) {
        for (size_t i = 0; i < manager->count; ++i) {
            free(manager->entries[i]);
        }
        free(manager->entries);
        destroy_memory_pool(&manager->pool);
        pthread_mutex_destroy(&manager->pool.lock);
        free(manager);
    }
}

int main() {
    // Example usage
    CRCListManager *manager = initialize_crc_list_manager(1);

    add_crc_entry(manager, 100, 1234); // Add an entry
    add_crc_entry(manager, 200, 5678); // Add another unique entry

    cleanup_crc_list_manager(manager);

    return 0;
}
```

