#define MAX_ELEMENTS 100000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    bool should_terminate;
    int flush_interval_seconds; // Configurable interval
    pthread_t validation_thread;
} DynamicArrayManager;

void* validate_crc(void* arg) {
    DynamicArrayManager* manager = (DynamicArrayManager*)arg;
    while (!manager->should_terminate) {
        pthread_mutex_lock(&manager->lock);
        for (size_t i = 0; i < manager->count; ++i) {
            // Simulate validation process
            printf("Validating CRC_INDICATION_REL8_TAG for RNTI: %u\n", manager->array[i].RNTI);
            pthread_mutex_unlock(&manager->lock);

            // Simulate timeout or delay handling
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            ts.tv_sec += 1; // Timeout after 1 second for example

            int result = pthread_cond_timedwait(&manager->cond, &manager->lock, &ts);
            if (result == ETIMEDOUT) {
                printf("Validation timeout for RNTI: %u\n", manager->array[i].RNTI);
            }

            pthread_mutex_lock(&manager->lock);
        }
        pthread_mutex_unlock(&manager->lock);

        // Sleep to prevent busy-waiting
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        ts.tv_sec += manager->flush_interval_seconds;

        int result = pthread_cond_timedwait(&manager->cond, NULL, &ts);
        if (result == ETIMEDOUT) {
            // Trigger flush to storage here
            printf("Flushing data to external storage...\n");
        }
    }

    return NULL;
}

void initialize_manager(DynamicArrayManager* manager, int flush_interval_seconds) {
    manager->array = calloc(MAX_ELEMENTS, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        perror("Failed to allocate memory for dynamic array");
        exit(EXIT_FAILURE);
    }
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->cond, NULL);
    manager->should_terminate = false;
    manager->flush_interval_seconds = flush_interval_seconds;

    if (pthread_create(&manager->validation_thread, NULL, validate_crc, manager) != 0) {
        perror("Failed to create validation thread");
        exit(EXIT_FAILURE);
    }
}

void add_element(DynamicArrayManager* manager, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&manager->lock);

    // Check for unique RNTI
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->array[i].RNTI == element.RNTI) {
            fprintf(stderr, "Duplicate RNTI detected: %u\n", element.RNTI);
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    // Add new element
    if (manager->count < MAX_ELEMENTS) {
        manager->array[manager->count++] = element;
    } else {
        fprintf(stderr, "Dynamic array is full\n");
    }

    pthread_cond_broadcast(&manager->cond); // Notify validation thread of changes
    pthread_mutex_unlock(&manager->lock);
}

void terminate_manager(DynamicArrayManager* manager) {
    pthread_mutex_lock(&manager->lock);
    manager->should_terminate = true;
    pthread_cond_broadcast(&manager->cond);
    pthread_mutex_unlock(&manager->lock);

    pthread_join(manager->validation_thread, NULL);
    free(manager->array);
    pthread_mutex_destroy(&manager->lock);
    pthread_cond_destroy(&manager->cond);
}

int main() {
    DynamicArrayManager manager;
    initialize_manager(&manager, 60); // Flush every minute

    // Simulate adding elements
    for (unsigned int i = 0; i < 100; ++i) { // Test with fewer elements for brevity
        NFAPI_CRC_INDICATION_PDU_T pdu = {
            .RX_UE_INFORMATION_TAG = rand(),
            .RNTI = rand() % MAX_ELEMENTS,
            .CRC_INDICATION_REL8_TAG = {.CRCFLAG = rand() & 1}
        };
        add_element(&manager, pdu);
    }

    // Simulate running for some time
    sleep(120);

    terminate_manager(&manager);
    return 0;
}
```

