// Initialize the dynamic list
void initialize_list(List* list) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    list->count = 0;
}

// Destroy the dynamic list and free resources
void destroy_list(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}

// Add an entry to the list, ensuring thread safety and uniqueness of RNTI
int add_entry(List* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->lock);

    // Check for unique RNTI
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == entry.RNTI) {
            fprintf(stderr, "Duplicate RNTI: %u\n", entry.RNTI);
            pthread_mutex_unlock(&list->lock);
            return -1; // Error due to duplicate
        }
        current = current->next;
    }

    // Add the new entry
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory error
    }
    new_node->data = entry;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

