ArrayManager* create_manager() {
    ArrayManager *manager = malloc(sizeof(ArrayManager));
    if (!manager) return NULL;

    manager->array = malloc(MAX_ELEMENTS * sizeof(LTE_PHY_MEASUREMENTS_T));
    if (!manager->array) {
        free(manager);
        log_error("Memory allocation failed for array.");
        return NULL;
    }

    manager->size = 0;
    manager->capacity = MAX_ELEMENTS;
    pthread_mutex_init(&manager->mutex, NULL);
    pthread_cond_init(&manager->cond_var, NULL);
    manager->flush_flag = 0;
    manager->last_flush_time = time(NULL);

    // Open log file
    manager->log_file = fopen("array_manager.log", "a");
    if (!manager->log_file) {
        free(manager->array);
        free(manager);
        return NULL;
    }

    pthread_t network_thread;
    pthread_create(&network_thread, NULL, network_monitor_thread, (void*)manager);

    return manager;
}

int add_measurement(ArrayManager *manager, LTE_PHY_MEASUREMENTS_T measurement) {
    pthread_mutex_lock(&manager->mutex);

    // Check for unique PCI
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->array[i].PCI == measurement.PCI) {
            log_error("Duplicate PCI detected.");
            pthread_mutex_unlock(&manager->mutex);
            return -1;
        }
    }

    // Add new measurement
    if (manager->size >= manager->capacity) {
        log_error("Array capacity reached.");
        pthread_mutex_unlock(&manager->mutex);
        return -2;
    }

    manager->array[manager->size++] = measurement;

    // Periodic flush check
    time_t current_time = time(NULL);
    if (difftime(current_time, manager->last_flush_time) >= FLUSH_INTERVAL_MINUTES * 60) {
        pthread_cond_signal(&manager->cond_var);
        manager->flush_flag = 1;
        manager->last_flush_time = current_time;
    }

    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

void* network_monitor_thread(void* arg) {
    ArrayManager *manager = (ArrayManager *)arg;

    while (1) {
        pthread_mutex_lock(&manager->mutex);

        if (manager->flush_flag) {
            flush_to_external_storage(manager);
            manager->flush_flag = 0;
        }

        pthread_cond_wait(&manager->cond_var, &manager->mutex);

        // Validate PHY_RX_QUALITY_INDICATOR with network service
        for (size_t i = 0; i < manager->size; ++i) {
            // Mock network validation and timeout handling
            int result = 1; // Assume valid unless error occurs

            if (!result) {
                log_error("Network validation failed for measurement.");
                return NULL;
            }
        }

        pthread_mutex_unlock(&manager->mutex);
    }
}

void flush_to_external_storage(ArrayManager *manager) {
    // Mock flushing logic
    fprintf(manager->log_file, "Flushing %zu measurements to external storage.\n", manager->size);

    // Reset array after flushing
    manager->size = 0;
}

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
    if (manager->log_file) {
        fprintf(manager->log_file, "%s\n", message);
    }
}

int main() {
