    int frequency_band;
    int transmit_power_level;
    bool is_initialized;
} NFC_CONFIG_T;

// Simulated external data source (could be an API in a real-world scenario).
typedef struct {
    int radio_id;
    int preferred_frequency_band;
    int recommended_transmit_power_level;
} ExternalConfigData;

// Error handling function.
void handle_error(const char *error_message) {
    fprintf(stderr, "Error: %s\n", error_message);
}

// Function to update configuration from external data source (simulated).
bool fetch_external_config(ExternalConfigData **config_data, int *size) {
    // Simulate fetching data; in a real-world scenario, this would be an API call.
    static ExternalConfigData sample_data[] = {
        {0, 2400, 20},     // Radio 0: preferred frequency band and power level
        {1, 5800, 15}      // Radio 1: different settings
    };
    *config_data = sample_data;
    *size = sizeof(sample_data) / sizeof(ExternalConfigData);
    return true; // Return false if fetching fails.
}

// Function to initialize and configure NFC_CONFIG_T.
NFC_CONFIG_T* configure_nfc(int radio_count, int critical_radio_ids[], size_t critical_count) {
    NFC_CONFIG_T *configs = (NFC_CONFIG_T *)malloc(radio_count * sizeof(NFC_CONFIG_T));
    if (!configs) {
        handle_error("Memory allocation failed");
        return NULL;
    }

    ExternalConfigData *external_data;
    int external_size;

    // Fetch configuration data from an external source.
    if (!fetch_external_config(&external_data, &external_size)) {
        free(configs);
        handle_error("Failed to fetch external configuration data");
        return NULL;
    }

    for (int i = 0; i < radio_count; ++i) {
        configs[i].radio_id = i;
        configs[i].is_initialized = false;

        // Match the radio module with its external config.
        for (int j = 0; j < external_size; ++j) {
            if (external_data[j].radio_id == i) {
                configs[i].frequency_band = external_data[j].preferred_frequency_band;
                configs[i].transmit_power_level = external_data[j].recommended_transmit_power_level;
                break;
            }
        }

        // Implement lazy initialization and prioritize critical radios.
        bool is_critical = false;
        for (size_t k = 0; k < critical_count; ++k) {
            if (critical_radio_ids[k] == i) {
                is_critical = true;
                break;
            }
        }

        if (is_critical) {
            // Prioritize configuration updates for critical applications.
            configs[i].is_initialized = true;
        } else {
            // Non-critical radios can be initialized later or under specific conditions to save resources.
            configs[i].is_initialized = false; 
        }
    }

    free(external_data);
    return configs;
}

// Example usage
int main() {
    int critical_radios[] = {0};  // Assume radio 0 is critical.
    size_t critical_count = sizeof(critical_radios) / sizeof(critical_radios[0]);

    NFC_CONFIG_T *configs = configure_nfc(2, critical_radios, critical_count);
    if (configs) {
        for (int i = 0; i < 2; ++i) {
            printf("Radio ID: %d, Band: %d, Power Level: %d, Initialized: %s\n",
                   configs[i].radio_id,
                   configs[i].frequency_band,
                   configs[i].transmit_power_level,
                   configs[i].is_initialized ? "Yes" : "No");
        }
        free(configs);
    }

    return 0;
}
