    if (!initialized) {
        srand(time(NULL));
        initialized = true;
    }

    while (true) {
        unsigned long rnti = rand() % maxRNTI + 1; // Assuming RNTI starts from 1
        if (!usedRNTIs[rnti]) {
            usedRNTIs[rnti] = true;
            return rnti;
        }
    }
