// Function to dynamically populate the linked list
Node* populate_crc_indication_list(unsigned int num_elements, unsigned int max_RNTI) {
    Node *head = NULL, *current = NULL;

    // Array to keep track of used RNTIs
    bool *usedRNTIs = calloc(max_RNTI + 1, sizeof(bool)); 
    if (!usedRNTIs) return NULL;  // Handle memory allocation failure

    for (unsigned int i = 0; i < num_elements; ++i) {
        Node* new_node = malloc(sizeof(Node));
        if (!new_node) {
            // Free allocated list on error
            while (head != NULL) {
                Node *temp = head;
                head = head->next;
                free(temp);
            }
            free(usedRNTIs);
            return NULL;  // Handle memory allocation failure
        }

        new_node->data.RNTI = generate_unique_RNTI(usedRNTIs, max_RNTI);
        // Populate RX_UE_INFORMATION_TAG as needed (placeholder initialization)
        new_node->data.rxInfo.TXPOWER = 0;

        // Randomly set CRCFLAG within the range [0, 1]
        new_node->data.crcTag.CRCFLAG = rand() % 2;

        new_node->next = NULL;

        if (!head) {
            head = current = new_node; 
        } else {
            current->next = new_node;
            current = new_node;
        }
    }

    free(usedRNTIs); // Free the RNTI tracking array
    return head;
}

// Function to free the linked list
void free_crc_indication_list(Node* head) {
    while (head != NULL) {
        Node *temp = head;
        head = head->next;
        free(temp);
    }
}
