void sort_by_rnti(NFAPI_CRC_INDICATION_PDU_T* list, size_t n);
void free_nfa_list(NFAPI_CRC_INDICATION_PDU_T* list);

// Sorting function using qsort
int compare_rnti(const void* a, const void* b) {
    NFAPI_CRC_INDICATION_PDU_T* pdu_a = (NFAPI_CRC_INDICATION_PDU_T*)a;
    NFAPI_CRC_INDICATION_PDU_T* pdu_b = (NFAPI_CRC_INDICATION_PDU_T*)b;
    return (pdu_a->rnti > pdu_b->rnti) - (pdu_a->rnti < pdu_b->rnti);
}

// Main function to create and populate the list
int create_and_populate_nfa_list(NFAPI_CRC_INDICATION_PDU_T** list) {
    if (!list) return ALLOC_FAILURE;

    *list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(MAX_ENTRIES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*list == NULL) {
        perror("Failed to allocate memory for NFA list");
        return ALLOC_FAILURE;
    }

    pthread_t threads[MAX_ENTRIES];
    size_t entries_per_thread = MAX_ENTRIES / (sizeof(threads) / sizeof(pthread_t));

    // Thread function to populate part of the list
    auto populate_list_part = [](void* arg) -> void* {
        size_t index = *(size_t*)arg;
        srand(time(NULL) + index); // Seed with time and index for randomness

        for (size_t i = index * entries_per_thread; i < (index + 1) * entries_per_thread && i < MAX_ENTRIES; ++i) {
            (*list)[i].ue_info_tag.RNTI = rand() % UINT32_MAX;
            (*list)[i].rnti = (uint16_t)(rand() % UINT16_MAX);
            (*list)[i].crc_indication_rel8_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
        }
        return nullptr;
    };

    for (size_t i = 0; i < sizeof(threads) / sizeof(pthread_t); ++i) {
        size_t* index_ptr = malloc(sizeof(size_t));
        if (!index_ptr) {
            perror("Failed to allocate memory for thread index");
            free_nfa_list(*list);
            return ALLOC_FAILURE;
        }
        *index_ptr = i;

        if (pthread_create(&threads[i], nullptr, reinterpret_cast<void*(*)(void*)>(populate_list_part), index_ptr)) {
            perror("Thread creation failed");
            free(index_ptr);
            free_nfa_list(*list);
            return ALLOC_FAILURE;
        }
    }

    for (size_t i = 0; i < sizeof(threads) / sizeof(pthread_t); ++i) {
        pthread_join(threads[i], nullptr);
        free((void*)((uintptr_t)threads[i] % sizeof(size_t))); // Free index pointer
    }

    sort_by_rnti(*list, MAX_ENTRIES);

    return 0;
}

// Function to sort the list by RNTI values using qsort
void sort_by_rnti(NFAPI_CRC_INDICATION_PDU_T* list, size_t n) {
    if (list && n > 1)
        qsort(list, n, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_rnti);
}

// Function to free the allocated memory for the NFA list
void free_nfa_list(NFAPI_CRC_INDICATION_PDU_T* list) {
    if (list) {
        free(list);
    }
}
