    int RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

// Function to get the resident set size of a process
unsigned long get_resident_set_size() {
    unsigned long vsize;
    FILE* statstream = fopen("/proc/self/stat", "r");
    if (statstream == NULL) return 0;

    fscanf(statstream, "%*d %*s %*c %*d %*d %*d %*u %lu", &vsize);
    fclose(statstream);

    return vsize / (1024); // Return in KB
}

// Function to populate CRC indications and compile a Rust file
void populate_crc_indications(int num_pdu) {
    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(num_pdu * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Populate the pdus array
    for (int i = 0; i < num_pdu; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Example random generation
        pdus[i].RNTI = rand() % 1000;
        CRC_INDICATION_REL8_TAG crc_tag;
        crc_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
    }

    unsigned long initial_rss = get_resident_set_size();

    clock_t start_time = clock();
    int rustc_available = system("which rustc > /dev/null") == 0;
    if (!rustc_available) {
        fprintf(stderr, "Rust compiler not available\n");
        free(pdus);
        return;
    }

    // Compile Rust file using a subprocess
    FILE *log_file = fopen("compile_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        free(pdus);
        return;
    }
    int result = system("rustc --emit=dep-info test.rs 2>&1 | tee compile_log.txt");

    clock_t end_time = clock();
    double time_taken = ((double)(end_time - start_time)) / CLOCKS_PER_SEC;

    fclose(log_file);

    unsigned long final_rss = get_resident_set_size();

    if (result != 0) {
        fprintf(stderr, "Rust compilation failed\n");
    } else {
        printf("Compilation successful. Time taken: %f seconds\n", time_taken);
        printf("Initial RSS: %lu KB, Final RSS: %lu KB\n", initial_rss, final_rss);
    }

    free(pdus);
}

int main() {
    srand(time(NULL)); // Seed the random number generator
    populate_crc_indications(10); // Example call with 10 PDUs
    return 0;
}
```

