int validate_rust_compiler_availability() {
    int status = system("rustc --version > /dev/null 2>&1");
    return WIFEXITED(status) && WEXITSTATUS(status) == 0;
}

void compile_rust_file_with_logging(const char *filename, int verbose) {
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork failed");
        exit(EXIT_FAILURE);
    } else if (pid > 0) {
        // Parent process
        int status;
        waitpid(pid, &status, 0);

        if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
            early_error("Rust compilation failed");
        }
    } else {
        // Child process
        char *args[] = {"rustc", filename, NULL};

        if (verbose) {
            printf("Compiling %s with rustc\n", filename);
        }

        execvp(args[0], args);
        perror("execvp failed");
        exit(EXIT_FAILURE);
    }
}

void populate_crc_indications(NFAPI_CRC_INDICATION_PDU_T *array, size_t N) {
    if (!array || N == 0) return;

    srand(time(NULL)); // Seed random number generator

    for (size_t i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 10000;
        array[i].RNTI = rand() % 5000;
        array[i].crc_indication_tag.CRCFLAG = rand() & 1;
    }

    if (!validate_rust_compiler_availability()) {
        early_error("Rust compiler is not available");
        return;
    }

    struct timespec start_time, end_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    int initial_rss = get_resident_set_size();

    compile_rust_file_with_logging("example.rs", 1); // Example Rust file

    clock_gettime(CLOCK_MONOTONIC, &end_time);
    double elapsed = (end_time.tv_sec - start_time.tv_sec) + 
                     (end_time.tv_nsec - start_time.tv_nsec) / 1e9;

    int final_rss = get_resident_set_size();

    printf("Compilation time: %.6f seconds\n", elapsed);
    printf("RSS change: %d bytes\n", final_rss - initial_rss);
}

int main() {
    size_t N = 10;
    NFAPI_CRC_INDICATION_PDU_T *indication_array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!indication_array) {
        perror("Failed to allocate memory");
        return EXIT_FAILURE;
    }

    populate_crc_indications(indication_array, N);

    free(indication_array);
    return 0;
}
