    if (!new_node) {
        pthread_mutex_unlock(&arr->lock);
        return -2; // Error: Memory allocation failure
    }

    new_node->next = arr->head;
    arr->head = new_node;

    pthread_mutex_unlock(&arr->lock);
    return 0; // Success
}

// Remove an entry by index
int remove_entry(DynamicArray* arr, int index) {
    pthread_mutex_lock(&arr->lock);

    if (arr->head == NULL) {
        pthread_mutex_unlock(&arr->lock);
        return -1; // Error: Empty array
    }

    Node *current = arr->head, *prev = NULL;
    for (int i = 0; current != NULL && i < index; ++i) {
        prev = current;
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&arr->lock);
        return -2; // Error: Index out of bounds
    }

    if (prev == NULL) {
        arr->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    pthread_mutex_unlock(&arr->lock);
    return 0; // Success
}

