    if (!entry) return -1;

    size_t index = find_index_by_rnti(array, entry->RNTI);
    if (index != SIZE_MAX) return -2; // RNTI already exists

    pthread_mutex_lock(&array->lock);

    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* temp_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!temp_data) {
            pthread_mutex_unlock(&array->lock);
            return -3; // Memory allocation failure
        }
        array->data = temp_data;
        array->capacity = new_capacity;
    }

    memcpy(&array->data[array->size], entry, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->size++;

    pthread_mutex_unlock(&array->lock);
    return 0; // Success
}

int remove_entry(DynamicArray* array, size_t index) {
    if (!array || index >= array->size) return -1;

    pthread_mutex_lock(&array->lock);

    memmove(&array->data[index], &array->data[index + 1], (array->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->size--;

    pthread_mutex_unlock(&array->lock);
