typedef struct {
    double TS;
    double SNR;
    double BER;
    double RSSI;
} PHY_STATS_RECORD_T;

typedef struct Node {
    PHY_STATS_RECORD_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t count;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->head = NULL;
    pthread_mutex_init(&array->lock, NULL);
    array->count = 0;

    return array;
}

int add_entry(DynamicArray* array, PHY_STATS_RECORD_T new_record) {
    pthread_mutex_lock(&array->lock);

    Node* current = array->head;
    while (current != NULL) {
        if (current->data.TS == new_record.TS) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Duplicate timestamp
        }
        current = current->next;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&array->lock);
        return -2; // Memory allocation failure
    }

    new_node->data = new_record;
    new_node->next = array->head;
    array->head = new_node;
    array->count++;

    pthread_mutex_unlock(&array->lock);
    return 0; // Success
}

int remove_entry(DynamicArray* array, double timestamp) {
    pthread_mutex_lock(&array->lock);

    Node *current = array->head, *prev = NULL;

    while (current != NULL) {
        if (current->data.TS == timestamp) {
            if (prev == NULL) { // Removing head
                array->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            array->count--;
            pthread_mutex_unlock(&array->lock);
            return 0; // Success
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&array->lock);
    return -1; // Entry not found
}

int update_entry(DynamicArray* array, double timestamp, PHY_STATS_RECORD_T new_data) {
    pthread_mutex_lock(&array->lock);

    Node *current = array->head;

    while (current != NULL) {
        if (current->data.TS == timestamp) {
            current->data.SNR = new_data.SNR;
            current->data.BER = new_data.BER;
            current->data.RSSI = new_data.RSSI;
            pthread_mutex_unlock(&array->lock);
            return 0; // Success
        }
        current = current->next;
    }

    pthread_mutex_unlock(&array->lock);
    return -1; // Entry not found
}

void destroy_dynamic_array(DynamicArray* array) {
    if (array == NULL) return;

    Node *current = array->head, *temp;

    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&array->lock);
    free(array);
}

// Example usage
int main() {
    DynamicArray* array = create_dynamic_array();
    if (!array) return 1;

    PHY_STATS_RECORD_T record1 = { .TS = 1.0, .SNR = 10.5, .BER = 0.01, .RSSI = -50 };
    add_entry(array, record1);

    // Further operations...

    destroy_dynamic_array(array);
    return 0;
}
