    EventType type;
    void *payload;
    size_t payload_size;
} Event;

typedef struct {
    Event **events;
    size_t capacity;
    size_t count;
} EventArray;

void init_event_array(EventArray *ea, size_t initial_capacity) {
    ea->events = (Event **)malloc(initial_capacity * sizeof(Event *));
    if (!ea->events) {
        perror("Failed to allocate memory for event array");
        exit(EXIT_FAILURE);
    }
    ea->capacity = initial_capacity;
    ea->count = 0;
}

void free_event_array(EventArray *ea) {
    for (size_t i = 0; i < ea->count; ++i) {
        if (ea->events[i]->payload) {
            free(ea->events[i]->payload);
        }
        free(ea->events[i]);
    }
    free(ea->events);
    ea->events = NULL;
    ea->capacity = 0;
    ea->count = 0;
}

void resize_event_array(EventArray *ea, size_t new_capacity) {
    Event **new_events = (Event **)realloc(ea->events, new_capacity * sizeof(Event *));
    if (!new_events) {
        perror("Failed to reallocate memory for event array");
        exit(EXIT_FAILURE);
    }
    ea->events = new_events;
    ea->capacity = new_capacity;
}

void insert_event(EventArray *ea, Event *event) {
    if (ea->count == ea->capacity) {
        resize_event_array(ea, ea->capacity ? ea->capacity * 2 : 4);
    }
    ea->events[ea->count++] = event;
}

void delete_event(EventArray *ea, size_t index) {
    if (index < ea->count) {
        if (ea->events[index]->payload) {
            free(ea->events[index]->payload);
        }
        free(ea->events[index]);

        for (size_t i = index; i < ea->count - 1; ++i) {
            ea->events[i] = ea->events[i + 1];
        }
        --ea->count;

        if (ea->capacity > 4 && ea->count <= ea->capacity / 4) {
            resize_event_array(ea, ea->capacity / 2);
        }
    } else {
        fprintf(stderr, "Index out of bounds\n");
    }
}

Event *retrieve_event(const EventArray *ea, size_t index) {
    if (index < ea->count) {
        return ea->events[index];
    } else {
        fprintf(stderr, "Index out of bounds\n");
        return NULL;
    }
}

void create_event(Event **event, unsigned long timestamp, EventType type, const void *payload, size_t payload_size) {
    *event = (Event *)malloc(sizeof(Event));
    if (!*event) {
        perror("Failed to allocate memory for event");
        exit(EXIT_FAILURE);
    }

    (*event)->timestamp = timestamp;
    (*event)->type = type;
    (*event)->payload_size = payload_size;

    if (payload_size > 0) {
        (*event)->payload = malloc(payload_size);
        if (!(*event)->payload) {
            perror("Failed to allocate memory for event payload");
            free(*event);
            *event = NULL;
            exit(EXIT_FAILURE);
        }
        memcpy((*event)->payload, payload, payload_size);
    } else {
        (*event)->payload = NULL;
    }
}

int main() {
    EventArray ea;
    init_event_array(&ea, 4);

    // Example of creating and inserting an event
    Event *event1;
    create_event(&event1, 1234567890, EVENT_TYPE_A, "Error Code: 404", strlen("Error Code: 404") + 1);
    insert_event(&ea, event1);

    // Example of retrieving an event
    Event *retrieved_event = retrieve_event(&ea, 0);
    if (retrieved_event) {
        printf("Retrieved Event: %s\n", (char *)retrieved_event->payload);
    }

    // Free resources
    free_event_array(&ea);

    return 0;
}
```

