#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>
#include <zlib.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Assume 0 or 1 for simplicity
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    uint16_t (*findIndexByRNTI)(uint16_t rnti);
} CRCList;

CRCList crc_list = {NULL, PTHREAD_MUTEX_INITIALIZER};

// Function to compare RNTIs
int compareRNTI(const void* a, const void* b) {
    return (*(uint16_t*)a - *(uint16_t*)b);
}

Node* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        perror("Failed to allocate memory for new node");
        return NULL;
    }
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

void insertSorted(CRCList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);

    Node** current = &list->head;
    while (*current && ((*current)->data.RNTI < data.RNTI)) {
        current = &(*current)->next;
    }

    Node* newNode = createNode(data);
    if (newNode) {
        newNode->next = *current;
        *current = newNode;
    } else {
        // Handle memory allocation failure
        fprintf(stderr, "Memory allocation failed for new entry.\n");
    }

    pthread_mutex_unlock(&list->lock);
}

uint16_t findIndexByRNTI(uint16_t rnti) {
    pthread_mutex_lock(&crc_list.lock);

    Node* current = crc_list.head;
    uint16_t index = 0;
    while (current) {
        if (current->data.RNTI == rnti) {
            pthread_mutex_unlock(&crc_list.lock);
            return index;
        }
        current = current->next;
        index++;
    }

    pthread_mutex_unlock(&crc_list.lock);
    return -1; // Not found
}

void pruneEntries(uint32_t timeThreshold) {
    pthread_mutex_lock(&crc_list.lock);

    Node* current = crc_list.head;
    Node* prev = NULL;

    while (current) {
        uint32_t currentTime = time(NULL);
        if ((currentTime - current->data.RX_UE_INFORMATION_TAG) > timeThreshold) {
            Node* toDelete = current;
            if (prev) {
                prev->next = current->next;
            } else {
                crc_list.head = current->next;
            }
            current = current->next;
            free(toDelete);
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&crc_list.lock);
}

int exportListToFile(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return -1;
    }

    z_stream stream;
    stream.zalloc = Z_NULL;
    stream.zfree = Z_NULL;
    stream.opaque = Z_NULL;

    if (deflateInit(&stream, Z_BEST_COMPRESSION) != Z_OK) {
        perror("Failed to initialize zlib compression");
        fclose(file);
        return -1;
    }

    pthread_mutex_lock(&crc_list.lock);

    Node* current = crc_list.head;
    int bufferSize = 1024;
    char buffer[bufferSize];
    stream.avail_out = bufferSize;

    while (current) {
        if (deflate(&stream, Z_NO_FLUSH) != Z_OK) {
            perror("Failed during zlib compression");
            pthread_mutex_unlock(&crc_list.lock);
            deflateEnd(&stream);
            fclose(file);
            return -1;
        }
        fwrite(stream.next_out, 1, bufferSize - stream.avail_out, file);
        current = current->next;
    }

    if (deflate(&stream, Z_FINISH) != Z_STREAM_END) {
        perror("Failed to finalize zlib compression");
        pthread_mutex_unlock(&crc_list.lock);
        deflateEnd(&stream);
        fclose(file);
        return -1;
    }
    fwrite(stream.next_out, 1, bufferSize - stream.avail_out, file);

    pthread_mutex_unlock(&crc_list.lock);

    deflateEnd(&stream);
    fclose(file);
    return 0;
}

void freeList(CRCList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* toDelete = current;
        current = current->next;
        free(toDelete);
    }
    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
}

int main() {
    // Example usage
    NFAPI_CRC_INDICATION_PDU_T pdu1 = {time(NULL), 100, 1, rand() % 2};
    insertSorted(&crc_list, pdu1);

    uint16_t index = findIndexByRNTI(100);
    printf("Index of RNTI 100: %d\n", index);

    pruneEntries(3600); // Prune entries older than 1 hour

    if (exportListToFile("output.gz") == 0) {
        printf("Export successful.\n");
    } else {
        fprintf(stderr, "Failed to export list.\n");
    }

    freeList(&crc_list);
    return 0;
}
