#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_QUEUE_SIZE 1000000

typedef struct {
    int CELL_ID;
    int TIME_BUCKET;
    int RX_POWER_LEVEL;
    int FRAME_COUNT;
} LTE_PHY_FRAME_STATISTICS;

typedef struct {
    LTE_PHY_FRAME_STATISTICS *queue;
    size_t capacity;
    size_t head;
    size_t tail;
    size_t count;
    pthread_mutex_t lock;
} DynamicQueue;

int init_dynamic_queue(DynamicQueue *dq, size_t initial_size) {
    if (initial_size > MAX_QUEUE_SIZE) {
        return -1; // Error: Exceeds maximum capacity
    }

    dq->queue = (LTE_PHY_FRAME_STATISTICS *)malloc(initial_size * sizeof(LTE_PHY_FRAME_STATISTICS));
    if (!dq->queue) {
        return -2; // Error: Memory allocation failed
    }

    dq->capacity = initial_size;
    dq->head = 0;
    dq->tail = 0;
    dq->count = 0;

    if (pthread_mutex_init(&dq->lock, NULL) != 0) {
        free(dq->queue);
        return -3; // Error: Mutex initialization failed
    }

    return 0; // Success
}

void destroy_dynamic_queue(DynamicQueue *dq) {
    pthread_mutex_lock(&dq->lock);
    free(dq->queue);
    pthread_mutex_unlock(&dq->lock);
    pthread_mutex_destroy(&dq->lock);
}

int enqueue(DynamicQueue *dq, LTE_PHY_FRAME_STATISTICS item) {
    pthread_mutex_lock(&dq->lock);

    if (dq->count == dq->capacity) {
        pthread_mutex_unlock(&dq->lock);
        return -1; // Queue is full
    }

    dq->queue[dq->tail] = item;
    dq->tail = (dq->tail + 1) % dq->capacity;
    dq->count++;

    pthread_mutex_unlock(&dq->lock);
    return 0; // Success
}

int dequeue(DynamicQueue *dq, LTE_PHY_FRAME_STATISTICS *item) {
    pthread_mutex_lock(&dq->lock);

    if (dq->count == 0) {
        pthread_mutex_unlock(&dq->lock);
        return -1; // Queue is empty
    }

    *item = dq->queue[dq->head];
    dq->head = (dq->head + 1) % dq->capacity;
    dq->count--;

    pthread_mutex_unlock(&dq->lock);
    return 0; // Success
}

int resize_queue(DynamicQueue *dq, size_t new_size) {
    if (new_size > MAX_QUEUE_SIZE || new_size == 0) {
        return -1; // Error: Invalid size
    }

    pthread_mutex_lock(&dq->lock);

    LTE_PHY_FRAME_STATISTICS *new_queue = (LTE_PHY_FRAME_STATISTICS *)malloc(new_size * sizeof(LTE_PHY_FRAME_STATISTICS));
    if (!new_queue) {
        pthread_mutex_unlock(&dq->lock);
        return -2; // Error: Memory allocation failed
    }

    for (size_t i = 0; i < dq->count; ++i) {
        new_queue[i] = dq->queue[(dq->head + i) % dq->capacity];
    }

    free(dq->queue);
    dq->queue = new_queue;
    dq->capacity = new_size;
    dq->head = 0;
    dq->tail = dq->count;

    pthread_mutex_unlock(&dq->lock);
    return 0; // Success
}

// Example function to dynamically adjust queue size based on system metrics
void monitor_and_adjust(DynamicQueue *dq) {
    while (1) {
        // Simulate monitoring system load and adjusting queue size
        // This is a placeholder for actual logic that would use real-time data
        sleep(10); // Adjust every 10 seconds

        pthread_mutex_lock(&dq->lock);

        if (dq->count > dq->capacity / 2 && dq->capacity < MAX_QUEUE_SIZE) {
            resize_queue(dq, dq->capacity * 2);
        } else if (dq->count < dq->capacity / 4 && dq->capacity > 1) {
            size_t new_size = dq->capacity / 2;
            resize_queue(dq, new_size);
        }

        pthread_mutex_unlock(&dq->lock);
    }
}

int main() {
    DynamicQueue dq;
    if (init_dynamic_queue(&dq, 1024) != 0) {
        fprintf(stderr, "Failed to initialize queue\n");
        return -1;
    }

    // Example usage
    LTE_PHY_FRAME_STATISTICS item = {1, 12345, -70, 10};
    enqueue(&dq, item);

    LTE_PHY_FRAME_STATISTICS dequeued_item;
    if (dequeue(&dq, &dequeued_item) == 0) {
        printf("Dequeued: CELL_ID=%d, TIME_BUCKET=%d, RX_POWER_LEVEL=%d, FRAME_COUNT=%d\n",
               dequeued_item.CELL_ID, dequeued_item.TIME_BUCKET,
               dequeued_item.RX_POWER_LEVEL, dequeued_item.FRAME_COUNT);
    }

    destroy_dynamic_queue(&dq);

    return 0;
}
