#define MAX_NFAS 100000

typedef struct {
    uint8_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int RX_UE_INFORMATION_TAG; // Assuming an integer type for simplicity
    int RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t mutex;
} List;

void initialize_list(List* list) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

Node* create_node(int rx_ue_info_tag, int rnti, uint8_t crc_flag) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed for node\n");
        return NULL;
    }
    new_node->pdu.RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    new_node->pdu.RNTI = rnti;
    new_node->pdu.CRC_INDICATION_TAG.CRCFLAG = crc_flag;
    new_node->next = NULL;
    return new_node;
}

int is_rnti_present(List* list, int rnti) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current != NULL) {
        if (current->pdu.RNTI == rnti) {
            pthread_mutex_unlock(&list->mutex);
            return 1; // RNTI is present
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
    return 0; // RNTI not found
}

void add_node(List* list, int rx_ue_info_tag, int rnti, uint8_t crc_flag) {
    if (is_rnti_present(list, rnti)) {
        fprintf(stderr, "Duplicate RNTI entry detected: %d\n", rnti);
        return;
    }

    Node* new_node = create_node(rx_ue_info_tag, rnti, crc_flag);
    if (!new_node) {
        // Logging framework call would go here for memory allocation failure
        return;
    }

    pthread_mutex_lock(&list->mutex);
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->mutex);
}

void free_list(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->mutex);
}

void populate_nfa_list(List* list, int nfas) {
    srand(time(NULL));
    for (int i = 0; i < nfas && i < MAX_NFAS; ++i) {
        int rx_ue_info_tag = rand() % 1000; // Example value generation
        int rnti = rand() % 65536;          // RNTI range example
        uint8_t crc_flag = (rand() % 2);    // Randomly set CRCFLAG

        add_node(list, rx_ue_info_tag, rnti, crc_flag);
    }
}

int main() {
    List nfa_list;
    initialize_list(&nfa_list);

    populate_nfa_list(&nfa_list, 100000);

    free_list(&nfa_list);
    return 0;
}
