// Logging mechanism
void log_creation(const char* message) {
    time_t now = time(NULL);
    struct tm *local_time = localtime(&now);

    static FILE *log_file = NULL;
    if (!log_file || local_time->tm_mday != current_day) {
        if (log_file) fclose(log_file);

        char log_filename[256];
        snprintf(log_filename, sizeof(log_filename), "logs/log_%d.txt", local_time->tm_yday + 1);

        log_file = fopen(log_filename, "a");
        if (!log_file) {
            perror("Failed to open log file");
            return;
        }
    }

    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n", 
            local_time->tm_year + 1900,
            local_time->tm_mon + 1,
            local_time->tm_mday,
            local_time->tm_hour,
            local_time->tm_min,
            local_time->tm_sec,
            message);

    fflush(log_file);
}

// Thread safety
pthread_mutex_t pdu_list_mutex = PTHREAD_MUTEX_INITIALIZER;
int current_day;

// Helper function to check if RNTI is unique in the list
int is_rnti_unique(NFAPI_CRC_INDICATION_PDU_T *pdu_list, size_t count, unsigned short rnti) {
    for (size_t i = 0; i < count; ++i) {
        if (pdu_list[i].RNTI == rnti) return 0;
    }
    return 1;
}

// Function to create and populate the list
int create_pdu_list(PDU_LIST *list, size_t num_pdus, unsigned short min_rnti, unsigned short max_rnti) {
    pthread_mutex_lock(&pdu_list_mutex);

    if (num_pdus == 0) {
        pthread_mutex_unlock(&pdu_list_mutex);
        return -1; // Error code for invalid input
    }

    list->count = num_pdus;
    list->pdu_list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_pdus);

    if (!list->pdu_list) {
        pthread_mutex_unlock(&pdu_list_mutex);
        return -2; // Error code for memory allocation failure
    }

    srand(time(NULL));
    for (size_t i = 0; i < num_pdus; ++i) {
        do {
            list->pdu_list[i].RX_UE_INFORMATION_TAG = rand();
            list->pdu_list[i].RNTI = min_rnti + rand() % (max_rnti - min_rnti + 1);
        } while (!is_rnti_unique(list->pdu_list, i, list->pdu_list[i].RNTI));

        list->pdu_list[i].CRC_INDICATION_REL8_TAG = rand();
        list->pdu_list[i].CRCFLAG = rand() & 0x01;

        char log_message[256];
        snprintf(log_message, sizeof(log_message), "Created PDU with RNTI: %d", list->pdu_list[i].RNTI);
        log_creation(log_message);
    }

    pthread_mutex_unlock(&pdu_list_mutex);
    return 0; // Success
}

// Example usage
int main() {
    PDU_LIST pdu_list;
    int result = create_pdu_list(&pdu_list, 10, 1, 100);

    if (result == 0) {
        printf("PDU list created successfully.\n");
    } else {
        fprintf(stderr, "Failed to create PDU list. Error code: %d\n", result);
    }

    free(pdu_list.pdu_list); // Clean up
    return 0;
}
