            int found = 0;

            for (int j = 0; j < i; ++j) {
                if (array[j].rnti == array[i].rnti) {
                    found = 1;
                    break;
                }
            }

            if (!found) {
                unique_rntis[i] = array[i].rnti;
                break;
            }

            attempts++;
        }

