#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <arpa/inet.h>

typedef struct {
    char interface_name[256];
    struct in6_addr ip_address;
    struct in6_addr subnet_mask;
    struct in6_addr default_gateway;
    int is_ipv4; // 1 for IPv4, 0 for IPv6
} NICB;

typedef struct {
    NICB *nicbs;
    size_t count;
    pthread_mutex_t lock;
} NetworkManager;

int ip_in_same_subnet(struct in6_addr *ip1, struct in6_addr *subnet_mask, struct in6_addr *ip2) {
    unsigned char a[16], b[16];
    memcpy(a, ip1, 16);
    memcpy(b, ip2, 16);

    for (int i = 0; i < 16; ++i) {
        a[i] &= subnet_mask->s6_addr[i];
        if (a[i] != b[i]) return 0;
    }
    return 1;
}

int validate_ip_config(NetworkManager *manager, NICB *new_nicb) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (ip_in_same_subnet(&new_nicb->ip_address, &new_nicb->subnet_mask, &manager->nicbs[i].ip_address)) {
            pthread_mutex_unlock(&manager->lock);
            return 0; // IP conflict within the subnet
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return 1;
}

void add_nicb(NetworkManager *manager, NICB *new_nicb) {
    if (!validate_ip_config(manager, new_nicb)) {
        fprintf(stderr, "IP configuration error: IP conflict detected.\n");
        return;
    }

    pthread_mutex_lock(&manager->lock);
    manager->nicbs = realloc(manager->nicbs, (manager->count + 1) * sizeof(NICB));
    if (!manager->nicbs) {
        perror("Failed to allocate memory for NICB");
        pthread_mutex_unlock(&manager->lock);
        return;
    }
    memcpy(&manager->nicbs[manager->count], new_nicb, sizeof(NICB));
    manager->count++;
    pthread_mutex_unlock(&manager->lock);

    printf("NICB added successfully.\n");
}

void remove_nicb(NetworkManager *manager, const char *interface_name) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->nicbs[i].interface_name, interface_name) == 0) {
            memmove(&manager->nicbs[i], &manager->nicbs[i + 1], (manager->count - i - 1) * sizeof(NICB));
            manager->count--;
            manager->nicbs = realloc(manager->nicbs, manager->count * sizeof(NICB));
            pthread_mutex_unlock(&manager->lock);
            printf("NICB removed successfully.\n");
            return;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    fprintf(stderr, "Error: NICB not found for interface '%s'.\n", interface_name);
}

void initialize_network_manager(NetworkManager *manager) {
    manager->nicbs = NULL;
    manager->count = 0;
    if (pthread_mutex_init(&manager->lock, NULL) != 0) {
        perror("Mutex init has failed");
        exit(EXIT_FAILURE);
    }
}

int main() {
    NetworkManager manager;
    initialize_network_manager(&manager);

    NICB nicb1 = {.interface_name = "eth0", .is_ipv4 = 1};
    inet_pton(AF_INET6, "::1", &nicb1.ip_address); // Example IP
    inet_pton(AF_INET6, "ffff:ffff:ffff:ffff::", &nicb1.subnet_mask);

    add_nicb(&manager, &nicb1);

    NICB nicb2 = {.interface_name = "eth1", .is_ipv4 = 1};
    inet_pton(AF_INET6, "::2", &nicb2.ip_address); // Example IP
    inet_pton(AF_INET6, "ffff:ffff:ffff:ffff::", &nicb2.subnet_mask);

    add_nicb(&manager, &nicb2);

    remove_nicb(&manager, "eth0");

    free(manager.nicbs);
    pthread_mutex_destroy(&manager.lock);

    return 0;
}
```

