NFAPI_CRC_INDICATION_PDU_T* create_nfa_pdu(uint16_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) return NULL;

    pdu->RX_UE_INFORMATION_TAG = rand();
    pdu->RNTI = rnti;
    memset(pdu->CRC_INDICATION_REL8_TAG, rand() % 256, sizeof(pdu->CRC_INDICATION_REL8_TAG));

    // Set CRCFLAG randomly
    pdu->CRC_INDICATION_REL8_TAG[3] = (pdu->CRC_INDICATION_REL8_TAG[3] & ~1) | (rand() % 2);

    return pdu;
}

int create_nfa_dynamic_list(NFAPIDynamicList *list, size_t num_structures) {
    pthread_mutex_lock(&lock);
    list->num_structures = num_structures;

    // Memory allocation for the entire list at once
    NFAPI_CRC_INDICATION_PDU_T *pdu_array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_structures);
    if (!pdu_array) {
        pthread_mutex_unlock(&lock);
        return -ENOMEM;
    }
    list->structures = pdu_array;

    uint16_t used_rntis[MAX_RNTI + 1] = {0};

    for (size_t i = 0; i < num_structures; ++i) {
        int success = 0;
        while (!success) {
            if (check_config_update()) continue;

            uint16_t rnti = config_min_rnti + rand() % (config_max_rnti - config_min_rnti + 1);
            retry_count++;

            if (used_rntis[rnti]) {
                success = 0;
                continue;
            }

            used_rntis[rnti] = 1;
            NFAPI_CRC_INDICATION_PDU_T *pdu = create_nfa_pdu(rnti);
            if (!pdu) {
                retry_count++;
                success = 0;
                continue;
            }

            list->structures[i] = *pdu;
            free(pdu);
            log_creation("NFAPI_CRC_INDICATION_PDU_T created");
            success = 1;
        }
    }

    pthread_mutex_unlock(&lock);
    return 0;
}

void log_creation(const char* message) {
    static FILE *log_file = NULL;
    if (!log_file || feof(log_file)) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char filename[256];
        strftime(filename, sizeof(filename), "logs/%Y-%m-%d.log", tm_info);

        log_file = fopen(filename, "a");
    }

    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fflush(log_file);
    }
}

int check_config_update() {
    static time_t last_check_time = 0;
    time_t current_time = time(NULL);

    if ((current_time - last_check_time) * 1000 >= CONFIG_UPDATE_CHECK_INTERVAL_MS) {
        // Example: Update configuration parameters here
        // config_min_rnti, config_max_rnti

        last_check_time = current_time;
        return 1; // Indicate a config update has been checked
    }

    return 0; // No config update needed
}

void serialize_list(const NFAPIDynamicList *list) {
    FILE *file = fopen("nfa_pdu_serialized.bin", "wb");
    if (!file) return;

    fwrite(&list->num_structures, sizeof(size_t), 1, file);
    for (size_t i = 0; i < list->num_structures; ++i) {
        fwrite(&list->structures[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }

    fclose(file);
}

int deserialize_list(NFAPIDynamicList *list) {
    FILE *file = fopen("nfa_pdu_serialized.bin", "rb");
    if (!file) return -errno;

    size_t num_structures;
    fread(&num_structures, sizeof(size_t), 1, file);

    NFAPI_CRC_INDICATION_PDU_T *pdu_array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_structures);
    if (!pdu_array) {
        fclose(file);
        return -ENOMEM;
    }

    for (size_t i = 0; i < num_structures; ++i) {
        fread(&pdu_array[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }

    fclose(file);

    list->num_structures = num_structures;
    list->structures = pdu_array;

    return 0;
}

void free_nfa_dynamic_list(NFAPIDynamicList *list) {
    if (list && list->structures) {
        free(list->structures);
        list->structures = NULL;
        list->num_structures = 0;
    }
}
