void* process_structures(void* arg) {
    SharedData* data = (SharedData*)arg;
    pthread_mutex_lock(&data->lock);

    double max_weighted_sum = 0.0;
    int transaction_id_with_max_weight = -1;

    time_t current_time = time(NULL);
    for (size_t i = 0; i < data->count; ++i) {
        NFAPI_CRC_INDICATION_PDU* pdu = data->structures[i];

        // Age management and frequency update
        if (difftime(current_time, pdu->timestamp) > 5) {
