        if (weighted_sum > max_weighted_sum) {
            max_weighted_sum = weighted_sum;
            transaction_id_with_max_weight = i; // Assuming index as transaction ID
        }

        data->valid_structures_count++;
    }

    data->max_weighted_sum = max_weighted_sum;

    pthread_mutex_unlock(&data->lock);

    return NULL;
}

