    pthread_mutex_init(&data->lock, NULL);
    memset(data->structures, 0, sizeof(NFAPI_CRC_INDICATION_PDU*) * MAX_STRUCTURES);
    data->count = 0;
    data->max_weighted_sum = 0.0;
