        new_pdu->timestamp = time(NULL);
        new_pdu->frequency_count = 0;

        data->structures[data->count++] = new_pdu;
        pthread_mutex_unlock(&data->lock);
        return new_pdu;
    }

    pthread_mutex_unlock(&data->lock);
    return NULL; // No space to add new structure
