#define INITIAL_CAPACITY 10

typedef struct {
    // Define the structure fields here.
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t capacity;
    size_t count;
    pthread_rwlock_t lock; 
} DynamicArray;

// Custom allocator functions (simplified)
void* custom_alloc(size_t size) {
    return malloc(size);
}

void custom_free(void* ptr) {
    free(ptr);
}

// Initialize the dynamic array
void init_dynamic_array(DynamicArray* arr) {
    arr->array = custom_alloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    arr->capacity = INITIAL_CAPACITY;
    arr->count = 0;
    pthread_rwlock_init(&arr->lock, NULL);
}

// Resize the dynamic array
void resize_dynamic_array(DynamicArray* arr) {
    size_t new_capacity = (size_t)((uint64_t)arr->capacity * 2); // Protect against overflow
    if ((uint64_t)new_capacity < (uint64_t)arr->capacity) {
        fprintf(stderr, "Capacity overflow detected!\n");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T* new_array = custom_alloc(new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        perror("Failed to allocate memory");
        return;
    }

    for (size_t i = 0; i < arr->count; ++i) {
        new_array[i] = arr->array[i];
    }

    custom_free(arr->array);
    arr->array = new_array;
    arr->capacity = new_capacity;
}

// Add a PDU to the dynamic array
void add_pdu(DynamicArray* arr, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_rwlock_wrlock(&arr->lock);

    if (arr->count >= arr->capacity) {
        resize_dynamic_array(arr);
    }

    arr->array[arr->count++] = pdu;

    pthread_rwlock_unlock(&arr->lock);
}

// Retrieve a PDU from the dynamic array
NFAPI_CRC_INDICATION_PDU_T get_pdu(DynamicArray* arr, size_t index) {
    pthread_rwlock_rdlock(&arr->lock);

    if (index >= arr->count) {
        fprintf(stderr, "Index out of bounds\n");
        NFAPI_CRC_INDICATION_PDU_T empty;
        pthread_rwlock_unlock(&arr->lock);
        return empty; // Return an empty/default structure
    }

    NFAPI_CRC_INDICATION_PDU_T pdu = arr->array[index];

    pthread_rwlock_unlock(&arr->lock);
    return pdu;
}

// Iterate over the dynamic array (example function)
void iterate_pdus(DynamicArray* arr, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    pthread_rwlock_rdlock(&arr->lock);

    for (size_t i = 0; i < arr->count; ++i) {
        callback(arr->array[i]);
    }

    pthread_rwlock_unlock(&arr->lock);
}

// Free the dynamic array
void free_dynamic_array(DynamicArray* arr) {
    custom_free(arr->array);
    pthread_rwlock_destroy(&arr->lock);
}

