// Unit tests for DynamicArray functionality
void test_add_and_get() {
    DynamicArray arr;
    init_dynamic_array(&arr);

    NFAPI_CRC_INDICATION_PDU_T pdu1 = {}, pdu2 = {};

    add_pdu(&arr, pdu1);
    add_pdu(&arr, pdu2);

    assert(arr.count == 2);
    assert(memcmp(get_pdu(&arr, 0), &pdu1, sizeof(NFAPI_CRC_INDICATION_PDU_T)) == 0);
    assert(memcmp(get_pdu(&arr, 1), &pdu2, sizeof(NFAPI_CRC_INDICATION_PDU_T)) == 0);

    free_dynamic_array(&arr);
}

void test_concurrent_access() {
    DynamicArray arr;
    init_dynamic_array(&arr);

    pthread_t threads[10];
    NFAPI_CRC_INDICATION_PDU_T pdu = {};

    for (int i = 0; i < 10; ++i) {
        pthread_create(&threads[i], NULL, (void* (*)(void*))add_pdu, &arr);
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    assert(arr.count == 10);

    free_dynamic_array(&arr);
}

// Main function to run tests
