using System;
using System.Collections.Generic;
using System.Linq;

public struct NFAPI_CRC_INDICATION_PDU_T
{
    public string RX_UE_INFORMATION_TAG;
    public int RNTI;
    public CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
}

public struct CRC_INDICATION_REL8_TAG
{
    public bool CRCFLAG;
}

public class DynamicValueGenerator
{
    private List<NFAPI_CRC_INDICATION_PDU_T> structurePool;
    private Dictionary<int, DateTime> structureAgeTracking;
    private int maxStructures;
    private float minFloatRange;
    private float maxFloatRange;
    private int minIntRange;
    private int maxIntRange;

    public DynamicValueGenerator(int n, float minFloat = 0.0f, float maxFloat = 1.0f, int minInt = 0, int maxInt = 100)
    {
        structurePool = new List<NFAPI_CRC_INDICATION_PDU_T>(n);
        structureAgeTracking = new Dictionary<int, DateTime>();
        maxStructures = n;
        minFloatRange = minFloat;
        maxFloatRange = maxFloat;
        minIntRange = minInt;
        maxIntRange = maxInt;

        InitializePool();
    }

    private void InitializePool()
    {
        for (int i = 0; i < maxStructures; i++)
        {
            structurePool.Add(GenerateRandomStructure());
        }
    }

    private NFAPI_CRC_INDICATION_PDU_T GenerateRandomStructure()
    {
        return new NFAPI_CRC_INDICATION_PDU_T
        {
            RX_UE_INFORMATION_TAG = Guid.NewGuid().ToString(),
            RNTI = GetRandomInt(),
            CRC_INDICATION_REL8_TAG = new CRC_INDICATION_REL8_TAG { CRCFLAG = GetRandomBoolean() }
        };
    }

    private int GetRandomInt()
    {
        var rnd = new Random();
        return rnd.Next(minIntRange, maxIntRange + 1);
    }

    private float GetRandomFloat(bool inclusiveMin = true, bool inclusiveMax = false)
    {
        var rnd = new Random();
        double min = inclusiveMin ? (double)minFloatRange : minFloatRange + double.Epsilon;
        double max = inclusiveMax ? maxFloatRange : maxFloatRange - double.Epsilon;

        return (float)(rnd.NextDouble() * (max - min) + min);
    }

    private bool GetRandomBoolean()
    {
        var rnd = new Random();
        return rnd.Next(0, 2) == 1;
    }

    public string GetStringRepresentation(int index)
    {
        if (index < 0 || index >= structurePool.Count)
            throw new ArgumentOutOfRangeException(nameof(index));

        var structure = structurePool[index];
        return $"TX: {structure.RX_UE_INFORMATION_TAG}, RNTI: {structure.RNTI}, CRCFLAG: {structure.CRC_INDICATION_REL8_TAG.CRCFLAG}";
    }

    public (double maxWeightedSum, string transactionId) ComputeMetrics(List<int> validRNTIs)
    {
        double maxWeightedSum = 0;
        string transactionId = null;

        foreach (var structure in structurePool.Where(s => IsValidRNTI(s.RNTI, validRNTIs)))
        {
            var weightedSum = CalculateWeightedSum(structure);
            if (weightedSum > maxWeightedSum)
            {
                maxWeightedSum = weightedSum;
                transactionId = structure.RX_UE_INFORMATION_TAG;
            }

            UpdateStructureAge(structure.RX_UE_INFORMATION_TAG);
        }

        return (maxWeightedSum, transactionId);
    }

    private bool IsValidRNTI(int rnti, List<int> validRNTIs)
    {
        // Validate against the current user list
        return validRNTIs.Contains(rnti);
    }

    private double CalculateWeightedSum(NFAPI_CRC_INDICATION_PDU_T structure)
    {
        // Example calculation; replace with actual logic as needed
        var crcWeight = structure.CRC_INDICATION_REL8_TAG.CRCFLAG ? 1.0 : 0.5;
        return GetRandomFloat() * crcWeight + GetRandomInt();
    }

    private void UpdateStructureAge(string transactionId)
    {
        if (structureAgeTracking.ContainsKey(transactionId.GetHashCode()))
        {
            structureAgeTracking[transactionId.GetHashCode()] = DateTime.UtcNow;
        }
        else
        {
            structureAgeTracking.Add(transactionId.GetHashCode(), DateTime.UtcNow);
        }
    }

    public (int validCount, int invalidCount) GetProcessingStatistics(List<int> validRNTIs)
    {
