    size_t used;
    size_t capacity;
    pthread_mutex_t lock;
} Collection;

// Function to create a new collection
Collection* create_collection() {
    Collection *c = (Collection*)malloc(sizeof(Collection));
    if (!c) return NULL;

    c->capacity = INITIAL_CAPACITY;
    c->used = 0;
    c->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(c->capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!c->array) {
        free(c);
        return NULL;
    }

    pthread_mutex_init(&c->lock, NULL);
    return c;
}

// Function to resize the collection
int resize_collection(Collection *c) {
    size_t new_capacity = c->capacity * 2;

    NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(c->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) return -1;

    c->array = new_array;
    c->capacity = new_capacity;
    return 0;
}

// Function to add or update an element
int collection_add_or_update(Collection *c, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&c->lock);

    for (size_t i = 0; i < c->used; ++i) {
        if (c->array[i].RNTI == pdu.RNTI) {
            c->array[i] = pdu;
            pthread_mutex_unlock(&c->lock);
            return 0; // Updated existing entry
        }
    }

    if (c->used == c->capacity) {
        pthread_mutex_unlock(&c->lock);

        if (resize_collection(c)) {
            fprintf(stderr, "Error: Unable to resize collection\n");
            return -1;
        }

        pthread_mutex_lock(&c->lock);
    }

    c->array[c->used++] = pdu;
    pthread_mutex_unlock(&c->lock);
    return 0;
}

// Function to retrieve an element by RNTI
NFAPI_CRC_INDICATION_PDU_T* collection_get(Collection *c, int rnti) {
    pthread_mutex_lock(&c->lock);

    for (size_t i = 0; i < c->used; ++i) {
        if (c->array[i].RNTI == rnti) {
            NFAPI_CRC_INDICATION_PDU_T *result = &c->array[i];
            pthread_mutex_unlock(&c->lock);
            return result;
        }
    }

    pthread_mutex_unlock(&c->lock);
    return NULL; // Not found
}

// Function to free the collection resources
void free_collection(Collection *c) {
    if (c) {
        if (c->array) {
            free(c->array);
        }
        pthread_mutex_destroy(&c->lock);
        free(c);
    }
}
