#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <unistd.h>

#define MAX_STRUCTURES 100
#define LOG_FILE "log.txt"
#define RETRY_LIMIT 5

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T data[MAX_STRUCTURES];
    int count;
    pthread_mutex_t lock;
} PduList;

PduList pdu_list = { .count = 0, .lock = PTHREAD_MUTEX_INITIALIZER };

void log_structure(const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    static pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;
    FILE *file = fopen(LOG_FILE, "a");
    if (file) {
        pthread_mutex_lock(&log_lock);
        fprintf(file, "RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_FLAG: %d\n",
                pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRC_INDICATION_REL8_TAG);
        fflush(file);
        fclose(file);
        pthread_mutex_unlock(&log_lock);
    }
}

void update_pdu_list(NFAPI_CRC_INDICATION_PDU_T *new_pdu) {
    int retries = 0;
    while (retries < RETRY_LIMIT) {
        pthread_mutex_lock(&pdu_list.lock);

        if (pdu_list.count < MAX_STRUCTURES) {
            pdu_list.data[pdu_list.count++] = *new_pdu;
            log_structure(new_pdu);
        }

        pthread_mutex_unlock(&pdu_list.lock);

        // Simulate data source update and retry logic
        usleep(100000);  // Sleep to simulate backoff
        retries++;
    }
}

void* pdu_updater_thread(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T new_pdu = *(NFAPI_CRC_INDICATION_PDU_T*)arg;

    while (1) {
        update_pdu_list(&new_pdu);
        usleep(500000);  // Simulate periodic updates
    }

    return NULL;
}

int main() {
    pthread_t threads[2];
    NFAPI_CRC_INDICATION_PDU_T pdu1 = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 1001, .CRC_INDICATION_REL8_TAG = 0 };
    NFAPI_CRC_INDICATION_PDU_T pdu2 = { .RX_UE_INFORMATION_TAG = 2, .RNTI = 1002, .CRC_INDICATION_REL8_TAG = 1 };

    pthread_create(&threads[0], NULL, pdu_updater_thread, &pdu1);
    pthread_create(&threads[1], NULL, pdu_updater_thread, &pdu2);

    for (int i = 0; i < 2; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
