    int CRCFLAG; // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} NFALIST;

NFALIST* createList() {
    NFALIST* list = (NFALIST*)malloc(sizeof(NFALIST));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int addEntry(NFALIST* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    if (entry.RNTI > MAX_RNTI) {
        printf("Error: Invalid RNTI value\n");
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        printf("Error: Memory allocation failed\n");
        return -1;
    }
    newNode->data = entry;
    newNode->next = list->head;
    list->head = newNode;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int removeEntry(NFALIST* list, unsigned int RNTI) {
    if (RNTI > MAX_RNTI) {
        printf("Error: Invalid RNTI value\n");
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current != NULL && current->data.RNTI != RNTI) {
        prev = current;
        current = current->next;
    }
    if (!current) {
        pthread_mutex_unlock(&list->lock);
        printf("Error: Entry not found\n");
        return -1;
    }

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }
    free(current);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int updateCRCFLAG(NFALIST* list, unsigned int RNTI, int newFlag) {
    if (RNTI > MAX_RNTI) {
        printf("Error: Invalid RNTI value\n");
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current != NULL && current->data.RNTI != RNTI) {
        current = current->next;
    }
    if (!current) {
        pthread_mutex_unlock(&list->lock);
        printf("Error: Entry not found\n");
        return -1;
    }

    current->data.CRCFLAG = newFlag;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void destroyList(NFALIST* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *nextNode;
    while (current != NULL) {
        nextNode = current->next;
        free(current);
        current = nextNode;
    }
    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

