#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>

typedef struct UE {
    int ue_id;
    struct UE *next;
} UE;

typedef struct LTE_ENB_TASK_STRUCT_T {
    int cell_id;
    int frequency;
    UE *ue_list;
    pthread_mutex_t lock;
} LTE_ENB_TASK_STRUCT_T;

typedef struct DynamicList {
    LTE_ENB_TASK_STRUCT_T **list;
    size_t capacity;
    size_t size;
    pthread_rwlock_t rwlock;
} DynamicList;

DynamicList* init_dynamic_list(size_t initial_capacity) {
    DynamicList *dynamic_list = malloc(sizeof(DynamicList));
    if (!dynamic_list) return NULL;

    dynamic_list->list = calloc(initial_capacity, sizeof(LTE_ENB_TASK_STRUCT_T *));
    if (!dynamic_list->list) {
        free(dynamic_list);
        return NULL;
    }

    dynamic_list->capacity = initial_capacity;
    dynamic_list->size = 0;
    pthread_rwlock_init(&dynamic_list->rwlock, NULL);

    return dynamic_list;
}

int add_node(DynamicList *dynamic_list, int cell_id, int frequency) {
    if (!dynamic_list) return -1;

    pthread_rwlock_wrlock(&dynamic_list->rwlock);
    if (dynamic_list->size >= dynamic_list->capacity) {
        size_t new_capacity = dynamic_list->capacity * 2;
        LTE_ENB_TASK_STRUCT_T **new_list = realloc(dynamic_list->list, new_capacity * sizeof(LTE_ENB_TASK_STRUCT_T *));
        if (!new_list) {
            pthread_rwlock_unlock(&dynamic_list->rwlock);
            return -1;
        }
        dynamic_list->list = new_list;
        dynamic_list->capacity = new_capacity;
    }

    LTE_ENB_TASK_STRUCT_T *node = malloc(sizeof(LTE_ENB_TASK_STRUCT_T));
    if (!node) {
        pthread_rwlock_unlock(&dynamic_list->rwlock);
        return -1;
    }

    node->cell_id = cell_id;
    node->frequency = frequency;
    node->ue_list = NULL;
    pthread_mutex_init(&node->lock, NULL);

    dynamic_list->list[dynamic_list->size++] = node;

    pthread_rwlock_unlock(&dynamic_list->rwlock);
    return 0;
}

int add_ue_to_node(DynamicList *dynamic_list, int cell_id, int ue_id) {
    if (!dynamic_list) return -1;

    pthread_rwlock_rdlock(&dynamic_list->rwlock);
    for (size_t i = 0; i < dynamic_list->size; ++i) {
        LTE_ENB_TASK_STRUCT_T *node = dynamic_list->list[i];
        if (node && node->cell_id == cell_id) {
            pthread_mutex_lock(&node->lock);

            UE *ue = malloc(sizeof(UE));
            if (!ue) {
                pthread_mutex_unlock(&node->lock);
                return -1;
            }

            ue->ue_id = ue_id;
            ue->next = node->ue_list;
            node->ue_list = ue;

            pthread_mutex_unlock(&node->lock);
            break;
        }
    }
    pthread_rwlock_unlock(&dynamic_list->rwlock);

    return 0;
}

void free_dynamic_list(DynamicList *dynamic_list) {
    if (!dynamic_list) return;

    for (size_t i = 0; i < dynamic_list->size; ++i) {
        LTE_ENB_TASK_STRUCT_T *node = dynamic_list->list[i];
        if (node) {
            pthread_mutex_lock(&node->lock);

            UE *ue = node->ue_list;
            while (ue) {
                UE *next_ue = ue->next;
                free(ue);
                ue = next_ue;
            }

            pthread_mutex_unlock(&node->lock);
            pthread_mutex_destroy(&node->lock);
            free(node);
        }
    }

    free(dynamic_list->list);
    pthread_rwlock_destroy(&dynamic_list->rwlock);
    free(dynamic_list);
}

int main() {
    size_t initial_capacity = 10;
    DynamicList *dynamic_list = init_dynamic_list(initial_capacity);

    if (!dynamic_list) {
        fprintf(stderr, "Failed to initialize dynamic list.\n");
        return EXIT_FAILURE;
    }

    // Example usage
    add_node(dynamic_list, 1, 1800);
    add_ue_to_node(dynamic_list, 1, 101);
    add_ue_to_node(dynamic_list, 1, 102);

    free_dynamic_list(dynamic_list);
    return EXIT_SUCCESS;
}
```

### Explanation:
