#define MAX_ENTRIES 1000000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned int CRCFLAG : 1; // only one bit needed
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} CRCList;

// Function to generate a random number between min and max
int rand_range(int min, int max) {
    return min + rand() % (max - min + 1);
}

void log_message(const char *message) {
    // Simple logging function; can be extended for more sophisticated logging
    printf("%s\n", message);
}

CRCList* create_crc_list(size_t initial_capacity) {
    if (initial_capacity == 0 || initial_capacity > MAX_ENTRIES) {
        log_message("Invalid initial capacity");
        return NULL;
    }

    CRCList *list = malloc(sizeof(CRCList));
    if (!list) {
        log_message("Memory allocation failed for CRCList structure");
        return NULL;
    }

    list->entries = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->entries) {
        free(list);
        log_message("Memory allocation failed for entries array");
        return NULL;
    }

    pthread_mutex_init(&list->lock, NULL);

    list->count = 0;
    list->capacity = initial_capacity;

    log_message("CRCList created successfully");

    return list;
}

int add_entry(CRCList *list) {
    if (!list || !pthread_mutex_trylock(&list->lock)) {
        log_message("Lock acquisition failed or invalid list");
        return -1;
    }

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;

        NFAPI_CRC_INDICATION_PDU_T *new_entries = realloc(list->entries, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_entries) {
            pthread_mutex_unlock(&list->lock);
            log_message("Memory reallocation failed");
            return -1;
        }

        list->entries = new_entries;
        list->capacity = new_capacity;

        log_message("Entries array resized successfully");
    }

    // Simulating the addition of a random entry
    NFAPI_CRC_INDICATION_PDU_T *entry = &list->entries[list->count++];
    entry->RX_UE_INFORMATION_TAG = rand_range(1, 1000);
    entry->RNTI = rand_range(1, 5000);
    entry->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    pthread_mutex_unlock(&list->lock);

    return 0;
}

void free_crc_list(CRCList *list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);
    free(list->entries);
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}

void populate_crc_list(CRCList *list, size_t n_entries) {
