['Below is a C implementation that fulfills the requirements specified in the task description. It uses a dynamic list with mutexes for concurrency control.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_SIZE 1024

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG data;
    int index; // To keep track of the insertion order
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T info;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    int size;
    pthread_mutex_t lock;
} DynamicList;

void init_list(DynamicList* list) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T info, int index) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->info = info;
    new_node->index = index;
    new_node->next = NULL;
    new_node->prev = NULL;
    return new_node;
}

void add_element(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T info) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *node_to_update = NULL;

    // Check for existing RNTI and update if found
    while (current != NULL) {
        if (current->info.data.RNTI == info.data.RNTI) {
            current->info = info;
            node_to_update = current;
            break;
        }
        current = current->next;
    }

    if (!node_to_update && list->size < MAX_SIZE) { // Add new element
        Node* new_node = create_node(info, ++list->tail->index);
        if (!new_node) {
            pthread_mutex_unlock(&list->lock);
            return;
        }

        new_node->next = NULL;
        new_node->prev = list->tail;
        if (list->tail) {
            list->tail->next = new_node;
        } else {
            list->head = new_node;
        }
        list->tail = new_node;

        if (list->size == MAX_SIZE - 1) { // Remove LRU
            Node* lru_node = list->head;
            list->head = list->head->next;
            if (list->head) {
                list->head->prev = NULL;
            } else {
                list->tail = NULL; // Empty list now
            }
            free(lru_node);
        }

        ++list->size;
    }

    pthread_mutex_unlock(&list->lock);
}

void remove_element(DynamicList* list, uint16_t rnti) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;

    while (current != NULL) {
        if (current->info.data.RNTI == rnti) {
            if (current->prev) current->prev->next = current->next;
            else list->head = current->next; // Remove head

            if (current->next) current->next->prev = current->prev;
            else list->tail = current->prev; // Remove tail

            free(current);
            --list->size;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void destroy_list(DynamicList* list) {
    Node *current = list->head, *temp;

    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&list->lock);
    init_list(list); // Reset the list
}

void print_list(DynamicList* list) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->tail;

    while (current != NULL) {
        printf("RNTI: %u, CRCFLAG: %d\n", current->info.data.RNTI, current->info.data.CRCFLAG);
        current = current->prev;
    }

    pthread_mutex_unlock(&list->lock);
}

// Sample usage
int main() {
    DynamicList list;
    init_list(&list);

    // Create a test NFAPI_CRC_INDICATION_PDU_T structure
    CRC_INDICATION_REL8_TAG tag1 = { .RX_UE_INFORMATION_TAG = 100, .RNTI = 200, .CRCFLAG = rand() % 2 };
    CRC_INDICATION_REL8_TAG tag2 = { .RX_UE_INFORMATION_TAG = 101, .RNTI = 201, .CRCFLAG = rand() % 2 };

    NFAPI_CRC_INDICATION_PDU_T pdu1 = { .data = tag1 };
    NFAPI_CRC_INDICATION_PDU_T pdu2 = { .data = tag2 };

    // Add elements
    add_element(&list, pdu1);
    add_element(&list, pdu2);

    // Print the list
    print_list(&list);

    // Remove an element
    remove_element(&list, 200);

    // Print the list again
    print_list(&list);

    destroy_list(&list);
    return 0;
}
```

This code initializes a doubly-linked list with nodes representing `NFAPI_CRC_INDICATION_PDU_T` structures. The list is protected by mutexes for thread safety. It supports addition, removal, and maintains constraints like unique RNTI values and maximum size through Least Recently Used (LRU) eviction policy.']

