import threading

typedef struct {
    int id;
    char *content;
} PHY_RRC_MESSAGE;

typedef struct {
    int srb_id;
    char *payload;
} PHY_SRB_MESSAGE;

typedef struct {
    PHY_RRC_MESSAGE rrc_message;
    PHY_SRB_MESSAGE srb_message;
} LTE_PHY_PDU;

typedef struct Node {
    LTE_PHY_PDU pdu;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    size_t count;
    threading.Lock lock;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *array = (DynamicArray *)malloc(sizeof(DynamicArray));
    if (!array) return NULL;
    array->head = NULL;
    array->count = 0;
    threading.Lock_init(&array->lock);
    return array;
}

void log_action(const char *action, LTE_PHY_PDU pdu) {
    printf("Action: %s, RRC Message ID: %d, SRB Message ID: %d\n", action,
           pdu.rcr_message.id, pdu.srb_message.srb_id);
}

int add_pdu(DynamicArray *array, LTE_PHY_PDU pdu) {
    threading.Lock_acquire(&array->lock);

    Node *new_node = (Node *)malloc(sizeof(Node));
    if (!new_node) {
        threading.Lock_release(&array->lock);
        return -1; // Error: Memory allocation failed
    }

    new_node->pdu = pdu;
    new_node->next = array->head;
    array->head = new_node;
    array->count++;

    log_action("ADD", pdu);

    threading.Lock_release(&array->lock);
    return 0; // Success
}

int update_pdu(DynamicArray *array, int rrc_id, PHY_RRC_MESSAGE new_rrc_msg) {
    threading.Lock_acquire(&array->lock);

    Node *current = array->head;
    while (current) {
        if (current->pdu.rcr_message.id == rrc_id) {
            current->pdu.rcr_message = new_rrc_msg;
            log_action("UPDATE", current->pdu);
            threading.Lock_release(&array->lock);
            return 0; // Success
        }
        current = current->next;
    }

    threading.Lock_release(&array->lock);
    return -2; // Error: PDU not found
}

int remove_pdu(DynamicArray *array, int rrc_id) {
    threading.Lock_acquire(&array->lock);

    Node **indirect = &array->head;
    while (*indirect) {
        if ((*indirect)->pdu.rcr_message.id == rrc_id) {
            Node *node_to_remove = *indirect;
            *indirect = node_to_remove->next;
            free(node_to_remove);
            array->count--;

            log_action("REMOVE", node_to_remove->pdu);

            threading.Lock_release(&array->lock);
            return 0; // Success
        }
        indirect = &(*indirect)->next;
    }

    threading.Lock_release(&array->lock);
    return -2; // Error: PDU not found
}

void free_dynamic_array(DynamicArray *array) {
    if (!array) return;

    Node *current = array->head;
    while (current) {
        Node *next_node = current->next;
        free(current);
        current = next_node;
    }

    threading.Lock_destroy(&array->lock);
    free(array);
}

int main() {
    DynamicArray *array = create_dynamic_array();
    if (!array) return -1;

    LTE_PHY_PDU pdu1 = {{.id = 1, .content = "RRM1"}, {.srb_id = 101, .payload = "SRB1"}};
    add_pdu(array, pdu1);

    PHY_RRC_MESSAGE new_rrc_msg = {.id = 1, .content = "Updated RRM"};
    update_pdu(array, 1, new_rrc_msg);

    remove_pdu(array, 1);

    free_dynamic_array(array);

    return 0;
}
