['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    bool CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
    struct NFAPI_CRC_INDICATION_PDU_T *prev;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    NFAPI_CRC_INDICATION_PDU_T *tail;
} CRC_List;

// Function to create a new node
static NFAPI_CRC_INDICATION_PDU_T* create_node(unsigned int tag, unsigned int rnti) {
    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) return NULL;

    new_node->RX_UE_INFORMATION_TAG = tag;
    new_node->RNTI = rnti;
    new_node->crc_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    new_node->next = NULL;
    new_node->prev = NULL;

    return new_node;
}

// Function to insert a node, ensuring no duplicate RNTIs
bool insert_node(CRC_List *list, unsigned int tag, unsigned int rnti) {
    if (!list) return false;

    // Check for duplicates
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        if (current->RNTI == rnti) return false; // Duplicate found
        current = current->next;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_node = create_node(tag, rnti);
    if (!new_node) return false;

    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    }

    return true;
}

// Function to iterate over the list in forward order
void iterate_forward(CRC_List *list, void (*callback)(CRC_INDICATION_REL8_TAG tag)) {
    if (!list || !callback) return;

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        callback(current->crc_tag);
        current = current->next;
    }
}

// Function to iterate over the list in reverse order
void iterate_reverse(CRC_List *list, void (*callback)(CRC_INDICATION_REL8_TAG tag)) {
    if (!list || !callback) return;

    NFAPI_CRC_INDICATION_PDU_T *current = list->tail;
