#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

#define MAX_LIST_SIZE 1000
#define LOG_FILE "nfa_crc_indication.log"

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        int CRCFLAG; // Assume this is an integer for simplicity
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
    pthread_mutex_t lock;
} LinkedList;

void initialize_list(LinkedList* list) {
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

int generate_unique_rnti(LinkedList* list, uint16_t* rnti) {
    while (1) {
        *rnti = rand() % 65535; // Generate a random RNTI
        pthread_mutex_lock(&list->lock);
        Node* current = list->head;
        while (current != NULL) {
            if (current->data.RNTI == *rnti) break;
            current = current->next;
        }
        pthread_mutex_unlock(&list->lock);
        if (current == NULL) return 1; // Unique RNTI found
    }
}

void add_to_list(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (list->size >= MAX_LIST_SIZE) return;

    Node* new_node = create_node(data);
    if (!new_node) return;

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    list->size++;
    pthread_mutex_unlock(&list->lock);

    log_data_to_file(list, data); // Logging function
}

void log_data_to_file(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    static pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;
    FILE* file = fopen(LOG_FILE, "a");
    if (!file) return;

    pthread_mutex_lock(&log_lock);
    fprintf(file, "RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n",
            data.RX_UE_INFORMATION_TAG, data.RNTI, data.CRC_INDICATION_REL8_TAG.CRCFLAG);
    fclose(file);

    pthread_mutex_unlock(&log_lock);
}

void free_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    list->size = 0;
    pthread_mutex_destroy(&list->lock);
}

void populate_list(LinkedList* list, size_t num_elements) {
    srand(time(NULL));
    for (size_t i = 0; i < num_elements; ++i) {
        NFAPI_CRC_INDICATION_PDU_T data;
        data.RX_UE_INFORMATION_TAG = rand() % 65535;

        uint16_t rnti;
        if (generate_unique_rnti(list, &rnti)) {
            data.RNTI = rnti;
        } else {
            continue; // Skip if no unique RNTI can be generated
        }

        data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRCFLAG

        add_to_list(list, data);
    }
}

int main() {
    LinkedList list;
    initialize_list(&list);

    pthread_t threads[4];
    for (int i = 0; i < 4; ++i) {
        pthread_create(&threads[i], NULL, (void*(*)(void*))populate_list, &list);
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    free_list(&list);

    return 0;
}
```

