FSA_State* populate_fsa_states(int *states, int num_states, FSA_State **fsa, int last_state_index) {
    if (!fsa || !(*fsa)) return NULL;

    srand(time(NULL));

    // Allocate memory for the new states
    FSA_State *new_states = (FSA_State*)malloc(num_states * sizeof(FSA_State));
    if (!new_states) return NULL;

    for (int i = 0; i < num_states; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!data) {
            // Free already allocated states in case of failure
            while (--i >= 0) free(new_states[i].data);
            free(new_states);
            return NULL;
        }

        new_states[i].data = data;

        // Populate data fields with random values
        data->RX_UE_INFORMATION_TAG = rand() % 100; // Example range
        data->RNTI = rand() % 1000; // Example range
        data->CRC_INDICATION_REL8_TAG = rand();
        data->CRCFLAG = rand() & 1; // Randomly set to 0 or 1

        new_states[i].next = (i == num_states - 1) ? NULL : &new_states[i + 1];
    }

    // Link the last state in the existing FSA to the new states
    (*fsa)[last_state_index].next = new_states;

    return new_states;
}
