#define VALID_INT_MIN -2147483648
#define VALID_INT_MAX  2147483647

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

// Helper function to find the largest integer in an array
int find_largest_int(const int* arr, size_t size) {
    if (size == 0) return INT_MIN; // Return minimum possible value for empty arrays

    int max = arr[0];
    for (size_t i = 1; i < size; ++i) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

// Function to process the stream of integers
int process_integer_stream(int socket_fd, int* error_code) {
    const size_t initial_size = 10;
    int* numbers = malloc(initial_size * sizeof(int));
    if (!numbers) {
        *error_code = -1; // Memory allocation failure
        return INT_MIN;
    }

    size_t current_capacity = initial_size;
    size_t count = 0;

    NFAPI_CRC_INDICATION_PDU_T* pdu_list = NULL;
    size_t pdu_count = 0;

    ssize_t received_bytes;
    int number;
    char buffer[4];
    time_t start_time, end_time;

    if (clock_gettime(CLOCK_MONOTONIC, &start_time) != 0) {
        *error_code = -2; // Time fetching failure
        free(numbers);
        return INT_MIN;
    }

    while ((received_bytes = recv(socket_fd, buffer, sizeof(buffer), MSG_DONTWAIT)) > 0) {
        if (count >= current_capacity) {
            size_t new_capacity = current_capacity * 2;
            int* temp = realloc(numbers, new_capacity * sizeof(int));
            if (!temp) {
                *error_code = -3; // Reallocation failure
                free(numbers);
                return INT_MIN;
            }
            numbers = temp;
            current_capacity = new_capacity;
        }

        memcpy(&number, buffer, received_bytes);

        // Validate the integer's correctness and range
        if (received_bytes == sizeof(number) && number >= VALID_INT_MIN && number <= VALID_INT_MAX) {
            numbers[count++] = number;

            // Create a new PDU structure for valid data
            pdu_list = realloc(pdu_list, (pdu_count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!pdu_list) {
                *error_code = -4; // Reallocation failure for PDUs
                free(numbers);
                return INT_MIN;
            }

            pdu_list[pdu_count].RX_UE_INFORMATION_TAG = rand();
            pdu_list[pdu_count].RNTI = rand() & 0xFFFF;
            pdu_list[pdu_count].CRCFLAG = rand() % 2; // Randomly set CRCFLAG
            time(&pdu_list[pdu_count].timestamp);

            ++pdu_count;
        }
    }

    if (received_bytes < 0) {
        *error_code = -5; // Socket read error
    } else {
        clock_gettime(CLOCK_MONOTONIC, &end_time);
        double processing_time = difftime(end_time.tv_sec + end_time.tv_nsec / 1e9,
                                          start_time.tv_sec + start_time.tv_nsec / 1e9);

        printf("Processing Time: %.6f seconds\n", processing_time); // Placeholder for logging framework
    }

    int largest_number = find_largest_int(numbers, count);

    free(numbers);
    free(pdu_list);

    return largest_number;
}
