#define MAX_UE_SESSIONS 10000
#define DEFAULT_POOL_SIZE 10

typedef struct {
    int rnti;
    // Add other session-specific parameters here
} UE_Session;

typedef struct {
    pthread_t *threads;
    size_t thread_count;
    UE_Session **sessions;
    size_t current_load;
    size_t capacity;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    FILE *config_file;
} NetworkInterface;

NetworkInterface* initialize_network_interface(size_t initial_capacity, const char *config_path) {
    NetworkInterface *ni = malloc(sizeof(NetworkInterface));
    if (!ni) return NULL;

    ni->thread_count = DEFAULT_POOL_SIZE;
    ni->threads = calloc(ni->thread_count, sizeof(pthread_t));
    if (!ni->threads) {
        free(ni);
        return NULL;
    }

    ni->sessions = calloc(initial_capacity, sizeof(UE_Session *));
    if (!ni->sessions) {
        free(ni->threads);
        free(ni);
        return NULL;
    }

    ni->current_load = 0;
    ni->capacity = initial_capacity;

    pthread_mutex_init(&ni->lock, NULL);
    pthread_cond_init(&ni->cond, NULL);

    // Load configuration file
    ni->config_file = fopen(config_path, "r");
    if (!ni->config_file) {
        perror("Failed to open config file");
        free(ni->sessions);
        free(ni->threads);
        free(ni);
        return NULL;
    }

    // Example: read configurations from the file
    // Implement parsing logic here

    return ni;
}

void resize_ue_sessions(NetworkInterface *ni, size_t new_capacity) {
    pthread_mutex_lock(&ni->lock);

    UE_Session **new_sessions = realloc(ni->sessions, new_capacity * sizeof(UE_Session *));
    if (new_sessions) {
        memset(new_sessions + ni->capacity, 0, (new_capacity - ni->capacity) * sizeof(UE_Session *));
        ni->sessions = new_sessions;
        ni->capacity = new_capacity;
    }

    pthread_mutex_unlock(&ni->lock);
}

void handle_error(const char *message) {
    perror(message);
    exit(EXIT_FAILURE);
}

static void* session_handler(void *arg) {
    NetworkInterface *ni = (NetworkInterface*)arg;

    while (1) {
        pthread_mutex_lock(&ni->lock);

        while (ni->current_load == 0) {
            pthread_cond_wait(&ni->cond, &ni->lock);
        }

        // Retrieve and process a session
        UE_Session *session = ni->sessions[0];
        if (!session) continue;

        // Process the session...

        // Simulating processing by freeing the session
        free(session);
        memmove(ni->sessions, ni->sessions + 1, (ni->current_load - 1) * sizeof(UE_Session*));
        ni->current_load--;

        pthread_mutex_unlock(&ni->lock);

        usleep(1000); // Simulate work delay
    }

    return NULL;
}

void start_threads(NetworkInterface *ni) {
    for (size_t i = 0; i < ni->thread_count; ++i) {
        if (pthread_create(&ni->threads[i], NULL, session_handler, ni)) {
            handle_error("Failed to create thread");
        }
    }
}

int add_ue_session(NetworkInterface *ni, int rnti) {
    pthread_mutex_lock(&ni->lock);

    if (ni->current_load >= ni->capacity) {
        resize_ue_sessions(ni, ni->capacity * 2);
    }

    UE_Session *new_session = malloc(sizeof(UE_Session));
    if (!new_session) {
        pthread_mutex_unlock(&ni->lock);
        return -1;
    }

    new_session->rnti = rnti;

    ni->sessions[ni->current_load++] = new_session;
    pthread_cond_signal(&ni->cond);

    pthread_mutex_unlock(&ni->lock);

    return 0;
}

void cleanup_network_interface(NetworkInterface *ni) {
    for (size_t i = 0; i < ni->thread_count; ++i) {
        pthread_cancel(ni->threads[i]);
    }

    for (size_t i = 0; i < ni->current_load; ++i) {
        free(ni->sessions[i]);
    }

    fclose(ni->config_file);
    free(ni->sessions);
    free(ni->threads);
    pthread_mutex_destroy(&ni->lock);
    pthread_cond_destroy(&ni->cond);

    free(ni);
}

int main() {
    NetworkInterface *ni = initialize_network_interface(100, "config.txt");
    if (!ni) return EXIT_FAILURE;

    start_threads(ni);

    for (int rnti = 1; rnti <= 10000; ++rnti) {
        if (add_ue_session(ni, rnti) != 0) {
            fprintf(stderr, "Failed to add session for RNTI %d\n", rnti);
        }
