// Object pool for efficient memory management
#define POOL_SIZE 1024

NFAPI_CRC_INDICATION_PDU_T* object_pool[POOL_SIZE];
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_object_pool() {
    for (int i = 0; i < POOL_SIZE; ++i) {
        object_pool[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!object_pool[i]) exit(EXIT_FAILURE); // Handle allocation failure
    }
}

NFAPI_CRC_INDICATION_PDU_T* acquire_object() {
    pthread_mutex_lock(&pool_lock);
    for (int i = 0; i < POOL_SIZE; ++i) {
        if (object_pool[i] != NULL) {
            NFAPI_CRC_INDICATION_PDU_T* obj = object_pool[i];
            object_pool[i] = NULL;
            pthread_mutex_unlock(&pool_lock);
            return obj;
        }
    }
    pthread_mutex_unlock(&pool_lock);
    return NULL; // Pool exhausted
}

void release_object(NFAPI_CRC_INDICATION_PDU_T* obj) {
    pthread_mutex_lock(&pool_lock);
    for (int i = 0; i < POOL_SIZE; ++i) {
        if (object_pool[i] == NULL) {
            object_pool[i] = obj;
            break;
        }
