    int status_update_interval;
    bool logging_enabled;
    // NMS related statistics
    size_t processed_frames;
    size_t lost_frames;
    size_t crc_errors;

} LTE_Frame_Manager;

void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void resize_frame_collection(LTE_Frame_Manager* manager) {
    size_t new_capacity = manager->capacity * 2;
    LTE_PHY_RX_FRAME_T* new_frames = allocate_memory(new_capacity * sizeof(LTE_PHY_RX_FRAME_T));

    memcpy(new_frames, manager->frames, manager->count * sizeof(LTE_PHY_RX_FRAME_T));
    free(manager->frames);
    manager->frames = new_frames;
    manager->capacity = new_capacity;

    if (manager->logging_enabled) {
        printf("Resized frame collection to %zu\n", new_capacity);
    }
}

bool check_crc_error_rate(LTE_Frame_Manager* manager) {
    return ((double)manager->crc_errors / (double)(manager->processed_frames + manager->lost_frames)) > manager->max_crc_error_rate;
}

void add_frame(LTE_Frame_Manager* manager, LTE_PHY_RX_FRAME_T frame) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        resize_frame_collection(manager);
    }

    manager->frames[manager->count++] = frame;

    // Simulate CRC flag generation
    manager->frames[manager->count - 1].crc_indication.CRC_FLAG = rand() % 2 == 0;

    if (!manager->frames[manager->count - 1].crc_indication.CRC_FLAG) {
        manager->crc_errors++;
    } else {
        manager->processed_frames++;
    }

    pthread_mutex_unlock(&manager->lock);
}

void report_statistics(LTE_Frame_Manager* manager) {
    double frame_loss_rate = (double)(manager->lost_frames) / (double)(manager->count + manager->lost_frames);
    double crc_error_rate = check_crc_error_rate(manager);

    // Report to NMS
    printf("Processed Frames: %zu\n", manager->processed_frames);
    printf("Frame Loss Rate: %.2f%%\n", frame_loss_rate * 100.0);
    printf("CRC Error Rate: %.2f%%\n", crc_error_rate * 100.0);

    if (crc_error_rate > manager->max_crc_error_rate) {
        // Handle high CRC error rate
        fprintf(stderr, "High CRC Error Rate detected\n");
    }
}

void init_frame_manager(LTE_Frame_Manager* manager, size_t initial_capacity, double max_crc_error_rate,
                        int status_update_interval, bool logging_enabled) {
    memset(manager, 0, sizeof(*manager));

    manager->frames = allocate_memory(initial_capacity * sizeof(LTE_PHY_RX_FRAME_T));
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);
    manager->max_crc_error_rate = max_crc_error_rate;
    manager->status_update_interval = status_update_interval;
    manager->logging_enabled = logging_enabled;
}

void destroy_frame_manager(LTE_Frame_Manager* manager) {
    free(manager->frames);
    pthread_mutex_destroy(&manager->lock);
}

int main() {
    LTE_Frame_Manager manager;

    init_frame_manager(&manager, INITIAL_CAPACITY, 0.05, 60, true);

    for (size_t i = 0; i < 100; ++i) {
        LTE_PHY_RX_FRAME_T frame;
        // Initialize frame with sample data
        add_frame(&manager, frame);
    }

    report_statistics(&manager);

    destroy_frame_manager(&manager);

    return 0;
}
