    if (!dyn_array) return NULL;

    dyn_array->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!dyn_array->array) {
