    resize_if_needed(dyn_array);

    NFAPI_CRC_INDICATION_PDU_T new_elem = {tag, rnti, crc_tag, hash_rnti(rnti)};
    dyn_array->array[dyn_array->count++] = new_elem;

    pthread_mutex_unlock(&dyn_array->mutex);
    return 0;
}

// Resize the array if needed
void resize_if_needed(DynamicArray *dyn_array) {
    if (dyn_array->count >= dyn_array->capacity) {
        size_t new_capacity = dyn_array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(dyn_array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) return; // Handle memory allocation failure gracefully

        dyn_array->capacity = new_capacity;
        dyn_array->array = new_array;
    }
}

// Get the total number of elements in the array
size_t get_total_elements(const DynamicArray *dyn_array) {
    pthread_mutex_lock(&dyn_array->mutex);
    size_t count = dyn_array->count;
    pthread_mutex_unlock(&dyn_array->mutex);
    return count;
}

// Retrieve an element by index
NFAPI_CRC_INDICATION_PDU_T* get_element(const DynamicArray *dyn_array, size_t index) {
    if (index >= dyn_array->count) return NULL;

    return &dyn_array->array[index];
}

// A simple hash function for RNTI
int hash_rnti(uint16_t rnti) {
    // Example hash function: parity of the RNTI value
    return __builtin_parity(rnti);
}

// Free the dynamic array resources
void free_dynamic_array(DynamicArray *dyn_array) {
    pthread_mutex_lock(&dyn_array->mutex);

    if (dyn_array->array) {
        free(dyn_array->array);
        dyn_array->array = NULL;
    }

    dyn_array->count = 0;
    dyn_array->capacity = 0;

    pthread_mutex_unlock(&dyn_array->mutex);
    pthread_mutex_destroy(&dyn_array->mutex);
    free(dyn_array);
}

