    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int validate_crc(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Placeholder for actual CRC validation logic
    return 1; // Assume valid for demonstration
}

void insert_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    if (!validate_crc(data)) return;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return;
    new_node->data = *data;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = new_node;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    pthread_mutex_unlock(&list->lock);
}

void clear_outdated_entries(LinkedList* list, unsigned int timeout) {
    time_t now = time(NULL);

    pthread_mutex_lock(&list->lock);
    Node *current = list->head, *prev = NULL;

    while (current != NULL) {
        // Placeholder condition for outdated entries
        if ((now - current->data.RX_UE_INFORMATION_TAG) > timeout) {
            Node* to_delete = current;
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            current = current->next;
            free(to_delete);
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void* periodic_clear(void* arg) {
    LinkedList* list = (LinkedList*)arg;
    while (1) {
        clear_outdated_entries(list, 60); // Example timeout of 60 seconds
        sleep(10); // Clear every 10 seconds
    }
    return NULL;
}

int main() {
    LinkedList* list = create_list();

    pthread_t cleanup_thread;
    if (pthread_create(&cleanup_thread, NULL, periodic_clear, list) != 0) {
        perror("Failed to create cleanup thread");
        destroy_list(list);
        return EXIT_FAILURE;
    }

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = time(NULL), .RNTI = 12345 };
    srand(time(NULL));
    pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

    insert_node(list, &pdu);

    // Wait for cleanup thread (in a real application, handle threads properly)
    pthread_join(cleanup_thread, NULL);

    destroy_list(list);
    return EXIT_SUCCESS;
}
