int allocate_crc_indication_pdu(int desired_count, NFAPI_CRC_INDICATION_PDU_T **allocated_array) {
    if (desired_count <= 0) desired_count = DEFAULT_NUM_STRUCTURES;

    // Calculate total memory required
    size_t structure_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    size_t total_memory_required = desired_count * structure_size;

    if (total_memory_required > MAX_MEMORY_BUDGET) {
        printf("Error: Memory requirement exceeds maximum budget.\n");
        return -1;
    }

    // Thread-safe memory allocation
    pthread_mutex_lock(&allocation_mutex);

    NFAPI_CRC_INDICATION_PDU_T *array = malloc(total_memory_required);
    if (!array) {
        printf("Error: Memory allocation failed.\n");
        pthread_mutex_unlock(&allocation_mutex);
        return -2;
    }

    // Initialize structures and ensure RNTI uniqueness
    unsigned int rnti_set[desired_count] = {0};
    for (int i = 0; i < desired_count; ++i) {
