            array[i].rnti = rand(); // Replace with actual RX_UE_INFORMATION_TAG generation if needed
        } while (rnti_set[array[i].rnti % desired_count]);

        rnti_set[array[i].rnti % desired_count] = 1;
    }

    *allocated_array = array;

    pthread_mutex_unlock(&allocation_mutex);
    printf("Memory allocated successfully for %d structures.\n", desired_count);

    return 0; // Success
}

void free_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T **allocated_array) {
    if (allocated_array && *allocated_array) {
