    NetworkEvent *newEvents = (NetworkEvent *)realloc(ea->events, newCapacity * sizeof(NetworkEvent));
    if (!newEvents) return -1; // Memory allocation failed
    ea->events = newEvents;
    ea->capacity = newCapacity;
    return 0;
}

int addEvent(EventArray *ea, NetworkEvent event) {
    if (ea->count == ea->capacity) {
        if (resizeEventArray(ea, ea->capacity * 2) != 0) return -1; // Failed to resize
    }
