    time_t currentTime = time(NULL);
    for (size_t i = 0; i < ea->count; ++i) {
        if (currentTime - ea->events[i].timestamp <= ageThreshold) {
            ea->events[writeIndex++] = ea->events[i];
        }
    }
    ea->count = writeIndex;
}

