    for (size_t i = 0; i < ea->count; ++i) {
        totalSignalStrength += ea->events[i].signalStrength;
        if (ea->events[i].networkLoadPercentage > maxNetworkLoad) {
            maxNetworkLoad = ea->events[i].networkLoadPercentage;
        }
