#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_CONNECTIONS 100000

typedef struct {
    char source_ip[16];
    char destination_ip[16];
    time_t last_connection_attempt;
} TCP_CONNECTION_RECORD_T;

typedef struct {
    TCP_CONNECTION_RECORD_T *records;
    size_t count;
    pthread_mutex_t lock;
} ConnectionManager;

ConnectionManager* create_connection_manager() {
    ConnectionManager *manager = (ConnectionManager *)malloc(sizeof(ConnectionManager));
    manager->records = NULL;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_connection_manager(ConnectionManager *manager) {
    if (manager != NULL) {
        free(manager->records);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

int record_exists(TCP_CONNECTION_RECORD_T *records, size_t count, const char *source_ip, const char *destination_ip) {
    for (size_t i = 0; i < count; i++) {
        if (strcmp(records[i].source_ip, source_ip) == 0 && strcmp(records[i].destination_ip, destination_ip) == 0) {
            return 1;
        }
    }
    return 0;
}

void add_connection(ConnectionManager *manager, const char *source_ip, const char *destination_ip) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= MAX_CONNECTIONS) {
        printf("Max connections reached. Cannot add new connection.\n");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    if (!record_exists(manager->records, manager->count, source_ip, destination_ip)) {
        if (manager->count == 0) {
            manager->records = (TCP_CONNECTION_RECORD_T *)malloc(sizeof(TCP_CONNECTION_RECORD_T));
        } else {
            manager->records = (TCP_CONNECTION_RECORD_T *)realloc(manager->records, (manager->count + 1) * sizeof(TCP_CONNECTION_RECORD_T));
        }
        strcpy(manager->records[manager->count].source_ip, source_ip);
        strcpy(manager->records[manager->count].destination_ip, destination_ip);
        manager->records[manager->count].last_connection_attempt = time(NULL);
        manager->count++;
    } else {
        for (size_t i = 0; i < manager->count; i++) {
            if (strcmp(manager->records[i].source_ip, source_ip) == 0 && strcmp(manager->records[i].destination_ip, destination_ip) == 0) {
                manager->records[i].last_connection_attempt = time(NULL);
            }
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

TCP_CONNECTION_RECORD_T* get_recent_record(ConnectionManager *manager, const char *source_ip, const char *destination_ip) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; i++) {
        if (strcmp(manager->records[i].source_ip, source_ip) == 0 && strcmp(manager->records[i].destination_ip, destination_ip) == 0) {
            TCP_CONNECTION_RECORD_T *record = &manager->records[i];
            pthread_mutex_unlock(&manager->lock);
            return record;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

int main() {
    ConnectionManager *manager = create_connection_manager();

    add_connection(manager, "192.168.1.1", "10.0.0.1");
    add_connection(manager, "192.168.1.2", "10.0.0.2");

    TCP_CONNECTION_RECORD_T *record = get_recent_record(manager, "192.168.1.1", "10.0.0.1");
    if (record != NULL) {
        printf("Recent connection: %s -> %s at %ld\n", record->source_ip, record->destination_ip, record->last_connection_attempt);
    }

    destroy_connection_manager(manager);
    return 0;
}
