    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->totalMemoryUsed = 0;
    list->eventCount = 0;
    list->totalSignalStrength = 0.0f;

    return list;
}

int add_event(EventList* list, EventType eventType, time_t timestamp, int cellID, float signalStrength) {
    pthread_mutex_lock(&list->lock);

    if (!list || signalStrength < -100 || signalStrength > 100) {
        log_error("Invalid data or null list");
        pthread_mutex_unlock(&list->lock);
        return ERROR_INDICATOR;
    }

    EventNode* new_node = (EventNode*)malloc(sizeof(EventNode));
    if (!new_node) {
        log_error("Memory allocation failed for new event node");
        pthread_mutex_unlock(&list->lock);
        return ERROR_INDICATOR;
    }

    list->totalMemoryUsed += sizeof(EventNode);

    if (list->totalMemoryUsed > MAX_MEMORY_USAGE) {
        evict_old_events(list, sizeof(EventNode));
    }

    new_node->eventType = eventType;
    new_node->timestamp = timestamp;
    new_node->cellID = cellID;
    new_node->signalStrength = signalStrength;

    new_node->next = list->head;
    list->head = new_node;
    list->eventCount++;
    list->totalSignalStrength += signalStrength;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void evict_old_events(EventList* list, size_t memoryToFree) {
    EventNode **curr = &list->head;
    while (*curr && list->totalMemoryUsed > MAX_MEMORY_USAGE - memoryToFree) {
        EventNode *old_node = *curr;
        *curr = old_node->next;

        list->totalMemoryUsed -= sizeof(EventNode);
        list->eventCount--;
        list->totalSignalStrength -= old_node->signalStrength;

        free(old_node);
    }
}

void remove_outdated_events(EventList* list, time_t currentTime, int ageThreshold) {
    pthread_mutex_lock(&list->lock);

    EventNode **curr = &list->head;
    while (*curr) {
        if (difftime(currentTime, (*curr)->timestamp) > ageThreshold) {
            EventNode *old_node = *curr;
            *curr = old_node->next;

            list->totalMemoryUsed -= sizeof(EventNode);
            list->eventCount--;
            list->totalSignalStrength -= old_node->signalStrength;

            free(old_node);
        } else {
            curr = &(*curr)->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void get_statistics(const EventList* list, unsigned long* totalEvents, float* averageSignalStrength) {
    pthread_mutex_lock((pthread_mutex_t*)&list->lock);

    if (totalEvents) *totalEvents = list->eventCount;
    if (averageSignalStrength && list->eventCount > 0)
        *averageSignalStrength = list->totalSignalStrength / list->eventCount;

    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
}

void log_error(const char* message) {
    time_t now = time(NULL);
    fprintf(stderr, "[%s] ERROR: %s\n", ctime(&now), message);
}

void destroy_event_list(EventList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    EventNode* current = list->head;
    while (current) {
        EventNode* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Test cases
void run_tests() {
    // Implement test cases here, covering normal operation, edge cases, and failure scenarios.
}
```

This code provides a thread-safe linked list with functions for adding events, removing outdated ones, evicting old nodes to manage memory usage, and getting statistics. It includes logging for error handling and uses mutexes for synchronization across threads. Adjust the `MAX_MEMORY_USAGE` constant as needed based on your system's constraints.']

