    }

    return 0;
}

int sort_records(record *records, size_t count) {
    if (count == 0 || records == NULL) return 0;

    // Use qsort for simplicity and efficiency.
    int compare_ints(const void *a, const void *b) {
        return ((record *)a)->value - ((record *)b)->value;
    }

    qsort(records, count, sizeof(record), compare_ints);
    return 0;
}

int allocate_and_init_offset_array(long **offsets, size_t count) {
