#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_ENTRIES 100000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t count;
    pthread_mutex_t mutex;
    FILE *log_file;
} DynamicArray;

// Function to initialize the dynamic array
void init_dynamic_array(DynamicArray *array, const char *log_filename) {
    array->data = NULL;
    array->count = 0;
    if (pthread_mutex_init(&array->mutex, NULL) != 0) {
        perror("Mutex initialization failed");
        exit(EXIT_FAILURE);
    }
    array->log_file = fopen(log_filename, "a");
    if (!array->log_file) {
        perror("Log file opening failed");
        exit(EXIT_FAILURE);
    }
}

// Function to generate a random CRC flag
int generate_random_crc_flag() {
    return rand() % 2;
}

// Function to add an element to the dynamic array
void add_element(DynamicArray *array, int RX_UE_INFORMATION_TAG, unsigned long RNTI) {
    pthread_mutex_lock(&array->mutex);

    // Check for duplicates
    for (size_t i = 0; i < array->count; ++i) {
        if (array->data[i].RNTI == RNTI) {
            fprintf(array->log_file, "Duplicate RNTI: %lu\n", RNTI);
            pthread_mutex_unlock(&array->mutex);
            return;
        }
    }

    // Resize array if needed
    if (array->count >= MAX_ENTRIES) {
        fprintf(array->log_file, "Max entries reached\n");
        pthread_mutex_unlock(&array->mutex);
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(array->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (array->count + 1));
    if (!new_data) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&array->mutex);
        return;
    }
    array->data = new_data;

    // Add new element
    NFAPI_CRC_INDICATION_PDU_T new_entry = {RX_UE_INFORMATION_TAG, RNTI, generate_random_crc_flag()};
    array->data[array->count++] = new_entry;
    fprintf(array->log_file, "Added: RX_UE_INFORMATION_TAG=%d, RNTI=%lu\n", RX_UE_INFORMATION_TAG, RNTI);

    pthread_mutex_unlock(&array->mutex);
}

// Function to retrieve an element by index
NFAPI_CRC_INDICATION_PDU_T* get_element(DynamicArray *array, size_t index) {
    if (index >= array->count) return NULL;

    pthread_mutex_lock(&array->mutex);
    NFAPI_CRC_INDICATION_PDU_T *element = &array->data[index];
    fprintf(array->log_file, "Retrieved: RX_UE_INFORMATION_TAG=%d, RNTI=%lu\n", element->RX_UE_INFORMATION_TAG, element->RNTI);
    pthread_mutex_unlock(&array->mutex);

    return element;
}

// Function to clean up resources
void cleanup_dynamic_array(DynamicArray *array) {
    pthread_mutex_lock(&array->mutex);
    free(array->data);
    array->count = 0;

    if (fclose(array->log_file)) {
        perror("Log file closing failed");
    }

    pthread_mutex_unlock(&array->mutex);
    pthread_mutex_destroy(&array->mutex);
}

// Example usage
int main() {
    DynamicArray array;
    init_dynamic_array(&array, "dynamic_array.log");

    add_element(&array, 1, 1001);
    add_element(&array, 2, 1002);

    NFAPI_CRC_INDICATION_PDU_T *element = get_element(&array, 0);
    if (element) {
        printf("Element: RX_UE_INFORMATION_TAG=%d, RNTI=%lu\n", element->RX_UE_INFORMATION_TAG, element->RNTI);
    }

    cleanup_dynamic_array(&array);

    return 0;
}
```

