void adjust_quality_threshold(NFAPIManager *manager) {
    pthread_mutex_lock(&manager->lock);

    double adjustment_factor = (double)(manager->checksum_success_count - manager->checksum_failure_count) / 100;
    manager->quality_threshold += adjustment_factor;

    filter_structures(manager); // Apply filtering based on new threshold

    pthread_mutex_unlock(&manager->lock);
}

// Filter structures below quality threshold
void filter_structures(NFAPIManager *manager) {
    size_t write_index = 0;
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->array[i].quality_score >= manager->quality_threshold) {
            if (write_index != i) {
                manager->array[write_index] = manager->array[i];
            }
            write_index++;
        }
    }
    manager->count = write_index;
}

