        add_structure(&manager);
        adjust_quality_threshold(&manager); // Adjust threshold based on conditions
    }

    printf("Checksum successes: %d\n", manager.checksum_success_count);
    printf("Checksum failures: %d\n", manager.checksum_failure_count);

    free_manager(&manager);
    return 0;
}
