static unsigned int max_limit = DEFAULT_MAX_LIMIT;
static unsigned long allocated_count = 0;
static pthread_mutex_t allocation_lock;

void configure_max_limit(unsigned int limit) {
    if (limit > 0) {
        pthread_mutex_lock(&allocation_lock);
        max_limit = limit;
        pthread_mutex_unlock(&allocation_lock);
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_crc_pdus(size_t n) {
    if (n == 0 || n > max_limit) {
        fprintf(stderr, "Warning: Invalid allocation size.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        perror("Failed to allocate memory");
        return NULL;
    }

    srand(time(NULL)); // Seed for random number generation
    pthread_mutex_lock(&allocation_lock);
    allocated_count += n;

    for (size_t i = 0; i < n; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = rand();
        pdus[i].RNTI = rand() & 0xFFFF;
        pdus[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }

    if (allocated_count > max_limit) {
        fprintf(stderr, "Warning: Allocated count exceeds configured maximum limit.\n");
        free(pdus);
        pthread_mutex_unlock(&allocation_lock);
        return NULL;
    }

    pthread_mutex_unlock(&allocation_lock);

    // Validation
    for (size_t i = 0; i < n; ++i) {
        if (pdus[i].RX_UE_INFORMATION_TAG == 0 || pdus[i].RNTI == 0 ||
            (pdus[i].CRC_INDICATION_REL8_TAG != 0 && pdus[i].CRC_INDICATION_REL8_TAG != 1)) {
            fprintf(stderr, "Validation failed for allocated data.\n");
            free(pdus);
            return NULL;
        }
    }

    return pdus;
}

void free_crc_pdus(NFAPI_CRC_INDICATION_PDU_T* pdus, size_t n) {
    if (!pdus) return;

    pthread_mutex_lock(&allocation_lock);
    allocated_count -= n;
    pthread_mutex_unlock(&allocation_lock);

    free(pdus);
}

unsigned long get_allocated_count() {
    unsigned long count;
    pthread_mutex_lock(&allocation_lock);
    count = allocated_count;
    pthread_mutex_unlock(&allocation_lock);
    return count;
}

int main() {
    configure_max_limit(500); // Example configuration

    pthread_mutex_init(&allocation_lock, NULL);

    size_t num_pdus = 100; // Example number
    NFAPI_CRC_INDICATION_PDU_T* pdus = allocate_crc_pdus(num_pdus);
    if (pdus) {
        printf("Successfully allocated %zu structures.\n", num_pdus);
        free_crc_pdus(pdus, num_pdus);
    }

    printf("Total allocated count: %lu\n", get_allocated_count());

