    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int size;
    int max_size;
} DynamicList;

void initialize_list(DynamicList* list, int max_size) {
    list->head = NULL;
    list->size = 0;
    list->max_size = max_size;
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond, NULL);
}

int validate_structure(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Implement validation logic
    return (pdu != NULL && pdu->RX_UE_INFORMATION_TAG >= 0 &&
            pdu->RNTI > 0 && (pdu->CRC_INDICATION_REL8_TAG.CRCFLAG == 0 || pdu->CRC_INDICATION_REL8_TAG.CRCFLAG == 1));
}

void update_rnti_from_external_source(DynamicList* list) {
    // Simulate updating RNTI from an external data source
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        current->data.RNTI += 1; // Example update logic
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void add_pdu_to_list(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!validate_structure(pdu)) return;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return; // Handle memory allocation failure

    srand(time(NULL)); // Seed for random number generation
    new_node->data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);

    while (list->size >= list->max_size) {
        pthread_cond_wait(&list->cond, &list->lock);
    }

    new_node->data = *pdu;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    pthread_cond_signal(&list->cond); // Signal any waiting threads
}

void iterate_over_list(DynamicList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        callback(&(current->data));
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void free_list(DynamicList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* next_node = current->next;
        free(current);
        current = next_node;
    }

    list->head = NULL;
    list->size = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->cond);
}

// Example callback function
void print_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    printf("RX_UE_INFORMATION_TAG: %d, RNTI: %u, CRCFLAG: %d\n",
           pdu->RX_UE_INFORMATION_TAG,
           pdu->RNTI,
           pdu->CRC_INDICATION_REL8_TAG.CRCFLAG);
}

int main() {
    DynamicList list;
    initialize_list(&list, MAX_LIST_SIZE);

    NFAPI_CRC_INDICATION_PDU_T pdu = {1, 12345, {.CRCFLAG = 0}};
    add_pdu_to_list(&list, &pdu);

    iterate_over_list(&list, print_pdu);

    free_list(&list);
    return 0;
}
