    if (!manager) return NULL;

    manager->sessions = calloc(initialCapacity, sizeof(SessionRecord));
    if (!manager->sessions) {
        free(manager);
        return NULL;
    }

    manager->count = 0;
    manager->capacity = initialCapacity;
    return manager;
}

// Clean up resources
void cleanupSessionManager(NetworkSessionManager *manager) {
    if (manager) {
        free(manager->sessions);
        free(manager);
    }
}

// Add a new session record
int addSession(NetworkSessionManager *manager, int sessionID, const char* srcIP, const char* dstIP, ProtocolType protocol) {
    if (!isValidIPAddress(srcIP) || !isValidIPAddress(dstIP)) return -1;

    if (manager->count >= manager->capacity) {
        size_t newCapacity = manager->capacity * 2;
        SessionRecord *newSessions = realloc(manager->sessions, newCapacity * sizeof(SessionRecord));
        if (!newSessions) return -1;

        manager->sessions = newSessions;
        manager->capacity = newCapacity;
    }

    manager->sessions[manager->count].sessionID = sessionID;
    strncpy(manager->sessions[manager->count].srcIP, srcIP, sizeof(manager->sessions[0].srcIP));
    strncpy(manager->sessions[manager->count].dstIP, dstIP, sizeof(manager->sessions[0].dstIP));
    manager->sessions[manager->count].protocol = protocol;

    manager->count++;
    return 0;
}

// Update an existing session record
int updateSession(NetworkSessionManager *manager, int sessionID, const char* newSrcIP, const char* newDstIP, ProtocolType newProtocol) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i].sessionID == sessionID) {
            if (!isValidIPAddress(newSrcIP) || !isValidIPAddress(newDstIP)) return -1;

            strncpy(manager->sessions[i].srcIP, newSrcIP, sizeof(manager->sessions[0].srcIP));
            strncpy(manager->sessions[i].dstIP, newDstIP, sizeof(manager->sessions[0].dstIP));
            manager->sessions[i].protocol = newProtocol;
            return 0;
        }
    }
    return -1; // Session ID not found
}

int main() {
    NetworkSessionManager *manager = initSessionManager(10);

    if (!manager) {
        fprintf(stderr, "Failed to initialize session manager\n");
        return EXIT_FAILURE;
    }

    addSession(manager, 1, "192.168.0.1", "8.8.8.8", PROTOCOL_TCP);
    updateSession(manager, 1, "192.168.0.2", "8.8.4.4", PROTOCOL_UDP);

    // Perform other operations...

    cleanupSessionManager(manager);

    return EXIT_SUCCESS;
}
