            (*pdu_list)[i].RX_UE_INFORMATION_TAG = i + 1;
            (*pdu_list)[i].RNTI = i + 2;
            (*pdu_list)[i].CRC_INDICATION_REL8_TAG = (i % 2) ? 1 : 0; // Set CRCFLAG based on parity
        } else if (version == 2) {
            // Initialize Version2 structure accordingly
            ((*((Version2_NFAPI_CRC_INDICATION_PDU_T **)pdu_list))[i].base).RX_UE_INFORMATION_TAG = i + 1;
            ((*((Version2_NFAPI_CRC_INDICATION_PDU_T **)pdu_list))[i].base).RNTI = i + 2;
            ((*((Version2_NFAPI_CRC_INDICATION_PDU_T **)pdu_list))[i].base).CRC_INDICATION_REL8_TAG = (i % 2) ? 1 : 0;
        }

        if (!validate_structure(version == DEFAULT_VERSION ? &((*pdu_list)[i]) : &(((*((Version2_NFAPI_CRC_INDICATION_PDU_T **)pdu_list))[i]).base), i)) {
            log_error("Validation failed for structure at index");
            free(*pdu_list);
            *pdu_list = NULL;
            return FAILURE;
        }
    }

    return SUCCESS;
}

void cleanup_pdu_list(NFAPI_CRC_INDICATION_PDU_T **pdu_list) {
    if (pdu_list && *pdu_list) {
        free(*pdu_list);
        *pdu_list = NULL;
    }
}
```

