void createNfarxPduList(MYSQL *conn, NFAPI_CRC_INDICATION_PDU_T **pdu_list, int *count) {
    if (!conn || !pdu_list || !count) return;

    const char *query = "SELECT rnti FROM ue_info";
    MYSQL_BIND binds[1];
    memset(binds, 0, sizeof(MYSQL_BIND));

    // Prepare a statement for the query
    MYSQL_STMT *stmt = mysql_stmt_init(conn);
    if (!mysql_stmt_prepare(stmt, query, strlen(query))) {
        int num_rows = executeSqlQueryWithParams(conn, query, binds, 0);

        // Allocate memory for PDU structures based on retrieved RNTI count
        *pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_rows * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!*pdu_list) {
            fprintf(stderr, "Memory allocation failed\n");
            *count = 0;
            return;
        }

        MYSQL_RES *result = mysql_stmt_result_metadata(stmt);
        if (result) {
            MYSQL_ROW row;
            MYSQL_BIND bind[1];
            my_bool is_null[1] = {0};
            unsigned long length[1] = {0};

            memset(bind, 0, sizeof(bind));
            bind[0].buffer_type = MYSQL_TYPE_LONG;
            bind[0].is_null = &is_null[0];
            bind[0].length = &length[0];
            bind[0].buffer = (void *)&row;

            if (!mysql_stmt_bind_result(stmt, bind)) {
                while (mysql_stmt_fetch(stmt) == 0) {
                    (*pdu_list)[*count].ueInformationTag.RNTI = row[0];
                    srand(time(NULL));
                    (*pdu_list)[*count].crcIndicationRel8Tag.CRCFLAG = rand() % 2;
                    (*count)++;
                }
            }

            mysql_free_result(result);
        }

        // Close the statement
        mysql_stmt_close(stmt);
    } else {
        fprintf(stderr, "Failed to prepare SQL statement\n");
    }
}

// Implementation of the function to execute SQL query with parameters
int executeSqlQueryWithParams(MYSQL *conn, const char *query, MYSQL_BIND *binds, unsigned int num_params) {
    if (!conn || !query) return 0;

    // Prepare a statement for the query
    MYSQL_STMT *stmt = mysql_stmt_init(conn);
    if (!mysql_stmt_prepare(stmt, query, strlen(query))) {
        if (num_params > 0 && binds) {
            if (!mysql_stmt_bind_param(stmt, binds)) {
                if (mysql_stmt_execute(stmt)) {
                    fprintf(stderr, "MySQL statement execution error: %s\n", mysql_stmt_error(stmt));
                }
            } else {
                fprintf(stderr, "Failed to bind parameters: %s\n", mysql_stmt_error(stmt));
            }
        }

        if (!mysql_stmt_store_result(stmt)) {
            int num_rows = (int)mysql_stmt_num_rows(stmt);
            return num_rows;
        } else {
            fprintf(stderr, "Failed to store result set: %s\n", mysql_stmt_error(stmt));
        }

        // Close the statement
        mysql_stmt_close(stmt);
    } else {
        fprintf(stderr, "Failed to prepare SQL statement: %s\n", mysql_stmt_error(conn));
    }

    return 0;
}
