['```c
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    uint16_t RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* entries;
    size_t count;
    size_t capacity;
    pthread_rwlock_t lock; // Read-write lock for concurrency control
} CRCDynamicArray;

// Function prototypes
CRCDynamicArray* create_crc_array(size_t initial_capacity);
int add_entry(CRCDynamicArray* array, uint16_t RNTI, int CRCFLAG);
int remove_entry_by_rnti(CRCDynamicArray* array, uint16_t RNTI);
int update_crcflag_by_rnti(CRCDynamicArray* array, uint16_t RNTI, int new_CRCFLAG);
void destroy_crc_array(CRCDynamicArray* array);

// Implementation
CRCDynamicArray* create_crc_array(size_t initial_capacity) {
    CRCDynamicArray* array = (CRCDynamicArray*)malloc(sizeof(CRCDynamicArray));
    if (!array) return NULL;

    array->entries = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->entries) {
        free(array);
        return NULL;
    }

    array->count = 0;
    array->capacity = initial_capacity;
    pthread_rwlock_init(&array->lock, NULL);

    return array;
}

int add_entry(CRCDynamicArray* array, uint16_t RNTI, int CRCFLAG) {
    pthread_rwlock_wrlock(&array->lock);

    // Check for duplicate RNTI
    for (size_t i = 0; i < array->count; ++i) {
        if (array->entries[i].RNTI == RNTI) {
            pthread_rwlock_unlock(&array->lock);
            return -1; // Duplicate entry
        }
    }

    // Resize if necessary
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_entries = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->entries, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_entries) {
            pthread_rwlock_unlock(&array->lock);
            return -2; // Memory allocation failure
        }
        array->entries = new_entries;
        array->capacity = new_capacity;
    }

    // Add entry
    array->entries[array->count].RNTI = RNTI;
    array->entries[array->count].CRCFLAG = CRCFLAG;
    ++array->count;

    pthread_rwlock_unlock(&array->lock);
    return 0; // Success
}

int remove_entry_by_rnti(CRCDynamicArray* array, uint16_t RNTI) {
    pthread_rwlock_wrlock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->entries[i].RNTI == RNTI) {
            memmove(&array->entries[i], &array->entries[i + 1], (array->count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            --array->count;
            pthread_rwlock_unlock(&array->lock);
            return 0; // Success
        }
    }

    pthread_rwlock_unlock(&array->lock);
    return -1; // Entry not found
}

int update_crcflag_by_rnti(CRCDynamicArray* array, uint16_t RNTI, int new_CRCFLAG) {
    pthread_rwlock_wrlock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->entries[i].RNTI == RNTI) {
            array->entries[i].CRCFLAG = new_CRCFLAG;
            pthread_rwlock_unlock(&array->lock);
            return 0; // Success
        }
    }

    pthread_rwlock_unlock(&array->lock);
    return -1; // Entry not found
}

void destroy_crc_array(CRCDynamicArray* array) {
    if (!array) return;

    pthread_rwlock_wrlock(&array->lock);

    free(array->entries);
    pthread_rwlock_destroy(&array->lock);

    free(array);
}
```

### Explanation

- **Concurrency Control**: Uses a read-write lock (`pthread_rwlock_t`) to allow multiple concurrent reads while ensuring exclusive access for writes, reducing contention.
- **Memory Management**: Efficiently resizes the array by doubling its capacity when needed. Handles allocation failures gracefully.
- **Error Handling**: Returns error codes for duplicate entries, memory allocation failures, and non-existent RNTI removal attempts.
- **Thread Safety**: All operations that modify or read from the array are protected with appropriate locking to prevent race conditions.
- **Scalability**: Designed to handle increasing loads by allowing dynamic resizing of the underlying storage.']

