} MessageList;

MessageList list = {NULL, PTHREAD_MUTEX_INITIALIZER, 0};

void log_operation(const char* operation, int message_id) {
    // Example logging function
    printf("Operation: %s, TEST_MESSAGE_ID: %d\n", operation, message_id);
}

Node* create_node(LTE_PHY_TEST_MESSAGE_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    node->data = data;
    node->next = NULL;
    return node;
}

void add_message(int id, int channel, int result) {
    LTE_PHY_TEST_MESSAGE_T new_data = {id, channel, result};

    pthread_mutex_lock(&list.lock);
    Node* new_node = create_node(new_data);

    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&list.lock);
        return;
    }

    new_node->next = list.head;
    list.head = new_node;
    log_operation("ADD", id);
    list.count++;

    pthread_mutex_unlock(&list.lock);
}

void remove_message(int id) {
    pthread_mutex_lock(&list.lock);

    Node *current = list.head, *prev = NULL;

    while (current != NULL && current->data.TEST_MESSAGE_ID != id) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        log_operation("REMOVE_FAILED", id);
    } else {
        if (prev == NULL) { // Removing head
            list.head = current->next;
        } else {
            prev->next = current->next;
        }
        free(current);
        log_operation("REMOVE", id);
        list.count--;
    }

    pthread_mutex_unlock(&list.lock);
}

void update_message_result(int id, int new_result) {
    pthread_mutex_lock(&list.lock);

    Node* current = list.head;

    while (current != NULL && current->data.TEST_MESSAGE_ID != id) {
        current = current->next;
    }

    if (current == NULL) {
        log_operation("UPDATE_FAILED", id);
    } else {
        current->data.TEST_RESULT = new_result;
        log_operation("UPDATE", id);
    }

    pthread_mutex_unlock(&list.lock);
}

void free_list() {
    pthread_mutex_lock(&list.lock);

    Node* current = list.head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    list.head = NULL;
    list.count = 0;

    pthread_mutex_unlock(&list.lock);
}

int main() {
    // Example usage
    add_message(1, 10, 100);
    add_message(2, 20, 200);

    update_message_result(1, 150);

    remove_message(1);

    free_list();

    return 0;
}
```

### Key Features:
- **Thread Safety**: The operations on the list are protected by a mutex to ensure thread safety.
- **Memory Management**: Efficiently handles memory allocation and deallocation to avoid fragmentation.
- **Logging**: Simple logging function logs each operation, aiding in monitoring performance.
- **Scalability**: Designed to handle high concurrency with minimal latency.

### Optimization Considerations:
- Ensure that the list is kept as short as possible for quick access.
- The mutex granularity can be adjusted if more fine-grained control over concurrency is required.']

