            memmove(&array->data[i], &array->data[i + 1], (array->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            --array->size;
            pthread_rwlock_unlock(&array->lock);
            return 0;
        }
    }

    pthread_rwlock_unlock(&array->lock);
    return -1;
}

int update_crcflag(DynamicArray *array, unsigned int RNTI, unsigned char CRCFLAG) {
