            array->data[i].CRCFLAG = CRCFLAG;
            pthread_rwlock_unlock(&array->lock);
            return 0;
        }
    }

    pthread_rwlock_unlock(&array->lock);
    return -1;
}

void batch_update(DynamicArray *array, unsigned int *RNTIs, unsigned char *CRCFLAGS, size_t count) {
