    for (size_t i = 0; i < count; ++i) {
        update_crcflag(array, RNTIs[i], CRCFLAGS[i]);
    }

    pthread_rwlock_unlock(&array->lock);
}

void batch_lookup(DynamicArray *array, unsigned int *RNTIs, unsigned char *CRCFLAGS, size_t count) {
    pthread_rwlock_rdlock(&array->lock);

    for (size_t i = 0; i < count; ++i) {
        for (size_t j = 0; j < array->size; ++j) {
            if (array->data[j].RNTI == RNTIs[i]) {
                CRCFLAGS[i] = array->data[j].CRCFLAG;
                break;
            }
        }
    }

    pthread_rwlock_unlock(&array->lock);
}

void free_dynamic_array(DynamicArray *array) {
    if (!array) return;

    pthread_rwlock_destroy(&array->lock);
    free(array->data);
    free(array);
}
