    dyn_array->num_entries = 0;
    dyn_array->capacity = 0;
}

// Add entry to the dynamic array with validation for unique RX_UE_INFORMATION_TAG
int add_entry(DynamicArray *dyn_array, NFAPI_CRC_INDICATION_PDU_T entry) {
    if (dyn_array->num_entries >= dyn_array->capacity) {
        size_t new_capacity = dyn_array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(dyn_array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            return 0; // Memory allocation failed
        }
        dyn_array->array = new_array;
        dyn_array->capacity = new_capacity;
    }

    for (size_t i = 0; i < dyn_array->num_entries; ++i) {
        if (dyn_array->array[i].RX_UE_INFORMATION_TAG == entry.RX_UE_INFORMATION_TAG) {
            // Duplicate found, try to insert at the next available position
            for (size_t j = dyn_array->num_entries; j < dyn_array->capacity && i != j; ++j) {
                if (dyn_array->array[j].RX_UE_INFORMATION_TAG == 0) { // Empty slot
                    dyn_array->array[j] = entry;
                    dyn_array->num_entries++;
                    return 1;
                }
            }
        }
    }

    dyn_array->array[dyn_array->num_entries++] = entry;
    return 1;
}

