#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

// Definitions based on assumed structure layout
typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    int CRCFLAG;  // 0 or 1
} NFAPI_CRC_INDICATION_PDU_T;

#define BATCH_SIZE 1000

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file;

// Function declarations
void generate_unique_rnti(uint16_t *rnti_set, uint16_t count);
uint8_t set_random_crcflag();
void log_entry(const char *message);

// Main function to create and populate the list of structures
NFAPI_CRC_INDICATION_PDU_T* create_nfa_api_list(size_t N) {
    if (N == 0) return NULL;

    // Memory allocation for batch processing
    size_t num_batches = (N + BATCH_SIZE - 1) / BATCH_SIZE;
    NFAPI_CRC_INDICATION_PDU_T *list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        perror("Memory allocation failed");
        return NULL;
    }

    // Initialize logging
    log_file = fopen("generation_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        free(list);
        return NULL;
    }

    for (size_t batch_index = 0; batch_index < num_batches; ++batch_index) {
        size_t start_idx = batch_index * BATCH_SIZE;
        size_t end_idx = start_idx + BATCH_SIZE;
        if (end_idx > N) end_idx = N;

        // Allocate memory for current batch
        size_t batch_size = end_idx - start_idx;

        // Generate unique RNTI set for the entire list so far
        uint16_t *rnti_set = malloc((uint64_t)(batch_index * BATCH_SIZE + batch_size) * sizeof(uint16_t));
        if (!rnti_set) {
            perror("Memory allocation failed");
            free(list);
            fclose(log_file);
            return NULL;
        }

        // Populate the current batch
        for (size_t i = 0; i < batch_size; ++i) {
            NFAPI_CRC_INDICATION_PDU_T *pdu = &list[start_idx + i];

            pthread_mutex_lock(&lock);
            generate_unique_rnti(rnti_set, uint64_t(batch_index * BATCH_SIZE + i));
            pthread_mutex_unlock(&lock);

            pdu->RX_UE_INFORMATION_TAG = rand(); // Assuming random generation
            pdu->RNTI = rnti_set[uint64_t(batch_index * BATCH_SIZE + i)];
            pdu->CRC_INDICATION_REL8_TAG = rand() % 256;
            pdu->CRCFLAG = set_random_crcflag();

            log_entry("Generated PDU with unique RNTI");
        }

        free(rnti_set);
    }

    fclose(log_file);
    return list;
}

// Function to generate a unique RNTI
void generate_unique_rnti(uint16_t *rnti_set, uint16_t count) {
    uint16_t new_rnti;
    int retry_count = 0;

    do {
        pthread_mutex_lock(&lock);
        new_rnti = rand() % (1 << 14); // Example range for RNTI
        int is_unique = 1;

        for (int i = 0; i < count; ++i) {
            if (rnti_set[i] == new_rnti) {
                is_unique = 0;
                break;
            }
        }

        pthread_mutex_unlock(&lock);

        if (!is_unique) {
            retry_count++;
            log_entry("Duplicate RNTI detected, regenerating...");
        }
    } while (!is_unique && retry_count < 100); // Arbitrary retry limit

    rnti_set[count] = new_rnti;
}

// Function to randomly set CRCFLAG
uint8_t set_random_crcflag() {
    return rand() % 2;  // Randomly returns 0 or 1
}

// Logging function for recording events
void log_entry(const char *message) {
    pthread_mutex_lock(&lock);
    fprintf(log_file, "%s: %ld\n", message, time(NULL));
    fflush(log_file); // Ensure immediate write to file
    pthread_mutex_unlock(&lock);
}
```

### Key Considerations

1. **Thread Safety**: The use of `pthread_mutex_t` ensures that critical sections are protected from concurrent access by multiple threads. This prevents race conditions when accessing shared resources such as the RNTI set and logging mechanism.

2. **Efficient Memory Management**:
   - Batch allocation reduces memory fragmentation and overhead.
   - Pool-based management could further optimize performance by reusing previously allocated memory blocks, though it's not implemented here for simplicity.

3. **Logging**: Logs are written with minimal delay using `fflush`, and access to the log file is protected by a mutex to prevent data corruption during concurrent writes.

4. **Scalability**:
   - The function can be extended to handle larger values of `N` by adjusting `BATCH_SIZE`.
   - For future scalability, consider dynamic adjustment of batch sizes based on system load or available memory resources.

5. **Performance Trade-offs**:
   - Fine-grained locking ensures minimal contention but may introduce overhead in high-load scenarios.
   - Memory allocation strategy (batch vs. pool) balances between ease of implementation and potential performance gains.

6. **Recommendations for Future Enhancements**:
   - Implement a more sophisticated RNTI generation mechanism to minimize retries.
   - Explore non-blocking data structures or lock-free algorithms to improve concurrency under high loads.']

