NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_array(size_t N) {
    if (N > MAX_USERS) {
        fprintf(stderr, "Exceeded maximum number of users.\n");
        return NULL;
    }

    // Allocate memory for the array
    NFAPI_CRC_INDICATION_PDU_T *array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        perror("Memory allocation failed");
        return NULL;
    }

    unsigned long rnti_set[MAX_USERS] = {0};
    int unique_count = 0;

    while (unique_count < N) {
        pthread_mutex_lock(&mutex);

        unsigned long userId = unique_count + 1; // Simulate user ID
        unsigned long rxTag = fetch_user_information(userId);
        unsigned long rnti = rand() % MAX_USERS;

        // Ensure no duplicate RNTI
        bool is_unique_rnti = true;
        for (int i = 0; i < unique_count; ++i) {
            if (array[i].RNTI == rnti) {
                is_unique_rnti = false;
                break;
            }
        }

        if (!is_unique_rnti) {
            pthread_mutex_unlock(&mutex);
            continue;
        }

        // Populate structure
        CRC_INDICATION_REL8_TAG crcTag;
        bool valid_crc = false;

        do {
            crcTag.CRCFLAG = rand() % 256; // Random CRCFLAG
            valid_crc = verify_crc_integrity(&crcTag);
        } while (!valid_crc);

        array[unique_count].RX_UE_INFORMATION_TAG = rxTag;
        array[unique_count].RNTI = rnti;
        array[unique_count].crcTag = crcTag;

        // Mark RNTI as used
        rnti_set[rnti] = 1;
        unique_count++;

        pthread_mutex_unlock(&mutex);
    }

    return array;
}

void free_allocated_array(NFAPI_CRC_INDICATION_PDU_T *array) {
    if (array) {
        free(array);
    }
}
