    if (list->count >= list->size * MAX_LOAD_FACTOR) {
        resize_list(list);
    }

    // Insert the PDU into the list
    memcpy(&list->data[list->count], &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->count++;

    pthread_mutex_unlock(&list->lock);
