    pthread_mutex_t lock;
} NICB_Array;

bool is_valid_mac_address(const char *mac) {
    return strlen(mac) == 17 && sscanf(mac, "%hhx:%hhx:%hhx:%hhx:%hhx:%hhx",
                                        &mac[0], &mac[3], &mac[6], 
                                        &mac[9], &mac[12], &mac[15]) == 6;
}

bool mac_address_exists(NICB_Array *array, const char *mac) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->count; ++i) {
        if (strcmp(array->nicbs[i].MAC_ADDRESS, mac) == 0) {
            pthread_mutex_unlock(&array->lock);
            return true;
        }
    }
    pthread_mutex_unlock(&array->lock);
    return false;
}

bool initialize_nicb(NICB *nicb, const char *mac, const char *ip, int port,
                     NFAPI_CRC_INDICATION_PDU_T *pdu_list, size_t pdu_count) {
    if (!is_valid_mac_address(mac)) return false;

    strncpy(nicb->MAC_ADDRESS, mac, sizeof(nicb->MAC_ADDRESS));
    strcpy(nicb->IP_ADDRESS, ip);
    nicb->PORT_NUMBER = port;
    nicb->pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(pdu_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nicb->pdu_list) return false;

    memcpy(nicb->pdu_list, pdu_list, pdu_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    nicb->pdu_count = pdu_count;
    nicb->CRCFLAG = rand() % 2; // Randomly set CRC flag

    return true;
}

void free_nicb(NICB *nicb) {
    if (nicb && nicb->pdu_list) {
        free(nicb->pdu_list);
    }
}

bool add_nicb(NICB_Array *array, const char *mac, const char *ip, int port,
              NFAPI_CRC_INDICATION_PDU_T *pdu_list, size_t pdu_count) {
    if (array->count >= MAX_NICBS || mac_address_exists(array, mac)) return false;

    NICB *new_nicb = &array->nicbs[array->count];
    bool success = initialize_nicb(new_nicb, mac, ip, port, pdu_list, pdu_count);
    if (success) {
        pthread_mutex_lock(&array->lock);
        array->count++;
        pthread_mutex_unlock(&array->lock);
    }
    return success;
}

void free_nicb_array(NICB_Array *array) {
    for (size_t i = 0; i < array->count; ++i) {
        free_nicb(&array->nicbs[i]);
    }
    if (array->nicbs) {
        free(array->nicbs);
    }
}

int main() {
    NICB_Array nicb_array;
    memset(&nicb_array, 0, sizeof(NICB_Array));
    pthread_mutex_init(&nicb_array.lock, NULL);

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T pdu_list[5] = {/* Initialize with data */};
    add_nicb(&nicb_array, "AA:BB:CC:DD:EE:FF", "192.168.1.1", 8080, pdu_list, 5);

    // Free resources
    free_nicb_array(&nicb_array);
    pthread_mutex_destroy(&nicb_array.lock);

    return 0;
}
```

### Key Features:
- **Uniqueness Check**: Ensures MAC addresses are unique using `mac_address_exists`.
- **Thread Safety**: Uses mutex locks to protect shared data.
- **Error Handling**: Checks for allocation failures and validates input.
- **Performance Optimization**: Limits NICB count and uses dynamic memory efficiently.
- **Scalability**: Designed to handle up to 10,000 NICBs with minimal latency.
- **Modular Design**: Facilitates future expansions and integration.

This implementation is designed to be integrated into a larger system with logging and monitoring tools. Adjustments may be needed based on specific requirements or constraints of the environment in which it will be deployed.']

