#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_NICBS 10000
#define MAC_ADDRESS_LENGTH 6
#define IP_ADDRESS_LENGTH 16 // Assuming IPv6
#define PORT_NUMBER_MAX 65535

typedef struct {
    uint8_t RX_UE_INFORMATION_TAG[10];
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[5];
    int CRCFLAG; // Randomly set to 0 or 1 for demonstration purposes.
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    uint8_t MAC_ADDRESS[MAC_ADDRESS_LENGTH];
    char IP_ADDRESS[IP_ADDRESS_LENGTH];
    uint16_t PORT_NUMBER;
    size_t pdu_count;
    NFAPI_CRC_INDICATION_PDU_T *pdu_list;
} NICB;

// Global lock for thread-safe operations
pthread_mutex_t nicb_lock = PTHREAD_MUTEX_INITIALIZER;

int compare_mac_addresses(const void *a, const void *b) {
    return memcmp(a, b, MAC_ADDRESS_LENGTH);
}

int initialize_nicbs(NICB **nicbs, size_t num_nicbs) {
    if (num_nicbs > MAX_NICBS || !nicbs) {
        return -1; // Invalid number of NICBs or null pointer
    }

    *nicbs = malloc(num_nicbs * sizeof(NICB));
    if (!*nicbs) {
        return -2; // Memory allocation failure
    }

    pthread_mutex_lock(&nicb_lock);

    for (size_t i = 0; i < num_nicbs; ++i) {
        (*nicbs)[i].pdu_count = 0;
        (*nicbs)[i].pdu_list = NULL;

        // Generate unique MAC_ADDRESS
        do {
            for (int j = 0; j < MAC_ADDRESS_LENGTH; ++j) {
                (*nicbs)[i].MAC_ADDRESS[j] = rand() % 256;
            }
        } while (!is_unique_mac_address(*nicbs, i));

        // Generate IP_ADDRESS and PORT_NUMBER
        snprintf((*nicbs)[i].IP_ADDRESS, IP_ADDRESS_LENGTH, "192.168.1.%zu", (rand() % 255) + 1);
        (*nicbs)[i].PORT_NUMBER = rand() % PORT_NUMBER_MAX + 1;
    }

    pthread_mutex_unlock(&nicb_lock);

    return 0; // Success
}

int is_unique_mac_address(NICB *nicbs, size_t current_index) {
    for (size_t i = 0; i < current_index; ++i) {
        if (compare_mac_addresses(nicbs[i].MAC_ADDRESS, nicbs[current_index].MAC_ADDRESS) == 0) {
            return 0; // Duplicate MAC address found
        }
    }
    return 1; // Unique MAC address
}

void free_nicbs(NICB *nicbs, size_t num_nicbs) {
    if (!nicbs) {
        return;
    }

    pthread_mutex_lock(&nicb_lock);

    for (size_t i = 0; i < num_nicbs; ++i) {
        free(nicbs[i].pdu_list);
    }

    free(nicbs);

    pthread_mutex_unlock(&nicb_lock);
}

void update_crc_indication(NICB *nicbs, size_t num_nicbs, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!nicbs) {
        return;
    }

    pthread_mutex_lock(&nicb_lock);

    for (size_t i = 0; i < num_nicbs; ++i) {
        // Example logic: Add PDU to the first NICB's list
        nicbs[i].pdu_count++;
        nicbs[i].pdu_list = realloc(nicbs[i].pdu_list, nicbs[i].pdu_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!nicbs[i].pdu_list) {
            // Handle allocation failure
            pthread_mutex_unlock(&nicb_lock);
            return;
        }

        nicbs[i].pdu_list[nicbs[i].pdu_count - 1] = pdu; // Assign new PDU
    }

    pthread_mutex_unlock(&nicb_lock);
}

// Main function for testing purposes
int main() {
    NICB *nicbs = NULL;
    size_t num_nicbs = 1000;

    if (initialize_nicbs(&nicbs, num_nicbs) != 0) {
        fprintf(stderr, "Failed to initialize NICBs\n");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu = {
        .RX_UE_INFORMATION_TAG = {0x01, 0x02, 0x03},
        .RNTI = 12345,
        .CRC_INDICATION_REL8_TAG = {0xA1, 0xB2, 0xC3},
        .CRCFLAG = rand() % 2
    };

    update_crc_indication(nicbs, num_nicbs, pdu);

    free_nicbs(nicbs, num_nicbs);

    return 0;
}
