#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Third-party libraries for networking and logging
#include "third_party_network_lib.h"
#include "third_party_logging_lib.h"

#define MAX_NICB_COUNT 10000

typedef struct {
    unsigned char mac_address[6];
    unsigned int ip_address;
    unsigned short port_number;

    // List of NFAPI_CRC_INDICATION_PDU_T structures
    struct {
        unsigned int rx_ue_information_tag;
        unsigned int rnti;
        unsigned char crc_indication_rel8_tag;
        unsigned char crcflag;
    } *pdu_list;

    size_t pdu_count;
} NICB_T;

typedef struct {
    NICB_T nicbs[MAX_NICB_COUNT];
    pthread_mutex_t lock;
    size_t count;
} NICB_Manager;

// Function prototypes
int initialize_nicb_manager(NICB_Manager *manager);
int add_nicb_entry(NICB_Manager *manager, const unsigned char mac_address[6], 
                   unsigned int ip_address, unsigned short port_number,
                   struct {
                       unsigned int rx_ue_information_tag;
                       unsigned int rnti;
                       unsigned char crc_indication_rel8_tag;
                       unsigned char crcflag;
                   } pdu_list[], size_t pdu_count);
int is_mac_address_unique(NICB_Manager *manager, const unsigned char mac_address[6]);
void free_nicb_manager_resources(NICB_Manager *manager);

// Initialize the NICB manager
int initialize_nicb_manager(NICB_Manager *manager) {
    if (!manager) return -1;

    pthread_mutex_init(&manager->lock, NULL);
    manager->count = 0;

    // Initialize logging and network communication with third-party libraries
    third_party_logging_lib_init();
    third_party_network_lib_init();

    return 0;
}

// Add a NICB entry ensuring MAC address uniqueness
int add_nicb_entry(NICB_Manager *manager, const unsigned char mac_address[6], 
                   unsigned int ip_address, unsigned short port_number,
                   struct {
                       unsigned int rx_ue_information_tag;
                       unsigned int rnti;
                       unsigned char crc_indication_rel8_tag;
                       unsigned char crcflag;
                   } pdu_list[], size_t pdu_count) {

    if (!manager || !pdu_list || pdu_count == 0)
        return -1;

    pthread_mutex_lock(&manager->lock);

    if (is_mac_address_unique(manager, mac_address)) {
        // Allocate memory for the NICB and its PDUs
        NICB_T *new_nicb = &manager->nicbs[manager->count];
        new_nicb->pdu_list = malloc(pdu_count * sizeof(struct {
            unsigned int rx_ue_information_tag;
            unsigned int rnti;
            unsigned char crc_indication_rel8_tag;
            unsigned char crcflag;
        }));

        if (!new_nicb->pdu_list) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failure
        }

        new_nicb->pdu_count = pdu_count;

        memcpy(new_nicb->mac_address, mac_address, 6);
        new_nicb->ip_address = ip_address;
        new_nicb->port_number = port_number;

        for (size_t i = 0; i < pdu_count; ++i) {
            new_nicb->pdu_list[i] = pdu_list[i];

            // Randomly set CRCFLAG
            new_nicb->pdu_list[i].crcflag = rand() % 2;
        }

        manager->count++;

        pthread_mutex_unlock(&manager->lock);

        // Log successful addition
        third_party_logging_lib_log("NICB entry added successfully.");
    } else {
        pthread_mutex_unlock(&manager->lock);

        // Log duplicate MAC address attempt
        third_party_logging_lib_log("Duplicate MAC address detected. NICB entry not added.");
        return -2; // Duplicate MAC address error code
    }

    return 0;
}

// Check for unique MAC addresses in the manager's NICBs
int is_mac_address_unique(NICB_Manager *manager, const unsigned char mac_address[6]) {
    if (!manager) return 0;

    for (size_t i = 0; i < manager->count; ++i) {
        if (memcmp(manager->nicbs[i].mac_address, mac_address, 6) == 0)
            return 0;
    }

    return 1;
}

// Free resources used by the NICB Manager
void free_nicb_manager_resources(NICB_Manager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->nicbs[i].pdu_list);
    }

    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);

    // Cleanup third-party library resources
    third_party_logging_lib_cleanup();
    third_party_network_lib_cleanup();
}

int main() {
    srand(time(NULL));  // Seed random number generator

    NICB_Manager manager;
    if (initialize_nicb_manager(&manager) != 0) {
        fprintf(stderr, "Failed to initialize NICB Manager\n");
        return -1;
    }

    unsigned char mac_address[6] = {0x00, 0x14, 0x22, 0x01, 0x23, 0x45};
    unsigned int ip_address = 192168011; // Example IP address
    unsigned short port_number = 8080;

    struct {
        unsigned int rx_ue_information_tag;
        unsigned int rnti;
        unsigned char crc_indication_rel8_tag;
        unsigned char crcflag;
    } pdu_list[5] = { 
        {1, 2, 3, 0},
        {4, 5, 6, 0},
        {7, 8, 9, 0},
        {10, 11, 12, 0},
        {13, 14, 15, 0}
    };

    if (add_nicb_entry(&manager, mac_address, ip_address, port_number, pdu_list, 5) != 0) {
        fprintf(stderr, "Failed to add NICB entry\n");
    }

    // Free allocated resources
    free_nicb_manager_resources(&manager);

    return 0;
}
