#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define constants
#define MAX_IPS 10

typedef struct {
    char ip[16]; // Assuming IPv4 addresses
} IPAddress;

typedef struct {
    char identifier[32];
    IPAddress ips[MAX_IPS];
    int num_ips;
    int config_status; // 0 for inactive, 1 for active
} NetworkInterfaceConfig;

// Error codes
#define SUCCESS 0
#define ERROR_MEMORY -1
#define ERROR_NOT_FOUND -2

typedef struct Node {
    NetworkInterfaceConfig data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    int update_count;
    int failed_operations;
} InterfaceList;

// Function prototypes
InterfaceList* create_interface_list();
void destroy_interface_list(InterfaceList* list);
int add_interface(InterfaceList* list, NetworkInterfaceConfig config);
int remove_interface(InterfaceList* list, const char* identifier);
NetworkInterfaceConfig* get_interface(const InterfaceList* list, const char* identifier);
int update_interface(InterfaceList* list, const char* identifier, NetworkInterfaceConfig new_config);
void log_metrics(const InterfaceList* list);

// Function implementations
InterfaceList* create_interface_list() {
    InterfaceList* list = (InterfaceList*)malloc(sizeof(InterfaceList));
    if (!list) return NULL;
    list->head = NULL;
    list->update_count = 0;
    list->failed_operations = 0;
    return list;
}

void destroy_interface_list(InterfaceList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

int add_interface(InterfaceList* list, NetworkInterfaceConfig config) {
    if (!list) return ERROR_MEMORY;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return ERROR_MEMORY;

    memcpy(&new_node->data, &config, sizeof(NetworkInterfaceConfig));
    new_node->next = list->head;
    list->head = new_node;

    log_metrics(list);
    return SUCCESS;
}

int remove_interface(InterfaceList* list, const char* identifier) {
    if (!list || !identifier) return ERROR_NOT_FOUND;

    Node **current = &list->head;
    while (*current) {
        Node* entry = *current;
        if (strcmp(entry->data.identifier, identifier) == 0) {
            *current = entry->next;
            free(entry);
            log_metrics(list);
            return SUCCESS;
        }
        current = &entry->next;
    }

    list->failed_operations++;
    return ERROR_NOT_FOUND;
}

NetworkInterfaceConfig* get_interface(const InterfaceList* list, const char* identifier) {
    if (!list || !identifier) return NULL;

    Node* current = list->head;
    while (current) {
        if (strcmp(current->data.identifier, identifier) == 0) {
            return &current->data;
        }
        current = current->next;
    }

    return NULL;
}

int update_interface(InterfaceList* list, const char* identifier, NetworkInterfaceConfig new_config) {
    if (!list || !identifier) return ERROR_NOT_FOUND;

    Node** current = &(list->head);
    while (*current) {
        Node* entry = *current;
        if (strcmp(entry->data.identifier, identifier) == 0) {
            memcpy(&entry->data, &new_config, sizeof(NetworkInterfaceConfig));
            list->update_count++;
            log_metrics(list);
            return SUCCESS;
        }
        current = &(entry->next);
    }

    list->failed_operations++;
    return ERROR_NOT_FOUND;
}

void log_metrics(const InterfaceList* list) {
    printf("Updates: %d\n", list->update_count);
    printf("Failed Operations: %d\n", list->failed_operations);
}
```

