int manage_pdu_list(NFAPI_CRC_INDICATION_PDU_T** pdu_list, int* count, 
                    const NFAPI_CRC_INDICATION_PDU_T* incoming_pdu, 
                    int source_id) {
    if (!pdu_list || !incoming_pdu) return -1;

    // Attempt to find an existing PDU with the same tags
    for (int i = 0; i < *count; ++i) {
        if ((*pdu_list)[i].RX_UE_INFORMATION_TAG == incoming_pdu->RX_UE_INFORMATION_TAG &&
