        printf("Max PDU count reached. Cannot add more.\n");
        return -1;
    }

    // Allocate or reallocate memory for a new PDU entry
    NFAPI_CRC_INDICATION_PDU_T* temp_list = realloc(*pdu_list, (*count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp_list) {
