#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

#define MAX_RECORDS 1000

typedef struct {
    int transaction_id;
    char client_ip[16];
    char server_ip[16];
    double request_time; // Unix timestamp
    double response_time; // Unix timestamp
} NFIX_Transaction_Record;

typedef struct {
    NFIX_Transaction_Record *records;
    atomic_size_t size;
    pthread_mutex_t lock;  // Traditional mutex-based approach
} TransactionList;

// Function declarations
TransactionList* create_transaction_list();
void free_transaction_list(TransactionList* list);
int add_transaction_record(TransactionList* list, int transaction_id, const char* client_ip, 
                           const char* server_ip, double request_time, double response_time);

TransactionList* create_transaction_list() {
    TransactionList *list = (TransactionList *)malloc(sizeof(TransactionList));
    if (!list) return NULL;

    list->records = (NFIX_Transaction_Record*)calloc(MAX_RECORDS, sizeof(NFIX_Transaction_Record));
    if (!list->records) {
        free(list);
        return NULL;
    }

    atomic_init(&list->size, 0);
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void free_transaction_list(TransactionList* list) {
    if (list) {
        if (list->records) {
            free(list->records);
        }
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

int add_transaction_record(TransactionList* list, int transaction_id, const char* client_ip,
                           const char* server_ip, double request_time, double response_time) {
    if (!list || !client_ip || !server_ip) return -1;

    pthread_mutex_lock(&list->lock);

    size_t current_size = atomic_load(&list->size);
    if (current_size >= MAX_RECORDS) {
        fprintf(stderr, "Transaction list is full. Cannot add new record.\n");
        pthread_mutex_unlock(&list->lock);
        return -2;
    }

    NFIX_Transaction_Record *record = &list->records[current_size];
    record->transaction_id = transaction_id;
    snprintf(record->client_ip, sizeof(record->client_ip), "%s", client_ip);
    snprintf(record->server_ip, sizeof(record->server_ip), "%s", server_ip);
    record->request_time = request_time;
    record->response_time = response_time;

    if (atomic_fetch_add(&list->size, 1) >= MAX_RECORDS) {
        // If the size exceeds the limit after incrementing, revert
        atomic_fetch_sub(&list->size, 1);
        fprintf(stderr, "Atomic operation failed. Size exceeded after addition.\n");
        pthread_mutex_unlock(&list->lock);
        return -3;
    }

    printf("Transaction record added successfully: %d\n", transaction_id);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Example usage
int main() {
    TransactionList *transaction_list = create_transaction_list();
    if (!transaction_list) {
        fprintf(stderr, "Failed to initialize transaction list.\n");
        return EXIT_FAILURE;
    }

    add_transaction_record(transaction_list, 1, "192.168.1.1", "10.0.0.1", 1625158800.0, 1625158805.0);

    free_transaction_list(transaction_list);
    return EXIT_SUCCESS;
}
```

### Design Choices and Rationale:

- **Mutex-based Approach**: For simplicity and reliability in managing concurrent updates, a traditional mutex (`pthread_mutex_t`) is used. This ensures data consistency even under high contention, as the lock protects the critical section of adding records.

- **Atomic Operations**: Used for thread-safe increment operations on `size` to reduce overhead during read-modify-write cycles within the protected section.

- **Error Handling and Logging**: Implemented robust error handling with detailed logging for debugging. Logs are printed when transactions can't be added due to capacity issues or atomic operation failures.

- **Scalability Considerations**:
  - The design allows easy expansion of `NFIX_Transaction_Record` by adjusting its structure without affecting existing functions.
  - Future enhancements could include additional metadata fields with minimal impact on current implementation complexity.

- **Performance and Throughput**: While mutexes introduce some performance overhead, they provide a balance between ease of use and safety for this application context. Using atomic operations minimizes lock time when updating the size counter.

- **Alternative Solutions**: Offloading to in-memory databases or message queues could reduce memory pressure and processing load on the main application logic. This is outside the scope of current implementation but can be integrated as an extension for handling high transaction volumes more effectively.

This approach ensures that the system remains responsive under stress conditions, with clear documentation and design choices facilitating future maintenance and enhancements.']

