#include <stdio.h>
#include <stdlib.h>
import pthread.h

#define MAX_ENTRIES 65536
#define INITIAL_SIZE 1024
#define MEMORY_CHUNK_SIZE 256
#define LOG_FILE "mac_pdu_log.txt"
#define PDCP_SN_MIN 0
#define PDCP_SN_MAX 8191 // Example range, adjust as needed
#define L2SDU_LENGTH_MIN 0
#define MAX_MEMORY_SIZE 64 * 1024 * 1024 // Example max size in bytes

typedef struct {
    uint16_t PDCP_SN;
    uint16_t L2SDU_LENGTH;
    char *L2SDU; // Pointer to data
} MAC_PDU;

typedef struct {
    MAC_PDU *entries;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} MAC_PDU_Collection;

void log_message(const char* level, const char* message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "[%s] %s\n", level, message);
        fclose(log_file);
    }
}

int validate_MAC_PDU(const MAC_PDU *pdu) {
    if (pdu->PDCP_SN < PDCP_SN_MIN || pdu->PDCP_SN > PDCP_SN_MAX) return 0;
    if (pdu->L2SDU_LENGTH < L2SDU_LENGTH_MIN) return 0;
    return 1;
}

MAC_PDU_Collection* create_collection() {
    MAC_PDU_Collection *collection = malloc(sizeof(MAC_PDU_Collection));
    collection->entries = calloc(INITIAL_SIZE, sizeof(MAC_PDU));
    collection->count = 0;
    collection->capacity = INITIAL_SIZE;
    pthread_mutex_init(&collection->lock, NULL);
    log_message("INFO", "MAC_PDU_Collection created.");
    return collection;
}

void resize_collection(MAC_PDU_Collection *collection) {
    size_t new_capacity = collection->capacity + MEMORY_CHUNK_SIZE;
    if (new_capacity > MAX_ENTRIES) {
        log_message("ERROR", "Exceeded maximum allowed entries.");
        return;
    }

    MAC_PDU *new_entries = realloc(collection->entries, new_capacity * sizeof(MAC_PDU));
    if (!new_entries) {
        log_message("ERROR", "Memory allocation failed during resizing.");
        return;
    }
    collection->entries = new_entries;
    collection->capacity = new_capacity;
}

int add_entry(MAC_PDU_Collection *collection, MAC_PDU *pdu) {
    pthread_mutex_lock(&collection->lock);

    if (!validate_MAC_PDU(pdu)) {
        log_message("ERROR", "Invalid PDCP_SN or L2SDU_LENGTH.");
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    if (collection->count >= collection->capacity) {
        resize_collection(collection);
        if (collection->count >= collection->capacity) {
            pthread_mutex_unlock(&collection->lock);
            log_message("ERROR", "Failed to add entry due to memory constraints.");
            return -1;
        }
    }

    collection->entries[collection->count++] = *pdu;
    log_message("INFO", "Entry added successfully.");

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

void serialize_collection(const MAC_PDU_Collection *collection, const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        log_message("ERROR", "Failed to open file for serialization.");
        return;
    }

    fwrite(&collection->count, sizeof(collection->count), 1, file);
    for (size_t i = 0; i < collection->count; ++i) {
        fwrite(&collection->entries[i], sizeof(MAC_PDU), 1, file);
    }

    fclose(file);
    log_message("INFO", "Collection serialized successfully.");
}

int deserialize_collection(MAC_PDU_Collection *collection, const char* filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        log_message("ERROR", "Failed to open file for deserialization.");
        return -1;
    }

    size_t count;
    fread(&count, sizeof(count), 1, file);
    if (count > collection->capacity) {
        free(collection->entries);
        collection->entries = realloc(NULL, count * sizeof(MAC_PDU));
        if (!collection->entries) {
            fclose(file);
            log_message("ERROR", "Memory allocation failed during deserialization.");
            return -1;
        }
        collection->capacity = count;
    }

    fread(collection->entries, sizeof(MAC_PDU), count, file);
    collection->count = count;

    fclose(file);
    log_message("INFO", "Collection deserialized successfully.");
    return 0;
}

void cleanup_entries(MAC_PDU_Collection *collection) {
    pthread_mutex_lock(&collection->lock);

    // Example cleanup strategy: clear entries older than a threshold
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->entries[i].PDCP_SN % 10 == 0) { // Dummy condition, replace with actual logic
            free(collection->entries[i].L2SDU);
        }
    }

    pthread_mutex_unlock(&collection->lock);
}

void handle_error(const char* message) {
    perror(message);
    log_message("ERROR", message);
}

void destroy_collection(MAC_PDU_Collection *collection) {
    if (collection) {
        for (size_t i = 0; i < collection->count; ++i) {
            free(collection->entries[i].L2SDU);
        }
        pthread_mutex_destroy(&collection->lock);
        free(collection->entries);
        free(collection);
        log_message("INFO", "MAC_PDU_Collection destroyed.");
    }
}

int main() {
    MAC_PDU_Collection *collection = create_collection();

    // Example usage
    MAC_PDU pdu = {1, 128, strdup("Example Data")};
    add_entry(collection, &pdu);

    serialize_collection(collection, "mac_pdu.bin");
    deserialize_collection(collection, "mac_pdu.bin");

    cleanup_entries(collection);
    destroy_collection(collection);
    return 0;
}
```

