}

void resize_azt_list(azt_list_t *list) {
    size_t new_capacity = list->capacity * GROWTH_FACTOR;
    if ((new_capacity + sizeof(azt_tx_pdu_t)) > MAX_MEMORY_SIZE / sizeof(azt_tx_pdu_t)) {
        fprintf(stderr, "Cannot resize beyond memory limits.\n");
        return;
    }

    azt_tx_pdu_t *new_entries = realloc(list->entries, new_capacity * sizeof(azt_tx_pdu_t));
    if (!new_entries) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }
    list->entries = new_entries;
    list->capacity = new_capacity;
}

void add_pdu(azt_list_t *list, const azt_tx_pdu_t *pdu) {
    pthread_mutex_lock(&list->lock);

    if (!validate_pdu(pdu)) {
        fprintf(stderr, "Invalid PDU: %d\n", pdu->sequence_number);
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (list->count == list->capacity) {
        resize_azt_list(list);
    }

    memcpy(&list->entries[list->count++], pdu, sizeof(azt_tx_pdu_t));

    pthread_mutex_unlock(&list->lock);
}

void serialize_list(const azt_list_t *list, unsigned char **out_data, size_t *out_size) {
    pthread_mutex_lock(&list->lock);

    size_t total_size = list->count * sizeof(azt_tx_pdu_t);
    if (total_size > MAX_MEMORY_SIZE) {
        fprintf(stderr, "Serialization exceeds maximum memory size.\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    *out_data = malloc(total_size);
    memcpy(*out_data, list->entries, total_size);
    *out_size = total_size;

    pthread_mutex_unlock(&list->lock);
}

int deserialize_list(const unsigned char *data, size_t data_size, azt_list_t *list) {
    pthread_mutex_lock(&list->lock);

    size_t num_entries = data_size / sizeof(azt_tx_pdu_t);
    if (num_entries > list->capacity) {
        fprintf(stderr, "Deserialization requires more capacity than available.\n");
        pthread_mutex_unlock(&list->lock);
        return DECODE_ERROR_INVALID_FORMAT;
    }

    memcpy(list->entries, data, data_size);
    list->count = num_entries;

    pthread_mutex_unlock(&list->lock);
    return DECODE_SUCCESS;
}

void log_operation(const char *message) {
    printf("Log: %s\n", message);
}
