}

NFAPI_MESSAGE_T* generate_nfa_messages(size_t n, NFAPI_CRC_INDICATION_PDU_T **pdu_list, size_t *pdu_count) {
    if (n > MAX_ELEMENTS || !pdu_list || !pdu_count) return NULL;

    NFAPI_MESSAGE_T *messages = malloc(n * sizeof(NFAPI_MESSAGE_T));
    if (!messages) return NULL;

    uint16_t rnti;
    size_t pdu_index = 0;
    *pdu_count = 0;

    for (size_t i = 0; i < n; ++i) {
        pthread_mutex_lock(&mutex);

        do {
            rnti = rand() % UINT16_MAX;
        } while (rnti == last_rnti);
        last_rnti = rnti;

        pthread_mutex_unlock(&mutex);

        messages[i].rx_ue_information_tag.tag = rand(); // Generate a valid tag
        messages[i].rnti.rnti = rnti;
        generate_random_crcflag(&messages[i].crc_indication_rel8_tag);

        NFAPI_CRC_INDICATION_PDU_T pdu = {
            .rx_ue_information_tag = messages[i].rx_ue_information_tag,
            .rnti = messages[i].rnti,
            .crc_indication_rel8_tag = messages[i].crc_indication_rel8_tag
        };

        pthread_mutex_lock(&mutex);
        if (pdu_index < MAX_ELEMENTS) {
            (*pdu_list)[pdu_index++] = pdu;
            (*pdu_count)++;
        }
        pthread_mutex_unlock(&mutex);
    }

    return messages;
}

void free_messages(NFAPI_MESSAGE_T *messages) {
    free(messages);
}

int main() {
    srand(time(NULL));

    NFAPI_CRC_INDICATION_PDU_T *pdu_list = malloc(MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) return 1;

