void generate_and_manage_list(int max_entries) {
    if (max_entries <= 0 || max_entries > MAX_ENTRIES) {
        printf("Invalid number of maximum entries.\n");
        return;
    }

    for (int i = 0; i < max_entries; ++i) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            printf("Memory allocation failed at entry %d\n", i);
            break;
        }

        // Generate random data
