        // Verify calculated CRC (for demonstration, assuming function `verify_crc`)
        if (!verify_crc(&new_node->data, crc_value)) {
            printf("CRC verification failed at entry %d\n", i);
            free(new_node);
            continue;
        }

        // Add node to the list in a thread-safe manner
        pthread_mutex_lock(&list_mutex);
        new_node->next = head;
        head = new_node;
        atomic_fetch_add_explicit(&entry_count, 1, memory_order_relaxed);
        pthread_mutex_unlock(&list_mutex);
    }

    printf("Total entries successfully created: %d\n", entry_count.load());
}

void cleanup_list() {
    Node* current = head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list_mutex);
}

