    if (num_packets > max_packets) num_packets = max_packets;

    NFAPI_CRC_INDICATION_PDU_T *packets = allocateMemory(num_packets * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!packets) {
        callback(0, NULL);
        return;
    }

    pthread_mutex_lock(&allocation_mutex);
    for (int i = 0; i < num_packets; ++i) {
        packets[i].rx_ue_information_tag.RNTI = rand();
        packets[i].rnti = rand();
        packets[i].crc_indication_rel8_tag.CRCFLAG = rand() % 2;

