        printf("Allocated packet %d with RNTI: %lu, CRCFLAG: %d\n", i, packets[i].rx_ue_information_tag.RNTI, packets[i].crc_indication_rel8_tag.CRCFLAG);
    }
    pthread_mutex_unlock(&allocation_mutex);

    callback(1, packets);
}

void cleanupNFAPackets(NFAPI_CRC_INDICATION_PDU_T *packets) {
    if (packets) {
        freeMemoryPool(); // Reinitialize the pool for simplicity
        printf("Cleanup completed.\n");
    }
}

// Sample Callback Function
void allocationCallback(int success, NFAPI_CRC_INDICATION_PDU_T *packet) {
    if (success && packet) {
        printf("Allocation successful. Number of packets: %zu\n", sizeof(packet) / sizeof(NFAPI_CRC_INDICATION_PDU_T));
        cleanupNFAPackets(packet);
    } else {
        fprintf(stderr, "Allocation failed.\n");
    }
}

int main() {
    srand(time(NULL));

    int num_packets = 5; // Example input
    allocateAndPopulateNFAPackets(num_packets, allocationCallback);

    return 0;
}
