// Memory pool structure for efficient allocation
typedef struct {
    size_t block_size;
    unsigned int count;
    unsigned int used;
    PDUEntry *pool;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, unsigned int count) {
    MemoryPool *mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!mp) return NULL;

    mp->block_size = block_size;
    mp->count = count;
    mp->used = 0;
    mp->pool = (PDUEntry*)malloc(block_size * count);
    if (!mp->pool) {
        free(mp);
        return NULL;
    }
    return mp;
}

void destroy_memory_pool(MemoryPool *mp) {
    if (mp) {
        free(mp->pool);
        free(mp);
    }
}

PDUEntry* pool_allocate(MemoryPool *mp) {
    if (mp->used < mp->count) {
        return &mp->pool[mp->used++];
    }
    return NULL;
}

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* generateNfapiPduList(void* arg) {
    int N = *(int*)arg;
