        log_message("ERROR", "Memory pool creation failed.");
        return NULL;
    }

    pthread_mutex_lock(&lock);
    for (int i = 0; i < N; ++i) {
        PDUEntry *entry = pool_allocate(mp);
        if (!entry) break;

        entry->RX_UE_INFORMATION_TAG = rand() % 1000000; // Example tag generation
        do {
