        } while (entry->RNTI == MAX_RNTI); // Avoid max limit

        int crcflag = rand() % 2;
        entry->pdu.crc_tag.CRCFLAG = crcflag;

        log_message("INFO", "Generated PDU entry.");
    }
    pthread_mutex_unlock(&lock);

    destroy_memory_pool(mp);
    return NULL;
}

int main(int argc, char *argv[]) {
    int N = 10000; // Example input
    pthread_t thread_id;

    if (pthread_create(&thread_id, NULL, generateNfapiPduList, &N) != 0) {
        log_message("ERROR", "Thread creation failed.");
        return EXIT_FAILURE;
    }

    pthread_join(thread_id, NULL);
    return EXIT_SUCCESS;
}
