typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu_array;
    size_t capacity;
    pthread_mutex_t mutex; // For managing concurrent access
    uint32_t hash_table_size;
    bool* tag_present;  // Simple hash table for quick look-up of tags
} PDU_MANAGER;

// Error structure to handle memory allocation failures
typedef struct {
    int error_code;
    char message[256];
} MemoryError;

PDU_MANAGER* init_pdu_manager(size_t initial_capacity, uint32_t hash_table_size) {
    PDU_MANAGER *manager = (PDU_MANAGER*)malloc(sizeof(PDU_MANAGER));
    if (!manager) return NULL;

    manager->pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->pdu_array) {
        free(manager);
        MemoryError err = {1, "Failed to allocate memory for PDU array"};
        printf("%s\n", err.message);
        return NULL;
    }

    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->mutex, NULL);
    manager->hash_table_size = hash_table_size;
    manager->tag_present = (bool*)calloc(hash_table_size, sizeof(bool));
    if (!manager->tag_present) {
        free(manager->pdu_array);
        free(manager);
        MemoryError err = {2, "Failed to allocate memory for tag presence table"};
        printf("%s\n", err.message);
        return NULL;
    }

    return manager;
}

uint32_t hash_tag(const char* tag) {
    uint32_t hash = 0;
    while (*tag) {
        hash = (hash * 31 + *tag++) % HASH_TABLE_SIZE;
    }
    return hash;
}

bool is_duplicate(PDU_MANAGER* manager, const RX_UE_INFORMATION_TAG* tag) {
    uint32_t index = hash_tag(tag) % manager->hash_table_size;
    pthread_mutex_lock(&manager->mutex);
    bool present = manager->tag_present[index];
    pthread_mutex_unlock(&manager->mutex);
    return present;
}

void set_duplicate(PDU_MANAGER* manager, const RX_UE_INFORMATION_TAG* tag) {
    uint32_t index = hash_tag(tag) % manager->hash_table_size;
    pthread_mutex_lock(&manager->mutex);
    manager->tag_present[index] = true;
    pthread_mutex_unlock(&manager->mutex);
}

void populate_pdu_manager(PDU_MANAGER* manager, size_t n, double p) {
    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < n && i < manager->capacity; ++i) {
        // Simulate RX_UE_INFORMATION_TAG and RNTI generation
        snprintf(manager->pdu_array[i].rx_ue_info.RX_UE_INFORMATION_TAG, sizeof(RX_UE_INFORMATION_TAG), "TAG_%zu", i);
        manager->pdu_array[i].rx_ue_info.RNTI = (uint32_t)i;

        if (!is_duplicate(manager, manager->pdu_array[i].rx_ue_info.RX_UE_INFORMATION_TAG)) {
            set_duplicate(manager, manager->pdu_array[i].rx_ue_info.RX_UE_INFORMATION_TAG);
            // Randomly set CRCFLAG
            double r = (double)rand() / RAND_MAX;
            manager->pdu_array[i].crc_tag.CRCFLAG = r < p;

            // Populate crc_value as needed
            manager->pdu_array[i].crc_tag.crc_value = i;  // Example value
        }
    }

    pthread_mutex_unlock(&manager->mutex);
}

void modify_pdu_entry(PDU_MANAGER* manager, size_t index, const RX_UE_INFORMATION_TAG* new_tag, uint32_t new_rnti) {
    if (index >= manager->capacity) return;

    pthread_mutex_lock(&manager->mutex);
    strncpy(manager->pdu_array[index].rx_ue_info.RX_UE_INFORMATION_TAG, new_tag, sizeof(RX_UE_INFORMATION_TAG));
    manager->pdu_array[index].rx_ue_info.RNTI = new_rnti;
    pthread_mutex_unlock(&manager->mutex);
}

void clear_crc_flags(PDU_MANAGER* manager) {
    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->capacity; ++i) {
        manager->pdu_array[i].crc_tag.CRCFLAG = false;
    }

    pthread_mutex_unlock(&manager->mutex);
}

void free_pdu_manager(PDU_MANAGER* manager) {
    if (manager) {
        free(manager->pdu_array);
        free(manager->tag_present);
        pthread_mutex_destroy(&manager->mutex);
        free(manager);
    }
}

// Example of a unit test
void test_pdu_manager() {
    PDU_MANAGER* manager = init_pdu_manager(100, 101); // Capacity and prime hash size
    if (!manager) return;

    populate_pdu_manager(manager, 50, 0.5);

    modify_pdu_entry(manager, 10, "NEW_TAG_10", 9999);

    clear_crc_flags(manager);

    free_pdu_manager(manager);
}

int main() {
    srand(time(NULL));
    test_pdu_manager();
    return 0;
}
