### JavaScript Function: Safe Copy from Fragmented Buffers

```javascript
function safeCopyFromChunks(chunks, copySize) {
    const result = Buffer.alloc(copySize);

    let offset = 0;
    for (let chunk of chunks) {
        if (!Buffer.isBuffer(chunk)) {
            throw new Error("All chunks must be instances of Buffer");
        }

        const bytesToCopy = Math.min(result.length - offset, chunk.length);
        if (bytesToCopy > 0) {
            chunk.copy(result, offset, 0, bytesToCopy);
            offset += bytesToCopy;
        }

        // Break early if we've copied enough data
        if (offset >= copySize) break;
    }

    // Slice the result buffer to only include the data that was successfully copied
    return result.slice(0, offset);
}

// Example usage with error handling:
try {
    const chunks = [Buffer.from('hello '), Buffer.from('world'), Buffer.from('!!!')];
    const copySize = 10;
    const result = safeCopyFromChunks(chunks, copySize);
    console.log(result.toString());
} catch (error) {
    console.error("An error occurred:", error.message);
}
```

