// C Function: Dynamic List Management of NFAPI_RX_FRAME_PDU_T

#include <stdlib.h>
#include <string.h>

typedef struct {
    int valid;
} RX_UE_INFORMATION_TAG;

typedef uint16_t RNTI;

typedef struct {
    unsigned char crc[4];
} PHY_RX_HEADER;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    RNTI rnti;
    PHY_RX_HEADER phy_rx_header;
} NFAPI_RX_FRAME_PDU_T;

typedef struct Node {
    NFAPI_RX_FRAME_PDU_T frame;
    struct Node* next;
} Node;

Node* head = NULL;

void add_frame(RX_UE_INFORMATION_TAG ue_info_tag, RNTI rnti, unsigned char crc[4]) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return; // handle memory allocation failure
    new_node->frame.ue_info_tag = ue_info_tag;
    new_node->frame.rnti = rnti;
    memcpy(new_node->frame.phy_rx_header.crc, crc, 4);
    new_node->next = head;
    head = new_node;
}

void remove_frame(RNTI target_rnti) {
    Node *current = head, *prev = NULL;
    while (current != NULL && current->frame.rnti != target_rnti) {
        prev = current;
        current = current->next;
    }
    if (current == NULL) return; // RNTI not found
    if (prev == NULL) { // Removing the head node
        head = current->next;
    } else {
        prev->next = current->next;
    }
    free(current);
}

void clear_frames() {
    Node *current = head, *temp;
    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp);
    }
    head = NULL;
}
