#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} CRC_INDICATION_REL8_TAG_T;

typedef struct {
    CRC_INDICATION_REL8_TAG_T crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

#define INITIAL_CAPACITY 10

DynamicArray* init_dynamic_array() {
    DynamicArray *da = malloc(sizeof(DynamicArray));
    if (!da) return NULL;

    da->capacity = INITIAL_CAPACITY;
    da->size = 0;
    da->array = calloc(da->capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        free(da);
        return NULL;
    }

    pthread_mutex_init(&da->mutex, NULL);
    return da;
}

void resize_dynamic_array(DynamicArray *da, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) return;

    da->array = new_array;
    da->capacity = new_capacity;
}

void add_crc_indication(DynamicArray *da, uint16_t rnti) {
    pthread_mutex_lock(&da->mutex);

    if (da->size == da->capacity) {
        resize_dynamic_array(da, da->capacity * 2);
    }

    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.crc_tag.RX_UE_INFORMATION_TAG = rand(); // Assign a valid random value
    pdu.crc_tag.RNTI = rnti;
    pdu.crc_tag.CRCFLAG = (rnti % 2) != 0;

    da->array[da->size++] = pdu;

    pthread_mutex_unlock(&da->mutex);
}

void cleanup_dynamic_array(DynamicArray *da) {
    pthread_mutex_lock(&da->mutex);

    if (da->array) {
        free(da->array);
    }

    pthread_mutex_unlock(&da->mutex);
    pthread_mutex_destroy(&da->mutex);
    free(da);
}
```

### Explanation:
