// Logging function
void log_error(const char *message) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(file, "[%s] ERROR: %s\n", timestamp, message);

    fclose(file);
}

// Thread-safe dynamic allocation
NFAPI_CRC_INDICATION_PDU_T* allocate_memory(size_t N) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    pthread_mutex_lock(&lock);
    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T*) malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        log_error("Memory allocation failed");
        pthread_mutex_unlock(&lock);
        pthread_mutex_destroy(&lock);
        return NULL;
    }

    for (size_t i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 100; // Example value
        array[i].RNTI = rand() % 10000;                // Example value
        array[i].CRC_INDICATION_REL8_TAG = (rand() % 2) * 255; // Random CRC flag
    }

    pthread_mutex_unlock(&lock);
    pthread_mutex_destroy(&lock);
    return array;
}

// Compress data using zlib
int compress_data(NFAPI_CRC_INDICATION_PDU_T *data, size_t N, unsigned char **compressedData, size_t *compressedSize) {
    uLongf destLen = compressBound(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    *compressedData = (unsigned char*) malloc(destLen);
    if (!*compressedData) {
        log_error("Failed to allocate memory for compression");
        return -1;
    }

    int res = compress(*compressedData, &destLen, (const Bytef*) data, N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (res != Z_OK) {
        free(*compressedData);
        log_error("Compression failed");
        return -1;
    }

    *compressedSize = destLen;
    return 0;
}

// Verify integrity of decompressed data
int verify_integrity(NFAPI_CRC_INDICATION_PDU_T *original, NFAPI_CRC_INDICATION_PDU_T *decompressed, size_t N) {
    for (size_t i = 0; i < N; ++i) {
        if (memcmp(&original[i], &decompressed[i], sizeof(NFAPI_CRC_INDICATION_PDU_T))) {
            log_error("Data integrity check failed");
            return -1;
        }
    }
    return 0;
}

// Serialize to JSON format
int serialize_to_json(const NFAPI_CRC_INDICATION_PDU_T *data, size_t N, char **jsonOutput) {
    char buffer[1024];
    strcpy(buffer, "[\n");

    for (size_t i = 0; i < N; ++i) {
        snprintf(buffer + strlen(buffer), sizeof(buffer) - strlen(buffer),
                 "  {\"RX_UE_INFORMATION_TAG\": %d, \"RNTI\": %d, \"CRC_INDICATION_REL8_TAG\": %u}%s\n",
                 data[i].RX_UE_INFORMATION_TAG,
                 data[i].RNTI,
                 (unsigned)data[i].CRC_INDICATION_REL8_TAG,
                 i < N - 1 ? "," : "");
    }

    strcat(buffer, "]");

    *jsonOutput = strdup(buffer);
    if (!*jsonOutput) {
        log_error("Failed to allocate memory for JSON serialization");
        return -1;
    }

    return 0;
}

// Example usage
int main(int argc, char *argv[]) {
    size_t N = 10; // Assume user input is provided here
    NFAPI_CRC_INDICATION_PDU_T *array = allocate_memory(N);

    if (!array) {
        return EXIT_FAILURE;
    }

    unsigned char *compressedData = NULL;
    size_t compressedSize = 0;

    if (compress_data(array, N, &compressedData, &compressedSize) == -1) {
        free(array);
        return EXIT_FAILURE;
    }

    // Decompress for integrity check demonstration
    uLongf decompressedLen = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    unsigned char *decompressedData = (unsigned char*) malloc(decompressedLen);
    if (!decompressedData) {
        log_error("Failed to allocate memory for decompression");
        free(compressedData);
        free(array);
        return EXIT_FAILURE;
    }

    if (uncompress(decompressedData, &decompressedLen, compressedData, compressedSize) != Z_OK) {
        log_error("Decompression failed");
        free(decompressedData);
        free(compressedData);
        free(array);
        return EXIT_FAILURE;
    }

    NFAPI_CRC_INDICATION_PDU_T *decompressedArray = (NFAPI_CRC_INDICATION_PDU_T*) decompressedData;

    if (verify_integrity(array, decompressedArray, N) == -1) {
        free(decompressedData);
        free(compressedData);
        free(array);
        return EXIT_FAILURE;
    }

    char *jsonOutput = NULL;
    if (serialize_to_json(array, N, &jsonOutput) == -1) {
        free(jsonOutput);
        free(decompressedData);
        free(compressedData);
        free(array);
        return EXIT_FAILURE;
    }

    printf("%s\n", jsonOutput);

    // Cleanup
    free(jsonOutput);
    free(decompressedData);
    free(compressedData);
    free(array);

