#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>
#include <string.h>
#include <errno.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint8_t CRC_FLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_RNTI 65535
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Logger structure and functions
typedef struct {
    FILE *log_file;
    int log_level;
} logger_t;

logger_t logger;

void init_logger(const char *path, int level) {
    pthread_mutex_lock(&mutex);
    logger.log_file = fopen(path, "a");
    if (!logger.log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    logger.log_level = level;
    pthread_mutex_unlock(&mutex);
}

void log_message(const char *message) {
    if (logger.log_level > 0) {
        time_t now;
        time(&now);
        pthread_mutex_lock(&mutex);
        fprintf(logger.log_file, "[%s] %s\n", ctime(&now), message);
        fflush(logger.log_file);
        pthread_mutex_unlock(&mutex);
    }
}

void cleanup_logger() {
    if (logger.log_file) {
        fclose(logger.log_file);
    }
}

// Function to dynamically allocate array
NFAPI_CRC_INDICATION_PDU_T* create_nfa_pdu_array(size_t N, int log_level, const char *log_path) {
    init_logger(log_path, log_level);

    // Memory allocation for the array
    NFAPI_CRC_INDICATION_PDU_T *array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        log_message("Memory allocation failed");
        return NULL;
    }

    pthread_mutex_lock(&mutex);
    uint16_t rnti_set[MAX_RNTI / 32] = {0};

    for (size_t i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 10000;

        // Ensure unique RNTI
        uint16_t rnti;
        do {
            rnti = rand() % MAX_RNTI;
        } while (rnti_set[rnti / 32] & (1 << (rnti % 32)));

        array[i].RNTI = rnti;
        rnti_set[rnti / 32] |= (1 << (rnti % 32));

        // Random CRC_FLAG generation and verification
        uint8_t crc_flag = rand() & 0x01;
        if (!(crc_flag)) {
            log_message("CRC flag validation failed, retrying...");
            --i;  // Retry this index
            continue;
        }

        array[i].CRC_INDICATION_REL8_TAG.CRC_FLAG = crc_flag;
    }

    pthread_mutex_unlock(&mutex);

    return array;
}

// Usage example (to be replaced with actual command-line argument parsing)
int main(int argc, char *argv[]) {
    size_t N = 100; // Number of elements
    int log_level = 1; // Logging level
    const char *log_path = "application.log"; // Log file path

    NFAPI_CRC_INDICATION_PDU_T* pdu_array = create_nfa_pdu_array(N, log_level, log_path);
    if (pdu_array) {
        free(pdu_array);  // Ensure to free allocated memory
    }

    cleanup_logger();
    return 0;
}
