    ListNode* head;
    pthread_mutex_t mutex;
    pthread_cond_t cond_var;
} CRCList;

// Function prototypes
void init_list(CRCList* list);
void destroy_list(CRCList* list);
void add_entry(CRCList* list, NFAPI_CRC_INDICATION_PDU_T entry);
void purge_old_entries(CRCList* list);
void reset_crc_flags(CRCList* list);
static void remove_node(ListNode** head, ListNode* node_to_remove);

// Initialize the list
void init_list(CRCList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->cond_var, NULL);
}

// Destroy the list and free memory
void destroy_list(CRCList* list) {
    ListNode *current = list->head, *next_node;

    while (current != NULL) {
        next_node = current->next;
        free(current);
        current = next_node;
    }

    pthread_mutex_destroy(&list->mutex);
    pthread_cond_destroy(&list->cond_var);
}

// Add an entry to the list
void add_entry(CRCList* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    ListNode *new_node = malloc(sizeof(ListNode));
    if (!new_node) return; // Handle allocation failure

    new_node->data = entry;
    new_node->next = NULL;

    pthread_mutex_lock(&list->mutex);

    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->mutex);
}

// Purge outdated entries older than 5 seconds
void purge_old_entries(CRCList* list) {
    time_t now = time(NULL);
    ListNode *current = list->head, *prev = NULL;

    pthread_mutex_lock(&list->mutex);

    while (current != NULL) {
        if ((now - current->data.timestamp) > 5) { // Entries older than 5 seconds
            ListNode* temp = current;
            if (prev == NULL)
                list->head = current->next; 
            else
                prev->next = current->next;

            current = current->next;
            free(temp);
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->mutex);
}

// Reset all CRC flags in the list
void reset_crc_flags(CRCList* list) {
    ListNode *current = list->head;

    pthread_mutex_lock(&list->mutex);

    while (current != NULL) {
        current->data.CRC_INDICATION_REL8_TAG.CRCFLAG = 0; // Assuming CRCFLAG is a field within CRC_INDICATION_REL8_TAG
        current = current->next;
    }

    pthread_mutex_unlock(&list->mutex);
}

// Error handling and logging utility function (example)
void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}
