```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

#define MAX_FRAMES 500000

typedef struct {
    uint32_t l2_pdu_id;
    // Other L2_PDU fields...
} L2_PDU_T;

typedef struct {
    int tci_state_index;
    time_t timestamp;
    L2_PDU_T l2_pdu;
} MAC_RX_FRAME_T;

typedef struct {
    MAC_RX_FRAME_T* frames;
    size_t count;
    pthread_mutex_t lock;
    uint32_t next_l2_pdu_id; // To generate unique L2_PDU IDs
} FrameManager;

void init_frame_manager(FrameManager* fm, size_t max_count) {
    fm->frames = (MAC_RX_FRAME_T*)malloc(max_count * sizeof(MAC_RX_FRAME_T));
    if (!fm->frames) {
        perror("Failed to allocate memory for frames");
        exit(EXIT_FAILURE);
    }
    fm->count = 0;
    pthread_mutex_init(&fm->lock, NULL);
    fm->next_l2_pdu_id = 1; // Starting from 1 for uniqueness
}

void destroy_frame_manager(FrameManager* fm) {
    if (fm->frames) {
        free(fm->frames);
    }
    pthread_mutex_destroy(&fm->lock);
}

int add_mac_rx_frame(FrameManager* fm, int tci_state_index, time_t timestamp, uint32_t min_l2_pdu_id, uint32_t max_l2_pdu_id) {
    if (fm->count >= MAX_FRAMES) return -1; // No space left

    pthread_mutex_lock(&fm->lock);

    MAC_RX_FRAME_T* frame = &fm->frames[fm->count];
    fm->count++;

    // Generate a unique L2_PDU ID
    uint32_t l2_pdu_id;
    do {
        l2_pdu_id = fm->next_l2_pdu_id++;
    } while (l2_pdu_id < min_l2_pdu_id || l2_pdu_id > max_l2_pdu_id);

    frame->tci_state_index = tci_state_index;
    frame->timestamp = timestamp;
    frame->l2_pdu.l2_pdu_id = l2_pdu_id;

    pthread_mutex_unlock(&fm->lock);
    return 0; // Success
}

void populate_frames(FrameManager* fm, int start_tci, int end_tci, time_t min_timestamp, time_t max_timestamp) {
    if (!fm || !fm->frames) return;

    for (size_t i = 0; i < MAX_FRAMES && i < fm->count; ++i) {
        MAC_RX_FRAME_T* frame = &fm->frames[i];

        // Check timestamp range
        if (frame->timestamp < min_timestamp || frame->timestamp > max_timestamp) continue;

        // Ensure TCI index is within range
        if (frame->tci_state_index >= start_tci && frame->tci_state_index <= end_tci) {
            // Verify L2_PDU integrity
            if (frame->l2_pdu.l2_pdu_id == 0) { // Assuming 0 as invalid ID
                fprintf(stderr, "Invalid L2_PDU ID at index %zu\n", i);
                continue;
            }
        } else {
            continue; // Skip frames outside TCI range
        }

        // Frame is valid and within specified criteria
        printf("Frame[%zu]: TCI=%d, PDU_ID=%u, Timestamp=%ld\n",
               i, frame->tci_state_index, frame->l2_pdu.l2_pdu_id, frame->timestamp);
    }
}

int main() {
    FrameManager fm;
    init_frame_manager(&fm, MAX_FRAMES);

    // Simulate adding frames
    time_t now = time(NULL);
    for (int i = 0; i < 100000; ++i) { // Adding fewer than max to simulate
        add_mac_rx_frame(&fm, i % 100, now - (rand() % 3600), 1, UINT32_MAX); // Random timestamps within last hour
    }

    populate_frames(&fm, 10, 90, now - 1800, now); // Filter frames in TCI range [10, 90] and last 30 minutes

    destroy_frame_manager(&fm);
    return 0;
}
```

### Key Points:

- **Thread Safety**: Mutex locks ensure that concurrent access to the `FrameManager` is safe.
- **Unique L2_PDU IDs**: Managed using an incrementing counter with boundary checks.
- **Resource Management**: Proper allocation and deallocation of memory, ensuring no leaks.
- **Data Integrity**: Checks for valid L2_PDU IDs and timestamps.
- **Scalability**: Efficiently handles up to `MAX_FRAMES` frames.
- **Flexibility**: Allows filtering by TCI index range and timestamp.']

