#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_NFAPI_CRC_INDICATION_PDUS 100000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG; // Assume this is a single byte flag
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPool {
    size_t unit_size;
    void *pool;
    size_t pool_size;
    pthread_mutex_t lock;
} MemoryPool;

int initialize_memory_pool(MemoryPool *mp, size_t unit_size, size_t num_units) {
    mp->unit_size = unit_size;
    mp->pool_size = unit_size * num_units;

    if ((mp->pool = malloc(mp->pool_size)) == NULL) {
        return -1; // Memory allocation failed
    }

    pthread_mutex_init(&mp->lock, NULL);
    return 0;
}

void* allocate_from_pool(MemoryPool *mp) {
    void *ptr = NULL;

    pthread_mutex_lock(&mp->lock);
    if ((size_t)((char*)mp->pool + mp->unit_size) <= (size_t)mp->pool + mp->pool_size) {
        ptr = mp->pool;
        mp->pool = (char*)mp->pool + mp->unit_size; // Move pool pointer
    }
    pthread_mutex_unlock(&mp->lock);

    return ptr;
}

void free_memory_pool(MemoryPool *mp) {
    if (mp->pool) {
        free(mp->pool);
        mp->pool = NULL;
    }
    pthread_mutex_destroy(&mp->lock);
}

int validate_parameters(int RX_UE_INFORMATION_TAG, int RNTI) {
    return RX_UE_INFORMATION_TAG > 0 && RNTI > 0; // Example validation
}

NFAPI_CRC_INDICATION_PDU_T* allocate_nfa_pdu_list(size_t n) {
