        fprintf(stderr, "Invalid number of structures requested.\n");
        return NULL;
    }

    MemoryPool pool;
    initialize_memory_pool(&pool, sizeof(NFAPI_CRC_INDICATION_PDU_T), n);

    NFAPI_CRC_INDICATION_PDU_T *pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        fprintf(stderr, "Failed to allocate memory for PDU list.\n");
        free_memory_pool(&pool);
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = allocate_from_pool(&pool);

        if (!pdu) {
            fprintf(stderr, "Failed to allocate memory from pool for PDU %zu.\n", i);
            free(pdu_list);
            free_memory_pool(&pool);
            return NULL;
        }

        pdu->RX_UE_INFORMATION_TAG = rand() % 1000 + 1; // Example random generation
        pdu->RNTI = rand() % 5000 + 1;
        pdu->CRC_INDICATION_REL8_TAG = rand() % 256;

        if (!validate_parameters(pdu->RX_UE_INFORMATION_TAG, pdu->RNTI)) {
            fprintf(stderr, "Validation failed for PDU %zu.\n", i);
            free(pdu_list);
            free_memory_pool(&pool);
            return NULL;
        }

        pdu->CRCFLAG = rand() & 1; // Set random CRCFLAG (0 or 1)

        memcpy((char*)pdu_list + i * sizeof(NFAPI_CRC_INDICATION_PDU_T), pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    free_memory_pool(&pool);
    return pdu_list;
}

int main() {
