#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>

#define MAX_CRC_FLAGS 32

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* create_dynamic_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_node(Node* node) {
    free(node);
}

int add_element(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1;

    new_node->data = element;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

int iterate_list(DynamicList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    if (!list || !callback) return -1;

    Node* current = NULL;

    pthread_mutex_lock(&list->lock);
    current = list->head;
    pthread_mutex_unlock(&list->lock);

    while (current) {
        callback(&(current->data));
        current = current->next;
    }

    return 0;
}

void clear_list(DynamicList* list) {
    if (!list) return;

    Node* current = NULL;
    Node* next_node = NULL;

    pthread_mutex_lock(&list->lock);
    current = list->head;
    while (current) {
        next_node = current->next;
        free_node(current);
        current = next_node;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
}

void destroy_dynamic_list(DynamicList* list) {
    if (!list) return;

    clear_list(list);
    free(list);
}

