#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_CLIENTS 1000
#define PDU_SIZE 1500
#define LOG_FILE "pdu_log.txt"

typedef struct {
    uint8_t source_mac[6];
    uint8_t destination_mac[6];
    uint16_t protocol_type;
    char data[PDU_SIZE - 18]; // Remaining space for metadata
} L2_PDU;

typedef struct {
    L2_PDU *pdus[MAX_CLIENTS];
    pthread_mutex_t lock;
    int active_clients;
} NetworkInterface;

void log_error(const char *message) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file != NULL) {
        fprintf(file, "%s\n", message);
        fclose(file);
    }
}

int validate_pdu(L2_PDU *pdu) {
    // Example validation: check protocol type and MAC address length
    if (ntohs(pdu->protocol_type) == 0 || 
        sizeof(pdu->source_mac) != 6 || 
        sizeof(pdu->destination_mac) != 6) {
        log_error("Invalid PDU format");
        return 0;
    }
    return 1;
}

void process_pdu(NetworkInterface *interface, L2_PDU *pdu) {
    pthread_mutex_lock(&interface->lock);
    if (interface->active_clients < MAX_CLIENTS) {
        interface->pdus[interface->active_clients++] = pdu;
        // Simulate processing
    } else {
        log_error("Too many active clients");
    }
    pthread_mutex_unlock(&interface->lock);
}

void configure_network_interface(NetworkInterface *interface) {
    memset(interface, 0, sizeof(NetworkInterface));
    pthread_mutex_init(&interface->lock, NULL);

    // External configuration service can be integrated here
}

void cleanup_network_interface(NetworkInterface *interface) {
    for (int i = 0; i < interface->active_clients; ++i) {
        free(interface->pdus[i]);
    }
    pthread_mutex_destroy(&interface->lock);
}

L2_PDU* create_pdu(uint8_t *source_mac, uint8_t *destination_mac, uint16_t protocol_type, const char *data) {
    L2_PDU *pdu = malloc(sizeof(L2_PDU));
    if (pdu == NULL) {
        log_error("Memory allocation failed for PDU");
        return NULL;
    }

    memcpy(pdu->source_mac, source_mac, 6);
    memcpy(pdu->destination_mac, destination_mac, 6);
    pdu->protocol_type = htons(protocol_type);
    strncpy((char*)pdu->data, data, sizeof(pdu->data) - 1);
    pdu->data[sizeof(pdu->data) - 1] = '\0';

    time_t now;
    time(&now);
    snprintf(pdu->data + strlen(pdu->data), sizeof(pdu->data) - strlen(pdu->data), " | Timestamp: %ld", now);

    return validate_pdu(pdu) ? pdu : NULL;
}

void handle_client(NetworkInterface *interface, uint8_t *source_mac, uint8_t *destination_mac, uint16_t protocol_type, const char *data) {
    L2_PDU *pdu = create_pdu(source_mac, destination_mac, protocol_type, data);
    if (pdu != NULL) {
        process_pdu(interface, pdu);
    }
}

// Example usage
int main() {
    NetworkInterface interface;
    configure_network_interface(&interface);

    uint8_t source_mac[6] = {0x00, 0x1A, 0x2B, 0x3C, 0x4D, 0x5E};
    uint8_t destination_mac[6] = {0x5E, 0x4D, 0x3C, 0x2B, 0x1A, 0x00};
    handle_client(&interface, source_mac, destination_mac, 0x0800, "Hello World");

    cleanup_network_interface(&interface);
    return 0;
}
