// Error codes
typedef enum {
    SUCCESS = 0,
    MEMORY_ALLOCATION_FAILED,
    INVALID_PARAMETERS,
    DATA_PROCESSING_ERROR
} ErrorCode_t;

ErrorCode_t allocate_and_initialize_structures(NFAPI_CRC_INDICATION_PDU_T **struct_array, size_t n) {
    if (n > MAX_STRUCTURES || struct_array == NULL) {
        return INVALID_PARAMETERS;
    }

    // Determine the actual number of structures to allocate
    size_t alloc_size = (n > MAX_STRUCTURES) ? MAX_STRUCTURES : n;

    NFAPI_CRC_INDICATION_PDU_T *temp_struct_array = NULL;
    ErrorCode_t result = MEMORY_ALLOCATION_FAILED;
    int retry_count = 0;

    while (retry_count < RETRY_LIMIT && !result) {
        temp_struct_array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(alloc_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (temp_struct_array == NULL) {
            result = MEMORY_ALLOCATION_FAILED;
            retry_count++;
            printf("Memory allocation failed, retrying... (%d/%d)\n", retry_count, RETRY_LIMIT);
        } else {
            // Initialize structures
            for (size_t i = 0; i < alloc_size; i++) {
                temp_struct_array[i].RX_UE_INFORMATION_TAG = rand() % 10000;
                temp_struct_array[i].RNTI = rand() % 10000;
                temp_struct_array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
            }

            // If allocation was successful, set the output array
            *struct_array = temp_struct_array;
            result = SUCCESS;
        }
    }

    if (result != SUCCESS) {
        free(temp_struct_array);
        return result;
    }

    // Signal completion to downstream components or log success
    printf("Data processing completed successfully.\n");

    return result;
}

int main() {
    srand(time(NULL));  // Seed the random number generator

    NFAPI_CRC_INDICATION_PDU_T *structures = NULL;
    ErrorCode_t status = allocate_and_initialize_structures(&structures, 1500);

    if (status != SUCCESS) {
        printf("Function failed with error code: %d\n", status);
    } else {
        // Use structures...
        free(structures);  // Free allocated memory
    }

    return 0;
}
