    array->data = NULL;
    array->size = 0;
    array->capacity = 0;
    pthread_mutex_destroy(&array->lock);
}

int resize_array_if_needed(CriticalFieldArray *array, size_t additional_size) {
    pthread_mutex_lock(&array->lock);

    if (array->size + additional_size > array->capacity) {
        size_t new_capacity = array->capacity * 2;
        while (new_capacity < array->size + additional_size) {
            new_capacity *= 2;
        }

        LTE_RRC_CriticalField_T *new_data = realloc(array->data, new_capacity * sizeof(LTE_RRC_CriticalField_T));
        if (!new_data) {
            pthread_mutex_unlock(&array->lock);
            perror("Failed to reallocate memory");
            return -1;
        }

        array->data = new_data;
        array->capacity = new_capacity;
