#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_ELEMENTS 10000
#define MEMORY_THRESHOLD (10 * 1024 * 1024) // Example threshold in bytes

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Simulated external resource manager for memory pooling
void* pool_alloc(size_t size) {
    return malloc(size);
}

void pool_free(void* ptr) {
    free(ptr);
}

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t count;
} List;

pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to generate a random CRCFLAG
int get_random_crcflag() {
    return rand() % 2; // Randomly returns 0 or 1
}

// Function to populate the list with NFAPI_CRC_INDICATION_PDU_T structures
void populate_list(List* list, unsigned short rnti_min, unsigned short rnti_max) {
    pthread_mutex_lock(&list_mutex);

    size_t element_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (element_size * MAX_ELEMENTS > MEMORY_THRESHOLD) {
        fprintf(stderr, "Memory allocation exceeds threshold\n");
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    list->data = pool_alloc(MAX_ELEMENTS * element_size);
    if (!list->data) {
        fprintf(stderr, "Failed to allocate memory\n");
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    srand(time(NULL));
    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        list->data[i].RX_UE_INFORMATION_TAG = rand() % 10000;
        list->data[i].RNTI = rnti_min + (rand() % (rnti_max - rnti_min + 1));
        if (list->data[i].RNTI < rnti_min || list->data[i].RNTI > rnti_max) {
            fprintf(stderr, "Invalid RNTI value: %u\n", list->data[i].RNTI);
            continue;
        }
        list->data[i].CRC_INDICATION_REL8_TAG.CRCFLAG = get_random_crcflag();
    }

    list->count = MAX_ELEMENTS;

    pthread_mutex_unlock(&list_mutex);
}

// Function to free the list
void free_list(List* list) {
    pthread_mutex_lock(&list_mutex);

    if (list->data) {
        pool_free(list->data);
        list->data = NULL;
    }

    list->count = 0;

    pthread_mutex_unlock(&list_mutex);
}

// Example usage
int main() {
    List my_list = {NULL, 0};

    unsigned short rnti_min = 1000;
    unsigned short rnti_max = 2000;

    populate_list(&my_list, rnti_min, rnti_max);

    // Perform operations with the list...

    free_list(&my_list);

    return 0;
}
