    int configVersion;
    size_t rbgCount;
    ResourceBlockGroupConfig *rbGroups;
} NetworkElementConfig;

// Custom allocator and deallocator for efficient memory management
void* custom_alloc(size_t size) {
    return malloc(size);
}

void custom_free(void *ptr) {
    free(ptr);
}

// Mutex for thread safety
pthread_mutex_t configMutex = PTHREAD_MUTEX_INITIALIZER;

NetworkElementConfig* initNetworkElementConfigs(size_t elementCount, const char **nodeIdentifiers, int version, size_t rbgCounts[], size_t rbCounts[], int freqBands[][100], float powerLevels[][100]) {
    pthread_mutex_lock(&configMutex);

    NetworkElementConfig *configs = (NetworkElementConfig*) custom_alloc(elementCount * sizeof(NetworkElementConfig));
    if (!configs) {
        perror("Failed to allocate memory for NetworkElementConfigs");
        pthread_mutex_unlock(&configMutex);
        return NULL;
    }

    for (size_t i = 0; i < elementCount; ++i) {
        strncpy(configs[i].NodeIdentifier, nodeIdentifiers[i], sizeof(configs[i].NodeIdentifier));
        configs[i].configVersion = version;
        configs[i].rbgCount = rbgCounts[i];

        configs[i].rbGroups = (ResourceBlockGroupConfig*) custom_alloc(rbgsCounts[i] * sizeof(ResourceBlockGroupConfig));
        if (!configs[i].rbGroups) {
            perror("Failed to allocate memory for ResourceBlockGroupConfigs");
            // Free previously allocated resources
            for (size_t j = 0; j < i; ++j) {
                custom_free(configs[j].rbGroups);
            }
            custom_free(configs);
            pthread_mutex_unlock(&configMutex);
            return NULL;
        }

        for (size_t j = 0; j < configs[i].rbgCount; ++j) {
            configs[i].rbGroups[j].count = rbCounts[i * elementCount + j];
            configs[i].rbGroups[j].blocks = (ResourceBlockConfig*) custom_alloc(configs[i].rbGroups[j].count * sizeof(ResourceBlockConfig));
            if (!configs[i].rbGroups[j].blocks) {
                perror("Failed to allocate memory for ResourceBlockConfigs");
                // Free previously allocated resources
                for (size_t k = 0; k < j; ++k) {
                    custom_free(configs[i].rbGroups[k].blocks);
                }
                custom_free(configs[i].rbGroups);
                for (size_t l = 0; l < i; ++l) {
                    custom_free(configs[l].rbGroups);
                }
                custom_free(configs);
                pthread_mutex_unlock(&configMutex);
                return NULL;
            }

            for (size_t k = 0; k < configs[i].rbGroups[j].count; ++k) {
                configs[i].rbGroups[j].blocks[k].frequencyBand = freqBands[i * elementCount + j][k];
                configs[i].rbGroups[j].blocks[k].powerLevel = powerLevels[i * elementCount + j][k];
            }
        }
    }

    pthread_mutex_unlock(&configMutex);
    return configs;
}

void freeNetworkElementConfigs(NetworkElementConfig *configs, size_t elementCount) {
    pthread_mutex_lock(&configMutex);

    if (configs) {
        for (size_t i = 0; i < elementCount; ++i) {
            if (configs[i].rbGroups) {
                for (size_t j = 0; j < configs[i].rbgCount; ++j) {
                    custom_free(configs[i].rbGroups[j].blocks);
                }
                custom_free(configs[i].rbGroups);
            }
        }
        custom_free(configs);
    }

    pthread_mutex_unlock(&configMutex);
}
