    size_t count;
    size_t capacity;
} ConnectionChecks;

void initConnectionChecks(ConnectionChecks *c) {
    c->capacity = 10;
    c->count = 0;
    c->checks = (float *)malloc(c->capacity * sizeof(float));
}

void freeConnectionChecks(ConnectionChecks *c) {
    free(c->checks);
    c->checks = NULL;
    c->count = 0;
    c->capacity = 0;
}

void addCheck(ConnectionChecks *c, float checkValue) {
    if (c->count == c->capacity) {
        c->capacity *= 2;
        c->checks = (float *)realloc(c->checks, c->capacity * sizeof(float));
    }
    c->checks[c->count++] = checkValue;
}

void updateCheck(ConnectionChecks *c, float newCheck) {
    if (c->count < c->capacity) {
        addCheck(c, newCheck);
    } else {
        for (size_t i = 1; i < c->capacity; ++i) {
            c->checks[i - 1] = c->checks[i];
        }
        c->checks[c->capacity - 1] = newCheck;
    }
}

float calculateAverage(ConnectionChecks *c) {
    if (c->count == 0) return 0.0f;

    float sum = 0.0f;
    for (size_t i = 0; i < c->count; ++i) {
        sum += c->checks[i];
    }
    return sum / c->count;
}

float simulateNetworkCheck() {
    // Simulate network check with random fluctuation
    float baseValue = 75.0f; // base health percentage
    float fluctuation = (rand() % 21) - 10.0f; // Random fluctuation between -10 and +10
    return baseValue + fluctuation;
}

void initializeNetworkElementStatus(NetworkElementStatus **array, size_t *size) {
    const int numElements = 5; // Number of network elements to track

    if (*size != 0) { 
        free(*array);
        *array = NULL;
    }

    *array = (NetworkElementStatus *)malloc(numElements * sizeof(NetworkElementStatus));
    *size = numElements;

    for (int i = 0; i < numElements; ++i) {
        (*array)[i].elementId = i + 1;
        (*array)[i].lastUpdateTimestamp = time(NULL);

        ConnectionChecks checks;
        initConnectionChecks(&checks);

        // Simulate adding initial connection checks
        for (int j = 0; j < 10; ++j) {
            float simulatedCheck = simulateNetworkCheck();
            updateCheck(&checks, simulatedCheck);
        }

        (*array)[i].connectionStatus = calculateAverage(&checks);

        freeConnectionChecks(&checks);
    }
}

void cleanupNetworkElementStatus(NetworkElementStatus **array) {
    if (array && *array) {
        free(*array);
        *array = NULL;
    }
}
