#define MAX_NETWORK_ELEMENTS 5000
#define UPDATE_INTERVAL 2 // seconds

typedef struct {
    int elementId;
    time_t lastUpdateTimestamp;
    double connectionStatus;
} NetworkElementStatus;

typedef struct {
    pthread_rwlock_t lock;
    NetworkElementStatus *elements;
    size_t capacity;
    size_t count;
} DynamicNetworkArray;

// Mock function for network health check
double performNetworkHealthCheck(int elementId) {
    // Simulate a network health check with random fluctuation and weighted average logic
    double status = rand() % 100 / 10.0; // Random value between 0.0 and 10.0
    return status;
}

// Log initialization attempts and errors
void logMessage(const char *message) {
    printf("%s\n", message);
}

// Initialize the dynamic array
int initializeNetworkArray(DynamicNetworkArray *array, size_t initialCapacity) {
    pthread_rwlock_init(&array->lock, NULL);

    if (initialCapacity > MAX_NETWORK_ELEMENTS)
        initialCapacity = MAX_NETWORK_ELEMENTS;

    array->elements = malloc(sizeof(NetworkElementStatus) * initialCapacity);
    if (!array->elements) {
        logMessage("Memory allocation failed for network elements.");
        pthread_rwlock_destroy(&array->lock);
        return -1;
    }

    array->capacity = initialCapacity;
    array->count = 0;

    logMessage("Dynamic network array initialized successfully.");
    return 0;
}

// Function to update network element status
void updateNetworkElementStatus(DynamicNetworkArray *array, int elementId) {
    time_t currentTime = time(NULL);

    pthread_rwlock_wrlock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->elements[i].elementId == elementId) {
            double status = performNetworkHealthCheck(elementId);
            array->elements[i].connectionStatus = status;
            array->elements[i].lastUpdateTimestamp = currentTime;

            pthread_rwlock_unlock(&array->lock);
            return;
        }
    }

    if (array->count < array->capacity) {
        array->elements[array->count].elementId = elementId;
        array->elements[array->count].connectionStatus = performNetworkHealthCheck(elementId);
        array->elements[array->count].lastUpdateTimestamp = currentTime;
        ++array->count;
    } else {
        logMessage("Reached maximum capacity of network elements.");
    }

    pthread_rwlock_unlock(&array->lock);
}

// Function to manage updates and handle concurrency
void *manageUpdates(void *arg) {
    DynamicNetworkArray *array = (DynamicNetworkArray *)arg;

    while (1) {
        for (int elementId = 0; elementId < MAX_NETWORK_ELEMENTS; ++elementId) {
            time_t currentTime = time(NULL);
            pthread_rwlock_rdlock(&array->lock);

            for (size_t i = 0; i < array->count; ++i) {
                if ((currentTime - array->elements[i].lastUpdateTimestamp >= UPDATE_INTERVAL) &&
                    (array->elements[i].elementId == elementId)) {

                    updateNetworkElementStatus(array, elementId);
                }
            }

            pthread_rwlock_unlock(&array->lock);
        }

        sleep(UPDATE_INTERVAL);
    }

    return NULL;
}

// Function to free allocated resources
void cleanupDynamicArray(DynamicNetworkArray *array) {
    pthread_rwlock_destroy(&array->lock);
    if (array->elements) {
        free(array->elements);
        array->elements = NULL;
    }
}

int main() {
    DynamicNetworkArray networkArray;
    size_t initialCapacity = 1000;

    if (initializeNetworkArray(&networkArray, initialCapacity) != 0)
        return EXIT_FAILURE;

    pthread_t updateThread;
    if (pthread_create(&updateThread, NULL, manageUpdates, &networkArray) != 0) {
        logMessage("Failed to create update thread.");
        cleanupDynamicArray(&networkArray);
        return EXIT_FAILURE;
    }

    // Join the thread in a real-world application as needed
    pthread_join(updateThread, NULL);

    cleanupDynamicArray(&networkArray);
    return EXIT_SUCCESS;
}
