    double precision_float;
} record;

#define LOGGING_ENABLED 1

#ifdef LOGGING_ENABLED
#define LOG(msg, ...) do { \
    printf("[%s:%d] " msg "\n", __FILE__, __LINE__, ##__VA_ARGS__); \
} while(0)
#else
#define LOG(msg, ...)
#endif

void initialize_data_structures(size_t array_size, int key_range_min, int key_range_max, double max_double_sum) {
    if (array_size < 0 || array_size > SIZE_MAX / sizeof(long) || 
        key_range_min >= key_range_max || max_double_sum <= 0.0) {
        LOG("Invalid input parameters");
        return;
    }

    long *offsets = NULL;
    int *keys = NULL;
    record *records = NULL;

    // Attempt memory allocation with retry mechanism
    void* allocate_memory(size_t size, const char* name) {
        void* ptr = aligned_alloc(64, size);
        if (!ptr) {
            LOG("Allocation failed for %s, retrying...", name);
            ptr = malloc(size);
        }
        return ptr;
    }

    offsets = (long*)allocate_memory(array_size * sizeof(long), "offsets");
    keys = (int*)allocate_memory(array_size * sizeof(int), "keys");
    records = (record*)allocate_memory(array_size * sizeof(record), "records");

    if (!offsets || !keys || !records) {
        LOG("Memory allocation failed, freeing resources...");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Initialize arrays
    for (size_t i = 0; i < array_size; ++i) {
        offsets[i] = i;
        keys[i] = i;

        // Populate records with random values and check double sum constraint
        pthread_mutex_lock(&lock);
        int rand_int = key_range_min + rand() % (key_range_max - key_range_min + 1);
        record r = {rand_int, ((double)rand() / RAND_MAX) * max_double_sum};

        // Check if the current record's double value can be added
        double current_double_sum = 0.0;
        for (size_t j = 0; j <= i; ++j) {
            current_double_sum += records[j].precision_float;
        }

        if (current_double_sum + r.precision_float > max_double_sum) {
            r.precision_float = max_double_sum - current_double_sum;
        }

        records[i] = r;
        pthread_mutex_unlock(&lock);
    }

    // Log resource usage
    LOG("Initialized data structures with array size: %zu", array_size);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
    pthread_mutex_destroy(&lock);
}
