#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PEAK_HISTORY 100

typedef struct {
    double timestamp;
    int usage;
} UsagePeak;

typedef struct ResourceUsageMetrics {
    char resourceId[256];
    time_t lastAccessTimestamp;
    float currentLoadFactor;
    UsagePeak peakUsageHistory[MAX_PEAK_HISTORY];
    size_t numPeaks;
} ResourceUsageMetrics;

ResourceUsageMetrics* find_or_create_metrics(ResourceUsageMetrics** cache, size_t* cache_size, const char* resourceId) {
    for (size_t i = 0; i < *cache_size; ++i) {
        if (strcmp(cache[i]->resourceId, resourceId) == 0) {
            return cache[i];
        }
    }

    ResourceUsageMetrics* new_metrics = malloc(sizeof(ResourceUsageMetrics));
    strcpy(new_metrics->resourceId, resourceId);
    time(&new_metrics->lastAccessTimestamp);
    new_metrics->currentLoadFactor = 0.0;
    new_metrics->numPeaks = 0;

    *cache_size += 1;
    cache = realloc(cache, (*cache_size) * sizeof(ResourceUsageMetrics*));
    cache[*cache_size - 1] = new_metrics;

    return new_metrics;
}

void update_usage_metric(ResourceUsageMetrics** cache, size_t cache_size, const char* resourceId, float loadFactor, int usage) {
    ResourceUsageMetrics* metrics = find_or_create_metrics(cache, &cache_size, resourceId);

    // Update current load factor
    metrics->currentLoadFactor = loadFactor;

    // Update last access timestamp
    time(&metrics->lastAccessTimestamp);

    // Add new usage peak and maintain rolling window
    UsagePeak new_peak = { (double)time(NULL), usage };
    if (metrics->numPeaks < MAX_PEAK_HISTORY || usage > metrics->peakUsageHistory[0].usage) {
        size_t i;
        for (i = metrics->numPeaks; i > 0 && metrics->peakUsageHistory[i-1].usage < usage; --i) {
            metrics->peakUsageHistory[i] = metrics->peakUsageHistory[i-1];
        }
        if (metrics->numPeaks < MAX_PEAK_HISTORY) {
            metrics->numPeaks += 1;
        } else {
            // Shift all entries one position to the left
            for (size_t j = 0; j < MAX_PEAK_HISTORY - 1; ++j) {
                metrics->peakUsageHistory[j] = metrics->peakUsageHistory[j + 1];
            }
        }
        metrics->peakUsageHistory[i] = new_peak;
    }

    // Remove outdated entries beyond one month
    time_t now = time(NULL);
    for (size_t i = 0; i < metrics->numPeaks && (now - metrics->peakUsageHistory[i].timestamp) > 30*24*60*60; ++i) {
        for (size_t j = i; j < metrics->numPeaks - 1; ++j) {
            metrics->peakUsageHistory[j] = metrics->peakUsageHistory[j + 1];
        }
        metrics->numPeaks -= 1;
    }
}

void free_cache(ResourceUsageMetrics** cache, size_t cache_size) {
    for (size_t i = 0; i < cache_size; ++i) {
        free(cache[i]);
    }
    free(cache);
}

int main() {
    ResourceUsageMetrics* cache = NULL;
    size_t cache_size = 0;

    // Example usage
    update_usage_metric(&cache, cache_size, "resource-1", 0.75, 500);
    update_usage_metric(&cache, cache_size, "resource-2", 0.60, 300);

    free_cache(cache, cache_size);

    return 0;
}
```

