#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

#define MAX_HISTORY 100

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint32_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* history[MAX_HISTORY];
    int index;
    pthread_mutex_t lock;
} RollingHistory;

// Function to initialize a new structure with valid values
void init_structure(NFAPI_CRC_INDICATION_PDU_T *structure) {
    if (structure == NULL) return;
    structure->RX_UE_INFORMATION_TAG = rand() % 65536; // Simulating valid tag
    structure->RNTI = rand() % 65536; // Simulating valid RNTI
    structure->CRC_INDICATION_REL8_TAG = rand() % 256; // Simulating valid CRC Tag
    structure->CRCFLAG = rand() % 10000; // Random CRCFLAG within range
}

// Function to add new entry with thread-safe mechanism
void add_to_rolling_history(RollingHistory *rollingHistory, NFAPI_CRC_INDICATION_PDU_T *newEntry) {
    pthread_mutex_lock(&rollingHistory->lock);
    if (rollingHistory->index < MAX_HISTORY) {
        rollingHistory->history[rollingHistory->index] = newEntry;
        rollingHistory->index++;
    } else {
        free(rollingHistory->history[0]);
        memmove(rollingHistory->history, rollingHistory->history + 1, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (MAX_HISTORY - 1));
        rollingHistory->history[MAX_HISTORY - 1] = newEntry;
    }
    pthread_mutex_unlock(&rollingHistory->lock);
}

// Function to validate and prevent duplicates in history
int validate_and_add(RollingHistory *rollingHistory, NFAPI_CRC_INDICATION_PDU_T *newEntry) {
    for (int i = 0; i < rollingHistory->index; ++i) {
        if (rollingHistory->history[i]->RNTI == newEntry->RNTI) return 0; // Duplicate RNTI found
    }
    add_to_rolling_history(rollingHistory, newEntry);
    return 1;
}

// Function to initialize the rolling history structure
void init_rolling_history(RollingHistory *rollingHistory) {
    rollingHistory->index = 0;
    memset(rollingHistory->history, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * MAX_HISTORY);
    pthread_mutex_init(&rollingHistory->lock, NULL);
}

// Function to destroy the rolling history structure and free memory
void destroy_rolling_history(RollingHistory *rollingHistory) {
    for (int i = 0; i < rollingHistory->index; ++i) {
        if (rollingHistory->history[i] != NULL)
            free(rollingHistory->history[i]);
    }
    pthread_mutex_destroy(&rollingHistory->lock);
}

// Function to dynamically manage a rolling history of up to 100 instances
NFAPI_CRC_INDICATION_PDU_T* create_and_manage_history(int N) {
    if (N <= 0 || N > MAX_HISTORY) return NULL;

    RollingHistory rollingHistory;
    init_rolling_history(&rollingHistory);

    for (int i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *newEntry = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (newEntry == NULL) {
            destroy_rolling_history(&rollingHistory);
            return NULL;
        }
        init_structure(newEntry);
        if (!validate_and_add(&rollingHistory, newEntry)) {
            free(newEntry); // If not added due to duplicate RNTI
        }
    }

    // Simulate usage
    for (int i = 0; i < rollingHistory.index; ++i) {
        printf("RNTI: %u\n", rollingHistory.history[i]->RNTI);
    }

    destroy_rolling_history(&rollingHistory);

    return NULL;
}

int main() {
    srand(time(NULL)); // Seed for random number generation
    create_and_manage_history(50); // Example usage with N = 50
    return 0;
}
```

This implementation ensures that the rolling history of `NFAPI_CRC_INDICATION_PDU_T` structures is managed dynamically, thread-safely, and efficiently. The mutex lock provides a straightforward mechanism to handle concurrent updates without race conditions. Memory allocation failures are handled gracefully by freeing any previously allocated memory before exiting. By validating and preventing duplicate RNTI values, the implementation maintains data integrity while minimizing overhead in high-throughput scenarios.']

