```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_STRUCTURES 50000
#define MEMORY_LIMIT_PER_10000 2 * 1024 * 1024

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t count;
} List;

void init_list(List* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
}

int validate_rnti(const List* list, uint16_t rnti) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            pthread_mutex_unlock(&list->lock);
            return 1; // Duplicate found
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return 0; // No duplicate
}

void add_pdu(List* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (validate_rnti(list, pdu.RNTI)) {
        printf("Warning: Duplicate RNTI detected: %u\n", pdu.RNTI);
        return;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory");
        return;
    }
    new_node->data = pdu;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    list->count++;
    pthread_mutex_unlock(&list->lock);
}

void serialize_list(const List* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);

    fclose(file);
}

void free_list(List* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    list->count = 0;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int main() {
    List pdu_list;
    init_list(&pdu_list);

    // Example usage
    for (int i = 0; i < MAX_STRUCTURES; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = {
            .RX_UE_INFORMATION_TAG = rand(),
            .RNTI = rand() % 65536,
            .CRC_INDICATION_REL8_TAG = rand() & 0xFF,
            .CRCFLAG = rand() & 1
        };
        add_pdu(&pdu_list, pdu);
    }

    serialize_list(&pdu_list, "pdu_data.bin");
    free_list(&pdu_list);

    return 0;
}
```

### Key Points:
- **Thread Safety**: The list operations are protected by a mutex to ensure thread safety.
- **Memory Management**: The code dynamically allocates memory for each node and ensures proper cleanup.
- **Uniqueness Check**: Before adding a structure, it checks for duplicate RNTI values.
- **Serialization**: Structures are serialized to a binary file for persistence.
- **Resource Constraints**: Designed with a focus on minimizing memory usage per 10,000 structures.']

