        log_message("Error: Requested frames exceed maximum allowed");
        return NULL;
    }

    pthread_mutex_lock(&lock);

    NFAPI_RX_FRAME_INFO* frames = malloc(num_frames * sizeof(NFAPI_RX_FRAME_INFO));
    if (!frames) {
        *error_code = -2; // Memory allocation failed
        log_message("Error: Memory allocation failed");
        pthread_mutex_unlock(&lock);
        return NULL;
