// Assuming NFAPI_RX_FRAME_INFO and RX_FRAME_INFO are defined somewhere
typedef struct {
    uint16_t rnti;
    bool CRC_FLAG;
} RX_FRAME_INFO;

typedef struct {
    RX_FRAME_INFO info;
    // Other fields...
} NFAPI_RX_FRAME_INFO;

// Mock function to get RNTI from an external source or local cache
uint16_t get_rnti_from_external_source() {
    static uint16_t rnti_cache = 0;
    // Simulate delay and failure
    if (rand() % 10 < 2) { // 20% chance of failure
        return 0; // Indicate failure
    }
    rnti_cache += rand() % 100 + 1; // Increment for uniqueness
    return rnti_cache;
}

// Initialize dynamic array of NFAPI_RX_FRAME_INFO structures
NFAPI_RX_FRAME_INFO* initialize_dynamic_array(size_t num_frames) {
    if (num_frames == 0) return NULL;

    NFAPI_RX_FRAME_INFO *frames = malloc(num_frames * sizeof(NFAPI_RX_FRAME_INFO));
    if (!frames) {
        fprintf(stderr, "Memory allocation failed for frames\n");
        return NULL;
    }

    srand(time(NULL)); // Seed random number generator

    for (size_t i = 0; i < num_frames; ++i) {
        uint16_t rnti = get_rnti_from_external_source();

        if (!rnti) {
            fprintf(stderr, "Failed to retrieve RNTI from external source, using cached value\n");
            // Use a fallback strategy with local cache
            static uint16_t local_cache = 1000;
            rnti = local_cache++;
        }

        frames[i].info.rnti = rnti;
        frames[i].info.CRC_FLAG = (rand() % 2 == 0); // Probabilistic model

        // Simulate prefetching and loop unrolling
        if ((i + 1) < num_frames) {
            frames[i + 1].info.rnti = get_rnti_from_external_source();
            if (!frames[i + 1].info.rnti) {
                fprintf(stderr, "Failed to retrieve RNTI from external source for frame %zu\n", i + 1);
                frames[i + 1].info.rnti = local_cache++;
            }
            frames[i + 1].info.CRC_FLAG = (rand() % 2 == 0);
        }
    }

    return frames;
}

// Function to free allocated memory
void free_dynamic_array(NFAPI_RX_FRAME_INFO *frames) {
    if (frames) {
        free(frames);
    }
}
