} NFAPI_RX_INDICATION_PDU;

typedef struct {
    NFAPI_RX_INDICATION_PDU pdu;
    // Add UE-specific parameters here
} NFAPI_MESSAGE_PDU_T;

#define INITIAL_CACHE_SIZE 10

// Structure to manage the dynamic collection
typedef struct {
    NFAPI_MESSAGE_PDU_T* cache;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} MessagePduCollection;

// Function prototypes
MessagePduCollection* initialize_collection(size_t max_concurrent_instances);
int configure_collection(MessagePduCollection* collection, size_t new_capacity);
void free_collection(MessagePduCollection* collection);

MessagePduCollection* initialize_collection(size_t max_concurrent_instances) {
    MessagePduCollection* collection = (MessagePduCollection*)malloc(sizeof(MessagePduCollection));
    if (!collection) {
        fprintf(stderr, "Memory allocation failed for MessagePduCollection.\n");
        return NULL;
    }

    collection->capacity = INITIAL_CACHE_SIZE;
    collection->count = 0;
    collection->cache = (NFAPI_MESSAGE_PDU_T*)malloc(collection->capacity * sizeof(NFAPI_MESSAGE_PDU_T));
    if (!collection->cache) {
        fprintf(stderr, "Memory allocation failed for NFAPI_MESSAGE_PDU_T cache.\n");
        free(collection);
        return NULL;
    }

    pthread_mutex_init(&collection->mutex, NULL);
    pthread_cond_init(&collection->cond, NULL);

    return collection;
}

int configure_collection(MessagePduCollection* collection, size_t new_capacity) {
    if (!collection) return -1;

    pthread_mutex_lock(&collection->mutex);

    NFAPI_MESSAGE_PDU_T* new_cache = (NFAPI_MESSAGE_PDU_T*)realloc(collection->cache, new_capacity * sizeof(NFAPI_MESSAGE_PDU_T));
    if (!new_cache) {
        fprintf(stderr, "Memory reallocation failed for NFAPI_MESSAGE_PDU_T cache.\n");
        pthread_mutex_unlock(&collection->mutex);
        return -1;
    }

    collection->cache = new_cache;
    collection->capacity = new_capacity;

    pthread_mutex_unlock(&collection->mutex);

    return 0; // Success
}

void free_collection(MessagePduCollection* collection) {
    if (collection) {
        pthread_mutex_lock(&collection->mutex);

        free(collection->cache);
        collection->cache = NULL;
        collection->capacity = 0;
        collection->count = 0;

        pthread_mutex_unlock(&collection->mutex);

        pthread_mutex_destroy(&collection->mutex);
        pthread_cond_destroy(&collection->cond);
        free(collection);
    }
}

int add_pdu_to_collection(MessagePduCollection* collection, NFAPI_MESSAGE_PDU_T pdu) {
    if (!collection) return -1;

    pthread_mutex_lock(&collection->mutex);

    while (collection->count >= collection->capacity) {
        // Wait for space to be available
        pthread_cond_wait(&collection->cond, &collection->mutex);
    }

    collection->cache[collection->count++] = pdu;
    pthread_cond_signal(&collection->cond);

    pthread_mutex_unlock(&collection->mutex);

    return 0; // Success
}

int main() {
    size_t max_instances = 100; // Example value for M

    MessagePduCollection* collection = initialize_collection(max_instances);
    if (!collection) return -1;

    NFAPI_MESSAGE_PDU_T pdu;
    // Initialize pdu and other fields here

    int result = add_pdu_to_collection(collection, pdu);
    if (result != 0) {
        fprintf(stderr, "Failed to add PDU to collection.\n");
    }

    configure_collection(collection, max_instances * 2); // Example for resizing the cache

    free_collection(collection);

    return 0;
}
```

