#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    struct {
        unsigned char CRCFLAG: 1; // Using bit field for CRCFLAG
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock; // Mutex for thread synchronization
} DoublyLinkedList;

void init_list(DoublyLinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

int is_rnti_duplicate(DoublyLinkedList* list, unsigned short rnti) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            return 1; // Duplicate found
        }
        current = current->next;
    }
    return 0; // No duplicates
}

void add_node(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);

    if (is_rnti_duplicate(list, data.RNTI)) {
        fprintf(stderr, "Duplicate RNTI: %u\n", data.RNTI);
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for new node");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->data = data;
    new_node->prev = NULL;
    new_node->next = list->head;

    if (list->head != NULL) {
        list->head->prev = new_node;
    }

    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
}

void free_list(DoublyLinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_destroy(&list->lock);
}

void populate_list(DoublyLinkedList* list, int num_elements) {
    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < num_elements; ++i) {
        NFAPI_CRC_INDICATION_PDU_T data;
        data.RX_UE_INFORMATION_TAG = rand(); // Unique tag
        do {
            data.RNTI = (unsigned short)(rand() % UINT16_MAX + 1); // Non-zero RNTI
        } while (is_rnti_duplicate(list, data.RNTI));

        data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 0x01; // Random CRCFLAG

        add_node(list, data);
    }
}

int main() {
    DoublyLinkedList list;
    init_list(&list);

    int num_elements = 1000; // Example number of elements
    populate_list(&list, num_elements);

    // Free the list after usage
    free_list(&list);

    return 0;
}
```

### Key Points:
