pthread_mutex_t nfa_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to simulate external RNTI assignment (mockup)
int assign_rnti_from_external_source(unsigned int *rnti) {
    // Simulate network delay or failure
    if ((rand() % 10) == 0) { // 10% chance of failure
        return -1; // Failure in obtaining RNTI
    }
    *rnti = rand(); // Assign a random RNTI for simplicity
    return 0;
}

// Function to create and populate the list with NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_nfa_list(size_t *num_elements) {
    if (num_elements == NULL || (*num_elements > MAX_ELEMENTS)) {
        fprintf(stderr, "Error: Number of elements must be positive and <= %d\n", MAX_ELEMENTS);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* nfa_list = malloc(*num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (nfa_list == NULL) {
        fprintf(stderr, "Error: Memory allocation failed for NFA list\n");
        return NULL;
    }

    unsigned int rnti_set[MAX_ELEMENTS] = {0};
    pthread_mutex_lock(&nfa_mutex);

    for (size_t i = 0; i < *num_elements; ++i) {
        unsigned int rx_ue_tag = rand(); // Simulate RX_UE_INFORMATION_TAG
        unsigned int crc_rel8_tag = rand(); // Simulate CRC_INDICATION_REL8_TAG
        unsigned int rnti;

        if (assign_rnti_from_external_source(&rnti) != 0) {
            fprintf(stderr, "Error: Failed to assign RNTI from external source for element %zu\n", i);
            pthread_mutex_unlock(&nfa_mutex);
            free(nfa_list);
            return NULL;
        }

        // Ensure uniqueness of RNTI
        int unique_rnti = 1;
        for (size_t j = 0; j < *num_elements && rnti_set[j] != 0; ++j) {
            if (rnti_set[j] == rnti) {
                fprintf(stderr, "Error: Duplicate RNTI %u found at element %zu\n", rnti, i);
                unique_rnti = 0;
                break;
            }
        }

        if (!unique_rnti) {
            pthread_mutex_unlock(&nfa_mutex);
            free(nfa_list);
            return NULL;
        }

        rnti_set[i] = rnti;

        nfa_list[i].RX_UE_INFORMATION_TAG = rx_ue_tag;
        nfa_list[i].RNTI = rnti;
        nfa_list[i].CRC_INDICATION_REL8_TAG = crc_rel8_tag;

        // Allocate additional CRC-related data buffer
        size_t data_size = rand() % 1024; // Simulate varying data sizes up to 1KB
        nfa_list[i].additional_crc_data = malloc(data_size);
        if (nfa_list[i].additional_crc_data == NULL) {
            fprintf(stderr, "Error: Memory allocation failed for additional CRC data at element %zu\n", i);
            pthread_mutex_unlock(&nfa_mutex);

            // Free previously allocated memory
            for (size_t k = 0; k < i; ++k) {
                free(nfa_list[k].additional_crc_data);
            }
            free(nfa_list);
            return NULL;
        }

        // Optionally initialize the buffer with some data
        memset(nfa_list[i].additional_crc_data, 0xAA, data_size); // Example initialization pattern
    }

    pthread_mutex_unlock(&nfa_mutex);
    return nfa_list;
}

// Function to free allocated resources for NFA list
void free_nfa_list(NFAPI_CRC_INDICATION_PDU_T *nfa_list, size_t num_elements) {
    if (nfa_list == NULL)
        return;

    for (size_t i = 0; i < num_elements; ++i) {
        if (nfa_list[i].additional_crc_data != NULL) {
            free(nfa_list[i].additional_crc_data);
        }
    }

    free(nfa_list);
}
