using System;
using System.Collections.Concurrent;
using System.Text.RegularExpressions;

public class HtmlContentUpdater
{
    private readonly ConcurrentDictionary<string, string> htmlCache;

    public HtmlContentUpdater()
    {
        htmlCache = new ConcurrentDictionary<string, string>();
    }

    public void UpdateHtmlContent(string sectionId, string elementId, string content)
    {
        if (string.IsNullOrEmpty(sectionId) || string.IsNullOrEmpty(elementId))
            throw new ArgumentException("Section ID and Element ID cannot be null or empty.");

        // Sanitize content to prevent XSS
        var sanitizedContent = Regex.Replace(content, @"<[^>]*>", string.Empty);

        // Simulating HTML element update with caching mechanism
        string key = $"{sectionId}:{elementId}";
        htmlCache.AddOrUpdate(key, sanitizedContent, (k, existingValue) => sanitizedContent);
    }

    public string GetHtmlContent(string sectionId, string elementId)
    {
        if (string.IsNullOrEmpty(sectionId) || string.IsNullOrEmpty(elementId))
            throw new ArgumentException("Section ID and Element ID cannot be null or empty.");

        return htmlCache.GetOrAdd($"{sectionId}:{elementId}", k => "");
    }
}

// Usage example
public class Program
{
    public static void Main()
    {
        var updater = new HtmlContentUpdater();
        updater.UpdateHtmlContent("header", "title", "<h1>Hello, World!</h1>");
        string content = updater.GetHtmlContent("header", "title");

        Console.WriteLine(content); // Outputs: Hello, World!
    }
}
