    if (!new_node) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    new_node->data = pdu;
    new_node->next = manager->head;
    new_node->prev = NULL;

    if (manager->head) manager->head->prev = new_node;
    manager->head = new_node;
    manager->allocated_memory += sizeof(Node);

    pthread_mutex_unlock(&manager->lock);
    return 1; // Success
