```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>

#define MAX_RNTI 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t size;
    pthread_mutex_t lock;
    uint8_t RNTI_bitmap[MAX_RNTI / 32 + 1];
} DynamicList;

DynamicList* create_list(size_t max_elements) {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    for (int i = 0; i < MAX_RNTI / 32 + 1; ++i) {
        list->RNTI_bitmap[i] = 0;
    }
    return list;
}

int is_rnti_unique(DynamicList* list, int rnti) {
    size_t index = rnti / 32;
    size_t bit_pos = rnti % 32;
    return !(list->RNTI_bitmap[index] & (1 << bit_pos));
}

void set_rnti_bit(DynamicList* list, int rnti) {
    size_t index = rnti / 32;
    size_t bit_pos = rnti % 32;
    list->RNTI_bitmap[index] |= (1 << bit_pos);
}

void clear_oldest_rnti(DynamicList* list) {
    if (!list->head) return;
    Node* oldest = list->head;
    int rnti_to_clear = oldest->data.RNTI;
    list->head = list->head->next;
    if (list->head == NULL) {
        list->tail = NULL;
    }
    free(oldest);
    size_t index = rnti_to_clear / 32;
    size_t bit_pos = rnti_to_clear % 32;
    list->RNTI_bitmap[index] &= ~(1 << bit_pos);
}

void add_node(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);

    if (!is_rnti_unique(list, data.RNTI)) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->data = data;
    set_rnti_bit(list, data.RNTI);

    new_node->next = NULL;
    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;
    list->size++;

    // Periodic cleanup
    if (list->size > MAX_ELEMENTS) {
        clear_oldest_rnti(list);
    }

    pthread_mutex_unlock(&list->lock);
}

void destroy_list(DynamicList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

size_t get_list_size(DynamicList* list) {
    pthread_mutex_lock(&list->lock);
    size_t size = list->size;
    pthread_mutex_unlock(&list->lock);
    return size;
}
```

### Explanation:

- **Dynamic List Management**: The `DynamicList` structure maintains a linked list with head and tail pointers, a bitmap for tracking unique RNTIs, and a mutex lock for thread safety.
- **Unique RNTI Check**: Uses a bitmap to efficiently check if an RNTI is already present in constant time.
- **Thread Safety**: A mutex (`pthread_mutex_t`) ensures that the list operations are thread-safe.
- **Periodic Cleanup**: When adding a new node, it checks if the size exceeds `MAX_ELEMENTS` and removes the oldest element if necessary.
- **Resource Management**: Properly allocates and frees memory to avoid leaks. The mutex is initialized and destroyed as needed.

This implementation assumes `MAX_ELEMENTS` is defined elsewhere in your code, representing the maximum number of elements you wish to retain in the list at any time. Adjustments may be required based on specific requirements or constraints.']

