    printf("[%s] %s\n", ctime(&now), message);
}

// Function to dynamically resize the array
int dynamic_resize(DynamicArray *arr) {
    pthread_mutex_lock(&arr->lock);

    size_t new_size = arr->size + INCREMENT_SIZE;
    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(arr->array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!new_array) {
        log_message("Allocation failed during resizing.");
        pthread_mutex_unlock(&arr->lock);
        return -1;
    }

    arr->array = new_array;
    arr->size = new_size;

    pthread_mutex_unlock(&arr->lock);
    log_message("Array resized successfully.");
    return 0;
}

// Function to add an element
int add_element(DynamicArray *arr, NFAPI_CRC_INDICATION_PDU_T element) {
    if (arr->used == arr->size) {
        if (dynamic_resize(arr) != 0) {
            log_message("Failed to resize array.");
            return -1;
        }
    }

    pthread_mutex_lock(&arr->lock);

    arr->array[arr->used++] = element;

    pthread_mutex_unlock(&arr->lock);

    return 0;
}

// Function for sorting
int compare_elements(const void *a, const void *b) {
    NFAPI_CRC_INDICATION_PDU_T *elem_a = (NFAPI_CRC_INDICATION_PDU_T *) a;
    NFAPI_CRC_INDICATION_PDU_T *elem_b = (NFAPI_CRC_INDICATION_PDU_T *) b;

    if (elem_a->RNTI < elem_b->RNTI) return -1;
    if (elem_a->RNTI > elem_b->RNTI) return 1;
    return 0;
}

// Export to file
int export_to_file(const DynamicArray *arr, const char *filename) {
    FILE *file = fopen(filename, "wb");

    if (!file) {
        log_message("Failed to open file for writing.");
        return -1;
    }

    pthread_mutex_lock(&arr->lock);

    fwrite(arr->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), arr->used, file);

    pthread_mutex_unlock(&arr->lock);

    fclose(file);

    log_message("Data exported to file successfully.");

    return 0;
}

// Function for LRU Cache
LRUCache* create_cache(size_t capacity) {
    LRUCache *cache = malloc(sizeof(LRUCache));
    cache->head = NULL;
    cache->tail = NULL;
    cache->count = 0;
    cache->capacity = capacity;
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

void add_to_cache(LRUCache *cache, unsigned int RNTI, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&cache->lock);

    // Check if element is already in the cache
    CacheNode *current = cache->head;
    while (current != NULL) {
        if (current->RNTI == RNTI) {
            current->data = data;
            if (current != cache->head) {
                current->prev->next = current->next;
                current->next->prev = current->prev;

                // Move to head
                current->next = cache->head;
                current->prev = NULL;
                cache->head->prev = current;
                cache->head = current;
            }
            pthread_mutex_unlock(&cache->lock);
            return;
        }
        current = current->next;
    }

    if (cache->count == cache->capacity) {
        // Remove the tail
        CacheNode *tail = cache->tail;
        cache->tail = tail->prev;

        if (cache->tail != NULL)
            cache->tail->next = NULL;

        free(tail);
        cache->count--;
    }

    // Add new node to head
    CacheNode *new_node = malloc(sizeof(CacheNode));
    new_node->RNTI = RNTI;
    new_node->data = data;

    if (cache->head == NULL) {
        cache->head = new_node;
        cache->tail = new_node;
    } else {
        new_node->next = cache->head;
        cache->head->prev = new_node;
        cache->head = new_node;
    }

    cache->count++;
    pthread_mutex_unlock(&cache->lock);
}

