    srand(time(NULL));
    DynamicArrayManager* manager = create_manager(10);

    if (!manager) {
        fprintf(stderr, "Failed to initialize the dynamic array manager\n");
        return 1;
    }

    pthread_t threads[MAX_ELEMENTS];
    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        if (pthread_create(&threads[i], NULL, thread_function, manager) != 0) {
            fprintf(stderr, "Failed to create thread %zu\n", i);
            break;
        }
    }

    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        pthread_join(threads[i], NULL);
    }

    log_operation("Final successful allocations: %zu", manager->successful_allocations);
    log_operation("Final failed allocations: %zu", manager->failed_allocations);

    destroy_manager(manager);
    return 0;
}
