#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ELEMENTS 10000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG crc_tag;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct List {
    Node* head;
    size_t count;
    pthread_mutex_t lock;  // Mutex for thread safety
} List;

List create_list() {
    List list = {NULL, 0};
    pthread_mutex_init(&list.lock, NULL);
    return list;
}

void destroy_list(List* list) {
    pthread_mutex_lock(&list->lock);
    Node *current = list->head, *next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    list->count = 0;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

void add_element(List* list, NFAPI_CRC_INDICATION_PDU_T element) {
    Node *new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return;

    new_node->data = element;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);

    if (list->head == NULL || list->count < MAX_ELEMENTS) {
        new_node->next = list->head;
        list->head = new_node;
        list->count++;
    }

    pthread_mutex_unlock(&list->lock);
}

void remove_element(List* list, uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current != NULL) {
        if (current->data.crc_tag.RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG &&
            current->data.crc_tag.RNTI == RNTI) {

            if (prev == NULL) { // Removing head
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            list->count--;
            break;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T* find_element(List* list, uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current != NULL) {
        if (current->data.crc_tag.RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG &&
            current->data.crc_tag.RNTI == RNTI) {

            pthread_mutex_unlock(&list->lock);
            return &current->data;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

// Example usage
int main() {
    List list = create_list();

    NFAPI_CRC_INDICATION_PDU_T pdu = {
        { .RX_UE_INFORMATION_TAG = 1, .RNTI = 100 },
        rand() % 2 // Randomly set CRCFLAG (0 or 1)
    };

    add_element(&list, pdu);
    NFAPI_CRC_INDICATION_PDU_T* found_pdu = find_element(&list, 1, 100);

    if (found_pdu) {
        printf("Found PDU with CRCFLAG: %d\n", found_pdu->CRCFLAG);
    }

    remove_element(&list, 1, 100);

    destroy_list(&list);
    return 0;
}
```

### Key Design Decisions:
