unsigned char used_crcflags[8] = {0};  // CRCFLAG is assumed to be an 8-bit flag for this example.

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_list(int N) {
    if (N > MAX_N || N < 1) return NULL;

    srand(time(NULL));
