    NFAPI_CRC_INDICATION_PDU_T** current = &head;

    for (int i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) {
            log_message(LOG_LEVEL_ERROR, "Memory allocation failed.");
            // Free any previously allocated nodes
            while (head != NULL) {
                NFAPI_CRC_INDICATION_PDU_T* temp = head;
                head = head->next;
                free(temp);
            }
            return NULL;
        }

        new_node->RX_UE_INFORMATION_TAG = rand();  // Assuming valid generation logic

        unsigned int rnti = rand() % (RNTI_MAX - RNTI_MIN + 1) + RNTI_MIN;
        if (rnti < RNTI_MIN || rnti > RNTI_MAX) {
            log_message(LOG_LEVEL_ERROR, "Invalid RNTI value generated.");
            free(new_node);
            continue; // Skip invalid RNTI
        }
        new_node->RNTI = rnti;

        unsigned char crcflag;
        do {
            pthread_mutex_lock(&crcflag_lock);
            crcflag = rand() % 8 + 1;
            if (used_crcflags[crcflag]) {
                pthread_mutex_unlock(&crcflag_lock);
                continue; // Retry
            }
            used_crcflags[crcflag] = 1;
            pthread_mutex_unlock(&crcflag_lock);
        } while (0);

        new_node->CRC_INDICATION_REL8_TAG.CRCFLAG = crcflag;

        log_message(current_log_level, "Added structure with CRCFLAG: %d at %s",
                    crcflag, ctime((time_t*)&new_node));

        *current = new_node;
        current = &new_node->next;  // Move to the next pointer for potential next allocation
    }

    return head;
}

void set_log_level(LogLevel level) {
    pthread_mutex_lock(&crcflag_lock);
    current_log_level = level;
    pthread_mutex_unlock(&crcflag_lock);
}
