#include <stdint.h>
#include <pthread.h>
#include <stdbool.h>

#define MAX_HISTORY 100

typedef struct {
    uint8_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crcTag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t size;
    pthread_mutex_t lock;
} Queue;

void initQueue(Queue* q) {
    q->head = q->tail = NULL;
    q->size = 0;
    pthread_mutex_init(&q->lock, NULL);
}

bool isDuplicateRNTI(const Queue* q, uint16_t rnti) {
    Node* current = q->head;
    while (current) {
        if (current->data.RNTI == rnti) return true;
        current = current->next;
    }
    return false;
}

void adjustCRCFlag(uint8_t* prevFlag, uint8_t* newFlag) {
    *newFlag = (*prevFlag + 1) % 2; // Toggle between 0 and 1
}

bool enqueue(Queue* q, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&q->lock);

    if (isDuplicateRNTI(q, pdu->RNTI)) {
        pthread_mutex_unlock(&q->lock);
        return false;
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&q->lock);
        fprintf(stderr, "Memory allocation failed\n");
        return false;
    }

    *newNode = (Node){ .data = *pdu, .next = NULL };

    if (q->tail) {
        q->tail->next = newNode;
    } else {
        q->head = newNode;
    }

    q->tail = newNode;

    if (++q->size > MAX_HISTORY) {
        Node* temp = q->head;
        q->head = q->head->next;
        free(temp);
        --q->size;
    }

    pthread_mutex_unlock(&q->lock);
    return true;
}

void dequeue(Queue* q, NFAPI_CRC_INDICATION_PDU_T** pdu) {
    pthread_mutex_lock(&q->lock);

    if (!q->head) {
        pthread_mutex_unlock(&q->lock);
        *pdu = NULL;
        return;
    }

    Node* temp = q->head;
    *pdu = &temp->data;

    q->head = q->head->next;
    if (!q->head) {
        q->tail = NULL;
    }

    free(temp);
    --q->size;

    pthread_mutex_unlock(&q->lock);
}

void destroyQueue(Queue* q) {
    Node* current = q->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&q->lock);
}

NFAPI_CRC_INDICATION_PDU_T* fetchDataFromExternalSource() {
    // Simulate external data fetching
    static uint8_t prevFlag = 0; 
    NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = rand(), .RNTI = rand() % 1024, .crcTag = {prevFlag} };

    adjustCRCFlag(&pdu.crcTag.CRCFLAG, &pdu.crcTag.CRCFLAG);
    prevFlag = pdu.crcTag.CRCFLAG;

    return &pdu;
}

void* processQueue(void* arg) {
    Queue* q = (Queue*)arg;

    while (1) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = fetchDataFromExternalSource();
        if (!enqueue(q, pdu)) {
            continue; // Handle enqueue failure
        }

        NFAPI_CRC_INDICATION_PDU_T* dequeuedPdu;
        dequeue(q, &dequeuedPdu);

        // Process dequeuedPdu if needed
    }

    return NULL;
}

int main() {
    Queue queue;
    initQueue(&queue);

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, processQueue, &queue);

    // Simulation running... In real code, handle thread join and proper exit

    destroyQueue(&queue);
    return 0;
}
