// Network Interface Configuration class
class NICConfig {
public:
    NICConfig(const std::string& ipAddress, const std::string& macAddress)
        : ip(ipAddress), mac(macAddress) {}

    std::string getIPAddress() const { return ip; }
    std::string getMACAddress() const { return mac; }

private:
    std::string ip;
    std::string mac;
};

// Function to simulate validation with external server
bool validateWithExternalServer(const NICConfig& config) {
    // Simulate network delay and occasional failure
    std::this_thread::sleep_for(std::chrono::milliseconds(100));
    return true; // Assume validation is successful for demonstration purposes
}

class NICManager {
public:
    bool addNICConfig(const NICConfig& config) {
        if (validateWithExternalServer(config)) {
            std::unique_lock<std::shared_mutex> lock(mutex_);
            auto result = configs_.emplace(config.getIPAddress(), config);
            return result.second; // Returns true if insertion took place
        }
        return false;
    }

    bool updateNICConfig(const std::string& ipAddress, const NICConfig& newConfig) {
        if (validateWithExternalServer(newConfig)) {
            std::unique_lock<std::shared_mutex> lock(mutex_);
            auto it = configs_.find(ipAddress);
            if (it != configs_.end()) {
                it->second = newConfig;
                return true;
            }
        }
        return false;
    }

    bool getNICConfig(const std::string& ipAddress, NICConfig& config) const {
        std::shared_lock<std::shared_mutex> lock(mutex_);
        auto it = configs_.find(ipAddress);
        if (it != configs_.end()) {
            config = it->second;
            return true;
        }
        return false;
    }

private:
    mutable std::shared_mutex mutex_;
    std::unordered_map<std::string, NICConfig> configs_;
};

int main() {
    NICManager manager;

    // Example usage
    NICConfig nic1("192.168.0.1", "AA:BB:CC:DD:EE:FF");
    if (manager.addNICConfig(nic1)) {
        std::cout << "NIC added successfully.\n";
    }

    NICConfig retrievedNic;
    if (manager.getNICConfig("192.168.0.1", retrievedNic)) {
        std::cout << "Retrieved NIC MAC: " << retrievedNic.getMACAddress() << "\n";
    }

    NICConfig updatedNic("192.168.0.1", "11:22:33:44:55:66");
    if (manager.updateNICConfig("192.168.0.1", updatedNic)) {
        std::cout << "NIC updated successfully.\n";
    }

    return 0;
}
