#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_LIST_SIZE 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list;
    size_t size;
    pthread_mutex_t lock;
} PDUListManager;

// Function to simulate random faults
int generate_crc_flag() {
    return rand() % 2 == 0 ? 1 : (rand() % 10 == 0); // Simulate occasional fault
}

// Validate input size
size_t validate_size(size_t N) {
    if (N > MAX_LIST_SIZE) {
        fprintf(stderr, "Error: Exceeding maximum allowable list size.\n");
        exit(EXIT_FAILURE);
    }
    return N;
}

// Initialize the PDU list manager
void initialize_manager(PDUListManager *manager, size_t N) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->size = 0;
    manager->list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->list) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
}

// Check for duplicates
int has_duplicates(PDUListManager *manager, int RX_UE_INFORMATION_TAG, int RNTI) {
    for (size_t i = 0; i < manager->size; ++i) {
        if ((manager->list[i].RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG || 
             manager->list[i].RNTI == RNTI)) {
            return 1;
        }
    }
    return 0;
}

// Populate the list
void populate_list(PDUListManager *manager, size_t N) {
    srand(time(NULL));
    for (size_t i = 0; i < N;) {
        pthread_mutex_lock(&manager->lock);
        int RX_UE_INFORMATION_TAG = rand() % 10000;
        int RNTI = rand() % 10000;

        if (!has_duplicates(manager, RX_UE_INFORMATION_TAG, RNTI)) {
            manager->list[i].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
            manager->list[i].RNTI = RNTI;
            manager->list[i].CRCFLAG = generate_crc_flag();
            i++;
        }
        pthread_mutex_unlock(&manager->lock);
    }
    manager->size = N;
}

// Log the list to a file
void log_list(const PDUListManager *manager, const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) {
        fprintf(stderr, "Error: Unable to open log file.\n");
        return;
    }
    for (size_t i = 0; i < manager->size; ++i) {
        fprintf(file, "Index: %zu, RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n",
                i, manager->list[i].RX_UE_INFORMATION_TAG,
                manager->list[i].RNTI, manager->list[i].CRCFLAG);
    }
    fclose(file);
}

// Free the resources
void free_manager(PDUListManager *manager) {
    pthread_mutex_destroy(&manager->lock);
    free(manager->list);
}

// Main function to demonstrate usage
int main(int argc, char *argv[]) {
    size_t N = (argc > 1) ? validate_size(atoi(argv[1])) : validate_size(10);

    PDUListManager manager;
    initialize_manager(&manager, N);

    populate_list(&manager, N);
    log_list(&manager, "pdu_log.txt");

    free_manager(&manager);
    return 0;
}
