UEContext* create_ue_context_list(int N) {
    if (!validate_N(N)) return NULL;

    UEContext* head = NULL;
    UEContext** current = &head;
    int ue_id_set[100000] = {0}; // Assuming a max of 100,000 possible IDs
    int tac_set[32768] = {0}; // Example for TAC range

    while (N-- > 0) {
        UEContext* new_context = malloc(sizeof(UEContext));
        if (!new_context) break;

        do {
            new_context->UE_ID = rand() % 100000;
        } while (ue_id_set[new_context->UE_ID]);

        ue_id_set[new_context->UE_ID] = 1;

        do {
            new_context->TAC = rand() % 32768;
        } while (tac_set[new_context->TAC]);

        tac_set[new_context->TAC] = 1;

        // Set PAGING_FLAG randomly
        new_context->paging_request.PAGING_FLAG = random_bool();

        *current = new_context;
        current = &new_context->next;
    }

    return head;
}

// Function to log UE CONTEXTs
void log_ue_contexts(const char* filename, UEContext* head) {
    FILE* file = fopen(filename, "w");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    int index = 0;
    while (head) {
        fprintf(file, "Index: %d, UE_ID: %d, TAC: %d, PAGING_FLAG: %d\n",
                index++, head->UE_ID, head->TAC, head->paging_request.PAGING_FLAG);
        head = head->next;
    }

    fclose(file);
}

// Function to simulate faulty network component
void introduce_fault(UEContext* context) {
    if (random_bool()) { // Simulate occasional fault
        context->paging_request.PAGING_FLAG = -1; // Invalid state
    }
}

// Function to free allocated memory
void free_ue_context_list(UEContext* head) {
    while (head) {
        UEContext* temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    init_random_seed();

    int N = 100; // Example size
    UEContext* ue_contexts = create_ue_context_list(N);

    if (!ue_contexts) return EXIT_FAILURE;

    log_ue_contexts("ue_context_log.txt", ue_contexts);

    UEContext* current = ue_contexts;
    while (current) {
        introduce_fault(current);
        current = current->next;
    }

    free_ue_context_list(ue_contexts);

    return EXIT_SUCCESS;
}
