    // Define fields for RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t pool_size;
    pthread_mutex_t lock;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_size);
void destroy_memory_pool(MemoryPool *mp);
NFAPI_CRC_INDICATION_PDU_T* allocate_pdu(MemoryPool *mp);
void deallocate_pdu(MemoryPool *mp, NFAPI_CRC_INDICATION_PDU_T *pdu);
void set_crc_flag(NFAPI_CRC_INDICATION_PDU_T *pdu);

MemoryPool* create_memory_pool(size_t initial_size) {
    if (initial_size > MAX_POOL_SIZE) {
        fprintf(stderr, "Error: Initial size exceeds maximum pool size.\n");
        return NULL;
    }

    MemoryPool *mp = malloc(sizeof(MemoryPool));
    if (!mp) {
        perror("Failed to allocate memory for Memory Pool");
        return NULL;
    }

    mp->pool = calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!mp->pool) {
        free(mp);
        perror("Failed to allocate memory pool");
        return NULL;
    }

    mp->pool_size = initial_size;
    pthread_mutex_init(&mp->lock, NULL);
    pthread_cond_init(&mp->not_full, NULL);
    pthread_cond_init(&mp->not_empty, NULL);

    fprintf(stdout, "Memory Pool created with size %zu\n", initial_size);
    return mp;
}

void destroy_memory_pool(MemoryPool *mp) {
    if (mp) {
        free(mp->pool);
        pthread_mutex_destroy(&mp->lock);
        pthread_cond_destroy(&mp->not_full);
        pthread_cond_destroy(&mp->not_empty);
        free(mp);

        fprintf(stdout, "Memory Pool destroyed\n");
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu(MemoryPool *mp) {
    if (!mp) return NULL;

    pthread_mutex_lock(&mp->lock);

    while (1) {  // Simple spin-lock for demonstration purposes
        size_t available = mp->pool_size;  // For simplicity, assume all slots are initially free.

        if (available > 0) {
            NFAPI_CRC_INDICATION_PDU_T *pdu = &mp->pool[available - 1];
            set_crc_flag(pdu);
            pthread_mutex_unlock(&mp->lock);
            fprintf(stdout, "PDU allocated\n");
            return pdu;
        }

        pthread_cond_wait(&mp->not_full, &mp->lock); // Wait for a free slot to become available
    }
}

void deallocate_pdu(MemoryPool *mp, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (!mp || !pdu) return;

    pthread_mutex_lock(&mp->lock);

    size_t index = pdu - mp->pool;  // Calculate the index of the PDU
    memset(pdu, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T)); // Clear the PDU data

    // Notify a waiting thread that space is available
    pthread_cond_signal(&mp->not_empty);

    pthread_mutex_unlock(&mp->lock);
    fprintf(stdout, "PDU deallocated\n");
}

void set_crc_flag(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (pdu) {
        srand(time(NULL)); // Seed the random number generator
        pdu->CRCFLAG = rand() % 2; // Set CRC flag randomly to 0 or 1
    }
}

int main() {
    size_t initial_size = 10000;
    MemoryPool *mp = create_memory_pool(initial_size);

    if (mp) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = allocate_pdu(mp);
        deallocate_pdu(mp, pdu);
        destroy_memory_pool(mp);
    }

    return 0;
}
