L2_CONTEXT_T* initialize_context(size_t max_structures) {
    if (initialized_structures >= max_structures || initialized_structures >= MAX_STRUCTURES) {
        fprintf(stderr, "Maximum number of structures reached.\n");
        return NULL;
    }

    L2_CONTEXT_T *context = malloc(sizeof(L2_CONTEXT_T));
    if (!context) {
        perror("Failed to allocate context");
        return NULL;
    }

    // Initialize MAC header.
    memset(&context->mac_header, 0, sizeof(MAC_HEADER_T));

    size_t packet_size = INITIAL_PACKET_SIZE;
    context->packets = malloc(packet_size * sizeof(L2_PACKET_T *));
    if (!context->packets) {
        perror("Failed to allocate initial packets");
        free(context);
        return NULL;
    }
    memset(context->packets, 0, packet_size * sizeof(L2_PACKET_T *));
    context->packet_count = 0;

    pthread_mutex_lock(&mutex);
    initialized_structures++;
    pthread_mutex_unlock(&mutex);

    return context;
}

int add_packet_to_context(L2_CONTEXT_T *context, const L2_PACKET_T *new_packet) {
    if (!validate_packet(new_packet)) {
        fprintf(stderr, "Invalid packet received.\n");
        return -1;
    }

    pthread_mutex_lock(&mutex);

    size_t current_count = context->packet_count;
    if (current_count >= INITIAL_PACKET_SIZE) {
        size_t new_size = current_count * 2;
        L2_PACKET_T **new_packets = realloc(context->packets, new_size * sizeof(L2_PACKET_T *));
        if (!new_packets) {
            perror("Failed to resize packets array");
            pthread_mutex_unlock(&mutex);
            return -1;
        }
        context->packets = new_packets;
        memset(context->packets + current_count, 0, (new_size - current_count) * sizeof(L2_PACKET_T *));
    }

    L2_PACKET_T *packet_copy = malloc(sizeof(L2_PACKET_T));
    if (!packet_copy) {
        perror("Failed to allocate packet copy");
        pthread_mutex_unlock(&mutex);
        return -1;
    }
    memcpy(packet_copy, new_packet, sizeof(L2_PACKET_T));

    context->packets[current_count] = packet_copy;
    context->packet_count++;

    pthread_mutex_unlock(&mutex);

    return 0;
}

void free_context(L2_CONTEXT_T *context) {
    if (!context) return;

    for (size_t i = 0; i < context->packet_count; ++i) {
        free(context->packets[i]);
    }
    free(context->packets);
    free(context);

    pthread_mutex_lock(&mutex);
    initialized_structures--;
    pthread_mutex_unlock(&mutex);
}
