// Function to execute a command in the background with retry mechanism
int run_command(const char* cmd, int max_retries, int retry_interval) {
    if (concurrent_processes >= MAX_CONCURRENT_PROCESSES) {
        log_message("Error: Maximum concurrent processes reached.");
        return 0;
    }

    pthread_mutex_lock(&command_lock);
    ++concurrent_processes;
    pthread_mutex_unlock(&command_lock);

    int retries = 0;
    while (retries <= max_retries) {
        pid_t pid = fork();
        if (pid == -1) {
            log_message("Error: Failed to fork process.");
        } else if (pid > 0) { // Parent
            waitpid(pid, NULL, WNOHANG);
            pthread_mutex_lock(&command_lock);
            --concurrent_processes;
            pthread_mutex_unlock(&command_lock);
            return 1; // Command executed successfully.
        } else { // Child
            execlp("/bin/sh", "sh", "-c", cmd, (char *)NULL);
            exit(EXIT_FAILURE); // If execlp fails.
        }

        retries++;
        log_message("Retrying command execution...");
        sleep(retry_interval);
    }

    pthread_mutex_lock(&command_lock);
    --concurrent_processes;
    pthread_mutex_unlock(&command_lock);

    log_message("Command execution failed after maximum retries.");
    return 0;
}

// Main function that manages the list and runs a background command
