    if (!create_nfa_list(&list, list_size)) {
        return 0;
    }

    if (!run_command(command, max_retries, retry_interval)) {
        free(list);
        return 0;
    }

    free(list);
    log_message("Operations completed successfully.");
    return 1;
}
