#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>
#include <time.h>

#define POOL_SIZE 1024

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pool[POOL_SIZE];
    pthread_mutex_t lock;
    size_t count;
} MemoryPool;

void initialize_pool(MemoryPool* pool) {
    memset(pool->pool, 0, sizeof(pool->pool));
    pthread_mutex_init(&pool->lock, NULL);
    pool->count = 0;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);

    if (pool->count < POOL_SIZE) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }
        pool->pool[pool->count++] = pdu;
    } else {
        NFAPI_CRC_INDICATION_PDU_T* pdu = NULL;
        for (size_t i = 0; i < POOL_SIZE; ++i) {
            if (!pool->pool[i]) {
                pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
                if (!pdu) {
                    fprintf(stderr, "Memory allocation failed\n");
                    break;
                }
                pool->pool[i] = pdu;
                break;
            }
        }
    }

    pthread_mutex_unlock(&pool->lock);
    return pdu;
}

void deallocate_pdu(MemoryPool* pool, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < POOL_SIZE; ++i) {
        if (pool->pool[i] == pdu) {
            free(pdu);
            pool->pool[i] = NULL;
            break;
        }
    }

    pthread_mutex_unlock(&pool->lock);
}

NFAPI_CRC_INDICATION_PDU_T* get_pdu_by_index(MemoryPool* pool, size_t index) {
    if (index >= POOL_SIZE) return NULL;
    return pool->pool[index];
}

void cleanup_pool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < POOL_SIZE; ++i) {
        if (pool->pool[i]) {
            free(pool->pool[i]);
            pool->pool[i] = NULL;
        }
    }

    pthread_mutex_unlock(&pool->lock);
    pthread_mutex_destroy(&pool->lock);
}

void initialize_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu, uint32_t rxTag, uint16_t rnti) {
    if (pdu) {
        pdu->RX_UE_INFORMATION_TAG = rxTag;
        pdu->RNTI = rnti;
        srand(time(NULL));
        pdu->CRC_INDICATION_REL8_TAG = rand() % 256; // Random CRC flag
    }
}

int main() {
    MemoryPool pool;
    initialize_pool(&pool);

    NFAPI_CRC_INDICATION_PDU_T* pdu1 = allocate_pdu(&pool);
    if (pdu1) initialize_pdu(pdu1, 12345, 6789);

    NFAPI_CRC_INDICATION_PDU_T* pdu2 = get_pdu_by_index(&pool, 0);
    if (pdu2) printf("PDU RNTI: %u\n", pdu2->RNTI);

    deallocate_pdu(&pool, pdu1);
    cleanup_pool(&pool);

    return 0;
}
