#define SLIDING_WINDOW_SIZE 10

typedef struct AllocationTracker {
    size_t allocations[SLIDING_WINDOW_SIZE];
    size_t index;
    pthread_mutex_t lock;
} AllocationTracker;

AllocationTracker tracker = {{0}, 0, PTHREAD_MUTEX_INITIALIZER};

void log_allocation(size_t count) {
    // Integration with external logging system (stub)
    printf("Logged allocation: %zu\n", count);
}

int initialize_tracker() {
    pthread_mutex_lock(&tracker.lock);
    for (size_t i = 0; i < SLIDING_WINDOW_SIZE; ++i) {
        tracker.allocations[i] = 0;
    }
    tracker.index = 0;
    pthread_mutex_unlock(&tracker.lock);
    return 0;
}

void update_tracker(size_t count) {
    pthread_mutex_lock(&tracker.lock);
    tracker.allocations[tracker.index++] = count;
    if (tracker.index == SLIDING_WINDOW_SIZE) {
        tracker.index = 0;
    }
    pthread_mutex_unlock(&tracker.lock);
}

size_t get_total_allocations() {
    size_t total = 0;
    pthread_mutex_lock(&tracker.lock);
    for (size_t i = 0; i < SLIDING_WINDOW_SIZE; ++i) {
        total += tracker.allocations[i];
    }
    pthread_mutex_unlock(&tracker.lock);
    return total;
}

int allocate_pdus(size_t n, NFAPI_CRC_INDICATION_PDU_T **pdus) {
    if (n > MAX_PDU_COUNT) {
        printf("Error: Requested number of PDUs exceeds maximum limit.\n");
