        printf("Warning: Allocation might exceed system's operational capacity.\n");
        // Handle potential resource exhaustion here
    }

    *pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*pdus == NULL) {
