        (*pdus)[i].RNTI = rand() % 100000; // Example value, replace with actual logic
        (*pdus)[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }

    update_tracker(n);
    log_allocation(n);

    return 0;
}

int main() {
