                free(new_node);
                pthread_mutex_unlock(&list->lock);
                free_linked_list(list);
                return NULL;
            }
            current = current->next;
        }

        new_node->next = list->head;
        list->head = new_node;

        pthread_mutex_unlock(&list->lock);
    }

    return list;
