        printf("No valid integers found. Exiting...\n");
        free_resources(pdu_array, offsets, keys, records, input_array);
        return EXIT_SUCCESS;
    }

    int largest_int = find_largest_integer(input_array, input_size);

    simulate_graph_database(largest_int);

    printf("Largest integer: %d\n", largest_int);

    free_resources(pdu_array, offsets, keys, records, input_array);

    return EXIT_SUCCESS;
}
