pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

int initialize_ue_context(NFAPI_UE_CONTEXT_T *context, const char *ue_id) {
    // Simulate external data source delay or failure
    // For the purpose of this example, we assume success
