}

Node* create_ue_context_list(int N) {
    if (N <= 0) return NULL;

    Node *head = NULL, **ptr = &head;
    pthread_mutex_lock(&list_mutex);

    for (int i = 0; i < N; ++i) {
        char ue_id[MAX_UE_ID_LENGTH];
        snprintf(ue_id, MAX_UE_ID_LENGTH, "UE_%d", i + 1);

        Node *new_node = (Node *)malloc(sizeof(Node));
        if (!new_node) {
            fprintf(stderr, "Memory allocation failed for UE context %d\n", i + 1);
            pthread_mutex_unlock(&list_mutex);
            return NULL;
        }

        if (initialize_ue_context(&(new_node->data), ue_id) != 0) {
            fprintf(stderr, "Failed to initialize UE context %s\n", new_node->data.UE_ID);
            free(new_node);
            pthread_mutex_unlock(&list_mutex);
            return NULL;
        }

        // Check for duplicate UE_ID
        Node *current = head;
        while (current) {
            if (strcmp(current->data.UE_ID, new_node->data.UE_ID) == 0) {
                fprintf(stderr, "Duplicate UE_ID detected: %s\n", new_node->data.UE_ID);
                free(new_node);
                pthread_mutex_unlock(&list_mutex);
                return NULL;
            }
            current = current->next;
        }

        new_node->next = NULL;
        *ptr = new_node;
        ptr = &new_node->next;
    }

    pthread_mutex_unlock(&list_mutex);
    return head;
}

void free_ue_context_list(Node* head) {
    Node* tmp;
    while (head != NULL) {
        tmp = head;
        head = head->next;
        free(tmp);
    }
}
