typedef struct {
    int ue_id;
    time_t report_time;
    float signal_strength;
} UE_Status_Report;

#define INITIAL_CAPACITY 10

typedef struct {
    UE_Status_Report *reports;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock; // Mutex for thread-safe operations
} DynamicArray;

// Function prototypes
DynamicArray* create_dynamic_array();
int add_report(DynamicArray *array, int ue_id, time_t report_time, float signal_strength);
int update_report(DynamicArray *array, int ue_id, time_t report_time, float signal_strength);
float get_latest_signal_strength(DynamicArray *array, int ue_id);
void destroy_dynamic_array(DynamicArray *array);

DynamicArray* create_dynamic_array() {
    DynamicArray *array = malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->reports = malloc(INITIAL_CAPACITY * sizeof(UE_Status_Report));
    if (!array->reports) {
        free(array);
        return NULL;
    }

    array->count = 0;
    array->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

int add_report(DynamicArray *array, int ue_id, time_t report_time, float signal_strength) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->reports[i].ue_id == ue_id) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Report already exists, consider updating instead
        }
    }

    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        UE_Status_Report *new_reports = realloc(array->reports, new_capacity * sizeof(UE_Status_Report));
        if (!new_reports) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Memory allocation failure
        }
        array->reports = new_reports;
        array->capacity = new_capacity;
    }

    UE_Status_Report report = {ue_id, report_time, signal_strength};
    array->reports[array->count++] = report;

    pthread_mutex_unlock(&array->lock);
    return 0; // Success
}

int update_report(DynamicArray *array, int ue_id, time_t report_time, float signal_strength) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->reports[i].ue_id == ue_id) {
            array->reports[i].report_time = report_time;
            array->reports[i].signal_strength = signal_strength;
            pthread_mutex_unlock(&array->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&array->lock);
    return -1; // Report not found
}

float get_latest_signal_strength(DynamicArray *array, int ue_id) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = array->count - 1; i < array->count; --i) { // Start from the latest report
        if (array->reports[i].ue_id == ue_id) {
            float signal_strength = array->reports[i].signal_strength;
            pthread_mutex_unlock(&array->lock);
            return signal_strength;
        }
    }

    pthread_mutex_unlock(&array->lock);
    return -1.0; // Report not found
}

void destroy_dynamic_array(DynamicArray *array) {
    if (array) {
        pthread_mutex_lock(&array->lock);
        free(array->reports);
        pthread_mutex_unlock(&array->lock);

        pthread_mutex_destroy(&array->lock);
        free(array);
    }
}
