['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicList;

void init_dynamic_list(DynamicList *list, size_t initial_capacity) {
    list->data = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->mutex, NULL);
}

void free_dynamic_list(DynamicList *list) {
    free(list->data);
    pthread_mutex_destroy(&list->mutex);
}

int resize_dynamic_list_if_needed(DynamicList *list) {
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            perror("Failed to reallocate memory");
            return -1;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }
    return 0;
}

int is_rnti_unique(DynamicList *list, unsigned int rnti) {
    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].RNTI == rnti) {
            return 0;
        }
    }
    return 1;
}

int populate_dynamic_list(DynamicList *list, size_t n) {
    unsigned int duplicate_count = 0;
    for (size_t i = 0; i < n; ++i) {
        if (resize_dynamic_list_if_needed(list) != 0) {
            perror("Failed to resize list");
            return -1;
        }

        pthread_mutex_lock(&list->mutex);

        NFAPI_CRC_INDICATION_PDU_T *pdu = &list->data[list->size];
        pdu->RX_UE_INFORMATION_TAG = rand();
        do {
            pdu->RNTI = rand() % 0x10000; // Example range for RNTI
        } while (!is_rnti_unique(list, pdu->RNTI));

        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1;
        list->size++;

        pthread_mutex_unlock(&list->mutex);

        if (duplicate_count > 0 && !is_rnti_unique(list, pdu->RNTI)) {
            duplicate_count++;
        }
    }

    return duplicate_count;
}

int compare_pdu(const void *a, const void *b) {
    NFAPI_CRC_INDICATION_PDU_T *pdu_a = (NFAPI_CRC_INDICATION_PDU_T *)a;
    NFAPI_CRC_INDICATION_PDU_T *pdu_b = (NFAPI_CRC_INDICATION_PDU_T *)b;
    return (int)(pdu_a->RNTI - pdu_b->RNTI);
}

void sort_dynamic_list(DynamicList *list) {
    qsort(list->data, list->size, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_pdu);
}

int write_to_file(const char *filename, DynamicList *list) {
    FILE *file = fopen(filename, "w");
    if (!file) {
        perror("Failed to open file for writing");
        return -1;
    }

    for (size_t i = 0; i < list->size; ++i) {
        fprintf(file, "RX_UE_INFORMATION_TAG: %u, RNTI: %u, CRCFLAG: %u\n",
                list->data[i].RX_UE_INFORMATION_TAG,
                list->data[i].RNTI,
                list->data[i].CRC_INDICATION_REL8_TAG.CRCFLAG);
    }

    fclose(file);
    return 0;
}

DynamicList *create_and_manage_list(size_t n, const char *filename) {
    DynamicList *list = malloc(sizeof(DynamicList));
    if (!list) {
        perror("Failed to allocate memory for list");
        exit(EXIT_FAILURE);
    }

    init_dynamic_list(list, 10); // Initial capacity

    int duplicate_count = populate_dynamic_list(list, n);
    sort_dynamic_list(list);

    if (filename && write_to_file(filename, list) != 0) {
        free_dynamic_list(list);
        free(list);
        return NULL;
    }

    printf("Successfully added %zu entries with %d duplicates encountered.\n", list->size, duplicate_count);
    return list;
}

int main() {
    size_t n = 100000; // Example number of elements
    const char *filename = "output.txt";

    DynamicList *list = create_and_manage_list(n, filename);

    if (list) {
        free_dynamic_list(list);
        free(list);
    }

    return 0;
}
```

This C code implements a function that dynamically manages a list of `NFAPI_CRC_INDICATION_PDU_T` structures. It includes memory management, concurrency handling with mutexes, RNTI uniqueness validation, sorting by RNTI, and optional file output. The code is designed for efficiency and robustness in managing potentially large data sets.']

['Below is an implementation in C for managing a doubly linked list of `TCP_CONNECTION_RECORD` structures with the specified requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char source_ip[16];
    char dest_ip[16];
    unsigned short src_port;
    unsigned short dst_port;
    long timestamp; // Assuming timestamp is a Unix epoch time for simplicity
} TCP_CONNECTION_RECORD;

typedef struct Node {
    TCP_CONNECTION_RECORD record;
    struct Node* prev;
    struct Node* next;
} Node;

Node* create_node(TCP_CONNECTION_RECORD rec) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->record = rec;
    new_node->prev = new_node->next = NULL;
    return new_node;
}

int ip_combination_exists(Node* head, char* src_ip, char* dest_ip) {
    Node* current = head;
    while (current) {
        if (strcmp(current->record.source_ip, src_ip) == 0 &&
            strcmp(current->record.dest_ip, dest_ip) == 0) {
            return 1;
        }
        current = current->next;
    }
    return 0;
}

void insert_sorted(Node** head, TCP_CONNECTION_RECORD rec) {
    Node* new_node = create_node(rec);
    if (!new_node) return;

    if (*head == NULL || (*head)->record.timestamp > rec.timestamp) {
        new_node->next = *head;
        if (*head != NULL) (*head)->prev = new_node;
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next && current->next->record.timestamp <= rec.timestamp) {
            current = current->next;
        }
        new_node->next = current->next;
        if (current->next != NULL) current->next->prev = new_node;
        current->next = new_node;
        new_node->prev = current;
    }
}

void add_record(Node** head, TCP_CONNECTION_RECORD rec) {
    while (ip_combination_exists(*head, rec.source_ip, rec.dest_ip)) {
        // Generate a unique combination; simplistic approach
        static int counter = 0;
        sprintf(rec.src_port == 0 ? rec.dest_ip : rec.source_ip, "127.0.%d.%d", ++counter / 256, counter % 256);
    }
    insert_sorted(head, rec);
}

void export_to_file(Node* head, const char* filename) {
    FILE* file = fopen(filename, "w");
    if (!file) return;

    Node* current = head;
    while (current) {
        fprintf(file, "%s %s %hu %hu %ld\n",
                current->record.source_ip,
                current->record.dest_ip,
                current->record.src_port,
                current->record.dst_port,
                current->record.timestamp);
        current = current->next;
    }

    fclose(file);
}

void free_list(Node* head) {
    Node* tmp;
    while (head) {
        tmp = head;
        head = head->next;
        free(tmp);
    }
}
```

### Explanation:

- **Node Structure**: Represents each element in the doubly linked list with pointers to both previous and next nodes.

- **create_node Function**: Allocates memory for a new node.

- **ip_combination_exists Function**: Checks if a source IP and destination IP combination already exists in the list.

- **insert_sorted Function**: Inserts a record into the list while maintaining chronological order based on timestamps.

- **add_record Function**: Ensures unique IP combinations by generating new ones when duplicates are found, then inserts them sorted.

- **export_to_file Function**: Writes the records to a specified file in a simple text format.

- **free_list Function**: Frees all nodes in the list to manage memory efficiently.

This implementation handles memory management and ensures that operations remain efficient even with large datasets by maintaining order during insertion. The unique combination generation is simplistic and can be enhanced as needed.']

