// Main function for dynamic memory allocation and initialization
DataStructures* allocate_and_initialize_data_structures(size_t num_elements, size_t num_crcs) {
    DataStructures *data = (DataStructures*)malloc(sizeof(DataStructures));
    if (!data) return NULL;

    data->offsets = (long*)calloc(num_elements, sizeof(long));
    if (!data->offsets) { free(data); return NULL; }

    data->keys = (int*)calloc(num_elements, sizeof(int));
    if (!data->keys) { free(data->offsets); free(data); return NULL; }

    data->records = (struct {
        int value;
    }*)malloc(num_elements * sizeof(struct { int value; }));
    if (!data->records) { 
        free(data->keys);
        free(data->offsets);
        free(data);
        return NULL;
    }

    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < num_elements; ++i) {
        data->records[i].value = rand() % 100; // Random integer between 0 and 99
    }

    data->crcIndications = (NFAPI_CRC_INDICATION_PDU_T**)malloc(num_crcs * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!data->crcIndications) {
        free(data->records);
        free(data->keys);
        free(data->offsets);
        free(data);
        return NULL;
    }

    for (size_t i = 0; i < num_crcs; ++i) {
        data->crcIndications[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!data->crcIndications[i]) {
            for (size_t j = 0; j < i; ++j) free(data->crcIndications[j]);
            free(data->crcIndications);
            free(data->records);
            free(data->keys);
            free(data->offsets);
            free(data);
            return NULL;
        }

        data->crcIndications[i]->RX_UE_INFORMATION_TAG = rand() % 1000; // Random tag
        data->crcIndications[i]->RNTI = rand() % 1000; // Random RNTI
        data->crcIndications[i]->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRC flag (0 or 1)
    }

    return data;
}

// Free allocated memory for the data structures
void free_data_structures(DataStructures *data) {
    if (!data) return;

    free(data->offsets);
    free(data->keys);
    free(data->records);

    for (size_t i = 0; i < num_crcs; ++i) {
        free(data->crcIndications[i]);
    }
    free(data->crcIndications);

    free(data);
