        cached_arrays[cache_count] = array;
        cache_indices[cache_count++] = N;
    } else {
        // Replace the oldest entry in the cache
        int oldest_index = 0; 
        for (int i = 1; i < CACHE_SIZE; ++i) {
            if (cache_indices[i] < cache_indices[oldest_index]) {
                oldest_index = i;
            }
        }

        free(cached_arrays[oldest_index]);
        cached_arrays[oldest_index] = array;
    }

    log_message("Memory allocation successful.");
    return array;
