// Define a type alias for easy readability
typedef struct {
    uint8_t PHY_MEASUREMENT_TAG;
    uint16_t CELL_ID;
    union {
        int RSRP;
        int RSRQ;
        float SINR;
        // Add other measurement types as needed
    } MEASUREMENT_RESULTS_TAG;
} LTE_PHY_MEASUREMENT_PDU_T;

// Function to generate a random value within a specified range
int getRandomValue(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Logger function for tracking allocation status
void logAllocationStatus(size_t allocatedCount, size_t failCount) {
    printf("Allocated: %zu, Failed: %zu\n", allocatedCount, failCount);
}

// Mutex to ensure thread-safe logging and counter incrementation
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to dynamically allocate and populate an array of LTE_PHY_MEASUREMENT_PDU_T structures
LTE_PHY_MEASUREMENT_PDU_T* createMeasurementPDUArray(size_t count, uint8_t measurementType, int rangeMin, int rangeMax) {
    if (count == 0 || rangeMin > rangeMax) return NULL;

    // Allocate memory for the array of structures
    LTE_PHY_MEASUREMENT_PDU_T *pduArray = (LTE_PHY_MEASUREMENT_PDU_T*)malloc(count * sizeof(LTE_PHY_MEASUREMENT_PDU_T));
    if (!pduArray) {
        logAllocationStatus(0, 1);
        return NULL;
    }

    size_t allocatedCount = 0;

    // Populate each structure with a valid PHY_MEASUREMENT_TAG, CELL_ID, and MEASUREMENT_RESULTS_TAG
    for (size_t i = 0; i < count; ++i) {
        pduArray[i].PHY_MEASUREMENT_TAG = measurementType;
        pduArray[i].CELL_ID = rand() % 65536; // Random cell ID

        switch (measurementType) {
            case 1: // RSRP
                pduArray[i].MEASUREMENT_RESULTS_TAG.RSRP = getRandomValue(rangeMin, rangeMax);
                break;
            case 2: // RSRQ
                pduArray[i].MEASUREMENT_RESULTS_TAG.RSRQ = getRandomValue(rangeMin, rangeMax);
                break;
            case 3: // SINR
                pduArray[i].MEASUREMENT_RESULTS_TAG.SINR = (float)getRandomValue(rangeMin, rangeMax) + rand() % 100 / 100.0f; // Random float value
                break;
            default:
                free(pduArray);
                logAllocationStatus(allocatedCount, count - allocatedCount);
                return NULL;
        }

        ++allocatedCount;
    }

    // Log the number of successfully allocated structures
    pthread_mutex_lock(&mutex);
    logAllocationStatus(allocatedCount, 0);
    pthread_mutex_unlock(&mutex);

    return pduArray;
}

// Example usage
int main() {
    srand(time(NULL)); // Seed random number generator

    size_t numStructures = 5000;
    uint8_t measurementType = 1; // Example: RSRP
    int rangeMin = -140, rangeMax = -50;

    LTE_PHY_MEASUREMENT_PDU_T *pduArray = createMeasurementPDUArray(numStructures, measurementType, rangeMin, rangeMax);

    if (pduArray) {
        // Use pduArray as needed

        free(pduArray); // Free allocated memory
    }

    return 0;
}
```

### Explanation of Key Design Choices:

- **Random Value Generation**: A helper function `getRandomValue` generates random integers within a specified range for integer types and provides a float value for SINR.

- **Memory Allocation & Error Handling**: The function attempts to allocate memory for the array, returning `NULL` if allocation fails. Successful allocations are logged using `logAllocationStatus`.

- **Thread Safety**: A mutex (`pthread_mutex_t`) is used to ensure that logging operations are thread-safe, preventing race conditions when accessed by multiple threads.

- **Measurement Type Handling**: The function uses a switch statement to populate the appropriate union field based on the provided `measurementType`. Invalid types result in freeing allocated memory and returning `NULL`.

- **Logging & Extensibility**: Logging is implemented for allocation status. Future extensions could involve adding new measurement types or enhancing logging with more detailed information (e.g., timestamps).

- **Resource Management**: Memory is freed after use to prevent leaks, adhering to efficient resource management practices in a high-throughput system.

The solution is designed to be extensible and maintainable while optimizing for performance and concurrency.']

