    // Simulate external data source logic, ensuring unique RNTI values within range
    srand(time(NULL));
    return (current_count % 1024) + 1;  // Example: Ensure RNTI is in a valid range [1, 1024]
}

// Function to calculate CRCFLAG based on non-trivial conditions
uint32_t calculate_crcflag(uint16_t rnti, int index, time_t timestamp) {
    return (rnti * index + timestamp) % 0xFFFFFFFF;  // Example hash-like calculation
}

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t count;
} CRC_UE_LIST_T;

// Initialize the list with an initial capacity
void init_crc_ue_list(CRC_UE_LIST_T *list, size_t initial_capacity) {
    list->data = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        fprintf(stderr, "Failed to allocate memory for UE list\n");
        exit(EXIT_FAILURE);
    }
    list->capacity = initial_capacity;
    list->count = 0;
}

// Resize the internal data structures dynamically
void resize_crc_ue_list(CRC_UE_LIST_T *list, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T* resized_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!resized_data) {
        fprintf(stderr, "Failed to resize UE list\n");
        exit(EXIT_FAILURE);
    }
    list->data = resized_data;
    list->capacity = new_capacity;
}

// Add a new UE instance to the list
void add_ue_to_list(CRC_UE_LIST_T *list) {
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity > 0 ? list->capacity * 2 : 1;
        resize_crc_ue_list(list, new_capacity);
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = &list->data[list->count];
    pdu->RX_UE_INFORMATION_TAG = rand();  // Simulate tag fetching
    pdu->RNTI = fetch_valid_rnti(list->count);

    time_t current_time = time(NULL);
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = calculate_crcflag(pdu->RNTI, list->count, current_time);

    list->count++;
}

// Deallocate the list resources
void free_crc_ue_list(CRC_UE_LIST_T *list) {
    free(list->data);
    list->data = NULL;
    list->capacity = 0;
    list->count = 0;
}

// Main function to demonstrate usage
int main() {
    CRC_UE_LIST_T ue_list;
    init_crc_ue_list(&ue_list, 10);  // Start with an initial capacity

    for (size_t i = 0; i < MAX_UE_COUNT; ++i) {
        add_ue_to_list(&ue_list);
    }

    printf("Total UEs managed: %zu\n", ue_list.count);

    free_crc_ue_list(&ue_list);
    return 0;
}
