typedef struct {
    float value;
    unsigned char identifier;
    char *buffer;
} entry_t;

int allocate_and_initialize(int num_entries, float min_value, float max_value, const char* buffer_string) {
    // Seed random number generator
    srand(time(NULL));

    float *float_values = NULL;
    unsigned char *identifiers = NULL;
    entry_t **entries = (entry_t **)malloc(num_entries * sizeof(entry_t *));
    if (!entries) return -1;

    int retry_count = 0;
    while (retry_count < 3) {
        // Allocate memory for arrays
        float_values = (float *)calloc(num_entries, sizeof(float));
        identifiers = (unsigned char *)calloc(num_entries, sizeof(unsigned char));

        if (float_values && identifiers) break;

        // If allocation fails, retry
        free_float_values(float_values);
        free_identifiers(identifiers);

        retry_count++;
    }

    if (!float_values || !identifiers) {
        free(entries);
        return -1;
    }

    // Initialize float values and identifiers
    for (int i = 0; i < num_entries; ++i) {
        float_values[i] = min_value + ((float)rand() / RAND_MAX) * (max_value - min_value);
        identifiers[i] = rand() % 256;
    }

    // Allocate memory for struct entries
    retry_count = 0;
    while (retry_count < 3 && !entries) {
        entry_t **temp_entries = (entry_t **)realloc(entries, num_entries * sizeof(entry_t *));
        if (!temp_entries) {
            retry_count++;
            continue;
        }
        entries = temp_entries;

        for (int i = 0; i < num_entries; ++i) {
            entry_t *new_entry = (entry_t *)malloc(sizeof(entry_t));
            if (!new_entry) {
                // If allocation fails, rollback
                free_struct_entries(entries, i);
                retry_count++;
                entries = NULL;
                break;
            }

            new_entry->value = float_values[i];
            new_entry->identifier = identifiers[i];

            size_t buffer_size = strlen(buffer_string) + 1;
            new_entry->buffer = (char *)malloc(buffer_size);
            if (!new_entry->buffer) {
                free(new_entry);
                // If allocation fails, rollback
                free_struct_entries(entries, i);
                retry_count++;
                entries = NULL;
                break;
            }

            strcpy(new_entry->buffer, buffer_string);

            entries[i] = new_entry;
        }
    }

    if (!entries) return -1;

    // Free temporary arrays
    free(float_values);
    free(identifiers);

    return 0; // Success
}

void free_float_values(float *float_values) {
    if (float_values) free(float_values);
}

void free_identifiers(unsigned char *identifiers) {
    if (identifiers) free(identifiers);
}

void free_struct_entries(entry_t **entries, int num_entries) {
    for (int i = 0; i < num_entries; ++i) {
        if (entries[i]) {
            free(entries[i]->buffer);
            free(entries[i]);
        }
    }
    free(entries);
}
