// Define the MAC_PDU structure
typedef struct {
    int PDCP_SN; // Unique Packet Data Convergence Protocol Sequence Number
    char *RRC_CONTAINER; // Assume a string representation for simplicity
    char DL_CCCH_Message[256]; // Placeholder size for demonstration purposes
} MAC_PDU;

// Structure to manage the dynamic array and synchronization
typedef struct {
    MAC_PDU **array;
    int count;
    int capacity;
    pthread_mutex_t lock;
    pthread_rwlock_t rwlock; // Read-write lock for efficient concurrent access
} MAC_PDU_Manager;

// Function prototypes
MAC_PDU_Manager* initialize_manager(int initial_capacity);
void cleanup_manager(MAC_PDU_Manager *manager);
int add_pdu(MAC_PDU_Manager *manager, int pdcp_sn, const char *rrc_container, const char *dl_ccch_message);
MAC_PDU* get_pdu_by_index(MAC_PDU_Manager *manager, int index);
int update_pdu(MAC_PDU_Manager *manager, int pdcp_sn, const char *new_rrc_container, const char *new_dl_ccch_message);
void validate_and_cleanup(MAC_PDU_Manager *manager);

// Initialize the manager with a given capacity
MAC_PDU_Manager* initialize_manager(int initial_capacity) {
    MAC_PDU_Manager *manager = (MAC_PDU_Manager *)malloc(sizeof(MAC_PDU_Manager));
    if (!manager) return NULL;

    manager->array = (MAC_PDU **)calloc(initial_capacity, sizeof(MAC_PDU *));
    if (!manager->array) {
        free(manager);
        return NULL;
    }

    manager->count = 0;
    manager->capacity = initial_capacity;

    pthread_mutex_init(&manager->lock, NULL);
    pthread_rwlock_init(&manager->rwlock, NULL);

    return manager;
}

// Cleanup resources
void cleanup_manager(MAC_PDU_Manager *manager) {
    if (pthread_rwlock_trywrlock(&manager->rwlock)) {
        pthread_rwlock_unlock(&manager->rwlock);
        // Handle busy wait or use a condition variable to wait for threads to release the lock.
        pthread_rwlock_wrlock(&manager->rwlock);
    }

    for (int i = 0; i < manager->count; ++i) {
        free(manager->array[i]->RRC_CONTAINER); // Assuming it was dynamically allocated
        free(manager->array[i]);
    }
    free(manager->array);

    pthread_mutex_destroy(&manager->lock);
    pthread_rwlock_destroy(&manager->rwlock);

    free(manager);
}

// Add a new PDU to the manager
int add_pdu(MAC_PDU_Manager *manager, int pdcp_sn, const char *rrc_container, const char *dl_ccch_message) {
    if (pthread_rwlock_wrlock(&manager->rwlock)) {
        return -1; // Lock error
    }

    for (int i = 0; i < manager->count; ++i) {
        if (manager->array[i]->PDCP_SN == pdcp_sn) {
            pthread_rwlock_unlock(&manager->rwlock);
            return -2; // Duplicate PDCP_SN
        }
    }

    // Validate RRC_CONTAINER with external data source here...

    if (manager->count >= manager->capacity) {
        int new_capacity = manager->capacity * 2;
        MAC_PDU **new_array = realloc(manager->array, new_capacity * sizeof(MAC_PDU *));
        if (!new_array) {
            pthread_rwlock_unlock(&manager->rwlock);
            return -3; // Memory error
        }
        manager->array = new_array;
        manager->capacity = new_capacity;
    }

    MAC_PDU *pdu = (MAC_PDU *)malloc(sizeof(MAC_PDU));
    if (!pdu) {
        pthread_rwlock_unlock(&manager->rwlock);
        return -3; // Memory error
    }

    pdu->PDCP_SN = pdcp_sn;
    pdu->RRC_CONTAINER = strdup(rrc_container); // Assume it needs dynamic allocation
    strncpy(pdu->DL_CCCH_Message, dl_ccch_message, sizeof(pdu->DL_CCCH_Message) - 1);
    manager->array[manager->count++] = pdu;

    pthread_rwlock_unlock(&manager->rwlock);
    return 0; // Success
}

// Retrieve a PDU by index
MAC_PDU* get_pdu_by_index(MAC_PDU_Manager *manager, int index) {
    if (index < 0 || index >= manager->count) return NULL;

    pthread_rwlock_rdlock(&manager->rwlock);
    MAC_PDU *pdu = manager->array[index];
    pthread_rwlock_unlock(&manager->rwlock);

    return pdu;
}

// Update an existing PDU by PDCP_SN
int update_pdu(MAC_PDU_Manager *manager, int pdcp_sn, const char *new_rrc_container, const char *new_dl_ccch_message) {
    if (pthread_rwlock_wrlock(&manager->rwlock)) {
        return -1; // Lock error
    }

    for (int i = 0; i < manager->count; ++i) {
        if (manager->array[i]->PDCP_SN == pdcp_sn) {
            free(manager->array[i]->RRC_CONTAINER);
            manager->array[i]->RRC_CONTAINER = strdup(new_rrc_container);

            strncpy(manager->array[i]->DL_CCCH_Message, new_dl_ccch_message, sizeof(manager->array[i]->DL_CCCH_Message) - 1);
            pthread_rwlock_unlock(&manager->rwlock);
            return 0; // Success
        }
    }

    pthread_rwlock_unlock(&manager->rwlock);
    return -2; // Not found
}

// Validate and cleanup the manager's data, simulating validation with an external source
void validate_and_cleanup(MAC_PDU_Manager *manager) {
    if (pthread_rwlock_wrlock(&manager->rwlock)) {
        return; // Handle lock error appropriately
    }

    for (int i = 0; i < manager->count; ++i) {
        // Simulate validation with an external data source...
        // Example: If invalid, remove the entry

        if (/* condition to determine invalid RRC_CONTAINER */) {
            free(manager->array[i]->RRC_CONTAINER);
            free(manager->array[i]);
            manager->array[i] = manager->array[--manager->count];
            i--; // Adjust index after removal
        }
    }

    pthread_rwlock_unlock(&manager->rwlock);
}

// Main function to demonstrate usage (for testing purposes)
int main() {
    MAC_PDU_Manager *manager = initialize_manager(10);

    add_pdu(manager, 1, "RRC_CONTAINER_1", "DL_CCCH_MSG_1");
    add_pdu(manager, 2, "RRC_CONTAINER_2", "DL_CCCH_MSG_2");

    MAC_PDU *pdu = get_pdu_by_index(manager, 0);
    if (pdu) {
        printf("PDCP_SN: %d, RRC_CONTAINER: %s\n", pdu->PDCP_SN, pdu->RRC_CONTAINER);
    }

    update_pdu(manager, 1, "NEW_RRC_CONTAINER_1", "NEW_DL_CCCH_MSG_1");

    cleanup_manager(manager);

    return 0;
}
