```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_NICS 1000
#define CACHE_SIZE 10

typedef struct {
    char mac_address[18];
    char ip_address[16];
    char subnet_mask[16];
} NICConfig;

typedef struct Node {
    NICConfig config;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} DoublyLinkedList;

typedef struct {
    char subnet[16];
    int hits;
    time_t timestamp;
} CacheEntry;

typedef struct {
    CacheEntry entries[CACHE_SIZE];
    pthread_rwlock_t rwlock;
} SubnetCache;

// Dummy external API functions
int validate_ip_with_subnet(const char* ip, const char* subnet) {
    // Placeholder for actual validation logic
    return 1; // Assume valid for demonstration
}

char* fetch_subnets_from_api() {
    // Placeholder for actual API call
    static char subnets[] = "192.168.0.0/24,10.0.0.0/8";
    return subnets;
}

// Cache management functions
void init_cache(SubnetCache* cache) {
    pthread_rwlock_init(&cache->rwlock, NULL);
}

char* get_cached_subnet(SubnetCache* cache, const char* subnet) {
    pthread_rwlock_rdlock(&cache->rwlock);
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (strcmp(cache->entries[i].subnet, subnet) == 0) {
            pthread_rwlock_unlock(&cache->rwlock);
            return cache->entries[i].subnet;
        }
    }
    pthread_rwlock_unlock(&cache->rwlock);

    pthread_rwlock_wrlock(&cache->rwlock);
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (cache->entries[i].hits == 0 || time(NULL) - cache->entries[i].timestamp > 3600) { // Refresh every hour
            strcpy(cache->entries[i].subnet, subnet);
            cache->entries[i].hits = 1;
            cache->entries[i].timestamp = time(NULL);
            pthread_rwlock_unlock(&cache->rwlock);
            return cache->entries[i].subnet;
        }
    }

    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (cache->entries[i].hits == 0 || time(NULL) - cache->entries[i].timestamp > 3600) {
            strcpy(cache->entries[i].subnet, subnet);
            cache->entries[i].hits = 1;
            cache->entries[i].timestamp = time(NULL);
            pthread_rwlock_unlock(&cache->rwlock);
            return cache->entries[i].subnet;
        }
    }

    pthread_rwlock_unlock(&cache->rwlock);
    return NULL; // Cache is full and no slot to refresh
}

// Linked list management functions
void init_list(DoublyLinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

Node* create_node(const NICConfig* config) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;

    memcpy(&new_node->config, config, sizeof(NICConfig));
    new_node->prev = new_node->next = NULL;
    return new_node;
}

void add_to_list(DoublyLinkedList* list, const NICConfig* config) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = create_node(config);
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (list->head == NULL) {
        list->head = new_node;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
        new_node->prev = current;
    }

    pthread_mutex_unlock(&list->lock);
}

int validate_and_add(DoublyLinkedList* list, SubnetCache* cache, const NICConfig* config) {
    char* subnets = fetch_subnets_from_api();
    char* token = strtok(strdup(subnets), ",");

    while (token != NULL) {
        char* cached_subnet = get_cached_subnet(cache, token);
        if (!cached_subnet || validate_ip_with_subnet(config->ip_address, cached_subnet)) {
            add_to_list(list, config);
            return 1; // Successfully added
        }
        token = strtok(NULL, ",");
    }

    fprintf(stderr, "Invalid IP configuration for NIC: %s\n", config->mac_address);
    return 0; // Invalid configuration
}

// Serialization functions
void serialize_list(const DoublyLinkedList* list, const char* filename) {
    pthread_mutex_lock(&list->lock);

    FILE* file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node* current = list->head;
    while (current != NULL) {
        fwrite(&current->config, sizeof(NICConfig), 1, file);
        current = current->next;
    }

    fclose(file);
    pthread_mutex_unlock(&list->lock);
}

void deserialize_list(DoublyLinkedList* list, const char* filename) {
    pthread_mutex_lock(&list->lock);

    FILE* file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for reading\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    NICConfig config;
    while (fread(&config, sizeof(NICConfig), 1, file)) {
        add_to_list(list, &config);
    }

    fclose(file);
    pthread_mutex_unlock(&list->lock);
}

// Example usage
int main() {
    DoublyLinkedList nic_list;
    SubnetCache subnet_cache;

    init_list(&nic_list);
    init_cache(&subnet_cache);

    NICConfig config = { "00:1A:2B:3C:4D:5E", "192.168.0.10", "255.255.255.0" };
    if (validate_and_add(&nic_list, &subnet_cache, &config)) {
        printf("NIC configuration added successfully.\n");
    }

    serialize_list(&nic_list, "nic_config.dat");

    DoublyLinkedList restored_list;
    init_list(&restored_list);
    deserialize_list(&restored_list, "nic_config.dat");

    pthread_mutex_destroy(&nic_list.lock);
    pthread_rwlock_destroy(&subnet_cache.rwlock);

    return 0;
}
```

### Key Features:
- **Thread Safety**: Uses mutexes and read-write locks to ensure thread-safe operations.
- **Caching Mechanism**: Implements a simple cache for subnet details, refreshing entries based on usage and time.
- **Error Handling**: Provides error messages for invalid configurations and memory allocation failures.
- **Serialization/Deserialization**: Allows saving and loading of the linked list structure from disk.']

