    if (!list) return NULL;

    list->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->size = initial_size;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_list(List* list) {
    if (list) {
        pthread_mutex_destroy(&list->lock);
        free(list->data);
        free(list);
    }
}

int add_pdu(List* list, int rx_ue_tag, int rnti, int crc_rel8_tag, int crcflag) {
    if (!list || !pthread_mutex_lock(&list->lock)) return -1;

    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].RX_UE_INFORMATION_TAG == rx_ue_tag && list->data[i].RNTI == rnti) {
            pthread_mutex_unlock(&list->lock);
            return -2; // Entry already exists
        }
    }

    NFAPI_CRC_INDICATION_PDU_T pdu = {rx_ue_tag, rnti, crc_rel8_tag, crcflag};
    list->data[list->size++] = pdu;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_pdu(List* list, int rx_ue_tag, int rnti) {
    if (!list || !pthread_mutex_lock(&list->lock)) return NULL;

    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].RX_UE_INFORMATION_TAG == rx_ue_tag && list->data[i].RNTI == rnti) {
            NFAPI_CRC_INDICATION_PDU_T* pdu = &list->data[i];
            pthread_mutex_unlock(&list->lock);
            return pdu;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

int resize_list(List* list, size_t new_size) {
    if (!list || !pthread_mutex_lock(&list->lock)) return -1;

    NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        pthread_mutex_unlock(&list->lock);
        return -2;
    }

    list->data = new_data;
    list->size = new_size;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

