#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <jansson.h>  // JSON parsing library

#define NFAPI_UE_TAG_MIN 1
#define NFAPI_UE_TAG_MAX 65535

typedef struct {
    unsigned int UE_ID;
    unsigned short RNTI;
    unsigned char CRCFLAG;
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    unsigned short RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int parse_rnti_from_json(const char *config_path, unsigned short **rnti_list, size_t *list_size) {
    json_error_t error;
    json_t *root = json_load_file(config_path, 0, &error);
    if (!root) {
        fprintf(stderr, "Error parsing JSON: %s\n", error.text);
        return -1;
    }

    if (!json_is_array(root)) {
        fprintf(stderr, "Invalid JSON format: root is not an array.\n");
        json_decref(root);
        return -2;
    }

    *rnti_list = malloc(json_array_size(root) * sizeof(unsigned short));
    if (!*rnti_list) {
        fprintf(stderr, "Memory allocation failed for RNTI list.\n");
        json_decref(root);
        return -3;
    }

    for (size_t i = 0; i < json_array_size(root); ++i) {
        json_t *value = json_array_get(root, i);
        if (!json_is_number(value)) {
            fprintf(stderr, "Invalid RNTI value at index %zu.\n", i);
            free(*rnti_list);
            json_decref(root);
            return -4;
        }
        (*rnti_list)[i] = (unsigned short)json_integer_value(value);
    }

    *list_size = json_array_size(root);
    json_decref(root);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* initialize_crc_pdu(int N, unsigned int seed, const char *config_path) {
    if (N <= 0) {
        fprintf(stderr, "Invalid input: N must be greater than zero.\n");
        return NULL;
    }

    unsigned short *rnti_list = NULL;
    size_t rnti_list_size = 0;

    int parse_result = parse_rnti_from_json(config_path, &rnti_list, &rnti_list_size);
    if (parse_result != 0 || rnti_list_size < N) {
        free(rnti_list);
        fprintf(stderr, "RNTI list is insufficient or invalid.\n");
        return NULL;
    }

    srand(seed);

    NFAPI_CRC_INDICATION_PDU_T *pdu_array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_array) {
        free(rnti_list);
        fprintf(stderr, "Memory allocation failed for PDU array.\n");
        return NULL;
    }

    unsigned int used_tags[N] = {0};
    size_t unique_tag_count = 0;

    for (int i = 0; i < N; ++i) {
        if (unique_tag_count >= (NFAPI_UE_TAG_MAX - NFAPI_UE_TAG_MIN + 1)) {
            free(pdu_array);
            free(rnti_list);
            fprintf(stderr, "Not enough unique UE tags available.\n");
            return NULL;
        }

        int ue_tag = NFAPI_UE_TAG_MIN + rand() % (NFAPI_UE_TAG_MAX - NFAPI_UE_TAG_MIN + 1);
        while (used_tags[ue_tag - NFAPI_UE_TAG_MIN]) {
            ue_tag = NFAPI_UE_TAG_MIN + rand() % (NFAPI_UE_TAG_MAX - NFAPI_UE_TAG_MIN + 1);
        }
        used_tags[ue_tag - NFAPI_UE_TAG_MIN] = 1;
        unique_tag_count++;

        pdu_array[i].ue_info_tag.UE_ID = ue_tag;
        pdu_array[i].ue_info_tag.RNTI = rnti_list[i % rnti_list_size];
        pdu_array[i].ue_info_tag.CRCFLAG = rand() & 0x01; // Random CRC flag
        pdu_array[i].RNTI = pdu_array[i].ue_info_tag.RNTI;
        pdu_array[i].CRC_INDICATION_REL8_TAG = i % 256;  // Arbitrary tag value for example purposes
    }

    free(rnti_list);
    return pdu_array;
}

void cleanup_pdu_array(NFAPI_CRC_INDICATION_PDU_T *pdu_array) {
    if (pdu_array) {
        free(pdu_array);
    }
}
