#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode *next;
} ListNode;

typedef struct {
    ListNode *head;
    pthread_mutex_t lock;
} LinkedList;

void init_random() {
    srand((unsigned int)time(NULL));
}

NFAPI_CRC_INDICATION_PDU_T create_pdu(int tag, int rnti) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = tag;
    pdu.RNTI = rnti;
    pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    return pdu;
}

LinkedList* create_list(int size) {
    LinkedList *list = malloc(sizeof(LinkedList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);

    for (int i = 0; i < size; ++i) {
        ListNode *new_node = malloc(sizeof(ListNode));
        new_node->data = create_pdu(i, rand()); // Random RNTI
        new_node->next = list->head;
        list->head = new_node;
    }
    return list;
}

void free_list(LinkedList *list) {
    pthread_mutex_lock(&list->lock);
    ListNode *current = list->head;
    while (current != NULL) {
        ListNode *temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void manage_crc_lists(int num_lists, int sizes[]) {
    LinkedList **lists = malloc(num_lists * sizeof(LinkedList*));

    for (int i = 0; i < num_lists; ++i) {
        lists[i] = create_list(sizes[i]);
    }

    // Simulate some operations...

    for (int i = 0; i < num_lists; ++i) {
        free_list(lists[i]);
    }

    free(lists);
}

void* thread_function(void *arg) {
    int num_lists = *(int *)arg;
    int sizes[] = {10, 20, 30}; // Example sizes
    manage_crc_lists(num_lists, sizes);
    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <num_threads>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int num_threads = atoi(argv[1]);
    pthread_t threads[num_threads];

    init_random();

    for (int i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, thread_function, &num_threads);
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    return EXIT_SUCCESS;
}
