#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    size_t payload_size;
    long timestamp;  // Using 'long' for simplicity in this example.
    int data_integrity_flag;
} DataPacket;

typedef struct {
    DataPacket* packets;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} PacketManager;

// Initialize the packet manager
void init_packet_manager(PacketManager* pm, size_t initial_capacity) {
    pm->packets = (DataPacket*)malloc(initial_capacity * sizeof(DataPacket));
    if (!pm->packets) {
        fprintf(stderr, "Failed to allocate memory for packets\n");
        exit(EXIT_FAILURE);
    }
    pm->capacity = initial_capacity;
    pm->count = 0;
    pthread_mutex_init(&pm->lock, NULL);
}

// Add a new packet
int add_packet(PacketManager* pm, DataPacket packet) {
    pthread_mutex_lock(&pm->lock);

    if (pm->count == pm->capacity) {
        size_t new_capacity = pm->capacity * 2;
        DataPacket* new_packets = (DataPacket*)realloc(pm->packets, new_capacity * sizeof(DataPacket));
        if (!new_packets) {
            pthread_mutex_unlock(&pm->lock);
            fprintf(stderr, "Failed to reallocate memory for packets\n");
            return -1; // Memory allocation error
        }
        pm->packets = new_packets;
        pm->capacity = new_capacity;
    }

    pm->packets[pm->count++] = packet;

    pthread_mutex_unlock(&pm->lock);
    return 0;
}

// Retrieve a packet by index
DataPacket* get_packet(PacketManager* pm, size_t index) {
    if (index >= pm->count) {
        fprintf(stderr, "Index out of bounds\n");
        return NULL; // Error handling for invalid index
    }

    pthread_mutex_lock(&pm->lock);
    DataPacket* packet = &pm->packets[index];
    pthread_mutex_unlock(&pm->lock);

    return packet;
}

// Calculate average payload size
double calculate_average_payload_size(PacketManager* pm) {
    if (pm->count == 0) {
        return 0.0; // Avoid division by zero
    }

    pthread_mutex_lock(&pm->lock);
    size_t total_payload_size = 0;

    for (size_t i = 0; i < pm->count; ++i) {
        total_payload_size += pm->packets[i].payload_size;
    }

    double average = (double)total_payload_size / pm->count;

    pthread_mutex_unlock(&pm->lock);
    return average;
}

// Clean up the packet manager
void free_packet_manager(PacketManager* pm) {
    pthread_mutex_lock(&pm->lock);
    free(pm->packets);
    pm->packets = NULL;
    pm->capacity = 0;
    pm->count = 0;
    pthread_mutex_unlock(&pm->lock);

    pthread_mutex_destroy(&pm->lock);
}

// Example usage
int main() {
    PacketManager pm;
    init_packet_manager(&pm, 10); // Initial capacity of 10

    DataPacket packet1 = {100, 1627892345, 1};
    add_packet(&pm, packet1);

    DataPacket* retrieved_packet = get_packet(&pm, 0);
    if (retrieved_packet) {
        printf("Retrieved Packet Payload Size: %zu\n", retrieved_packet->payload_size);
    }

    double avg_payload = calculate_average_payload_size(&pm);
    printf("Average Payload Size: %.2f\n", avg_payload);

    free_packet_manager(&pm);
    return 0;
}
```

