#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS_PER_SESSION 100
#define ERROR_CODE -1
#define SUCCESS_CODE 0

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t mutex;
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t max_elements;
} SessionData;

SessionData* create_session_data(size_t max_elements, unsigned int seed) {
    if (max_elements > MAX_ELEMENTS_PER_SESSION) {
        fprintf(stderr, "Error: Exceeds maximum elements per session.\n");
        return NULL;
    }

    SessionData *session = malloc(sizeof(SessionData));
    if (!session) {
        perror("Failed to allocate memory for SessionData");
        return NULL;
    }

    pthread_mutex_init(&session->mutex, NULL);
    session->max_elements = max_elements;
    session->array = calloc(max_elements, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!session->array) {
        perror("Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T array");
        free(session);
        return NULL;
    }

    srand(seed);

    pthread_mutex_lock(&session->mutex);
    for (size_t i = 0; i < max_elements; ++i) {
        session->array[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        session->array[i].RNTI = rand() % 1000;
        session->array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }
    pthread_mutex_unlock(&session->mutex);

    return session;
}

void delete_session_data(SessionData *session) {
    if (session) {
        pthread_mutex_lock(&session->mutex);
        free(session->array);
        pthread_mutex_unlock(&session->mutex);

        pthread_mutex_destroy(&session->mutex);
        free(session);
    }
}

int verify_data_integrity(const SessionData *session) {
    if (!session || !session->array) return ERROR_CODE;

    pthread_mutex_lock(&session->mutex);
    for (size_t i = 0; i < session->max_elements; ++i) {
        if (session->array[i].RX_UE_INFORMATION_TAG <= 0 ||
            session->array[i].RNTI <= 0 ||
            (session->array[i].CRC_INDICATION_REL8_TAG.CRCFLAG != 0 &&
             session->array[i].CRC_INDICATION_REL8_TAG.CRCFLAG != 1)) {
            pthread_mutex_unlock(&session->mutex);
            return ERROR_CODE;
        }
    }
    pthread_mutex_unlock(&session->mutex);

    return SUCCESS_CODE;
}

void batch_process(SessionData *session, size_t batch_size) {
    if (!session || !session->array) return;

    pthread_mutex_lock(&session->mutex);
    for (size_t i = 0; i < session->max_elements; i += batch_size) {
        size_t end_index = (i + batch_size > session->max_elements) ? session->max_elements : i + batch_size;
        printf("Processing batch from %zu to %zu\n", i, end_index);
    }
    pthread_mutex_unlock(&session->mutex);
}
