Design and implement a scalable C library module for managing network interface statistics in a high-performance application. The module should support dynamic addition, update, and retrieval of statistics for network interfaces. Each entry in the module should include fields for interface name, packet count, byte count, and a timestamp for the last update. The module must handle concurrent access from multiple threads without introducing significant latency or overhead during high-frequency updates and retrievals.

**Design Challenges**:
- Efficiently manage memory for dynamic arrays and ensure robustness against memory allocation failures.
- Implement thread-safe operations to handle concurrent access from multiple threads without using excessive locking mechanisms that could degrade performance.
- Optimize for low-latency updates and retrievals to meet real-time monitoring requirements.
- Minimize the impact of frequent updates on system resources and performance.

**Engineering Tradeoffs**:
- Balance between memory usage and performance by carefully managing memory allocations and deallocations.
- Decide between using lock-free data structures or fine-grained locking to achieve thread safety while minimizing contention.
- Consider the trade-off between simplicity and performance when implementing data structures and synchronization mechanisms.

**Demonstrative Examples**:
- **Unsafe Code Example**:
  ```c
  void addInterfaceStats(char* name, int packets, int bytes) {
      for (int i = 0; i < numEntries; i++) {
          if (strcmp(interfaceStats[i].name, name) == 0) {
              interfaceStats[i].packets += packets;
              interfaceStats[i].bytes += bytes;
              interfaceStats[i].lastUpdate = getCurrentTime();
              return;
          }
      }
      // Memory allocation failure is ignored for simplicity
      interfaceStats[numEntries++] = {name, packets, bytes, getCurrentTime()};
  }
  ```

- **Safe Code Example**:
  Use a lock-free data structure or fine-grained locking mechanism to ensure thread safety and minimize latency.

column3:
['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

#define INITIAL_CAPACITY 16

typedef struct {
    char *name;
    atomic_int packets;
    atomic_int bytes;
    time_t lastUpdate;
} InterfaceStats;

typedef struct {
    InterfaceStats *entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock; // For resizing and managing the array
} StatsManager;

// Function to get current timestamp
time_t getCurrentTime() {
    return time(NULL);
}

// Initialize the stats manager
void initStatsManager(StatsManager *manager) {
    manager->entries = (InterfaceStats *)malloc(INITIAL_CAPACITY * sizeof(InterfaceStats));
    if (!manager->entries) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

// Resize the array when capacity is reached
void resizeStatsManager(StatsManager *manager) {
    pthread_mutex_lock(&manager->lock);

    size_t newCapacity = manager->capacity * 2;
    InterfaceStats *newEntries = (InterfaceStats *)realloc(manager->entries, newCapacity * sizeof(InterfaceStats));
    if (!newEntries) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }

    manager->entries = newEntries;
    manager->capacity = newCapacity;

    pthread_mutex_unlock(&manager->lock);
}

// Add or update interface statistics
void addOrUpdateInterfaceStats(StatsManager *manager, const char *name, int packets, int bytes) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->entries[i].name, name) == 0) {
            atomic_fetch_add(&(manager->entries[i].packets), packets);
            atomic_fetch_add(&(manager->entries[i].bytes), bytes);
            manager->entries[i].lastUpdate = getCurrentTime();
            return;
        }
    }

    // Entry not found, add a new one
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        resizeStatsManager(manager);
    }

    InterfaceStats *entry = &manager->entries[manager->count++];
    entry->name = strdup(name);  // Ensure name is copied and managed
    atomic_store(&(entry->packets), packets);
    atomic_store(&(entry->bytes), bytes);
    entry->lastUpdate = getCurrentTime();

    pthread_mutex_unlock(&manager->lock);
}

// Retrieve interface statistics
InterfaceStats *getInterfaceStats(StatsManager *manager, const char *name) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->entries[i].name, name) == 0) {
            return &manager->entries[i];
        }
    }
    return NULL;
}

// Free the stats manager
void freeStatsManager(StatsManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->entries[i].name);
    }
    free(manager->entries);
    pthread_mutex_destroy(&manager->lock);
}
```

This implementation provides a scalable and thread-safe module for managing network interface statistics. It uses atomic operations to handle frequent updates, minimizing the need for locking during individual read/write operations, while resizing the internal array is protected with a mutex to ensure data consistency. This design allows efficient concurrent access in high-performance environments.']

