#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <arpa/inet.h>
#include <unistd.h>

#define MAX_CLIENTS 100

typedef struct {
    char client_ip[INET_ADDRSTRLEN];
    int port;
    unsigned long connection_id;
} TCP_CONNECTION_INFO;

pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

int is_valid_file(const char *path) {
    return access(path, F_OK) != -1 && access(path, R_OK) == 0;
}

unsigned long generate_unique_connection_id() {
    // Simple example using time and random
    return (unsigned long)(time(NULL)) ^ rand();
}

void initialize_connections_and_process_files(TCP_CONNECTION_INFO *connections, int num_clients) {
    pthread_t threads[MAX_CLIENTS];
    int thread_count = 0;

    struct sockaddr_in addr;
    for (int i = 0; i < num_clients; ++i) {
        addr.sin_family = AF_INET;
        inet_pton(AF_INET, "192.168.1.1", &addr.sin_addr);
        addr.sin_port = htons(rand() % 65536);

        pthread_mutex_lock(&list_mutex);
        strcpy(connections[i].client_ip, inet_ntoa(addr.sin_addr));
        connections[i].port = ntohs(addr.sin_port);
        connections[i].connection_id = generate_unique_connection_id();
        pthread_mutex_unlock(&list_mutex);
    }

    void *process_file(void *arg) {
        char file_path[256];
        int largest_number = -1;

        while (fgets(file_path, sizeof(file_path), stdin)) {
            file_path[strcspn(file_path, "\n")] = '\0';
            if (!is_valid_file(file_path))
                continue;

            long number;
            const char *token = strtok(file_path, "_.");
            while (token) {
                if (sscanf(token, "%ld", &number) == 1 && number > largest_number)
                    largest_number = number;
                token = strtok(NULL, "_.");
            }
        }

        printf("Largest number found: %d\n", largest_number);
        return NULL;
    }

    for (int i = 0; i < num_clients; ++i) {
        if (pthread_create(&threads[thread_count++], NULL, process_file, NULL)) {
            fprintf(stderr, "Error creating thread\n");
            exit(1);
        }
    }

    for (int i = 0; i < thread_count; ++i)
        pthread_join(threads[i], NULL);
}

int main() {
    TCP_CONNECTION_INFO connections[MAX_CLIENTS];
    initialize_connections_and_process_files(connections, MAX_CLIENTS);

    return 0;
}
