typedef struct {
    time_t timestamp;
    int status;
    char* description;
} DataItem;

DataItem* initialize_data_items(size_t count, const int *initial_statuses, size_t status_count) {
    if (!count || !status_count) return NULL;

    DataItem* items = (DataItem*)malloc(count * sizeof(DataItem));
    if (!items) {
        log_message("Memory allocation failed for data items array");
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        items[i].timestamp = time(NULL); // Set current timestamp
        items[i].status = (i < status_count) ? initial_statuses[i] : -1; // Default status if not enough provided

        size_t desc_size = strlen(items[i].description) + 1;
        items[i].description = (char*)malloc(256);
        if (!items[i].description) {
            log_message("Memory allocation failed for description");
            return NULL;
        }

        // Copy the string safely, ensuring no buffer overflow
        strncpy(items[i].description, "default description", 255);
        items[i].description[255] = '\0'; // Ensure null-termination
    }

    return items;
}

void free_data_items(DataItem* items, size_t count) {
    if (!items) return;

    for (size_t i = 0; i < count; ++i) {
        free(items[i].description);
    }

    free(items);
}

// Example usage
int main() {
    int initial_statuses[] = {1, 2, 3}; // Sample statuses
    size_t num_items = 5;

    DataItem* data_items = initialize_data_items(num_items, initial_statuses, sizeof(initial_statuses) / sizeof(initial_statuses[0]));
    if (data_items) {
        // Do something with the initialized items
        free_data_items(data_items, num_items);
    }

    return 0;
}
