#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>

#define MAX_RNTI 16383

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to generate a random number within a range
uint16_t rand_range(uint16_t min, uint16_t max) {
    return (rand() % (max - min + 1)) + min;
}

// Thread function for batch processing
void* populate_pdu_batch(void* arg) {
    int batch_size = *(int*)arg;
    NFAPI_CRC_INDICATION_PDU_T* pdus = malloc(batch_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (pdus == NULL) return NULL;

    for (int i = 0; i < batch_size; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = rand_range(1, MAX_RNTI);
        pdus[i].RNTI = rand_range(1, MAX_RNTI);
        // Simulate setting CRC_INDICATION_REL8_TAG with CRCFLAG
    }

    return (void*)pdus;
}

// Main function to generate and populate the list of structures
void generate_nfaapi_crc_indication_pdus(const char* config_path, size_t num_structures, uint16_t rnti_range_min, 
                                         uint16_t rnti_range_max, double crcflag_prob) {
    srand(time(NULL));

    int num_threads = 4;
    pthread_t threads[num_threads];
    void* results[num_threads];

    // Determine batch size per thread
    int batch_size = (int)(num_structures / num_threads);

    for (int i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, populate_pdu_batch, &batch_size);
    }

    NFAPI_CRC_INDICATION_PDU_T* all_pdus = malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    size_t offset = 0;
    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], &results[i]);

        NFAPI_CRC_INDICATION_PDU_T* batch_pdus = (NFAPI_CRC_INDICATION_PDU_T*)results[i];
        memcpy(all_pdus + offset, batch_pdus, batch_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        free(batch_pdus);

        offset += batch_size;
    }

    // Replace placeholders in the configuration file
    FILE* config_file = fopen(config_path, "w");
    if (config_file == NULL) return;

    for (size_t i = 0; i < num_structures; ++i) {
        fprintf(config_file, "{RX_UE_INFORMATION_TAG: %u, RNTI: %u}\n", 
                all_pdus[i].RX_UE_INFORMATION_TAG, all_pdus[i].RNTI);
    }

    fclose(config_file);

    // Add a new line with an encrypted password using sed
    char command[256];
    snprintf(command, sizeof(command), "sed -i 's|PLACEHOLDER_PASSWORD|ENCRYPTED_PASSWORD|' %s", config_path);
    system(command);

    free(all_pdus);
}
