    char rrm_config[256];
    time_t last_active;
} LTE_UE_Context;

// Define a node for linked list operations
typedef struct Node {
    LTE_UE_Context context;
    struct Node* next;
} Node;

// Define the manager structure for UE contexts
typedef struct {
    Node* head;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
} UE_Context_Manager;

// Initialize the UE context manager
void init_manager(UE_Context_Manager* manager) {
    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->cond_var, NULL);
}

// Add a new UE context
void add_ue_context(UE_Context_Manager* manager, LTE_UE_Context context) {
    pthread_mutex_lock(&manager->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory");
        pthread_mutex_unlock(&manager->lock);
        return;
    }
    new_node->context = context;
    new_node->next = manager->head;
    manager->head = new_node;

    pthread_mutex_unlock(&manager->lock);
}

// Remove a UE context by UE ID
void remove_ue_context(UE_Context_Manager* manager, int ue_id) {
    pthread_mutex_lock(&manager->lock);

    Node *current = manager->head, *prev = NULL;
    while (current != NULL && current->context.ue_id != ue_id) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    if (prev == NULL) {
        manager->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    pthread_mutex_unlock(&manager->lock);
}

// Retrieve a UE context by UE ID
LTE_UE_Context* get_ue_context(UE_Context_Manager* manager, int ue_id) {
    pthread_mutex_lock(&manager->lock);

    Node *current = manager->head;
    while (current != NULL && current->context.ue_id != ue_id) {
        current = current->next;
    }

    LTE_UE_Context* context = (current == NULL) ? NULL : &current->context;

    pthread_mutex_unlock(&manager->lock);
    return context;
}

// Periodically prune inactive UE contexts
void prune_inactive_contexts(UE_Context_Manager* manager, time_t timeout) {
    pthread_mutex_lock(&manager->lock);

    Node *current = manager->head, *prev = NULL;
    while (current != NULL) {
        if (difftime(time(NULL), current->context.last_active) > timeout) {
            Node* to_delete = current;
            current = current->next;

            if (prev == NULL) {
                manager->head = current;
            } else {
                prev->next = current;
            }

            free(to_delete);
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

// Update cell identities from an external data source
void update_cell_identities(UE_Context_Manager* manager, int new_cell_identity) {
    pthread_mutex_lock(&manager->lock);

    Node *current = manager->head;
    while (current != NULL) {
        current->context.cell_identity = new_cell_identity;
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
}

// Save and restore contexts for system restarts or crashes
void save_contexts(UE_Context_Manager* manager, const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    pthread_mutex_lock(&manager->lock);

    Node *current = manager->head;
    while (current != NULL) {
        fwrite(&(current->context), sizeof(LTE_UE_Context), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
    fclose(file);
}

void restore_contexts(UE_Context_Manager* manager, const char* filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    LTE_UE_Context context;

    pthread_mutex_lock(&manager->lock);

    // Clear existing contexts
    Node *current = manager->head;
    while (current != NULL) {
        Node *to_delete = current;
        current = current->next;
        free(to_delete);
    }
    manager->head = NULL;

    // Load contexts from file
    while (fread(&context, sizeof(LTE_UE_Context), 1, file)) {
        add_ue_context(manager, context);
    }

    pthread_mutex_unlock(&manager->lock);
    fclose(file);
}

// Main function to demonstrate usage
int main() {
    UE_Context_Manager manager;
    init_manager(&manager);

    LTE_UE_Context context = {1, 1001, "Config1", time(NULL)};
    add_ue_context(&manager, context);

    LTE_UE_Context* retrieved_context = get_ue_context(&manager, 1);
    if (retrieved_context) {
        printf("Retrieved UE ID: %d\n", retrieved_context->ue_id);
    }

    prune_inactive_contexts(&manager, 300); // Prune contexts inactive for more than 5 minutes
    update_cell_identities(&manager, 1002);

    save_contexts(&manager, "contexts.dat");
    restore_contexts(&manager, "contexts.dat");

    remove_ue_context(&manager, 1);

    return 0;
}
```

