#define MAX_STRUCTURES 10000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t count;
    pthread_mutex_t lock;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) {
        fprintf(stderr, "Failed to allocate memory for list\n");
        return NULL;
    }
    list->head = list->tail = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_list(List* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int is_valid_rnti(uint16_t rnti) {
    return rnti <= 65535;
}

void insert_node(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (!is_valid_rnti(data.RNTI)) {
        fprintf(stderr, "Invalid RNTI value\n");
        return;
    }

    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Failed to allocate memory for node\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }
    new_node->data = data;
    new_node->next = NULL;

    if (!list->head || list->count < MAX_STRUCTURES) {
        if (list->tail) {
            list->tail->next = new_node;
        } else {
            list->head = new_node;
        }
        list->tail = new_node;
        list->count++;
    }

    pthread_mutex_unlock(&list->lock);
}

void delete_node(List* list, uint16_t rnti) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current) {
        if (current->data.RNTI == rnti) {
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }
            if (current == list->tail) {
                list->tail = prev;
            }
            free(current);
            list->count--;
            pthread_mutex_unlock(&list->lock);
            return;
        }
        prev = current;
        current = current->next;
    }

    fprintf(stderr, "RNTI not found\n");
    pthread_mutex_unlock(&list->lock);
}

void serialize_list(const List* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    pthread_mutex_lock((pthread_mutex_t*)&list->lock);

    size_t count = list->count;
    fwrite(&count, sizeof(count), 1, file);
    Node* current = list->head;
    while (current) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
    fclose(file);
}

void deserialize_list(List* list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }

    pthread_mutex_lock(&list->lock);

    size_t count;
    fread(&count, sizeof(count), 1, file);
    while (count--) {
        NFAPI_CRC_INDICATION_PDU_T data;
        fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        insert_node(list, data);
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
}
