static void load_state_from_disk(UE_Context_Array* array);
static void update_cell_identities(UE_Context_Array* array);

// Function to initialize the context array
void init_ue_context_array(UE_Context_Array* array) {
    pthread_mutex_init(&array->lock, NULL);
    array->head = NULL;
    array->size = 0;
    load_state_from_disk(array); // Load state on initialization
}

// Add a new UE Context
int add_ue_context(UE_Context_Array* array, LTE_UE_Context context) {
    pthread_mutex_lock(&array->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1;

    new_node->context = context;
    new_node->next = array->head;
    array->head = new_node;
    array->size++;

    save_state_to_disk(array); // Save state on addition

    pthread_mutex_unlock(&array->lock);
    return 0;
}

// Remove a UE Context by ID
int remove_ue_context(UE_Context_Array* array, int ue_id) {
    pthread_mutex_lock(&array->lock);

    Node **curr = &array->head, *temp = NULL;

    while (*curr) {
        if ((*curr)->context.ue_id == ue_id) {
            temp = *curr;
            *curr = temp->next;
            free(temp);
            array->size--;

            save_state_to_disk(array); // Save state on removal

            pthread_mutex_unlock(&array->lock);
            return 0;
        }
        curr = &(*curr)->next;
    }

    pthread_mutex_unlock(&array->lock);
    return -1; // UE ID not found
}

// Retrieve a UE Context by ID
LTE_UE_Context* get_ue_context(UE_Context_Array* array, int ue_id) {
    pthread_mutex_lock(&array->lock);

    Node* curr = array->head;
    while (curr) {
        if (curr->context.ue_id == ue_id) {
            pthread_mutex_unlock(&array->lock);
            return &curr->context;
        }
        curr = curr->next;
    }

    pthread_mutex_unlock(&array->lock);
    return NULL; // UE ID not found
}

// Periodically prune inactive contexts
void* prune_inactive_contexts(void* arg) {
    UE_Context_Array* array = (UE_Context_Array*)arg;

    while (1) {
        sleep(60); // Run every minute

        pthread_mutex_lock(&array->lock);

        Node **curr = &array->head, *temp;
        time_t now = time(NULL);

        while (*curr) {
            if ((now - (*curr)->context.last_activity_timestamp) > ACTIVE_THRESHOLD) {
                temp = *curr;
                *curr = temp->next;
                free(temp);
                array->size--;
            } else {
                curr = &(*curr)->next;
            }
        }

        save_state_to_disk(array); // Save state after pruning

        pthread_mutex_unlock(&array->lock);
    }
}

// Periodically update cell identities from external data source
void* update_cell_identities_task(void* arg) {
    UE_Context_Array* array = (UE_Context_Array*)arg;

    while (1) {
        sleep(300); // Run every 5 minutes

