['Below is a C implementation for managing a dynamically allocated array of LTE UE Context structures with thread-safe operations, efficient memory management, and periodic pruning of inactive contexts.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define INACTIVITY_THRESHOLD_SECONDS 300

typedef struct {
    int ue_id;
    int cell_identity;
    float signal_strength;
    time_t last_active_timestamp;
    // Add other RRM configuration parameters here
} UEContext;

typedef struct {
    UEContext *contexts;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
    float average_signal_strength;
    int update_frequency;
} UEContextManager;

UEContextManager* create_ue_context_manager() {
    UEContextManager *manager = (UEContextManager *)malloc(sizeof(UEContextManager));
    manager->contexts = (UEContext *)calloc(INITIAL_CAPACITY, sizeof(UEContext));
    manager->capacity = INITIAL_CAPACITY;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->cond_var, NULL);
    manager->average_signal_strength = 0.0f;
    manager->update_frequency = 0;
    return manager;
}

void resize_contexts(UEContextManager *manager) {
    size_t new_capacity = manager->capacity * 2;
    UEContext *new_array = (UEContext *)realloc(manager->contexts, new_capacity * sizeof(UEContext));
    if (!new_array) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }
    manager->contexts = new_array;
    manager->capacity = new_capacity;
}

void add_ue_context(UEContextManager *manager, UEContext context) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size == manager->capacity) {
        resize_contexts(manager);
    }

    manager->contexts[manager->size++] = context;

    // Update statistics
    manager->average_signal_strength =
        ((manager->average_signal_strength * manager->update_frequency) + context.signal_strength) / 
        (manager->update_frequency + 1);
    manager->update_frequency++;

    pthread_cond_broadcast(&manager->cond_var);

    pthread_mutex_unlock(&manager->lock);
}

void remove_ue_context(UEContextManager *manager, int ue_id) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->contexts[i].ue_id == ue_id) {
            // Shift elements to the left
            memmove(&manager->contexts[i], &manager->contexts[i + 1],
                    (manager->size - i - 1) * sizeof(UEContext));
            manager->size--;
            break;
        }
    }

    pthread_cond_broadcast(&manager->cond_var);

    pthread_mutex_unlock(&manager->lock);
}

void prune_inactive_contexts(UEContextManager *manager, time_t current_time) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size;) {
        if (difftime(current_time, manager->contexts[i].last_active_timestamp) > INACTIVITY_THRESHOLD_SECONDS) {
            memmove(&manager->contexts[i], &manager->contexts[i + 1],
                    (manager->size - i - 1) * sizeof(UEContext));
            manager->size--;
        } else {
            ++i;
        }
    }

    pthread_cond_broadcast(&manager->cond_var);

    pthread_mutex_unlock(&manager->lock);
}

void* periodic_pruning(void *arg) {
    UEContextManager *manager = (UEContextManager *)arg;

    while (1) {
        sleep(INACTIVITY_THRESHOLD_SECONDS / 2); // Prune every half the threshold time
        prune_inactive_contexts(manager, time(NULL));
    }

    return NULL;
}

void report_ue_context_state(UEContextManager *manager) {
    pthread_mutex_lock(&manager->lock);

    int active_count = 0;
    for (size_t i = 0; i < manager->size; ++i) {
        if (difftime(time(NULL), manager->contexts[i].last_active_timestamp) <= INACTIVITY_THRESHOLD_SECONDS) {
            active_count++;
        }
    }

    printf("Active UE Contexts: %d\n", active_count);
    printf("Inactive UE Contexts: %zu - %d\n", manager->size, active_count);
    printf("Average Signal Strength: %.2f dBm\n", manager->average_signal_strength);

    pthread_mutex_unlock(&manager->lock);
}

void free_ue_context_manager(UEContextManager *manager) {
    pthread_mutex_destroy(&manager->lock);
    pthread_cond_destroy(&manager->cond_var);
    free(manager->contexts);
    free(manager);
}
```

### Key Points:
- **Thread Safety**: Mutex and condition variables ensure thread-safe operations.
- **Dynamic Memory Management**: Resizes context array when needed, preventing fragmentation.
- **Periodic Pruning**: Background thread prunes inactive contexts based on a configurable threshold.
- **Reporting**: Provides insights into active/inactive UE contexts and average signal strength.

This implementation is modular, allowing for easy extension or modification. It assumes that the external database interactions are handled elsewhere in your system.']

