bool add_to_list(ListNode** head, unsigned int rnti, unsigned int* count_unique_rntis) {
    if (!head) return false;

    // Check for memory allocation failure
    ListNode* new_node = create_node(rnti);
    if (!new_node) return false;

    // Ensure no two consecutive nodes have the same RNTI
    if (*head && (*head)->data.RNTI == rnti) {
        free(new_node);
        return false;
    }

    // Add to list
    new_node->next = *head;
    *head = new_node;

    // Count unique RNTIs (simple approach)
    ListNode* current = *head;
    bool is_unique = true;
    while (current) {
        if (current->data.RNTI == rnti) {
            is_unique = false;
            break;
        }
        current = current->next;
    }

    if (is_unique) (*count_unique_rntis)++;

    return true;
}

// Helper function to free the linked list
void free_list(ListNode* head) {
    while (head) {
        ListNode* temp = head;
        head = head->next;
        free(temp);
    }
}
