#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int is_rnti_unique(LinkedList* list, unsigned int rnti) {
    Node* current = list->head;
    while (current) {
        if (current->data.RNTI == rnti) return 0;
        current = current->next;
    }
    return 1;
}

int add_pdu(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!is_rnti_unique(list, pdu.RNTI)) {
        fprintf(stderr, "Error: RNTI %u already exists.\n", pdu.RNTI);
        return -1;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for a new node");
        return -1;
    }

    memcpy(&new_node->data, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);

    printf("Successfully added PDU with RNTI %u.\n", pdu.RNTI);
    return 0;
}

int populate_list(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T pdus[], int count) {
    for (int i = 0; i < count; ++i) {
        if (add_pdu(list, pdus[i]) != 0) {
            fprintf(stderr, "Failed to add PDU at index %d.\n", i);
