    if (!list) {
        fprintf(stderr, "Failed to create list.\n");
        return EXIT_FAILURE;
    }

    NFAPI_CRC_INDICATION_PDU_T pdus[5] = {
        {1, 101, 201},
        {2, 102, 202},
        {3, 103, 203},
        {4, 104, 204},
        {5, 105, 205}
    };

    if (populate_list(list, pdus, 5) != 0) {
        destroy_list(list);
        return EXIT_FAILURE;
    }

    // Simulate concurrent access
    pthread_t threads[2];
    for (int i = 0; i < 2; ++i) {
        if (pthread_create(&threads[i], NULL, (void*(*)(void*))populate_list, list) != 0) {
            fprintf(stderr, "Failed to create thread %d.\n", i);
        }
    }

    for (int i = 0; i < 2; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_list(list);
    return EXIT_SUCCESS;
}
