LTE_RRC_ChanInfo* init_dynamic_array(size_t num_entries, float rsrp_min, float rsrp_max) {
    if (num_entries > MAX_ENTRIES || num_entries == 0) {
        fprintf(stderr, "Invalid number of entries\n");
        return NULL;
    }

    pthread_mutex_lock(&lock);

    LTE_RRC_ChanInfo *array = malloc(num_entries * sizeof(LTE_RRC_ChanInfo));
    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    for (size_t i = 0; i < num_entries; ++i) {
        array[i].rrc_scg_config.some_field = rand() % 100; // Initialize with a dummy value
        array[i].cell_id.cell_id = i + 1;

        array[i].phy_rsrp_meas_val = malloc(sizeof(PHY_RSRP测量值));
        if (!array[i].phy_rsrp_meas_val) {
            fprintf(stderr, "Memory allocation failed for PHY_RSRP测量值\n");
            while (i > 0) { // Free previously allocated entries
                free(array[--i].phy_rsrp_meas_val);
            }
            free(array);
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        array[i].phy_rsrp_meas_val->phy_rsrp_value = generate_random_value(rsrp_min, rsrp_max);
    }

    pthread_mutex_unlock(&lock);

    return array;
}

void cleanup_dynamic_array(LTE_RRC_ChanInfo *array, size_t num_entries) {
    if (!array) return;

    for (size_t i = 0; i < num_entries; ++i) {
        free(array[i].phy_rsrp_meas_val);
    }
    free(array);
}
