```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_SESSIONS 1000

typedef struct {
    char session_id[64];
    char auth_token[256];
    time_t last_updated;
} Session;

typedef struct {
    int api_count;
    char api_name[32][128]; // List of active API requests
    time_t timestamps[32];
} ActiveAPISessions;

typedef struct {
    Session sessions[MAX_SESSIONS];
    pthread_mutex_t lock; // For thread safety
    size_t session_count;
} SessionManager;

// Function to initialize the session manager
void init_session_manager(SessionManager *manager) {
    memset(manager, 0, sizeof(SessionManager));
    pthread_mutex_init(&manager->lock, NULL);
}

// Function to add a new session
int add_session(SessionManager *manager, const char *session_id, const char *auth_token) {
    pthread_mutex_lock(&manager->lock);

    if (manager->session_count >= MAX_SESSIONS) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // No space left
    }

    strncpy(manager->sessions[manager->session_count].session_id, session_id, sizeof(manager->sessions[0].session_id));
    strncpy(manager->sessions[manager->session_count].auth_token, auth_token, sizeof(manager->sessions[0].auth_token));
    manager->sessions[manager->session_count].last_updated = time(NULL);

    manager->session_count++;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Function to remove a session by ID
int remove_session(SessionManager *manager, const char *session_id) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->session_count; i++) {
        if (strcmp(manager->sessions[i].session_id, session_id) == 0) {
            memmove(&manager->sessions[i], &manager->sessions[i + 1], 
                    (manager->session_count - i - 1) * sizeof(Session));
            manager->session_count--;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Session not found
}

// Function to update a session's authentication token
int update_session_token(SessionManager *manager, const char *session_id, const char *new_auth_token) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->session_count; i++) {
        if (strcmp(manager->sessions[i].session_id, session_id) == 0) {
            strncpy(manager->sessions[i].auth_token, new_auth_token, sizeof(manager->sessions[0].auth_token));
            manager->sessions[i].last_updated = time(NULL);
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Session not found
}

// Function to add an API request to a session
int add_api_request(SessionManager *manager, const char *session_id, const char *api_name) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->session_count; i++) {
        if (strcmp(manager->sessions[i].session_id, session_id) == 0) {
            for (int j = 0; j < MAX_SESSIONS; j++) {
                if (manager->sessions[i].api_count >= sizeof(manager->sessions[0].api_name) / sizeof(manager->sessions[0].api_name[0])) {
                    pthread_mutex_unlock(&manager->lock);
                    return -1; // No space for more APIs
                }

                if (strcmp(manager->sessions[i].api_name[j], api_name) == 0) {
                    manager->timestamps[j] = time(NULL); // Update timestamp
                    pthread_mutex_unlock(&manager->lock);
                    return 0;
                }
            }

            strncpy(manager->sessions[i].api_name[manager->sessions[i].api_count], api_name, sizeof(manager->sessions[0].api_name[0]));
            manager->timestamps[manager->sessions[i].api_count] = time(NULL);
            manager->sessions[i].api_count++;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Session not found
}

// Function to remove an API request from a session
int remove_api_request(SessionManager *manager, const char *session_id, const char *api_name) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->session_count; i++) {
        if (strcmp(manager->sessions[i].session_id, session_id) == 0) {
            for (int j = 0; j < manager->sessions[i].api_count; j++) {
                if (strcmp(manager->sessions[i].api_name[j], api_name) == 0) {
                    memmove(&manager->sessions[i].api_name[j], &manager->sessions[i].api_name[j + 1],
                            (manager->sessions[i].api_count - j - 1) * sizeof(manager->sessions[0].api_name[0]));
                    memmove(&manager->timestamps[j], &manager->timestamps[j + 1],
                            (manager->sessions[i].api_count - j - 1) * sizeof(time_t));
                    manager->sessions[i].api_count--;
                    pthread_mutex_unlock(&manager->lock);
                    return 0;
                }
            }
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // API not found
}

// Function to clean up the session manager
void cleanup_session_manager(SessionManager *manager) {
    pthread_mutex_destroy(&manager->lock);
}
```

### Key Features:
- **Thread Safety**: Uses `pthread_mutex_t` for concurrent access control.
- **Dynamic Session Management**: Supports adding, removing, and updating sessions with efficient memory management.
- **API Request Handling**: Allows tracking of active API requests per session with timestamps.
- **Error Handling**: Returns error codes to indicate success or failure of operations.

This implementation is designed to be scalable, maintainable, and performant under high load conditions."]

