// Function implementations
void initialize_dynamic_ue_list(DynamicUEList* list, size_t initial_capacity) {
    pthread_mutex_init(&list->lock, NULL);
    list->capacity = initial_capacity;
    list->count = 0;
    list->ues = (UE_Context**)calloc(initial_capacity, sizeof(UE_Context*));
}

void destroy_dynamic_ue_list(DynamicUEList* list) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        free(list->ues[i]->active_connections);
        free(list->ues[i]);
    }
    free(list->ues);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int add_ue_context(DynamicUEList* list, UE_Context* ue_context) {
    pthread_mutex_lock(&list->lock);

    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        UE_Context** new_ues = (UE_Context**)realloc(list->ues, new_capacity * sizeof(UE_Context*));

        if (!new_ues) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }

        list->ues = new_ues;
        list->capacity = new_capacity;
    }

    list->ues[list->count++] = ue_context;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

int remove_ue_context(DynamicUEList* list, int ue_id) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->ues[i]->UE_ID == ue_id) {
            free(list->ues[i]->active_connections);
            free(list->ues[i]);

            // Shift remaining elements
            memmove(&list->ues[i], &list->ues[i + 1],
                    (list->count - i - 1) * sizeof(UE_Context*));
            list->count--;

            pthread_mutex_unlock(&list->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // UE not found
}

int update_ue_context(DynamicUEList* list, int ue_id, UE_Context* updated_context) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->ues[i]->UE_ID == ue_id) {
            free(list->ues[i]->active_connections);

            *list->ues[i] = *updated_context;
            list->ues[i]->active_connections = malloc(updated_context->num_connections * sizeof(RRC_Connection));
            memcpy(list->ues[i]->active_connections, updated_context->active_connections,
                   updated_context->num_connections * sizeof(RRC_Connection));

            pthread_mutex_unlock(&list->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // UE not found
}

void generate_pdu_batch(DynamicUEList* ue_list, NFAPI_CRC_INDICATION_PDU_T** pdu_batch,
                        size_t batch_size, int crc_flag_min, int crc_flag_max) {
    srand(time(NULL));  // Seed for random generation
    *pdu_batch = (NFAPI_CRC_INDICATION_PDU_T*)malloc(batch_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_lock(&ue_list->lock);

    for (size_t i = 0; i < batch_size && ue_list->count > 0; ++i) {
        size_t idx = rand() % ue_list->count;

        (*pdu_batch)[i].rx_ue_information_tag.valid = 1; // Assume valid
        (*pdu_batch)[i].RNTI = ue_list->ues[idx]->P_TMSI;
        (*pdu_batch)[i].crc_indication_rel8_tag.CRCFLAG =
            crc_flag_min + rand() % (crc_flag_max - crc_flag_min + 1);
    }

    pthread_mutex_unlock(&ue_list->lock);
}

void serialize_pdus(NFAPI_CRC_INDICATION_PDU_T* pdus, size_t count, void** serialized_data, size_t* data_size) {
    *data_size = count * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    *serialized_data = malloc(*data_size);

    if (*serialized_data) {
        memcpy(*serialized_data, pdus, *data_size);
    }
}

int undo_last_pdu_batch(void* serialized_data, size_t data_size) {
    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)serialized_data;

    if (!pdus || !data_size) return -1;  // Invalid input

    free(serialized_data);
    return 0;  // Success
}

