#include <stdatomic.h>

#define MAX_ENTRIES 1000000

typedef struct {
    int RSRP_value;
} PHY_RSRP测量值;

typedef struct {
    unsigned long Cell_ID;
    _Atomic unsigned char unique_flag; // For detecting duplicates
} LTE_RRC_ChanInfo;

typedef struct {
    LTE_RRC_ChanInfo* entries;
    size_t size;
    pthread_mutex_t lock;
    atomic_size_t count; // Atomic counter for current number of initialized elements
} DynamicArray;

// Utility functions
int generate_random_rsrp(int min, int max) {
    return rand() % (max - min + 1) + min;
}

int is_valid_rsrp(PHY_RSRP测量值* phy_rsrp) {
    // Implement validation logic
    return phy_rsrp->RSRP_value >= -140; // Example threshold value
}

int check_cell_id_uniqueness(LTE_RRC_ChanInfo* array, size_t count, unsigned long cell_id) {
    for (size_t i = 0; i < count; ++i) {
        if (array[i].Cell_ID == cell_id && atomic_load(&array[i].unique_flag)) {
            return 0;
        }
    }
    return 1;
}

void log_message(const char* message) {
    // Implement logging logic
    printf("%s\n", message);
}

void* initialize_entry(void* arg) {
    DynamicArray* array = (DynamicArray*)arg;
    size_t index = atomic_fetch_add(&array->count, 1);

    if (index >= MAX_ENTRIES) return NULL;

    LTE_RRC_ChanInfo* entry = &array->entries[index];

    pthread_mutex_lock(&array->lock);

    unsigned long cell_id = rand(); // Simulating external API call

    if (!check_cell_id_uniqueness(array->entries, array->count, cell_id)) {
        log_message("Duplicate Cell_ID detected");
        pthread_mutex_unlock(&array->lock);
        return NULL;
    }

    entry->Cell_ID = cell_id;
    atomic_store(&entry->unique_flag, 1);

    PHY_RSRP测量值* phy_rsrp = malloc(sizeof(PHY_RSRP测量值));
    if (!phy_rsrp) {
        log_message("Memory allocation failed");
        pthread_mutex_unlock(&array->lock);
        return NULL;
    }

    int rsrp_value = generate_random_rsrp(-140, -50); // Example range
    phy_rsrp->RSRP_value = rsrp_value;

    if (!is_valid_rsrp(phy_rsrp)) {
        log_message("Invalid RSRP value detected");
        free(phy_rsrp);
        pthread_mutex_unlock(&array->lock);
        return NULL;
    }

    // Assume a function to serialize the data (not implemented here)
    entry->PHY_RSRP测量值 = phy_rsrp;

    log_message("Successfully initialized an LTE_RRC_ChanInfo entry");

    pthread_mutex_unlock(&array->lock);

    return NULL;
}

void init_dynamic_array(DynamicArray* array, size_t initial_size) {
    srand(time(NULL));
    array->entries = calloc(initial_size, sizeof(LTE_RRC_ChanInfo));
    if (!array->entries) {
        fprintf(stderr, "Failed to allocate memory for entries\n");
        exit(EXIT_FAILURE);
    }
    array->size = initial_size;
    pthread_mutex_init(&array->lock, NULL);
    atomic_store(&array->count, 0);

    pthread_t threads[MAX_ENTRIES];
    size_t thread_count = (MAX_ENTRIES < initial_size) ? MAX_ENTRIES : initial_size;

    for (size_t i = 0; i < thread_count; ++i) {
        if (pthread_create(&threads[i], NULL, initialize_entry, array)) {
            fprintf(stderr, "Error creating thread\n");
            exit(EXIT_FAILURE);
        }
    }

    for (size_t i = 0; i < thread_count; ++i) {
        pthread_join(threads[i], NULL);
    }
}

void free_dynamic_array(DynamicArray* array) {
    for (size_t i = 0; i < atomic_load(&array->count); ++i) {
        if (array->entries[i].PHY_RSRP测量值) {
            free(array->entries[i].PHY_RSRP测量值);
        }
    }
    free(array->entries);
    pthread_mutex_destroy(&array->lock);
}

int main() {
    DynamicArray array;
    init_dynamic_array(&array, MAX_ENTRIES);

    // Example operation on the array can be added here

    free_dynamic_array(&array);
    return 0;
}
