#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_ENTRIES 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef void (*CallbackFunction)(NFAPI_CRC_INDICATION_PDU_T* pdu);

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T entries[MAX_ENTRIES];
    int active_entries;
    pthread_mutex_t lock;
    CallbackFunction callback;
} CRCManager;

CRCManager* crc_manager_create(CallbackFunction cb) {
    CRCManager* manager = (CRCManager*)malloc(sizeof(CRCManager));
    if (!manager) return NULL;

    memset(manager, 0, sizeof(CRCManager));
    pthread_mutex_init(&manager->lock, NULL);
    manager->callback = cb;
    for (int i = 0; i < MAX_ENTRIES; ++i) {
        manager->entries[i].RX_UE_INFORMATION_TAG = -1; // Indicates unused entry
    }

    return manager;
}

void crc_manager_destroy(CRCManager* manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);
    free(manager);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

int crc_manager_add_entry(CRCManager* manager, int rx_ue_tag, int rnti) {
    if (!manager || rx_ue_tag < 0 || rnti <= 0 || manager->active_entries >= MAX_ENTRIES)
        return -1;

    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < MAX_ENTRIES; ++i) {
        if (manager->entries[i].RX_UE_INFORMATION_TAG == -1) {
            manager->entries[i].RX_UE_INFORMATION_TAG = rx_ue_tag;
            manager->entries[i].RNTI = rnti;
            manager->entries[i].CRC_INDICATION_REL8_TAG = rand() % 256; // Random CRC flag
            ++manager->active_entries;

            if (manager->callback) {
                manager->callback(&manager->entries[i]);
            }

            pthread_mutex_unlock(&manager->lock);
            return i;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1;
}

NFAPI_CRC_INDICATION_PDU_T* crc_manager_get_entry(CRCManager* manager, int index) {
    if (!manager || index < 0 || index >= MAX_ENTRIES)
        return NULL;

    pthread_mutex_lock(&manager->lock);

    NFAPI_CRC_INDICATION_PDU_T* entry = &manager->entries[index];
    if (entry->RX_UE_INFORMATION_TAG == -1) {
        pthread_mutex_unlock(&manager->lock);
        return NULL;
    }

    pthread_mutex_unlock(&manager->lock);
    return entry;
}

int crc_manager_update_crc(CRCManager* manager, int index) {
    if (!manager || index < 0 || index >= MAX_ENTRIES)
        return -1;

    pthread_mutex_lock(&manager->lock);

    NFAPI_CRC_INDICATION_PDU_T* entry = &manager->entries[index];
    if (entry->RX_UE_INFORMATION_TAG == -1) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    // Simulate external API call and retry logic
    int success = 0, retries = 3;
    while (!success && retries > 0) {
        // Assume api_update_crc_status is a function that updates the CRC status.
        success = api_update_crc_status(entry->RNTI);
        if (!success) {
            --retries;
            // Simulate network delay
            sleep(1); 
        }
    }

    if (manager->callback && success)
        manager->callback(entry);

    pthread_mutex_unlock(&manager->lock);
    return success ? 0 : -1;
}

