#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/types.h>
#include <errno.h>
#include <time.h>

#define MAX_ENTRIES 100000
#define DEFAULT_DIRECTORY "/default/path"
#define CACHE_SIZE 1024

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG crc_tag;
    unsigned int RNTI;
    unsigned int RX_UE_INFORMATION_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct CacheNode {
    char* theme_bitmap;
    time_t last_accessed;
    struct CacheNode* next;
} CacheNode;

CacheNode* cache_head = NULL;
unsigned int cache_count = 0;

void add_to_cache(char* theme_bitmap) {
    if (cache_count >= CACHE_SIZE) {
        // Simple eviction strategy: remove the oldest accessed item
        CacheNode *current = cache_head, *prev = NULL;
        time_t oldest_time = current->last_accessed;
        CacheNode *oldest_node = current;

        while (current != NULL) {
            if (difftime(current->last_accessed, oldest_time) < 0) {
                oldest_time = current->last_accessed;
                oldest_node = current;
            }
            prev = current;
            current = current->next;
        }

        free(oldest_node->theme_bitmap);
        if (prev == NULL) {
            cache_head = oldest_node->next;
        } else {
            prev->next = oldest_node->next;
        }
        free(oldest_node);

        --cache_count;
    }

    CacheNode* new_node = (CacheNode*)malloc(sizeof(CacheNode));
    new_node->theme_bitmap = strdup(theme_bitmap);
    new_node->last_accessed = time(NULL);
    new_node->next = cache_head;
    cache_head = new_node;

    ++cache_count;
}

char* get_from_cache(char* theme_bitmap) {
    CacheNode *current = cache_head;

    while (current != NULL) {
        if (strcmp(current->theme_bitmap, theme_bitmap) == 0) {
            current->last_accessed = time(NULL);
            return strdup(theme_bitmap);
        }
        current = current->next;
    }

    add_to_cache(theme_bitmap);
    return strdup(theme_bitmap);
}

NFAPI_CRC_INDICATION_PDU_T* load_entries(const char *directory, unsigned int *count) {
    DIR *dir;
    struct dirent *ent;
    FILE *file;
    char filepath[256];
    NFAPI_CRC_INDICATION_PDU_T *entries = (NFAPI_CRC_INDICATION_PDU_T*)malloc(MAX_ENTRIES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!entries) {
        perror("Memory allocation failed");
        return NULL;
    }

    unsigned int total_count = 0;

    if ((dir = opendir(directory)) != NULL) {
        while ((ent = readdir(dir)) != NULL && total_count < MAX_ENTRIES) {
            if (ent->d_type == DT_REG) { // Regular files
                snprintf(filepath, sizeof(filepath), "%s/%s", directory, ent->d_name);

                file = fopen(filepath, "r");
                if (!file) continue;

                while (fscanf(file, "%u,%u,%d\n",
                              &entries[total_count].RX_UE_INFORMATION_TAG,
                              &entries[total_count].RNTI,
                              &entries[total_count].crc_tag.CRCFLAG) == 3 && total_count < MAX_ENTRIES) {
                    ++total_count;
                }

                fclose(file);
            }
        }
        closedir(dir);

    } else {
        perror("Unable to open directory");
        free(entries);
        return NULL;
    }

    *count = total_count;
    return entries;
}

void handle_directory_access(const char* path, unsigned int* count) {
    NFAPI_CRC_INDICATION_PDU_T* entries;

    if (access(path, F_OK) != -1) {
        entries = load_entries(path, count);

        // Process each entry for caching or theme bitmap management
        for (unsigned int i = 0; i < *count; ++i) {
            char theme_bitmap[20];
            snprintf(theme_bitmap, sizeof(theme_bitmap), "%u-%u", entries[i].RX_UE_INFORMATION_TAG, entries[i].RNTI);

            get_from_cache(theme_bitmap); // Add to cache
        }

        free(entries);
    } else {
        perror("Directory access failed");
        *count = 0;
    }
}

int main() {
    unsigned int entry_count = 0;

    const char* directory_path = DEFAULT_DIRECTORY; // Can be configured

    handle_directory_access(directory_path, &entry_count);

    // Cleanup cache
    while (cache_head != NULL) {
        CacheNode *temp = cache_head;
        cache_head = cache_head->next;
        free(temp->theme_bitmap);
        free(temp);
    }

    return 0;
}
