#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <pthread.h>

#define MAX_SIZE 1024
#define RETRY_LIMIT 3

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t mutex;
    size_t count;
    NFAPI_CRC_INDICATION_PDU_T *array;
} ConcurrentArray;

void initialize_concurrent_array(ConcurrentArray *concurrentArray) {
    concurrentArray->count = 0;
    concurrentArray->array = malloc(MAX_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&concurrentArray->mutex, NULL);
}

bool resize_if_needed(ConcurrentArray *concurrentArray, size_t new_count) {
    if (new_count > MAX_SIZE) return false;
    if (concurrentArray->count >= new_count) return true;

    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(concurrentArray->array, new_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) return false;

    concurrentArray->array = new_array;
    return true;
}

bool add_pdu(ConcurrentArray *concurrentArray, uint32_t tag, uint16_t rnti) {
    pthread_mutex_lock(&concurrentArray->mutex);

    if (concurrentArray->count >= MAX_SIZE || !resize_if_needed(concurrentArray, concurrentArray->count + 1)) {
        pthread_mutex_unlock(&concurrentArray->mutex);
        return false;
    }

    for (size_t i = 0; i < concurrentArray->count; ++i) {
        if (concurrentArray->array[i].RNTI == rnti) {
            pthread_mutex_unlock(&concurrentArray->mutex);
            return false;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = &concurrentArray->array[concurrentArray->count++];
    pdu->RX_UE_INFORMATION_TAG = tag;
    pdu->RNTI = rnti;
    pdu->CRC_INDICATION_REL8_TAG = rand() % 256;
    pdu->CRCFLAG = rand() % 2;

    pthread_mutex_unlock(&concurrentArray->mutex);
    return true;
}

int fetch_ue_info_and_rnti(uint32_t *tag, uint16_t *rnti) {
    // Simulate fetching data from an external source
    static int attempt = 0;
    if (attempt < RETRY_LIMIT) {
        *tag = rand();
        *rnti = rand() % 65535;
        attempt++;
        return 0; // Success
    }
    return -1; // Simulate failure after retries
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int read_integers(int *array, size_t max_size) {
    int count = 0;
    while (count < max_size && scanf("%d", &array[count]) == 1) {
        ++count;
    }
    return count;
}

int find_largest_integer(const int *array, size_t size) {
    if (size == 0) return -1; // Error value
    int largest = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

int main() {
    ConcurrentArray concurrentArray;
    initialize_concurrent_array(&concurrentArray);

    uint32_t tag;
    uint16_t rnti;
    int retry_delay = 1;

    for (size_t i = 0; i < MAX_SIZE; ++i) {
        while (fetch_ue_info_and_rnti(&tag, &rnti)) {
            log_error("Failed to fetch UE info and RNTI");
            sleep(retry_delay);
            retry_delay *= 2;
            if (retry_delay > RETRY_LIMIT * 1000) return -1; // Max delay exceeded
        }

        if (!add_pdu(&concurrentArray, tag, rnti)) {
            log_error("Failed to add PDU");
            break;
        }
    }

    int integers[MAX_SIZE];
    size_t count = read_integers(integers, MAX_SIZE);
    int largest_integer = find_largest_integer(integers, count);

    printf("Largest integer: %d\n", largest_integer);

    free(concurrentArray.array);
    pthread_mutex_destroy(&concurrentArray.mutex);
    return 0;
}
