#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>

#define MAX_ENTRIES 1000
#define HISTORY_SIZE 100

typedef struct {
    int valid;
    uint16_t rnti;
    uint8_t crc_tag[4];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries[MAX_ENTRIES];
    size_t count;
    pthread_mutex_t lock;
} CRC_Indication_List;

CRC_Indication_List* create_list() {
    CRC_Indication_List* list = (CRC_Indication_List*) malloc(sizeof(CRC_Indication_List));
    memset(list->entries, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * MAX_ENTRIES);
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int add_or_update_entry(CRC_Indication_List* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->lock);

    if (entry.valid == 0 || entry.rnti == 0) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Invalid tags
    }

    for (size_t i = 0; i < list->count; ++i) {
        if (list->entries[i]->rnti == entry.rnti) {
            memcpy(list->entries[i], &entry, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }

    if (list->count >= MAX_ENTRIES) {
        pthread_mutex_unlock(&list->lock);
        return -2; // List is full
    }

    list->entries[list->count] = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memcpy(list->entries[list->count], &entry, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_entry_by_rnti(CRC_Indication_List* list, uint16_t rnti) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->entries[i]->rnti == rnti) {
            NFAPI_CRC_INDICATION_PDU_T* entry = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            memcpy(entry, list->entries[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pthread_mutex_unlock(&list->lock);
            return entry;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void clear_old_entries(CRC_Indication_List* list) {
    pthread_mutex_lock(&list->lock);

    if (list->count > HISTORY_SIZE) {
        size_t excess = list->count - HISTORY_SIZE;
        for (size_t i = 0; i < excess; ++i) {
            free(list->entries[i]);
        }
        memmove(list->entries, list->entries + excess, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (list->count - excess));
        list->count -= excess;
    }

    pthread_mutex_unlock(&list->lock);
}

void serialize_list(CRC_Indication_List* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    pthread_mutex_lock(&list->lock);

    fwrite(&list->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < list->count; ++i) {
        fwrite(list->entries[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
}

void deserialize_list(CRC_Indication_List* list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    pthread_mutex_lock(&list->lock);
    list->count = count;

    for (size_t i = 0; i < count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* entry = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        fread(entry, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        list->entries[i] = entry;
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
}

void destroy_list(CRC_Indication_List* list) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        free(list->entries[i]);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

