#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a structure for LTE_UERadioResourceManagerConfig_t (example fields)
typedef struct {
    int cellID;
    unsigned char CRCFLAG;
} LTE_UERadioResourceManagerConfig_t;

// Structure to manage the dynamic array
typedef struct {
    LTE_UERadioResourceManagerConfig_t *configs;
    size_t capacity;
    size_t count;
    pthread_rwlock_t rwlock;  // Read-write lock for thread safety
} ConfigManager;

#define DEFAULT_CAPACITY 10

// Function prototypes
void initConfigManager(ConfigManager *manager);
int addOrUpdateConfiguration(ConfigManager *manager, int cellID, unsigned char CRCFLAG);
LTE_UERadioResourceManagerConfig_t* getConfiguration(const ConfigManager *manager, int cellID);
int resetCRCFLAGS(ConfigManager *manager, unsigned char defaultState);
void freeConfigManager(ConfigManager *manager);

// Initialize the configuration manager
void initConfigManager(ConfigManager *manager) {
    if (pthread_rwlock_init(&manager->rwlock, NULL) != 0) {
        perror("Failed to initialize rwlock");
        exit(EXIT_FAILURE);
    }
    manager->capacity = DEFAULT_CAPACITY;
    manager->count = 0;
    manager->configs = (LTE_UERadioResourceManagerConfig_t *)malloc(manager->capacity * sizeof(LTE_UERadioResourceManagerConfig_t));
    if (!manager->configs) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
}

// Add or update a configuration
int addOrUpdateConfiguration(ConfigManager *manager, int cellID, unsigned char CRCFLAG) {
    pthread_rwlock_wrlock(&manager->rwlock);

    // Search for existing entry
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->configs[i].cellID == cellID) {
            manager->configs[i].CRCFLAG = CRCFLAG;
            pthread_rwlock_unlock(&manager->rwlock);
            return 1; // Updated
        }
    }

    // Resize if necessary
    if (manager->count >= manager->capacity) {
        size_t newCapacity = manager->capacity * 2;
        LTE_UERadioResourceManagerConfig_t *newConfigs = realloc(manager->configs, newCapacity * sizeof(LTE_UERadioResourceManagerConfig_t));
        if (!newConfigs) {
            pthread_rwlock_unlock(&manager->rwlock);
            perror("Memory allocation failed");
            return -1; // Allocation failure
        }
        manager->configs = newConfigs;
        manager->capacity = newCapacity;
    }

    // Add new configuration
    manager->configs[manager->count].cellID = cellID;
    manager->configs[manager->count].CRCFLAG = CRCFLAG;
    ++manager->count;

    pthread_rwlock_unlock(&manager->rwlock);
    return 0; // Added
}

// Retrieve a configuration by cell ID
LTE_UERadioResourceManagerConfig_t* getConfiguration(const ConfigManager *manager, int cellID) {
    pthread_rwlock_rdlock(&manager->rwlock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->configs[i].cellID == cellID) {
            LTE_UERadioResourceManagerConfig_t *result = malloc(sizeof(LTE_UERadioResourceManagerConfig_t));
            if (!result) {
                perror("Memory allocation failed");
                pthread_rwlock_unlock(&manager->rwlock);
                return NULL; // Allocation failure
            }
            memcpy(result, &manager->configs[i], sizeof(LTE_UERadioResourceManagerConfig_t));
            pthread_rwlock_unlock(&manager->rwlock);
            return result;
        }
    }

    pthread_rwlock_unlock(&manager->rwlock);
    return NULL; // Not found
}

// Reset CRCFLAGS to a default state
int resetCRCFLAGS(ConfigManager *manager, unsigned char defaultState) {
    pthread_rwlock_wrlock(&manager->rwlock);

    int updatedCount = 0;
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->configs[i].CRCFLAG != defaultState) {
            manager->configs[i].CRCFLAG = defaultState;
            ++updatedCount;
        }
    }

    pthread_rwlock_unlock(&manager->rwlock);
    return updatedCount; // Return the number of updates
}

// Free resources associated with the configuration manager
void freeConfigManager(ConfigManager *manager) {
    if (manager->configs) {
        free(manager->configs);
    }
    pthread_rwlock_destroy(&manager->rwlock);
}
