#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct DnsServer {
    char ip[16];
} DnsServer;

typedef struct NicConfig {
    char macAddress[18]; // Format: XX:XX:XX:XX:XX:XX
    char ipAddress[16];  // Format: XXX.XXX.XXX.XXX
    char subnetMask[16]; // Format: XXX.XXX.XXX.XXX
    DnsServer *dnsServers;
    int dnsCount;
    struct NicConfig *prev;
    struct NicConfig *next;
} NicConfig;

typedef struct {
    NicConfig *head;
    NicConfig *tail;
} DoublyLinkedList;

// Initialize the doubly linked list
void initializeList(DoublyLinkedList *list) {
    list->head = NULL;
    list->tail = NULL;
}

// Function to validate IP configuration settings
int isValidIpConfiguration(const char* ipAddress, const char* subnetMask) {
    // Simplified validation logic for illustration purposes
    return 1; // Assume valid for now
}

// Add a NIC configuration to the doubly linked list
void addNicConfig(DoublyLinkedList *list, const NicConfig *config) {
    if (!isValidIpConfiguration(config->ipAddress, config->subnetMask)) {
        fprintf(stderr, "Invalid IP configuration\n");
        return;
    }

    NicConfig *newNode = (NicConfig *)malloc(sizeof(NicConfig));
    if (!newNode) {
        perror("Failed to allocate memory for new NIC configuration");
        return;
    }

    memcpy(newNode->macAddress, config->macAddress, sizeof(config->macAddress));
    memcpy(newNode->ipAddress, config->ipAddress, sizeof(config->ipAddress));
    memcpy(newNode->subnetMask, config->subnetMask, sizeof(config->subnetMask));
    newNode->dnsCount = config->dnsCount;

    newNode->dnsServers = (DnsServer *)malloc(sizeof(DnsServer) * config->dnsCount);
    if (!newNode->dnsServers) {
        perror("Failed to allocate memory for DNS servers");
        free(newNode);
        return;
    }

    for (int i = 0; i < config->dnsCount; ++i) {
        memcpy(&newNode->dnsServers[i], &config->dnsServers[i], sizeof(DnsServer));
    }

    newNode->prev = list->tail;
    newNode->next = NULL;

    if (list->tail != NULL) {
        list->tail->next = newNode;
    } else {
        list->head = newNode;
    }
    list->tail = newNode;
}

// Remove a NIC configuration from the doubly linked list
void removeNicConfig(DoublyLinkedList *list, NicConfig *configToRemove) {
    if (configToRemove == NULL || configToRemove == list->head && configToRemove == list->tail) {
        // List is empty or has only one element which is to be removed
        free(configToRemove->dnsServers);
        free(configToRemove);
        initializeList(list);
        return;
    }

    NicConfig *current = list->head;

    while (current != NULL) {
        if (current == configToRemove) {
            if (current->prev != NULL) {
                current->prev->next = current->next;
            }
            if (current->next != NULL) {
                current->next->prev = current->prev;
            }

            if (current == list->tail) {
                list->tail = current->prev;
            }

            free(current->dnsServers);
            free(current);

            return;
        }
        current = current->next;
    }
}

// Forward iteration over the doubly linked list
void iterateForward(DoublyLinkedList *list, void (*callback)(NicConfig*)) {
    NicConfig *current = list->head;
    while (current != NULL) {
        callback(current);
        current = current->next;
    }
}

// Reverse iteration over the doubly linked list
void iterateReverse(DoublyLinkedList *list, void (*callback)(NicConfig*)) {
    NicConfig *current = list->tail;
    while (current != NULL) {
        callback(current);
        current = current->prev;
    }
}
