        free(list);
        log_message("Memory deallocation for PDU list due to error or limit exceedance.");
    }
    pthread_mutex_unlock(&global_lock);
}

unsigned char* compute_md5_hash(const char *input, int *length) {
    MD5_CTX mdContext;
    unsigned char digest[MD5_DIGEST_LENGTH];

    if (MD5_Init(&mdContext) != 1 || 
        MD5_Update(&mdContext, input, strlen(input)) != 1 ||
        MD5_Final(digest, &mdContext) != 1) {
        log_message("Error computing MD5 hash.");
        *length = 0;
        return NULL;
    }

    unsigned char* hash_str = malloc(MD5_DIGEST_LENGTH * 2 + 1);
    if (hash_str == NULL) {
        log_message("Memory allocation failed for MD5 hash string.");
        *length = 0;
        return NULL;
    }

    for(int i = 0; i < MD5_DIGEST_LENGTH; ++i)
        sprintf(hash_str + (i * 2), "%02x", (unsigned int)digest[i]);

    hash_str[MD5_DIGEST_LENGTH * 2] = '\0';
    *length = MD5_DIGEST_LENGTH * 2;
    log_message("Computed MD5 hash successfully.");

    return hash_str;
}

// Example function to simulate a cache layer
