typedef struct CRC_INDICATION_REL8_TAG {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG; // Assuming this is an integer for simplicity
    int RNTI;                   // Similarly, assuming this is an integer
    CRC_INDICATION_REL8_TAG crc_tag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    pthread_mutex_t lock;
    size_t count;
    const size_t max_capacity;
} CRCLinkedList;

CRCLinkedList* create_linked_list(size_t capacity) {
    CRCLinkedList *list = (CRCLinkedList*)malloc(sizeof(CRCLinkedList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    list->max_capacity = capacity;

    return list;
}

int add_to_list(CRCLinkedList *list, NFAPI_CRC_INDICATION_PDU_T *node) {
    if (!list || !node) return -1;

    pthread_mutex_lock(&list->lock);

    if (list->count >= list->max_capacity) {
        pthread_mutex_unlock(&list->lock);
        // Overflow management: Log or handle the overflow
        fprintf(stderr, "List is at full capacity.\n");
        return -2; // Indicate overflow error
    }

    node->next = list->head;
    list->head = node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* create_node(int rx_ue_info_tag, int rnti) {
    NFAPI_CRC_INDICATION_PDU_T *node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!node) return NULL;

    node->RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    node->RNTI = rnti;
    node->crc_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
    node->next = NULL;

    return node;
}

void free_linked_list(CRCLinkedList *list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *next_node = current->next;
        free(current);
        current = next_node;
    }

    list->head = NULL;
    list->count = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    size_t capacity = 10000;
    CRCLinkedList *list = create_linked_list(capacity);

    if (!list) {
        fprintf(stderr, "Failed to allocate memory for the list.\n");
        return -1;
    }

    for (size_t i = 0; i < capacity + 5; ++i) { // Intentionally exceed capacity
        NFAPI_CRC_INDICATION_PDU_T *node = create_node(i, i);
        if (!node) {
            fprintf(stderr, "Failed to allocate memory for node.\n");
            continue;
        }

        int result = add_to_list(list, node);
        if (result == -2) { // Handle overflow
            free(node); // Node wasn't added, so we need to free it
        }
    }

    free_linked_list(list);

    return 0;
}
