    PHY_TEST_CONFIGURATION phy_test_config;
} LTE_PHY_TEST_FRAME;

typedef struct {
    LTE_PHY_TEST_FRAME *frames;
    size_t count;
    pthread_mutex_t mutex;
} DynamicFrameArray;

DynamicFrameArray* init_dynamic_frame_array() {
    DynamicFrameArray *dfa = malloc(sizeof(DynamicFrameArray));
    if (!dfa) {
        perror("Failed to allocate memory for DynamicFrameArray");
        return NULL;
    }

    dfa->frames = calloc(MAX_FRAMES, sizeof(LTE_PHY_TEST_FRAME));
    if (!dfa->frames) {
        free(dfa);
        perror("Failed to allocate memory for frames");
        return NULL;
    }

    dfa->count = 0;
    pthread_mutex_init(&dfa->mutex, NULL);

    return dfa;
}

int add_frame(DynamicFrameArray *dfa, LTE_PHY_TEST_FRAME frame) {
    if (!dfa || dfa->count >= MAX_FRAMES) {
        fprintf(stderr, "Failed to add frame: array full or invalid pointer\n");
        return -1;
    }

    pthread_mutex_lock(&dfa->mutex);

    dfa->frames[dfa->count++] = frame;

    pthread_mutex_unlock(&dfa->mutex);

    return 0;
}

LTE_PHY_TEST_FRAME get_frame(DynamicFrameArray *dfa, size_t index) {
    if (!dfa || index >= dfa->count) {
        fprintf(stderr, "Failed to retrieve frame: invalid pointer or index\n");
        return (LTE_PHY_TEST_FRAME){};
    }

    pthread_mutex_lock(&dfa->mutex);

    LTE_PHY_TEST_FRAME frame = dfa->frames[index];

    pthread_mutex_unlock(&dfa->mutex);

    return frame;
}

void free_dynamic_frame_array(DynamicFrameArray *dfa) {
    if (!dfa) return;

    if (dfa->frames) {
        free(dfa->frames);
    }

    pthread_mutex_destroy(&dfa->mutex);
    free(dfa);
}
