    size_t count;
    pthread_mutex_t mutex;
} CRCList;

unsigned int generate_random_number(unsigned int max) {
    return rand() % (max + 1);
}

int is_unique(CRCList *list, unsigned int tag, unsigned int rnti) {
    for (size_t i = 0; i < list->count; ++i) {
        if (list->data[i].RX_UE_INFORMATION_TAG == tag || list->data[i].RNTI == rnti) {
            return 0;
        }
    }
    return 1;
}

void resize_list(CRCList *list, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_data) {
        list->data = new_data;
        list->capacity = new_capacity;
    } else {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

void log_structure(const NFAPI_CRC_INDICATION_PDU_T *structure, size_t index, FILE *log_file) {
    if (log_file) {
        fprintf(log_file, "Index: %zu, RX_UE_INFORMATION_TAG: %u, RNTI: %u, CRCFLAG: %d\n",
                index, structure->RX_UE_INFORMATION_TAG, structure->RNTI, generate_random_number(1));
    }
}

int add_structure(CRCList *list, unsigned int max_tag, unsigned int max_rnti) {
    pthread_mutex_lock(&list->mutex);

    if (list->count >= list->capacity) {
        resize_list(list, list->capacity ? list->capacity * 2 : 4);
    }

    NFAPI_CRC_INDICATION_PDU_T new_structure;
    do {
        new_structure.RX_UE_INFORMATION_TAG = generate_random_number(max_tag);
        new_structure.RNTI = generate_random_number(max_rnti);
    } while (!is_unique(list, new_structure.RX_UE_INFORMATION_TAG, new_structure.RNTI));

    list->data[list->count++] = new_structure;
    pthread_mutex_unlock(&list->mutex);

    return 0;
}

CRCList* create_crc_list(size_t initial_capacity) {
    CRCList *list = malloc(sizeof(CRCList));
    if (!list) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    list->data = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroy_crc_list(CRCList *list) {
    if (list) {
        free(list->data);
        pthread_mutex_destroy(&list->mutex);
        free(list);
    }
}

int populate_crc_list(CRCList *list, size_t N, unsigned int max_tag, unsigned int max_rnti, FILE *log_file) {
