        fprintf(stderr, "Requested list size exceeds maximum allowed\n");
        return -1;
    }

    for (size_t i = 0; i < N; ++i) {
        if (add_structure(list, max_tag, max_rnti) != 0) {
            return -1;
        }
        log_structure(&list->data[list->count - 1], list->count - 1, log_file);
    }

    return 0;
}

int main() {
    srand(time(NULL));
    FILE *log_file = fopen("crc_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

