        ListNode* current = lists[i]->head;
        while (current != NULL) {
            ListNode* temp = current;
            current = current->next;
            free(temp);
        }

        pthread_mutex_unlock(&lists[i]->lock);
        pthread_mutex_destroy(&lists[i]->lock);
    }
    free(lists);
}

