} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} List;

List* create_list(size_t initial_capacity) {
    if (initial_capacity == 0) return NULL;

    List *list = malloc(sizeof(List));
    list->elements = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);

    if (!list || !list->elements) {
        free(list);
        return NULL;
    }

    return list;
}

void destroy_list(List *list) {
    if (list) {
        pthread_mutex_destroy(&list->lock);
        free(list->elements);
        free(list);
    }
}

int resize_list(List *list, size_t new_capacity) {
    if (!list || new_capacity == 0) return -1;

    NFAPI_CRC_INDICATION_PDU_T *new_elements = realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_elements) return -1;

    list->capacity = new_capacity;
    list->elements = new_elements;
    return 0;
}

int add_to_list(List *list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity) {
        int resize_result = resize_list(list, list->capacity * 2);
        if (resize_result != 0) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
    }

    list->elements[list->size++] = element;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

NFAPI_CRC_INDICATION_PDU_T generate_random_pdu() {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    srand(time(NULL)); // Seed with current time for randomization
    pdu.RX_UE_INFORMATION_TAG = rand();
    pdu.RNTI = rand();
    pdu.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1

    return pdu;
}

void* thread_function(void *arg) {
    List **lists = (List **)arg;
    size_t num_lists = *(size_t *)arg;

    for (size_t i = 0; i < num_lists; ++i) {
        if (add_to_list(lists[i], generate_random_pdu()) == -1) {
            fprintf(stderr, "Failed to add PDU to list %zu\n", i);
        }
    }

    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <num_lists> <list_size>\n", argv[0]);
        return EXIT_FAILURE;
    }

    size_t num_lists = atoi(argv[1]);
    size_t list_size = atoi(argv[2]);

    if (num_lists == 0 || list_size == 0) {
        fprintf(stderr, "Number of lists and list sizes must be positive.\n");
        return EXIT_FAILURE;
    }

    List **lists = malloc(num_lists * sizeof(List *));
    if (!lists) {
        fprintf(stderr, "Memory allocation failed for lists array\n");
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < num_lists; ++i) {
        lists[i] = create_list(list_size);
        if (!lists[i]) {
            fprintf(stderr, "Failed to allocate list %zu\n", i);
            while (--i >= 0) destroy_list(lists[i]);
            free(lists);
            return EXIT_FAILURE;
        }
    }

    size_t num_threads = 4; // For example
    pthread_t threads[num_threads];

    for (size_t t = 0; t < num_threads; ++t) {
        if (pthread_create(&threads[t], NULL, thread_function, lists)) {
            fprintf(stderr, "Error creating thread\n");
            return EXIT_FAILURE;
        }
    }

    for (size_t t = 0; t < num_threads; ++t) {
        pthread_join(threads[t], NULL);
    }

    for (size_t i = 0; i < num_lists; ++i) {
        destroy_list(lists[i]);
    }

    free(lists);

    return EXIT_SUCCESS;
}
```

