    return da;
}

bool is_rnti_unique(DynamicArray* da, int rnti) {
    for (size_t i = 0; i < da->size; ++i) {
        if (da->array[i].RNTI == rnti) {
            return false;
        }
    }
    return true;
}

void resize_dynamic_array(DynamicArray* da) {
    size_t new_capacity = da->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) return;

    da->array = new_array;
    da->capacity = new_capacity;
}

void add_element(DynamicArray* da, int rx_ue_tag, int rnti) {
    pthread_mutex_lock(&da->lock);

    if (da->size >= da->capacity) {
        resize_dynamic_array(da);
    }

    if (!is_rnti_unique(da, rnti)) {
        pthread_mutex_unlock(&da->lock);
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T new_element = {rx_ue_tag, rnti, generate_random_crc_flag()};
    da->array[da->size++] = new_element;

    pthread_mutex_unlock(&da->lock);
}

NFAPI_CRC_INDICATION_PDU_T* get_element_by_index(DynamicArray* da, size_t index) {
    if (index >= da->size) return NULL;
    return &da->array[index];
}

NFAPI_CRC_INDICATION_PDU_T* get_element_by_tag(DynamicArray* da, int rx_ue_tag) {
    for (size_t i = 0; i < da->size; ++i) {
        if (da->array[i].RX_UE_INFORMATION_TAG == rx_ue_tag) {
            return &da->array[i];
        }
    }
    return NULL;
}

void cleanup_dynamic_array(DynamicArray* da) {
    pthread_mutex_lock(&da->lock);
    free(da->array);
    pthread_mutex_unlock(&da->lock);

