#include <time.h>
#include <sys/resource.h>

typedef struct {
    int value;
} record;

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

size_t memory_management_function(size_t num_elements, long init_offsets[], int init_keys[]) {
    if (num_elements == 0 || !init_offsets || !init_keys) return 0;

    size_t total_records = 0;
    struct rusage usage_before, usage_after;
    clock_t start_time, end_time;
    double cpu_time_used;

    // Get resource usage before allocation
    getrusage(RUSAGE_SELF, &usage_before);

    start_time = clock();

    long *offsets = malloc(num_elements * sizeof(long));
    int *keys = malloc(num_elements * sizeof(int));
    record *records = malloc(num_elements * sizeof(record));

    if (!offsets || !keys || !records) {
        log_error("Memory allocation failed");
        free(offsets);
        free(keys);
        free(records);
        return 0;
    }

    for (size_t i = 0; i < num_elements; ++i) {
        offsets[i] = init_offsets[i];
        keys[i] = init_keys[i];
        records[i].value = rand() % 100 + 1; // Random int between 1 and 100
    }

    total_records = num_elements;

    free(offsets);
    free(keys);
    free(records);

    // Get resource usage after allocation
    getrusage(RUSAGE_SELF, &usage_after);

    end_time = clock();
    cpu_time_used = ((double) (end_time - start_time)) / CLOCKS_PER_SEC;

    printf("Resident Set Size Before: %ld KB\n", usage_before.ru_maxrss);
    printf("Resident Set Size After: %ld KB\n", usage_after.ru_maxrss);
    printf("Time taken for initialization: %.2f seconds\n", cpu_time_used);

    return total_records;
}
