    }

    for (size_t i = 0; i < actualNumStructures; ++i) {
        (*list)[i].RX_UE_INFORMATION_TAG = i + 1;
        (*list)[i].RNTI = rand() % maxRNTIValue + 1;
        (*list)[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        (*list)[i].CRCFLAG = rand() % 2;
    }

