        unsigned char CRCFLAG; // Randomly set
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Custom memory allocator using a simple slab allocation system for demonstration
#define SLAB_SIZE 1024

typedef struct {
    void *slabs[SLAB_SIZE];
    pthread_mutex_t lock;
} SlabAllocator;

SlabAllocator* create_slab_allocator() {
    SlabAllocator *allocator = malloc(sizeof(SlabAllocator));
    pthread_mutex_init(&allocator->lock, NULL);
    for (int i = 0; i < SLAB_SIZE; ++i) {
        allocator->slabs[i] = NULL;
    }
    return allocator;
}

void* slab_alloc(SlabAllocator *allocator, size_t size) {
    pthread_mutex_lock(&allocator->lock);

    for (int i = 0; i < SLAB_SIZE; ++i) {
        if (allocator->slabs[i] == NULL) {
            allocator->slabs[i] = malloc(size);
            pthread_mutex_unlock(&allocator->lock);
            return allocator->slabs[i];
        }
    }

    void *ptr = malloc(size);
    pthread_mutex_unlock(&allocator->lock);
    return ptr;
}

void slab_free(SlabAllocator *allocator, void *ptr) {
    pthread_mutex_lock(&allocator->lock);

    for (int i = 0; i < SLAB_SIZE; ++i) {
        if (allocator->slabs[i] == ptr) {
            allocator->slabs[i] = NULL;
            break;
        }
    }

    free(ptr);
    pthread_mutex_unlock(&allocator->lock);
}

void destroy_slab_allocator(SlabAllocator *allocator) {
    for (int i = 0; i < SLAB_SIZE; ++i) {
        if (allocator->slabs[i]) {
            free(allocator->slabs[i]);
        }
    }
    pthread_mutex_destroy(&allocator->lock);
    free(allocator);
}

// Collection with thread-safe access
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    pthread_rwlock_t rwlock;
} CRCCollection;

CRCCollection* create_collection() {
    CRCCollection *collection = malloc(sizeof(CRCCollection));
    collection->head = NULL;
    pthread_rwlock_init(&collection->rwlock, NULL);
    return collection;
}

void insert_into_collection(CRCCollection *collection, NFAPI_CRC_INDICATION_PDU_T data) {
    Node *new_node = slab_alloc(g_allocator, sizeof(Node));
    new_node->data = data;
    new_node->next = NULL;

    pthread_rwlock_wrlock(&collection->rwlock);
    new_node->next = collection->head;
    collection->head = new_node;
    pthread_rwlock_unlock(&collection->rwlock);
}

void delete_from_collection(CRCCollection *collection, int index) {
    pthread_rwlock_wrlock(&collection->rwlock);

    Node **curr = &collection->head;
    for (int i = 0; i < index && *curr != NULL; ++i) {
        curr = &((*curr)->next);
    }

    if (*curr) {
        Node *to_delete = *curr;
        *curr = to_delete->next;
        slab_free(g_allocator, to_delete);
    }

    pthread_rwlock_unlock(&collection->rwlock);
}

void free_collection(CRCCollection *collection) {
    pthread_rwlock_wrlock(&collection->rwlock);

    Node *current = collection->head;
    while (current != NULL) {
        Node *next_node = current->next;
        slab_free(g_allocator, current);
        current = next_node;
    }

    pthread_rwlock_unlock(&collection->rwlock);
    pthread_rwlock_destroy(&collection->rwlock);
    free(collection);
}

// Random CRCFLAG generation
void generate_random_crc(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 256;
}

// Logging utility
void log_operation(const char *operation, pthread_t thread_id) {
    time_t now;
    time(&now);
    printf("[%s] Operation: %s performed by Thread ID: %lu\n", ctime(&now), operation, (unsigned long)thread_id);
}

// Main function to demonstrate usage
int main() {
    srand(time(NULL));

    g_allocator = create_slab_allocator();
    CRCCollection *collection = create_collection();

    // Simulate thread operations
    pthread_t threads[5];
    for (int i = 0; i < 5; ++i) {
        pthread_create(&threads[i], NULL, (void *(*)(void *))[] (void *arg) -> void* {
            NFAPI_CRC_INDICATION_PDU_T pdu;
            pdu.RX_UE_INFORMATION_TAG = rand() % 1000;
            pdu.RNTI = rand() % 1000;

            generate_random_crc(&pdu);
            insert_into_collection(collection, pdu);

            log_operation("Insert", pthread_self());

            return NULL;
        }, NULL);
    }

    for (int i = 0; i < 5; ++i) {
        pthread_join(threads[i], NULL);
    }

    free_collection(collection);
    destroy_slab_allocator(g_allocator);
    return 0;
}
