    *array = (PHY_FRAME_RX_PDU_T*)calloc(initial_capacity, sizeof(PHY_FRAME_RX_PDU_T));
    if (!*array) return -1;

    for (size_t i = 0; i < initial_capacity; ++i) {
        (*array)[i].tag.SYNC_FLAG = rand() % 2;
        (*array)[i].tag.FRAME_NUMBER = (uint16_t)i;
        (*array)[i].tag.RECEPTION_STATUS = (rand() % 3 == 0) ? -1 : 0; // Random error status
        (*array)[i].data_size = 0;
    }

    return 0;
}

void resize_array(PHY_FRAME_RX_PDU_T** array, size_t* current_capacity) {
    pthread_mutex_lock(&mutex);
    size_t new_capacity = *current_capacity * 2;
    PHY_FRAME_RX_PDU_T* temp = (PHY_FRAME_RX_PDU_T*)realloc(*array, new_capacity * sizeof(PHY_FRAME_RX_PDU_T));
    if (!temp) {
        // Handle realloc failure
        pthread_mutex_unlock(&mutex);
        return;
    }

    for (size_t i = *current_capacity; i < new_capacity; ++i) {
        temp[i].tag.SYNC_FLAG = rand() % 2;
        temp[i].tag.FRAME_NUMBER = (uint16_t)i;
        temp[i].tag.RECEPTION_STATUS = (rand() % 3 == 0) ? -1 : 0;
        temp[i].data_size = 0;
    }

    *array = temp;
    *current_capacity = new_capacity;
    pthread_mutex_unlock(&mutex);
}

