}

int resize_if_needed(NFAPI_CRC_LIST *list) {
    size_t new_capacity = list->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T *)custom_alloc(new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) return -1;

    for (size_t i = 0; i < list->size; ++i) {
        new_data[i] = list->data[i];
    }

    custom_free(list->data);
    list->data = new_data;
    list->capacity = new_capacity;
    return 0;
}

int add_crc_indication(NFAPI_CRC_LIST *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list) return -1;

    pthread_mutex_lock(&list->mutex);

    if (list->size == list->capacity && resize_if_needed(list) != 0) {
        pthread_mutex_unlock(&list->mutex);
        return -2; // Memory allocation failed
    }

    list->data[list->size++] = pdu;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_crc_indication(NFAPI_CRC_LIST *list, size_t index) {
    if (!list || index >= list->size) return NULL;

    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU_T* pdu = &list->data[index];
    pthread_mutex_unlock(&list->mutex);

    return pdu;
}

void remove_crc_indication(NFAPI_CRC_LIST *list, size_t index) {
    if (!list || index >= list->size) return;

    pthread_mutex_lock(&list->mutex);

    for (size_t i = index; i < list->size - 1; ++i) {
        list->data[i] = list->data[i + 1];
    }
    --list->size;

    pthread_mutex_unlock(&list->mutex);
}
