```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define GROWTH_FACTOR 2
#define IDLE_TIMEOUT_SECONDS 30

typedef struct {
    uint64_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI; // Using uint64_t for larger RNTI values
    unsigned char CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    time_t last_active_time;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    double growth_factor; // Allows runtime configuration
    uint64_t total_bandwidth_consumed;
} NFA_List;

void list_init(NFA_List* list, double growth_factor) {
    list->entries = malloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->entries) {
        perror("Failed to allocate initial memory");
        exit(EXIT_FAILURE);
    }
    list->capacity = INITIAL_CAPACITY;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->growth_factor = growth_factor;
    list->total_bandwidth_consumed = 0;
}

void list_destroy(NFA_List* list) {
    pthread_mutex_lock(&list->lock);
    free(list->entries);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

static NFAPI_CRC_INDICATION_PDU_T* ensure_capacity(NFA_List* list) {
    if (list->count < list->capacity) return NULL;

    size_t new_capacity = (size_t)(list->capacity * list->growth_factor);
    NFAPI_CRC_INDICATION_PDU_T* new_entries = realloc(list->entries, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!new_entries) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    list->capacity = new_capacity;
    return new_entries;
}

void add_pdu(NFA_List* list, uint64_t RX_UE_INFORMATION_TAG, uint32_t RNTI,
             unsigned char CRC_INDICATION_REL8_TAG, int CRCFLAG) {
    pthread_mutex_lock(&list->lock);

    ensure_capacity(list);

    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu.RNTI = RNTI;
    pdu.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    pdu.CRCFLAG = CRCFLAG;
    pdu.last_active_time = time(NULL);

    list->entries[list->count++] = pdu;

    pthread_mutex_unlock(&list->lock);
}

void reclaim_inactive_sessions(NFA_List* list) {
    pthread_mutex_lock(&list->lock);

    time_t current_time = time(NULL);
    size_t new_count = 0;
    for (size_t i = 0; i < list->count; ++i) {
        if (current_time - list->entries[i].last_active_time > IDLE_TIMEOUT_SECONDS) continue;

        if (new_count != i) {
            list->entries[new_count] = list->entries[i];
        }
        new_count++;
    }

    list->count = new_count;

    pthread_mutex_unlock(&list->lock);
}

size_t get_active_sessions(NFA_List* list) {
    pthread_mutex_lock(&list->lock);

    size_t active_count = 0;
    time_t current_time = time(NULL);
    for (size_t i = 0; i < list->count; ++i) {
        if (current_time - list->entries[i].last_active_time <= IDLE_TIMEOUT_SECONDS)
            active_count++;
    }

    pthread_mutex_unlock(&list->lock);

    return active_count;
}

uint64_t get_total_bandwidth_consumed(NFA_List* list) {
    pthread_mutex_lock(&list->lock);

    uint64_t total = list->total_bandwidth_consumed;

    pthread_mutex_unlock(&list->lock);

    return total;
}
```

### Key Features:
- **Thread Safety**: Uses `pthread_mutex_t` for synchronization.
- **Dynamic Memory Management**: Efficiently manages memory with dynamic reallocation, using a growth factor that can be configured at runtime.
