#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define SUCCESS 0
#define FAILURE -1

typedef struct {
    long *offsets;
    int *keys;
} Record;

int generate_random(int min, int max) {
    return rand() % (max - min + 1) + min;
}

Record* create_records(size_t num_records, size_t n_offsets, size_t n_keys, int min_value, int max_value, int *error_code) {
    if (num_records == 0 || n_offsets == 0 || n_keys == 0) {
        *error_code = FAILURE;
        return NULL;
    }

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);
    pthread_mutex_lock(&mutex);

    srand(time(NULL));

    Record* records = (Record*)malloc(num_records * sizeof(Record));
    if (!records) {
        *error_code = FAILURE;
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    for (size_t i = 0; i < num_records; ++i) {
        records[i].offsets = (long*)malloc(n_offsets * sizeof(long));
        if (!records[i].offsets) {
            *error_code = FAILURE;
            free(records);
            pthread_mutex_unlock(&mutex);
            return NULL;
        }

        for (size_t j = 0; j < n_offsets; ++j) {
            records[i].offsets[j] = generate_random(0, 1000);
        }

        records[i].keys = (int*)malloc(n_keys * sizeof(int));
        if (!records[i].keys) {
            *error_code = FAILURE;
            free(records[i].offsets);
            for (size_t k = 0; k < i; ++k) {
                free(records[k].offsets);
                free(records[k].keys);
            }
            free(records);
            pthread_mutex_unlock(&mutex);
            return NULL;
        }

        for (size_t j = 0; j < n_keys; ++j) {
            records[i].keys[j] = j + 1;
        }

        int random_value = generate_random(min_value, max_value);
    }

    pthread_mutex_unlock(&mutex);

    *error_code = SUCCESS;
    return records;
}

void free_records(Record* records, size_t num_records) {
    if (!records) return;

    for (size_t i = 0; i < num_records; ++i) {
        if (records[i].offsets) free(records[i].offsets);
        if (records[i].keys) free(records[i].keys);
    }
    free(records);
}

void log_error(const char* message) {
    // Simple logging function, can be expanded to use more sophisticated logging mechanisms
    fprintf(stderr, "Error: %s\n", message);
}
