#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Structure Definitions
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned short CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int minInt;
    int maxInt;
    float minFloat;
    float maxFloat;
} Range;

typedef struct {
    pthread_mutex_t mutex;
    unsigned int seed;
    Range range;
} RandomManager;

// Function Prototypes
void *DynamicArrayManager(void *arg);
int generateRandomInt(RandomManager *manager);
float generateRandomFloat(RandomManager *manager);
const char *RangeToString(const Range *range);

// Dynamic Array Manager Implementation
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T **array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    RandomManager randomManager;
} DynamicArray;

void initializeRandomManager(RandomManager *manager, int minInt, int maxInt, float minFloat, float maxFloat) {
    pthread_mutex_init(&manager->mutex, NULL);
    manager->seed = (unsigned int)time(NULL);
    manager->range.minInt = minInt;
    manager->range.maxInt = maxInt;
    manager->range.minFloat = minFloat;
    manager->range.maxFloat = maxFloat;
}

void cleanupRandomManager(RandomManager *manager) {
    pthread_mutex_destroy(&manager.mutex);
}

int generateRandomInt(RandomManager *manager) {
    pthread_mutex_lock(&manager->mutex);
    srand(manager->seed++);
    int value = rand() % (manager->range.maxInt - manager->range.minInt + 1) + manager->range.minInt;
    pthread_mutex_unlock(&manager->mutex);
    return value;
}

float generateRandomFloat(RandomManager *manager) {
    pthread_mutex_lock(&manager->mutex);
    srand(manager->seed++);
    float value = ((float)rand() / RAND_MAX) * (manager->range.maxFloat - manager->range.minFloat) + manager->range.minFloat;
    pthread_mutex_unlock(&manager->mutex);
    return value;
}

const char *RangeToString(const Range *range) {
    static char buffer[128];
    snprintf(buffer, sizeof(buffer), "Int: [%d, %d], Float: [%f, %f]", range->minInt, range->maxInt, range->minFloat, range->maxFloat);
    return buffer;
}

void initializeDynamicArray(DynamicArray *dynamicArray, size_t initialCapacity) {
    pthread_mutex_init(&dynamicArray->lock, NULL);
    dynamicArray->capacity = initialCapacity;
    dynamicArray->count = 0;
    dynamicArray->array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * initialCapacity);
    initializeRandomManager(&dynamicArray->randomManager, 1, 100, 0.0f, 10.0f); // Example range
}

void cleanupDynamicArray(DynamicArray *dynamicArray) {
    for (size_t i = 0; i < dynamicArray->count; ++i) {
        free(dynamicArray->array[i]);
    }
    free(dynamicArray->array);
    pthread_mutex_destroy(&dynamicArray->lock);
    cleanupRandomManager(&dynamicArray->randomManager);
}

void addElement(DynamicArray *dynamicArray, int rxTag, int rnti) {
    pthread_mutex_lock(&dynamicArray->lock);
    if (dynamicArray->count == dynamicArray->capacity) {
        size_t newCapacity = dynamicArray->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T **newArray = realloc(dynamicArray->array, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * newCapacity);
        if (newArray) {
            dynamicArray->array = newArray;
            dynamicArray->capacity = newCapacity;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T *element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    element->RX_UE_INFORMATION_TAG = rxTag;
    element->RNTI = rnti;
    element->CRC_INDICATION_REL8_TAG = (unsigned short)generateRandomInt(&dynamicArray->randomManager);
    dynamicArray->array[dynamicArray->count++] = element;

    pthread_mutex_unlock(&dynamicArray->lock);
}

void printDynamicArray(DynamicArray *dynamicArray) {
    pthread_mutex_lock(&dynamicArray->lock);
    for (size_t i = 0; i < dynamicArray->count; ++i) {
        printf("Element %zu: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=0x%04X\n",
               i, dynamicArray->array[i]->RX_UE_INFORMATION_TAG,
               dynamicArray->array[i]->RNTI, dynamicArray->array[i]->CRC_INDICATION_REL8_TAG);
    }
    printf("Current Range: %s\n", RangeToString(&dynamicArray->randomManager.range));
    pthread_mutex_unlock(&dynamicArray->lock);
}

void *DynamicArrayManager(void *arg) {
    DynamicArray *dynamicArray = (DynamicArray *)arg;
    for (int i = 0; i < 10; ++i) { // Example usage
        addElement(dynamicArray, rand() % 1000 + 1, rand() % 1000 + 1);
    }
    printDynamicArray(dynamicArray);
    return NULL;
}

// Main function for demonstration purposes
int main() {
    DynamicArray dynamicArray;
    initializeDynamicArray(&dynamicArray, 2);

    pthread_t threads[5];
    for (int i = 0; i < 5; ++i) {
        pthread_create(&threads[i], NULL, DynamicArrayManager, &dynamicArray);
    }

    for (int i = 0; i < 5; ++i) {
        pthread_join(threads[i], NULL);
    }

    cleanupDynamicArray(&dynamicArray);
    return 0;
}
