#define MAX_PAYLOAD_LENGTH 100

typedef struct {
    unsigned int field1;
    unsigned int field2;
} MAC_Header;

typedef struct {
    MAC_Header header;
    char *payload;
    size_t payload_len;
} MAC_PDU;

typedef struct RX_UE_INFORMATION_TAG {
    unsigned int ue_index;
} RX_UE_INFORMATION_TAG;

typedef struct CRC_INDICATION_REL8_TAG {
    unsigned int crcflag;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_info;
    unsigned int rnti;
    CRC_INDICATION_REL8_TAG crc_tag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t array_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

MAC_PDU* allocate_mac_pdu_array(size_t max_size, size_t *num_pdus) {
    MAC_PDU *array = NULL;
    size_t current_size = 0;
    while (current_size < max_size) {
        MAC_PDU pdu;
        pdu.header.field1 = rand();
        pdu.header.field2 = rand();

        size_t payload_len = (rand() % (MAX_PAYLOAD_LENGTH - 10 + 1)) + 10;
        if ((current_size + sizeof(MAC_Header) + payload_len + 1) > max_size)
            break;

        pdu.payload = malloc(payload_len);
        if (!pdu.payload) {
            free(array);
            *num_pdus = 0;
            return NULL;
        }

        memset(pdu.payload, rand() % 256, payload_len); 
        pdu.payload_len = payload_len;
        current_size += sizeof(MAC_Header) + payload_len + 1;

        array = realloc(array, (++*num_pdus) * sizeof(MAC_PDU));
        if (!array) {
            for (size_t i = 0; i < *num_pdus - 1; ++i)
                free(array[i].payload);
            free(array);
            *num_pdus = 0;
            return NULL;
        }

        array[*num_pdus - 1] = pdu;
    }
    return array;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_crc_list(size_t N, size_t *num_elements) {
    NFAPI_CRC_INDICATION_PDU_T *head = NULL, **tail = &head;

    for (size_t i = 0; i < N;) {
        NFAPI_CRC_INDICATION_PDU_T *new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) break;

        new_node->rx_ue_info.ue_index = rand();
        do {
            new_node->rnti = rand() % 10000;
        } while (find_rnti(head, new_node->rnti));

        new_node->crc_tag.crcflag = rand() & 1; // Random CRC flag
        new_node->next = NULL;

        *tail = new_node;
        tail = &new_node->next;
        (*num_elements)++;
    }

    return head;
}

int find_rnti(NFAPI_CRC_INDICATION_PDU_T *head, unsigned int rnti) {
    while (head) {
        if (head->rnti == rnti)
            return 1;
        head = head->next;
    }
    return 0;
}

void serialize_crc_list(const char *filename, NFAPI_CRC_INDICATION_PDU_T *list) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    pthread_mutex_lock(&list_mutex);

    NFAPI_CRC_INDICATION_PDU_T *current = list;
    while (current) {
        fwrite(&current->rx_ue_info, sizeof(RX_UE_INFORMATION_TAG), 1, file);
        fwrite(&current->rnti, sizeof(unsigned int), 1, file);
        fwrite(&current->crc_tag.crcflag, sizeof(current->crc_tag.crcflag), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock(&list_mutex);

    fclose(file);
}

NFAPI_CRC_INDICATION_PDU_T* deserialize_crc_list(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return NULL;
    }

    pthread_mutex_lock(&list_mutex);

    NFAPI_CRC_INDICATION_PDU_T *head = NULL, **tail = &head;

    while (1) {
        RX_UE_INFORMATION_TAG rx_ue_info;
        unsigned int rnti;
        unsigned int crcflag;

        if (fread(&rx_ue_info, sizeof(RX_UE_INFORMATION_TAG), 1, file) != 1 ||
            fread(&rnti, sizeof(unsigned int), 1, file) != 1 ||
            fread(&crcflag, sizeof(crcflag), 1, file) != 1)
            break;

        NFAPI_CRC_INDICATION_PDU_T *new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) {
            free_crc_list(head);
            pthread_mutex_unlock(&list_mutex);
            fclose(file);
            return NULL;
        }

        new_node->rx_ue_info = rx_ue_info;
        new_node->rnti = rnti;
        new_node->crc_tag.crcflag = crcflag;
        new_node->next = NULL;

        *tail = new_node;
        tail = &new_node->next;
    }

    pthread_mutex_unlock(&list_mutex);
    fclose(file);

    return head;
}

void free_crc_list(NFAPI_CRC_INDICATION_PDU_T *head) {
    while (head) {
        NFAPI_CRC_INDICATION_PDU_T *tmp = head;
        head = head->next;
        free(tmp);
    }
}

void free_mac_pdu_array(MAC_PDU *array, size_t num_pdus) {
    pthread_mutex_lock(&array_mutex);

    for (size_t i = 0; i < num_pdus; ++i)
        free(array[i].payload);

    free(array);

    pthread_mutex_unlock(&array_mutex);
}

int main() {
    srand(time(NULL));

    size_t max_array_size = 1024 * 1024; // Example maximum size in bytes
    size_t num_mac_pdus;
    MAC_PDU *mac_pdu_array = allocate_mac_pdu_array(max_array_size, &num_mac_pdus);

    if (mac_pdu_array) {
        free_mac_pdu_array(mac_pdu_array, num_mac_pdus);
