#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_MAX_LIMIT 100
#define MAX_RETRY_ATTEMPTS 5

typedef struct {
    // Define the structure with necessary fields and a CRCFLAG.
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG; 
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t count;
    size_t capacity;
    pthread_rwlock_t lock;
    int max_limit;
} DynamicList;

// Function prototypes
void initialize_list(DynamicList* list, int max_limit);
void free_list(DynamicList* list);
int add_pdu(DynamicList* list, const NFAPI_CRC_INDICATION_PDU_T* pdu);
void update_data_from_source(DynamicList* list);
void *thread_function(void *arg);

// Initialize the dynamic list
void initialize_list(DynamicList* list, int max_limit) {
    pthread_rwlock_init(&list->lock, NULL);
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(max_limit * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->count = 0;
    list->capacity = max_limit;
    list->max_limit = max_limit;
}

// Free the allocated memory
void free_list(DynamicList* list) {
    pthread_rwlock_destroy(&list->lock);
    free(list->data);
}

// Add a new PDU to the dynamic list with retry mechanism and exponential backoff
int add_pdu(DynamicList* list, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    int attempts = 0;
    double backoff_time = 1.0;

    while (attempts < MAX_RETRY_ATTEMPTS) {
        pthread_rwlock_wrlock(&list->lock);

        if (list->count < list->max_limit) {
            list->data[list->count++] = *pdu;
            pthread_rwlock_unlock(&list->lock);
            return 0; // Success
        }

        pthread_rwlock_unlock(&list->lock);

        usleep((useconds_t)(backoff_time * 1000000));
        backoff_time *= 2;
        attempts++;
    }

    return -1; // Failed after retrying
}

