```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <string.h>

// Define structure
typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Hash map entry for storing elements by RNTI
struct HashMapEntry {
    uint16_t RNTI;
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct HashMapEntry* next; // For handling hash collisions using chaining
};

#define HASH_MAP_SIZE 1024

typedef struct {
    struct HashMapEntry** buckets;
    pthread_mutex_t lock; // Mutex for thread safety
} CRCIndicationManager;

// Hash function
static uint32_t hash_function(uint16_t RNTI) {
    return RNTI % HASH_MAP_SIZE;
}

CRCIndicationManager* create_manager() {
    CRCIndicationManager* manager = (CRCIndicationManager*)malloc(sizeof(CRCIndicationManager));
    if (!manager) return NULL;

    manager->buckets = (struct HashMapEntry**)calloc(HASH_MAP_SIZE, sizeof(struct HashMapEntry*));
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu() {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) return NULL;

    // Populate with random values
    pdu->RX_UE_INFORMATION_TAG = rand();
    pdu->RNTI = rand() & 0xFFFF; // Ensure it's within uint16_t range
    pdu->CRC_INDICATION_REL8_TAG = rand() % 256;

    printf("Allocated PDU: RX_UE_INFORMATION_TAG=%u, RNTI=0x%X, CRC_INDICATION_REL8_TAG=%d\n", 
           pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRC_INDICATION_REL8_TAG);
    return pdu;
}

int add_pdu(CRCIndicationManager* manager, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!manager || !pdu) return -1;

    pthread_mutex_lock(&manager->lock);

    uint32_t index = hash_function(pdu->RNTI);
    struct HashMapEntry* entry = manager->buckets[index];

    // Check for existing RNTI
    while (entry) {
        if (entry->data->RNTI == pdu->RNTI) {
            pthread_mutex_unlock(&manager->lock);
            free(pdu); // Clean up allocated PDU on failure to insert
            return -1;
        }
        entry = entry->next;
    }

    struct HashMapEntry* new_entry = (struct HashMapEntry*)malloc(sizeof(struct HashMapEntry));
    if (!new_entry) {
        pthread_mutex_unlock(&manager->lock);
        free(pdu); // Clean up allocated PDU on failure to insert
        return -1;
    }

    new_entry->RNTI = pdu->RNTI;
    new_entry->data = pdu;
    new_entry->next = manager->buckets[index];
    manager->buckets[index] = new_entry;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_pdu_by_index(CRCIndicationManager* manager, size_t index) {
    if (!manager || index >= HASH_MAP_SIZE) return NULL;

    struct HashMapEntry* entry = manager->buckets[index];
    while (entry) {
        pthread_mutex_lock(&manager->lock); // Lock during read
        NFAPI_CRC_INDICATION_PDU_T* pdu = entry->data;
        pthread_mutex_unlock(&manager->lock);

        if (pdu) return pdu;
        entry = entry->next;
    }
    return NULL;
}

void cleanup_manager(CRCIndicationManager* manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < HASH_MAP_SIZE; ++i) {
        struct HashMapEntry* entry = manager->buckets[i];
        while (entry) {
            struct HashMapEntry* next = entry->next;
            free(entry->data);
            free(entry);
            entry = next;
        }
    }

    pthread_mutex_unlock(&manager->lock);

    free(manager->buckets);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int main() {
    srand(time(NULL));
    CRCIndicationManager* manager = create_manager();

    for (int i = 0; i < 10; ++i) { // Example usage
        NFAPI_CRC_INDICATION_PDU_T* pdu = allocate_pdu();
        if (!pdu || add_pdu(manager, pdu)) {
            free(pdu);
        }
    }

    for (size_t i = 0; i < HASH_MAP_SIZE; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = get_pdu_by_index(manager, i);
        if (pdu) {
            printf("Retrieved PDU: RX_UE_INFORMATION_TAG=%u, RNTI=0x%X, CRC_INDICATION_REL8_TAG=%d\n", 
                   pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRC_INDICATION_REL8_TAG);
        }
    }

    cleanup_manager(manager);
    return 0;
}
```

### Key Components:

1. **Hash Map**: Utilized to store `NFAPI_CRC_INDICATION_PDU_T` structures for quick retrieval by `RNTI`. Collision handling is done using chaining.

2. **Thread Safety**: A mutex locks critical sections of code where shared data (the hash map) is accessed or modified, ensuring thread-safe operations.

3. **Custom Allocator**: Each PDU is allocated individually to manage memory efficiently and enable random value assignment for testing purposes.

4. **Logging**: Basic logging via `printf` provides insights into the lifecycle events such as allocation and retrieval of PDUs.

5. **Cleanup Functionality**: Ensures all dynamically allocated memory is freed, preventing leaks.

This implementation strikes a balance between simplicity and performance with a focus on thread safety and efficient resource management.']

