int findMaxInteger(int* array, int size) {
    if (size == 0)
        return INT_MIN; // Consider defining an error code or handling this case as needed.

    int max = array[0];
    for (int i = 1; i < size; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

void processRadioData(int numPDUs, int inputSize) {
    Node* head = NULL;

    // Read integers from standard input
    int* inputArray = malloc(inputSize * sizeof(int));
    if (inputArray == NULL) {
        logMessage("Failed to allocate memory for input array.");
        return;
    }

    printf("Enter %d integers:\n", inputSize);
    for (int i = 0; i < inputSize; ++i) {
        scanf("%d", &inputArray[i]);
    }

    // Determine the maximum integer
    int maxInteger = findMaxInteger(inputArray, inputSize);
    logMessage("Maximum integer found.");

    free(inputArray);

    // Initialize PDUs and store them in a linked list
    for (int i = 0; i < numPDUs; ++i) {
        Node* newNode = malloc(sizeof(Node));
        if (newNode == NULL) {
            logMessage("Failed to allocate memory for PDU node.");
            break;
        }

        // Assign unique values for demonstration purposes, replace with real logic as necessary
        newNode->data.RX_UE_INFORMATION_TAG = rand() % 1000 + i; // Example uniqueness logic
        newNode->data.RNTI = rand() % 1000 + i;
        newNode->data.CRC_INDICATION_REL8_TAG = maxInteger;

        if (head == NULL) {
            head = newNode;
            head->next = NULL;
        } else {
            Node* current = head;
            while (current->next != NULL) {
                // Check for uniqueness within the linked list
                if (current->data.RX_UE_INFORMATION_TAG == newNode->data.RX_UE_INFORMATION_TAG ||
                    current->data.RNTI == newNode->data.RNTI) {
                    logMessage("Duplicate RNTI or RX_UE_INFORMATION_TAG found. Skipping node.");
                    free(newNode);
                    break;
                }
                current = current->next;
            }
            if (current->next == NULL) {
                current->next = newNode;
            }
        }

        logMessage("PDU initialized and added to the list.");
    }

    // Log completion
    logMessage("Radio data processing completed.");

    // Cleanup linked list memory
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    int numPDUs, inputSize;

    printf("Enter the number of PDUs to initialize: ");
    scanf("%d", &numPDUs);

    printf("Enter the size of the integer array: ");
