    int CRCFLAG; // 0 or 1
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_INITIAL_ENTRIES 10000
#define MINIMUM_LIMIT_ADJUSTMENT (MAX_INITIAL_ENTRIES / 10)

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    int priority;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t count;
    size_t max_entries;
    FILE* config_file;
} PduListManager;

// Function prototypes
void init_pdm_list(PduListManager* manager, const char* config_path);
void destroy_pdm_list(PduListManager* manager);
int add_pdu_to_list(PduListManager* manager, NFAPI_CRC_INDICATION_PDU_T pdu, int priority);
int get_system_load_based_limit();
void adjust_max_entries(PduListManager* manager);
void periodic_adjustment_thread(void *arg);

// Initialize the PDU list manager
void init_pdm_list(PduListManager* manager, const char* config_path) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->head = NULL;
    manager->count = 0;
    manager->max_entries = MAX_INITIAL_ENTRIES;
    manager->config_file = fopen(config_path, "r");

    if (pthread_create(&adjustment_thread, NULL, periodic_adjustment_thread, manager) != 0) {
        perror("Failed to create adjustment thread");
    }
}

// Cleanup resources
void destroy_pdm_list(PduListManager* manager) {
    Node* current = manager->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&manager->lock);
    if (manager->config_file) {
        fclose(manager->config_file);
    }
}

// Add a PDU to the list based on priority
int add_pdu_to_list(PduListManager* manager, NFAPI_CRC_INDICATION_PDU_T pdu, int priority) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->max_entries) {
        printf("Maximum entries limit reached. PDU not added.\n");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    Node* current = manager->head;
    while (current && current->data.RNTI != pdu.RNTI) {
        current = current->next;
    }

    if (!current) { // No duplicate RNTI found
        Node* new_node = malloc(sizeof(Node));
        if (!new_node) {
            pthread_mutex_unlock(&manager->lock);
            return -2; // Memory allocation failure
        }

        new_node->data = pdu;
        new_node->priority = priority;
        new_node->next = manager->head;

        while (new_node->next && new_node->next->priority >= priority) {
            Node* temp = new_node->next;
            new_node->next = temp->next;
            temp->next = new_node;
        }

        manager->head = new_node;
        manager->count++;
    } else { // Duplicate RNTI
        printf("Duplicate RNTI found. PDU not added.\n");
    }

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Retrieve system load-based limit
int get_system_load_based_limit() {
    float cpu_usage = get_cpu_usage(); // Assume this function is provided by system_metrics.h
    float memory_available = get_memory_available();

    int new_limit = MAX_INITIAL_ENTRIES;

    if (cpu_usage > 80.0 || memory_available < 200 * 1024 * 1024) { // Less than 200 MB available
        new_limit -= MINIMUM_LIMIT_ADJUSTMENT;
    } else if (cpu_usage < 50.0 && memory_available > 500 * 1024 * 1024) {
        new_limit += MINIMUM_LIMIT_ADJUSTMENT;
    }

    return new_limit > MAX_INITIAL_ENTRIES ? MAX_INITIAL_ENTRIES : 
           new_limit < MINIMUM_LIMIT_ADJUSTMENT ? MINIMUM_LIMIT_ADJUSTMENT : new_limit;
}

// Adjust maximum entries based on system load
void adjust_max_entries(PduListManager* manager) {
    int new_limit = get_system_load_based_limit();
    if (new_limit != manager->max_entries) {
        pthread_mutex_lock(&manager->lock);
        printf("Adjusting max entries from %zu to %d\n", manager->max_entries, new_limit);
        manager->max_entries = new_limit;
        pthread_mutex_unlock(&manager->lock);
    }
}

// Periodic adjustment thread
void* periodic_adjustment_thread(void *arg) {
    PduListManager* manager = (PduListManager*)arg;

    while (1) {
        sleep(5); // Adjust every 5 seconds
        adjust_max_entries(manager);
    }

    return NULL;
}
```

### Explanation

- **Data Structure**: A linked list is used to store the `NFAPI_CRC_INDICATION_PDU_T` structures, with each node also storing a priority level.

- **Thread Safety**: A mutex lock (`pthread_mutex_t`) is utilized for thread-safe operations on the shared data structure.

- **Dynamic Limit Adjustment**: The system periodically checks CPU usage and available memory to adjust the maximum number of entries allowed in the list. This operation runs in a separate thread.

- **Configuration File**: The function assumes access to a configuration file where priority rules can be dynamically updated.

- **Duplicate Handling**: Before adding an entry, it checks for duplicate RNTI values to ensure each appears only once.

- **Resource Deallocation**: While not explicitly implemented here, the structure allows for resource management based on current load conditions. 

This implementation provides a foundation that you can expand upon with more sophisticated error handling and performance logging as needed.']

