#include <pthread.h>

typedef struct {
    int key;
    long *offset_ptr;
} Record;

typedef struct {
    Record **records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} RecordManager;

RecordManager* create_record_manager(size_t initial_capacity) {
    RecordManager *manager = malloc(sizeof(RecordManager));
    manager->records = calloc(initial_capacity, sizeof(Record *));
    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void resize_record_manager(RecordManager *manager) {
    size_t new_capacity = manager->capacity * 2;
    Record **new_records = realloc(manager->records, new_capacity * sizeof(Record *));
    if (new_records != NULL) {
        manager->records = new_records;
        manager->capacity = new_capacity;
    } else {
        perror("Failed to resize record array");
        exit(EXIT_FAILURE);
    }
}

void add_record(RecordManager *manager, int key, long offset) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size >= manager->capacity) {
        resize_record_manager(manager);
    }

    Record *record = malloc(sizeof(Record));
    record->key = key;
    record->offset_ptr = &offset;

    manager->records[manager->size++] = record;

    pthread_mutex_unlock(&manager->lock);
}

void free_record_manager(RecordManager *manager) {
    for (size_t i = 0; i < manager->size; ++i) {
        free(manager->records[i]);
    }
    free(manager->records);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int main() {
    RecordManager *manager = create_record_manager(10);

    // Example usage
    for (int i = 0; i < 15; ++i) {
        add_record(manager, i, (long)i * 1000);
    }

    for (size_t i = 0; i < manager->size; ++i) {
        printf("Key: %d, Offset: %ld\n", manager->records[i]->key, *(manager->records[i]->offset_ptr));
    }

    free_record_manager(manager);
    return 0;
}
