```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define INITIAL_CAPACITY 10

typedef struct {
    int LAYER2_CONTEXT_ID;
    char RRC_CGI[20]; // Example size for a CGI string
    int MAC_STATE; // Representing the priority level
} MAC_CONTEXT;

typedef struct {
    MAC_CONTEXT *array;
    size_t capacity;
    size_t size;
    pthread_rwlock_t lock; // Read-write lock for concurrency management
} MAC_ARRAY;

// Function to initialize the dynamic array
MAC_ARRAY* mac_array_init() {
    MAC_ARRAY *macArray = (MAC_ARRAY*)malloc(sizeof(MAC_ARRAY));
    if (!macArray) return NULL;

    macArray->array = (MAC_CONTEXT*)calloc(INITIAL_CAPACITY, sizeof(MAC_CONTEXT));
    if (!macArray->array) {
        free(macArray);
        return NULL;
    }

    macArray->capacity = INITIAL_CAPACITY;
    macArray->size = 0;

    pthread_rwlock_init(&macArray->lock, NULL);

    return macArray;
}

// Function to add a new MAC_CONTEXT
int mac_array_add(MAC_ARRAY *macArray, int LAYER2_ID, const char *RRC_CGI, int MAC_STATE) {
    if (!macArray || !macArray->array) return -1;

    pthread_rwlock_wrlock(&macArray->lock);

    // Resize array if necessary
    if (macArray->size == macArray->capacity) {
        size_t new_capacity = macArray->capacity * 2;
        MAC_CONTEXT *new_array = (MAC_CONTEXT*)realloc(macArray->array, new_capacity * sizeof(MAC_CONTEXT));

        if (!new_array) {
            pthread_rwlock_unlock(&macArray->lock);
            return -1;
        }

        macArray->array = new_array;
        macArray->capacity = new_capacity;
    }

    // Add the new MAC context
    int index = macArray->size++;
    macArray->array[index].LAYER2_CONTEXT_ID = LAYER2_ID;
    snprintf(macArray->array[index].RRC_CGI, sizeof(macArray->array[index].RRC_CGI), "%s", RRC_CGI);
    macArray->array[index].MAC_STATE = MAC_STATE;

    pthread_rwlock_unlock(&macArray->lock);

    return 0;
}

// Function to retrieve a MAC_CONTEXT by ID
MAC_CONTEXT* mac_array_get(MAC_ARRAY *macArray, int LAYER2_ID) {
    if (!macArray || !macArray->array) return NULL;

    pthread_rwlock_rdlock(&macArray->lock);

    for (size_t i = 0; i < macArray->size; ++i) {
        if (macArray->array[i].LAYER2_CONTEXT_ID == LAYER2_ID) {
            MAC_CONTEXT *context = &macArray->array[i];
            pthread_rwlock_unlock(&macArray->lock);
            return context;
        }
    }

    pthread_rwlock_unlock(&macArray->lock);

    return NULL;
}

// Function to update a MAC_CONTEXT's priority based on ID
int mac_array_update_priority(MAC_ARRAY *macArray, int LAYER2_ID, int new_priority) {
    if (!macArray || !macArray->array) return -1;

    pthread_rwlock_wrlock(&macArray->lock);

    for (size_t i = 0; i < macArray->size; ++i) {
        if (macArray->array[i].LAYER2_CONTEXT_ID == LAYER2_ID) {
            macArray->array[i].MAC_STATE = new_priority;
            pthread_rwlock_unlock(&macArray->lock);
            return 0;
        }
    }

    pthread_rwlock_unlock(&macArray->lock);

    return -1;
}

// Function to clean up resources
void mac_array_cleanup(MAC_ARRAY *macArray) {
    if (!macArray) return;

    pthread_rwlock_wrlock(&macArray->lock);

    free(macArray->array);
    pthread_rwlock_unlock(&macArray->lock);

    pthread_rwlock_destroy(&macArray->lock);
    free(macArray);
}
```

### Key Points:
- **Concurrency**: Utilizes `pthread_rwlock_t` for read-write locks, allowing multiple readers or a single writer, which is beneficial in scenarios with more reads than writes.
- **Dynamic Array Resizing**: Uses `realloc` to dynamically increase the array size when needed. This helps manage memory efficiently under growing loads.
- **Resource Management**: Provides cleanup functions to ensure all allocated resources are released properly to avoid memory leaks.
- **Error Handling**: Returns error codes for failure scenarios, such as failed allocations or invalid operations.

This code structure provides a balance between performance, usability, and maintainability while addressing the real-world challenges outlined.']

