#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Definitions for LTE PHY info tags.
#define MAX_CQI 15
#define MAX_CSIRI 4

typedef struct {
    int cqi_value;
} LTE_PHY_RX_CQI_INFO_TAG;

typedef struct {
    int quiet_period_info;
} LTE_PHY_RX_QUIET_PERIOD_INFO_TAG;

typedef struct {
    int csirri_value;
} LTE_PHY_RX_CSIRI_INFO_TAG;

typedef struct {
    LTE_PHY_RX_CQI_INFO_TAG cqi;
    LTE_PHY_RX_QUIET_PERIOD_INFO_TAG quiet_period;
    LTE_PHY_RX_CSIRI_INFO_TAG csirri;
} LTE_RRC_CUCCH_INDICATION_T;

typedef struct {
    LTE_RRC_CUCCH_INDICATION_T* array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;  // For thread safety.
} DynamicArray;

// Function prototypes
int initDynamicArray(DynamicArray *da, size_t initial_capacity);
int resizeDynamicArray(DynamicArray *da, size_t new_capacity);
int addElement(DynamicArray *da, LTE_RRC_CUCCH_INDICATION_T element);
void freeDynamicArray(DynamicArray *da);
void printStatistics(const DynamicArray *da);

// Function implementations
int initDynamicArray(DynamicArray *da, size_t initial_capacity) {
    pthread_mutex_init(&da->lock, NULL);
    da->array = (LTE_RRC_CUCCH_INDICATION_T *)malloc(initial_capacity * sizeof(LTE_RRC_CUCCH_INDICATION_T));
    if (!da->array) return -1;
    da->size = 0;
    da->capacity = initial_capacity;
    return 0;
}

int resizeDynamicArray(DynamicArray *da, size_t new_capacity) {
    pthread_mutex_lock(&da->lock);
    LTE_RRC_CUCCH_INDICATION_T* temp = realloc(da->array, new_capacity * sizeof(LTE_RRC_CUCCH_INDICATION_T));
    if (!temp) {
        pthread_mutex_unlock(&da->lock);
        return -1;
    }
    da->capacity = new_capacity;
    da->array = temp;
    pthread_mutex_unlock(&da->lock);
    return 0;
}

int addElement(DynamicArray *da, LTE_RRC_CUCCH_INDICATION_T element) {
    if (element.cqi.cqi_value < 0 || element.cqi.cqi_value > MAX_CQI ||
        element.csirri.csirri_value < 0 || element.csirri.csirri_value > MAX_CSIRI) {
        return -1; // Invalid value
    }

    pthread_mutex_lock(&da->lock);
    if (da->size == da->capacity) {
        size_t new_capacity = da->capacity * 2;
        if (resizeDynamicArray(da, new_capacity) != 0) {
            pthread_mutex_unlock(&da->lock);
            return -1; // Resizing failed
        }
    }
    da->array[da->size] = element;
    da->size++;
    pthread_mutex_unlock(&da->lock);
    return 0;
}

void freeDynamicArray(DynamicArray *da) {
    pthread_mutex_lock(&da->lock);
    free(da->array);
    pthread_mutex_destroy(&da->lock);
    da->array = NULL;
    da->size = 0;
    da->capacity = 0;
}

void printStatistics(const DynamicArray *da) {
    int total_cqi = 0, total_csirri = 0;
    pthread_mutex_lock((pthread_mutex_t*)&da->lock);

    for (size_t i = 0; i < da->size; ++i) {
        total_cqi += da->array[i].cqi.cqi_value;
        total_csirri += da->array[i].csirri.csirri_value;
    }

    pthread_mutex_unlock((pthread_mutex_t*)&da->lock);

    if (da->size > 0) {
        printf("Average CQI: %.2f\n", (double)total_cqi / da->size);
        printf("Average CSI-RI: %.2f\n", (double)total_csirri / da->size);
    } else {
        printf("No elements to calculate statistics.\n");
    }
}

// Example usage
int main() {
    DynamicArray da;
    if (initDynamicArray(&da, 10) != 0) {
        fprintf(stderr, "Failed to initialize dynamic array\n");
        return EXIT_FAILURE;
    }

    LTE_RRC_CUCCH_INDICATION_T sample1 = {{5}, {0}, {2}};
    addElement(&da, sample1);

    LTE_RRC_CUCCH_INDICATION_T sample2 = {{7}, {1}, {3}};
    addElement(&da, sample2);

    printStatistics(&da);

    freeDynamicArray(&da);
    return EXIT_SUCCESS;
}
