#define MAX_PACKETS 10000

typedef enum {
    PROTOCOL_TCP,
    PROTOCOL_UDP,
    // Add other protocol types as necessary
} ProtocolType;

typedef struct {
    unsigned char ip[4];          // IPv4 address
    unsigned short port;          // Port number (0-65535)
    ProtocolType protocol_type;   // Protocol type (e.g., TCP, UDP)
    unsigned char tcp_flags;      // TCP flags for TCP packets
} Packet;

typedef struct {
    Packet *packets;
    size_t count;
} PacketArray;

unsigned short generate_unique_port(unsigned short *used_ports, size_t used_count) {
    unsigned short port;
    int attempts = 0;
    do {
        if (attempts > MAX_PACKETS) {
            fprintf(stderr, "Port range exceeded; unable to allocate unique ports.\n");
            exit(EXIT_FAILURE);
        }
        port = rand() % (65535 - 1024 + 1) + 1024; // Generate a random port in the valid range
        attempts++;
    } while (attempts < MAX_PACKETS && (port == 0 || is_port_in_use(port, used_ports, used_count)));

    return port;
}

int is_port_in_use(unsigned short port, unsigned short *used_ports, size_t used_count) {
    for (size_t i = 0; i < used_count; ++i) {
        if (used_ports[i] == port)
            return 1;
    }
    return 0;
}

void initialize_packet_array(PacketArray *packet_array, size_t desired_packets) {
    srand((unsigned int)time(NULL));

    packet_array->packets = malloc(desired_packets * sizeof(Packet));
    if (!packet_array->packets) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    unsigned short used_ports[MAX_PACKETS] = {0};
    size_t used_count = 0;
    packet_array->count = desired_packets;

    for (size_t i = 0; i < desired_packets; ++i) {
        // Generate a random IP address
        for (int j = 0; j < 4; ++j) {
            packet_array->packets[i].ip[j] = rand() % 256;
        }

        // Generate a unique port number in the range of 1024 to 65535
        packet_array->packets[i].port = generate_unique_port(used_ports, used_count);
        used_ports[used_count++] = packet_array->packets[i].port;

        // Assign protocol type (e.g., TCP for demonstration)
        packet_array->packets[i].protocol_type = PROTOCOL_TCP;

        // Generate random TCP flags if the protocol is TCP
        if (packet_array->packets[i].protocol_type == PROTOCOL_TCP) {
            packet_array->packets[i].tcp_flags = rand() % 16; // Random TCP flags (6 bits)
        }
    }
}

void free_packet_array(PacketArray *packet_array) {
    free(packet_array->packets);
    packet_array->packets = NULL;
    packet_array->count = 0;
}

// Documentation for extending the function:
//
// To support additional packet types or protocols, follow these steps:
//
// 1. Update the ProtocolType enum to include new protocol identifiers.
// 2. Adjust the initialization logic inside `initialize_packet_array` 
//    to handle each protocol accordingly (e.g., setting flags specific to a protocol).
// 3. If necessary, add additional fields to the Packet structure for supporting
//    unique characteristics of new protocols.
