        pthread_mutex_lock(&lock);
        strcpy(messages[i].user_id, user_id);
        messages[i].timestamp = timestamp;
        snprintf(messages[i].message_content, MESSAGE_CONTENT_LEN, "Message content for user %s", user_id);
        messages[i].priority_level = priority_level;
        pthread_mutex_unlock(&lock);
    }
}

int main() {
    Message messages[MAX_MESSAGES];
    initialize_messages(messages, MAX_MESSAGES, 1, 10);

    // Example: Print first few messages
    for (size_t i = 0; i < 5 && i < MAX_MESSAGES; ++i) {
        printf("User ID: %s, Timestamp: %ld, Priority: %d, Content: %s\n",
               messages[i].user_id,
               messages[i].timestamp,
               messages[i].priority_level,
               messages[i].message_content);
