#define MAX_LOG_ENTRIES 10000

typedef enum {
    LOG_LEVEL_DEBUG,
    LOG_LEVEL_INFO,
    LOG_LEVEL_WARN,
    LOG_LEVEL_ERROR,
    LOG_LEVEL_FATAL
} LogLevel;

typedef struct {
    time_t timestamp;
    LogLevel level;
    char message[256];
} LogEntry;

typedef struct {
    time_t start_time;
    time_t end_time;
    int rollover_days;
    LogEntry *entries;
    size_t count;
    size_t capacity;
} LogManager;

LogManager* create_log_manager(time_t start_time, time_t end_time, int rollover_days) {
    LogManager *manager = (LogManager *)malloc(sizeof(LogManager));
    manager->start_time = start_time;
    manager->end_time = end_time;
    manager->rollover_days = rollover_days;
    manager->entries = NULL;
    manager->count = 0;
    manager->capacity = 0;
    return manager;
}

void free_log_manager(LogManager *manager) {
    if (manager) {
        free(manager->entries);
        free(manager);
    }
}

int is_within_range(time_t timestamp, LogManager *manager) {
    time_t current_time = time(NULL);
    double seconds_in_day = 86400.0;

    // Check rollover
    if ((timestamp > manager->end_time && (current_time - timestamp) < seconds_in_day * manager->rollover_days) ||
        (timestamp < manager->start_time && (timestamp - current_time) < seconds_in_day * manager->rollover_days)) {
        return 1;
    }

    return (timestamp >= manager->start_time && timestamp <= manager->end_time);
}

void add_log_entry(LogManager *manager, LogEntry entry) {
    if (!is_within_range(entry.timestamp, manager)) {
        fprintf(stderr, "Log entry timestamp out of range.\n");
        return;
    }

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity == 0 ? 10 : manager->capacity * 2;
        LogEntry *new_entries = (LogEntry *)realloc(manager->entries, new_capacity * sizeof(LogEntry));
        if (!new_entries) {
            fprintf(stderr, "Failed to allocate memory for log entries.\n");
            return;
        }
        manager->entries = new_entries;
        manager->capacity = new_capacity;
    }

    manager->entries[manager->count++] = entry;
}

char* format_log_entry(LogEntry entry) {
    static char json_buffer[512];
    snprintf(json_buffer, sizeof(json_buffer), 
             "{\"timestamp\": %ld, \"level\": \"%s\", \"message\": \"%s\"}", 
             entry.timestamp,
             entry.level == LOG_LEVEL_DEBUG ? "DEBUG" :
             entry.level == LOG_LEVEL_INFO ? "INFO" :
             entry.level == LOG_LEVEL_WARN ? "WARN" :
             entry.level == LOG_LEVEL_ERROR ? "ERROR" : "FATAL",
             entry.message);
    return json_buffer;
}

char* format_log_entries(LogManager *manager) {
    char *json_output = (char *)malloc(1024); // Adjust size as needed
    if (!json_output) {
        fprintf(stderr, "Failed to allocate memory for JSON output.\n");
        return NULL;
    }

    strcpy(json_output, "[\n");
    for (size_t i = 0; i < manager->count; ++i) {
        strcat(json_output, format_log_entry(manager->entries[i]));
        if (i < manager->count - 1) {
            strcat(json_output, ",\n");
        }
    }
    strcat(json_output, "\n]");

    return json_output;
}

// Example usage
int main() {
    time_t start_time = time(NULL) - 86400; // Yesterday
    time_t end_time = time(NULL);

    LogManager *manager = create_log_manager(start_time, end_time, 7);

    LogEntry entry1 = {time(NULL), LOG_LEVEL_INFO, "System started"};
    add_log_entry(manager, entry1);

    char *json_output = format_log_entries(manager);
    if (json_output) {
        printf("%s\n", json_output);
        free(json_output);
    }

    free_log_manager(manager);
    return 0;
}
