CRC_Indication_List* create_list() {
    CRC_Indication_List* list = (CRC_Indication_List*)malloc(sizeof(CRC_Indication_List));
    if (!list) return NULL;
    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int is_rnti_unique(CRC_Indication_List* list, uint16_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current != NULL) {
        if (current->rnti == rnti) return 0;
        current = current->next;
    }
    return 1;
}

uint16_t generate_unique_rnti(CRC_Indication_List* list) {
    uint16_t rnti;
    do {
        rnti = rand() % 65535 + 1; // RNTI values range from 1 to 65535
    } while (!is_rnti_unique(list, rnti));
    return rnti;
}

