    if (list->count >= 1000) { // Limit the number of structures
        pthread_mutex_unlock(&list->lock);
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->ue_info_tag.RNTI = generate_unique_rnti(list);
    new_node->rnti = new_node->ue_info_tag.RNTI;
    new_node->crc_indication_rel8_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    log_structure(new_node);

    pthread_mutex_unlock(&list->lock);
}

void free_list(CRC_Indication_List* list) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    list->count = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

