// Node for the linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    atomic_int size;
} ThreadSafeList;

// Function prototypes
ThreadSafeList* create_list();
int insert_unique(ThreadSafeList* list, const NFAPI_CRC_INDICATION_PDU_T* pdu);
void free_list(ThreadSafeList* list);

// Create an empty thread-safe list
ThreadSafeList* create_list() {
    ThreadSafeList* list = (ThreadSafeList*)malloc(sizeof(ThreadSafeList));
    if (!list) return NULL;

    list->head = NULL;
    atomic_init(&list->size, 0);
    return list;
}

// Insert a unique element into the list
int insert_unique(ThreadSafeList* list, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!list || !pdu) return -1;

    Node* current = list->head;

    while (current) {
        if (current->data.rnti == pdu->rnti && 
            current->data.crc_indication_rel8_tag.CRCFLAG == pdu->crc_indication_rel8_tag.CRCFLAG) {
            return 0; // Duplicate found
        }
        current = current->next;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -2;

    *new_node = (Node){ .data = *pdu, .next = list->head };

    while (__sync_bool_compare_and_swap(&list->head, new_node->next, new_node)) {
        // Spinlock-like behavior
    }

    atomic_fetch_add_explicit(&list->size, 1, memory_order_relaxed);

    return 1; // Inserted successfully
}

// Free the list and its nodes
void free_list(ThreadSafeList* list) {
    if (!list) return;

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    free(list);
}

// Example usage in a multi-threaded environment
void* thread_function(void* arg) {
    ThreadSafeList* list = (ThreadSafeList*)arg;

    NFAPI_CRC_INDICATION_PDU_T pdu = {
        .ue_info_tag = {.RNTI = 123},
        .rnti = 456,
        .crc_indication_rel8_tag = {.CRCFLAG = rand() % 2}
    };

    if (insert_unique(list, &pdu) != 1) {
        fprintf(stderr, "Failed to insert unique PDU.\n");
    }

    return NULL;
}

int main() {
    ThreadSafeList* list = create_list();
    if (!list) {
        fprintf(stderr, "Failed to create list.\n");
        return EXIT_FAILURE;
    }

    pthread_t threads[10];
    for (int i = 0; i < 10; ++i) {
        if (pthread_create(&threads[i], NULL, thread_function, list)) {
            perror("Thread creation failed");
            free_list(list);
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

