    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

void cleanup_manager(SessionManager *manager) {
    free(manager->sessions);
    pthread_mutex_destroy(&manager->lock);
}

bool add_session(SessionManager *manager, PDU_Session session, double cpu_utilization, double memory_usage) {
    double threshold = get_dynamic_threshold();

    // Check system performance constraints
    if (is_above_performance_threshold(cpu_utilization, memory_usage)) {
        return false;
    }

    pthread_mutex_lock(&manager->lock);

    if (manager->count < threshold) {
        manager->sessions[manager->count++] = session;
        pthread_mutex_unlock(&manager->lock);
        return true;
    }

    pthread_mutex_unlock(&manager->lock);
    return false;
}

bool remove_session(SessionManager *manager, int session_id) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i].session_id == session_id) {
            memmove(&manager->sessions[i], &manager->sessions[i + 1],
                    (manager->count - i - 1) * sizeof(PDU_Session));
            --manager->count;
            pthread_mutex_unlock(&manager->lock);
            return true;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return false;
}

