// Function to initialize and configure the dynamic array of structures
int init_lte_rrc_cch_userinfo_array(LTE_RRC_CCH_USERINFO **user_info_array, int num_users, int block_size) {
    if (num_users <= 0 || block_size <= 0) {
        fprintf(stderr, "Invalid number of users or block size.\n");
        return -1;
    }

    *user_info_array = malloc(num_users * sizeof(LTE_RRC_CCH_USERINFO));
    if (*user_info_array == NULL) {
        perror("Failed to allocate memory for user info array");
        return -2;
    }

    for (int i = 0; i < num_users; ++i) {
        (*user_info_array)[i].RRC_UE_ID = i + 1; // Assign a valid RRC_UE_ID
        (*user_info_array)[i].RRC_CCH_USERINFO_TAG = 100 + i; // Arbitrary tag value
        (*user_info_array)[i].transport_block_size = block_size;

        // Allocate buffer for uplink transport blocks
        (*user_info_array)[i].transport_blocks = malloc(block_size);
        if ((*user_info_array)[i].transport_blocks == NULL) {
            fprintf(stderr, "Failed to allocate memory for transport blocks for UE ID %d\n", i + 1);

            // Cleanup partially allocated resources before returning
            for (int j = 0; j < i; ++j) {
                free((*user_info_array)[j].transport_blocks);
            }
            free(*user_info_array);
            *user_info_array = NULL;
            return -3;
        }

        // Initialize transport blocks with zeros or any default value
        memset((*user_info_array)[i].transport_blocks, 0, block_size);
    }

    return 0; // Success
}

// Function to calculate total size of the uplink transport blocks and update structure accordingly
size_t calculate_total_transport_block_size(LTE_RRC_CCH_USERINFO *user_info_array, int num_users) {
    if (user_info_array == NULL || num_users <= 0) {
        fprintf(stderr, "Invalid user info array or number of users.\n");
        return 0;
    }

    size_t total_size = 0;
    for (int i = 0; i < num_users; ++i) {
        total_size += user_info_array[i].transport_block_size;
    }

    printf("Total transport block size: %zu bytes\n", total_size);
    return total_size;
}

// Example usage
int main() {
    LTE_RRC_CCH_USERINFO *user_info_array = NULL;
    int num_users = 5;
    int block_size = 1024; // Arbitrary block size

    if (init_lte_rrc_cch_userinfo_array(&user_info_array, num_users, block_size) != 0) {
        fprintf(stderr, "Initialization failed\n");
        return -1;
    }

    calculate_total_transport_block_size(user_info_array, num_users);

    for (int i = 0; i < num_users; ++i) {
        free(user_info_array[i].transport_blocks);
    }
    free(user_info_array);

    return 0;
}
