        }
    }
}

void set_log_level(int level) {
    pthread_mutex_lock(&list.lock);
    list.log_level = level;
    pthread_mutex_unlock(&list.lock);
}

void log_message(const char* message) {
    pthread_mutex_lock(&list.lock);
    if (list.log_file && list.log_level > 0) {
        fprintf(list.log_file, "%s\n", message);
        fflush(list.log_file);
    }
    pthread_mutex_unlock(&list.lock);
}

int random_crcflag() {
    return rand() % 2;
