void add_element(NFAPI_CRC_INDICATION_PDU_T* element) {
    if (list.size >= MAX_ELEMENTS) return;

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return;

    *new_node->data = *element;
    pthread_mutex_lock(&list.lock);
    new_node->next = list.head;
    list.head = new_node;
    list.size++;
    pthread_cond_signal(&list.cond);
    pthread_mutex_unlock(&list.lock);

    char log_msg[256];
    snprintf(log_msg, sizeof(log_msg), "Added element: RX_UE_INFORMATION_TAG=%u, RNTI=%u, CRCFLAG=%d",
             element->RX_UE_INFORMATION_TAG, element->RNTI, element->CRC_INDICATION_REL8_TAG.CRCFLAG);
    log_message(log_msg);
}

void remove_element(size_t index) {
    if (index >= list.size) return;

    pthread_mutex_lock(&list.lock);
    Node* current = list.head;
    Node* prev = NULL;
    for (size_t i = 0; i < index; ++i) {
        prev = current;
        current = current->next;
    }
    if (prev == NULL) {
        list.head = current->next;
    } else {
        prev->next = current->next;
    }
    free(current);
    list.size--;
    pthread_cond_signal(&list.cond);
    pthread_mutex_unlock(&list.lock);

    char log_msg[256];
    snprintf(log_msg, sizeof(log_msg), "Removed element at index: %zu", index);
    log_message(log_msg);
}

