    Node* current = list.head;
    for (size_t i = 0; i < index; ++i) {
        current = current->next;
    }
    current->data.CRC_INDICATION_REL8_TAG.CRCFLAG = random_crcflag();
    pthread_mutex_unlock(&list.lock);

    char log_msg[256];
    snprintf(log_msg, sizeof(log_msg), "Updated CRCFLAG at index: %zu to %d",
             index, current->data.CRC_INDICATION_REL8_TAG.CRCFLAG);
    log_message(log_msg);
}

NFAPI_CRC_INDICATION_PDU_T* get_element(size_t index) {
    if (index >= list.size) return NULL;

    pthread_mutex_lock(&list.lock);
    Node* current = list.head;
    for (size_t i = 0; i < index; ++i) {
        current = current->next;
    }
    NFAPI_CRC_INDICATION_PDU_T* element = &current->data;
    pthread_mutex_unlock(&list.lock);

    char log_msg[256];
    snprintf(log_msg, sizeof(log_msg), "Retrieved element at index: %zu", index);
    log_message(log_msg);

    return element;
}

void filter_and_add_range(unsigned int rnti_start, unsigned int rnti_end) {
    pthread_mutex_lock(&list.lock);
    Node* current = list.head;
    while (current != NULL) {
        if (current->data.RNTI >= rnti_start && current->data.RNTI <= rnti_end) {
