                     current->data.RX_UE_INFORMATION_TAG, current->data.RNTI);
            log_message(log_msg);
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list.lock);
}

void* monitor_and_throttle(void* arg) {
    while (1) {
        sleep(5); // Adjust as necessary for throttling
        pthread_mutex_lock(&list.lock);
        if (list.size > 0 && list.log_file != NULL) {
            char log_msg[256];
            snprintf(log_msg, sizeof(log_msg), "Current size: %zu", list.size);
            log_message(log_msg);
        }
        pthread_mutex_unlock(&list.lock);
    }
    return NULL;
}

void cleanup() {
    pthread_mutex_lock(&list.lock);
    Node* current = list.head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list.size = 0;
    if (list.log_file) {
        fclose(list.log_file);
        list.log_file = NULL;
    }
    pthread_mutex_unlock(&list.lock);
}

int main() {
    srand(time(NULL));
    init_log_file("log.txt");
    set_log_level(1);

