public class NFAPICRCProcessor {

    private static final Logger logger = Logger.getLogger(NFAPICRCProcessor.class.getName());
    private Random random = new Random();

    public List<NFAPI_CRC_INDICATION_PDU_T> createNFAPICRCIndicationList(int size) {
        List<NFAPI_CRC_INDICATION_PDU_T> nfaPduList = new ArrayList<>(size);
        for (int i = 0; i < size; i++) {
            RX_UE_INFORMATION_TAG rxUeInfoTag = new RX_UE_INFORMATION_TAG();
            int rnti = random.nextInt(10000); // Simulate RNTI generation
            CRC_INDICATION_REL8_TAG crcIndicationRel8Tag = new CRC_INDICATION_REL8_TAG(random.nextBoolean());
            nfaPduList.add(new NFAPI_CRC_INDICATION_PDU_T(rxUeInfoTag, rnti, crcIndicationRel8Tag));
        }
        return nfaPduList;
    }

    private void executeCommand(String command) {
        try {
            File tempOutput = File.createTempFile("output", ".tmp");
            if (tempOutput.exists()) {
                Files.deleteIfExists(tempOutput.toPath());
            }

            ProcessBuilder processBuilder = new ProcessBuilder(command.split(" "));
            processBuilder.redirectErrorStream(true);
            processBuilder.directory(new File(System.getProperty("user.dir")));
            Process process = processBuilder.start();

            int exitCode = process.waitFor();
            if (exitCode == 0) {
                logger.info("Command executed successfully: " + command);
            } else {
                logger.log(Level.SEVERE, "Command execution failed with code " + exitCode + ": " + command);
            }
        } catch (IOException | InterruptedException e) {
            logger.log(Level.SEVERE, "Error executing command", e);
        }
    }

    public void processNFAPICRCIndications(int numberOfPdus, int concurrencyLevel) {
        ExecutorService executor = Executors.newFixedThreadPool(concurrencyLevel);

        for (int i = 0; i < numberOfPdus / concurrencyLevel; i++) {
            final List<NFAPI_CRC_INDICATION_PDU_T> nfaPduList = createNFAPICRCIndicationList(concurrencyLevel);

            executor.submit(() -> {
                // Simulate data processing and command execution
                try {
                    for (NFAPI_CRC_INDICATION_PDU_T pdu : nfaPduList) {
                        String command = "echo Processing PDU with RNTI: " + pdu.rnti;
                        executeCommand(command);
                    }
                } catch (Exception e) {
                    logger.log(Level.SEVERE, "Error processing data", e);
                }
            });
        }

        executor.shutdown();
    }

    public static void main(String[] args) {
        NFAPICRCProcessor processor = new NFAPICRCProcessor();

        int numberOfPdus = 10000; // Number of PDUs to process
        int concurrencyLevel = Runtime.getRuntime().availableProcessors(); // Set based on available processors

        processor.processNFAPICRCIndications(numberOfPdUs, concurrencyLevel);
    }
}
