#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_UE_ID_SIZE 32

typedef struct {
    char *ue_id;
} UEIdentifier;

typedef struct EventNode {
    int event_id;
    time_t timestamp;
    UEIdentifier *ue_ids;
    size_t ue_count;
    struct EventNode *next;
} EventNode;

typedef struct {
    EventNode *head;
    pthread_mutex_t lock;
} EventList;

EventList* initialize_event_list() {
    EventList *list = (EventList *)malloc(sizeof(EventList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void add_event(EventList *list, int event_id, time_t timestamp, char **ue_ids, size_t ue_count) {
    pthread_mutex_lock(&list->lock);

    EventNode *new_node = (EventNode *)malloc(sizeof(EventNode));
    new_node->event_id = event_id;
    new_node->timestamp = timestamp;

    new_node->ue_ids = (UEIdentifier *)malloc(ue_count * sizeof(UEIdentifier));
    for (size_t i = 0; i < ue_count; ++i) {
        new_node->ue_ids[i].ue_id = strdup(ue_ids[i]);
    }
    new_node->ue_count = ue_count;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
}

EventNode* query_events(EventList *list, time_t start_time, time_t end_time) {
    pthread_mutex_lock(&list->lock);

    EventNode **current = &list->head;
    while (*current) {
        if ((*current)->timestamp >= start_time && (*current)->timestamp <= end_time) {
            break;
        }
        current = &(*current)->next;
    }

    pthread_mutex_unlock(&list->lock);
    return *current;
}

void update_event(EventList *list, int event_id, time_t new_timestamp, char **new_ue_ids, size_t new_ue_count) {
    pthread_mutex_lock(&list->lock);

    EventNode *node = list->head;
    while (node) {
        if (node->event_id == event_id) {
            node->timestamp = new_timestamp;

            for (size_t i = 0; i < node->ue_count; ++i) {
                free(node->ue_ids[i].ue_id);
            }
            free(node->ue_ids);

            node->ue_ids = (UEIdentifier *)malloc(new_ue_count * sizeof(UEIdentifier));
            for (size_t i = 0; i < new_ue_count; ++i) {
                node->ue_ids[i].ue_id = strdup(new_ue_ids[i]);
            }
            node->ue_count = new_ue_count;
            break;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void free_event_list(EventList *list) {
    pthread_mutex_lock(&list->lock);

    EventNode *current = list->head;
    while (current) {
        EventNode *temp = current;
        current = current->next;

        for (size_t i = 0; i < temp->ue_count; ++i) {
            free(temp->ue_ids[i].ue_id);
        }
        free(temp->ue_ids);
        free(temp);
    }

    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example of integrating with an external data service
void validate_ue_identifiers(char **ue_ids, size_t ue_count) {
    // Placeholder for real-time validation logic
}

int main() {
    EventList *event_list = initialize_event_list();

    char *ue_ids[] = {"UE1", "UE2"};
    add_event(event_list, 101, time(NULL), ue_ids, 2);

    EventNode *events = query_events(event_list, time(NULL) - 3600, time(NULL));
    if (events) {
        printf("Event ID: %d\n", events->event_id);
        for (size_t i = 0; i < events->ue_count; ++i) {
            printf("UE ID: %s\n", events->ue_ids[i].ue_id);
        }
    }

    char *new_ue_ids[] = {"UE3"};
    update_event(event_list, 101, time(NULL), new_ue_ids, 1);

    free_event_list(event_list);
    return 0;
}
