#include <stdint.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint8_t CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t size;
    pthread_mutex_t lock;
    unsigned int access_count;
} NFAPI_CRC_ARRAY;

NFAPI_CRC_ARRAY* create_nfa_api_crc_array(size_t n) {
    if (n == 0) return NULL;

    NFAPI_CRC_ARRAY* array = malloc(sizeof(NFAPI_CRC_ARRAY));
    if (!array) return NULL;

    array->data = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->data) {
        free(array);
        return NULL;
    }

    pthread_mutex_init(&array->lock, NULL);
    array->size = n;
    array->access_count = 0;

    // Seed random number generator for consistent CRCFLAG
    srand(42);

    for (size_t i = 0; i < n; ++i) {
        array->data[i].RX_UE_INFORMATION_TAG = rand() % 100000;
        array->data[i].RNTI = rand() % 65536;
        array->data[i].CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2);
    }

    return array;
}

void free_nfa_api_crc_array(NFAPI_CRC_ARRAY* array) {
    if (!array) return;

    pthread_mutex_destroy(&array->lock);
    free(array->data);
    free(array);
}

void serialize_array_to_file(const NFAPI_CRC_ARRAY* array, const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    // Write version and size for backward compatibility
    uint8_t version = 1;
    fwrite(&version, sizeof(version), 1, file);
    fwrite(&array->size, sizeof(array->size), 1, file);

    pthread_mutex_lock(&array->lock);
    fwrite(array->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), array->size, file);
    pthread_mutex_unlock(&array->lock);

    fclose(file);
}

void deserialize_array_from_file(NFAPI_CRC_ARRAY** array, const char* filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    uint8_t version;
    size_t n;
    fread(&version, sizeof(version), 1, file);
    fread(&n, sizeof(n), 1, file);

    *array = create_nfa_api_crc_array(n);
    if (*array) {
        pthread_mutex_lock(&(*array)->lock);
        fread((*array)->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), n, file);
        pthread_mutex_unlock(&(*array)->lock);
    }

    fclose(file);
}

void* anomaly_check_thread(void* arg) {
    NFAPI_CRC_ARRAY* array = (NFAPI_CRC_ARRAY*)arg;

    while (1) {
        sleep(5); // Check every 5 seconds

        pthread_mutex_lock(&array->lock);

        for (size_t i = 0; i < array->size; ++i) {
            if (array->data[i].RNTI == 0 || array->data[i].CRC_INDICATION_REL8_TAG.CRCFLAG == 255) {
                printf("Anomaly detected at index %zu\n", i);
            }
        }

        pthread_mutex_unlock(&array->lock);
    }

    return NULL;
}

int main() {
    NFAPI_CRC_ARRAY* array = create_nfa_api_crc_array(10);

    if (!array) {
        fprintf(stderr, "Failed to allocate memory for the array\n");
        return 1;
    }

    pthread_t anomaly_thread;
    pthread_create(&anomaly_thread, NULL, anomaly_check_thread, (void*)array);

    serialize_array_to_file(array, "data.bin");

    NFAPI_CRC_ARRAY* loaded_array = NULL;
    deserialize_array_from_file(&loaded_array, "data.bin");

    if (loaded_array) {
        // Use the loaded array...
        free_nfa_api_crc_array(loaded_array);
    }

    pthread_cancel(anomaly_thread);
    pthread_join(anomaly_thread, NULL);

    free_nfa_api_crc_array(array);

    return 0;
}
```

### Key Points:
- **Thread Safety**: A mutex is used to ensure thread safety when accessing the shared array.
- **Serialization**: The array is serialized with a version number for backward compatibility.
- **Anomaly Detection**: A background thread periodically checks for anomalies in the data.
- **Memory Management**: Proper allocation and deallocation of memory are handled, including freeing of the mutex.']

