    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} NFALIST_T;

// Function prototypes
NFALIST_T* create_nfa_list();
void destroy_nfa_list(NFALIST_T *nfa_list);
int resize_nfa_list(NFALIST_T *nfa_list, size_t new_capacity);
int load_from_csv(NFALIST_T *nfa_list, const char *filename);
void log_error(const char *message);
void generate_statistics(const NFALIST_T *nfa_list);

// Function implementations
NFALIST_T* create_nfa_list() {
    NFALIST_T *list = (NFALIST_T*)malloc(sizeof(NFALIST_T));
    if (!list) {
        log_error("Memory allocation failed for NFALIST_T");
        return NULL;
    }

    list->entries = NULL;
    list->count = 0;
    list->capacity = 0;

    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_nfa_list(NFALIST_T *nfa_list) {
    if (nfa_list) {
        pthread_mutex_destroy(&nfa_list->lock);
        free(nfa_list->entries);
        free(nfa_list);
    }
}

int resize_nfa_list(NFALIST_T *nfa_list, size_t new_capacity) {
    pthread_mutex_lock(&nfa_list->lock);

    NFAPI_CRC_INDICATION_PDU_T *new_entries = (NFAPI_CRC_INDICATION_PDU_T*)realloc(nfa_list->entries, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_entries) {
        log_error("Memory reallocation failed for NFALIST_T");
        pthread_mutex_unlock(&nfa_list->lock);
        return -1;
    }

    nfa_list->entries = new_entries;
    nfa_list->capacity = new_capacity;

    pthread_mutex_unlock(&nfa_list->lock);

    return 0;
}

int load_from_csv(NFALIST_T *nfa_list, const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        log_error("Failed to open CSV file");
        return -1;
    }

    pthread_mutex_lock(&nfa_list->lock);

    size_t initial_capacity = 10; // Start with an initial capacity
    resize_nfa_list(nfa_list, initial_capacity);

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        if (nfa_list->count >= nfa_list->capacity) {
            resize_nfa_list(nfa_list, nfa_list->capacity * 2);
        }

        int rx_ue_tag, rnti;
        if (sscanf(line, "%d,%d", &rx_ue_tag, &rnti) != 2) {
            log_error("Malformed CSV line");
            continue;
        }

        NFAPI_CRC_INDICATION_PDU_T pdu = { {rx_ue_tag, rnti}, {rand() % 2} };
        nfa_list->entries[nfa_list->count++] = pdu;
    }

    pthread_mutex_unlock(&nfa_list->lock);

    fclose(file);

    return 0;
}

void log_error(const char *message) {
    fprintf(stderr, "ERROR: %s\n", message);
}

void generate_statistics(const NFALIST_T *nfa_list) {
    size_t crc_flag_sum = 0;

    pthread_mutex_lock(&nfa_list->lock);

    for (size_t i = 0; i < nfa_list->count; ++i) {
        crc_flag_sum += nfa_list->entries[i].crc_tag.CRCFLAG;
    }

    pthread_mutex_unlock(&nfa_list->lock);

    double error_rate = ((double)crc_flag_sum / nfa_list->count) * 100.0;

    printf("CRC Error Rate: %.2f%%\n", error_rate);
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <csv_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    NFALIST_T *nfa_list = create_nfa_list();
    if (!nfa_list) {
        return EXIT_FAILURE;
    }

    if (load_from_csv(nfa_list, argv[1]) == -1) {
        destroy_nfa_list(nfa_list);
        return EXIT_FAILURE;
    }

    generate_statistics(nfa_list);

    destroy_nfa_list(nfa_list);

    return EXIT_SUCCESS;
}
```

