#define INITIAL_CAPACITY 10

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* elements;
    size_t capacity;
    size_t count;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->elements = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->elements) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->count = 0;

    return array;
}

void resize_dynamic_array(DynamicArray* array, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T* new_elements = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_elements) return;

    memset(new_elements + array->count, 0, (new_capacity - array->count) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    array->elements = new_elements;
    array->capacity = new_capacity;
}

int find_rnti_index(DynamicArray* array, unsigned long rnti) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->elements[i].RNTI == rnti) return i;
    }
    return -1;
}

int add_element(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T element) {
    if (find_rnti_index(array, element.RNTI) != -1) return 0;

    if (array->count == array->capacity) {
        resize_dynamic_array(array, array->capacity * 2);
    }

    array->elements[array->count++] = element;
    return 1;
}

int remove_element_by_rnti(DynamicArray* array, unsigned long rnti) {
    int index = find_rnti_index(array, rnti);

    if (index == -1) return 0;

    for (size_t i = index; i < array->count - 1; ++i) {
        array->elements[i] = array->elements[i + 1];
    }

    --array->count;

    if (array->capacity > INITIAL_CAPACITY && array->count <= array->capacity / 4) {
        resize_dynamic_array(array, array->capacity / 2);
    }

    return 1;
}

void free_dynamic_array(DynamicArray* array) {
    if (!array) return;

    free(array->elements);
    free(array);
}

int main() {
    DynamicArray* array = create_dynamic_array(INITIAL_CAPACITY);

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T pdu1 = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 1001, .CRC_INDICATION_REL8_TAG = 5 };
    NFAPI_CRC_INDICATION_PDU_T pdu2 = { .RX_UE_INFORMATION_TAG = 2, .RNTI = 1002, .CRC_INDICATION_REL8_TAG = 6 };

    add_element(array, pdu1);
    add_element(array, pdu2);

    remove_element_by_rnti(array, 1001);

    free_dynamic_array(array);

    return 0;
}
