    MemoryPool* pool = create_memory_pool(sizeof(NFAPI_CRC_INDICATION_PDU_T), n);
    if (!pool) {
        fprintf(stderr, "Failed to allocate memory pool\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T** list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!list) {
        destroy_memory_pool(pool);
        fprintf(stderr, "Memory allocation failed for structure pointers\n");
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (size_t i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = allocate_from_pool(pool);
        if (!pdu) {
            fprintf(stderr, "Memory allocation failed from pool\n");
            while (i > 0) deallocate_to_pool(pool, list[--i]);
            free(list);
            destroy_memory_pool(pool);
            return NULL;
        }

        pthread_mutex_lock(&mutex);
        pdu->rx_ue_info.rnti = rand() % 100000; // Random RNTI for simplicity
        pdu->rx_ue_info.tag.crcflag = rand() & 1; // Random CRCFLAG

        if (pdu->rx_ue_info.tag.crcflag >= crc_threshold) {
            list[i] = pdu;
        } else {
