    while (count < N) {
        int rnti = rand() % (maxRNTI - minRNTI + 1) + minRNTI;

        // Check if RNTI is unique and within the valid range
        bool exists = false;
        for (size_t i = 0; i < count; ++i) {
            if (generatedRNTIs[i] == rnti) {
                exists = true;
