        (strcmp(method, "POST") == 0 && response_code != 201)) {
        return -1; // Inconsistent
    }
    return 0; // Consistent
}

// Function to manage dynamic array of HTTP_Request structures
void manage_http_requests(size_t max_memory_size) {
    size_t request_count = 0;
    size_t current_memory_usage = 0;
    int base_body_size = 1024; // 1KB
    HTTP_Request* requests = NULL;

    while (current_memory_usage < max_memory_size) {
        HTTP_Request new_request;
        new_request.URL = generate_random_string(20);
        new_request.HTTP_Method = generate_random_method();
        new_request.Header_Size = rand() % 1000; // Random header size
        int body_size = adjust_body_size_based_on_network(base_body_size);

        if (current_memory_usage + sizeof(HTTP_Request) + strlen(new_request.URL) + new_request.Header_Size + body_size > max_memory_size) {
            break;
        }

        current_memory_usage += sizeof(HTTP_Request) + strlen(new_request.URL) + new_request.Header_Size + body_size;
        requests = realloc(requests, (request_count + 1) * sizeof(HTTP_Request));

        memcpy(&requests[request_count], &new_request, sizeof(HTTP_Request));
        request_count++;
    }

    // Validation and monitoring service simulation
    int successful_validations = 0, failed_validations = 0;
    for (size_t i = 0; i < request_count; ++i) {
        int response_code = rand() % 300; // Random response code
        if (validate_http_method_and_response_code(requests[i].HTTP_Method, response_code) == 0) {
            successful_validations++;
        } else {
            failed_validations++;
        }
    }

    printf("Validations: Successful=%d, Failed=%d\n", successful_validations, failed_validations);

    // Free allocated memory
    for (size_t i = 0; i < request_count; ++i) {
        free(requests[i].URL);
    }
    free(requests);
