    frame->payload_size = (rand() % (MAX_PAYLOAD_SIZE - MIN_PAYLOAD_SIZE + 1)) + MIN_PAYLOAD_SIZE;
    frame->payload = malloc(frame->payload_size);
    if (!frame->payload) {
        fprintf(stderr, "Failed to allocate memory for WebSocket payload\n");
        exit(EXIT_FAILURE);
    }
    memset(frame->payload, rand() % 256, frame->payload_size); // Random data
}

void free_websocket_pdu(WebSocket_PDU *pdu_array, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (pdu_array[i].frame.payload) {
            free(pdu_array[i].frame.payload);
        }
    }
    free(pdu_array);
}

void create_and_manage_websocket_pdus(size_t *count, WebSocket_PDU **pdus) {
    size_t total_allocated = 0;
    size_t max_pdus = MAX_MEMORY_SIZE / (MAX_PAYLOAD_SIZE + sizeof(WebSocket_Frame));
    size_t pdu_count = rand() % (max_pdus + 1);

    if (total_allocated + pdu_count * (sizeof(WebSocket_PDU)) > MAX_MEMORY_SIZE) {
        fprintf(stderr, "Exceeded maximum memory allocation\n");
        return;
    }

    *pdus = malloc(pdu_count * sizeof(WebSocket_PDU));
