    pthread_cond_destroy(&array->cond);
}

// Add a new MIB table to the array
bool addMIBTable(DynamicArray *array, const LTE_PHY_MIB_TABLE *mib) {
    pthread_mutex_lock(&array->lock);

    if (array->size == array->capacity) {
        resizeArray(array);
    }

    array->data[array->size++] = *mib;

    pthread_mutex_unlock(&array->lock);
    return true;
}

// Resize the dynamic array
void resizeArray(DynamicArray *array) {
    size_t newCapacity = array->capacity * GROWTH_FACTOR;
    LTE_PHY_MIB_TABLE *newData = realloc(array->data, newCapacity * sizeof(LTE_PHY_MIB_TABLE));

