    DL_FRAME_INFO dl_frame_info;
    CELL_ID cell_id;
    PHY_STATS *phy_stats; // Optional pointer to a PHY_STATS structure
} LTE_DL_FRAME_MSG;

typedef struct {
    LTE_DL_FRAME_MSG *array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} LTE_DL_FRAME_ARRAY;

// Function declarations
int initialize_lte_dl_frame_array(LTE_DL_FRAME_ARRAY *frameArray, size_t initialCapacity);
int resize_lte_dl_frame_array(LTE_DL_FRAME_ARRAY *frameArray, size_t newCapacity);
int add_lte_dl_frame_message(LTE_DL_FRAME_ARRAY *frameArray, LTE_DL_FRAME_MSG message);
void cleanup_lte_dl_frame_array(LTE_DL_FRAME_ARRAY *frameArray);

// Function definitions
int initialize_lte_dl_frame_array(LTE_DL_FRAME_ARRAY *frameArray, size_t initialCapacity) {
    pthread_mutex_init(&frameArray->lock, NULL);
    frameArray->capacity = initialCapacity;
    frameArray->count = 0;

    if (initialCapacity > 0) {
        frameArray->array = (LTE_DL_FRAME_MSG *)malloc(initialCapacity * sizeof(LTE_DL_FRAME_MSG));
        if (!frameArray->array) {
            pthread_mutex_destroy(&frameArray->lock);
            return -1; // Memory allocation failed
        }
    } else {
        frameArray->array = NULL;
    }

    return 0; // Success
}

int resize_lte_dl_frame_array(LTE_DL_FRAME_ARRAY *frameArray, size_t newCapacity) {
    pthread_mutex_lock(&frameArray->lock);

    LTE_DL_FRAME_MSG *newArray = (LTE_DL_FRAME_MSG *)realloc(frameArray->array, newCapacity * sizeof(LTE_DL_FRAME_MSG));
    if (!newArray && newCapacity > 0) {
        pthread_mutex_unlock(&frameArray->lock);
        return -1; // Realloc failed
    }

    frameArray->array = newArray;
    frameArray->capacity = newCapacity;

    pthread_mutex_unlock(&frameArray->lock);
    return 0; // Success
}

int add_lte_dl_frame_message(LTE_DL_FRAME_ARRAY *frameArray, LTE_DL_FRAME_MSG message) {
    pthread_mutex_lock(&frameArray->lock);

    if (frameArray->count >= frameArray->capacity) {
        size_t newCapacity = frameArray->capacity > 0 ? frameArray->capacity * 2 : 1;
        int resizeResult = resize_lte_dl_frame_array(frameArray, newCapacity);
        if (resizeResult != 0) {
            pthread_mutex_unlock(&frameArray->lock);
            return -1; // Resize failed
        }
    }

    frameArray->array[frameArray->count] = message;
    frameArray->count++;

    pthread_mutex_unlock(&frameArray->lock);
    return 0; // Success
}

void cleanup_lte_dl_frame_array(LTE_DL_FRAME_ARRAY *frameArray) {
    pthread_mutex_lock(&frameArray->lock);

    for (size_t i = 0; i < frameArray->count; ++i) {
        if (frameArray->array[i].phy_stats != NULL) {
            free(frameArray->array[i].phy_stats);
        }
    }

    free(frameArray->array);
    pthread_mutex_unlock(&frameArray->lock);
    pthread_mutex_destroy(&frameArray->lock);

    frameArray->capacity = 0;
    frameArray->count = 0;
}

// Example usage
int main() {
    LTE_DL_FRAME_ARRAY frameArray;

    if (initialize_lte_dl_frame_array(&frameArray, 10) != 0) {
        fprintf(stderr, "Failed to initialize LTE_DL_FRAME_ARRAY\n");
        return EXIT_FAILURE;
    }

    // Add messages...

    cleanup_lte_dl_frame_array(&frameArray);
    return EXIT_SUCCESS;
}
```

### Key Points:
- **Thread Safety**: Achieved using a mutex (`pthread_mutex_t`) to lock critical sections.
- **Dynamic Resizing**: The array resizes automatically when it exceeds its capacity.
- **Memory Management**: Ensures proper allocation, deallocation, and error handling.
- **Logging Integration Placeholder**: You can integrate logging within the mutex locks where needed.
- **Future Extensibility**: The design allows easy additions by modifying structures or adding new fields without extensive changes.']

['Here's an implementation of a C function to manage a dynamic list of `NFAPI_CRC_INDICATION_PDU_T` structures using an LRU eviction policy:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_SIZE 10 // Example maximum size M

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    time_t last_access_time; // Timestamp for LRU management
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    int size;
    int capacity;
} LRUCache;

// Function prototypes
LRUCache* create_cache(int max_size);
void destroy_cache(LRUCache* cache);
int insert_cache(LRUCache* cache, NFAPI_CRC_INDICATION_PDU_T pdu);
NFAPI_CRC_INDICATION_PDU_T evict_cache(LRUCache* cache);
void access_cache(LRUCache* cache, int tag);

// Create a new LRU cache
LRUCache* create_cache(int max_size) {
    LRUCache* cache = (LRUCache*)malloc(sizeof(LRUCache));
    if (!cache) return NULL;

    cache->head = cache->tail = NULL;
    cache->size = 0;
    cache->capacity = max_size;

    return cache;
}

// Destroy the LRU cache
void destroy_cache(LRUCache* cache) {
    Node* current = cache->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(cache);
}

// Insert a new PDU into the cache
int insert_cache(LRUCache* cache, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (cache->size == cache->capacity) {
        NFAPI_CRC_INDICATION_PDU_T evicted = evict_cache(cache);
        printf("Evicted: RX_UE_INFORMATION_TAG=%d, RNTI=%d\n", evicted.RX_UE_INFORMATION_TAG, evicted.RNTI);
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return 0;

    new_node->data = pdu;
    new_node->last_access_time = time(NULL);

    // Insert at head
    new_node->next = cache->head;
    new_node->prev = NULL;
    if (cache->head != NULL) {
        cache->head->prev = new_node;
    }
    cache->head = new_node;

    if (cache->tail == NULL) {
        cache->tail = new_node;
    }

    cache->size++;
    printf("Inserted: RX_UE_INFORMATION_TAG=%d, RNTI=%d\n", pdu.RX_UE_INFORMATION_TAG, pdu.RNTI);
    return 1;
}

// Evict the least recently used item
NFAPI_CRC_INDICATION_PDU_T evict_cache(LRUCache* cache) {
    if (cache->tail == NULL) return (NFAPI_CRC_INDICATION_PDU_T){0};

    Node* to_evict = cache->tail;
    NFAPI_CRC_INDICATION_PDU_T data = to_evict->data;

    cache->tail = to_evict->prev;
    if (cache->tail != NULL) {
        cache->tail->next = NULL;
    } else {
        cache->head = NULL;
    }

    free(to_evict);
    cache->size--;

    return data;
}

// Access a PDU in the cache
void access_cache(LRUCache* cache, int tag) {
    Node* current = cache->head;
    while (current != NULL) {
        if (current->data.RX_UE_INFORMATION_TAG == tag) {
            // Move accessed node to head
            if (current->prev) {
                current->prev->next = current->next;
            }
            if (current->next) {
                current->next->prev = current->prev;
            }
            if (cache->tail == current) {
                cache->tail = current->prev;
            }

            current->next = cache->head;
            current->prev = NULL;
            if (cache->head != NULL) {
                cache->head->prev = current;
            }
            cache->head = current;

            // Update access time
            current->last_access_time = time(NULL);
            printf("Accessed: RX_UE_INFORMATION_TAG=%d, RNTI=%d\n", current->data.RX_UE_INFORMATION_TAG, current->data.RNTI);
            return;
        }
        current = current->next;
    }
}

int main() {
    LRUCache* cache = create_cache(MAX_SIZE);

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T pdu1 = {1, 1001, 10};
    insert_cache(cache, pdu1);

    NFAPI_CRC_INDICATION_PDU_T pdu2 = {2, 1002, 20};
    insert_cache(cache, pdu2);

    access_cache(cache, 1); // Access the first item

    NFAPI_CRC_INDICATION_PDU_T pdu3 = {3, 1003, 30};
    insert_cache(cache, pdu3);

    destroy_cache(cache);
    return 0;
}
```

This code implements a simple LRU cache for managing `NFAPI_CRC_INDICATION_PDU_T` structures. It includes functions to create and destroy the cache, insert new items with eviction if necessary, access existing items to update their position in the LRU order, and evict the least recently used item when the cache reaches its maximum capacity. The example usage demonstrates how to use these functions.']

