    MAC_LAYER_FRAME macFrame;
    L2_PHY_STATS phyStats;
    RX_UE_INFORMATION_TAG rxUeInfoTag;
} NFAPI_PDCH_INDICATION_PDU_T;

typedef struct GPRS_PDU {
    NFAPI_PDCH_INDICATION_PDU_T pdu;
    pthread_mutex_t lock; // For thread safety
} GPRS_PDU;

typedef struct DynamicArray {
    GPRS_PDU *array;
    size_t used;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicArray;

void initDynamicArray(DynamicArray *da, size_t initialCapacity) {
    da->array = (GPRS_PDU *)malloc(initialCapacity * sizeof(GPRS_PDU));
    if (!da->array) exit(1);
    for (size_t i = 0; i < initialCapacity; ++i)
        pthread_mutex_init(&da->array[i].lock, NULL);
    da->used = 0;
    da->capacity = initialCapacity;
    pthread_mutex_init(&da->mutex, NULL);
}

void freeDynamicArray(DynamicArray *da) {
    for (size_t i = 0; i < da->used; ++i)
        pthread_mutex_destroy(&da->array[i].lock);
    free(da->array);
    pthread_mutex_destroy(&da->mutex);
}

void resizeArrayIfNeeded(DynamicArray *da) {
    if (da->used >= da->capacity) {
        size_t newCapacity = da->capacity * 2;
        GPRS_PDU *newArray = realloc(da->array, newCapacity * sizeof(GPRS_PDU));
        if (!newArray) exit(1);

        for (size_t i = da->capacity; i < newCapacity; ++i)
            pthread_mutex_init(&newArray[i].lock, NULL);

        da->array = newArray;
        da->capacity = newCapacity;
    }
}

void insertPDU(DynamicArray *da, NFAPI_PDCH_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&da->mutex);
    resizeArrayIfNeeded(da);
    GPRS_PDU newElement = { .pdu = pdu };
    pthread_mutex_init(&newElement.lock, NULL);

    pthread_mutex_lock(&da->array[da->used].lock);
    da->array[da->used] = newElement;
    pthread_mutex_unlock(&da->array[da->used].lock);

    da->used++;
    pthread_mutex_unlock(&da->mutex);
}

NFAPI_PDCH_INDICATION_PDU_T retrievePDU(DynamicArray *da, size_t index) {
    NFAPI_PDCH_INDICATION_PDU_T pdu;
    if (index >= da->used) return pdu; // Out of bounds
    pthread_mutex_lock(&da->array[index].lock);
    pdu = da->array[index].pdu;
    pthread_mutex_unlock(&da->array[index].lock);
    return pdu;
}

void initializePDU(NFAPI_PDCH_INDICATION_PDU_T *pdu) {
    srand(time(NULL));
    for (int i = 0; i < sizeof(pdu->macFrame.data); ++i)
        pdu->macFrame.data[i] = rand() % 256;

    pdu->phyStats.id = rand();
    pdu->phyStats.rxPower = ((double)rand() / RAND_MAX) * 100.0;
    pdu->phyStats.timeStamp = (unsigned long)time(NULL);

    pdu->rxUeInfoTag.rnti = rand() % 65536;
    pdu->rxUeInfoTag.crcFlag = rand() % 2;

    pdu->pdchId = rand();
}

int main() {
    DynamicArray da;
    initDynamicArray(&da, 10);

    for (size_t i = 0; i < 50; ++i) {
        NFAPI_PDCH_INDICATION_PDU_T pdu;
        initializePDU(&pdu);
        insertPDU(&da, pdu);
    }

    for (size_t i = 0; i < da.used; ++i) {
        NFAPI_PDCH_INDICATION_PDU_T retrievedPdu = retrievePDU(&da, i);
        printf("RNTI: %u, CRCFLAG: %u\n", retrievedPdu.rxUeInfoTag.rnti, retrievedPdu.rxUeInfoTag.crcFlag);
    }

    freeDynamicArray(&da);
    return 0;
}
