NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_crc_indications(int num_structures, int emergency_flag) {
    int max_size = (emergency_flag) ? INT_MAX : MAX_ARRAY_SIZE;

    if (num_structures > max_size) {
        log_message("Exceeded maximum array size limit");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!array) {
        perror("Memory allocation failed");
        log_message("Transient memory allocation failure, possibly due to insufficient resources.");
        return NULL;
