    srand(time(NULL));

    pthread_mutex_lock(&mutex);
    memory_usage += num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    for (int i = 0; i < num_structures; ++i) {
        array[i].CRC_INDICATION_REL8.CRCFLAG = generate_random_crcflag();

        while (!validate_crcflag(array[i].CRC_INDICATION_REL8.CRCFLAG)) {
            array[i].CRC_INDICATION_REL8.CRCFLAG = generate_random_crcflag();
        }
    }

    pthread_mutex_unlock(&mutex);

    return array;
}

void free_crc_indications(NFAPI_CRC_INDICATION_PDU_T *array, int num_structures) {
    if (array != NULL) {
        pthread_mutex_lock(&mutex);
        memory_usage -= num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T);
        free(array);
        pthread_mutex_unlock(&mutex);
    }
}
