    *crcflag = flags[rand() % (sizeof(flags)/sizeof(uint8_t))];
}

int process_csv_line(DynamicArrayManager *manager, const char *line) {
    if (manager->count >= MAX_ENTRIES) return -1; // Handle max entry limit

    pthread_mutex_lock(&manager->lock);

    char *token = strtok(line, ",");
    if (!token) { 
        pthread_mutex_unlock(&manager->lock);
        return -2;  // Malformed CSV
    }

    UEState ue;
    ue.UE_ID = atoi(token);
    token = strtok(NULL, ",");
    if (!token || strlen(token) >= sizeof(ue.RRC_STATE)) {
        pthread_mutex_unlock(&manager->lock);
        return -3;  // Malformed CSV or overflow risk
    }
    strcpy(ue.RRC_STATE, token);

    size_t num_measurements;
    double measurement_value;

    while ((token = strtok(NULL, ","))) {
        if (sscanf(token, "%lf", &measurement_value) != 1) break;
        num_measurements++;
    }

    ue.MeasurementResults = malloc(num_measurements * sizeof(double));
    if (!ue.MeasurementResults) {
        pthread_mutex_unlock(&manager->lock);
        return -4;  // Memory allocation failed
    }

    size_t idx = 0;
    token = strtok(line, ",");
    while ((token = strtok(NULL, ","))) {
        sscanf(token, "%lf", &measurement_value);
        ue.MeasurementResults[idx++] = measurement_value;
    }

    manager->ues[manager->count] = ue;

    NFAPI_CRC_INDICATION_PDU_T crc_pdu;
    crc_pdu.RX_UE_INFORMATION_TAG = rand();
    crc_pdu.RNTI = rand() % 10000; // Random RNTI for demonstration
    shuffle_crc_flag(&crc_pdu.CRCFLAG);

    manager->crcs[manager->count] = crc_pdu;

    manager->count++;

    pthread_mutex_unlock(&manager->lock);

    return 0;
}

DynamicArrayManager* init_manager(int max_entries) {
    DynamicArrayManager *manager = malloc(sizeof(DynamicArrayManager));
    if (!manager) return NULL;

    pthread_mutex_init(&manager->lock, NULL);
    manager->count = 0;
    manager->ues = malloc(max_entries * sizeof(UEState));
    manager->crcs = malloc(max_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!manager->ues || !manager->crcs) {
        free(manager->ues);
        free(manager->crcs);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
        return NULL;
    }

    return manager;
}

void destroy_manager(DynamicArrayManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->ues[i].MeasurementResults);
    }
    pthread_mutex_destroy(&manager->lock);
    free(manager->ues);
    free(manager->crcs);
    free(manager);
}

void process_csv_file(DynamicArrayManager *manager, const char *file_path) {
    FILE *file = fopen(file_path, "r");
    if (!file) return; // Handle file open error

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        process_csv_line(manager, line);
    }

    fclose(file);
}

int main(int argc, char **argv) {
    srand(time(NULL));  // Seed random number generator
    int max_entries;

    if (read_config("config.conf", &max_entries) != 0)
        return -1;  // Handle config error

    DynamicArrayManager *manager = init_manager(max_entries);
    if (!manager) return -2;  // Failed to initialize manager

    process_csv_file(manager, "ue_data.csv");

    destroy_manager(manager);

    return 0;
}
