    float sum = 0.0f;
    for (size_t i = 0; i < count; ++i) {
        sum += array[i];
    }
    return sum / count;
}

void free_frames(NFAPI_RX_FRAME_PDU_T *frames, size_t frame_count) {
    for (size_t i = 0; i < frame_count; ++i) {
        free(frames[i].buffer);
    }
