int process_rx_frames_and_data(const char *config_file_path) {
    FILE *file = fopen(config_file_path, "r");
    if (!file) {
        perror("Failed to open configuration file");
        return -1;
    }

    NFAPI_RX_FRAME_PDU_T *frames = NULL;
    size_t frame_count = 0;
    int ue_id, srs_index;
    float rssi;

    // Use a simple hash set for unique UE_ID and SRS_INDEX
    int max_entries = 10000; // Adjust as necessary
    int ue_srs_set[max_entries];
    memset(ue_srs_set, -1, sizeof(ue_srs_set));

    while (fscanf(file, "%d %d %f", &ue_id, &srs_index, &rssi) == 3) {
        int hash_key = (ue_id * 31 + srs_index) % max_entries;
        while (ue_srs_set[hash_key] != -1 && 
               !(ue_srs_set[hash_key] == ue_id && (ue_srs_set[hash_key] >> 16) == srs_index)) {
            hash_key = (hash_key + 1) % max_entries;
        }
        if (ue_srs_set[hash_key] != -1) {
            fprintf(stderr, "Warning: Duplicate UE_ID and SRS_INDEX (%d, %d)\n", ue_id, srs_index);
            continue;
        }

        // Allocate memory for new frame
        NFAPI_RX_FRAME_PDU_T *new_frames = realloc(frames, (frame_count + 1) * sizeof(NFAPI_RX_FRAME_PDU_T));
        if (!new_frames) {
            perror("Memory allocation failed");
            free_frames(frames, frame_count);
            fclose(file);
            return -1;
        }
        frames = new_frames;

        // Initialize the new frame
        frames[frame_count].UE_ID = ue_id;
        frames[frame_count].SRS_INDEX = srs_index;
        frames[frame_count].buffer = NULL; // Assume buffer is set elsewhere
        frames[frame_count].timestamp = 0.0; // Placeholder for actual timestamp
        frames[frame_count].RSSI = rssi;

        // Store in hash set
        ue_srs_set[hash_key] = (ue_id << 16) | srs_index;

        frame_count++;
    }
    fclose(file);

    // Read floating-point numbers from stdin
    float *float_values = NULL;
    size_t value_count = 0;
    while (scanf("%f", &rssi) == 1) {
        float *new_floats = realloc(float_values, (value_count + 1) * sizeof(float));
        if (!new_floats) {
            perror("Memory allocation failed");
            free_frames(frames, frame_count);
            return -1;
        }
        float_values = new_floats;
        float_values[value_count++] = rssi;
    }

    // Calculate averages
    float average_rssi = 0.0f;
    if (frame_count > 0) {
        for (size_t i = 0; i < frame_count; ++i) {
            average_rssi += frames[i].RSSI;
        }
        average_rssi /= frame_count;
    }

    float average_floats = calculate_average(float_values, value_count);

    // Print results
    printf("Average RSSI: %.2f\n", average_rssi);
    printf("Average of floating-point numbers: %.2f\n", average_floats);

    // Free allocated memory
    free_frames(frames, frame_count);
    free(float_values);

    return 0;
}
