```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>

#define MAX_QUEUE_CAPACITY 1000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[5];
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* items[MAX_QUEUE_CAPACITY];
    size_t front, rear, count;
    pthread_mutex_t mutex;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} ThreadSafeQueue;

ThreadSafeQueue queue;
int allowed_rnti_min = 0;  // Default values
int allowed_rnti_max = 65535;
int queue_capacity = MAX_QUEUE_CAPACITY;

// Fetch configuration from external source (stub function)
void fetch_configuration() {
    // In practice, this would involve network calls or similar operations.
    // Here we simulate it with fixed values and potential delays or failures.

    // Simulating latency
    printf("Fetching configuration...\n");
    sleep(1);

    // Simulate a successful fetch
    allowed_rnti_min = 1000;  // Example range from the external source
    allowed_rnti_max = 60000;
    queue_capacity = MAX_QUEUE_CAPACITY;  // Assuming it's fetched

    printf("Configuration: RNTI range [%d, %d], Queue Capacity: %d\n",
           allowed_rnti_min, allowed_rnti_max, queue_capacity);
}

// Initialize the thread-safe queue
void init_queue(ThreadSafeQueue* q) {
    q->front = 0;
    q->rear = -1;
    q->count = 0;
    pthread_mutex_init(&q->mutex, NULL);
    pthread_cond_init(&q->not_full, NULL);
    pthread_cond_init(&q->not_empty, NULL);
}

// Enqueue operation with back-pressure mechanism
bool enqueue(ThreadSafeQueue* q, NFAPI_CRC_INDICATION_PDU_T* item) {
    pthread_mutex_lock(&q->mutex);

    while (q->count == queue_capacity) {
        printf("Queue is full. Applying back-pressure...\n");
        pthread_cond_wait(&q->not_full, &q->mutex);
    }

    q->rear = (q->rear + 1) % MAX_QUEUE_CAPACITY;
    q->items[q->rear] = item;
    q->count++;

    pthread_cond_signal(&q->not_empty);
    pthread_mutex_unlock(&q->mutex);
    return true;
}

// Dequeue operation
NFAPI_CRC_INDICATION_PDU_T* dequeue(ThreadSafeQueue* q) {
    pthread_mutex_lock(&q->mutex);

    while (q->count == 0) {
        pthread_cond_wait(&q->not_empty, &q->mutex);
    }

    NFAPI_CRC_INDICATION_PDU_T* item = q->items[q->front];
    q->front = (q->front + 1) % MAX_QUEUE_CAPACITY;
    q->count--;

    pthread_cond_signal(&q->not_full);
    pthread_mutex_unlock(&q->mutex);
    return item;
}

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void manage_nfa_list(size_t n) {
    fetch_configuration();  // Fetch initial configuration

    srand(time(NULL));  // Seed for random number generation

    for (size_t i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            perror("Memory allocation failed");
            continue;
        }

        pdu->RX_UE_INFORMATION_TAG = rand();  // Assign random value
        pdu->RNTI = (rand() % (allowed_rnti_max - allowed_rnti_min + 1)) + allowed_rnti_min;

        if (pdu->RNTI < allowed_rnti_min || pdu->RNTI > allowed_rnti_max) {
            printf("Out-of-range RNTI value: %d\n", pdu->RNTI);
            free(pdu);
            continue;
        }

        for (int j = 0; j < 5; ++j) {
            pdu->CRC_INDICATION_REL8_TAG[j] = rand() % 256;  // Assign random byte values
        }

        pdu->CRCFLAG = rand() % 2 == 0;  // Randomly set CRCFLAG

        if (!enqueue(&queue, pdu)) {
            printf("Failed to enqueue item.\n");
            free(pdu);
        }
    }
}

int main() {
    init_queue(&queue);

    size_t n = 1500;  // Example number of items
    manage_nfa_list(n);

    // Clean up: Dequeue and free all allocated memory (in real code, this would be more complex)
    while (queue.count > 0) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = dequeue(&queue);
        if (pdu) {
            free(pdu);
        }
    }

    return 0;
}
