#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a structure to hold CRC indication data.
typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint8_t CRCFLAG;
        // Other fields can be added here as needed
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a structure for the dynamic array manager.
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;       // Dynamic array of entries
    size_t capacity;                         // Current allocated capacity
    size_t count;                            // Number of valid entries
    pthread_mutex_t lock;                    // Mutex for thread safety
} CRC_Indication_Manager;

// Initialize the manager.
int crc_ind_manager_init(CRC_Indication_Manager *manager, size_t initial_capacity) {
    if (!manager) return -1;

    pthread_mutex_init(&manager->lock, NULL);
    manager->array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * initial_capacity);
    if (!manager->array) {
        pthread_mutex_destroy(&manager->lock);
        return -1; // Memory allocation failed
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    return 0;
}

// Destroy the manager, freeing all allocated resources.
void crc_ind_manager_destroy(CRC_Indication_Manager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);
    free(manager->array);
    manager->array = NULL;
    manager->capacity = 0;
    manager->count = 0;
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
}

// Add or update an entry based on RNTI.
int crc_ind_manager_add_or_update(CRC_Indication_Manager *manager, 
                                  NFAPI_CRC_INDICATION_PDU_T new_entry) {
    if (!manager || !new_entry.array) return -1;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->array[i].RNTI == new_entry.RNTI) { // Update existing entry
            manager->array[i] = new_entry;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    // Add new entry if RNTI not found and ensure capacity.
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(manager->array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
        if (!new_array) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory reallocation failed
        }
        manager->array = new_array;
        manager->capacity = new_capacity;
    }

    manager->array[manager->count++] = new_entry;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Retrieve the entire array.
NFAPI_CRC_INDICATION_PDU_T *crc_ind_manager_get_all(CRC_Indication_Manager *manager, size_t *out_count) {
    if (!manager || !out_count) return NULL;

    pthread_mutex_lock(&manager->lock);

    *out_count = manager->count;
    NFAPI_CRC_INDICATION_PDU_T *snapshot_array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * manager->count);

    if (snapshot_array) {
        memcpy(snapshot_array, manager->array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * manager->count);
    }

    pthread_mutex_unlock(&manager->lock);

    return snapshot_array; // Caller must free this memory
}

