typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *buffer;
    size_t head;
    size_t tail;
    size_t count;
    pthread_mutex_t mutex;
    pthread_cond_t cond_non_empty;
    pthread_cond_t cond_non_full;
} CircularBuffer;

CircularBuffer cb = { .buffer = NULL, .head = 0, .tail = 0, .count = 0 };

// External logging service interface placeholder
