Config config;

void initialize_buffer() {
    cb.buffer = (NFAPI_CRC_INDICATION_PDU_T *)malloc(MAX_BUFFER_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!cb.buffer) {
        async_log("ERROR: Memory allocation for circular buffer failed");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&cb.mutex, NULL);
    pthread_cond_init(&cb.cond_non_empty, NULL);
    pthread_cond_init(&cb.cond_non_full, NULL);
}

void cleanup_buffer() {
    free(cb.buffer);
    cb.buffer = NULL;
    pthread_mutex_destroy(&cb.mutex);
    pthread_cond_destroy(&cb.cond_non_empty);
    pthread_cond_destroy(&cb.cond_non_full);
}

uint32_t default_crcflag_generator(uint32_t RNTI, uint16_t ue_info) {
    // Implement a simple CRCFLAG generator algorithm here
    return RNTI ^ (ue_info << 1);
}

void set_config(Config *new_config) {
    if (!new_config->crcflag_generator) {
        new_config->crcflag_generator = default_crcflag_generator;
    }
    config = *new_config;
}

void add_pdu(NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&cb.mutex);
    while (cb.count == MAX_BUFFER_SIZE) {
        pthread_cond_wait(&cb.cond_non_full, &cb.mutex);
    }

    cb.buffer[cb.tail] = pdu;
    cb.tail = (cb.tail + 1) % MAX_BUFFER_SIZE;
    cb.count++;
    pthread_cond_signal(&cb.cond_non_empty);

    async_log("INFO: Successfully added PDU to buffer");
    pthread_mutex_unlock(&cb.mutex);
}

NFAPI_CRC_INDICATION_PDU_T get_pdu() {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pthread_mutex_lock(&cb.mutex);
    while (cb.count == 0) {
        pthread_cond_wait(&cb.cond_non_empty, &cb.mutex);
    }

    pdu = cb.buffer[cb.head];
    cb.head = (cb.head + 1) % MAX_BUFFER_SIZE;
    cb.count--;
    pthread_cond_signal(&cb.cond_non_full);

    async_log("INFO: Successfully retrieved PDU from buffer");
    pthread_mutex_unlock(&cb.mutex);
    return pdu;
}

void* generate_pdus(void *arg) {
