        if (!config[i].dlsch_allocations) {
            fprintf(stderr, "Memory allocation failed within RRC_CONFIG_DLSCH_TAG\n");
            // Free previously allocated memory before returning
            for (int j = 0; j < i; ++j) {
                free(config[j].dlsch_allocations);
