#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_MEMORY_POOL_SIZE 1024 * 1024 // Example size for memory pool

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPool {
    void* pool;
    size_t block_size;
    size_t total_blocks;
    size_t free_blocks;
    pthread_mutex_t mutex;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t total_blocks) {
    if (block_size * total_blocks > MAX_MEMORY_POOL_SIZE)
        return NULL;

    MemoryPool* mp = malloc(sizeof(MemoryPool));
    if (!mp) return NULL;

    mp->pool = malloc(block_size * total_blocks);
    if (!mp->pool) {
        free(mp);
        return NULL;
    }

    mp->block_size = block_size;
    mp->total_blocks = total_blocks;
    mp->free_blocks = total_blocks;
    pthread_mutex_init(&mp->mutex, NULL);

    return mp;
}

void* allocate_from_pool(MemoryPool* mp) {
    if (!mp || mp->free_blocks == 0)
        return NULL;

    pthread_mutex_lock(&mp->mutex);
    void* block = (char*)mp->pool + (--mp->free_blocks) * mp->block_size;
    pthread_mutex_unlock(&mp->mutex);

    return block;
}

void release_memory_pool(MemoryPool** mp) {
    if (!mp || !(*mp))
        return;

    MemoryPool* pool = *mp;
    free(pool->pool);
    pthread_mutex_destroy(&pool->mutex);
    free(pool);
    *mp = NULL;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_nfa_crc_pdu_array(size_t N, MemoryPool** memory_pool) {
    if (N <= 0)
        return NULL;

    size_t block_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);

    if (*memory_pool == NULL || (*memory_pool)->block_size < block_size) {
        release_memory_pool(memory_pool);
        *memory_pool = create_memory_pool(block_size, N);
        if (!*memory_pool)
            return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)allocate_from_pool(*memory_pool);

    if (!array) {
        // Implement fallback strategy
        fprintf(stderr, "Memory pool exhausted. Allocation failed.\n");
        return NULL;
    }

    for (size_t i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 256; // Example range
        array[i].RNTI = rand() % 4096;                 // Example range
        array[i].CRC_INDICATION_REL8_TAG = rand() % 1024; // Example range
        array[i].CRCFLAG = (rand() % 10) < 2 ? 0xFF : rand() % 256; // Random, including occasional invalid value
    }

    return array;
}

void log_performance_metrics(size_t allocation_time_us, size_t memory_usage_kb, size_t throughput) {
    printf("Allocation Time: %zu us\n", allocation_time_us);
    printf("Memory Usage: %zu KB\n", memory_usage_kb);
    printf("Throughput: %zu PDUs/sec\n", throughput);
}

int main() {
    srand(time(NULL));
    MemoryPool* pool = NULL;

    size_t N = 100; // Example size
    struct timespec start, end;

    clock_gettime(CLOCK_MONOTONIC, &start);

    NFAPI_CRC_INDICATION_PDU_T* pdu_array = allocate_nfa_crc_pdu_array(N, &pool);
    if (!pdu_array) {
        fprintf(stderr, "Failed to allocate PDU array\n");
        return 1;
    }

    clock_gettime(CLOCK_MONOTONIC, &end);

    size_t allocation_time_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

    // Example metrics logging
