#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>

#define INITIAL_SIZE 16

typedef struct {
    int valid_RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} NFList;

// Function to initialize the list
NFList* nf_list_create() {
    NFList *list = malloc(sizeof(NFList));
    if (list) {
        list->elements = calloc(INITIAL_SIZE, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list->capacity = INITIAL_SIZE;
        list->count = 0;
        pthread_mutex_init(&list->lock, NULL);
    }
    return list;
}

// Function to destroy the list and free resources
void nf_list_destroy(NFList *list) {
    if (list) {
        free(list->elements);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

// Function to add a new element to the list
void nf_list_add(NFList *list, int valid_RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    pthread_mutex_lock(&list->lock);

    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_elements = realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_elements) {
            pthread_mutex_unlock(&list->lock);
            return; // Handle reallocation failure
        }
        list->elements = new_elements;
        list->capacity = new_capacity;
    }

    size_t index = list->count++;
    list->elements[index].valid_RX_UE_INFORMATION_TAG = valid_RX_UE_INFORMATION_TAG;
    list->elements[index].RNTI = RNTI;
    list->elements[index].CRC_INDICATION_REL8_TAG = rand() % 256; // Random value
    list->elements[index].CRCFLAG = rand() % 2;

    pthread_mutex_unlock(&list->lock);
}

// Function to remove an element based on RNTI
void nf_list_remove(NFList *list, uint16_t RNTI) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->elements[i].RNTI == RNTI) {
            memmove(&list->elements[i], &list->elements[i + 1], (list->count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            list->count--;
            break;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to iterate over the list and perform an action on each element
void nf_list_iterate(NFList *list, void (*action)(NFAPI_CRC_INDICATION_PDU_T *)) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        action(&list->elements[i]);
    }

    pthread_mutex_unlock(&list->lock);
}

// Example usage of the nf_list_iterate function
void print_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    printf("RNTI: %u, CRCFLAG: %d\n", pdu->RNTI, pdu->CRCFLAG);
}

int main() {
    NFList *list = nf_list_create();

    // Example additions
    for (uint16_t i = 0; i < 20; ++i) {
        nf_list_add(list, 1, i);
    }

    // Remove element with RNTI 10
    nf_list_remove(list, 10);

    // Iterate and print each PDU
    nf_list_iterate(list, print_pdu);

    nf_list_destroy(list);
    return 0;
}
