    size_t count;
    pthread_rwlock_t lock;
} CRC_Indications;

void log_error(const char* message) {
    printf("ERROR: %s\n", message);
}

CRC_Indications* allocate_and_populate_crc_indications(size_t max_size, int emergency_flag) {
    if (max_size & EMERGENCY_FLAG) {
        max_size &= ~EMERGENCY_FLAG;
    }

    CRC_Indications* indications = calloc(1, sizeof(CRC_Indications));
    if (!indications) {
        log_error("Memory allocation for CRC_Indications failed");
        return NULL;
    }

    pthread_rwlock_init(&indications->lock, NULL);
    indications->array = malloc(max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!indications->array) {
        free(indications);
        log_error("Memory allocation for CRC_Indication array failed");
        return NULL;
    }

    srand(time(NULL)); // Seed random number generator

    pthread_rwlock_wrlock(&indications->lock);
    size_t current_size = 0;

    while (current_size < max_size) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        int tag, rnti, crcflag;

        do {
            tag = rand() % 10000; // Example range
        } while (!validate_rx_ue_tag(tag));

        do {
            rnti = rand() % 1000; // Example range
        } while (!validate_rnti(rnti) || current_size > 0 && indications->array[current_size - 1].RX_UE_INFORMATION_TAG == tag);

        crcflag = rand() % 2;
        pdu.RX_UE_INFORMATION_TAG = tag;
        pdu.RNTI = rnti;

        for (size_t i = 0; i < current_size; ++i) {
            if (indications->array[i].RX_UE_INFORMATION_TAG == tag) {
                goto next_iteration; // Duplicate found, retry
            }
        }

        indications->array[current_size++] = pdu;
next_iteration:
        if (current_size >= max_size) {
            log_error("Maximum size limit reached");
            break;
        }
    }

    pthread_rwlock_unlock(&indications->lock);
    indications->count = current_size;

    return indications;
}

void free_crc_indications(CRC_Indications* indications) {
    if (!indications) return;

    pthread_rwlock_wrlock(&indications->lock);
    free(indications->array);
    pthread_rwlock_unlock(&indications->lock);

    pthread_rwlock_destroy(&indications->lock);
    free(indications);
}

int main() {
    CRC_Indications* indications = allocate_and_populate_crc_indications(MAX_SIZE, 0);
    if (indications) {
        // Use the indications
        free_crc_indications(indications);
    }
    return 0;
}
