['Below is a robust implementation in C that addresses the specified requirements. This example assumes certain types like `NFAPI_MESSAGE_T`, `PDCP_PDU`, and `L2_HEADER` are predefined, and includes threading, synchronization, memory management, and configuration.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>
#include <time.h>

#define MAX_MESSAGES 10000
#define DEFAULT_PRUNE_THRESHOLD 1000

typedef struct {
    // Assuming PDCP_PDU is a defined structure
    char* pdcp_pdu;
    size_t pdu_size;

    // Assuming L2_HEADER is a defined structure
    char* l2_header;
    size_t header_size;
} NFAPI_MESSAGE_T;

typedef struct MessageNode {
    NFAPI_MESSAGE_T message;
    struct MessageNode* next;
} MessageNode;

typedef struct {
    MessageNode* head;
    pthread_mutex_t lock;
    int max_entries;
    pthread_cond_t cond_var;
    int active_messages;
} MessageList;

MessageList global_message_list = {NULL, PTHREAD_MUTEX_INITIALIZER, DEFAULT_PRUNE_THRESHOLD, PTHREAD_COND_INITIALIZER, 0};

void init_message_list(MessageList* list, int max_entries) {
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond_var, NULL);
    list->max_entries = max_entries;
    list->head = NULL;
}

void free_node(MessageNode* node) {
    if (node) {
        free(node->message.pdcp_pdu);
        free(node->message.l2_header);
        free(node);
    }
}

void prune_list(MessageList* list) {
    pthread_mutex_lock(&list->lock);

    MessageNode **current = &list->head;
    while (*current && (*current)->next != NULL) {
        current = &(*current)->next;
    }

    if (current && *current) {
        free_node(*current);
        *current = NULL;
    }

    pthread_mutex_unlock(&list->lock);
}

void add_message_to_list(MessageList* list, NFAPI_MESSAGE_T message) {
    MessageNode* new_node = malloc(sizeof(MessageNode));
    if (!new_node) {
        perror("Failed to allocate memory for new message node");
        return;
    }

    new_node->message = message;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);

    // Add the new node at the head of the list
    new_node->next = list->head;
    list->head = new_node;
    list->active_messages++;

    if (list->active_messages > list->max_entries) {
        prune_list(list);
    }

    pthread_mutex_unlock(&list->lock);

    // Notify any waiting threads about the change in the active messages count
    pthread_cond_signal(&list->cond_var);
}

void process_message(NFAPI_MESSAGE_T message) {
    // Dummy processing function
    printf("Processing message\n");
}

void* message_handler(void* arg) {
    while (1) {
        NFAPI_MESSAGE_T message;

        pthread_mutex_lock(&global_message_list.lock);

        if (global_message_list.head == NULL) {
            pthread_cond_wait(&global_message_list.cond_var, &global_message_list.lock);
        }

        // Remove the head of the list
        MessageNode* node = global_message_list.head;
        if (node) {
            message = node->message;
            global_message_list.head = node->next;
            global_message_list.active_messages--;

            pthread_mutex_unlock(&global_message_list.lock);

            process_message(message);
            free_node(node);

        } else {
            pthread_mutex_unlock(&global_message_list.lock);
        }

        // Simulate variable processing time
        usleep(rand() % 1000);
    }

    return NULL;
}

int main(int argc, char** argv) {
    int num_threads = 4; // Number of threads to handle messages

    init_message_list(&global_message_list, DEFAULT_PRUNE_THRESHOLD);

    pthread_t handlers[num_threads];

    for (int i = 0; i < num_threads; ++i) {
        if(pthread_create(&handlers[i], NULL, message_handler, NULL)) {
            perror("Failed to create thread");
            return EXIT_FAILURE;
        }
    }

    // Simulate incoming messages
    while (1) {
        NFAPI_MESSAGE_T message;
        message.pdcp_pdu = malloc(1024); // Example size
        message.header_size = 256;       // Example size
        if (!message.pdcp_pdu || !message.l2_header) {
            perror("Failed to allocate memory for message");
            continue;
        }

        add_message_to_list(&global_message_list, message);

        usleep(rand() % 1000); // Simulate variable incoming rate
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(handlers[i], NULL);
    }

    return EXIT_SUCCESS;
}
