#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t size;
    size_t capacity;
    pthread_rwlock_t lock;  // Read-write lock for concurrency control
} DynamicArray;

// Function to initialize the dynamic array
void init_dynamic_array(DynamicArray* arr) {
    arr->array = NULL;
    arr->size = 0;
    arr->capacity = 0;
    pthread_rwlock_init(&arr->lock, NULL);
}

// Internal function to resize the array
static void resize_array(DynamicArray* arr) {
    size_t new_capacity = (arr->capacity == 0) ? 4 : arr->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(arr->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        perror("Failed to resize array");
        exit(EXIT_FAILURE);
    }
    arr->array = new_array;
    arr->capacity = new_capacity;
}

// Function to add a new element
void add_element(DynamicArray* arr, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_rwlock_wrlock(&arr->lock);

    if (arr->size == arr->capacity) {
        resize_array(arr);
    }

    // Validate the integrity of the data before insertion
    if (element.RX_UE_INFORMATION_TAG < 0 || element.RNTI < 0 || element.CRC_INDICATION_REL8_TAG < 0) {
        pthread_rwlock_unlock(&arr->lock);
        fprintf(stderr, "Invalid data received\n");
        return;
    }

    arr->array[arr->size++] = element;

    pthread_rwlock_unlock(&arr->lock);
}

// Function to remove an element by index
void remove_element(DynamicArray* arr, size_t index) {
    if (index >= arr->size) {
        fprintf(stderr, "Index out of bounds\n");
        return;
    }

    pthread_rwlock_wrlock(&arr->lock);

    memmove(&arr->array[index], &arr->array[index + 1], (arr->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    arr->size--;

    pthread_rwlock_unlock(&arr->lock);
}

// Function to update an element by RX_UE_INFORMATION_TAG
void update_element(DynamicArray* arr, int tag, NFAPI_CRC_INDICATION_PDU_T new_data) {
    pthread_rwlock_wrlock(&arr->lock);

    for (size_t i = 0; i < arr->size; ++i) {
        if (arr->array[i].RX_UE_INFORMATION_TAG == tag) {
            // Validate the integrity of the data before update
            if (new_data.RNTI < 0 || new_data.CRC_INDICATION_REL8_TAG < 0) {
                pthread_rwlock_unlock(&arr->lock);
                fprintf(stderr, "Invalid data received\n");
                return;
            }
            arr->array[i] = new_data;
            break;
        }
    }

    pthread_rwlock_unlock(&arr->lock);
}

// Function to free the dynamic array
void free_dynamic_array(DynamicArray* arr) {
    pthread_rwlock_wrlock(&arr->lock);

    free(arr->array);
    arr->array = NULL;
    arr->size = 0;
    arr->capacity = 0;

    pthread_rwlock_unlock(&arr->lock);
    pthread_rwlock_destroy(&arr->lock);
}

// Example usage
int main() {
    DynamicArray arr;
    init_dynamic_array(&arr);

    NFAPI_CRC_INDICATION_PDU_T pdu1 = {1, 100, 200};
    add_element(&arr, pdu1);

    NFAPI_CRC_INDICATION_PDU_T pdu2 = {2, 101, 201};
    add_element(&arr, pdu2);

    update_element(&arr, 1, (NFAPI_CRC_INDICATION_PDU_T){1, 102, 202});

    remove_element(&arr, 0);

    free_dynamic_array(&arr);
    return 0;
}
