    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Define the dynamically managed list and its mutex lock.
typedef struct {
    Node* head;
    pthread_mutex_t lock; // Mutex for synchronizing access
} CRCIndicationList;

// Function to initialize the list.
void initCRCIndicationList(CRCIndicationList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Helper function to validate CRC flag.
int validateCRCFlag(unsigned char crc_flag) {
    // Example validation logic
    return (crc_flag == 0x01); // Assuming 0x01 is a valid flag for demonstration purposes
}

// Function to add an element to the list.
void addElement(CRCIndicationList* list, unsigned int ue_tag, unsigned int rnti,
                unsigned char crc_flag, void* payload_data) {
    if (!validateCRCFlag(crc_flag)) {
        fprintf(stderr, "Invalid CRC flag.\n");
        return;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for node");
        return;
    }

    // Allocate memory and copy payload data.
    new_node->data.payload_data = malloc(payload_data ? 1024 : 0); // Assume a fixed size buffer of 1024 bytes
    if (payload_data && new_node->data.payload_data) {
        memcpy(new_node->data.payload_data, payload_data, 1024);
    }

    new_node->data.RX_UE_INFORMATION_TAG = ue_tag;
    new_node->data.RNTI = rnti;
    new_node->data.CRC_INDICATION_REL8_TAG = crc_flag;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);

    // Add the new node to the list.
    if (list->head == NULL) {
        list->head = new_node;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to free the list and its resources.
void freeCRCIndicationList(CRCIndicationList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        if (current->data.payload_data) {
            free(current->data.payload_data);
        }
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}

