#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>

#define MAX_ELEMENTS 10000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    unsigned int count;
    unsigned int *rnti_set;
} RNTIList;

RNTIList* create_list() {
    RNTIList* list = (RNTIList*)malloc(sizeof(RNTIList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    list->rnti_set = calloc(MAX_ELEMENTS, sizeof(unsigned int));
    return list;
}

bool is_rnti_unique(RNTIList* list, unsigned int rnti) {
    pthread_mutex_lock(&list->lock);
    bool unique = (list->rnti_set[rnti % MAX_ELEMENTS] == 0);
    if (unique) {
        list->rnti_set[rnti % MAX_ELEMENTS] = rnti;
    }
    pthread_mutex_unlock(&list->lock);
    return unique;
}

void free_list(RNTIList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    free(list->rnti_set);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void add_pdu(RNTIList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!is_rnti_unique(list, pdu.RNTI)) {
        printf("RNTI %u is not unique.\n", pdu.RNTI);
        return;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = pdu;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    list->count++;
    pthread_mutex_unlock(&list->lock);
}

void simulate_external_rnti_assignment(RNTIList* list) {
    for (unsigned int i = 0; i < MAX_ELEMENTS; ++i) {
