        pdu.RX_UE_INFORMATION_TAG = rand() % 1000;
        pdu.RNTI = rand() % MAX_ELEMENTS;
        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        add_pdu(list, pdu);
    }
}

void print_list(RNTIList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        printf("RNTI: %u, RX_UE_INFORMATION_TAG: %u, CRCFLAG: %d\n",
               current->data.RNTI,
               current->data.RX_UE_INFORMATION_TAG,
               current->data.CRC_INDICATION_REL8_TAG.CRCFLAG);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void* thread_func(void* arg) {
    RNTIList* list = (RNTIList*)arg;
    simulate_external_rnti_assignment(list);
    return NULL;
}

int main() {
    srand(time(NULL));
    RNTIList* list = create_list();

    pthread_t threads[4];
    for (int i = 0; i < 4; ++i) {
        pthread_create(&threads[i], NULL, thread_func, (void*)list);
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    print_list(list);
    free_list(list);

    return 0;
}
