```java
import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;

public class FileProcessor {

    public static Map<String, String> processFilePaths(List<String> filePaths) {
        Map<String, String> fileHashes = new HashMap<>();

        for (String path : filePaths) {
            File file = new File(path);
            if (!file.exists() || !file.canRead()) {
                continue;
            }

            try {
                MessageDigest md = MessageDigest.getInstance("MD5");
                byte[] dataBytes = Files.readAllBytes(Paths.get(file.getAbsolutePath()));
                byte[] mdbytes = md.digest(dataBytes);

                StringBuilder sb = new StringBuilder();
                for (byte b : mdbytes) {
                    sb.append(String.format("%02x", b));
                }

                fileHashes.put(path, sb.toString());
            } catch (IOException | NoSuchAlgorithmException e) {
                // Handle exceptions gracefully
                System.err.println("Error processing file: " + path);
            }
        }

        return fileHashes;
    }

    public static void main(String[] args) {
        List<String> filePaths = Arrays.asList("/path/to/file1", "/path/to/file2");
        Map<String, String> hashes = processFilePaths(filePaths);

        for (Map.Entry<String, String> entry : hashes.entrySet()) {
            System.out.println("File: " + entry.getKey() + ", MD5 Hash: " + entry.getValue());
        }
    }
}
