#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>

#define LOG_FILE "memory_allocation.log"
#define MIN_RNTI 1
#define MAX_RNTI 65535

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        int CRCFLAG; // Assuming CRCFLAG is an integer type for simplicity
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef enum { LOG_CRITICAL, LOG_DETAILED } LogLevel;

void log_event(const char *message, LogLevel level) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) return; // Log failure silently

    switch (level) {
        case LOG_CRITICAL:
            fprintf(log_file, "[CRITICAL] %s\n", message);
            break;
        case LOG_DETAILED:
            fprintf(log_file, "[DETAILED] %s\n", message);
            break;
    }
    fclose(log_file);
}

int get_random_number(uint32_t *random_out) {
    int fd = open("/dev/urandom", O_RDONLY);
    if (fd < 0) return -1;

    ssize_t result = read(fd, random_out, sizeof(*random_out));
    close(fd);

    return (result == sizeof(*random_out)) ? 0 : -1;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_and_initialize_pdu_array(size_t size, LogLevel log_level) {
    NFAPI_CRC_INDICATION_PDU_T *array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * size);
    if (!array) {
        log_event("Memory allocation failed for PDU array", LOG_CRITICAL);
        return NULL;
    }

    log_event("Memory allocated for PDU array", log_level);

    uint32_t random_value;
    for (size_t i = 0; i < size; ++i) {
        // Generate RX_UE_INFORMATION_TAG
        if (get_random_number(&random_value)) {
            free(array);
            log_event("Failed to generate random number for RX_UE_INFORMATION_TAG", LOG_CRITICAL);
            return NULL;
        }
        array[i].RX_UE_INFORMATION_TAG = (uint16_t)(random_value & 0xFFFF);

        // Generate RNTI
        if (get_random_number(&random_value)) {
            free(array);
            log_event("Failed to generate random number for RNTI", LOG_CRITICAL);
            return NULL;
        }
        array[i].RNTI = MIN_RNTI + ((uint16_t)(random_value & 0xFFFF) % (MAX_RNTI - MIN_RNTI + 1));

        // Generate CRCFLAG
        if (get_random_number(&random_value)) {
            free(array);
            log_event("Failed to generate random number for CRCFLAG", LOG_CRITICAL);
            return NULL;
        }
        array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = random_value & 1; // Simplified: Randomly set to 0 or 1
    }

    log_event("PDU array initialized successfully", log_level);

    return array;
}

void free_pdu_array(NFAPI_CRC_INDICATION_PDU_T *array) {
    if (array) {
        free(array);
        log_event("Memory deallocated for PDU array", LOG_DETAILED);
    }
}
