#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Assume it's an integer for simplicity
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    char *name;
    int priority;
    time_t deadline;
} projectTask;

typedef struct TaskNode {
    projectTask task;
    struct TaskNode* next;
} TaskNode;

// Function prototypes
void freeMemory(NFAPI_CRC_INDICATION_PDU_T** pduArray, size_t count);
size_t manageData(int n);

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int main() {
    int n = 100; // Example value for N
    size_t result = manageData(n);
    printf("Successfully managed %zu structures and tasks.\n", result);
    return 0;
}

size_t manageData(int n) {
    if (n <= 0) return 0;

    pthread_mutex_lock(&mutex);

    // Allocate memory for the array of NFAPI_CRC_INDICATION_PDU_T
    NFAPI_CRC_INDICATION_PDU_T* pduArray = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pduArray) {
        pthread_mutex_unlock(&mutex);
        return 0;
    }

    // Seed random number generator
    srand(time(NULL));

    int validCount = 0;
    for (int i = 0; i < n; ++i) {
        pduArray[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        pduArray[i].RNTI = rand() % 1000;
        pduArray[i].CRC_INDICATION_REL8_TAG = rand() % 1000;

        // Ensure no two consecutive structures have the same CRCFLAG
        pduArray[i].CRCFLAG = rand() % 2;
        if (i > 0 && pduArray[i].CRCFLAG == pduArray[i - 1].CRCFLAG) {
            pduArray[i].CRCFLAG ^= 1; // Flip bit to change value
        }

        validCount++;
    }

    // Create the head of a linked list for project tasks
    TaskNode* taskList = NULL;
    for (int i = 0; i < n; ++i) {
        TaskNode* newNode = malloc(sizeof(TaskNode));
        if (!newNode) {
            freeMemory(&pduArray, validCount);
            // Free remaining nodes in case of partial failure
            while (taskList != NULL) {
                TaskNode* temp = taskList;
                taskList = taskList->next;
                free(temp->task.name);
                free(temp);
            }
            pthread_mutex_unlock(&mutex);
            return 0;
        }

        newNode->task.name = malloc(50 * sizeof(char));
        if (!newNode->task.name) {
            free(newNode);
            freeMemory(&pduArray, validCount);
            // Free remaining nodes in case of partial failure
            while (taskList != NULL) {
                TaskNode* temp = taskList;
                taskList = taskList->next;
                free(temp);
            }
            pthread_mutex_unlock(&mutex);
            return 0;
        }

        snprintf(newNode->task.name, 50, "Task %d", i + 1);

        // Generate unique priority
        int priority;
        do {
            priority = rand() % 10 + 1;
        } while (!isPriorityUnique(priority, taskList));

        newNode->task.priority = priority;

        time_t currentTime = time(NULL);
        int delaySeconds = rand() % 3600 + 1; // Random seconds between 1 and 3600
        newNode->task.deadline = currentTime + delaySeconds;

        newNode->next = taskList;
        taskList = newNode;
    }

    pthread_mutex_unlock(&mutex);

    // Free allocated memory (simulated, actual freeing would be done outside)
    freeMemory(&pduArray, validCount);
    while (taskList != NULL) {
        TaskNode* temp = taskList;
        taskList = taskList->next;
        free(temp->task.name);
        free(temp);
    }

    return validCount; // Return the number of validly populated structures and tasks
}

void freeMemory(NFAPI_CRC_INDICATION_PDU_T** pduArray, size_t count) {
    if (pduArray && *pduArray) {
        free(*pduArray);
        *pduArray = NULL;
    }
}

int isPriorityUnique(int priority, TaskNode* taskList) {
    while (taskList != NULL) {
        if (taskList->task.priority == priority) return 0;
        taskList = taskList->next;
    }
    return 1;
}
```

### Key Points:
