    return n > 0 && n <= SIZE_MAX / sizeof(NFAPI_CRC_INDICATION_PDU_T);
}

DynamicList* createDynamicList() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) {
        perror("Failed to allocate memory for dynamic list");
        return NULL;
    }
    list->head = NULL;
    list->size = 0;
    return list;
}

void freeNode(Node* node) {
    free(node);
}

void freeDynamicList(DynamicList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        freeNode(current);
        current = next;
    }
    free(list);
}

bool addElement(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    if (!list) return false;

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        perror("Failed to allocate memory for new node");
        return false;
    }
    newNode->data = element;
    newNode->next = list->head;
    list->head = newNode;
    list->size++;
    return true;
}

bool removeElement(DynamicList* list, int RX_UE_INFORMATION_TAG) {
    if (!list || !list->head) return false;

    Node *current = list->head, *prev = NULL;
    while (current && current->data.RX_UE_INFORMATION_TAG != RX_UE_INFORMATION_TAG) {
        prev = current;
        current = current->next;
    }

    if (!current) return false; // Element not found

    if (prev == NULL) { // Head needs to be removed
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    freeNode(current);
    list->size--;
    return true;
}

