#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

#define MAX_LIST_SIZE 1000
#define RNTI_MIN 1
#define RNTI_MAX 500

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int rnti;
    // Other fields...
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    size_t size;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_list() {
    LinkedList* list = malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

bool is_rnti_valid(int rnti) {
    return rnti >= RNTI_MIN && rnti <= RNTI_MAX;
}

void log_malformed_entry(const char* message) {
    fprintf(stderr, "Malformed entry: %s\n", message);
}

bool add_to_list(LinkedList* list, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= MAX_LIST_SIZE || !is_rnti_valid(pdu->rnti)) {
        log_malformed_entry("Invalid RNTI or max size reached");
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }
    *new_node = (Node){.data = *pdu, .next = list->head};
    list->head = new_node;
    list->size++;

    // Throttling can be implemented here if needed

    pthread_mutex_unlock(&list->lock);
    return true;
}

NFAPI_CRC_INDICATION_PDU_T* get_head(LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T* head_data = NULL;
    if (list->head) {
        head_data = &list->head->data;
    }

    pthread_mutex_unlock(&list->lock);
    return head_data;
}

void delete_list(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Unit tests
