    assert(!add_to_list(list, &pdu2)); // Should fail

    NFAPI_CRC_INDICATION_PDU_T* head_data = get_head(list);
    assert(head_data && head_data->rnti == 100);

    delete_list(list);
}

void test_concurrent_additions() {
    LinkedList* list = create_list();
    pthread_t threads[10];
    int rtis[] = {101, 102, 103, 104, 105, 106, 107, 108, 109, 110};

    for (int i = 0; i < 10; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = {.rnti = rtis[i]};
        pthread_create(&threads[i], NULL, (void*(*)(void*))add_to_list, list);
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    assert(list->size == 10);

    delete_list(list);
}

void run_tests() {
    test_add_and_retrieve();
