['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_LIST_SIZE 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI; // Assuming RNTI is an unsigned integer type
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t size;
} LinkedList;

// Function prototypes
LinkedList* create_list();
int validate_rnti(unsigned long rnti);
void add_pdu(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T pdu);
Node* find_node_by_rnti(LinkedList* list, unsigned long rnti);
void remove_duplicates(LinkedList* list);
void free_list(LinkedList* list);

// Create a new linked list
LinkedList* create_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) {
        perror("Failed to allocate memory for list");
        return NULL;
    }
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->size = 0;
    return list;
}

// Validate RNTI
int validate_rnti(unsigned long rnti) {
    const unsigned long MIN_RNTI = 1; // Set appropriate range
    const unsigned long MAX_RNTI = 1000000; // Set appropriate range
    return (rnti >= MIN_RNTI && rnti <= MAX_RNTI);
}

// Add a PDU to the list, ensuring it is valid and removing duplicates if necessary
void add_pdu(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    // Validate the incoming PDU
    if (!validate_rnti(pdu.RNTI)) {
        fprintf(stderr, "Malformed entry detected: Invalid RNTI value\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node* existing_node = find_node_by_rnti(list, pdu.RNTI);

    // If it's a duplicate, skip adding
    if (existing_node) {
        fprintf(stderr, "Duplicate entry detected: RNTI already exists\n");
    } else if (list->size < MAX_LIST_SIZE) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            perror("Failed to allocate memory for node");
            pthread_mutex_unlock(&list->lock);
            return;
        }
        new_node->data = pdu;
        new_node->next = list->head;
        list->head = new_node;
        list->size++;
    } else {
        fprintf(stderr, "List is full. Dropping entry\n");
    }

    // Remove any duplicates that might exist after the addition
    remove_duplicates(list);

    pthread_mutex_unlock(&list->lock);
}

// Find a node by RNTI
Node* find_node_by_rnti(LinkedList* list, unsigned long rnti) {
    Node* current = list->head;
    while (current) {
        if (current->data.RNTI == rnti) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

// Remove duplicate nodes based on RNTI
void remove_duplicates(LinkedList* list) {
    Node *current, *prev, *runner;
    for (current = list->head; current != NULL && current->next != NULL;) {
        prev = current;
        runner = current->next;

        while (runner != NULL) {
            if (current->data.RNTI == runner->data.RNTI) {
                // Duplicate found, remove runner
                Node* duplicate_node = runner;
                prev->next = runner->next;
                free(duplicate_node);
                list->size--;
            } else {
                prev = runner;
            }
            runner = runner->next;
        }

        current = current->next;
    }
}

// Free the entire linked list
void free_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next_node = current->next;
        free(current);
        current = next_node;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example usage
int main() {
    LinkedList* list = create_list();
    if (!list) return EXIT_FAILURE;

    NFAPI_CRC_INDICATION_PDU_T pdu1 = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 12345, .CRC_INDICATION_REL8_TAG = 6789 };
    add_pdu(list, pdu1);

    // Add more PDUs...

    free_list(list);
    return EXIT_SUCCESS;
}
```

