#include <pthread.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define MAX_CAPACITY 1000 // Default max capacity, can be overridden by environment variable

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} ArrayManager;

unsigned int hash_function(unsigned short rnti) {
    // Simple hash function for CRCFLAG
    return (rnti * 2654435761u) % 256; // Multiply with a prime number and mod 256
}

void log_operation(const char* operation, size_t index, unsigned short rnti) {
    pthread_t thread_id = pthread_self();
    time_t now = time(NULL);
    printf("[%s] Thread ID: %lu, Operation: %s, Index: %zu, RNTI: %u\n",
           ctime(&now), (unsigned long)thread_id, operation, index, rnti);
}

ArrayManager* init_array_manager(size_t initial_capacity) {
    ArrayManager *manager = malloc(sizeof(ArrayManager));
    manager->array = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->size = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void resize_array_manager(ArrayManager *manager) {
    size_t new_capacity = manager->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_array) {
        manager->array = new_array;
        manager->capacity = new_capacity;
    } else {
        perror("Failed to resize array");
        exit(EXIT_FAILURE);
    }
}

void initialize_structure(NFAPI_CRC_INDICATION_PDU_T *structure, size_t index) {
    structure->RX_UE_INFORMATION_TAG = (unsigned int)index; // Unique tag based on index
    structure->RNTI = (unsigned short)(index + 1);          // Simple unique RNTI
    structure->CRC_INDICATION_REL8_TAG = (unsigned char)(index % 256);
    structure->CRCFLAG = hash_function(structure->RNTI);
}

void add_structure(ArrayManager *manager, size_t index) {
    pthread_mutex_lock(&manager->lock);

