    char* env_cap = getenv("MAX_ARRAY_CAPACITY");
    if (env_cap) {
        initial_capacity = strtoul(env_cap, NULL, 10);
    }

    ArrayManager *manager = init_array_manager(initial_capacity);

    // Example usage: Adding structures in a multithreaded environment
    pthread_t threads[10];
    for (size_t i = 0; i < 10; ++i) {
        size_t index = i;
        pthread_create(&threads[i], NULL, (void *(*)(void *))add_structure, manager);
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    free_array_manager(manager);

    return 0;
}
