}

void init_management(NFAPI_CRC_ARRAY_MANAGEMENT* management, size_t initial_capacity) {
    management->array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * initial_capacity);
    if (!management->array) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    management->capacity = initial_capacity;
    management->count = 0;
    pthread_mutex_init(&management->lock, NULL);
}

void destroy_management(NFAPI_CRC_ARRAY_MANAGEMENT* management) {
    free(management->array);
    pthread_mutex_destroy(&management->lock);
}

int add_element(NFAPI_CRC_ARRAY_MANAGEMENT* management, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&management->lock);

    if (management->count == management->capacity) {
        size_t new_capacity = management->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* temp_array = realloc(management->array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
        if (!temp_array) {
            pthread_mutex_unlock(&management->lock);
            perror("Failed to reallocate memory");
            return -1;
        }
        management->array = temp_array;
        management->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T* element = &management->array[management->count];
    element->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    element->RNTI = RNTI;
    element->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    element->CRCFLAG = calculate_crcflag(RNTI);

    management->count++;
    pthread_mutex_unlock(&management->lock);

    return 0; // Success
}

int update_element(NFAPI_CRC_ARRAY_MANAGEMENT* management, size_t index, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    if (index >= management->count) {
        fprintf(stderr, "Index out of bounds\n");
        return -1;
    }

    pthread_mutex_lock(&management->lock);

    NFAPI_CRC_INDICATION_PDU_T* element = &management->array[index];
    element->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    element->RNTI = RNTI;
    element->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    element->CRCFLAG = calculate_crcflag(RNTI);

    pthread_mutex_unlock(&management->lock);

    return 0; // Success
}

int get_element(NFAPI_CRC_ARRAY_MANAGEMENT* management, size_t index, NFAPI_CRC_INDICATION_PDU_T* outElement) {
    if (index >= management->count) {
        fprintf(stderr, "Index out of bounds\n");
        return -1;
    }

    pthread_mutex_lock(&management->lock);

    *outElement = management->array[index];

    pthread_mutex_unlock(&management->lock);

    return 0; // Success
}

