#define INITIAL_CAPACITY 10

typedef struct {
    uint16_t L2_HEADER;
    uint8_t PREAMBLE;
    uint16_t MAC_SEQ_NUMBER;
    uint8_t CRCFLAG;
} MAC_PDU_T;

typedef struct {
    MAC_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} MAC_PDU_Array;

uint8_t computeCRC(uint16_t L2_HEADER) {
    // Simple hash function for demonstration purposes
    return (L2_HEADER ^ (L2_HEADER >> 4)) & 0xFF;
}

MAC_PDU_T* initialize_MAC_PDU(size_t index) {
    MAC_PDU_T *pdu = malloc(sizeof(MAC_PDU_T));
    if (!pdu) {
        perror("Failed to allocate MAC_PDU_T");
        exit(EXIT_FAILURE);
    }

    pdu->L2_HEADER = (uint16_t)index;
    pdu->PREAMBLE = (index & 0xF0) >> 4;
    pdu->MAC_SEQ_NUMBER = index + 1;
    pdu->CRCFLAG = computeCRC(pdu->L2_HEADER);

    return pdu;
}

void log_operation(const char *operation, size_t index, pthread_t thread_id) {
    time_t now;
    time(&now);
    printf("[%ld] Thread %lu: %s operation on index %zu\n", (long)now, (unsigned long)thread_id, operation, index);
}

MAC_PDU_Array* create_MAC_PDU_Array(size_t initial_capacity) {
    MAC_PDU_Array *mac_pdu_array = malloc(sizeof(MAC_PDU_Array));
    if (!mac_pdu_array) {
        perror("Failed to allocate MAC_PDU_Array");
        exit(EXIT_FAILURE);
    }

    mac_pdu_array->array = calloc(initial_capacity, sizeof(MAC_PDU_T*));
    if (!mac_pdu_array->array) {
        free(mac_pdu_array);
        perror("Failed to allocate initial MAC_PDU_T array");
        exit(EXIT_FAILURE);
    }

    mac_pdu_array->capacity = initial_capacity;
    mac_pdu_array->size = 0;

    pthread_mutex_init(&mac_pdu_array->lock, NULL);
    pthread_cond_init(&mac_pdu_array->cond, NULL);

    return mac_pdu_array;
}

void resize_MAC_PDU_Array(MAC_PDU_Array *mac_pdu_array) {
    size_t new_capacity = mac_pdu_array->capacity * 2;

    MAC_PDU_T **new_array = realloc(mac_pdu_array->array, new_capacity * sizeof(MAC_PDU_T*));
    if (!new_array) {
        perror("Failed to reallocate MAC_PDU_T array");
        exit(EXIT_FAILURE);
    }

    memset(new_array + mac_pdu_array->capacity, 0, (new_capacity - mac_pdu_array->capacity) * sizeof(MAC_PDU_T*));

    pthread_mutex_lock(&mac_pdu_array->lock);
    mac_pdu_array->array = new_array;
    mac_pdu_array->capacity = new_capacity;
    pthread_mutex_unlock(&mac_pdu_array->lock);

    log_operation("Resized", new_capacity, pthread_self());
}

void add_MAC_PDU(MAC_PDU_Array *mac_pdu_array) {
    pthread_t thread_id = pthread_self();

    if (mac_pdu_array->size == mac_pdu_array->capacity) {
        resize_MAC_PDU_Array(mac_pdu_array);
    }

    pthread_mutex_lock(&mac_pdu_array->lock);

    MAC_PDU_T *pdu = initialize_MAC_PDU(mac_pdu_array->size);
    mac_pdu_array->array[mac_pdu_array->size++] = pdu;

    log_operation("Added", mac_pdu_array->size - 1, thread_id);

    pthread_mutex_unlock(&mac_pdu_array->lock);
}

void free_MAC_PDU_Array(MAC_PDU_Array *mac_pdu_array) {
    for (size_t i = 0; i < mac_pdu_array->size; i++) {
        free(mac_pdu_array->array[i]);
    }
    free(mac_pdu_array->array);

    pthread_mutex_destroy(&mac_pdu_array->lock);
    pthread_cond_destroy(&mac_pdu_array->cond);
    free(mac_pdu_array);
}

int main() {
    MAC_PDU_Array *mac_pdu_array = create_MAC_PDU_Array(INITIAL_CAPACITY);

    // Simulate concurrent additions
    for (size_t i = 0; i < 50; i++) {
        pthread_t thread;
        if (pthread_create(&thread, NULL, (void *(*)(void *))add_MAC_PDU, mac_pdu_array) != 0) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
        pthread_join(thread, NULL);
    }

    free_MAC_PDU_Array(mac_pdu_array);

    return 0;
}
