```c
#include <stdio.h>
#include <stdlib.h>
import threading

#define MAX_PACKETS 1000

typedef struct {
    unsigned int RNTI;
    unsigned char RX_UE_INFORMATION_TAG;
    struct {
        unsigned short CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    int count;
    pthread_mutex_t lock;
} List;

List* create_list() {
    List* list = malloc(sizeof(List));
    if (!list) return NULL;

    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int add_pdu(List* list, NFAPI_CRC_INDICATION_PDU_T pdu, unsigned short crcflag) {
    pthread_mutex_lock(&list->lock);

    // Check for duplicates
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == pdu.RNTI) {
            pthread_mutex_unlock(&list->lock);
            return 0; // Duplicate RNTI, do not add
        }
        current = current->next;
    }

    if (list->count >= MAX_PACKETS) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Allocation failure
    }

    pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = crcflag;
    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 1; // Successfully added
}

void cleanup_list(List* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    list->head = NULL;
    list->count = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void iterate_list(List* list, void (*process)(NFAPI_CRC_INDICATION_PDU_T)) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        process(current->data);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Example usage function
void print_pdu(NFAPI_CRC_INDICATION_PDU_T pdu) {
    printf("RNTI: %u, RX_UE_INFORMATION_TAG: %d, CRCFLAG: %hu\n",
           pdu.RNTI,
           pdu.RX_UE_INFORMATION_TAG,
           pdu.CRC_INDICATION_REL8_TAG.CRCFLAG);
}

int main() {
    List* list = create_list();
    if (!list) return -1;

    NFAPI_CRC_INDICATION_PDU_T pdu1 = { .RNTI = 100, .RX_UE_INFORMATION_TAG = 1 };
    add_pdu(list, pdu1, 123);

    NFAPI_CRC_INDICATION_PDU_T pdu2 = { .RNTI = 200, .RX_UE_INFORMATION_TAG = 2 };
    add_pdu(list, pdu2, 456);

    iterate_list(list, print_pdu);

    cleanup_list(list);
    return 0;
}
```

### Key Points:
- **Concurrency**: The list is protected by a mutex (`pthread_mutex_t`) to ensure thread safety during modifications.
- **Memory Management**: Each node in the list is dynamically allocated and freed correctly. Allocation failures are handled gracefully without causing memory leaks.
- **Duplication Handling**: Before adding a new `NFAPI_CRC_INDICATION_PDU_T`, the function checks for duplicate `RNTI` values.
- **Cleanup**: A dedicated cleanup function ensures all resources are released properly, even in cases of partial allocation or errors.
- **Iteration**: Provides an efficient way to iterate over the list, allowing clients to process each element.']

