    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// List Structure
typedef struct {
    Node* head;
    int count;
} CRCList;

// Function Prototypes
CRCList* create_list();
void destroy_list(CRCList* list);
int add_element(CRCList* list, NFAPI_CRC_INDICATION_PDU_T element);
int update_element(CRCList* list, RNTI rnti, NFAPI_CRC_INDICATION_PDU_T updated_data);
int remove_element(CRCList* list, RNTI rnti);
void validate_list(CRCList* list);
static Node* find_node_by_rnti(Node* head, RNTI rnti);
static int is_valid_tag(RX_UE_INFORMATION_TAG tag);

// Function Implementations
CRCList* create_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;
    list->head = NULL;
    list->count = 0;
    return list;
}

void destroy_list(CRCList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

int add_element(CRCList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    if (!is_valid_tag(element.rx_ue_information_tag)) return 0;

    Node* existing_node = find_node_by_rnti(list->head, element.rnti);
    if (existing_node) return 0; // Duplicate RNTI

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return 0;

    new_node->data = element;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    validate_list(list);
    return 1;
}

int update_element(CRCList* list, RNTI rnti, NFAPI_CRC_INDICATION_PDU_T updated_data) {
    if (!is_valid_tag(updated_data.rx_ue_information_tag)) return 0;

    Node* node = find_node_by_rnti(list->head, rnti);
    if (!node) return 0; // Element not found

    node->data = updated_data;
    validate_list(list);
    return 1;
}

int remove_element(CRCList* list, RNTI rnti) {
    Node *current = list->head, *prev = NULL;

    while (current && current->data.rnti != rnti) {
        prev = current;
        current = current->next;
    }

    if (!current) return 0; // Element not found

    if (prev) {
        prev->next = current->next;
    } else {
        list->head = current->next;
    }

    free(current);
    list->count--;

    validate_list(list);
    return 1;
}

void validate_list(CRCList* list) {
    Node* current = list->head;
    while (current) {
        if (!is_valid_tag(current->data.rx_ue_information_tag)) {
            fprintf(stderr, "Invalid tag found\n");
            exit(EXIT_FAILURE);
        }
        current = current->next;
    }
}

static Node* find_node_by_rnti(Node* head, RNTI rnti) {
    while (head) {
        if (head->data.rnti == rnti) return head;
        head = head->next;
    }
    return NULL;
}

static int is_valid_tag(RX_UE_INFORMATION_TAG tag) {
    // Implement the validation logic for the tag
    return 1; // Assume valid for demonstration purposes
}
