#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <random>
#include <chrono>
#include <atomic>
#include <condition_variable>

struct Record {
    int value;
};

class ConfigurationManager {
public:
    std::atomic<int> maxEntries{5000};

    void adjustMaxEntries(int newLimit) {
        maxEntries.store(newLimit);
    }
};

std::mutex mtx;
ConfigurationManager configManager;

int selectStrategy() {
    // Simulate strategy selection logic
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(1, 10);  // Assume 10 strategies

    int cooldown = 8;  // Cooldown period in seconds
    while (true) {
        std::unique_lock<std::mutex> lock(mtx);
        auto selectedStrategy = dis(gen);

        std::cout << "Selected Strategy: " << selectedStrategy << std::endl;

        lock.unlock();
        std::this_thread::sleep_for(std::chrono::seconds(cooldown));
    }
}

void simulateDegradedNetwork() {
    // Simulate degraded network conditions
    std::this_thread::sleep_for(std::chrono::milliseconds(100));  // Simulate latency
}

void populateArraysAndSelectStrategy() {
    int maxEntries = configManager.maxEntries.load();

    std::vector<long> longOffsets(maxEntries, 0);
    std::vector<int> keys(maxEntries, 0);
    std::vector<Record> records(maxEntries);

    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(1, 100); // Random range for record values

    for (int i = 0; i < maxEntries; ++i) {
        longOffsets[i] = static_cast<long>(dis(gen));
        keys[i] = dis(gen);
        records[i].value = dis(gen);

        std::cout << "Record " << i << ": Value = " << records[i].value << std::endl;
    }

    // Start strategy selection in a separate thread
    std::thread strategyThread(selectStrategy);

    // Simulate degraded network environment for demonstration
    simulateDegradedNetwork();

    // Join threads to prevent premature exit
    if (strategyThread.joinable()) {
        strategyThread.join();
    }
}

int main() {
    populateArraysAndSelectStrategy();
    return 0;
}
```

