    size_t memory_usage;
    Node* duplicates_head;
} PacketList;

PacketList packet_list = {NULL, PTHREAD_MUTEX_INITIALIZER, 0, 0, 0, NULL};

int is_rnti_unique(unsigned int rnti) {
    pthread_mutex_lock(&packet_list.lock);
    Node* current = packet_list.head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            pthread_mutex_unlock(&packet_list.lock);
            return 0; // RNTI is not unique
        }
        current = current->next;
    }
    pthread_mutex_unlock(&packet_list.lock);
    return 1; // RNTI is unique
}

void add_duplicate(Node* new_node) {
    pthread_mutex_lock(&packet_list.lock);
    if (packet_list.duplicates_head == NULL) {
        packet_list.duplicates_head = new_node;
    } else {
