        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    pthread_mutex_unlock(&packet_list.lock);
}

void add_packet(unsigned int rx_ue_info_tag, unsigned int rnti, unsigned char crc_ind_rel8_tag, unsigned char crcflag) {
