        new_node->data.CRC_INDICATION_REL8_TAG = crc_ind_rel8_tag;
        new_node->data.CRCFLAG = crcflag;
        new_node->next = NULL;

        add_duplicate(new_node);
        return;
    }

    pthread_mutex_lock(&packet_list.lock);

    if (!packet_list.crcflag_specified) {
        packet_list.fixed_crcflag = crcflag;
        packet_list.crcflag_specified = 1;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&packet_list.lock);
        return;
    }

    new_node->data.RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    new_node->data.RNTI = rnti;
    new_node->data.CRC_INDICATION_REL8_TAG = crc_ind_rel8_tag;
    new_node->data.CRCFLAG = packet_list.fixed_crcflag;
    new_node->next = packet_list.head;

    packet_list.head = new_node;
    pthread_mutex_unlock(&packet_list.lock);

    // Update memory usage
    pthread_mutex_lock(&packet_list.lock);
    packet_list.memory_usage += sizeof(Node);
    pthread_mutex_unlock(&packet_list.lock);
}

void cleanup() {
    pthread_mutex_lock(&packet_list.lock);
    Node* current = packet_list.head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    packet_list.head = NULL;

    // Clean duplicates
    current = packet_list.duplicates_head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    packet_list.duplicates_head = NULL;

    pthread_mutex_unlock(&packet_list.lock);
}

void iterate_over_packets(void (*process)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&packet_list.lock);

    Node* current = packet_list.head;
    while (current != NULL) {
        process(&(current->data));
        current = current->next;
    }

    pthread_mutex_unlock(&packet_list.lock);
}

void process_packet(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    printf("Processing RNTI: %u\n", pdu->RNTI);
}
