#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>

#define MIN_RNTI 0x0001
#define MAX_RNTI 0xFFFF
#define CACHE_SIZE 100

typedef struct CRC_INDICATION_REL8_TAG {
    bool CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
    struct NFAPI_CRC_INDICATION_PDU_T *prev;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    NFAPI_CRC_INDICATION_PDU_T *tail;
    size_t size;
    pthread_mutex_t lock;
    unsigned int access_count;
    unsigned int cache_hits;
    unsigned int cache_misses;
    NFAPI_CRC_INDICATION_PDU_T *cache[CACHE_SIZE];
} CRCList;

void init_list(CRCList *list) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->access_count = 0;
    list->cache_hits = 0;
    list->cache_misses = 0;
}

void destroy_list(CRCList *list) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDIGATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}

bool is_rnti_valid(unsigned int rnti) {
    return rnti >= MIN_RNTI && rnti <= MAX_RNTI;
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu(unsigned int rx_tag, unsigned int rnti) {
    if (!is_rnti_valid(rnti)) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu == NULL) {
        return NULL;
    }

    pdu->RX_UE_INFORMATION_TAG = rx_tag;
    pdu->RNTI = rnti;
    pdu->crc_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    pdu->prev = NULL;
    pdu->next = NULL;

    return pdu;
}

void add_pdu(CRCList *list, unsigned int rx_tag, unsigned int rnti) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *pdu = create_pdu(rx_tag, rnti);
    if (pdu == NULL) {
        printf("Invalid RNTI or memory allocation failed\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    pdu->next = list->head;
    if (list->head != NULL) {
        list->head->prev = pdu;
    }
    list->head = pdu;

    if (list->tail == NULL) {
        list->tail = pdu;
    }

    list->size++;

    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T* get_head(CRCList *list) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *head = list->head;

    // Cache mechanism
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (list->cache[i] == head) {
            list->cache_hits++;
            pthread_mutex_unlock(&list->lock);
            return head;
        }
    }

    list->cache_misses++;

    // Update cache
    for (int i = 0; i < CACHE_SIZE - 1; ++i) {
        list->cache[i] = list->cache[i + 1];
    }
    list->cache[CACHE_SIZE - 1] = head;

    pthread_mutex_unlock(&list->lock);
    return head;
}

void print_list_stats(CRCList *list) {
    printf("Current List Size: %zu\n", list->size);
    printf("Access Count: %u\n", list->access_count);
    printf("Cache Hits: %u, Cache Misses: %u\n", list->cache_hits, list->cache_misses);
}

// Unit test function
void run_tests() {
    CRCList list;
    init_list(&list);

    // Add some PDUs
    for (unsigned int i = 0; i < 1000; ++i) {
        add_pdu(&list, i, MIN_RNTI + (i % (MAX_RNTI - MIN_RNTI + 1)));
    }

    NFAPI_CRC_INDICATION_PDU_T *head = get_head(&list);
    while (head != NULL) {
        printf("RNTI: %u, CRCFLAG: %d\n", head->RNTI, head->crc_tag.CRCFLAG);
        head = head->next;
    }

    print_list_stats(&list);

    destroy_list(&list);
}

int main() {
    srand(time(NULL));
    run_tests();
    return 0;
}
