#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pthread.h>

#define MAX_RNTI 65535

typedef struct {
    uint16_t RNTI;
    uint32_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    uint64_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    NFAPI_CRC_INDICATION_PDU_T crc_pdu;
} NFAPI_Structure;

// Custom memory pool for efficient allocation
#define POOL_SIZE 1024

typedef struct MemoryPool {
    size_t unit_size;
    void *pool;
    pthread_mutex_t lock;
} MemoryPool;

void* custom_malloc(MemoryPool *mp, size_t n) {
    pthread_mutex_lock(&mp->lock);
    // Implement memory pool allocation logic
    pthread_mutex_unlock(&mp->lock);
    return malloc(mp->unit_size * n);  // Fallback to standard malloc for simplicity
}

void* custom_free(MemoryPool *mp, void *ptr) {
    pthread_mutex_lock(&mp->lock);
    free(ptr);
    pthread_mutex_unlock(&mp->lock);
}

bool validate_structure(NFAPI_Structure *structure) {
    return (structure->RNTI <= MAX_RNTI && structure->crc_pdu.CRCFLAG < UINT32_MAX);
}

void generateNfapiPduList(int N, uint64_t seed, int logging_level, float network_load, MemoryPool *mp) {
    if (N <= 0 || mp == NULL) return;

    srand(seed);
    pthread_mutex_init(&mp->lock, NULL);

    NFAPI_Structure *pdus = custom_malloc(mp, N);
    bool validation_success[N];

    for (int i = 0; i < N; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = rand() ^ seed;
        do {
            pdus[i].RNTI = rand() % (MAX_RNTI + 1);
        } while (!validate_structure(&pdus[i]));

        float crc_flag_probability = network_load < 0.5 ? 0.3 : 0.7; // Example dynamic adjustment
        pdus[i].crc_pdu.CRCFLAG = ((float)rand() / RAND_MAX < crc_flag_probability) ? 1 : 0;

        validation_success[i] = validate_structure(&pdus[i]);
        if (logging_level > 1) {
            printf("Generated PDU %d: RNTI=%u, CRCFLAG=%u\n", i, pdus[i].RNTI, pdus[i].crc_pdu.CRCFLAG);
        }
    }

    int success_count = 0;
    for (int i = 0; i < N; ++i) {
        if (validation_success[i]) ++success_count;
    }

    printf("Validation Success Rate: %.2f%%\n", (float)success_count / N * 100);

    custom_free(mp, pdus);
    pthread_mutex_destroy(&mp->lock);
}

int main() {
    MemoryPool mp = {sizeof(NFAPI_Structure), NULL, PTHREAD_MUTEX_INITIALIZER};

    generateNfapiPduList(1000, 12345, 2, 0.6, &mp);
    return 0;
}
