typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t count;
    pthread_mutex_t lock;
} DynamicList;

// Function to initialize the dynamic list
int init_dynamic_list(DynamicList *list, size_t initial_size) {
    if (initial_size > MAX_ENTRIES) return -1; // Handle invalid input sizes

    pthread_mutex_init(&list->lock, NULL);
    list->data = malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        perror("Memory allocation failed");
        pthread_mutex_destroy(&list->lock);
        return -1;
    }

    list->count = 0;
    printf("Dynamic list initialized with size %zu\n", initial_size);
    return 0;
}

// Function to free the dynamic list
void free_dynamic_list(DynamicList *list) {
    pthread_mutex_lock(&list->lock);
    free(list->data);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    printf("Dynamic list deallocated\n");
}

// Function to add an entry to the dynamic list
int add_entry_to_list(DynamicList *list, const NFAPI_CRC_INDICATION_PDU_T *entry) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_ENTRIES) {
        printf("Maximum entries reached\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    list->data[list->count++] = *entry;
    printf("Added entry %zu to the dynamic list\n", list->count);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Function to populate a given number of entries in the dynamic list
int populate_list(DynamicList *list, size_t num_entries) {
    if (num_entries > MAX_ENTRIES || !init_dynamic_list(list, num_entries)) return -1;

    for (size_t i = 0; i < num_entries; ++i) {
        NFAPI_CRC_INDICATION_PDU_T entry;
        entry.valid_RX_UE_INFORMATION_TAG = rand(); // Simulate valid tag
        entry.RNTI = rand() % 65536; // Simulate RNTI
        entry.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1; // Randomly set CRCFLAG

        if (add_entry_to_list(list, &entry) != 0) {
            perror("Failed to add entry");
            free_dynamic_list(list);
            return -1;
        }
    }

    printf("%zu entries populated in the dynamic list\n", num_entries);
    return 0;
}

// Example usage
int main() {
    DynamicList nfaPI_CRC_LIST;

    size_t entries_to_add = 100000; // Adjust as needed for testing

    if (populate_list(&nfaPI_CRC_LIST, entries_to_add) != 0) {
        fprintf(stderr, "Failed to populate list\n");
        return EXIT_FAILURE;
    }

    free_dynamic_list(&nfaPI_CRC_LIST);

