#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define DEFAULT_BUFFER_SIZE 1024

typedef enum {
    OVERFLOW_DISCARD,
    OVERFLOW_BLOCK,
    OVERFLOW_WRAP
} OverflowStrategy;

typedef struct {
    uint8_t *data;
    size_t capacity;
    size_t head;
    size_t tail;
    size_t size;
    size_t frame_size;
    OverflowStrategy overflow_strategy;
} CircularBuffer;

// Helper function to calculate checksum (simple XOR for demonstration)
uint8_t calculateChecksum(const uint8_t *data, size_t len) {
    uint8_t checksum = 0;
    for (size_t i = 0; i < len; ++i) {
        checksum ^= data[i];
    }
    return checksum;
}

// Function to initialize the circular buffer
void initBuffer(CircularBuffer *buffer, size_t capacity, OverflowStrategy strategy) {
    buffer->data = (uint8_t *)malloc(capacity);
    if (!buffer->data) {
        perror("Failed to allocate buffer");
        exit(EXIT_FAILURE);
    }
    buffer->capacity = capacity;
    buffer->head = 0;
    buffer->tail = 0;
    buffer->size = 0;
    buffer->frame_size = 0;
    buffer->overflow_strategy = strategy;
}

// Function to manage the circular buffer
int manageDataFrameBuffer(CircularBuffer *buffer, const uint8_t *dataFrame, size_t frameSize) {
    // Calculate checksum for validation
    uint8_t expectedChecksum = dataFrame[frameSize - 1];
    if (calculateChecksum(dataFrame, frameSize - 1) != expectedChecksum) {
        fprintf(stderr, "Data integrity check failed\n");
        return -1; // Integrity failure
    }

    size_t totalSize = buffer->size + frameSize;

    // Handle overflow based on strategy
    switch (buffer->overflow_strategy) {
        case OVERFLOW_DISCARD:
            if (totalSize > buffer->capacity) {
                fprintf(stderr, "Buffer overflow, discarding data\n");
                return -2; // Overflow discarded
            }
            break;
        case OVERFLOW_BLOCK:
            if (totalSize > buffer->capacity) {
                fprintf(stderr, "Buffer overflow, blocking insertion\n");
                return -3; // Block insertion
            }
            break;
        case OVERFLOW_WRAP:
            totalSize = totalSize % buffer->capacity;
            break;
    }

    // Insert data into the buffer
    for (size_t i = 0; i < frameSize; ++i) {
        buffer->data[(buffer->head + i) % buffer->capacity] = dataFrame[i];
    }

    buffer->head = (buffer->head + frameSize) % buffer->capacity;
    if (totalSize > buffer->capacity) {
        buffer->tail = (buffer->tail + totalSize - buffer->capacity) % buffer->capacity;
        buffer->size = buffer->capacity; // Buffer is full
    } else {
        buffer->size = totalSize;
    }

    return 0; // Success
}

// Function to retrieve data from the circular buffer
int retrieveData(CircularBuffer *buffer, uint8_t *outFrame, size_t maxFrameSize) {
    if (buffer->size == 0) {
        fprintf(stderr, "Buffer underflow\n");
        return -1; // Underflow
    }

    size_t frameSize = 0;
    while (frameSize < buffer->capacity && buffer->data[buffer->tail] != 0xFF) { // Assuming 0xFF as frame delimiter
        outFrame[frameSize++]++;
    }

    if (frameSize == 0 || frameSize >= maxFrameSize) {
        fprintf(stderr, "Invalid frame size\n");
        return -2; // Invalid frame or buffer overflow
    }

    memcpy(outFrame, &buffer->data[buffer->tail], frameSize);

    // Validate checksum during retrieval
    uint8_t calculatedChecksum = calculateChecksum(outFrame, frameSize - 1);
    if (calculatedChecksum != outFrame[frameSize - 1]) {
        fprintf(stderr, "Data integrity check failed on retrieval\n");
        return -3; // Integrity failure
    }

    buffer->tail = (buffer->tail + frameSize) % buffer->capacity;
    buffer->size -= frameSize;

    return frameSize; // Return the size of the retrieved frame
}

// Function to free the circular buffer resources
void destroyBuffer(CircularBuffer *buffer) {
    if (buffer->data) {
        free(buffer->data);
        buffer->data = NULL;
    }
}
```

### Explanation

- **Checksum Calculation**: A simple XOR checksum is used for data integrity checks. This can be replaced with a more robust algorithm if needed.

- **Overflow Strategies**:
  - `OVERFLOW_DISCARD`: Discards new data if the buffer overflows.
  - `OVERFLOW_BLOCK`: Blocks insertion when the buffer is full.
  - `OVERFLOW_WRAP`: Overwrites old data in a circular manner.

- **Buffer Management**: Efficiently handles data insertion and retrieval, including wrapping and managing overflow/underflow scenarios.

- **Memory Management**: Dynamically allocates memory for the buffer and ensures proper cleanup with `destroyBuffer`.

- **Testing and Validation**: The code includes basic error handling and validation checks. Further testing should be conducted to cover edge cases and typical usage patterns.']

