    uv_run(js_context.loop, UV_RUN_DEFAULT);
}

int execute_javascript_file(const char *file_path) {
    pthread_mutex_lock(&js_context.mutex);

    FILE *script_file = fopen(file_path, "r");
    if (!script_file) {
        log_error("Unable to open JavaScript file.");
        pthread_mutex_unlock(&js_context.mutex);
        return -1;
    }

    fseek(script_file, 0, SEEK_END);
    long length = ftell(script_file);
    rewind(script_file);

    char *script_content = malloc(length + 1);
    if (!script_content) {
        fclose(script_file);
        log_error("Memory allocation failed for script content.");
        pthread_mutex_unlock(&js_context.mutex);
        return -1;
    }

    fread(script_content, 1, length, script_file);
    script_content[length] = '\0';
    fclose(script_file);

    uv_work_t *work_request = malloc(sizeof(uv_work_t));
    if (!work_request) {
        free(script_content);
        log_error("Memory allocation failed for work request.");
        pthread_mutex_unlock(&js_context.mutex);
        return -1;
    }

    struct exec_js_data {
        uv_work_t req;
        char *script;
        int status;
    };

    struct exec_js_data *data = malloc(sizeof(struct exec_js_data));
    if (!data) {
        free(script_content);
        free(work_request);
        log_error("Memory allocation failed for execution data.");
        pthread_mutex_unlock(&js_context.mutex);
        return -1;
    }

    data->req.data = (void *)data;
    data->script = script_content;
    data->status = 0;

    uv_queue_work(js_context.loop, work_request, [](uv_work_t *req) {
        struct exec_js_data *data = req->data;
        int result = system("node -e");
        if (result != 0) {
            log_error("JavaScript execution failed.");
            data->status = -1;
        }
    }, [](uv_work_t *req, int status) {
        struct exec_js_data *data = req->data;
        if (status < 0 || data->status == -1) {
            fprintf(stderr, "Error in JavaScript execution or callback.\n");
        }

        free(data->script);
        free(req);
        free(data);

        pthread_mutex_unlock(&js_context.mutex);
    });

    return 0; // Success
}

