// Define the dynamic list and its mutex
typedef struct {
    size_t count;
    size_t capacity;
    NFAPI_CRC_INDICATION_PDU_T *items;
    pthread_mutex_t lock; // Mutex for thread safety
} DynamicList;

// Function prototypes
int init_dynamic_list(DynamicList *list);
void free_dynamic_list(DynamicList *list);
int add_pdu_to_list(DynamicList *list, const RX_UE_INFORMATION_TAG *ue_info_tag);
int reset_crc_flags(DynamicList *list, int default_flag);
void log_change(const char *message);

// Initialize the dynamic list
int init_dynamic_list(DynamicList *list) {
    if (!list) return -1;

    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    list->capacity = 10; // Initial capacity

    list->items = (NFAPI_CRC_INDICATION_PDU_T *)malloc(list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->items) {
        pthread_mutex_destroy(&list->lock);
        return -1;
    }

    log_change("Dynamic list initialized.");
    return 0;
}

// Free the dynamic list
void free_dynamic_list(DynamicList *list) {
    if (list) {
        pthread_mutex_lock(&list->lock);

        if (list->items) {
            free(list->items);
            list->items = NULL;
        }

        pthread_mutex_unlock(&list->lock);
        pthread_mutex_destroy(&list->lock);
        log_change("Dynamic list freed.");
    }
}

// Add a new PDU to the dynamic list
int add_pdu_to_list(DynamicList *list, const RX_UE_INFORMATION_TAG *ue_info_tag) {
    if (!list || !ue_info_tag) return -1;

    pthread_mutex_lock(&list->lock);

    if (list->count == list->capacity) { // Resize array if needed
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_items =
            (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->items, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_items) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }

        list->items = new_items;
        list->capacity = new_capacity;
    }

    // Populate new item
    list->items[list->count].ue_info_tag = *ue_info_tag;
    list->items[list->count].crc_indication_tag.CRCFLAG = rand() % 2; // Random CRCFLAG

    log_change("PDU added to the dynamic list.");
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Reset all CRC flags in the dynamic list
int reset_crc_flags(DynamicList *list, int default_flag) {
