#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

#define MAX_RNTI 65535

typedef struct CRC_INDICATION_REL8_TAG {
    uint32_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* create_nfa_list(int num_entries) {
    NFAPI_CRC_INDICATION_PDU_T *head = NULL, **last_ptr = &head;

    srand(time(NULL));
    for (int i = 0; i < num_entries; ++i) {
        pthread_mutex_lock(&list_mutex);

        uint16_t rnti = rand() % (MAX_RNTI + 1); // Random RNTI between 0 and 65535
        if (rnti > MAX_RNTI) {
            printf("Invalid RNTI: %u, skipping entry.\n", rnti);
            pthread_mutex_unlock(&list_mutex);
            continue;
        }

        NFAPI_CRC_INDICATION_PDU_T *new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        new_node->RX_UE_INFORMATION_TAG = i;  // Example tag
        new_node->RNTI = rnti;
        new_node->crc_tag.CRCFLAG = rand() % 2;  // Random CRC flag (0 or 1)
        new_node->next = NULL;

        *last_ptr = new_node;
        last_ptr = &new_node->next;

        pthread_mutex_unlock(&list_mutex);
    }

    return head;
}

size_t serialize_list(NFAPI_CRC_INDICATION_PDU_T* head, uint8_t **buffer) {
    size_t total_size = 0;

    if (!head) return 0;
    NFAPI_CRC_INDICATION_PDU_T *current = head;

    while (current != NULL) {
        total_size += sizeof(int) + sizeof(uint16_t) + sizeof(CRC_INDICATION_REL8_TAG);
        current = current->next;
    }

    *buffer = malloc(total_size);
    if (!*buffer) {
        fprintf(stderr, "Memory allocation failed for serialization buffer\n");
        exit(EXIT_FAILURE);
    }

    uint8_t *ptr = *buffer;
    current = head;

    while (current != NULL) {
        *(int *)ptr = current->RX_UE_INFORMATION_TAG; ptr += sizeof(int);
        *(uint16_t *)ptr = current->RNTI; ptr += sizeof(uint16_t);
        *(CRC_INDICATION_REL8_TAG *)ptr = current->crc_tag; ptr += sizeof(CRC_INDICATION_REL8_TAG);

        current = current->next;
    }

    return total_size;
}

void free_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T *current = head;

    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *temp = current;
        current = current->next;
        free(temp);
    }
}

int main() {
    int num_entries = 10000; // Example number of entries
    NFAPI_CRC_INDICATION_PDU_T* head = create_nfa_list(num_entries);

    uint8_t *buffer;
    size_t buffer_size = serialize_list(head, &buffer);

    printf("Serialized list size: %zu bytes\n", buffer_size);

    free(buffer); // Free serialized data
    free_list(head); // Free the linked list

    return 0;
}
