['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <string.h>

#define MAX_ENTRIES 10000

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    int CRCFLAG; // Assume 0 or 1
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T entries[MAX_ENTRIES];
    size_t count;
    pthread_mutex_t lock;
    uint8_t cache[256]; // Simple LRU-like fixed-size cache for demonstration
    size_t cache_hits, cache_misses;
} CRCManager;

CRCManager crc_manager = {0};

void initialize_crc_manager() {
    pthread_mutex_init(&crc_manager.lock, NULL);
}

int set_crcflag(NFAPI_CRC_INDICATION_PDU_T *entry) {
    if (!entry) return -1;
    entry->CRCFLAG = rand() % 2; // Randomly sets CRCFLAG to 0 or 1
    return 0;
}

void add_entry(uint16_t tag, uint16_t rnti) {
    pthread_mutex_lock(&crc_manager.lock);

    if (crc_manager.count < MAX_ENTRIES) {
        NFAPI_CRC_INDICATION_PDU_T *entry = &crc_manager.entries[crc_manager.count++];

        entry->RX_UE_INFORMATION_TAG = tag;
        entry->RNTI = rnti;

        // Set CRCFLAG with error handling
        if (set_crcflag(entry) != 0) {
            fprintf(stderr, "Failed to set CRCFLAG for RNTI: %u\n", rnti);
            pthread_mutex_unlock(&crc_manager.lock);
            return;
        }
    } else {
        fprintf(stderr, "Maximum entries reached.\n");
    }

    pthread_mutex_unlock(&crc_manager.lock);
}

void process_entries() {
    pthread_mutex_lock(&crc_manager.lock);

    for (size_t i = 0; i < crc_manager.count; ++i) {
        // Process each entry
        NFAPI_CRC_INDICATION_PDU_T *entry = &crc_manager.entries[i];

        // Simple cache lookup simulation
        if (entry->RX_UE_INFORMATION_TAG < sizeof(crc_manager.cache)) {
            if (crc_manager.cache[entry->RX_UE_INFORMATION_TAG] == 1) {
                crc_manager.cache_hits++;
            } else {
                crc_manager.cache_misses++;
                crc_manager.cache[entry->RX_UE_INFORMATION_TAG] = 1;
            }
        }

        // Log processing
        printf("Processing entry %zu with RNTI: %u, CRCFLAG: %d\n", i, entry->RNTI, entry->CRCFLAG);
    }

    pthread_mutex_unlock(&crc_manager.lock);

    // Print cache performance metrics
    printf("Cache Hits: %zu, Cache Misses: %zu\n", crc_manager.cache_hits, crc_manager.cache_misses);
}

void cleanup_crc_manager() {
    pthread_mutex_destroy(&crc_manager.lock);
}

int main() {
    initialize_crc_manager();

    for (uint16_t i = 0; i < 100; ++i) { // Simulate adding some entries
        add_entry(rand() % 256, rand() % 65535);
    }

    process_entries();
    cleanup_crc_manager();

    return 0;
}
```

