- **Corrupted Data Handling:** Implemented via error checks in `set_crcflag` with appropriate logging.

This code provides a foundational example of managing NFAPI_CRC_INDICATION_PDU_T structures while considering thread safety, caching, and basic logging.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef enum {
    ITEM_STATUS_AVAILABLE,
    ITEM_STATUS_UNAVAILABLE
} ItemStatus;

typedef struct Item {
    int id;
    ItemStatus status;
    char *name;
    pthread_mutex_t lock; // Lock for thread-safe operations on this item
} Item;

typedef struct Node {
    Item *item;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    pthread_rwlock_t collection_lock; // Read-write lock for the entire collection
    int size;
} ItemCollection;

// Function prototypes
ItemCollection* create_collection();
void destroy_collection(ItemCollection *collection);
int add_item(ItemCollection *collection, int id, const char *name);
int remove_item(ItemCollection *collection, int id);
Item* get_item(ItemCollection *collection, int id);

// Internal helper functions
static Node* find_node(ItemCollection *collection, int id);
static void free_item_memory(Item *item);

// Implementations

ItemCollection* create_collection() {
    ItemCollection *collection = malloc(sizeof(ItemCollection));
    if (!collection) return NULL;

    collection->head = NULL;
    pthread_rwlock_init(&collection->collection_lock, NULL);
    collection->size = 0;

    return collection;
}

void destroy_collection(ItemCollection *collection) {
    Node *current = collection->head;
    while (current != NULL) {
        Node *next = current->next;
        free_item_memory(current->item);
        pthread_mutex_destroy(&current->item->lock);
        free(current);
        current = next;
    }
    pthread_rwlock_destroy(&collection->collection_lock);
    free(collection);
}

int add_item(ItemCollection *collection, int id, const char *name) {
    if (!collection || !name) return -1;

    pthread_rwlock_wrlock(&collection->collection_lock);

    Node *current = collection->head;
    while (current != NULL) {
        pthread_mutex_lock(&current->item->lock);
        if (current->item->id == id) {
            pthread_mutex_unlock(&current->item->lock);
            pthread_rwlock_unlock(&collection->collection_lock);
            return -1; // ID already exists
        }
        pthread_mutex_unlock(&current->item->lock);

        current = current->next;
    }

    Item *new_item = malloc(sizeof(Item));
    if (!new_item) {
        pthread_rwlock_unlock(&collection->collection_lock);
        return -1;
    }

    new_item->id = id;
    new_item->status = ITEM_STATUS_AVAILABLE;
    new_item->name = strdup(name); // Copy the name
    if (!new_item->name) {
        free(new_item);
        pthread_rwlock_unlock(&collection->collection_lock);
        return -1;
    }

    pthread_mutex_init(&new_item->lock, NULL);

    Node *new_node = malloc(sizeof(Node));
    if (!new_node) {
        free_item_memory(new_item);
        pthread_rwlock_unlock(&collection->collection_lock);
        return -1;
    }

    new_node->item = new_item;
    new_node->next = collection->head;
    collection->head = new_node;

    pthread_rwlock_unlock(&collection->collection_lock);
    collection->size++;
    return 0; // Success
}

int remove_item(ItemCollection *collection, int id) {
    if (!collection) return -1;

    pthread_rwlock_wrlock(&collection->collection_lock);

    Node **current_ptr = &collection->head;
    while (*current_ptr != NULL) {
        Node *current_node = *current_ptr;
        pthread_mutex_lock(&current_node->item->lock);
        if (current_node->item->id == id) {
            *current_ptr = current_node->next; // Remove node from list
            free_item_memory(current_node->item);
            pthread_mutex_unlock(&current_node->item->lock);
            pthread_mutex_destroy(&current_node->item->lock);
            free(current_node);

            pthread_rwlock_unlock(&collection->collection_lock);
            collection->size--;
            return 0;
        }
        pthread_mutex_unlock(&current_node->item->lock);

        current_ptr = &current_node->next;
    }

    pthread_rwlock_unlock(&collection->collection_lock);
    return -1; // ID not found
}

Item* get_item(ItemCollection *collection, int id) {
    if (!collection) return NULL;

    Node *node = find_node(collection, id);
    if (node == NULL) return NULL;

    pthread_mutex_lock(&node->item->lock);
    Item *item = node->item;
    pthread_mutex_unlock(&node->item->lock);

    return item;
}

static Node* find_node(ItemCollection *collection, int id) {
    Node *current = collection->head;
    while (current != NULL) {
        pthread_mutex_lock(&current->item->lock);
        if (current->item->id == id) {
            pthread_mutex_unlock(&current->item->lock);
            return current;
        }
        pthread_mutex_unlock(&current->item->lock);

        current = current->next;
    }
    return NULL;
}

static void free_item_memory(Item *item) {
    free(item->name);
    free(item);
}
```']

