```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG; // Assuming CRCFLAG is an integer for simplicity
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Initialize list head
Node* init_list() {
    return NULL;
}

// Add new element to the list
int add_element(Node** head, int RX_UE_INFORMATION_TAG, int RNTI) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1;

    new_node->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->data.RNTI = RNTI;
    new_node->data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRCFLAG
    new_node->next = *head;
    *head = new_node;

    return 0;
}

// Remove element based on RNTI
int remove_element(Node** head, int RNTI) {
    Node *temp = *head, *prev = NULL;

    if (temp != NULL && temp->data.RNTI == RNTI) {
        *head = temp->next;
        free(temp);
        return 0;
    }

    while (temp != NULL && temp->data.RNTI != RNTI) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) return -1;

    prev->next = temp->next;
    free(temp);

    return 0;
}

// Update CRCFLAG for a given RNTI
int update_crcflag(Node* head, int RNTI, int new_flag) {
    Node* current = head;

    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            current->data.CRC_INDICATION_REL8_TAG.CRCFLAG = new_flag;
            return 0;
        }
        current = current->next;
    }

    return -1;
}

// Print all elements
void print_list(Node* head) {
    Node* current = head;

    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n",
               current->data.RX_UE_INFORMATION_TAG,
               current->data.RNTI,
               current->data.CRC_INDICATION_REL8_TAG.CRCFLAG);
        current = current->next;
    }
}

// Serialize list to file
int serialize_list(Node* head, const char* filename) {
    FILE *file = fopen(filename, "w");
    if (!file) return -1;

    Node* current = head;

    while (current != NULL) {
        fprintf(file, "%d,%d,%d\n",
                current->data.RX_UE_INFORMATION_TAG,
                current->data.RNTI,
                current->data.CRC_INDICATION_REL8_TAG.CRCFLAG);
        current = current->next;
    }

    fclose(file);
    return 0;
}

// Deserialize list from file
Node* deserialize_list(const char* filename) {
    FILE *file = fopen(filename, "r");
    if (!file) return NULL;

    Node* head = NULL;
    int RX_UE_INFORMATION_TAG, RNTI, CRCFLAG;

    while (fscanf(file, "%d,%d,%d\n", &RX_UE_INFORMATION_TAG, &RNTI, &CRCFLAG) == 3) {
        add_element(&head, RX_UE_INFORMATION_TAG, RNTI);
        head->data.CRC_INDICATION_REL8_TAG.CRCFLAG = CRCFLAG;
    }

    fclose(file);
    return head;
}

// Free list
void free_list(Node* head) {
    Node* temp;

    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}
