// Define the maximum size for each structure list (could be configurable)
#define MAX_LIST_SIZE 1000
#define DEFAULT_CRCFLAG_STATE false

typedef struct {
    uint16_t RNTI;
    // Other fields like RX_UE_INFORMATION_TAG, CRC_INDICATION_REL8_TAG...
} NFAPI_CRC_INDICATION_PDU_T;

// Dynamic list structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* entries[MAX_LIST_SIZE];
    size_t count;
    pthread_rwlock_t lock;  // For thread safety: reader-writer lock
} DynamicList;

DynamicList* dynamic_list_create() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) {
        log_error("Memory allocation failed for DynamicList");
        return NULL;
    }
    memset(list, 0, sizeof(DynamicList));
    pthread_rwlock_init(&list->lock, NULL);
    return list;
}

void dynamic_list_destroy(DynamicList* list) {
    if (list) {
        pthread_rwlock_wrlock(&list->lock);
        for (size_t i = 0; i < list->count; ++i) {
            free(list->entries[i]);
        }
        pthread_rwlock_unlock(&list->lock);

        pthread_rwlock_destroy(&list->lock);
        free(list);
    }
}

bool dynamic_list_add(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T* entry) {
    if (!list || !entry) return false;

    bool result = false;
    pthread_rwlock_wrlock(&list->lock);

    if (list->count < MAX_LIST_SIZE) {
        list->entries[list->count] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (list->entries[list->count]) {
            memcpy(list->entries[list->count], entry, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            // Randomly set CRCFLAG; ensure logging
            list->entries[list->count]->CRCFLAG = rand() % 2;
            log_info("Added new NFAPI_CRC_INDICATION_PDU_T with RNTI: %u", entry->RNTI);

            ++list->count;
            result = true;
        } else {
            log_error("Memory allocation failed for a new list entry");
        }
    }

    pthread_rwlock_unlock(&list->lock);
    return result;
}

bool dynamic_list_reset_crcflags(DynamicList* list, bool default_state) {
    if (!list) return false;

    bool success = true;
    pthread_rwlock_wrlock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        list->entries[i]->CRCFLAG = default_state;
        log_info("Reset CRCFLAG to %d for RNTI: %u", default_state, list->entries[i]->RNTI);
    }

    pthread_rwlock_unlock(&list->lock);
    return success;
}

NFAPI_CRC_INDICATION_PDU_T* dynamic_list_query(DynamicList* list, uint16_t rnti) {
    if (!list) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* result = NULL;
    pthread_rwlock_rdlock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->entries[i]->RNTI == rnti) {
            result = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (result) {
                memcpy(result, list->entries[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
                log_info("Queried NFAPI_CRC_INDICATION_PDU_T with RNTI: %u", rnti);
            }
            break;
        }
    }

    pthread_rwlock_unlock(&list->lock);
    return result;
}

void dynamic_list_archive_old_entries(DynamicList* list, time_t threshold) {
    if (!list) return;

    pthread_rwlock_wrlock(&list->lock);

    for (size_t i = 0; i < list->count;) {
        // Assuming each entry has a timestamp field
        if (time(NULL) - list->entries[i]->timestamp > threshold) {
            free(list->entries[i]);
            memmove(&list->entries[i], &list->entries[i + 1],
                    (list->count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
            --list->count;
            log_info("Archived old entry with RNTI: %u", list->entries[i]->RNTI);
        } else {
            ++i;
        }
    }

    pthread_rwlock_unlock(&list->lock);
}

