#include <unistd.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_STRUCTURES 10000
#define LOG_FILE "nfaapi_log.txt"
#define BIN_FILE "nfaapi_data.bin"

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void log_message(const char *message) {
    FILE *log_fp = fopen(LOG_FILE, "a");
    if (log_fp) {
        fprintf(log_fp, "%s\n", message);
        fclose(log_fp);
    }
}

unsigned int pseudo_random_crcflag() {
    unsigned int seed = time(NULL) ^ getpid() ^ ((unsigned long)&seed);
    srand(seed);
    return rand() % 2; // Simulating a binary flag
}

int allocate_nfaapi_list(NFAPI_CRC_INDICATION_PDU_T **list, size_t *size) {
    if (!list || !size) return -1;

    pthread_mutex_lock(&lock);

    *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(MAX_STRUCTURES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*list == NULL) {
        log_message("Memory allocation failed for NFAPI list");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    *size = MAX_STRUCTURES;

    for (int i = 0; i < MAX_STRUCTURES; ++i) {
        (*list)[i].RX_UE_INFORMATION_TAG = rand() % 100;
        (*list)[i].RNTI = rand() % 1000;
        (*list)[i].CRC_INDICATION_REL8_TAG.CRCFLAG = pseudo_random_crcflag();
    }

    log_message("NFAPI list successfully created");

    pthread_mutex_unlock(&lock);
    return 0;
}

void serialize_list(const NFAPI_CRC_INDICATION_PDU_T *list, size_t size) {
    FILE *bin_fp = fopen(BIN_FILE, "wb");
    if (bin_fp) {
        fwrite(list, sizeof(NFAPI_CRC_INDICATION_PDU_T), size, bin_fp);
        fclose(bin_fp);
    } else {
        log_message("Failed to open binary file for writing");
    }
}

int deserialize_list(NFAPI_CRC_INDICATION_PDU_T **list, size_t *size) {
    FILE *bin_fp = fopen(BIN_FILE, "rb");
    if (!bin_fp) {
        log_message("Failed to open binary file for reading");
        return -1;
    }

    fseek(bin_fp, 0, SEEK_END);
    long fsize = ftell(bin_fp);
    rewind(bin_fp);

    *size = fsize / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(fsize);

    if (*list) {
        fread(*list, 1, fsize, bin_fp);
        fclose(bin_fp);
    } else {
        log_message("Memory allocation failed during deserialization");
        fclose(bin_fp);
        return -1;
    }

    log_message("NFAPI list successfully deserialized");

    return 0;
}

void cleanup_list(NFAPI_CRC_INDICATION_PDU_T *list) {
    free(list);
}

// Mock function to simulate external persistence (e.g., database)
