#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

#define MAX_NODES 10000

typedef struct CRC_INDICATION_REL8_TAG {
    uint8_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* head;
    pthread_mutex_t lock;
    uint16_t used_rntis[MAX_NODES];
    int size;
} CRC_Indication_List;

CRC_Indication_List* create_list() {
    CRC_Indication_List* list = (CRC_Indication_List*)malloc(sizeof(CRC_Indication_List));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    for (int i = 0; i < MAX_NODES; ++i) {
        list->used_rntis[i] = 0;
    }
    list->size = 0;

    return list;
}

void destroy_list(CRC_Indication_List* list) {
    if (!list) return;

    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

uint16_t generate_unique_rnti(CRC_Indication_List* list) {
    uint16_t rnti;
    do {
        rnti = rand() % MAX_NODES;
    } while (list->used_rntis[rnti]);

    return rnti;
}

int add_node(CRC_Indication_List* list, uint32_t rx_ue_info_tag) {
    if (!list || list->size >= MAX_NODES) return -1;

    pthread_mutex_lock(&list->lock);

    uint16_t rnti = generate_unique_rnti(list);
    NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_node->RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    new_node->RNTI = rnti;
    new_node->crc_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
    new_node->next = list->head;

    list->used_rntis[rnti] = 1;
    list->head = new_node;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void print_list(CRC_Indication_List* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current) {
        printf("RX_UE_INFORMATION_TAG: %u, RNTI: %u, CRCFLAG: %u\n",
               current->RX_UE_INFORMATION_TAG,
               current->RNTI,
               current->crc_tag.CRCFLAG);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}
